-- Immutable CloudTMS TEST function snapshot, page 09.
-- Generated from pg_get_functiondef; definitions only, with function body checks deferred for forward references.
-- Do not edit an applied baseline page. Add or replace routine authority in supabase/repeatable.

\set ON_ERROR_STOP on
set check_function_bodies = off;
set search_path = pg_catalog, public, extensions;

-- pay_batch_freshness_scope_seed(uuid,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_batch_freshness_scope_seed(p_operation_id uuid, p_pay_batch_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_pay_batch_id uuid := p_pay_batch_id;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_candidate_id uuid := NULL::uuid;
  v_cursor_item_id uuid := NULL::uuid;
  v_seeded_count integer := 0;
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_candidate_id uuid := NULL::uuid;
  v_last_item_id uuid := NULL::uuid;
  v_existing_max_ordinal bigint := 0;
  v_new_unit_count integer := 0;
  v_touched_unit_count integer := 0;
  v_page_scope_hash text := NULL::text;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_new_total_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_seeded_units integer := 0;
  v_prev_scope_hash text := NULL::text;
  v_new_scope_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed operation not found: %', p_operation_id;
  END IF;

  v_pay_batch_id := COALESCE(v_pay_batch_id, v_operation.pay_batch_id);
  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed: pay_batch_id is required';
  END IF;

  IF v_operation.pay_batch_id IS NOT NULL AND v_operation.pay_batch_id <> v_pay_batch_id THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed operation % belongs to pay batch %, not %', p_operation_id, v_operation.pay_batch_id, v_pay_batch_id;
  END IF;

  PERFORM 1
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_freshness_scope_seed pay batch not found: %', v_pay_batch_id;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    IF COALESCE(p_cursor_json->>'last_candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_candidate_id := (p_cursor_json->>'last_candidate_id')::uuid;
    END IF;
    IF COALESCE(p_cursor_json->>'last_pay_batch_item_id', p_cursor_json->>'last_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_item_id := COALESCE(p_cursor_json->>'last_pay_batch_item_id', p_cursor_json->>'last_item_id')::uuid;
    END IF;
  END IF;

  SELECT COALESCE(MAX(scope_unit.unit_ordinal), 0)
  INTO v_existing_max_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_seed_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_seed_page ON COMMIT DROP AS
  WITH ordered_items AS (
    SELECT
      batch_candidate.candidate_id,
      batch_item.id AS pay_batch_item_id,
      batch_item.pay_batch_candidate_id,
      batch_item.item_type,
      batch_item.timesheet_id,
      batch_item.source_ref,
      batch_item.description,
      batch_item.amount_ex_vat,
      batch_item.amount_vat,
      batch_item.amount_inc_vat,
      batch_item.pay_channel,
      batch_item.finance_case_id,
      batch_item.finance_component_id,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.frozen_component_classification,
      batch_item.frozen_source_amount,
      batch_item.frozen_target_amount_ex_vat,
      batch_item.frozen_target_amount_vat,
      batch_item.frozen_target_amount_inc_vat,
      batch_item.payout_instruction_snapshot_json,
      batch_item.operation_source_key,
      COALESCE(batch_item.is_voided, false) AS is_voided
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_pay_batch_id
      AND COALESCE(batch_item.is_voided, false) = false
      AND (
        v_cursor_candidate_id IS NULL
        OR batch_candidate.candidate_id > v_cursor_candidate_id
        OR (batch_candidate.candidate_id = v_cursor_candidate_id AND batch_item.id > COALESCE(v_cursor_item_id, '00000000-0000-0000-0000-000000000000'::uuid))
      )
    ORDER BY batch_candidate.candidate_id, batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT
    ordered_items.*,
    row_number() OVER (ORDER BY ordered_items.candidate_id, ordered_items.pay_batch_item_id)::integer AS page_ordinal
  FROM ordered_items;

  SELECT COUNT(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row;

  v_has_more := COALESCE(v_page_count, 0) > v_limit;

  WITH seed_rows AS (
    SELECT
      page_row.*,
      (v_existing_max_ordinal + page_row.page_ordinal)::bigint AS unit_ordinal,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => page_row.pay_batch_item_id,
      p_pay_batch_id => v_pay_batch_id,
      p_timesheet_id => page_row.timesheet_id,
      p_item_type => page_row.item_type,
      p_frozen_key_type => page_row.frozen_component_key_type,
      p_frozen_key_value => page_row.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(page_row.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(page_row.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
    WHERE page_row.page_ordinal <= v_limit
  ), upserted_units AS (
    INSERT INTO public.banking_pay_operation_scope_units (
      operation_id,
      pay_batch_id,
      phase,
      unit_type,
      unit_key,
      unit_payload_json,
      unit_ordinal,
      status,
      chunk_id,
      result_hash,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_operation_id,
      v_pay_batch_id,
      'FRESHNESS',
      'PAY_BATCH_ITEM',
      'pay_batch_item:' || seed_rows.pay_batch_item_id::text,
      jsonb_build_object(
        'pay_batch_item_id', seed_rows.pay_batch_item_id::text,
        'pay_batch_candidate_id', seed_rows.pay_batch_candidate_id::text,
        'candidate_id', seed_rows.candidate_id::text,
        'timesheet_id', CASE WHEN seed_rows.timesheet_id IS NULL THEN NULL ELSE seed_rows.timesheet_id::text END,
        'item_type', seed_rows.item_type,
        'source_ref', seed_rows.source_ref,
        'description', seed_rows.description,
        'pay_channel', seed_rows.pay_channel,
        'finance_case_id', CASE WHEN seed_rows.finance_case_id IS NULL THEN NULL ELSE seed_rows.finance_case_id::text END,
        'finance_component_id', CASE WHEN seed_rows.finance_component_id IS NULL THEN NULL ELSE seed_rows.finance_component_id::text END,
        'amounts', jsonb_build_object(
          'amount_ex_vat', seed_rows.amount_ex_vat,
          'amount_vat', seed_rows.amount_vat,
          'amount_inc_vat', seed_rows.amount_inc_vat
        ),
        'economic_key', jsonb_strip_nulls(jsonb_build_object(
          'timesheet_id', CASE WHEN seed_rows.resolved_timesheet_id IS NULL THEN NULL ELSE seed_rows.resolved_timesheet_id::text END,
          'key_type', seed_rows.resolved_key_type,
          'key_value', seed_rows.resolved_key_value,
          'resolution_source', seed_rows.key_resolution_source,
          'failure_reason', seed_rows.key_resolution_failure_reason
        )),
        'frozen', jsonb_strip_nulls(jsonb_build_object(
          'frozen_component_key_type', seed_rows.frozen_component_key_type,
          'frozen_component_key_value', seed_rows.frozen_component_key_value,
          'frozen_component_snapshot_json', seed_rows.frozen_component_snapshot_json,
          'frozen_source_basis_json', seed_rows.frozen_source_basis_json,
          'frozen_component_classification', CASE WHEN seed_rows.frozen_component_classification IS NULL THEN NULL ELSE seed_rows.frozen_component_classification::text END,
          'frozen_source_amount', seed_rows.frozen_source_amount,
          'frozen_target_amount_ex_vat', seed_rows.frozen_target_amount_ex_vat,
          'frozen_target_amount_vat', seed_rows.frozen_target_amount_vat,
          'frozen_target_amount_inc_vat', seed_rows.frozen_target_amount_inc_vat
        )),
        'payout_instruction_snapshot_json', seed_rows.payout_instruction_snapshot_json,
        'operation_source_key', seed_rows.operation_source_key,
        'is_voided', seed_rows.is_voided
      ),
      seed_rows.unit_ordinal,
      'PENDING',
      NULL::uuid,
      NULL::text,
      NULL::jsonb,
      v_now,
      v_now
    FROM seed_rows
    ON CONFLICT (operation_id, phase, unit_type, unit_key)
    DO UPDATE
    SET unit_payload_json = EXCLUDED.unit_payload_json,
        unit_ordinal = LEAST(public.banking_pay_operation_scope_units.unit_ordinal, EXCLUDED.unit_ordinal),
        status = CASE
          WHEN public.banking_pay_operation_scope_units.status IN ('FRESH', 'STALE', 'ERROR') THEN public.banking_pay_operation_scope_units.status
          ELSE 'PENDING'
        END,
        error_json = CASE
          WHEN public.banking_pay_operation_scope_units.status IN ('FRESH', 'STALE') THEN public.banking_pay_operation_scope_units.error_json
          ELSE NULL::jsonb
        END,
        updated_at_utc = v_now
    RETURNING
      (xmax = '0'::xid) AS inserted_row,
      unit_key,
      unit_ordinal
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE upserted_units.inserted_row)::integer,
    md5(COALESCE(string_agg(upserted_units.unit_key, '|' ORDER BY upserted_units.unit_ordinal, upserted_units.unit_key) FILTER (WHERE upserted_units.inserted_row), 'NO_NEW_SCOPE_UNITS'))
  INTO
    v_touched_unit_count,
    v_new_unit_count,
    v_page_scope_hash
  FROM upserted_units;

  v_seeded_count := COALESCE(v_new_unit_count, 0);

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_candidate_id', page_row.candidate_id::text,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_seed_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );

  v_new_seeded_units := COALESCE(v_prev_seeded_units, 0) + COALESCE(v_new_unit_count, 0);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0) + COALESCE(v_new_unit_count, 0), v_new_seeded_units);
  v_new_pending_units := COALESCE(v_prev_pending_units, 0) + COALESCE(v_new_unit_count, 0);
  v_new_scope_hash := CASE
    WHEN COALESCE(v_new_unit_count, 0) <= 0 THEN v_prev_scope_hash
    WHEN v_prev_scope_hash IS NULL THEN v_page_scope_hash
    ELSE md5(v_prev_scope_hash || '|seed|' || COALESCE(v_page_scope_hash, 'NO_NEW_SCOPE_UNITS'))
  END;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', 'PENDING',
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0),
    'stale_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0),
    'scope_hash', v_new_scope_hash,
    'result_hash', NULL::text,
    'stale_reasons', COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb),
    'diff_samples', COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb),
    'last_seeded_at_utc', v_now::text,
    'last_seeded_count', COALESCE(v_seeded_count, 0),
    'last_touched_count', COALESCE(v_touched_unit_count, 0),
    'seed_has_more', COALESCE(v_has_more, false),
    'seed_next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', 'PENDING',
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_stale_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0),
          'freshness_error_units', COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0),
          'freshness_scope_hash', v_new_scope_hash,
          'freshness_result_hash', NULL::text
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  UPDATE public.pay_batches AS batch_update
  SET freshness_operation_id = p_operation_id,
      freshness_validation_status = 'PENDING',
      freshness_scope_hash = COALESCE(v_new_scope_hash, batch_update.freshness_scope_hash),
      freshness_result_hash = NULL::text,
      freshness_result_json = jsonb_build_object(
        'ok', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_pay_batch_id::text,
        'phase', 'FRESHNESS',
        'status', 'PENDING',
        'is_stale', false,
        'summary', v_new_summary
      )
  WHERE batch_update.id = v_pay_batch_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_count', COALESCE(v_seeded_count, 0),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$;

-- pay_batch_freshness_user_failures_v1(uuid,uuid,uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_batch_freshness_user_failures_v1(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
 SET statement_timeout TO '2000ms'
AS $function$
DECLARE
  v_operation public.banking_pay_operations%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_actor_is_valid boolean := true;
  v_failure_count integer := 0;
  v_failures jsonb := '[]'::jsonb;
BEGIN
  IF p_operation_id IS NULL OR p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_USER_FAILURES_IDENTIFIERS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_USER_FAILURES_IDENTIFIERS_REQUIRED'
            )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id;

  IF NOT FOUND OR v_operation.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_USER_FAILURES_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = pg_catalog.jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_USER_FAILURES_OPERATION_BATCH_MISMATCH',
              'operation_id', p_operation_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_USER_FAILURES_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = pg_catalog.jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_USER_FAILURES_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id
              )::text;
    END IF;
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_failure_count
  FROM public.banking_pay_operation_scope_units AS failed_unit
  WHERE failed_unit.operation_id = p_operation_id
    AND failed_unit.pay_batch_id = p_pay_batch_id
    AND failed_unit.phase = 'FRESHNESS'
    AND failed_unit.unit_type = 'PAY_BATCH_ITEM'
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(failed_unit.status, ''))) IN ('STALE', 'ERROR');

  WITH failed_units AS (
    SELECT
      failed_unit.id,
      failed_unit.unit_ordinal,
      failed_unit.status,
      failed_unit.unit_payload_json,
      failed_unit.error_json,
      CASE
        WHEN COALESCE(failed_unit.unit_payload_json->>'pay_batch_candidate_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (failed_unit.unit_payload_json->>'pay_batch_candidate_id')::uuid
        ELSE NULL::uuid
      END AS pay_batch_candidate_id,
      CASE
        WHEN COALESCE(failed_unit.unit_payload_json->>'pay_batch_item_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (failed_unit.unit_payload_json->>'pay_batch_item_id')::uuid
        ELSE NULL::uuid
      END AS pay_batch_item_id,
      CASE
        WHEN COALESCE(failed_unit.unit_payload_json->>'timesheet_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (failed_unit.unit_payload_json->>'timesheet_id')::uuid
        WHEN COALESCE(failed_unit.unit_payload_json #>> '{validation_result,diff,stored_key,timesheet_id}', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (failed_unit.unit_payload_json #>> '{validation_result,diff,stored_key,timesheet_id}')::uuid
        ELSE NULL::uuid
      END AS timesheet_id
    FROM public.banking_pay_operation_scope_units AS failed_unit
    WHERE failed_unit.operation_id = p_operation_id
      AND failed_unit.pay_batch_id = p_pay_batch_id
      AND failed_unit.phase = 'FRESHNESS'
      AND failed_unit.unit_type = 'PAY_BATCH_ITEM'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(failed_unit.status, ''))) IN ('STALE', 'ERROR')
    ORDER BY failed_unit.unit_ordinal, failed_unit.id
    LIMIT v_limit
  ), failure_rows AS (
    SELECT
      failed_unit.unit_ordinal,
      failed_unit.id,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'status', pg_catalog.upper(pg_catalog.btrim(COALESCE(failed_unit.status, ''))),
        'candidate_id', failed_unit.unit_payload_json->>'candidate_id',
        'candidate_tms_ref', batch_candidate.candidate_tms_ref,
        'candidate_display_name', batch_candidate.candidate_display_name,
        'client_name', timesheet_display.client_name,
        'week_ending_date', timesheet_display.week_ending_date,
        'payment_amount', payment_display.payment_amount,
        'payment_amount_pence', pg_catalog.round(payment_display.payment_amount * 100)::bigint,
        'currency', 'GBP',
        'pay_batch_candidate_id', failed_unit.unit_payload_json->>'pay_batch_candidate_id',
        'pay_batch_item_id', failed_unit.unit_payload_json->>'pay_batch_item_id',
        'timesheet_id', failed_unit.unit_payload_json->>'timesheet_id',
        'item_type', failed_unit.unit_payload_json->>'item_type',
        'description', failed_unit.unit_payload_json->>'description',
        'source_ref', failed_unit.unit_payload_json->>'source_ref',
        'pay_channel', failed_unit.unit_payload_json->>'pay_channel',
        'reason_codes', COALESCE(reason_values.reason_codes, '[]'::jsonb),
        'diff', CASE
          WHEN pg_catalog.jsonb_typeof(failed_unit.unit_payload_json #> '{validation_result,diff}') = 'object'
            THEN failed_unit.unit_payload_json #> '{validation_result,diff}'
          ELSE NULL::jsonb
        END
      )) AS failure_json
    FROM failed_units AS failed_unit
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = failed_unit.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = p_pay_batch_id
    LEFT JOIN public.pay_batch_items AS frozen_batch_item
      ON frozen_batch_item.id = failed_unit.pay_batch_item_id
     AND frozen_batch_item.pay_batch_candidate_id = batch_candidate.id
    LEFT JOIN LATERAL (
      SELECT
        COALESCE(
          NULLIF(pg_catalog.btrim(COALESCE(frozen_timesheet.target_snapshot_json->>'client_name', '')), ''),
          NULLIF(pg_catalog.btrim(COALESCE(current_client.name, '')), '')
        ) AS client_name,
        COALESCE(
          NULLIF(pg_catalog.btrim(COALESCE(frozen_timesheet.target_snapshot_json->>'week_ending_date', '')), ''),
          CASE
            WHEN current_timesheet.week_ending_date IS NOT NULL
              THEN pg_catalog.to_char(current_timesheet.week_ending_date, 'YYYY-MM-DD')
            ELSE NULL::text
          END
        ) AS week_ending_date
      FROM (SELECT 1 AS display_seed) AS display_seed
      LEFT JOIN LATERAL (
        SELECT timesheet_snapshot.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS timesheet_snapshot
        WHERE timesheet_snapshot.pay_batch_id = p_pay_batch_id
          AND timesheet_snapshot.timesheet_id = COALESCE(failed_unit.timesheet_id, frozen_batch_item.timesheet_id)
        ORDER BY timesheet_snapshot.created_at_utc DESC, timesheet_snapshot.id DESC
        LIMIT 1
      ) AS frozen_timesheet ON true
      LEFT JOIN public.timesheets AS current_timesheet
        ON current_timesheet.timesheet_id = COALESCE(failed_unit.timesheet_id, frozen_batch_item.timesheet_id)
      LEFT JOIN public.contracts AS current_contract
        ON current_contract.id = current_timesheet.contract_id
      LEFT JOIN public.clients AS current_client
        ON current_client.id = current_contract.client_id
      LIMIT 1
    ) AS timesheet_display ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(
        (
          SELECT member_row.active_amount
          FROM public.pay_payment_correction_request_candidates AS member_row
          JOIN public.pay_payment_correction_requests AS member_request
            ON member_request.id = member_row.correction_request_id
          WHERE member_request.pay_batch_id = p_pay_batch_id
            AND member_row.pay_batch_candidate_id = batch_candidate.id
          ORDER BY
            CASE WHEN member_request.status IN ('APPLIED', 'APPLIED_WITH_BLOCKERS') THEN 0 ELSE 1 END,
            member_request.updated_at_utc DESC,
            member_request.id DESC
          LIMIT 1
        ),
        CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS active_paye_item
            WHERE active_paye_item.pay_batch_candidate_id = batch_candidate.id
              AND COALESCE(active_paye_item.is_voided, false) IS NOT TRUE
              AND pg_catalog.upper(pg_catalog.btrim(COALESCE(active_paye_item.pay_channel, ''))) = 'PAYE'
          ) THEN
            COALESCE((
              SELECT paye_input.net_amount
              FROM public.pay_batch_paye_net_inputs AS paye_input
              WHERE paye_input.pay_batch_candidate_id = batch_candidate.id
              ORDER BY paye_input.imported_at_utc DESC, paye_input.id DESC
              LIMIT 1
            ), 0)
            + COALESCE((
              SELECT pg_catalog.sum(active_umbrella_item.amount_inc_vat)
              FROM public.pay_batch_items AS active_umbrella_item
              WHERE active_umbrella_item.pay_batch_candidate_id = batch_candidate.id
                AND COALESCE(active_umbrella_item.is_voided, false) IS NOT TRUE
                AND pg_catalog.upper(pg_catalog.btrim(COALESCE(active_umbrella_item.pay_channel, ''))) = 'UMBRELLA'
            ), 0)
          ELSE batch_candidate.net_bank_amount
        END,
        0
      )::numeric(14,2) AS payment_amount
    ) AS payment_display ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(pg_catalog.jsonb_agg(
        reason_set.reason_code ORDER BY reason_set.reason_code
      ), '[]'::jsonb) AS reason_codes
      FROM (
        SELECT DISTINCT NULLIF(pg_catalog.btrim(reason_text.reason_code), '') AS reason_code
        FROM (
          SELECT stale_reason.value AS reason_code
          FROM pg_catalog.jsonb_array_elements_text(
            CASE
              WHEN pg_catalog.jsonb_typeof(failed_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
                THEN failed_unit.unit_payload_json #> '{validation_result,stale_reasons}'
              ELSE '[]'::jsonb
            END
          ) AS stale_reason(value)

          UNION ALL
          SELECT failed_unit.error_json->>'code'
          UNION ALL
          SELECT failed_unit.error_json->>'reason'
        ) AS reason_text(reason_code)
        WHERE NULLIF(pg_catalog.btrim(reason_text.reason_code), '') IS NOT NULL
      ) AS reason_set
    ) AS reason_values ON true
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(
    failure_rows.failure_json ORDER BY failure_rows.unit_ordinal, failure_rows.id
  ), '[]'::jsonb)
  INTO v_failures
  FROM failure_rows;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'contract_version', 'PAY_BATCH_FRESHNESS_USER_FAILURES_V1',
    'operation_id', p_operation_id,
    'pay_batch_id', p_pay_batch_id,
    'failure_count', COALESCE(v_failure_count, 0),
    'returned_count', pg_catalog.jsonb_array_length(COALESCE(v_failures, '[]'::jsonb)),
    'truncated', COALESCE(v_failure_count, 0) > v_limit,
    'all_failures_listed', COALESCE(v_failure_count, 0) <= v_limit,
    'failures', COALESCE(v_failures, '[]'::jsonb),
    'instruction_code', 'REMOVE_OR_RESOLVE_STALE_PAYMENTS_THEN_REAUTHORISE',
    'instruction', 'Remove or resolve every payment listed, then reauthorise the remaining batch. If these are the only freshness failures, reauthorisation can proceed.',
    'decision_authority', 'EXISTING_FRESHNESS_SCOPE_UNIT_RESULTS',
    'policy_x_economics_changed', false
  );
END;
$function$;

-- pay_batch_get_section_page(uuid,text,jsonb,integer,uuid,jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION public.pay_batch_get_section_page(p_pay_batch_id uuid, p_section text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100, p_actor_user_id uuid DEFAULT NULL::uuid, p_filters_json jsonb DEFAULT '{}'::jsonb, p_sort_json jsonb DEFAULT '{}'::jsonb, p_purpose text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.pay_batches%ROWTYPE;
  v_section text := LOWER(REPLACE(NULLIF(BTRIM(COALESCE(p_section, '')), ''), '-', '_'));
  v_purpose text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_purpose, '')), ''), '-', '_'));
  v_limit integer := COALESCE(p_limit, 100);
  v_cursor_id uuid := NULL::uuid;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := NULL::jsonb;
  v_returned_count integer := 0;
  v_raw_count integer := 0;
  v_last_cursor_text text := NULL::text;
  v_known_total_count integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_server_time_utc timestamptz := now();
  v_live_signal_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_overview_version bigint := 0;
  v_last_status_hash text := NULL::text;
  v_last_alert_hash text := NULL::text;
  v_known_live_signal_version bigint := NULL::bigint;
  v_changed_since_version boolean := false;
  v_section_page_signature text := NULL::text;
  v_freshness_summary jsonb := '{}'::jsonb;
  v_candidate_scope_type text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id_text text := NULL::text;
  v_candidate_scope_candidate_id_text text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id uuid := NULL::uuid;
  v_candidate_scope_candidate_id uuid := NULL::uuid;
  v_candidate_scope_actual_pay_batch_id uuid := NULL::uuid;
  v_candidate_scope_actual_candidate_id uuid := NULL::uuid;
  v_candidate_scope_enabled boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply(
    CASE
      WHEN v_purpose = 'OVERVIEW' OR v_section IN ('overview', 'overview_items') THEN 'OVERVIEW_PAGE'
      ELSE 'EXPLICIT_DIAGNOSTIC'
    END
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_section IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED')::text;
  END IF;

  IF v_section = 'overview' THEN
    v_section := 'overview_items';
  END IF;

  IF v_section = 'overview_items' THEN
    v_purpose := 'OVERVIEW';
  END IF;

  IF v_purpose IS NULL THEN
    v_purpose := 'SECTION_PAGE';
  END IF;

  IF v_purpose NOT IN (
    'SECTION_PAGE',
    'OVERVIEW',
    'DETAIL',
    'PAYE_WORKSHEET',
    'CURRENT_PAYMENT_STATUS',
    'PAYMENT_ISSUES',
    'REMITTANCE'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE',
              'purpose', v_purpose,
              'allowed_purposes', jsonb_build_array(
                'SECTION_PAGE',
                'OVERVIEW',
                'DETAIL',
                'PAYE_WORKSHEET',
                'CURRENT_PAYMENT_STATUS',
                'PAYMENT_ISSUES',
                'REMITTANCE'
              )
            )::text;
  END IF;

  IF v_purpose = 'OVERVIEW' AND v_section <> 'overview_items' THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED',
              'purpose', v_purpose,
              'section', v_section,
              'message', 'Overview purpose may only load overview_items.'
            )::text;
  END IF;

  IF v_section NOT IN (
    'overview_items',
    'candidates',
    'items',
    'item_breakdowns',
    'transfers',
    'current_payment_status',
    'finance_case_groups',
    'remittances',
    'communications',
    'auth_history',
    'events'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION',
              'section', v_section
            )::text;
  END IF;

  v_limit := GREATEST(1, LEAST(v_limit, CASE WHEN v_section = 'overview_items' OR v_purpose = 'OVERVIEW' THEN 100 ELSE 250 END));

  IF p_cursor_json IS NOT NULL
     AND jsonb_typeof(p_cursor_json) = 'object'
     AND NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_cursor_id := COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id')::uuid;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_filters_json IS NOT NULL AND jsonb_typeof(p_filters_json) = 'object' THEN
    BEGIN
      v_known_live_signal_version := NULLIF(BTRIM(COALESCE(
        p_filters_json ->> 'known_live_signal_version',
        p_filters_json ->> 'known_version',
        p_filters_json ->> 'live_signal_version',
        p_filters_json #>> '{live_signal,version}',
        ''
      )), '')::bigint;
    EXCEPTION WHEN OTHERS THEN
      v_known_live_signal_version := NULL::bigint;
    END;

    v_candidate_scope_type := NULLIF(
      UPPER(REGEXP_REPLACE(BTRIM(COALESCE(
        p_filters_json ->> 'scope_type',
        p_filters_json ->> 'scopeType',
        ''
      )), '[[:space:]-]+', '_', 'g')),
      ''
    );
    v_candidate_scope_pay_batch_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'pay_batch_candidate_id',
      p_filters_json ->> 'payBatchCandidateId',
      ''
    )), '');
    v_candidate_scope_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'candidate_id',
      p_filters_json ->> 'candidateId',
      ''
    )), '');
  END IF;

  IF v_candidate_scope_type = 'PAY_BATCH_CANDIDATE' THEN
    IF v_section <> 'items' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED',
                'section', v_section,
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text IS NULL
       OR v_candidate_scope_candidate_id_text IS NULL THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED',
                'scope_type', v_candidate_scope_type,
                'requires', jsonb_build_array('pay_batch_candidate_id', 'candidate_id')
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_candidate_scope_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_pay_batch_candidate_id := v_candidate_scope_pay_batch_candidate_id_text::uuid;
    v_candidate_scope_candidate_id := v_candidate_scope_candidate_id_text::uuid;

    SELECT
      candidate_scope.pay_batch_id,
      candidate_scope.candidate_id
    INTO
      v_candidate_scope_actual_pay_batch_id,
      v_candidate_scope_actual_candidate_id
    FROM public.pay_batch_candidates AS candidate_scope
    WHERE candidate_scope.id = v_candidate_scope_pay_batch_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_actual_pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH',
                'scope_type', v_candidate_scope_type,
                'pay_batch_id', p_pay_batch_id::text
              )::text;
    END IF;

    IF v_candidate_scope_actual_candidate_id IS DISTINCT FROM v_candidate_scope_candidate_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_enabled := true;
  ELSIF v_section = 'items'
        AND (v_candidate_scope_pay_batch_candidate_id_text IS NOT NULL OR v_candidate_scope_candidate_id_text IS NOT NULL) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED',
              'required_scope_type', 'PAY_BATCH_CANDIDATE'
            )::text;
  END IF;

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash
  INTO
    v_live_signal_version,
    v_payment_status_version,
    v_correction_progress_version,
    v_alert_version,
    v_overview_version,
    v_last_status_hash,
    v_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_live_signal_version := 0;
    v_payment_status_version := 0;
    v_correction_progress_version := 0;
    v_alert_version := 0;
    v_overview_version := 0;
    v_last_status_hash := NULL::text;
    v_last_alert_hash := NULL::text;
  END IF;

  v_changed_since_version := (
    v_known_live_signal_version IS NOT NULL
    AND COALESCE(v_live_signal_version, 0) > v_known_live_signal_version
  );

  v_freshness_summary := jsonb_strip_nulls(jsonb_build_object(
    'freshness_validation_status', v_batch.freshness_validation_status,
    'freshness_checked_at_utc', CASE WHEN v_batch.freshness_checked_at_utc IS NULL THEN NULL::text ELSE v_batch.freshness_checked_at_utc::text END,
    'freshness_result_hash', v_batch.freshness_result_hash,
    'freshness_scope_hash', v_batch.freshness_scope_hash
  ));

  IF v_section = 'overview_items' THEN
    WITH raw_item_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.pay_bank_transfer_id,
        NULLIF(BTRIM(COALESCE(
          pay_bank_transfer_page.payee_name,
          pay_batch_item_page.payout_instruction_snapshot_json->>'payee_name',
          pay_batch_item_page.payout_instruction_snapshot_json->>'account_holder_name',
          pay_batch_candidate_page.candidate_display_name
        )), '') AS payee_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
          pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
          timesheet_snapshot_page.target_snapshot_json->>'week_ending_date',
          pay_batch_item_page.payout_instruction_snapshot_json->>'week_ending_bucket'
        )), '') AS week_ending_date,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
          pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
          pay_batch_item_page.frozen_resolution_result_json->>'client_name',
          timesheet_snapshot_page.target_snapshot_json->>'client_name'
        )), '') AS client_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'role',
          pay_batch_item_page.frozen_source_basis_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json->>'role',
          pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
          pay_batch_item_page.frozen_resolution_payload_json->>'role',
          pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
          timesheet_snapshot_page.target_snapshot_json->>'role',
          timesheet_snapshot_page.target_snapshot_json->>'job_title'
        )), '') AS role,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'date',
          CASE
            WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
             AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
            THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
            ELSE NULL::text
          END
        )), '') AS worked_date,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
          THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
          ELSE NULL::text
        END AS additional_code
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.pay_batch_candidate_id = pay_batch_candidate_page.id
      LEFT JOIN public.pay_bank_transfers AS pay_bank_transfer_page
        ON pay_bank_transfer_page.id = pay_batch_item_page.pay_bank_transfer_id
      LEFT JOIN LATERAL (
        SELECT snapshot_page_inner.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_page_inner
        WHERE snapshot_page_inner.pay_batch_id = pay_batch_candidate_page.pay_batch_id
          AND snapshot_page_inner.timesheet_id = pay_batch_item_page.timesheet_id
          AND snapshot_page_inner.candidate_id = pay_batch_candidate_page.candidate_id
          AND (
            snapshot_page_inner.pay_channel IS NOT DISTINCT FROM pay_batch_item_page.pay_channel
            OR snapshot_page_inner.pay_channel IS NULL
            OR pay_batch_item_page.pay_channel IS NULL
          )
        ORDER BY snapshot_page_inner.created_at_utc DESC, snapshot_page_inner.id DESC
        LIMIT 1
      ) AS timesheet_snapshot_page ON true
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
    ),
    raw_item_rows_with_grouping AS (
      SELECT
        raw_item_rows.*,
        raw_item_rows.item_type AS source_item_type,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN 'TIMESHEET_PAYMENT'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'EXPENSE'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'MILEAGE'
          ELSE 'ITEM'
        END AS overview_group_kind,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN CONCAT_WS('|', 'TIMESHEET_PAYMENT', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'EXPENSE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'MILEAGE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          ELSE CONCAT_WS('|', 'ITEM', raw_item_rows.id::text)
        END AS overview_group_key
      FROM raw_item_rows
    ),
    grouped_rows AS (
      SELECT
        (ARRAY_AGG(group_source.id ORDER BY group_source.id ASC))[1] AS id,
        (ARRAY_AGG(group_source.pay_batch_candidate_id ORDER BY group_source.id ASC))[1] AS pay_batch_candidate_id,
        (ARRAY_AGG(group_source.candidate_id ORDER BY group_source.id ASC))[1] AS candidate_id,
        (ARRAY_AGG(group_source.candidate_tms_ref ORDER BY group_source.id ASC))[1] AS candidate_tms_ref,
        (ARRAY_AGG(group_source.candidate_display_name ORDER BY group_source.id ASC))[1] AS candidate_display_name,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'EXPENSE'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'MILEAGE'
          ELSE (ARRAY_AGG(group_source.item_type ORDER BY group_source.id ASC))[1]
        END AS item_type,
        (ARRAY_AGG(group_source.source_item_type ORDER BY group_source.id ASC))[1] AS source_item_type,
        (ARRAY_AGG(group_source.timesheet_id ORDER BY group_source.id ASC))[1] AS timesheet_id,
        (ARRAY_AGG(group_source.pay_channel ORDER BY group_source.id ASC))[1] AS pay_channel,
        (ARRAY_AGG(group_source.source_ref ORDER BY group_source.id ASC) FILTER (WHERE group_source.source_ref IS NOT NULL))[1] AS source_ref,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'Expense'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'Mileage'
          ELSE (ARRAY_AGG(group_source.description ORDER BY group_source.id ASC))[1]
        END AS description,
        ROUND(SUM(COALESCE(group_source.amount_ex_vat, 0)), 2)::numeric(12,2) AS amount_ex_vat,
        ROUND(SUM(COALESCE(group_source.amount_vat, 0)), 2)::numeric(12,2) AS amount_vat,
        ROUND(SUM(COALESCE(group_source.amount_inc_vat, 0)), 2)::numeric(12,2) AS amount_inc_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_ex_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_ex_vat, group_source.amount_ex_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_ex_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_vat, group_source.amount_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_inc_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_inc_vat, group_source.amount_inc_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_inc_vat,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_type ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_type,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_value ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_value,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_classification::text ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_classification,
        (ARRAY_AGG(group_source.frozen_source_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_source_pay_method IS NOT NULL))[1] AS frozen_source_pay_method,
        (ARRAY_AGG(group_source.frozen_target_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_target_pay_method IS NOT NULL))[1] AS frozen_target_pay_method,
        (ARRAY_AGG(group_source.pay_bank_transfer_id ORDER BY group_source.id ASC) FILTER (WHERE group_source.pay_bank_transfer_id IS NOT NULL))[1] AS pay_bank_transfer_id,
        (ARRAY_AGG(group_source.payee_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.payee_name IS NOT NULL))[1] AS payee_name,
        (ARRAY_AGG(group_source.week_ending_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.week_ending_date IS NOT NULL))[1] AS week_ending_date,
        (ARRAY_AGG(group_source.client_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.client_name IS NOT NULL))[1] AS client_name,
        (ARRAY_AGG(group_source.role ORDER BY group_source.id ASC) FILTER (WHERE group_source.role IS NOT NULL))[1] AS role,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.worked_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.worked_date IS NOT NULL))[1]
          ELSE NULL::text
        END AS worked_date,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.additional_code ORDER BY group_source.id ASC) FILTER (WHERE group_source.additional_code IS NOT NULL))[1]
          ELSE NULL::text
        END AS additional_code,
        group_source.overview_group_kind,
        (COUNT(*) > 1)::boolean AS overview_grouped,
        COUNT(*)::integer AS overview_grouped_item_count,
        TO_JSONB(ARRAY_AGG(group_source.id::text ORDER BY group_source.id ASC)) AS pay_batch_item_ids,
        COALESCE(
          jsonb_agg(
            jsonb_strip_nulls(jsonb_build_object(
              'pay_batch_item_id', group_source.id::text,
              'key_type', group_source.frozen_component_key_type,
              'key_value', group_source.frozen_component_key_value
            ))
            ORDER BY group_source.id ASC
          ) FILTER (
            WHERE group_source.frozen_component_key_type IS NOT NULL
               OR group_source.frozen_component_key_value IS NOT NULL
          ),
          '[]'::jsonb
        ) AS grouped_frozen_economic_keys
      FROM raw_item_rows_with_grouping AS group_source
      GROUP BY
        group_source.overview_group_key,
        group_source.overview_group_kind
    ),
    page_rows AS (
      SELECT grouped_rows.*
      FROM grouped_rows
      WHERE v_cursor_id IS NULL OR grouped_rows.id > v_cursor_id
      ORDER BY grouped_rows.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'id', page_rows.id::text,
              'pay_batch_item_id', page_rows.id::text,
              'pay_batch_item_ids', COALESCE(page_rows.pay_batch_item_ids, '[]'::jsonb),
              'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
              'candidate_id', page_rows.candidate_id::text,
              'candidate_tms_ref', page_rows.candidate_tms_ref,
              'candidate_display_name', page_rows.candidate_display_name,
              'candidate_name', page_rows.candidate_display_name,
              'payee_name', COALESCE(page_rows.payee_name, page_rows.candidate_display_name),
              'item_type', page_rows.item_type,
              'source_item_type', page_rows.source_item_type,
              'overview_group_kind', page_rows.overview_group_kind,
              'overview_grouped', page_rows.overview_grouped,
              'overview_grouped_item_count', page_rows.overview_grouped_item_count,
              'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
              'pay_channel', page_rows.pay_channel,
              'source_ref', page_rows.source_ref,
              'source_reference', page_rows.source_ref,
              'description', page_rows.description
            )
            || jsonb_build_object(
              'amount_ex_vat', page_rows.amount_ex_vat,
              'amount_vat', page_rows.amount_vat,
              'amount_inc_vat', page_rows.amount_inc_vat,
              'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
              'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
              'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat,
              'frozen_economic_key_type', page_rows.frozen_component_key_type,
              'frozen_economic_key_value', page_rows.frozen_component_key_value,
              'grouped_frozen_economic_keys', COALESCE(page_rows.grouped_frozen_economic_keys, '[]'::jsonb),
              'frozen_component_classification', page_rows.frozen_component_classification,
              'frozen_source_pay_method', page_rows.frozen_source_pay_method,
              'frozen_target_pay_method', page_rows.frozen_target_pay_method,
              'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'additional_code', page_rows.additional_code,
              'draft_not_submitted', COALESCE(UPPER(BTRIM(COALESCE(v_batch.status, ''))) IN ('DRAFT', 'DRAFT_CREATED'), false)
                AND COALESCE(UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) IN ('', 'NOT_SUBMITTED', 'NONE'), true)
            )
            || jsonb_build_object(
              'frozen_component_key_type', page_rows.frozen_component_key_type,
              'frozen_component_key_value', page_rows.frozen_component_key_value,
              'line_kind', page_rows.item_type,
              'unit_name', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'unit_label', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'display_context_json', jsonb_strip_nulls(jsonb_build_object(
                'week_ending_date', page_rows.week_ending_date,
                'client_name', page_rows.client_name,
                'role', page_rows.role,
                'worked_date', page_rows.worked_date,
                'additional_code', page_rows.additional_code,
                'overview_group_kind', page_rows.overview_group_kind,
                'overview_grouped_item_count', page_rows.overview_grouped_item_count
              ))
            )
          )
          ORDER BY page_rows.id ASC
        ),
        '[]'::jsonb
      ),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO
      v_items,
      v_raw_count,
      v_last_cursor_text
    FROM page_rows;

ELSIF v_section = 'candidates' THEN
    WITH page_rows AS (
      SELECT
        pay_batch_candidate_page.*,
        latest_paye_net_input.id AS latest_paye_net_input_id,
        latest_paye_net_input.source AS paye_net_source,
        latest_paye_net_input.net_amount AS paye_net_amount,
        latest_paye_net_input.imported_at_utc AS paye_net_imported_at_utc,
        latest_paye_net_input.file_name AS paye_net_file_name,
        latest_paye_net_input.file_hash AS paye_net_file_hash,
        ROW_NUMBER() OVER (ORDER BY pay_batch_candidate_page.id ASC) AS row_ordinal
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      LEFT JOIN LATERAL (
        SELECT
          paye_net_input_page.id,
          paye_net_input_page.source,
          paye_net_input_page.net_amount,
          paye_net_input_page.imported_at_utc,
          paye_net_input_page.file_name,
          paye_net_input_page.file_hash
        FROM public.pay_batch_paye_net_inputs AS paye_net_input_page
        WHERE paye_net_input_page.pay_batch_candidate_id = pay_batch_candidate_page.id
        ORDER BY paye_net_input_page.imported_at_utc DESC, paye_net_input_page.id DESC
        LIMIT 1
      ) AS latest_paye_net_input ON true
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_candidate_page.id > v_cursor_id)
      ORDER BY pay_batch_candidate_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'paye_state', page_rows.paye_state,
            'mismatch_settlement_choice', page_rows.mismatch_settlement_choice,
            'gross_preview', page_rows.gross_preview,
            'net_bank_amount', page_rows.net_bank_amount,
            'debt_created', page_rows.debt_created,
            'loan_repayment_taken', page_rows.loan_repayment_taken,
            'overpayment_recovery_taken', page_rows.overpayment_recovery_taken,
            'awaiting_net_amount', page_rows.awaiting_net_amount,
            'settlement_status', page_rows.settlement_status,
            'settled_at_utc', page_rows.settled_at_utc,
            'settled_via', page_rows.settled_via,
            'remittance_trigger_status', page_rows.remittance_trigger_status,
            'remittance_sent_at_utc', page_rows.remittance_sent_at_utc,
            'last_remittance_error', page_rows.last_remittance_error,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'paye_net_amount', page_rows.paye_net_amount,
            'paye_net_source', page_rows.paye_net_source,
            'paye_net_imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
            'latest_paye_net_input', CASE
              WHEN page_rows.latest_paye_net_input_id IS NULL THEN NULL::jsonb
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'id', page_rows.latest_paye_net_input_id::text,
                'pay_batch_candidate_id', page_rows.id::text,
                'candidate_id', page_rows.candidate_id::text,
                'source', page_rows.paye_net_source,
                'net_amount', page_rows.paye_net_amount,
                'imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
                'file_name', page_rows.paye_net_file_name,
                'file_hash', page_rows.paye_net_file_hash
              ))
            END
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'items' THEN
    WITH candidate_scoped_item_ids AS MATERIALIZED (
      SELECT pay_batch_item_scope.id
      FROM public.pay_batch_items AS pay_batch_item_scope
      JOIN public.pay_batch_candidates AS pay_batch_candidate_scope
        ON pay_batch_candidate_scope.id = pay_batch_item_scope.pay_batch_candidate_id
      WHERE pay_batch_candidate_scope.pay_batch_id = p_pay_batch_id
        AND (
          v_candidate_scope_enabled IS NOT TRUE
          OR (
            pay_batch_candidate_scope.id = v_candidate_scope_pay_batch_candidate_id
            AND pay_batch_candidate_scope.candidate_id = v_candidate_scope_candidate_id
          )
        )
        AND (v_cursor_id IS NULL OR pay_batch_item_scope.id > v_cursor_id)
      ORDER BY pay_batch_item_scope.id ASC
      LIMIT (v_limit + 1)
    ), page_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_candidate_page.paye_state AS candidate_paye_state,
        pay_batch_candidate_page.gross_preview AS candidate_gross_preview,
        pay_batch_candidate_page.net_bank_amount AS candidate_net_bank_amount,
        pay_batch_candidate_page.awaiting_net_amount AS candidate_awaiting_net_amount,
        pay_batch_candidate_page.settlement_status AS candidate_settlement_status,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.segment_key,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.umbrella_id,
        pay_batch_item_page.bank_reference,
        pay_batch_item_page.pay_bank_transfer_id,
        pay_batch_item_page.repayment_week_start,
        pay_batch_item_page.is_voided,
        pay_batch_item_page.is_mismatch,
        pay_batch_item_page.finance_case_id,
        pay_batch_item_page.finance_component_id,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_basis_json,
        pay_batch_item_page.frozen_component_snapshot_json,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.frozen_resolution_mode,
        pay_batch_item_page.frozen_resolution_payload_json,
        pay_batch_item_page.frozen_resolution_result_json,
        pay_batch_item_page.operation_source_key,
        pay_batch_item_page.created_at,
        pay_batch_item_page.updated_at,
        breakdown_display.first_breakdown_id,
        breakdown_display.line_kind,
        breakdown_display.bucket_code,
        breakdown_display.breakdown_unit_name,
        breakdown_display.breakdown_units,
        breakdown_display.breakdown_rate,
        breakdown_display.breakdown_amount_ex_vat,
        breakdown_display.breakdowns_json,
        display_context.week_ending_date,
        display_context.client_name,
        display_context.role,
        display_context.worked_date,
        display_context.source_rate,
        display_context.source_charge_rate,
        display_context.additional_code,
        display_line.unit_name,
        CASE
          WHEN display_line.unit_name IS NOT NULL
           AND display_context.role IS NOT NULL
           AND UPPER(display_line.unit_name) <> UPPER(display_context.role) THEN display_line.unit_name || ' / ' || display_context.role
          ELSE COALESCE(display_line.unit_name, display_context.role)
        END AS unit_label,
        breakdown_display.breakdown_units AS units,
        breakdown_display.breakdown_rate AS rate
      FROM candidate_scoped_item_ids AS candidate_scoped_item
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.id = candidate_scoped_item.id
      JOIN public.pay_batch_candidates AS pay_batch_candidate_page
        ON pay_batch_candidate_page.id = pay_batch_item_page.pay_batch_candidate_id
      LEFT JOIN LATERAL (
        SELECT
          (ARRAY_AGG(breakdown_page_inner.id ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_id,
          (ARRAY_AGG(breakdown_page_inner.line_kind ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS line_kind,
          (ARRAY_AGG(breakdown_page_inner.bucket_code ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS bucket_code,
          (ARRAY_AGG(breakdown_page_inner.unit_name ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_unit_name,
          (ARRAY_AGG(breakdown_page_inner.units ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_units,
          (ARRAY_AGG(breakdown_page_inner.rate ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_rate,
          (ARRAY_AGG(breakdown_page_inner.amount_ex_vat ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_amount_ex_vat,
          (ARRAY_AGG(breakdown_page_inner.meta_json ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_meta_json,
          COALESCE(
            jsonb_agg(
              jsonb_strip_nulls(jsonb_build_object(
                'id', breakdown_page_inner.id::text,
                'line_kind', breakdown_page_inner.line_kind,
                'bucket_code', breakdown_page_inner.bucket_code,
                'unit_name', breakdown_page_inner.unit_name,
                'units', breakdown_page_inner.units,
                'rate', breakdown_page_inner.rate,
                'amount_ex_vat', breakdown_page_inner.amount_ex_vat,
                'amount_vat', breakdown_page_inner.amount_vat,
                'amount_inc_vat', breakdown_page_inner.amount_inc_vat,
                'meta_json', COALESCE(breakdown_page_inner.meta_json, '{}'::jsonb),
                'operation_source_key', breakdown_page_inner.operation_source_key
              ))
              ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC
            ),
            '[]'::jsonb
          ) AS breakdowns_json
        FROM public.pay_batch_item_breakdowns AS breakdown_page_inner
        WHERE breakdown_page_inner.pay_batch_item_id = pay_batch_item_page.id
      ) AS breakdown_display ON true
      LEFT JOIN LATERAL (
        SELECT
          snapshot_page_inner.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_page_inner
        WHERE snapshot_page_inner.pay_batch_id = pay_batch_candidate_page.pay_batch_id
          AND snapshot_page_inner.timesheet_id = pay_batch_item_page.timesheet_id
          AND snapshot_page_inner.candidate_id = pay_batch_candidate_page.candidate_id
          AND (
            snapshot_page_inner.pay_channel IS NOT DISTINCT FROM pay_batch_item_page.pay_channel
            OR snapshot_page_inner.pay_channel IS NULL
            OR pay_batch_item_page.pay_channel IS NULL
          )
        ORDER BY snapshot_page_inner.created_at_utc DESC, snapshot_page_inner.id DESC
        LIMIT 1
      ) AS snapshot_page ON true
      CROSS JOIN LATERAL (
        SELECT
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
            pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,week_ending_date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,week_ending_date}',
            snapshot_page.target_snapshot_json->>'week_ending_date',
            pay_batch_item_page.payout_instruction_snapshot_json->>'week_ending_bucket'
          )), '') AS week_ending_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
            pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
            pay_batch_item_page.frozen_resolution_result_json->>'client_name',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,client_name}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,client_name}',
            snapshot_page.target_snapshot_json->>'client_name'
          )), '') AS client_name,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'role',
            pay_batch_item_page.frozen_source_basis_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json->>'role',
            pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
            pay_batch_item_page.frozen_resolution_payload_json->>'role',
            pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,job_title}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,job_title}',
            snapshot_page.target_snapshot_json->>'role',
            snapshot_page.target_snapshot_json->>'job_title'
          )), '') AS role,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,date}',
            snapshot_page.target_snapshot_json->>'date',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
               AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS worked_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_rate',
            pay_batch_item_page.frozen_source_basis_json->>'pay_rate',
            pay_batch_item_page.frozen_source_basis_json->>'rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'pay_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,pay_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,pay_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,pay_rate}'
          )), '') AS source_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_charge_rate',
            pay_batch_item_page.frozen_source_basis_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_charge_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,charge_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_charge_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_charge_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,charge_rate}'
          )), '') AS source_charge_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,additional_code}',
            pay_batch_item_page.frozen_resolution_payload_json->>'additional_code',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,additional_code}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,additional_code}',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS additional_code
      ) AS display_context
      CROSS JOIN LATERAL (
        SELECT
          COALESCE(
            NULLIF(BTRIM(COALESCE(breakdown_display.breakdown_unit_name, '')), ''),
            display_context.additional_code,
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_source_basis_json->>'unit_name', pay_batch_item_page.frozen_source_basis_json->>'unit', '')), ''),
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_snapshot_json->>'unit_name', pay_batch_item_page.frozen_component_snapshot_json->>'unit', '')), ''),
            display_context.role
          ) AS unit_name
      ) AS display_line
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_item_page.id > v_cursor_id)
      ORDER BY pay_batch_item_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_item_id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_paye_state', page_rows.candidate_paye_state,
            'candidate_gross_preview', page_rows.candidate_gross_preview,
            'candidate_net_bank_amount', page_rows.candidate_net_bank_amount,
            'candidate_awaiting_net_amount', page_rows.candidate_awaiting_net_amount,
            'candidate_settlement_status', page_rows.candidate_settlement_status,
            'item_type', page_rows.item_type,
            'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
            'segment_key', page_rows.segment_key,
            'source_ref', page_rows.source_ref,
            'description', page_rows.description,
            'amount_ex_vat', page_rows.amount_ex_vat,
            'amount_vat', page_rows.amount_vat,
            'amount_inc_vat', page_rows.amount_inc_vat,
            'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
            'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
            'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat
          )
          || jsonb_build_object(
            'pay_channel', page_rows.pay_channel,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'bank_reference', page_rows.bank_reference,
            'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
            'repayment_week_start', CASE WHEN page_rows.repayment_week_start IS NULL THEN NULL::text ELSE page_rows.repayment_week_start::text END,
            'is_voided', page_rows.is_voided,
            'is_mismatch', page_rows.is_mismatch,
            'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
            'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
            'frozen_component_key_type', page_rows.frozen_component_key_type,
            'frozen_component_key_value', page_rows.frozen_component_key_value,
            'operation_source_key', page_rows.operation_source_key,
            'created_at', page_rows.created_at,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'week_ending_date', page_rows.week_ending_date,
            'client_name', page_rows.client_name,
            'role', page_rows.role,
            'worked_date', page_rows.worked_date,
            'unit_name', page_rows.unit_name,
            'unit_label', page_rows.unit_label,
            'units', page_rows.units,
            'rate', page_rows.rate,
            'source_rate', page_rows.source_rate,
            'source_charge_rate', page_rows.source_charge_rate,
            'additional_code', page_rows.additional_code,
            'line_kind', page_rows.line_kind,
            'bucket_code', page_rows.bucket_code,
            'breakdown_unit_name', page_rows.breakdown_unit_name,
            'breakdown_amount_ex_vat', page_rows.breakdown_amount_ex_vat,
            'breakdowns', page_rows.breakdowns_json
          )
          || jsonb_build_object(
            'frozen_component_classification', page_rows.frozen_component_classification,
            'frozen_source_basis_json', COALESCE(page_rows.frozen_source_basis_json, '{}'::jsonb),
            'frozen_component_snapshot_json', COALESCE(page_rows.frozen_component_snapshot_json, '{}'::jsonb),
            'frozen_source_pay_method', page_rows.frozen_source_pay_method,
            'frozen_target_pay_method', page_rows.frozen_target_pay_method,
            'frozen_resolution_mode', page_rows.frozen_resolution_mode,
            'frozen_resolution_payload_json', COALESCE(page_rows.frozen_resolution_payload_json, '{}'::jsonb),
            'frozen_resolution_result_json', COALESCE(page_rows.frozen_resolution_result_json, '{}'::jsonb),
            'display_context_json', jsonb_strip_nulls(jsonb_build_object(
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'source_rate', page_rows.source_rate,
              'source_charge_rate', page_rows.source_charge_rate,
              'additional_code', page_rows.additional_code
            ))
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'item_breakdowns' THEN
    WITH page_rows AS (
      SELECT
        breakdown_page.id,
        breakdown_page.pay_batch_item_id,
        item_page.pay_batch_candidate_id,
        candidate_page.candidate_id,
        breakdown_page.line_kind,
        breakdown_page.bucket_code,
        breakdown_page.unit_name,
        breakdown_page.units,
        breakdown_page.rate,
        breakdown_page.amount_ex_vat,
        breakdown_page.amount_vat,
        breakdown_page.amount_inc_vat,
        breakdown_page.meta_json,
        breakdown_page.operation_source_key,
        breakdown_page.created_at_utc
      FROM public.pay_batch_item_breakdowns AS breakdown_page
      JOIN public.pay_batch_items AS item_page
        ON item_page.id = breakdown_page.pay_batch_item_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR breakdown_page.id > v_cursor_id)
      ORDER BY breakdown_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', page_rows.id::text,
          'pay_batch_item_id', page_rows.pay_batch_item_id::text,
          'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
          'candidate_id', page_rows.candidate_id::text,
          'line_kind', page_rows.line_kind,
          'bucket_code', page_rows.bucket_code,
          'unit_name', page_rows.unit_name,
          'units', page_rows.units,
          'rate', page_rows.rate,
          'amount_ex_vat', page_rows.amount_ex_vat,
          'amount_vat', page_rows.amount_vat,
          'amount_inc_vat', page_rows.amount_inc_vat,
          'meta_json', COALESCE(page_rows.meta_json, '{}'::jsonb),
          'operation_source_key', page_rows.operation_source_key,
          'created_at_utc', page_rows.created_at_utc
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section IN ('transfers', 'current_payment_status') THEN
    WITH page_rows AS (
      SELECT
        transfer_page.id,
        transfer_page.pay_batch_id,
        transfer_page.candidate_id,
        transfer_page.umbrella_id,
        transfer_page.pay_channel,
        transfer_page.amount,
        transfer_page.currency,
        transfer_page.status,
        transfer_page.payment_reference,
        transfer_page.payee_name,
        transfer_page.sort_code,
        transfer_page.account_number,
        transfer_page.account_type,
        transfer_page.created_at_utc,
        transfer_page.completed_at_utc,
        transfer_page.failed_reason,
        transfer_page.rail_provider,
        transfer_page.rail_env,
        transfer_page.request_id,
        transfer_page.rail_tx_id,
        transfer_page.rail_state,
        transfer_page.rail_meta_json,
        transfer_page.bank_details_hash_snapshot,
        transfer_page.payee_entity_kind,
        transfer_page.payee_entity_id,
        transfer_page.transfer_group_key,
        transfer_page.grouping_mode_used,
        transfer_page.week_ending_bucket,
        candidate_page.id AS pay_batch_candidate_id,
        candidate_page.candidate_display_name,
        latest_event_page.provider_key AS latest_event_provider_key,
        latest_event_page.provider_transaction_id AS latest_provider_transaction_id,
        latest_event_page.provider_request_id AS latest_provider_request_id,
        latest_event_page.provider_event_key AS latest_provider_event_key,
        latest_event_page.provider_event_id AS latest_provider_event_id,
        latest_event_page.provider_reference AS latest_provider_reference,
        latest_event_page.normalised_state AS latest_event_normalised_state,
        latest_event_page.provider_state AS latest_event_provider_state,
        latest_event_page.provider_failure_reason_code AS latest_provider_failure_reason_code,
        latest_event_page.provider_failure_reason_group AS latest_provider_failure_reason_group,
        latest_event_page.event_time_utc AS latest_event_time_utc,
        latest_event_page.received_at_utc AS latest_event_received_at_utc,
        latest_event_page.correction_disposition AS latest_event_correction_disposition,
        latest_event_page.movement_classification AS latest_event_movement_classification
      FROM public.pay_bank_transfers AS transfer_page
      LEFT JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.pay_batch_id = transfer_page.pay_batch_id
       AND candidate_page.candidate_id = transfer_page.candidate_id
      LEFT JOIN LATERAL (
        SELECT
          event_page.provider_key,
          event_page.provider_transaction_id,
          event_page.provider_request_id,
          event_page.provider_event_key,
          event_page.provider_event_id,
          event_page.provider_reference,
          event_page.normalised_state,
          event_page.provider_state,
          event_page.provider_failure_reason_code,
          event_page.provider_failure_reason_group,
          event_page.event_time_utc,
          event_page.received_at_utc,
          event_page.correction_disposition,
          event_page.movement_classification
        FROM public.pay_bank_transfer_events AS event_page
        WHERE event_page.pay_batch_id = transfer_page.pay_batch_id
          AND event_page.pay_bank_transfer_id = transfer_page.id
        ORDER BY COALESCE(event_page.event_time_utc, event_page.received_at_utc, event_page.created_at_utc) DESC NULLS LAST,
                 event_page.id DESC
        LIMIT 1
      ) AS latest_event_page ON true
      WHERE transfer_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR transfer_page.id > v_cursor_id)
      ORDER BY transfer_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', CASE WHEN page_rows.candidate_id IS NULL THEN NULL::text ELSE page_rows.candidate_id::text END,
            'pay_batch_candidate_id', CASE WHEN page_rows.pay_batch_candidate_id IS NULL THEN NULL::text ELSE page_rows.pay_batch_candidate_id::text END,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_name', page_rows.candidate_display_name,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'pay_channel', page_rows.pay_channel,
            'amount', page_rows.amount,
            'currency', page_rows.currency,
            'status', page_rows.status,
            'payment_reference', page_rows.payment_reference,
            'payee_name', page_rows.payee_name,
            'sort_code', page_rows.sort_code,
            'account_number', page_rows.account_number,
            'account_type', page_rows.account_type
          )
          || jsonb_build_object(
            'created_at_utc', page_rows.created_at_utc,
            'completed_at_utc', page_rows.completed_at_utc,
            'failed_reason', page_rows.failed_reason,
            'rail_provider', page_rows.rail_provider,
            'rail_env', page_rows.rail_env,
            'request_id', page_rows.request_id,
            'rail_tx_id', page_rows.rail_tx_id,
            'rail_state', page_rows.rail_state,
            'rail_meta_json', COALESCE(page_rows.rail_meta_json, '{}'::jsonb),
            'bank_details_hash_snapshot', page_rows.bank_details_hash_snapshot,
            'payee_entity_kind', page_rows.payee_entity_kind,
            'payee_entity_id', CASE WHEN page_rows.payee_entity_id IS NULL THEN NULL::text ELSE page_rows.payee_entity_id::text END,
            'transfer_group_key', page_rows.transfer_group_key,
            'grouping_mode_used', page_rows.grouping_mode_used,
            'week_ending_bucket', CASE WHEN page_rows.week_ending_bucket IS NULL THEN NULL::text ELSE page_rows.week_ending_bucket::text END
          )
          || CASE
            WHEN v_section = 'current_payment_status' THEN jsonb_build_object(
              'payment_lifecycle_state', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state',
              'payment_lifecycle_label', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_label',
              'recommended_action', transfer_diagnostic.diagnostic_json->>'recommended_action',
              'row_cancel_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
              'can_no_money_unwind', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
              'can_recover_overpayment', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
              'provider_outcome_unknown_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
              'provider_webhook_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
              'terminal_no_money_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
              'pending_provider_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
              'status_update_signature', NULLIF(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'status_update_signature', '')), ''),
              'provider_submission_status', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json->>'provider_submission_status',
                page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
                page_rows.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
                page_rows.rail_meta_json->>'provider_submission_status',
                ''
              )), ''),
              'money_movement_cash_state', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}',
                transfer_diagnostic.diagnostic_json->>'cash_state',
                page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}',
                ''
              )), ''),
              'is_final_money_moved', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','BANK_CONFIRMED','MANUAL_CONFIRM')
              ),
              'safe_retry_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'safe_retry_available', page_rows.rail_meta_json #>> '{provider_submit_diagnostic,safe_retry_available}', 'false'))) IN ('true','1','yes','y','on'),
              'payment_status_raw', page_rows.status,
              'payment_status_bucket', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                ) THEN 'SENT_CONFIRMED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                  THEN 'FAILED_RETURNED'
                WHEN UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state', ''))) IN ('PROVIDER_OUTCOME_UNKNOWN','CHECK_REQUIRED','UNKNOWN')
                  OR UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'recommended_action', ''))) = 'CHECK_PROVIDER_STATUS'
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  THEN 'CHECK_REQUIRED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
                  OR NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), '') IS NOT NULL
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', page_rows.rail_meta_json->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
                  THEN 'PENDING_SUBMITTED'
                ELSE 'NOT_SENT'
              END,
              'payment_status_label', public._pay_bank_transfer_status_display_label(
                page_rows.status,
                page_rows.rail_state,
                COALESCE(
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}'), ''),
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'cash_state'), ''),
                  NULLIF(BTRIM(page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}'), ''),
                  CASE
                    WHEN LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on') THEN 'FINAL_PAID'
                    ELSE NULL::text
                  END
                )
              ),
              'payment_terminal_success', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
              ),
              'payment_terminal_failed', (
                UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal_timestamp', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'payment_terminal_at_utc', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'provider', COALESCE(page_rows.rail_provider, page_rows.latest_event_provider_key),
              'rail', page_rows.rail_env,
              'rail_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), ''),
              'provider_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_transaction_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', page_rows.rail_meta_json #>> '{provider_transaction_id}', '')), ''),
              'provider_request_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_request_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', page_rows.request_id, '')), ''),
              'provider_event_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_event_id, page_rows.latest_provider_event_key, '')), ''),
              'provider_reference', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_reference, page_rows.payment_reference, '')), ''),
              'provider_failure_reason_code', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_code, '')), ''),
              'provider_failure_reason_group', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_group, '')), ''),
              'action_review_status', COALESCE(NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'recommended_action'), ''), NULLIF(BTRIM(page_rows.latest_event_correction_disposition), ''))
            )
            ELSE '{}'::jsonb
          END
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows
    LEFT JOIN LATERAL (
      SELECT CASE
        WHEN v_section = 'current_payment_status' THEN public.pay_payment_cancelability_diagnostic(
          p_pay_batch_id,
          jsonb_build_object(
            'scope_type', 'TRANSFER',
            'pay_bank_transfer_ids', jsonb_build_array(page_rows.id::text)
          ),
          p_actor_user_id,
          'CURRENT_PAYMENT_STATUS'
        )
        ELSE '{}'::jsonb
      END AS diagnostic_json
    ) AS transfer_diagnostic ON true;

  ELSIF v_section = 'finance_case_groups' THEN
    WITH group_keys AS (
      SELECT COALESCE(item_page.finance_case_id, item_page.finance_component_id) AS group_id
      FROM public.pay_batch_items AS item_page
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (item_page.finance_case_id IS NOT NULL OR item_page.finance_component_id IS NOT NULL)
      GROUP BY COALESCE(item_page.finance_case_id, item_page.finance_component_id)
    ),
    page_rows AS (
      SELECT
        group_keys.group_id,
        (ARRAY_AGG(item_page.finance_case_id ORDER BY item_page.finance_case_id::text) FILTER (WHERE item_page.finance_case_id IS NOT NULL))[1] AS finance_case_id,
        (ARRAY_AGG(item_page.finance_component_id ORDER BY item_page.finance_component_id::text) FILTER (WHERE item_page.finance_component_id IS NOT NULL))[1] AS finance_component_id,
        COUNT(*)::integer AS item_count,
        ROUND(COALESCE(SUM(COALESCE(item_page.amount_ex_vat, 0)), 0), 2)::numeric AS total_amount_ex_vat,
        COALESCE(jsonb_agg(DISTINCT item_page.item_type) FILTER (WHERE item_page.item_type IS NOT NULL), '[]'::jsonb) AS item_types,
        COALESCE(jsonb_agg(DISTINCT candidate_page.candidate_id::text) FILTER (WHERE candidate_page.candidate_id IS NOT NULL), '[]'::jsonb) AS candidate_ids
      FROM group_keys
      JOIN public.pay_batch_items AS item_page
        ON COALESCE(item_page.finance_case_id, item_page.finance_component_id) = group_keys.group_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR group_keys.group_id > v_cursor_id)
      GROUP BY group_keys.group_id
      ORDER BY group_keys.group_id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(jsonb_build_object(
        'group_id', page_rows.group_id::text,
        'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
        'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
        'item_count', page_rows.item_count,
        'total_amount_ex_vat', page_rows.total_amount_ex_vat,
        'item_types', page_rows.item_types,
        'candidate_ids', page_rows.candidate_ids
      ) ORDER BY page_rows.group_id ASC), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.group_id::text ORDER BY page_rows.group_id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'remittances' THEN
    WITH page_rows AS (
      SELECT
        mail_page.id,
        mail_page.type,
        mail_page."to" AS mail_to,
        mail_page.cc,
        mail_page.bcc,
        mail_page.subject,
        mail_page.status::text AS status,
        mail_page.provider_status,
        mail_page.recipient_kind,
        mail_page.recipient_id,
        mail_page.context_kind,
        mail_page.context_id,
        mail_page.reference,
        mail_page.created_at_utc,
        mail_page.sent_at,
        mail_page.failed_at,
        mail_page.last_error,
        mail_page.deterministic_outbox_key
      FROM public.mail_outbox AS mail_page
      WHERE (
           mail_page.payment_scope_json->>'pay_batch_id' = p_pay_batch_id::text
        OR (LOWER(COALESCE(mail_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND mail_page.context_id = p_pay_batch_id)
        OR mail_page.reference = p_pay_batch_id::text
        OR mail_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR mail_page.id > v_cursor_id)
      ORDER BY mail_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'communications' THEN
    WITH page_rows AS (
      SELECT
        comms_page.id,
        comms_page.channel,
        comms_page.status,
        comms_page.to_address,
        comms_page.provider_key,
        comms_page.provider_message_id,
        comms_page.recipient_kind,
        comms_page.recipient_id,
        comms_page.context_kind,
        comms_page.context_id,
        comms_page.created_at_utc,
        comms_page.sent_at,
        comms_page.delivered_at,
        comms_page.read_at,
        comms_page.failed_at,
        comms_page.last_error,
        comms_page.deterministic_outbox_key
      FROM public.comms_outbox AS comms_page
      WHERE (
           (LOWER(COALESCE(comms_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND comms_page.context_id = p_pay_batch_id)
        OR comms_page.provider_payload_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.provider_response_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR comms_page.id > v_cursor_id)
      ORDER BY comms_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'auth_history' THEN
    WITH page_rows AS (
      SELECT
        auth_page.id,
        auth_page.pay_batch_id,
        auth_page.requested_by_user_id,
        auth_page.required_quantity,
        auth_page.schedule_kind,
        auth_page.scheduled_at_utc,
        auth_page.funding_account_ref,
        auth_page.state,
        auth_page.golden_key_used,
        auth_page.golden_key_user_id,
        auth_page.created_at_utc,
        auth_page.finalised_at_utc,
        auth_page.finalised_by_user_id,
        auth_page.execution_intent_json
      FROM public.pay_batch_auth_requests AS auth_page
      WHERE auth_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR auth_page.id > v_cursor_id)
      ORDER BY auth_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'events' THEN
    WITH page_rows AS (
      SELECT
        event_page.id,
        event_page.pay_batch_id,
        event_page.pay_bank_transfer_id,
        event_page.candidate_id,
        event_page.umbrella_id,
        event_page.provider_key,
        event_page.provider_event_id,
        event_page.provider_reference,
        event_page.provider_state,
        event_page.normalised_state,
        event_page.event_source,
        event_page.event_time_utc,
        event_page.received_at_utc,
        event_page.amount,
        event_page.currency,
        event_page.mapping_status,
        event_page.movement_classification,
        event_page.correction_disposition,
        event_page.mapping_method,
        event_page.created_at_utc
      FROM public.pay_bank_transfer_events AS event_page
      WHERE event_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR event_page.id > v_cursor_id)
      ORDER BY event_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;
  END IF;

  v_raw_count := COALESCE(v_raw_count, 0);

  IF v_raw_count > v_limit THEN
    v_next_cursor := jsonb_build_object(
      'last_id',
      COALESCE(
        v_items -> (v_limit - 1) ->> 'id',
        v_items -> (v_limit - 1) ->> 'group_id',
        v_last_cursor_text
      )
    );

    SELECT COALESCE(jsonb_agg(trimmed_items.value ORDER BY trimmed_items.ordinality), '[]'::jsonb)
    INTO v_items
    FROM jsonb_array_elements(COALESCE(v_items, '[]'::jsonb)) WITH ORDINALITY AS trimmed_items(value, ordinality)
    WHERE trimmed_items.ordinality <= v_limit;

    v_returned_count := v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
    v_returned_count := v_raw_count;
  END IF;

  v_section_page_signature := 'pay_batch_section_page:v2:' || MD5(
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'section', v_section,
      'purpose', v_purpose,
      'items', COALESCE(v_items, '[]'::jsonb),
      'next_cursor', v_next_cursor,
      'live_signal_version', COALESCE(v_live_signal_version, 0),
      'payment_status_version', COALESCE(v_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_correction_progress_version, 0),
      'overview_version', COALESCE(v_overview_version, 0),
      'candidate_scope', CASE
        WHEN v_candidate_scope_enabled THEN jsonb_build_object(
          'scope_type', 'PAY_BATCH_CANDIDATE',
          'pay_batch_candidate_id', v_candidate_scope_pay_batch_candidate_id::text,
          'candidate_id', v_candidate_scope_candidate_id::text
        )
        ELSE NULL::jsonb
      END
    )::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'section', v_section,
    'purpose', v_purpose,
    'items', COALESCE(v_items, '[]'::jsonb),
    'next_cursor', v_next_cursor,
    'returned_count', COALESCE(v_returned_count, 0),
    'known_total_count', v_known_total_count,
    'pay_batch_id', p_pay_batch_id::text,
    'server_time_utc', v_server_time_utc::text,
    'section_page_signature', v_section_page_signature,
    'live_signal_version', COALESCE(v_live_signal_version, 0),
    'payment_status_version', COALESCE(v_payment_status_version, 0),
    'correction_progress_version', COALESCE(v_correction_progress_version, 0),
    'alert_version', COALESCE(v_alert_version, 0),
    'overview_version', COALESCE(v_overview_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'known_live_signal_version', v_known_live_signal_version,
    'changed_since_version', COALESCE(v_changed_since_version, false),
    'batch_status', v_batch.status,
    'execution_commit_state', v_batch.execution_commit_state,
    'freshness', v_freshness_summary,
    'limit', v_limit,
    'scope_type', CASE WHEN v_candidate_scope_enabled THEN 'PAY_BATCH_CANDIDATE' ELSE NULL::text END,
    'pay_batch_candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_pay_batch_candidate_id::text ELSE NULL::text END,
    'candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_candidate_id::text ELSE NULL::text END
  );
END;
$function$;

-- pay_batch_get(uuid,uuid,text,integer)
CREATE OR REPLACE FUNCTION public.pay_batch_get(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_detail_mode text DEFAULT 'AUTO'::text, p_recommended_page_size integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch record;
  v_candidates jsonb := '[]'::jsonb;
  v_transfers jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;

  -- ✅ NEW: derived batch kind + channels
  v_batch_kind text := null;
  v_pay_channels_present jsonb := '[]'::jsonb;

  -- ✅ NEW: child modal support payloads
  v_candidate_breakdown jsonb := '[]'::jsonb;
  v_candidate_lines jsonb := '[]'::jsonb;
  v_finance_case_groups jsonb := '[]'::jsonb;
  v_finance_summaries jsonb := '{}'::jsonb;
  v_remittance_summary jsonb := '{}'::jsonb;
  v_communications_summary jsonb := '{}'::jsonb;

  -- ✅ C: schedule recommendations / UI defaults
  v_default_schedule_umbrella_local text := null;
  v_default_schedule_paye_local text := null;
  v_funds_warning_hours_json jsonb := null;
  v_rail_default_funding_account_ref text := null;

  -- ✅ D: authorisation summary (lightweight, for Banking UI)
  v_ar record;
  v_auth_approved_count int := 0;
  v_auth_approved_by jsonb := '[]'::jsonb;
  v_auth_invited_to jsonb := '[]'::jsonb;
  v_auth jsonb := null;

  v_batch_kind_fixed text := null;

  v_provider_normalized text := null;
  v_provider_known boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_batch_status_upper text := null;
  v_batch_status_raw text := NULL::text;
  v_batch_status_label text := NULL::text;
  v_batch_terminal_with_failed_payments boolean := false;
  v_pending_bank_outcome_count integer := 0;
  v_unknown_bank_outcome_count integer := 0;
  v_terminal_success_payment_count integer := 0;
  v_terminal_failed_payment_count integer := 0;
  v_settlement_required boolean := false;
  v_has_external_submission_evidence boolean := false;
  v_submission_evidence jsonb := '{}'::jsonb;
  v_current_transfer_hash text := null;
  v_pending_transfer_hash text := null;
  v_stable_transfer_hash text := null;
  v_execution_transfer_hash text := null;
  v_csv_comparison_transfer_hash text := null;
  v_csv_export_match_basis text := null;
  v_bank_csv_export_hash text := null;
  v_has_cloudtms_csv_export boolean := false;
  v_csv_export_matches_current_transfers boolean := false;
  v_can_create_bank_csv_file boolean := false;
  v_can_start_standard_execution boolean := false;
  v_can_start_csv_settlement boolean := false;
  v_can_start_external_settlement boolean := false;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_active_auth_execution_intent_json jsonb := null;
  v_execution_mode_pending text := null;
  v_suppress_remittances_pending boolean := false;

  -- Payment correction summary payloads for Banking Pay batch modal
  v_payment_correction jsonb := '{}'::jsonb;
  v_bank_evidence jsonb := '[]'::jsonb;
  v_movement_classification jsonb := '{}'::jsonb;
  v_manual_actions jsonb := '{}'::jsonb;
  v_communication_status jsonb := '{}'::jsonb;
  v_finance_case_correction_summary jsonb := '[]'::jsonb;
  v_correction_progress jsonb := '{}'::jsonb;
  v_open_correction_request_id uuid := NULL::uuid;
  v_latest_correction_request jsonb := '{}'::jsonb;
  v_latest_correction_request_status text := NULL::text;
  v_open_correction_request_count integer := 0;
  v_open_settled_reversal_request_count integer := 0;
  v_awaiting_authorisation_count integer := 0;
  v_processing_request_count integer := 0;
  v_blocked_request_count integer := 0;
  v_failed_request_count integer := 0;
  v_work_item_pending_count integer := 0;
  v_work_item_processing_count integer := 0;
  v_work_item_blocked_count integer := 0;
  v_work_item_failed_retryable_count integer := 0;
  v_work_item_failed_final_count integer := 0;
  v_work_item_failed_count integer := 0;
  v_work_item_requires_user_action boolean := false;
  v_work_item_processing_continues boolean := false;
  v_bank_event_count integer := 0;
  v_bank_failure_event_count integer := 0;
  v_bank_return_event_count integer := 0;
  v_transfer_failure_count integer := 0;
  v_transfer_completed_count integer := 0;
  v_transfer_provider_evidence_count integer := 0;
  v_settlement_evidence_count integer := 0;
  v_applied_unwind_item_count integer := 0;
  v_applied_reversal_item_count integer := 0;
  v_applied_precancel_item_count integer := 0;
  v_correctable_item_count integer := 0;
  v_corrected_item_count integer := 0;
  v_derived_correction_state text := 'NONE';
  v_can_cancel_payment_attempt boolean := false;
  v_can_unwind_failed_payment boolean := false;
  v_can_reverse_settled_payment boolean := false;
  v_can_review_bank_evidence boolean := false;
  v_active_effective_item_count integer := 0;
  v_active_effective_amount_ex_vat numeric := 0;
  v_active_effective_amount_inc_vat numeric := 0;
  v_payment_issue_candidate_count integer := 0;

  -- Banking alert / legacy funds-check compatibility support
  v_alert_actor_user_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_alert_registry jsonb := jsonb_build_object('alerts', '[]'::jsonb, 'unacknowledged_count', 0, 'highest_severity', NULL::text, 'highest_label', NULL::text);
  v_banking_alerts jsonb := '[]'::jsonb;
  v_banking_alert_kind text := NULL::text;
  v_banking_alert_severity text := NULL::text;
  v_banking_alert_label text := NULL::text;
  v_banking_alert_reason text := NULL::text;
  v_banking_alert_fingerprint text := NULL::text;
  v_banking_alert_acknowledged_for_user boolean := false;
  v_banking_alert_requires_attention boolean := false;
  v_blocked_funds_required_gbp numeric := NULL::numeric;
  v_blocked_funds_available_gbp numeric := NULL::numeric;
  v_blocked_funds_required_gbp_display text := '—';
  v_blocked_funds_available_gbp_display text := '—';
  v_blocked_funds_reason text := NULL::text;
  v_blocked_funds_sufficient boolean := NULL::boolean;
  v_blocked_funds_provider text := NULL::text;
  v_blocked_funds_env text := NULL::text;
  v_blocked_funds_account_ref text := NULL::text;
  v_no_bank_transfer_events boolean := true;
  v_no_rail_tx_id boolean := true;
  v_no_provider_submission_reference boolean := true;
  v_no_submitted_or_completed_transfer_state boolean := true;
  v_no_provider_attempt_request_or_idempotency_reference boolean := true;
  v_no_possible_provider_attempt_evidence boolean := true;
  v_no_external_submission_evidence boolean := true;
  v_no_submission_evidence_flags jsonb := '{}'::jsonb;
  v_can_retry_blocked_funds boolean := false;
  v_blocked_funds_alert_payload jsonb := '{}'::jsonb;
  v_blocked_funds_payment_issue jsonb := NULL::jsonb;
  v_batch_stale_payment_issue jsonb := NULL::jsonb;
  v_batch_stale_payment_execution_review jsonb := NULL::jsonb;
  v_payment_issues jsonb := '[]'::jsonb;

  -- Scalable batch-open controls. These allow large batches to return a compact
  -- bootstrap payload without building heavy candidate/item/transfer arrays.
  v_detail_mode text := 'AUTO';
  v_effective_page_size integer := 100;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_item_breakdown_count integer := 0;
  v_transfer_count integer := 0;
  v_large_batch boolean := false;
  v_large_batch_reasons jsonb := '[]'::jsonb;
  v_bootstrap_only boolean := false;
  v_total_amount numeric := 0;
  v_provider_submitted_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_failed_transfer_count integer := 0;
  v_ambiguous_transfer_count integer := 0;
  v_attempted_but_unproven_transfer_count integer := 0;
  v_remittance_status_summary jsonb := '{}'::jsonb;
  v_settlement_status_summary jsonb := '{}'::jsonb;
  v_active_operation_id uuid := NULL::uuid;
  v_active_operation_type text := NULL::text;
  v_active_operation_status text := NULL::text;
  v_active_operation_phase text := NULL::text;
  v_active_operation_progress jsonb := NULL::jsonb;
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_freshness_is_stale boolean := false;
  v_provider_environment_summary jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_provider_submit_review_reason_code text := NULL::text;
  v_provider_submit_headline text := NULL::text;
  v_provider_submit_summary text := NULL::text;
  v_provider_submit_action_required text := NULL::text;
  v_provider_submit_actual_context boolean := false;
  v_payment_provider_review_required boolean := false;
  v_provider_submit_is_diagnostic_only boolean := false;
  v_provider_submit_backend_review_required boolean := false;
  v_provider_submit_operation_review_required boolean := false;
  v_provider_submit_acceptance_retry_unsafe boolean := false;
  v_provider_submit_issue_present boolean := false;
  v_provider_submit_manual_resolution_required boolean := false;
  v_provider_submit_manual_resolution_available boolean := false;
  v_provider_submit_safe_retry_available boolean := false;
  v_provider_submit_acceptance_evidence_present boolean := false;
  v_provider_submit_response_present boolean := false;
  v_provider_submit_stale_chunk boolean := false;
  v_payment_execution_review jsonb := NULL::jsonb;
  v_provider_submit_payment_issue jsonb := NULL::jsonb;
  v_available_sections jsonb := '["overview_items","current_payment_status","candidates","items","item_breakdowns","transfers","finance_case_groups","remittances","communications","auth_history","events"]'::jsonb;

  -- 3.41 backend-derived lifecycle/action/carry-forward payloads for Overview and Current Payment Status.
  v_batch_cancelability_diagnostic jsonb := '{}'::jsonb;
  v_batch_payment_lifecycle_state text := NULL::text;
  v_batch_payment_lifecycle_label text := NULL::text;
  v_batch_recommended_action text := NULL::text;
  v_whole_batch_cancel_available boolean := false;
  v_batch_can_pre_provider_cancel boolean := false;
  v_batch_requires_bank_check boolean := false;
  v_batch_requires_provider_cancel boolean := false;
  v_retry_state text := NULL::text;
  v_retry_after_utc text := NULL::text;
  v_retry_reason text := NULL::text;
  v_next_retry_description text := NULL::text;
  v_retry_plan_json jsonb := '{}'::jsonb;
  v_retry_eligible_count integer := 0;
  v_retry_ineligible_count integer := 0;
  v_retry_in_progress boolean := false;
  v_retry_already_in_progress boolean := false;
  v_retry_operation_id uuid := NULL::uuid;
  v_retry_operation_status text := NULL::text;
  v_retry_eligible_scope_json jsonb := '{}'::jsonb;
  v_retry_ineligible_summary_json jsonb := '[]'::jsonb;
  v_retry_scope_signature text := NULL::text;
  v_retry_status_label text := NULL::text;
  v_retry_button_label text := 'Retry unsent payments';
  v_retry_button_disabled_reason text := NULL::text;
  v_retry_button_visible boolean := false;
  v_partial_cancel_count integer := 0;
  v_cancelled_before_bank_submission_count integer := 0;
  v_financials_rewound_count integer := 0;
  v_manual_adjustments_carried_forward_count integer := 0;
  v_manual_adjustment_carry_forward_records_json jsonb := '[]'::jsonb;
  v_remittance_already_sent boolean := false;
  v_remittance_sent_outbox_count integer := 0;
  v_remittance_reconciled_sent_count integer := 0;
  v_clean_paid_or_settled_success boolean := false;
  v_has_actual_recovery_context boolean := false;
  v_has_provider_unknown_context boolean := false;
  v_has_no_money_context boolean := false;
  v_has_failed_remittance_context boolean := false;
  v_has_unmatched_or_ambiguous_event_context boolean := false;
  v_action_required boolean := false;
  v_batch_support_details_json jsonb := '{}'::jsonb;
  v_batch_signal_version bigint := 0;
  v_batch_payment_status_version bigint := 0;
  v_batch_correction_progress_version bigint := 0;
  v_batch_alert_version bigint := 0;
  v_batch_overview_version bigint := 0;
  v_batch_last_status_hash text := NULL::text;
  v_batch_last_alert_hash text := NULL::text;
  v_provider_webhook_evidence_json jsonb := '{}'::jsonb;
  -- 4.2 BOOTSTRAP_ONLY safe path support. These values are loaded from
  -- pay_batch_display_summary and cheap signal rows only, before any heavy
  -- diagnostics/evidence/remittance/correction scans are allowed to run.
  v_display_summary_found boolean := false;
  v_display_batch_status text := NULL::text;
  v_display_batch_kind text := NULL::text;
  v_display_candidate_count integer := 0;
  v_display_item_count integer := 0;
  v_display_transfer_count integer := 0;
  v_display_total_payable numeric := 0;
  v_display_total_bank_out numeric := 0;
  v_display_execution_commit_state text := NULL::text;
  v_display_rail_provider_label text := NULL::text;
  v_display_rail_env_label text := NULL::text;
  v_display_issue_summary_counts jsonb := '{}'::jsonb;
  v_display_latest_operation_id uuid := NULL::uuid;
  v_display_latest_operation_status text := NULL::text;
  v_display_latest_operation_phase text := NULL::text;
  v_display_label text := NULL::text;
  v_display_stale_summary_json jsonb := '{}'::jsonb;
  v_display_freshness_validation_status text := NULL::text;
  v_display_freshness_checked_at_utc timestamptz := NULL::timestamptz;
  v_display_freshness_result_hash text := NULL::text;
  v_display_summary_version bigint := 0;
  v_display_summary_updated_at_utc timestamptz := NULL::timestamptz;
  v_bootstrap_detail_mode_applied text := 'FULL';
  v_actor_is_active boolean := true;

  -- Bootstrap display-summary validation. These values are derived from durable
  -- batch artefacts using cheap counts before the BOOTSTRAP_ONLY early return,
  -- so a stale pay_batch_display_summary row cannot make a populated batch look
  -- empty. They are display/open metadata only and do not alter Policy X
  -- post-draft economic authority, frozen artefacts, settlement, remittance, or
  -- export calculations.
  v_durable_candidate_count integer := 0;
  v_durable_item_count integer := 0;
  v_durable_item_breakdown_count integer := 0;
  v_durable_timesheet_snapshot_count integer := 0;
  v_durable_transfer_count integer := 0;
  v_durable_total_payable numeric := 0;
  v_durable_total_bank_out numeric := 0;
  v_durable_sent_confirmed_count integer := 0;
  v_durable_sent_confirmed_amount numeric := 0;
  v_durable_pending_submitted_count integer := 0;
  v_durable_pending_submitted_amount numeric := 0;
  v_durable_failed_returned_count integer := 0;
  v_durable_failed_returned_amount numeric := 0;
  v_durable_check_required_count integer := 0;
  v_durable_check_required_amount numeric := 0;
  v_durable_not_sent_count integer := 0;
  v_durable_not_sent_amount numeric := 0;
  v_durable_counts jsonb := '{}'::jsonb;
  v_payment_status_buckets jsonb := '{}'::jsonb;
  v_display_summary_stale_before_refresh boolean := false;
  v_display_summary_repaired boolean := false;
  v_display_summary_stale boolean := false;
  v_summary_refresh_failed boolean := false;
  v_summary_refresh_error text := NULL::text;
  v_empty_shell boolean := false;
  v_empty_shell_kind text := NULL::text;
  v_empty_shell_message text := NULL::text;
  v_batch_signal_last_changed_at_utc timestamptz := NULL::timestamptz;
begin
  v_detail_mode := upper(btrim(coalesce(p_detail_mode, 'AUTO')));
  IF v_detail_mode NOT IN ('AUTO','FULL','BOOTSTRAP_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_INVALID_DETAIL_MODE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_INVALID_DETAIL_MODE',
              'detail_mode', p_detail_mode,
              'allowed_modes', jsonb_build_array('AUTO','FULL','BOOTSTRAP_ONLY')
            )::text;
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply(
    CASE WHEN v_detail_mode = 'FULL' THEN 'EXPLICIT_DIAGNOSTIC' ELSE 'BATCH_BOOTSTRAP' END
  );

  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  select
    pb.*
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if not found then
    raise exception 'pay_batch not found';
  end if;

  v_batch_kind_fixed := upper(btrim(coalesce(v_batch.batch_kind_fixed::text,'')));
  v_batch_status_upper := upper(btrim(coalesce(v_batch.status::text, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state::text, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED','SUBMITTED_NOT_COMMITTED','COMMITTED') then
    v_execution_commit_state := null;
  end if;

  v_provider_normalized := upper(btrim(coalesce(v_batch.rail_provider_snapshot::text, '')));
  if v_provider_normalized = 'REV' then
    v_provider_normalized := 'REVOLUT';
  end if;
  v_provider_known := (v_provider_normalized in ('REVOLUT','CSV'));

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  v_detail_mode := upper(btrim(coalesce(p_detail_mode, 'AUTO')));
  IF v_detail_mode NOT IN ('AUTO','FULL','BOOTSTRAP_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_INVALID_DETAIL_MODE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_INVALID_DETAIL_MODE',
              'detail_mode', p_detail_mode,
              'allowed_modes', jsonb_build_array('AUTO','FULL','BOOTSTRAP_ONLY')
            )::text;
  END IF;

  v_effective_page_size := LEAST(250, GREATEST(25, COALESCE(p_recommended_page_size, 100)));

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user_check
      WHERE actor_user_check.id = p_actor_user_id
        AND COALESCE(actor_user_check.is_active, false) = true
    )
    INTO v_actor_is_active;

    IF COALESCE(v_actor_is_active, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  SELECT
    display_summary.batch_status,
    display_summary.batch_kind,
    COALESCE(display_summary.candidate_count, 0),
    COALESCE(display_summary.item_count, 0),
    COALESCE(display_summary.transfer_count, 0),
    COALESCE(display_summary.total_payable, 0),
    COALESCE(display_summary.total_bank_out, 0),
    display_summary.execution_commit_state,
    display_summary.rail_provider_label,
    display_summary.rail_env_label,
    COALESCE(display_summary.issue_summary_counts, '{}'::jsonb),
    display_summary.latest_operation_id,
    display_summary.latest_operation_status,
    display_summary.latest_operation_phase,
    display_summary.display_label,
    COALESCE(display_summary.stale_summary_json, '{}'::jsonb),
    display_summary.freshness_validation_status,
    display_summary.freshness_checked_at_utc,
    display_summary.freshness_result_hash,
    COALESCE(display_summary.summary_version, 0),
    display_summary.updated_at_utc
  INTO
    v_display_batch_status,
    v_display_batch_kind,
    v_display_candidate_count,
    v_display_item_count,
    v_display_transfer_count,
    v_display_total_payable,
    v_display_total_bank_out,
    v_display_execution_commit_state,
    v_display_rail_provider_label,
    v_display_rail_env_label,
    v_display_issue_summary_counts,
    v_display_latest_operation_id,
    v_display_latest_operation_status,
    v_display_latest_operation_phase,
    v_display_label,
    v_display_stale_summary_json,
    v_display_freshness_validation_status,
    v_display_freshness_checked_at_utc,
    v_display_freshness_result_hash,
    v_display_summary_version,
    v_display_summary_updated_at_utc
  FROM public.pay_batch_display_summary AS display_summary
  WHERE display_summary.pay_batch_id = p_pay_batch_id;

  v_display_summary_found := FOUND;

  IF v_display_summary_found IS NOT TRUE THEN
    v_display_batch_status := v_batch.status;
    v_display_batch_kind := v_batch.batch_kind_fixed;
    v_display_candidate_count := 0;
    v_display_item_count := 0;
    v_display_transfer_count := 0;
    v_display_total_payable := 0;
    v_display_total_bank_out := COALESCE(v_batch.total_bank_out, 0);
    v_display_execution_commit_state := v_batch.execution_commit_state;
    v_display_rail_provider_label := v_batch.rail_provider_snapshot;
    v_display_rail_env_label := v_batch.rail_env_snapshot;
    v_display_issue_summary_counts := '{}'::jsonb;
    v_display_stale_summary_json := '{}'::jsonb;
    v_display_freshness_validation_status := to_jsonb(v_batch) ->> 'freshness_validation_status';
    BEGIN
      v_display_freshness_checked_at_utc := NULLIF(to_jsonb(v_batch) ->> 'freshness_checked_at_utc', '')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      v_display_freshness_checked_at_utc := NULL::timestamptz;
    END;
    v_display_freshness_result_hash := to_jsonb(v_batch) ->> 'freshness_result_hash';
    v_display_summary_version := 0;
    v_display_summary_updated_at_utc := NULL::timestamptz;
  END IF;

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash,
    batch_signal.last_changed_at_utc
  INTO
    v_batch_signal_version,
    v_batch_payment_status_version,
    v_batch_correction_progress_version,
    v_batch_alert_version,
    v_batch_overview_version,
    v_batch_last_status_hash,
    v_batch_last_alert_hash,
    v_batch_signal_last_changed_at_utc
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_batch_signal_version := 0;
    v_batch_payment_status_version := 0;
    v_batch_correction_progress_version := 0;
    v_batch_alert_version := 0;
    v_batch_overview_version := 0;
    v_batch_last_status_hash := NULL::text;
    v_batch_last_alert_hash := NULL::text;
    v_batch_signal_last_changed_at_utc := NULL::timestamptz;
  END IF;

  SELECT
    COALESCE(durable_candidate_summary.candidate_count, 0)::integer,
    COALESCE(durable_item_summary.item_count, 0)::integer,
    COALESCE(durable_breakdown_summary.item_breakdown_count, 0)::integer,
    COALESCE(durable_snapshot_summary.timesheet_snapshot_count, 0)::integer,
    COALESCE(durable_transfer_summary.transfer_count, 0)::integer,
    ROUND(COALESCE(durable_item_summary.total_payable, 0), 2)::numeric,
    ROUND(COALESCE(durable_transfer_summary.transfer_amount_total, 0), 2)::numeric,
    COALESCE(durable_transfer_summary.sent_confirmed_count, 0)::integer,
    ROUND(COALESCE(durable_transfer_summary.sent_confirmed_amount, 0), 2)::numeric,
    COALESCE(durable_transfer_summary.pending_submitted_count, 0)::integer,
    ROUND(COALESCE(durable_transfer_summary.pending_submitted_amount, 0), 2)::numeric,
    COALESCE(durable_transfer_summary.failed_returned_count, 0)::integer,
    ROUND(COALESCE(durable_transfer_summary.failed_returned_amount, 0), 2)::numeric,
    COALESCE(durable_transfer_summary.check_required_count, 0)::integer,
    ROUND(COALESCE(durable_transfer_summary.check_required_amount, 0), 2)::numeric,
    COALESCE(durable_transfer_summary.not_sent_count, 0)::integer,
    ROUND(COALESCE(durable_transfer_summary.not_sent_amount, 0), 2)::numeric
  INTO
    v_durable_candidate_count,
    v_durable_item_count,
    v_durable_item_breakdown_count,
    v_durable_timesheet_snapshot_count,
    v_durable_transfer_count,
    v_durable_total_payable,
    v_durable_total_bank_out,
    v_durable_sent_confirmed_count,
    v_durable_sent_confirmed_amount,
    v_durable_pending_submitted_count,
    v_durable_pending_submitted_amount,
    v_durable_failed_returned_count,
    v_durable_failed_returned_amount,
    v_durable_check_required_count,
    v_durable_check_required_amount,
    v_durable_not_sent_count,
    v_durable_not_sent_amount
  FROM (
    SELECT COUNT(*)::integer AS candidate_count
    FROM public.pay_batch_candidates AS durable_candidate_row
    WHERE durable_candidate_row.pay_batch_id = p_pay_batch_id
  ) AS durable_candidate_summary
  CROSS JOIN (
    SELECT
      COUNT(*) FILTER (WHERE COALESCE(durable_item_row.is_voided, false) = false)::integer AS item_count,
      ROUND(
        COALESCE(
          SUM(
            COALESCE(
              durable_item_row.frozen_target_amount_inc_vat,
              durable_item_row.amount_inc_vat,
              durable_item_row.frozen_target_amount_ex_vat,
              durable_item_row.amount_ex_vat,
              0
            )
          ) FILTER (WHERE COALESCE(durable_item_row.is_voided, false) = false),
          0
        ),
        2
      )::numeric AS total_payable
    FROM public.pay_batch_candidates AS durable_candidate_for_item
    JOIN public.pay_batch_items AS durable_item_row
      ON durable_item_row.pay_batch_candidate_id = durable_candidate_for_item.id
    WHERE durable_candidate_for_item.pay_batch_id = p_pay_batch_id
  ) AS durable_item_summary
  CROSS JOIN (
    SELECT COUNT(*)::integer AS item_breakdown_count
    FROM public.pay_batch_item_breakdowns AS durable_breakdown_row
    JOIN public.pay_batch_items AS durable_breakdown_item_row
      ON durable_breakdown_item_row.id = durable_breakdown_row.pay_batch_item_id
    JOIN public.pay_batch_candidates AS durable_breakdown_candidate_row
      ON durable_breakdown_candidate_row.id = durable_breakdown_item_row.pay_batch_candidate_id
    WHERE durable_breakdown_candidate_row.pay_batch_id = p_pay_batch_id
  ) AS durable_breakdown_summary
  CROSS JOIN (
    SELECT COUNT(*)::integer AS timesheet_snapshot_count
    FROM public.pay_batch_timesheet_snapshots AS durable_snapshot_row
    WHERE durable_snapshot_row.pay_batch_id = p_pay_batch_id
  ) AS durable_snapshot_summary
  CROSS JOIN (
    SELECT
      COUNT(*)::integer AS transfer_count,
      ROUND(COALESCE(SUM(COALESCE(classified_transfer_rows.transfer_amount, 0)), 0), 2)::numeric AS transfer_amount_total,
      COUNT(*) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'SENT_CONFIRMED')::integer AS sent_confirmed_count,
      ROUND(COALESCE(SUM(classified_transfer_rows.transfer_amount) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'SENT_CONFIRMED'), 0), 2)::numeric AS sent_confirmed_amount,
      COUNT(*) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'PENDING_SUBMITTED')::integer AS pending_submitted_count,
      ROUND(COALESCE(SUM(classified_transfer_rows.transfer_amount) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'PENDING_SUBMITTED'), 0), 2)::numeric AS pending_submitted_amount,
      COUNT(*) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'FAILED_RETURNED')::integer AS failed_returned_count,
      ROUND(COALESCE(SUM(classified_transfer_rows.transfer_amount) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'FAILED_RETURNED'), 0), 2)::numeric AS failed_returned_amount,
      COUNT(*) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'CHECK_REQUIRED')::integer AS check_required_count,
      ROUND(COALESCE(SUM(classified_transfer_rows.transfer_amount) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'CHECK_REQUIRED'), 0), 2)::numeric AS check_required_amount,
      COUNT(*) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'NOT_SENT')::integer AS not_sent_count,
      ROUND(COALESCE(SUM(classified_transfer_rows.transfer_amount) FILTER (WHERE classified_transfer_rows.transfer_bucket = 'NOT_SENT'), 0), 2)::numeric AS not_sent_amount
    FROM (
      SELECT
        durable_transfer_row.id AS pay_bank_transfer_id,
        COALESCE(durable_transfer_row.amount, 0)::numeric AS transfer_amount,
        CASE
          WHEN UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) IN (
            'PAID', 'COMPLETED', 'COMPLETE', 'SETTLED', 'BANK_CONFIRMED', 'CONFIRMED', 'COMMITTED', 'SUCCESS', 'SUCCEEDED'
          )
          OR UPPER(BTRIM(COALESCE(durable_transfer_row.rail_state, ''))) IN (
            'PAID', 'COMPLETED', 'COMPLETE', 'SETTLED', 'BANK_CONFIRMED', 'CONFIRMED', 'COMMITTED', 'SUCCESS', 'SUCCEEDED'
          )
          OR (
            durable_transfer_row.completed_at_utc IS NOT NULL
            AND UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) NOT IN (
              'FAILED', 'REJECTED', 'DECLINED', 'RETURNED', 'CANCELLED', 'CANCELED', 'VOIDED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT'
            )
            AND UPPER(BTRIM(COALESCE(durable_transfer_row.rail_state, ''))) NOT IN (
              'FAILED', 'REJECTED', 'DECLINED', 'RETURNED', 'CANCELLED', 'CANCELED', 'VOIDED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT'
            )
          ) THEN 'SENT_CONFIRMED'
          WHEN UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) IN (
            'FAILED', 'REJECTED', 'DECLINED', 'RETURNED', 'CANCELLED', 'CANCELED', 'VOIDED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT'
          )
          OR UPPER(BTRIM(COALESCE(durable_transfer_row.rail_state, ''))) IN (
            'FAILED', 'REJECTED', 'DECLINED', 'RETURNED', 'CANCELLED', 'CANCELED', 'VOIDED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT'
          ) THEN 'FAILED_RETURNED'
          WHEN UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) IN (
            'UNKNOWN', 'UNCERTAIN', 'REVIEW_REQUIRED', 'AMBIGUOUS', 'TIMEOUT', 'TIMED_OUT'
          )
          OR UPPER(BTRIM(COALESCE(durable_transfer_row.rail_state, ''))) IN (
            'UNKNOWN', 'UNCERTAIN', 'REVIEW_REQUIRED', 'AMBIGUOUS', 'TIMEOUT', 'TIMED_OUT'
          ) THEN 'CHECK_REQUIRED'
          WHEN NULLIF(BTRIM(COALESCE(durable_transfer_row.rail_tx_id, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) IN (
              'PENDING', 'PROCESSING', 'SUBMITTED', 'ACCEPTED', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'WAITING_BANK_CONFIRM', 'SUBMITTED_NOT_COMMITTED'
            )
            OR UPPER(BTRIM(COALESCE(durable_transfer_row.rail_state, ''))) IN (
              'PENDING', 'PROCESSING', 'SUBMITTED', 'ACCEPTED', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'WAITING_BANK_CONFIRM', 'SUBMITTED_NOT_COMMITTED'
            )
            OR POSITION('PROVIDER_SUBMISSION_ACCEPTED' IN UPPER(COALESCE(durable_transfer_row.rail_meta_json::text, ''))) > 0
          THEN 'PENDING_SUBMITTED'
          WHEN NULLIF(BTRIM(COALESCE(durable_transfer_row.request_id, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(durable_transfer_row.status, ''))) IN (
              'LOCAL', 'READY', 'DRAFT', 'CREATED', 'PREPARED', 'AUTHORISED', 'AUTHORIZED', 'NOT_SUBMITTED', 'PENDING_AUTH'
            )
          THEN 'NOT_SENT'
          ELSE 'CHECK_REQUIRED'
        END AS transfer_bucket
      FROM public.pay_bank_transfers AS durable_transfer_row
      WHERE durable_transfer_row.pay_batch_id = p_pay_batch_id
    ) AS classified_transfer_rows
  ) AS durable_transfer_summary;

  v_batch_status_raw := v_batch.status;
  v_pending_bank_outcome_count := COALESCE(v_durable_pending_submitted_count, 0);
  v_unknown_bank_outcome_count := COALESCE(v_durable_check_required_count, 0);
  v_terminal_success_payment_count := COALESCE(v_durable_sent_confirmed_count, 0);
  v_terminal_failed_payment_count := COALESCE(v_durable_failed_returned_count, 0);
  v_batch_terminal_with_failed_payments := UPPER(BTRIM(COALESCE(v_batch.status::text, ''))) = 'FAILED';
  v_batch_status_label := public._pay_batch_status_display_label(
    v_batch.status,
    v_pending_bank_outcome_count,
    v_unknown_bank_outcome_count
  );
  v_settlement_required := (
    v_batch_status_upper = 'WAITING_BANK_CONFIRM'
    AND COALESCE(v_durable_transfer_count, 0) > 0
    AND COALESCE(v_pending_bank_outcome_count, 0) = 0
    AND COALESCE(v_unknown_bank_outcome_count, 0) = 0
    AND COALESCE(v_durable_not_sent_count, 0) = 0
    AND (COALESCE(v_terminal_success_payment_count, 0) + COALESCE(v_terminal_failed_payment_count, 0)) > 0
  );

  v_durable_counts :=
    jsonb_build_object(
      'candidate_count', COALESCE(v_durable_candidate_count, 0),
      'item_count', COALESCE(v_durable_item_count, 0),
      'item_breakdown_count', COALESCE(v_durable_item_breakdown_count, 0),
      'timesheet_snapshot_count', COALESCE(v_durable_timesheet_snapshot_count, 0),
      'transfer_count', COALESCE(v_durable_transfer_count, 0),
      'total_payable', COALESCE(v_durable_total_payable, 0)
    )
    || jsonb_build_object(
      'total_bank_out', COALESCE(v_durable_total_bank_out, 0),
      'batch_status_raw', v_batch_status_raw,
      'batch_status_label', v_batch_status_label,
      'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
      'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
      'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
      'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
      'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
      'settlement_required', COALESCE(v_settlement_required, false),
      'settlement_nudge_recommended', COALESCE(v_settlement_required, false),
      'source', 'durable_batch_artefact_counts',
      'validated_at_utc', now()::text
    );

  v_payment_status_buckets :=
    jsonb_build_object(
      'sent_confirmed_count', COALESCE(v_durable_sent_confirmed_count, 0),
      'sent_confirmed_amount', COALESCE(v_durable_sent_confirmed_amount, 0),
      'pending_submitted_count', COALESCE(v_durable_pending_submitted_count, 0),
      'pending_submitted_amount', COALESCE(v_durable_pending_submitted_amount, 0),
      'failed_returned_count', COALESCE(v_durable_failed_returned_count, 0),
      'failed_returned_amount', COALESCE(v_durable_failed_returned_amount, 0)
    )
    || jsonb_build_object(
      'check_required_count', COALESCE(v_durable_check_required_count, 0),
      'check_required_amount', COALESCE(v_durable_check_required_amount, 0),
      'not_sent_count', COALESCE(v_durable_not_sent_count, 0),
      'not_sent_amount', COALESCE(v_durable_not_sent_amount, 0),
      'classification_source', 'pay_bank_transfers_durable_status'
    );

  v_display_summary_stale_before_refresh := (
    v_display_summary_found IS NOT TRUE
    OR LOWER(BTRIM(COALESCE(v_display_stale_summary_json ->> 'summary_refresh_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (COALESCE(v_display_candidate_count, 0) = 0 AND COALESCE(v_durable_candidate_count, 0) > 0)
    OR (COALESCE(v_display_item_count, 0) = 0 AND COALESCE(v_durable_item_count, 0) > 0)
    OR (COALESCE(v_display_transfer_count, 0) = 0 AND COALESCE(v_durable_transfer_count, 0) > 0)
    OR (COALESCE(v_display_total_bank_out, 0) <> 0 AND COALESCE(v_display_transfer_count, 0) = 0)
    OR (v_batch_signal_last_changed_at_utc IS NOT NULL AND (v_display_summary_updated_at_utc IS NULL OR v_display_summary_updated_at_utc < v_batch_signal_last_changed_at_utc))
  );

  v_display_summary_stale := v_display_summary_stale_before_refresh;

  IF v_display_summary_stale_before_refresh IS TRUE THEN
    BEGIN
      PERFORM public.pay_batch_display_summary_refresh(p_pay_batch_id);

      SELECT
        refreshed_display_summary.batch_status,
        refreshed_display_summary.batch_kind,
        COALESCE(refreshed_display_summary.candidate_count, 0),
        COALESCE(refreshed_display_summary.item_count, 0),
        COALESCE(refreshed_display_summary.transfer_count, 0),
        COALESCE(refreshed_display_summary.total_payable, 0),
        COALESCE(refreshed_display_summary.total_bank_out, 0),
        refreshed_display_summary.execution_commit_state,
        refreshed_display_summary.rail_provider_label,
        refreshed_display_summary.rail_env_label,
        COALESCE(refreshed_display_summary.issue_summary_counts, '{}'::jsonb),
        refreshed_display_summary.latest_operation_id,
        refreshed_display_summary.latest_operation_status,
        refreshed_display_summary.latest_operation_phase,
        refreshed_display_summary.display_label,
        COALESCE(refreshed_display_summary.stale_summary_json, '{}'::jsonb),
        refreshed_display_summary.freshness_validation_status,
        refreshed_display_summary.freshness_checked_at_utc,
        refreshed_display_summary.freshness_result_hash,
        COALESCE(refreshed_display_summary.summary_version, 0),
        refreshed_display_summary.updated_at_utc
      INTO
        v_display_batch_status,
        v_display_batch_kind,
        v_display_candidate_count,
        v_display_item_count,
        v_display_transfer_count,
        v_display_total_payable,
        v_display_total_bank_out,
        v_display_execution_commit_state,
        v_display_rail_provider_label,
        v_display_rail_env_label,
        v_display_issue_summary_counts,
        v_display_latest_operation_id,
        v_display_latest_operation_status,
        v_display_latest_operation_phase,
        v_display_label,
        v_display_stale_summary_json,
        v_display_freshness_validation_status,
        v_display_freshness_checked_at_utc,
        v_display_freshness_result_hash,
        v_display_summary_version,
        v_display_summary_updated_at_utc
      FROM public.pay_batch_display_summary AS refreshed_display_summary
      WHERE refreshed_display_summary.pay_batch_id = p_pay_batch_id;

      v_display_summary_found := FOUND;
      v_display_summary_stale := (
        v_display_summary_found IS NOT TRUE
        OR LOWER(BTRIM(COALESCE(v_display_stale_summary_json ->> 'summary_refresh_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR (COALESCE(v_display_candidate_count, 0) = 0 AND COALESCE(v_durable_candidate_count, 0) > 0)
        OR (COALESCE(v_display_item_count, 0) = 0 AND COALESCE(v_durable_item_count, 0) > 0)
        OR (COALESCE(v_display_transfer_count, 0) = 0 AND COALESCE(v_durable_transfer_count, 0) > 0)
        OR (COALESCE(v_display_total_bank_out, 0) <> 0 AND COALESCE(v_display_transfer_count, 0) = 0)
      );
      v_display_summary_repaired := (v_display_summary_found IS TRUE AND v_display_summary_stale IS NOT TRUE);
    EXCEPTION WHEN OTHERS THEN
      v_summary_refresh_failed := true;
      v_summary_refresh_error := SQLERRM;
      v_display_summary_stale := true;
    END;
  END IF;

  IF v_display_summary_stale IS TRUE THEN
    v_display_candidate_count := COALESCE(v_durable_candidate_count, 0);
    v_display_item_count := COALESCE(v_durable_item_count, 0);
    v_display_transfer_count := COALESCE(v_durable_transfer_count, 0);
    v_display_total_payable := COALESCE(v_durable_total_payable, 0);
    v_display_total_bank_out := COALESCE(v_durable_total_bank_out, v_batch.total_bank_out, 0);
  END IF;

  v_item_breakdown_count := COALESCE(v_durable_item_breakdown_count, 0);
  v_empty_shell := (
    COALESCE(v_durable_candidate_count, 0) = 0
    AND COALESCE(v_durable_item_count, 0) = 0
    AND COALESCE(v_durable_item_breakdown_count, 0) = 0
    AND COALESCE(v_durable_timesheet_snapshot_count, 0) = 0
    AND COALESCE(v_durable_transfer_count, 0) = 0
  );

  IF v_empty_shell IS TRUE THEN
    v_empty_shell_kind := 'DRAFT_NO_DURABLE_CONTENT';
    v_empty_shell_message := 'This draft payment batch contains no candidates, no payable items and no bank transfers.';
  END IF;

  v_display_stale_summary_json :=
    COALESCE(v_display_stale_summary_json, '{}'::jsonb)
    || jsonb_build_object(
      'summary_refresh_required', COALESCE(v_display_summary_stale, false),
      'display_summary_stale_before_refresh', COALESCE(v_display_summary_stale_before_refresh, false),
      'display_summary_repaired', COALESCE(v_display_summary_repaired, false),
      'summary_refresh_failed', COALESCE(v_summary_refresh_failed, false),
      'summary_source', CASE WHEN v_display_summary_stale IS TRUE THEN 'durable_validation_fallback' ELSE 'display_summary_validated' END
    )
    || jsonb_build_object(
      'durable_counts', COALESCE(v_durable_counts, '{}'::jsonb),
      'payment_status_buckets', COALESCE(v_payment_status_buckets, '{}'::jsonb),
      'empty_shell', COALESCE(v_empty_shell, false),
      'empty_shell_kind', v_empty_shell_kind,
      'validated_at_utc', now()::text
    );

  v_display_issue_summary_counts :=
    COALESCE(v_display_issue_summary_counts, '{}'::jsonb)
    || COALESCE(v_durable_counts, '{}'::jsonb)
    || COALESCE(v_payment_status_buckets, '{}'::jsonb)
    || jsonb_build_object(
      'display_summary_stale', COALESCE(v_display_summary_stale, false),
      'display_summary_stale_before_refresh', COALESCE(v_display_summary_stale_before_refresh, false),
      'display_summary_repaired', COALESCE(v_display_summary_repaired, false),
      'summary_refresh_failed', COALESCE(v_summary_refresh_failed, false),
      'empty_shell', COALESCE(v_empty_shell, false)
    )
    || jsonb_build_object(
      'batch_status_raw', v_batch_status_raw,
      'batch_status_label', v_batch_status_label,
      'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
      'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
      'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
      'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
      'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
      'settlement_required', COALESCE(v_settlement_required, false),
      'settlement_nudge_recommended', COALESCE(v_settlement_required, false)
    );

  v_candidate_count := COALESCE(v_display_candidate_count, 0);
  v_item_count := COALESCE(v_display_item_count, 0);
  v_transfer_count := COALESCE(v_display_transfer_count, 0);
  v_total_amount := COALESCE(v_display_total_bank_out, v_display_total_payable, v_batch.total_bank_out, 0);
  v_batch_kind := COALESCE(NULLIF(BTRIM(v_display_batch_kind), ''), NULLIF(BTRIM(v_batch.batch_kind_fixed), ''));
  v_pay_channels_present := CASE
    WHEN UPPER(COALESCE(v_batch_kind, '')) IN ('PAYE','UMBRELLA') THEN jsonb_build_array(UPPER(v_batch_kind))
    WHEN UPPER(COALESCE(v_batch_kind, '')) = 'MIXED' THEN jsonb_build_array('PAYE','UMBRELLA')
    ELSE '[]'::jsonb
  END;

  v_provider_environment_summary := jsonb_build_object(
    'rail_provider_snapshot', COALESCE(v_display_rail_provider_label, v_batch.rail_provider_snapshot),
    'rail_env_snapshot', COALESCE(v_display_rail_env_label, v_batch.rail_env_snapshot),
    'provider_normalized', v_provider_normalized,
    'provider_known', v_provider_known,
    'funding_account_ref', v_batch.funding_account_ref
  );

  v_large_batch := (
    COALESCE(v_display_candidate_count, v_durable_candidate_count, 0) > 100
    OR COALESCE(v_display_item_count, v_durable_item_count, 0) > 250
    OR COALESCE(v_display_transfer_count, v_durable_transfer_count, 0) > 100
  );

  SELECT COALESCE(jsonb_agg(large_reason.reason ORDER BY large_reason.reason), '[]'::jsonb)
  INTO v_large_batch_reasons
  FROM (
    SELECT 'candidate_count'::text AS reason WHERE COALESCE(v_display_candidate_count, v_durable_candidate_count, 0) > 100
    UNION ALL
    SELECT 'item_count'::text AS reason WHERE COALESCE(v_display_item_count, v_durable_item_count, 0) > 250
    UNION ALL
    SELECT 'transfer_count'::text AS reason WHERE COALESCE(v_display_transfer_count, v_durable_transfer_count, 0) > 100
  ) AS large_reason;

  v_bootstrap_only := (
    v_detail_mode = 'BOOTSTRAP_ONLY'
    OR v_detail_mode = 'AUTO'
    OR (v_detail_mode = 'FULL' AND v_large_batch = true)
  );

  IF v_bootstrap_only THEN
    v_bootstrap_detail_mode_applied := 'BOOTSTRAP_ONLY';

    RETURN
      jsonb_build_object(
        'ok', true,
        'bootstrap_only', true,
        'detail_mode_requested', v_detail_mode,
        'detail_mode_applied', v_bootstrap_detail_mode_applied,
        'full_mode_downgraded_to_bootstrap', v_detail_mode = 'FULL' AND v_large_batch = true,
        'large_batch', COALESCE(v_large_batch, false),
        'large_batch_reasons', COALESCE(v_large_batch_reasons, '[]'::jsonb),
        'available_sections', v_available_sections,
        'recommended_page_size', v_effective_page_size,
        'id', v_batch.id::text,
        'pay_batch_id', v_batch.id::text,
        'status', v_batch.status,
        'db_status', v_batch.status,
        'batch_status_raw', v_batch_status_raw,
        'batch_status_label', v_batch_status_label,
        'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
        'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
        'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
        'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
        'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
        'settlement_required', COALESCE(v_settlement_required, false),
        'settlement_nudge_recommended', COALESCE(v_settlement_required, false),
        'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
        'batch_kind', v_batch_kind,
        'batch_kind_fixed', v_batch.batch_kind_fixed,
        'pay_channel', v_batch_kind,
        'pay_channels_present', COALESCE(v_pay_channels_present, '[]'::jsonb),
        'execution_commit_state', COALESCE(v_display_execution_commit_state, v_batch.execution_commit_state)
      )
      || jsonb_build_object(
        'candidate_count', COALESCE(v_display_candidate_count, 0),
        'item_count', COALESCE(v_display_item_count, 0),
        'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
        'timesheet_snapshot_count', COALESCE(v_durable_timesheet_snapshot_count, 0),
        'transfer_count', COALESCE(v_display_transfer_count, 0),
        'total_amount', COALESCE(v_total_amount, 0),
        'total_bank_out', COALESCE(v_display_total_bank_out, v_batch.total_bank_out, 0),
        'total_payable', COALESCE(v_display_total_payable, 0),
        'display_label', v_display_label,
        'summary_version', COALESCE(v_display_summary_version, 0),
        'summary_updated_at_utc', CASE WHEN v_display_summary_updated_at_utc IS NULL THEN NULL::text ELSE v_display_summary_updated_at_utc::text END,
        'issue_summary_counts', COALESCE(v_display_issue_summary_counts, '{}'::jsonb),
        'stale_summary_json', COALESCE(v_display_stale_summary_json, '{}'::jsonb),
        'durable_counts', COALESCE(v_durable_counts, '{}'::jsonb),
        'payment_status_buckets', COALESCE(v_payment_status_buckets, '{}'::jsonb),
        'display_summary_stale_before_refresh', COALESCE(v_display_summary_stale_before_refresh, false),
        'display_summary_repaired', COALESCE(v_display_summary_repaired, false),
        'display_summary_stale', COALESCE(v_display_summary_stale, false),
        'summary_refresh_failed', COALESCE(v_summary_refresh_failed, false),
        'empty_shell', COALESCE(v_empty_shell, false),
        'empty_shell_kind', v_empty_shell_kind,
        'empty_shell_message', v_empty_shell_message,
        'provider_environment_summary', v_provider_environment_summary,
        'latest_operation_id', CASE WHEN v_display_latest_operation_id IS NULL THEN NULL::text ELSE v_display_latest_operation_id::text END,
        'latest_operation_status', v_display_latest_operation_status,
        'latest_operation_phase', v_display_latest_operation_phase,
        'active_operation', CASE
          WHEN v_display_latest_operation_id IS NULL THEN NULL::jsonb
          ELSE jsonb_strip_nulls(jsonb_build_object(
            'id', v_display_latest_operation_id::text,
            'operation_id', v_display_latest_operation_id::text,
            'status', v_display_latest_operation_status,
            'phase', v_display_latest_operation_phase
          ))
        END
      )
      || jsonb_build_object(
        'sent_confirmed_count', COALESCE(v_durable_sent_confirmed_count, 0),
        'sent_confirmed_amount', COALESCE(v_durable_sent_confirmed_amount, 0),
        'pending_submitted_count', COALESCE(v_durable_pending_submitted_count, 0),
        'pending_submitted_amount', COALESCE(v_durable_pending_submitted_amount, 0),
        'failed_returned_count', COALESCE(v_durable_failed_returned_count, 0),
        'failed_returned_amount', COALESCE(v_durable_failed_returned_amount, 0)
      )
      || jsonb_build_object(
        'check_required_count', COALESCE(v_durable_check_required_count, 0),
        'check_required_amount', COALESCE(v_durable_check_required_amount, 0),
        'not_sent_count', COALESCE(v_durable_not_sent_count, 0),
        'not_sent_amount', COALESCE(v_durable_not_sent_amount, 0)
      )
      || jsonb_build_object(
        'live_signal_version', COALESCE(v_batch_signal_version, 0),
        'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
        'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
        'alert_version', COALESCE(v_batch_alert_version, 0),
        'overview_version', COALESCE(v_batch_overview_version, 0),
        'last_status_hash', v_batch_last_status_hash,
        'last_alert_hash', v_batch_last_alert_hash,
        'freshness', jsonb_build_object(
          'freshness_validation_status', COALESCE(v_display_freshness_validation_status, to_jsonb(v_batch) ->> 'freshness_validation_status'),
          'freshness_checked_at_utc', COALESCE(CASE WHEN v_display_freshness_checked_at_utc IS NULL THEN NULL::text ELSE v_display_freshness_checked_at_utc::text END, to_jsonb(v_batch) ->> 'freshness_checked_at_utc'),
          'freshness_result_hash', COALESCE(v_display_freshness_result_hash, to_jsonb(v_batch) ->> 'freshness_result_hash'),
          'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
          'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id'
        ),
        'batch', jsonb_build_object(
          'id', v_batch.id::text,
          'bootstrap_only', true,
          'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
          'status', v_batch.status,
          'db_status', v_batch.status,
          'batch_status_raw', v_batch_status_raw,
          'batch_status_label', v_batch_status_label,
          'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
          'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
          'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
          'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
          'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
          'settlement_required', COALESCE(v_settlement_required, false),
          'settlement_nudge_recommended', COALESCE(v_settlement_required, false),
          'batch_kind', v_batch_kind,
          'batch_kind_fixed', v_batch.batch_kind_fixed,
          'pay_channel', v_batch_kind,
          'pay_channels_present', COALESCE(v_pay_channels_present, '[]'::jsonb),
          'execution_commit_state', COALESCE(v_display_execution_commit_state, v_batch.execution_commit_state),
          'created_at_utc', v_batch.created_at_utc,
          'created_by_user_id', CASE WHEN v_batch.created_by_user_id IS NULL THEN NULL ELSE v_batch.created_by_user_id::text END,
          'candidate_count', COALESCE(v_display_candidate_count, 0),
          'item_count', COALESCE(v_display_item_count, 0),
          'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
          'timesheet_snapshot_count', COALESCE(v_durable_timesheet_snapshot_count, 0),
          'transfer_count', COALESCE(v_display_transfer_count, 0),
          'total_payable', COALESCE(v_display_total_payable, 0),
          'total_bank_out', COALESCE(v_display_total_bank_out, v_batch.total_bank_out, 0),
          'durable_counts', COALESCE(v_durable_counts, '{}'::jsonb),
          'payment_status_buckets', COALESCE(v_payment_status_buckets, '{}'::jsonb),
          'empty_shell', COALESCE(v_empty_shell, false),
          'empty_shell_kind', v_empty_shell_kind,
          'empty_shell_message', v_empty_shell_message,
          'summary_version', COALESCE(v_display_summary_version, 0),
          'live_signal_version', COALESCE(v_batch_signal_version, 0),
          'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
          'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
          'alert_version', COALESCE(v_batch_alert_version, 0),
          'overview_version', COALESCE(v_batch_overview_version, 0)
        ),
        'candidates', NULL::jsonb,
        'items', NULL::jsonb,
        'transfers', NULL::jsonb,
        'diagnostics_included', false,
        'alerts_included', false,
        'correction_summary_included', false
      );
  END IF;

  -- ✅ NEW: derive batch kind + channels from items (excludes DEBT_CREATED)
  select
    case
      when ch.channels is null then null
      when array_position(ch.channels,'PAYE') is not null and array_position(ch.channels,'UMBRELLA') is not null then 'MIXED'
      when array_position(ch.channels,'PAYE') is not null then 'PAYE'
      when array_position(ch.channels,'UMBRELLA') is not null then 'UMBRELLA'
      else null
    end as batch_kind,
    coalesce(to_jsonb(ch.channels), '[]'::jsonb) as channels_json
  into
    v_batch_kind,
    v_pay_channels_present
  from (
    select
      array_agg(distinct upper(coalesce(pbi.pay_channel::text,'')) order by upper(coalesce(pbi.pay_channel::text,'')))
        filter (where upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA')) as channels
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ) ch;


  v_detail_mode := upper(btrim(coalesce(p_detail_mode, 'AUTO')));
  IF v_detail_mode NOT IN ('AUTO','FULL','BOOTSTRAP_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_INVALID_DETAIL_MODE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_INVALID_DETAIL_MODE',
              'detail_mode', p_detail_mode,
              'allowed_modes', jsonb_build_array('AUTO','FULL','BOOTSTRAP_ONLY')
            )::text;
  END IF;

  v_effective_page_size := LEAST(250, GREATEST(25, COALESCE(p_recommended_page_size, 100)));

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.pay_batch_candidates AS candidate_count_scope
  WHERE candidate_count_scope.pay_batch_id = p_pay_batch_id;

  WITH item_scope AS (
    SELECT
      pbc_count.id AS pay_batch_candidate_id,
      pbc_count.candidate_id,
      pbi_count.id AS pay_batch_item_id,
      pbi_count.item_type,
      pbi_count.amount_ex_vat,
      pbi_count.amount_inc_vat,
      COALESCE(pbi_count.is_voided, false) AS is_voided,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS precancel_items
        WHERE precancel_items.pay_batch_item_id = pbi_count.id
          AND precancel_items.status = 'APPLIED'
          AND precancel_items.correction_item_kind = 'PRE_BANK_CANCEL'
      ) AS has_precancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS unwind_items
        WHERE unwind_items.pay_batch_item_id = pbi_count.id
          AND unwind_items.status = 'APPLIED'
          AND unwind_items.correction_item_kind = 'NO_MONEY_UNWIND'
      ) AS has_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reversal_items
        WHERE reversal_items.pay_batch_item_id = pbi_count.id
          AND reversal_items.status = 'APPLIED'
          AND reversal_items.correction_item_kind = 'SETTLED_REVERSAL'
      ) AS has_settled_reversal
    FROM public.pay_batch_candidates AS pbc_count
    LEFT JOIN public.pay_batch_items AS pbi_count
      ON pbi_count.pay_batch_candidate_id = pbc_count.id
    WHERE pbc_count.pay_batch_id = p_pay_batch_id
  ), candidate_rollup AS (
    SELECT
      item_scope.pay_batch_candidate_id,
      item_scope.candidate_id,
      COUNT(item_scope.pay_batch_item_id)::integer AS total_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.pay_batch_item_id IS NOT NULL
          AND COALESCE(item_scope.is_voided, false) = false
          AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
      )::integer AS active_effective_item_count,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_inc_vat,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal
      )::integer AS corrected_item_count
    FROM item_scope
    GROUP BY item_scope.pay_batch_candidate_id, item_scope.candidate_id
  )
  SELECT
    COALESCE(SUM(COALESCE(candidate_rollup.total_item_count, 0)), 0)::integer,
    COALESCE(SUM(COALESCE(candidate_rollup.active_effective_item_count, 0)), 0)::integer,
    ROUND(COALESCE(SUM(COALESCE(candidate_rollup.active_effective_amount_ex_vat, 0)), 0), 2)::numeric,
    ROUND(COALESCE(SUM(COALESCE(candidate_rollup.active_effective_amount_inc_vat, 0)), 0), 2)::numeric,
    COUNT(*) FILTER (WHERE COALESCE(candidate_rollup.corrected_item_count, 0) > 0)::integer
  INTO
    v_item_count,
    v_active_effective_item_count,
    v_active_effective_amount_ex_vat,
    v_active_effective_amount_inc_vat,
    v_payment_issue_candidate_count
  FROM candidate_rollup;

  SELECT COUNT(*)::integer
  INTO v_item_breakdown_count
  FROM public.pay_batch_item_breakdowns AS breakdown_count_scope
  JOIN public.pay_batch_items AS item_count_scope
    ON item_count_scope.id = breakdown_count_scope.pay_batch_item_id
  JOIN public.pay_batch_candidates AS candidate_count_scope
    ON candidate_count_scope.id = item_count_scope.pay_batch_candidate_id
  WHERE candidate_count_scope.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_transfer_count
  FROM public.pay_bank_transfers AS transfer_count_scope
  WHERE transfer_count_scope.pay_batch_id = p_pay_batch_id;

  -- Use counts-only evidence for the summary/bootstrap path so large batch open
  -- does not build evidence samples or event-detail arrays. Full mode refreshes
  -- v_submission_evidence later with p_counts_only = false before detailed
  -- legacy funds-check/evidence payload construction.
  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      'ALL'::text,
      NULL::uuid,
      true,
      'CURRENT_PAYMENT_STATUS'
    ) AS classification_row
  ), classified_rows_with_sample AS (
    SELECT
      classified_rows.*,
      row_number() OVER (
        ORDER BY
          CASE
            WHEN classified_rows.evidence_classification IN ('local_only_evidence', 'attempted_but_unproven', 'ambiguous', 'failed', 'pending', 'scope_without_transfer') THEN 0
            ELSE 1
          END,
          classified_rows.pay_bank_transfer_id NULLS LAST,
          classified_rows.scope_id NULLS LAST
      ) AS evidence_sample_ordinality
    FROM classified_rows
  ), evidence_counts AS (
    SELECT
      count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer AS transfer_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'provider_evidence_present')::integer AS provider_submitted_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'local_only_evidence')::integer AS local_only_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'failed' OR classified_rows.is_failed_or_blocked IS TRUE)::integer AS failed_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'ambiguous' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer AS ambiguous_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS attempted_but_unproven_count,
      count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer AS provider_attempt_without_external_id_count,
      count(*) FILTER (
        WHERE classified_rows.evidence_classification = 'ambiguous'
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS requires_provider_poll_count,
      count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer AS committed_count,
      COALESCE(bool_or(
        EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
            AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        )
      ), false) AS has_rail_tx_id,
      COALESCE(bool_or(classified_rows.has_local_prepare_identity IS TRUE), false) AS has_local_generated_request_identity,
      COALESCE(bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE), false) AS has_external_submission_evidence,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_count,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_transfer_count,
      count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer AS unattempted_submit_eligible_count,
      count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer AS safe_local_cleanup_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS provider_attempt_or_evidence_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
      )::integer AS provider_or_ambiguous_evidence_count,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND false), '[]'::jsonb) AS evidence_sample,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'evidence_classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_route_ready', classified_rows.has_route_ready,
          'has_local_prepare_identity', classified_rows.has_local_prepare_identity,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_failed_or_blocked', classified_rows.is_failed_or_blocked,
          'is_terminal_or_completed', classified_rows.is_terminal_or_completed,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND false), '[]'::jsonb) AS execution_classification_sample
    FROM classified_rows_with_sample AS classified_rows
  ), status_sets AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(status_item.status_value ORDER BY status_item.status_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.status, ''))) AS status_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.status, '')), '') IS NOT NULL
        ) AS status_item
      ), '[]'::jsonb) AS transfer_statuses,
      COALESCE((
        SELECT jsonb_agg(rail_state_item.rail_state_value ORDER BY rail_state_item.rail_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.rail_state, ''))) AS rail_state_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.rail_state, '')), '') IS NOT NULL
        ) AS rail_state_item
      ), '[]'::jsonb) AS transfer_rail_states,
      COALESCE((
        SELECT jsonb_agg(event_state_item.normalised_state_value ORDER BY event_state_item.normalised_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.normalised_state, ''))) AS normalised_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.normalised_state, '')), '') IS NOT NULL
        ) AS event_state_item
      ), '[]'::jsonb) AS event_normalised_states,
      COALESCE((
        SELECT jsonb_agg(provider_state_item.provider_state_value ORDER BY provider_state_item.provider_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.provider_state, ''))) AS provider_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.provider_state, '')), '') IS NOT NULL
        ) AS provider_state_item
      ), '[]'::jsonb) AS event_provider_states,
      (SELECT count(*)::integer FROM public.pay_bank_transfer_events AS event_row WHERE event_row.pay_batch_id = p_pay_batch_id) AS transfer_event_count
  ), prepared_counts AS (
    SELECT
      evidence_counts.*,
      status_sets.*,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_unattempted_submit_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) AS remaining_evidence_unresolved_count,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_submit_attempt_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) + COALESCE(evidence_counts.ambiguous_count, 0) + COALESCE(evidence_counts.attempted_but_unproven_count, 0) AS remaining_provider_evidence_required,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_provider_submission_required,
      (
        COALESCE(evidence_counts.transfer_count, 0) > 0
        AND COALESCE(evidence_counts.provider_submitted_count, 0) = COALESCE(evidence_counts.transfer_count, 0)
        AND COALESCE(evidence_counts.failed_count, 0) = 0
        AND COALESCE(evidence_counts.ambiguous_count, 0) = 0
        AND COALESCE(evidence_counts.local_only_count, 0) = 0
        AND COALESCE(evidence_counts.pending_count, 0) = 0
        AND COALESCE(evidence_counts.attempted_but_unproven_count, 0) = 0
      ) AS can_mark_submitted
    FROM evidence_counts
    CROSS JOIN status_sets
  )
  SELECT
    jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'counts_only', true,
      'transfer_count', COALESCE(prepared_counts.transfer_count, 0),
      'transfer_event_count', COALESCE(prepared_counts.transfer_event_count, 0),
      'has_transfer_events', COALESCE(prepared_counts.transfer_event_count, 0) > 0,
      'provider_submitted_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'provider_evidence_present_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'local_idempotency_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_evidence_count', COALESCE(prepared_counts.local_only_count, 0),
      'pending_count', COALESCE(prepared_counts.pending_count, 0),
      'failed_count', COALESCE(prepared_counts.failed_count, 0),
      'ambiguous_count', COALESCE(prepared_counts.ambiguous_count, 0),
      'attempted_but_unproven_count', COALESCE(prepared_counts.attempted_but_unproven_count, 0),
      'provider_attempt_without_external_id_count', COALESCE(prepared_counts.provider_attempt_without_external_id_count, 0)
    )
    || jsonb_build_object(
      'requires_provider_poll_count', COALESCE(prepared_counts.requires_provider_poll_count, 0),
      'authorisation_ready_count', COALESCE(prepared_counts.authorisation_ready_count, 0),
      'authorisation_ready_transfer_count', COALESCE(prepared_counts.authorisation_ready_transfer_count, 0),
      'unattempted_submit_eligible_count', COALESCE(prepared_counts.unattempted_submit_eligible_count, 0),
      'safe_local_cleanup_count', COALESCE(prepared_counts.safe_local_cleanup_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(prepared_counts.provider_attempt_or_evidence_count, 0),
      'provider_or_ambiguous_evidence_count', COALESCE(prepared_counts.provider_or_ambiguous_evidence_count, 0),
      'cancellable_local_auth_request_count', 0,
      'non_cancellable_auth_request_count', 0,
      'same_operation_active_auth_request_count', 0,
      'other_operation_active_auth_request_count', 0,
      'auth_request_provider_risk_count', 0,
      'auth_request_retry_blocker_count', 0,
      'remaining_submit_attempt_required', COALESCE(prepared_counts.remaining_submit_attempt_required, 0),
      'remaining_unattempted_submit_required', COALESCE(prepared_counts.remaining_unattempted_submit_required, 0),
      'remaining_evidence_unresolved_count', COALESCE(prepared_counts.remaining_evidence_unresolved_count, 0)
    )
    || jsonb_build_object(
      'remaining_submit_attempt_required_definition', 'unattempted_submit_eligible_count',
      'remaining_provider_evidence_required', COALESCE(prepared_counts.remaining_provider_evidence_required, 0),
      'remaining_provider_submission_required', COALESCE(prepared_counts.remaining_provider_submission_required, 0),
      'submission_count_semantics', jsonb_build_object(
        'remaining_submit_attempt_required', 'count of transfers currently eligible for an unattempted provider submit',
        'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
        'pending_count', 'evidence-level pending classification, not submit eligibility'
      ),
      'batch_can_be_marked_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_committed', COALESCE(prepared_counts.can_mark_submitted, false) AND COALESCE(prepared_counts.committed_count, 0) = COALESCE(prepared_counts.transfer_count, 0),
      'has_rail_tx_id', COALESCE(prepared_counts.has_rail_tx_id, false),
      'has_local_generated_request_identity', COALESCE(prepared_counts.has_local_generated_request_identity, false),
      'has_external_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'no_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) = false,
      'transfer_statuses', COALESCE(prepared_counts.transfer_statuses, '[]'::jsonb),
      'transfer_rail_states', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb),
      'event_normalised_states', COALESCE(prepared_counts.event_normalised_states, '[]'::jsonb),
      'event_provider_states', COALESCE(prepared_counts.event_provider_states, '[]'::jsonb)
    )
    || jsonb_build_object(
      'evidence_sample', CASE WHEN false THEN COALESCE(prepared_counts.evidence_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'execution_classification_sample', CASE WHEN false THEN COALESCE(prepared_counts.execution_classification_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'has_possible_provider_attempt_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_provider_attempt_request_or_idempotency_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_request_or_idempotency_reference', COALESCE(prepared_counts.local_only_count, 0) > 0 OR COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_submitted_state', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_processing_state', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb) ?| array['PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION'],
      'has_completed_state', COALESCE(prepared_counts.committed_count, 0) > 0,
      'has_failed_or_rejected_provider_state', COALESCE(prepared_counts.failed_count, 0) > 0,
      'has_unknown_or_timeout_state', COALESCE(prepared_counts.ambiguous_count, 0) > 0,
      'requires_provider_poll', COALESCE(prepared_counts.requires_provider_poll_count, 0) > 0,
      'requires_review', COALESCE(prepared_counts.ambiguous_count, 0) > 0 OR (COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0 AND COALESCE(prepared_counts.requires_provider_poll_count, 0) = 0),
      'has_provider_submission_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_payment_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transfer_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transaction_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_external_payment_reference', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'has_external_transfer_reference', COALESCE(prepared_counts.has_external_submission_evidence, false)
    )
  INTO v_submission_evidence
  FROM prepared_counts;
  v_provider_submitted_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'provider_submitted_count', '')::integer, 0);
  v_local_only_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'local_only_count', '')::integer, COALESCE(NULLIF(v_submission_evidence ->> 'local_idempotency_only_count', '')::integer, 0));
  v_pending_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'pending_count', '')::integer, 0);
  v_failed_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'failed_count', '')::integer, 0);
  v_ambiguous_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'ambiguous_count', '')::integer, 0);
  v_attempted_but_unproven_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'attempted_but_unproven_count', '')::integer, 0);
  v_has_external_submission_evidence := COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false);

  v_total_amount := COALESCE(v_batch.total_bank_out, v_active_effective_amount_inc_vat, v_active_effective_amount_ex_vat, 0);
  v_has_cloudtms_csv_export := (
    v_batch.bank_csv_export_json is not null
    and jsonb_typeof(v_batch.bank_csv_export_json) = 'object'
    and NULLIF(btrim(coalesce(v_batch.bank_csv_export_json ->> 'transfer_hash', '')), '') IS NOT NULL
  );

  v_can_create_bank_csv_file := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
  );
  v_can_start_standard_execution := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_provider_normalized <> 'CSV'
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );
  v_can_start_csv_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
    and v_has_cloudtms_csv_export = true
  );
  v_can_start_external_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );

  WITH settlement_status_counts AS (
    SELECT
      COALESCE(NULLIF(btrim(coalesce(settlement_candidate.settlement_status, '')), ''), 'UNKNOWN') AS settlement_status,
      COUNT(*)::integer AS status_count
    FROM public.pay_batch_candidates AS settlement_candidate
    WHERE settlement_candidate.pay_batch_id = p_pay_batch_id
    GROUP BY COALESCE(NULLIF(btrim(coalesce(settlement_candidate.settlement_status, '')), ''), 'UNKNOWN')
  )
  SELECT jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'settled_count', COALESCE((
      SELECT SUM(settlement_status_counts.status_count)::integer
      FROM settlement_status_counts
      WHERE upper(settlement_status_counts.settlement_status) IN ('SETTLED','PAID','CONFIRMED')
    ), 0),
    'status_counts', COALESCE((
      SELECT jsonb_object_agg(settlement_status_counts.settlement_status, settlement_status_counts.status_count ORDER BY settlement_status_counts.settlement_status)
      FROM settlement_status_counts
    ), '{}'::jsonb)
  )
  INTO v_settlement_status_summary;

  WITH remittance_status_counts AS (
    SELECT
      COALESCE(NULLIF(btrim(coalesce(remittance_candidate.remittance_trigger_status, '')), ''), 'UNKNOWN') AS remittance_status,
      COUNT(*)::integer AS status_count
    FROM public.pay_batch_candidates AS remittance_candidate
    WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
    GROUP BY COALESCE(NULLIF(btrim(coalesce(remittance_candidate.remittance_trigger_status, '')), ''), 'UNKNOWN')
  ), sent_outbox AS (
    SELECT DISTINCT
      COALESCE(
        NULLIF(btrim(COALESCE(remittance_outbox.payment_scope_json->>'pay_batch_candidate_id', '')), ''),
        scoped_candidate_ids.candidate_id_text,
        CASE
          WHEN lower(BTRIM(COALESCE(remittance_outbox.recipient_kind, ''))) = 'candidate'
            THEN remittance_candidate_by_recipient.id::text
          ELSE NULL::text
        END
      ) AS pay_batch_candidate_id_text
    FROM public.mail_outbox AS remittance_outbox
    LEFT JOIN LATERAL jsonb_array_elements_text(COALESCE(remittance_outbox.payment_scope_json->'pay_batch_candidate_ids', '[]'::jsonb)) AS scoped_candidate_ids(candidate_id_text)
      ON true
    LEFT JOIN public.pay_batch_candidates AS remittance_candidate_by_recipient
      ON remittance_candidate_by_recipient.pay_batch_id = p_pay_batch_id
     AND remittance_candidate_by_recipient.candidate_id = remittance_outbox.recipient_id
    WHERE remittance_outbox.type = 'REMITTANCE'
      AND upper(BTRIM(COALESCE(remittance_outbox.status::text, ''))) = 'SENT'
      AND upper(BTRIM(COALESCE(remittance_outbox.provider_status, 'ACCEPTED'))) IN ('ACCEPTED', 'SENT', 'SUCCESS', 'OK', '')
      AND (
        remittance_outbox.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR remittance_outbox.reference LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR remittance_outbox.reference LIKE ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
        OR (
          lower(BTRIM(COALESCE(remittance_outbox.context_kind, ''))) IN ('pay_batch', 'pay_batches')
          AND remittance_outbox.context_id = p_pay_batch_id
        )
        OR COALESCE(remittance_outbox.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
      )
  ), sent_candidate_ids AS (
    SELECT DISTINCT sent_remittance_candidate.id::text AS pay_batch_candidate_id_text
    FROM public.pay_batch_candidates AS sent_remittance_candidate
    WHERE sent_remittance_candidate.pay_batch_id = p_pay_batch_id
      AND (
        sent_remittance_candidate.remittance_sent_at_utc IS NOT NULL
        OR upper(BTRIM(COALESCE(sent_remittance_candidate.remittance_trigger_status, ''))) = 'SENT_VIA_MAIL_OUTBOX'
      )

    UNION

    SELECT sent_outbox.pay_batch_candidate_id_text
    FROM sent_outbox
    WHERE NULLIF(BTRIM(COALESCE(sent_outbox.pay_batch_candidate_id_text, '')), '') IS NOT NULL
  )
  SELECT jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'sent_count', COALESCE((SELECT COUNT(*)::integer FROM sent_candidate_ids), 0),
    'candidate_sent_count', COALESCE((
      SELECT COUNT(*)::integer
      FROM public.pay_batch_candidates AS sent_remittance_candidate
      WHERE sent_remittance_candidate.pay_batch_id = p_pay_batch_id
        AND (
          sent_remittance_candidate.remittance_sent_at_utc IS NOT NULL
          OR upper(BTRIM(COALESCE(sent_remittance_candidate.remittance_trigger_status, ''))) = 'SENT_VIA_MAIL_OUTBOX'
        )
    ), 0),
    'outbox_sent_count', COALESCE((SELECT COUNT(*)::integer FROM sent_outbox), 0),
    'status_counts', COALESCE((
      SELECT jsonb_object_agg(remittance_status_counts.remittance_status, remittance_status_counts.status_count ORDER BY remittance_status_counts.remittance_status)
      FROM remittance_status_counts
    ), '{}'::jsonb)
  )
  INTO v_remittance_status_summary;

  v_remittance_sent_outbox_count := COALESCE(NULLIF(v_remittance_status_summary->>'outbox_sent_count', '')::integer, 0);
  v_remittance_reconciled_sent_count := COALESCE(NULLIF(v_remittance_status_summary->>'sent_count', '')::integer, 0);

  SELECT
    operation_scope.id,
    operation_scope.operation_type,
    operation_scope.status,
    operation_scope.phase,
    operation_scope.progress_json
  INTO
    v_active_operation_id,
    v_active_operation_type,
    v_active_operation_status,
    v_active_operation_phase,
    v_active_operation_progress
  FROM public.banking_pay_operations AS operation_scope
  WHERE operation_scope.pay_batch_id = p_pay_batch_id
    AND operation_scope.status NOT IN ('COMPLETE','FAILED','CANCELLED')
  ORDER BY COALESCE(operation_scope.updated_at_utc, operation_scope.created_at_utc) DESC, operation_scope.created_at_utc DESC, operation_scope.id DESC
  LIMIT 1;

  v_provider_environment_summary := jsonb_build_object(
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'provider_normalized', v_provider_normalized,
    'provider_known', v_provider_known,
    'funding_account_ref', v_batch.funding_account_ref
  );

  v_batch_cancelability_diagnostic := COALESCE(
    public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object('scope_type', 'BATCH'),
      p_actor_user_id,
      'CURRENT_PAYMENT_STATUS'
    ),
    '{}'::jsonb
  );

  v_batch_payment_lifecycle_state := COALESCE(
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'payment_lifecycle_state', '')), ''),
    'LOCAL_PREPARED_NOT_SENT'
  );

  v_batch_payment_lifecycle_label := CASE v_batch_payment_lifecycle_state
    WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
    WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
    WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
    WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried'
    WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
    WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
    WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
    WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
    WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
    WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
    WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
    ELSE initcap(replace(lower(COALESCE(v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
  END;

  v_batch_recommended_action := NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'recommended_action', '')), '');
  v_whole_batch_cancel_available := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'whole_batch_cancel_available', 'false'))) IN ('true','1','yes','y','on');
  v_batch_can_pre_provider_cancel := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_pre_provider_cancel', 'false'))) IN ('true','1','yes','y','on');
  v_batch_requires_bank_check := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_bank_check', 'false'))) IN ('true','1','yes','y','on');
  v_batch_requires_provider_cancel := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_provider_cancel', 'false'))) IN ('true','1','yes','y','on');

  v_has_actual_recovery_context := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'has_actual_recovery_context', 'false'))) IN ('true','1','yes','y','on');
  v_has_provider_unknown_context := COALESCE(v_batch_requires_bank_check, false)
    OR COALESCE(v_batch_payment_lifecycle_state, '') = 'PROVIDER_OUTCOME_UNKNOWN'
    OR upper(BTRIM(COALESCE(v_batch_recommended_action, ''))) = 'CHECK_PROVIDER_STATUS';
  v_has_no_money_context := COALESCE(v_batch_payment_lifecycle_state, '') IN ('PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_FAILED_NO_MONEY', 'FINANCIALS_REWOUND')
    OR upper(BTRIM(COALESCE(v_batch_recommended_action, ''))) = 'NO_MONEY_UNWIND_AND_RECALCULATE';
  v_has_failed_remittance_context := EXISTS (
    SELECT 1
    FROM public.pay_batch_candidates AS failed_remittance_candidate
    WHERE failed_remittance_candidate.pay_batch_id = p_pay_batch_id
      AND NULLIF(BTRIM(COALESCE(failed_remittance_candidate.last_remittance_error, '')), '') IS NOT NULL
  )
  OR EXISTS (
    SELECT 1
    FROM public.mail_outbox AS failed_remittance_outbox
    WHERE failed_remittance_outbox.type = 'REMITTANCE'
      AND upper(BTRIM(COALESCE(failed_remittance_outbox.status::text, ''))) = 'FAILED'
      AND (
        failed_remittance_outbox.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR failed_remittance_outbox.reference LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR failed_remittance_outbox.reference LIKE ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
        OR (
          lower(BTRIM(COALESCE(failed_remittance_outbox.context_kind, ''))) IN ('pay_batch', 'pay_batches')
          AND failed_remittance_outbox.context_id = p_pay_batch_id
        )
        OR COALESCE(failed_remittance_outbox.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
      )
  );
  v_has_unmatched_or_ambiguous_event_context := COALESCE(v_ambiguous_transfer_count, 0) > 0
    OR COALESCE(v_attempted_but_unproven_transfer_count, 0) > 0
    OR EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS ambiguous_payment_event
      WHERE ambiguous_payment_event.pay_batch_id = p_pay_batch_id
        AND upper(BTRIM(COALESCE(ambiguous_payment_event.mapping_status, ''))) IN ('UNMATCHED', 'AMBIGUOUS', 'REVIEW_REQUIRED')
    );

  SELECT COUNT(*)::integer
  INTO v_transfer_completed_count
  FROM public.pay_bank_transfers AS completed_transfer_check
  WHERE completed_transfer_check.pay_batch_id = p_pay_batch_id
    AND (
      upper(BTRIM(COALESCE(completed_transfer_check.status, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'COMMITTED', 'EXECUTED')
      OR upper(BTRIM(COALESCE(completed_transfer_check.rail_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'COMMITTED', 'EXECUTED')
      OR completed_transfer_check.completed_at_utc IS NOT NULL
    );

  SELECT COUNT(*)::integer
  INTO v_transfer_provider_evidence_count
  FROM public.pay_bank_transfers AS provider_evidence_transfer_check
  WHERE provider_evidence_transfer_check.pay_batch_id = p_pay_batch_id
    AND (
      NULLIF(BTRIM(COALESCE(provider_evidence_transfer_check.rail_tx_id, '')), '') IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS provider_evidence_event_check
        WHERE provider_evidence_event_check.pay_batch_id = p_pay_batch_id
          AND provider_evidence_event_check.pay_bank_transfer_id = provider_evidence_transfer_check.id
          AND (
            NULLIF(BTRIM(COALESCE(provider_evidence_event_check.provider_reference, '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(provider_evidence_event_check.provider_event_id, '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(provider_evidence_event_check.raw_payload #>> '{provider_transaction_id}', '')), '') IS NOT NULL
          )
      )
    );

  v_retry_state := CASE
    WHEN lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_retry_later', 'false'))) IN ('true','1','yes','y','on')
      OR upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER'
      THEN 'RETRY_UNSENT_AVAILABLE'
    ELSE NULL::text
  END;
  v_retry_after_utc := COALESCE(
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'next_retry_at_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_after_utc', '')), '')
  );
  v_retry_reason := COALESCE(
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_reason', '')), '')
  );
  v_next_retry_description := CASE
    WHEN v_retry_state IN ('RETRY_UNSENT_AVAILABLE','RETRY_UNSENT_IN_PROGRESS') THEN COALESCE(v_retry_reason, 'Payments were not sent to the bank/provider and can be retried.')
    ELSE NULL::text
  END;

  SELECT
    COALESCE(COUNT(DISTINCT correction_items.pay_batch_item_id) FILTER (WHERE correction_items.correction_item_kind = 'PRE_BANK_CANCEL' AND correction_items.status = 'APPLIED'), 0)::integer,
    COALESCE(COUNT(DISTINCT correction_items.pay_batch_item_id) FILTER (WHERE correction_items.correction_item_kind = 'NO_MONEY_UNWIND' AND correction_items.status = 'APPLIED'), 0)::integer
  INTO
    v_cancelled_before_bank_submission_count,
    v_financials_rewound_count
  FROM public.pay_payment_correction_items AS correction_items
  WHERE correction_items.pay_batch_id = p_pay_batch_id;

  v_partial_cancel_count := CASE
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_active_effective_item_count, 0) > 0
     AND v_batch_payment_lifecycle_state <> 'CANCELLED_BEFORE_BANK_SUBMISSION'
      THEN COALESCE(v_cancelled_before_bank_submission_count, 0)
    ELSE 0
  END;

  SELECT
    COALESCE(COUNT(*)::integer, 0),
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', carry_forward_rows.id::text,
        'status', carry_forward_rows.status,
        'source_pay_batch_id', CASE WHEN carry_forward_rows.source_pay_batch_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_batch_id::text END,
        'source_pay_batch_item_id', CASE WHEN carry_forward_rows.source_pay_batch_item_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_batch_item_id::text END,
        'source_pay_bank_transfer_id', CASE WHEN carry_forward_rows.source_pay_bank_transfer_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_bank_transfer_id::text END,
        'target_pay_batch_id', CASE WHEN carry_forward_rows.target_pay_batch_id IS NULL THEN NULL ELSE carry_forward_rows.target_pay_batch_id::text END,
        'target_pay_batch_item_id', CASE WHEN carry_forward_rows.target_pay_batch_item_id IS NULL THEN NULL ELSE carry_forward_rows.target_pay_batch_item_id::text END,
        'adjustment_direction', carry_forward_rows.adjustment_direction,
        'amount_ex_vat', carry_forward_rows.amount_ex_vat,
        'amount_vat', carry_forward_rows.amount_vat,
        'amount_inc_vat', carry_forward_rows.amount_inc_vat,
        'signed_amount_convention', 'SIGNED_AMOUNTS'
      )
      ORDER BY carry_forward_rows.id
    ), '[]'::jsonb)
  INTO
    v_manual_adjustments_carried_forward_count,
    v_manual_adjustment_carry_forward_records_json
  FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
  WHERE carry_forward_rows.source_pay_batch_id = p_pay_batch_id
     OR carry_forward_rows.target_pay_batch_id = p_pay_batch_id;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_batch_candidates AS remittance_candidate
    WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
      AND (
        remittance_candidate.remittance_sent_at_utc IS NOT NULL
        OR upper(BTRIM(COALESCE(remittance_candidate.remittance_trigger_status, ''))) = 'SENT_VIA_MAIL_OUTBOX'
      )
  )
  OR EXISTS (
    SELECT 1
    FROM public.mail_outbox AS remittance_outbox
    WHERE remittance_outbox.type = 'REMITTANCE'
      AND upper(BTRIM(COALESCE(remittance_outbox.status::text, ''))) = 'SENT'
      AND upper(BTRIM(COALESCE(remittance_outbox.provider_status, 'ACCEPTED'))) IN ('ACCEPTED', 'SENT', 'SUCCESS', 'OK', '')
      AND (
        remittance_outbox.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR remittance_outbox.reference LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
        OR remittance_outbox.reference LIKE ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
        OR (
          lower(BTRIM(COALESCE(remittance_outbox.context_kind, ''))) IN ('pay_batch', 'pay_batches')
          AND remittance_outbox.context_id = p_pay_batch_id
        )
        OR COALESCE(remittance_outbox.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
      )
  )
  INTO v_remittance_already_sent;

  IF v_batch_status_upper = 'SETTLED'
     AND v_execution_commit_state = 'COMMITTED'
     AND COALESCE(v_transfer_completed_count, 0) > 0
     AND (COALESCE(v_transfer_provider_evidence_count, 0) > 0 OR COALESCE(v_has_external_submission_evidence, false))
     AND COALESCE(v_has_no_money_context, false) IS NOT TRUE
     AND COALESCE(v_has_failed_remittance_context, false) IS NOT TRUE
     AND COALESCE(v_has_unmatched_or_ambiguous_event_context, false) IS NOT TRUE
     AND COALESCE(v_has_actual_recovery_context, false) IS NOT TRUE THEN
    v_has_provider_unknown_context := false;
    v_batch_requires_bank_check := false;
    v_batch_requires_provider_cancel := false;

    IF upper(BTRIM(COALESCE(v_batch_recommended_action, ''))) IN ('AMEND_AND_RECOVER_OVERPAYMENT', 'CHECK_PROVIDER_STATUS') THEN
      v_batch_recommended_action := 'VIEW_DETAILS';
    END IF;
  END IF;

  v_clean_paid_or_settled_success := (
    v_batch_status_upper = 'SETTLED'
    AND v_execution_commit_state = 'COMMITTED'
    AND COALESCE(v_transfer_completed_count, 0) > 0
    AND (COALESCE(v_transfer_provider_evidence_count, 0) > 0 OR COALESCE(v_has_external_submission_evidence, false))
    AND COALESCE(v_has_actual_recovery_context, false) IS NOT TRUE
    AND COALESCE(v_has_provider_unknown_context, false) IS NOT TRUE
    AND COALESCE(v_has_no_money_context, false) IS NOT TRUE
    AND COALESCE(v_has_failed_remittance_context, false) IS NOT TRUE
    AND COALESCE(v_has_unmatched_or_ambiguous_event_context, false) IS NOT TRUE
  );

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash
  INTO
    v_batch_signal_version,
    v_batch_payment_status_version,
    v_batch_correction_progress_version,
    v_batch_alert_version,
    v_batch_overview_version,
    v_batch_last_status_hash,
    v_batch_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_batch_signal_version := 0;
    v_batch_payment_status_version := 0;
    v_batch_correction_progress_version := 0;
    v_batch_alert_version := 0;
    v_batch_overview_version := 0;
    v_batch_last_status_hash := NULL::text;
    v_batch_last_alert_hash := NULL::text;
  END IF;

  v_provider_webhook_evidence_json := COALESCE(
    v_batch_cancelability_diagnostic->'provider_webhook_evidence_json',
    v_batch_cancelability_diagnostic#>'{provider_evidence,provider_webhook_evidence_json}',
    '{}'::jsonb
  );

  v_batch_support_details_json := jsonb_strip_nulls(
    COALESCE(v_batch_cancelability_diagnostic->'support_details_json', '{}'::jsonb)
    || jsonb_build_object(
      'live_signal_version', COALESCE(v_batch_signal_version, 0),
      'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
      'alert_version', COALESCE(v_batch_alert_version, 0),
      'overview_version', COALESCE(v_batch_overview_version, 0),
      'last_status_hash', v_batch_last_status_hash,
      'last_alert_hash', v_batch_last_alert_hash,
      'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb)
    )
    || jsonb_build_object(
      'db_status', v_batch.status,
      'payment_lifecycle_state', v_batch_payment_lifecycle_state,
      'recommended_action', v_batch_recommended_action,
      'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
      'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
      'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
      'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
      'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
      'derived_lifecycle_values_are_payload_only', true,
      'clean_paid_or_settled_success', COALESCE(v_clean_paid_or_settled_success, false),
      'has_actual_recovery_context', COALESCE(v_has_actual_recovery_context, false),
      'has_provider_unknown_context', COALESCE(v_has_provider_unknown_context, false),
      'has_no_money_context', COALESCE(v_has_no_money_context, false),
      'has_failed_remittance_context', COALESCE(v_has_failed_remittance_context, false),
      'has_unmatched_or_ambiguous_event_context', COALESCE(v_has_unmatched_or_ambiguous_event_context, false),
      'action_required', COALESCE(v_action_required, false)
    )
  );

  v_large_batch := (
    COALESCE(v_candidate_count, 0) > 100
    OR COALESCE(v_item_count, 0) > 250
    OR COALESCE(v_transfer_count, 0) > 100
    OR COALESCE(v_item_breakdown_count, 0) > 500
  );

  SELECT COALESCE(jsonb_agg(large_reason.reason ORDER BY large_reason.reason), '[]'::jsonb)
  INTO v_large_batch_reasons
  FROM (
    SELECT 'candidate_count'::text AS reason WHERE COALESCE(v_candidate_count, 0) > 100
    UNION ALL
    SELECT 'item_count'::text AS reason WHERE COALESCE(v_item_count, 0) > 250
    UNION ALL
    SELECT 'transfer_count'::text AS reason WHERE COALESCE(v_transfer_count, 0) > 100
    UNION ALL
    SELECT 'item_breakdown_count'::text AS reason WHERE COALESCE(v_item_breakdown_count, 0) > 500
  ) AS large_reason;

  -- BOOTSTRAP_ONLY responses are handled exclusively by the safe early-return
  -- branch above. From this point onward the function is in the full-detail
  -- path, so provider-submit diagnostics are loaded only for full detail.
    v_provider_submit_diagnostic_result := COALESCE(
      public.pay_provider_submit_diagnostic_get(p_pay_batch_id => p_pay_batch_id, p_provider_diagnostic_context => 'CURRENT_PAYMENT_STATUS_PROVIDER_DETAIL'),
      '{}'::jsonb
    );

    IF jsonb_typeof(v_provider_submit_diagnostic_result -> 'provider_submit_diagnostic') = 'object' THEN
      v_provider_submit_diagnostic := v_provider_submit_diagnostic_result -> 'provider_submit_diagnostic';
    ELSE
      v_provider_submit_diagnostic := '{}'::jsonb;
    END IF;

  -- 3.41: finalise retry metadata after provider-submit diagnostics are loaded.
  -- The earlier batch diagnostic is intentionally kept, but provider retry
  -- metadata is not available until this point.
  v_retry_after_utc := COALESCE(
    NULLIF(btrim(COALESCE(v_retry_after_utc, '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,retry_after_utc}', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,retry_after_utc}', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'next_retry_at_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic #>> '{support_details_json,retry_after_utc}', '')), '')
  );

  v_retry_reason := COALESCE(
    NULLIF(btrim(COALESCE(v_retry_reason, '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,retry_reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic #>> '{support_details_json,retry_reason}', '')), '')
  );

  v_next_retry_description := CASE
    WHEN v_retry_state IN ('RETRY_UNSENT_AVAILABLE','RETRY_UNSENT_IN_PROGRESS') THEN COALESCE(v_retry_reason, 'Payments were not sent to the bank/provider and can be retried.')
    ELSE NULL::text
  END;

  IF upper(btrim(COALESCE(v_active_operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
     AND upper(btrim(COALESCE(v_active_operation_status, ''))) NOT IN ('COMPLETED','COMPLETE','SUCCEEDED','SUCCESS','FAILED','FAILED_FINAL','CANCELLED','CANCELED') THEN
    v_retry_in_progress := true;
    v_retry_already_in_progress := true;
    v_retry_operation_id := v_active_operation_id;
    v_retry_operation_status := v_active_operation_status;
    v_retry_state := 'RETRY_UNSENT_IN_PROGRESS';
  END IF;

  IF upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER'
     OR COALESCE(v_retry_in_progress, false) THEN
    BEGIN
      v_retry_plan_json := public.pay_payment_correction_plan(
        p_pay_batch_id,
        jsonb_build_object(
          'scope_type', 'BATCH',
          'source_context', 'PAY_BATCH_GET_OVERVIEW',
          'requested_action', 'RETRY_PROVIDER_LATER'
        ),
        p_actor_user_id,
        'CURRENT_PAYMENT_STATUS_CORRECTION_ACTION'
      );
    EXCEPTION WHEN OTHERS THEN
      v_retry_plan_json := jsonb_build_object(
        'ok', false,
        'retry_eligible_count', 0,
        'retry_ineligible_count', 0,
        'retry_eligible_scope_json', '{}'::jsonb,
        'retry_ineligible_summary_json', jsonb_build_array(jsonb_build_object(
          'code', 'RETRY_UNSENT_PLAN_UNAVAILABLE',
          'message', SQLERRM,
          'sqlstate', SQLSTATE
        )),
        'retry_in_progress', COALESCE(v_retry_in_progress, false),
        'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
        'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
        'retry_operation_status', v_retry_operation_status,
        'retry_button_visible', false,
        'retry_button_disabled_reason', 'Retry status could not be checked'
      );
    END;

    v_retry_eligible_count := CASE
      WHEN COALESCE(v_retry_plan_json->>'retry_eligible_count', '') ~ '^\d+$' THEN (v_retry_plan_json->>'retry_eligible_count')::integer
      ELSE 0
    END;
    v_retry_ineligible_count := CASE
      WHEN COALESCE(v_retry_plan_json->>'retry_ineligible_count', '') ~ '^\d+$' THEN (v_retry_plan_json->>'retry_ineligible_count')::integer
      ELSE 0
    END;
    v_retry_eligible_scope_json := COALESCE(v_retry_plan_json->'retry_eligible_scope_json', '{}'::jsonb);
    v_retry_ineligible_summary_json := COALESCE(v_retry_plan_json->'retry_ineligible_summary_json', '[]'::jsonb);
    v_retry_scope_signature := NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_scope_signature', '')), '');

    IF NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_operation_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_retry_operation_id := (v_retry_plan_json->>'retry_operation_id')::uuid;
    END IF;
    v_retry_operation_status := COALESCE(NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_operation_status', '')), ''), v_retry_operation_status);
    v_retry_in_progress := COALESCE(NULLIF(v_retry_plan_json->>'retry_in_progress', '')::boolean, v_retry_in_progress, false);
    v_retry_already_in_progress := COALESCE(NULLIF(v_retry_plan_json->>'retry_already_in_progress', '')::boolean, v_retry_in_progress, false);
  END IF;

  IF v_retry_operation_id IS NULL THEN
    SELECT retry_operation_rows.id,
           retry_operation_rows.status
    INTO v_retry_operation_id,
         v_retry_operation_status
    FROM public.banking_pay_operations AS retry_operation_rows
    WHERE retry_operation_rows.pay_batch_id = p_pay_batch_id
      AND upper(btrim(COALESCE(retry_operation_rows.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
    ORDER BY COALESCE(retry_operation_rows.updated_at_utc, retry_operation_rows.created_at_utc) DESC NULLS LAST,
             retry_operation_rows.created_at_utc DESC NULLS LAST,
             retry_operation_rows.id DESC
    LIMIT 1;
  END IF;

  IF COALESCE(v_retry_in_progress, false) THEN
    v_retry_state := 'RETRY_UNSENT_IN_PROGRESS';
    v_retry_status_label := 'Retrying unsent payments';
    v_retry_button_disabled_reason := 'Retry in progress';
    v_retry_button_visible := false;
  ELSIF COALESCE(v_retry_eligible_count, 0) > 0 THEN
    v_retry_state := 'RETRY_UNSENT_AVAILABLE';
    v_retry_status_label := 'Bank unavailable — unsent payments can be retried';
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := true;
  ELSIF upper(btrim(COALESCE(v_retry_operation_status, ''))) IN ('COMPLETED','COMPLETE','SUCCEEDED','SUCCESS') THEN
    v_retry_state := 'RETRY_UNSENT_COMPLETE';
    v_retry_status_label := 'Retry complete';
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := false;
  ELSIF upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER' THEN
    v_retry_state := 'NO_UNSENT_RETRY_AVAILABLE';
    v_retry_status_label := 'No unsent payments available to retry';
    v_retry_button_disabled_reason := 'No unsent payments available to retry';
    v_retry_button_visible := false;
  ELSE
    v_retry_state := NULL::text;
    v_retry_status_label := NULL::text;
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := false;
  END IF;

  v_next_retry_description := CASE
    WHEN v_retry_state = 'RETRY_UNSENT_AVAILABLE' THEN 'Payments were not sent to the bank/provider and can be retried.'
    WHEN v_retry_state = 'RETRY_UNSENT_IN_PROGRESS' THEN 'CloudTMS is retrying payments confirmed as not sent. You can continue using CloudTMS while this runs.'
    WHEN v_retry_state = 'NO_UNSENT_RETRY_AVAILABLE' THEN 'No unsent payments are currently available to retry.'
    WHEN v_retry_state = 'RETRY_UNSENT_COMPLETE' THEN 'Retry complete.'
    ELSE NULL::text
  END;

  v_batch_support_details_json := COALESCE(v_batch_support_details_json, '{}'::jsonb) || jsonb_build_object(
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_scope_signature', v_retry_scope_signature,
    'retry_status_label', v_retry_status_label,
    'retry_button_label', v_retry_button_label,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason
  );

  v_provider_submission_status := upper(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'provider_submission_status',
    v_provider_submit_diagnostic_result ->> 'provider_submission_status',
    'NO_PROVIDER_SUBMISSION_ATTEMPTED'
  )));

  v_provider_submit_review_reason_code := upper(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'review_reason_code',
    v_provider_submit_diagnostic_result ->> 'review_reason_code',
    ''
  )));

  v_provider_submit_actual_context := (
    COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,operation_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,chunk_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', '')::integer, 0) > 0
    OR v_provider_submission_status NOT IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED')
  );

  v_provider_submit_acceptance_evidence_present := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'provider_acceptance_evidence_present', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_response_present := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'provider_response_present', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_stale_chunk := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'stale_submit_chunk', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_manual_resolution_required := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'manual_resolution_required', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_safe_retry_available := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'safe_retry_available', 'false'))) IN ('true','1','yes','y','on');

  v_provider_submit_backend_review_required := lower(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'payment_provider_review_required',
    v_provider_submit_diagnostic_result ->> 'payment_provider_review_required',
    v_provider_submit_diagnostic ->> 'provider_submit_review_required',
    v_provider_submit_diagnostic_result ->> 'provider_submit_review_required',
    'false'
  ))) IN ('true','1','yes','y','on');

  v_provider_submit_operation_review_required := (
    upper(btrim(coalesce(v_active_operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND upper(btrim(coalesce(v_active_operation_status, ''))) = 'REVIEW_REQUIRED'
  );

  v_provider_submit_acceptance_retry_unsafe := (
    v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
    AND v_provider_submit_acceptance_evidence_present
    AND (
      v_provider_submit_backend_review_required
      OR v_provider_submit_operation_review_required
      OR lower(btrim(coalesce(
        v_provider_submit_diagnostic ->> 'duplicate_payment_risk',
        v_provider_submit_diagnostic_result ->> 'duplicate_payment_risk',
        v_provider_submit_diagnostic ->> 'provider_duplicate_payment_risk',
        v_provider_submit_diagnostic_result ->> 'provider_duplicate_payment_risk',
        'false'
      ))) IN ('true','1','yes','y','on')
    )
  );

  IF v_provider_submit_acceptance_evidence_present THEN
    v_has_external_submission_evidence := true;
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;
  v_provider_submit_manual_resolution_available := (
    v_provider_submit_actual_context
    AND v_provider_submit_manual_resolution_required
    AND v_provider_submit_acceptance_evidence_present = false
  );

  v_payment_provider_review_required := (
    COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE
    AND v_provider_submit_actual_context
    AND v_provider_submission_status <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
    AND (
      v_provider_submit_backend_review_required
      OR v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_REJECTED',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      )
      OR v_provider_submit_acceptance_retry_unsafe
    )
  );

  v_provider_submit_issue_present := COALESCE(v_payment_provider_review_required, false);

  IF COALESCE(v_clean_paid_or_settled_success, false) THEN
    v_payment_provider_review_required := false;
    v_provider_submit_issue_present := false;
    v_provider_submit_manual_resolution_required := false;
    v_provider_submit_manual_resolution_available := false;
    v_provider_submit_safe_retry_available := false;
    v_payment_execution_review := NULL::jsonb;
    v_provider_submit_payment_issue := NULL::jsonb;
  END IF;

  v_provider_submit_is_diagnostic_only := (
    v_provider_submit_actual_context
    AND COALESCE(v_provider_submit_issue_present, false) = false
  );

  IF v_provider_submit_issue_present AND COALESCE(v_provider_submit_safe_retry_available, false) IS NOT TRUE THEN
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;

  IF v_provider_submit_issue_present THEN
    v_provider_submit_headline := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected payment'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
      ELSE 'Provider submission outcome unknown'
    END;

    v_provider_submit_summary := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider returned a rejection/failure.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Submission failed before the payment request was sent.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider accepted/submitted the payment.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'A provider request may have been sent, but no usable response was recorded.'
      ELSE 'Submit chunk is stale with no provider response, transfer event, rail transaction ID, or rail state.'
    END;

    v_provider_submit_action_required := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Review provider error and correct before retry.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Retry may be available after local cleanup.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Do not retry until reconciled.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Reconcile with provider before retry.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Reconcile with provider before retry.'
      ELSE 'Check Revolut/bank before retry.'
    END;

    v_payment_execution_review := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_submission_status', v_provider_submission_status,
      'headline', v_provider_submit_headline,
      'summary', v_provider_submit_summary,
      'recommended_action', COALESCE(NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'recommended_action', '')), ''), v_provider_submit_action_required),
      'operation_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'operation_id', '')), ''),
      'chunk_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'chunk_id', '')), ''),
      'transfer_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'auth_request_id', '')), ''),
      'provider_acceptance_evidence_present', v_provider_submit_acceptance_evidence_present,
      'provider_response_present', v_provider_submit_response_present,
      'stale_submit_chunk', v_provider_submit_stale_chunk,
      'manual_resolution_required', v_provider_submit_manual_resolution_required,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', false,
      'provider_submit_diagnostic', v_provider_submit_diagnostic
    ));

    v_provider_submit_payment_issue := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'issue_type', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'status', 'NEEDS_REVIEW',
      'severity', CASE WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'danger' ELSE 'warning' END,
      'headline', v_provider_submit_headline,
      'summary', v_provider_submit_summary,
      'action_required', v_provider_submit_action_required,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'manual_resolution_required', v_provider_submit_manual_resolution_required,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', false,
      'operation_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'operation_id', '')), ''),
      'chunk_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'chunk_id', '')), ''),
      'transfer_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'auth_request_id', '')), ''),
      'request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'request_id', '')), ''),
      'idempotency_key', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'idempotency_key', '')), '')
    ));
  ELSE
    v_payment_execution_review := NULL::jsonb;
    v_provider_submit_payment_issue := NULL::jsonb;
  END IF;

  IF COALESCE(v_clean_paid_or_settled_success, false) THEN
    v_payment_provider_review_required := false;
    v_provider_submit_issue_present := false;
    v_payment_execution_review := NULL::jsonb;
    v_provider_submit_payment_issue := NULL::jsonb;
    v_banking_alert_requires_attention := false;
  END IF;

  v_action_required := (
    COALESCE(v_provider_submit_issue_present, false)
    OR COALESCE(v_payment_provider_review_required, false)
    OR COALESCE(v_has_actual_recovery_context, false)
    OR COALESCE(v_has_provider_unknown_context, false)
    OR COALESCE(v_has_no_money_context, false)
    OR COALESCE(v_has_failed_remittance_context, false)
    OR COALESCE(v_has_unmatched_or_ambiguous_event_context, false)
  ) AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE;

  v_batch_support_details_json := COALESCE(v_batch_support_details_json, '{}'::jsonb) || jsonb_build_object(
    'clean_paid_or_settled_success', COALESCE(v_clean_paid_or_settled_success, false),
    'has_actual_recovery_context', COALESCE(v_has_actual_recovery_context, false),
    'has_provider_unknown_context', COALESCE(v_has_provider_unknown_context, false),
    'has_no_money_context', COALESCE(v_has_no_money_context, false),
    'has_failed_remittance_context', COALESCE(v_has_failed_remittance_context, false),
    'has_unmatched_or_ambiguous_event_context', COALESCE(v_has_unmatched_or_ambiguous_event_context, false),
    'action_required', COALESCE(v_action_required, false)
  );

  v_freshness_is_stale := upper(btrim(coalesce(to_jsonb(v_batch) ->> 'freshness_validation_status', ''))) = 'STALE';
  v_stale_reason_counts := COALESCE((to_jsonb(v_batch) -> 'freshness_result_json') -> 'stale_reason_counts', '{}'::jsonb);

  IF v_batch_status_upper IN ('DRAFT','DRAFT_CREATED')
     AND COALESCE(v_freshness_is_stale, false) = true THEN
    v_batch_stale_payment_issue := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_BATCH_STALE',
      'issue_type', 'PAYMENT_BATCH_STALE',
      'status', 'NEEDS_REVIEW',
      'severity', 'warning',
      'headline', 'Draft payment is no longer valid',
      'title', 'Draft payment is no longer valid',
      'summary', 'Some payments in this draft are no longer valid.',
      'message', 'Some payments in this draft are no longer valid. Delete this draft and create a new draft payment batch.',
      'action_required', 'Delete this draft and create a new draft payment batch.',
      'recommended_action', 'Delete this draft and create a new draft payment batch.',
      'user_action', 'DELETE_DRAFT_AND_CREATE_NEW',
      'delete_draft_recommended', true,
      'create_new_draft_recommended', true,
      'requires_user_action', true,
      'whole_batch_issue', true,
      'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
      'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
      'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
      'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
      'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
    ));

    v_batch_stale_payment_execution_review := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_BATCH_STALE',
      'review_reason_code', 'BATCH_STALE',
      'headline', 'Draft payment is no longer valid',
      'summary', 'Some payments in this draft are no longer valid.',
      'message', 'Some payments in this draft are no longer valid. Delete this draft and create a new draft payment batch.',
      'recommended_action', 'Delete this draft and create a new draft payment batch.',
      'user_action', 'DELETE_DRAFT_AND_CREATE_NEW',
      'delete_draft_recommended', true,
      'create_new_draft_recommended', true,
      'manual_resolution_required', false,
      'manual_resolution_available', false,
      'safe_retry_available', false,
      'payment_provider_review_required', false,
      'provider_submit_issue_present', false,
      'provider_submit_is_diagnostic_only', true,
      'provider_submission_status', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submission_status ELSE NULL::text END,
      'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
      'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
      'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
      'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
      'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
    ));

    IF v_payment_execution_review IS NULL THEN
      v_payment_execution_review := v_batch_stale_payment_execution_review;
    END IF;

    v_payment_issues := COALESCE(v_payment_issues, '[]'::jsonb) || jsonb_build_array(v_batch_stale_payment_issue);
  END IF;

  -- BOOTSTRAP_ONLY responses are handled exclusively by the safe early-return
  -- branch above, before any classification, cancelability, provider, correction,
  -- remittance, mail, payment-status, provider-evidence, or manual-adjustment
  -- diagnostic work is performed. From this point onward the function is in the
  -- full-detail path only.
  v_bootstrap_only := false;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_batch_get_candidate_effective;
  CREATE TEMP TABLE _tmp_pay_batch_get_candidate_effective ON COMMIT DROP AS
  WITH item_scope AS (
    SELECT
      pbc_effective.id AS pay_batch_candidate_id,
      pbc_effective.candidate_id,
      pbi_effective.id AS pay_batch_item_id,
      pbi_effective.item_type,
      pbi_effective.amount_ex_vat,
      pbi_effective.amount_inc_vat,
      COALESCE(pbi_effective.is_voided, false) AS is_voided,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS precancel_items
        WHERE precancel_items.pay_batch_item_id = pbi_effective.id
          AND precancel_items.status = 'APPLIED'
          AND precancel_items.correction_item_kind = 'PRE_BANK_CANCEL'
      ) AS has_precancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS unwind_items
        WHERE unwind_items.pay_batch_item_id = pbi_effective.id
          AND unwind_items.status = 'APPLIED'
          AND unwind_items.correction_item_kind = 'NO_MONEY_UNWIND'
      ) AS has_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reversal_items
        WHERE reversal_items.pay_batch_item_id = pbi_effective.id
          AND reversal_items.status = 'APPLIED'
          AND reversal_items.correction_item_kind = 'SETTLED_REVERSAL'
      ) AS has_settled_reversal
    FROM public.pay_batch_candidates AS pbc_effective
    LEFT JOIN public.pay_batch_items AS pbi_effective
      ON pbi_effective.pay_batch_candidate_id = pbc_effective.id
    WHERE pbc_effective.pay_batch_id = p_pay_batch_id
  ), candidate_effective AS (
    SELECT
      item_scope.pay_batch_candidate_id,
      item_scope.candidate_id,
      COUNT(item_scope.pay_batch_item_id)::integer AS total_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.pay_batch_item_id IS NOT NULL
          AND COALESCE(item_scope.is_voided, false) = false
          AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
      )::integer AS active_effective_item_count,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_inc_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS original_frozen_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS original_frozen_amount_inc_vat,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_precancel)::integer AS applied_precancel_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_no_money_unwind)::integer AS applied_unwind_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_settled_reversal)::integer AS applied_reversal_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)::integer AS corrected_item_count
    FROM item_scope
    GROUP BY item_scope.pay_batch_candidate_id, item_scope.candidate_id
  )
  SELECT
    candidate_effective.pay_batch_candidate_id,
    candidate_effective.candidate_id,
    COALESCE(candidate_effective.total_item_count, 0)::integer AS total_item_count,
    COALESCE(candidate_effective.active_effective_item_count, 0)::integer AS active_effective_item_count,
    COALESCE(candidate_effective.active_effective_amount_ex_vat, 0)::numeric AS active_effective_amount_ex_vat,
    COALESCE(candidate_effective.active_effective_amount_inc_vat, 0)::numeric AS active_effective_amount_inc_vat,
    COALESCE(candidate_effective.original_frozen_amount_ex_vat, 0)::numeric AS original_frozen_amount_ex_vat,
    COALESCE(candidate_effective.original_frozen_amount_inc_vat, 0)::numeric AS original_frozen_amount_inc_vat,
    COALESCE(candidate_effective.applied_precancel_item_count, 0)::integer AS applied_precancel_item_count,
    COALESCE(candidate_effective.applied_unwind_item_count, 0)::integer AS applied_unwind_item_count,
    COALESCE(candidate_effective.applied_reversal_item_count, 0)::integer AS applied_reversal_item_count,
    COALESCE(candidate_effective.corrected_item_count, 0)::integer AS corrected_item_count,
    (COALESCE(candidate_effective.corrected_item_count, 0) > 0) AS payment_issue_badge,
    (
      COALESCE(candidate_effective.corrected_item_count, 0) > 0
      AND COALESCE(candidate_effective.active_effective_item_count, 0) = 0
    ) AS current_effective_zero,
    CASE
      WHEN COALESCE(candidate_effective.applied_reversal_item_count, 0) > 0 THEN 'Overpayment recovery applied'
      WHEN COALESCE(candidate_effective.applied_unwind_item_count, 0) > 0 THEN 'Financials rewound'
      WHEN COALESCE(candidate_effective.applied_precancel_item_count, 0) > 0 THEN 'Cancelled before bank submission'
      ELSE NULL::text
    END AS payment_issue_label,
    COALESCE((
      SELECT jsonb_agg(issue_kind_values.issue_kind ORDER BY issue_kind_values.issue_kind)
      FROM (
        SELECT 'PRE_BANK_CANCEL'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_precancel_item_count, 0) > 0
        UNION ALL
        SELECT 'NO_MONEY_UNWIND'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_unwind_item_count, 0) > 0
        UNION ALL
        SELECT 'SETTLED_REVERSAL'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_reversal_item_count, 0) > 0
      ) AS issue_kind_values
    ), '[]'::jsonb) AS payment_issue_kinds
  FROM candidate_effective;

  SELECT
    COALESCE(SUM(COALESCE(candidate_effective.active_effective_item_count, 0)), 0)::integer,
    ROUND(COALESCE(SUM(COALESCE(candidate_effective.active_effective_amount_ex_vat, 0)), 0), 2)::numeric,
    ROUND(COALESCE(SUM(COALESCE(candidate_effective.active_effective_amount_inc_vat, 0)), 0), 2)::numeric,
    COUNT(*) FILTER (WHERE COALESCE(candidate_effective.payment_issue_badge, false))::integer
  INTO
    v_active_effective_item_count,
    v_active_effective_amount_ex_vat,
    v_active_effective_amount_inc_vat,
    v_payment_issue_candidate_count
  FROM pg_temp._tmp_pay_batch_get_candidate_effective AS candidate_effective;

  -- ✅ C: load schedule defaults for UI preselect (do not change batch state)
  select
    sd.default_schedule_umbrella_local,
    sd.default_schedule_paye_local,
    sd.funds_warning_hours_json,
    sd.rail_default_funding_account_ref
  into
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_rail_default_funding_account_ref
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  -- ✅ D: authorisation summary (latest active request if present)
  v_auth := jsonb_build_object(
    'auth_request_id', null,
    'auth_state', null,
    'required_quantity', null,
    'approved_count', 0,
    'approved_by', '[]'::jsonb,
    'invited_to', '[]'::jsonb,
    'golden_key_used', false,
    'golden_key_user_id', null,
    'execution_intent_json', null,
    'execution_mode', null,
    'suppress_remittances', false
  );

  select
    pbar0.id as auth_request_id,
    pbar0.state as auth_state,
    pbar0.required_quantity as required_quantity,
    pbar0.golden_key_used as golden_key_used,
    pbar0.golden_key_user_id as golden_key_user_id,
    pbar0.execution_intent_json as execution_intent_json
  into v_ar
  from public.pay_batch_auth_requests pbar0
  where pbar0.pay_batch_id = p_pay_batch_id
    and pbar0.state in ('AWAITING','AUTHORISED')
  order by pbar0.created_at_utc desc, pbar0.id desc
  limit 1;

  if v_ar.auth_request_id is not null then
    if v_ar.execution_intent_json is not null and jsonb_typeof(v_ar.execution_intent_json) = 'object' then
      v_active_auth_execution_intent_json := v_ar.execution_intent_json;
    else
      v_active_auth_execution_intent_json := null;
    end if;

    select count(*)::int
    into v_auth_approved_count
    from public.pay_batch_auth_actions pbaa0
    where pbaa0.auth_request_id = v_ar.auth_request_id
      and pbaa0.action in ('AUTHORISE','USE_GOLDEN_KEY');

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'actor_user_id', pbaa1.actor_user_id::text,
          'actor_display_name', tu1.display_name,
          'action', pbaa1.action,
          'action_at_utc', pbaa1.action_at_utc,
          'note', pbaa1.note
        )
        order by pbaa1.action_at_utc asc nulls last, pbaa1.id asc
      ),
      '[]'::jsonb
    )
    into v_auth_approved_by
    from public.pay_batch_auth_actions pbaa1
    left join public.tms_users tu1
      on tu1.id = pbaa1.actor_user_id
    where pbaa1.auth_request_id = v_ar.auth_request_id;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'target_user_id', pbat0.target_user_id::text,
          'target_display_name', tu2.display_name,
          'invited_at_utc', pbat0.created_at_utc,
          'expires_at_utc', pbat0.expires_at_utc,
          'used_at_utc', pbat0.used_at_utc
        )
        order by pbat0.created_at_utc asc nulls last, pbat0.token asc
      ),
      '[]'::jsonb
    )
    into v_auth_invited_to
    from public.pay_batch_auth_tokens pbat0
    left join public.tms_users tu2
      on tu2.id = pbat0.target_user_id
    where pbat0.auth_request_id = v_ar.auth_request_id;

    v_auth := jsonb_build_object(
      'auth_request_id', v_ar.auth_request_id::text,
      'auth_state', v_ar.auth_state,
      'required_quantity', v_ar.required_quantity,
      'approved_count', v_auth_approved_count,
      'approved_by', v_auth_approved_by,
      'invited_to', v_auth_invited_to,
      'golden_key_used', coalesce(v_ar.golden_key_used,false),
      'golden_key_user_id', case when v_ar.golden_key_user_id is null then null else v_ar.golden_key_user_id::text end,
      'execution_intent_json', v_active_auth_execution_intent_json,
      'execution_mode', case when v_active_auth_execution_intent_json is null then null else v_active_auth_execution_intent_json->>'execution_mode' end,
      'suppress_remittances', lower(btrim(coalesce(v_active_auth_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on')
    );
  end if;

  -- Candidates + PAYE net input summary (latest per candidate)
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
          'id',
          pbc.id::text,
          'candidate_id',
          pbc.candidate_id::text,
          'candidate_tms_ref',
          pbc.candidate_tms_ref,
          'candidate_display_name',
          pbc.candidate_display_name,
          'paye_state',
          pbc.paye_state,
          'mismatch_settlement_choice',
          pbc.mismatch_settlement_choice,
          'original_gross_preview',
          pbc.gross_preview,
          'original_net_bank_amount',
          pbc.net_bank_amount,
          'gross_preview',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'net_bank_amount',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'current_effective_gross_preview',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'current_effective_net_bank_amount',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'current_effective_item_count',
          coalesce(ce.active_effective_item_count, 0),
          'active_effective_item_count',
          coalesce(ce.active_effective_item_count, 0),
          'total_item_count',
          coalesce(ce.total_item_count, 0),
          'current_effective_amount_ex_vat',
          coalesce(ce.active_effective_amount_ex_vat, 0),
          'current_effective_amount_inc_vat',
          coalesce(ce.active_effective_amount_inc_vat, 0),
          'original_frozen_amount_ex_vat',
          coalesce(ce.original_frozen_amount_ex_vat, 0),
          'original_frozen_amount_inc_vat',
          coalesce(ce.original_frozen_amount_inc_vat, 0),
          'payment_issue_badge',
          coalesce(ce.payment_issue_badge, false),
          'payment_issue_badge_label',
          case when coalesce(ce.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
          'payment_issue_label',
          ce.payment_issue_label,
          'payment_issue_kinds',
          coalesce(ce.payment_issue_kinds, '[]'::jsonb),
          'payment_lifecycle_state',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state),
          'payment_lifecycle_label',
          CASE COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state)
          WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
          WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
          WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
          WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
          WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
          WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
          WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
          WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
          WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
          ELSE initcap(replace(lower(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
        END,
          'recommended_action',
          candidate_payment_diagnostic.diagnostic_json->>'recommended_action',
          'row_action',
          CASE
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
            ELSE candidate_payment_diagnostic.diagnostic_json->>'recommended_action'
          END,
          'row_action_label',
          CASE
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
            ELSE 'View details'
          END,
          'retry_row_context',
          CASE WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OVERVIEW_ONLY' ELSE NULL::text END,
          'row_cancel_available',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
          'can_no_money_unwind',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
          'can_recover_overpayment',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustment_carry_forward_required',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustments_to_carry_forward',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
          'manual_adjustments_carried_forward',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
          'carry_forward_blockers',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
          'blocking_paid_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
          'terminal_no_money_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
          'pending_provider_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
          'resolved_full_payment_scope_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
          'finance_scope_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
          'provider_failure_reason_group',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
          'provider_failure_reason_label',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), '')
        )
        || jsonb_build_object(
          'status_update_signature',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'status_update_signature', candidate_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
          'provider_outcome_unknown_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
          'provider_webhook_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
          'applied_precancel_item_count',
          coalesce(ce.applied_precancel_item_count, 0),
          'applied_unwind_item_count',
          coalesce(ce.applied_unwind_item_count, 0),
          'applied_reversal_item_count',
          coalesce(ce.applied_reversal_item_count, 0),
          'corrected_item_count',
          coalesce(ce.corrected_item_count, 0),
          'debt_created',
          pbc.debt_created,
          'overpayment_recovery_taken',
          pbc.overpayment_recovery_taken,
          'loan_repayment_taken',
          pbc.loan_repayment_taken,
          'awaiting_net_amount',
          case when v_batch_kind_fixed = 'LOANS' then false else coalesce(pbc.awaiting_net_amount,false) end,
          'settlement_status',
          pbc.settlement_status,
          'settled_at_utc',
          pbc.settled_at_utc,
          'settled_via',
          pbc.settled_via,
          'settled_note',
          pbc.settled_note,
          'remittance_sent_at_utc',
          pbc.remittance_sent_at_utc,
          'remittance_sent_by_user_id',
          case when pbc.remittance_sent_by_user_id is null then null else pbc.remittance_sent_by_user_id::text end,
          'remittance_trigger_status',
          pbc.remittance_trigger_status,
          'last_remittance_error',
          pbc.last_remittance_error,
          -- Latest PAYE net input summary
        'paye_net_amount',
          ni.net_amount,
          'paye_net_source',
          ni.source,
          'paye_net_imported_at_utc',
          ni.imported_at_utc,
          'paye_net_file_name',
          ni.file_name,
          -- ✅ NEW: explicit deductions summary for child modal / UI
        'deductions_summary',
          jsonb_build_object(
          'gross_positive', case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'manual_debt_recovery', coalesce(fs.manual_debt_recovery,0),
          'manual_debt_net_deductions', coalesce(fs.manual_debt_net_deductions,0),
          'payment_advance_repayment', coalesce(fs.payment_advance_repayment,0),
          'loan_repayment', coalesce(fs.payment_advance_repayment,0),
          'repayment', coalesce(fs.repayment,0),
          'overpayment_recovery', coalesce(fs.overpayment_recovery,0),
          'final_payable', case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'awaiting_net_amount', case when v_batch_kind_fixed = 'LOANS' then false else coalesce(pbc.awaiting_net_amount,false) end,
          'paye_net_amount', ni.net_amount
        ),
          'finance_summary',
          jsonb_build_object(
          'gross_additions_ex_vat', coalesce(fs.gross_additions_ex_vat,0),
          'gross_deductions_ex_vat', coalesce(fs.gross_deductions_ex_vat,0),
          'net_deductions_ex_vat', coalesce(fs.net_deductions_ex_vat,0)
        )
        )
      order by pbc.candidate_display_name nulls last, pbc.candidate_tms_ref nulls last, pbc.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidates
  from public.pay_batch_candidates pbc
  left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
    on ce.pay_batch_candidate_id = pbc.id
  left join lateral (
    select
      pni.net_amount,
      pni.source,
      pni.imported_at_utc,
      pni.file_name
    from public.pay_batch_paye_net_inputs pni
    where pni.pay_batch_candidate_id = pbc.id
    order by pni.imported_at_utc desc
    limit 1
  ) ni on true
  left join lateral (
    select
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_recovery,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_net_deductions,
      round(coalesce(sum(case when pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as payment_advance_repayment,
      round(coalesce(sum(case when pbi.item_type = 'OVERPAYMENT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as overpayment_recovery,
      round(coalesce(sum(case when (pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') or (pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as repayment
    from public.pay_batch_items pbi
    where pbi.pay_batch_candidate_id = pbc.id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ) fs on true
  left join lateral (
    select public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object(
        'scope_type', 'CANDIDATES',
        'pay_batch_candidate_ids', jsonb_build_array(pbc.id::text),
        'candidate_ids', jsonb_build_array(pbc.candidate_id::text)
      ),
      p_actor_user_id,
      'CURRENT_PAYMENT_STATUS'
    ) as diagnostic_json
  ) AS candidate_payment_diagnostic ON true
  where pbc.pay_batch_id = p_pay_batch_id;

  -- Transfers + snapshot fields + rail-generic fields
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'candidate_id', case when pbt.candidate_id is null then null else pbt.candidate_id::text end,
        'umbrella_id', case when pbt.umbrella_id is null then null else pbt.umbrella_id::text end,
        'pay_channel', pbt.pay_channel,
        'amount', pbt.amount,
        'currency', pbt.currency,
        'status', pbt.status,

        -- Rail-generic equivalents
        'rail_provider', pbt.rail_provider,
        'rail_env', pbt.rail_env,
        'request_id', pbt.request_id,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,

        -- Snapshot bank fields
        'payment_reference', pbt.payment_reference,
        'payee_name', pbt.payee_name,
        'sort_code', pbt.sort_code,
        'account_number', pbt.account_number,
        'account_type', pbt.account_type,
        'bank_details_hash_snapshot', pbt.bank_details_hash_snapshot,

        -- Drilldown/grouping fields
        'transfer_group_key', pbt.transfer_group_key,
        'grouping_mode_used', pbt.grouping_mode_used,
        'week_ending_bucket', case when pbt.week_ending_bucket is null then null else pbt.week_ending_bucket::text end,

        'created_at_utc', pbt.created_at_utc,
        'completed_at_utc', pbt.completed_at_utc,
        'payment_lifecycle_state', COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state),
        'payment_lifecycle_label', CASE COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state)
          WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
          WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
          WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
          WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
          WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
          WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
          WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
          WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
          WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
          ELSE initcap(replace(lower(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
        END,
        'recommended_action', transfer_payment_diagnostic.diagnostic_json->>'recommended_action',
        'row_action', CASE
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
          ELSE transfer_payment_diagnostic.diagnostic_json->>'recommended_action'
        END,
        'row_action_label', CASE
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
          ELSE 'View details'
        END,
        'retry_row_context', CASE WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OVERVIEW_ONLY' ELSE NULL::text END,
        'row_cancel_available', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
        'can_no_money_unwind', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
        'can_recover_overpayment', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
        'manual_adjustment_carry_forward_required', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
        'manual_adjustments_to_carry_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
        'manual_adjustments_carried_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
        'carry_forward_blockers', COALESCE(transfer_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
        'blocking_paid_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
        'terminal_no_money_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
        'pending_provider_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
        'resolved_full_payment_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
        'finance_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
        'provider_failure_reason_group', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
        'provider_failure_reason_label', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), ''),
        'status_update_signature', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'status_update_signature', transfer_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
        'provider_outcome_unknown_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
        'provider_webhook_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
        'failed_reason', pbt.failed_reason
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_transfers
  from public.pay_bank_transfers pbt
  left join lateral (
    select public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object(
        'scope_type', 'TRANSFER',
        'pay_bank_transfer_ids', jsonb_build_array(pbt.id::text)
      ),
      p_actor_user_id,
      'CURRENT_PAYMENT_STATUS'
    ) as diagnostic_json
  ) AS transfer_payment_diagnostic ON true
  where pbt.pay_batch_id = p_pay_batch_id;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_pending_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_hash.status,'')) = 'PENDING'
    order by pbt_hash.id
  ) transfer_hash_rows;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_stable_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_hash.status,'')) <> 'BLOCKED'
    order by pbt_hash.id
  ) transfer_hash_rows;

  v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch.bank_csv_export_json->>'transfer_hash', '')), '');
  v_execution_transfer_hash := nullif(btrim(coalesce(v_execution_intent_json->>'current_transfer_hash', '')), '');
  v_has_cloudtms_csv_export := (
    v_batch.bank_csv_export_json is not null
    and jsonb_typeof(v_batch.bank_csv_export_json) = 'object'
    and v_bank_csv_export_hash is not null
  );

  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      'ALL'::text,
      NULL::uuid,
      true,
      'CURRENT_PAYMENT_STATUS'
    ) AS classification_row
  ), classified_rows_with_sample AS (
    SELECT
      classified_rows.*,
      row_number() OVER (
        ORDER BY
          CASE
            WHEN classified_rows.evidence_classification IN ('local_only_evidence', 'attempted_but_unproven', 'ambiguous', 'failed', 'pending', 'scope_without_transfer') THEN 0
            ELSE 1
          END,
          classified_rows.pay_bank_transfer_id NULLS LAST,
          classified_rows.scope_id NULLS LAST
      ) AS evidence_sample_ordinality
    FROM classified_rows
  ), evidence_counts AS (
    SELECT
      count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer AS transfer_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'provider_evidence_present')::integer AS provider_submitted_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'local_only_evidence')::integer AS local_only_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'failed' OR classified_rows.is_failed_or_blocked IS TRUE)::integer AS failed_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'ambiguous' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer AS ambiguous_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS attempted_but_unproven_count,
      count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer AS provider_attempt_without_external_id_count,
      count(*) FILTER (
        WHERE classified_rows.evidence_classification = 'ambiguous'
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS requires_provider_poll_count,
      count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer AS committed_count,
      COALESCE(bool_or(
        EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
            AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        )
      ), false) AS has_rail_tx_id,
      COALESCE(bool_or(classified_rows.has_local_prepare_identity IS TRUE), false) AS has_local_generated_request_identity,
      COALESCE(bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE), false) AS has_external_submission_evidence,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_count,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_transfer_count,
      count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer AS unattempted_submit_eligible_count,
      count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer AS safe_local_cleanup_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS provider_attempt_or_evidence_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
      )::integer AS provider_or_ambiguous_evidence_count,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND true), '[]'::jsonb) AS evidence_sample,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'evidence_classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_route_ready', classified_rows.has_route_ready,
          'has_local_prepare_identity', classified_rows.has_local_prepare_identity,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_failed_or_blocked', classified_rows.is_failed_or_blocked,
          'is_terminal_or_completed', classified_rows.is_terminal_or_completed,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND true), '[]'::jsonb) AS execution_classification_sample
    FROM classified_rows_with_sample AS classified_rows
  ), status_sets AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(status_item.status_value ORDER BY status_item.status_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.status, ''))) AS status_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.status, '')), '') IS NOT NULL
        ) AS status_item
      ), '[]'::jsonb) AS transfer_statuses,
      COALESCE((
        SELECT jsonb_agg(rail_state_item.rail_state_value ORDER BY rail_state_item.rail_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.rail_state, ''))) AS rail_state_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.rail_state, '')), '') IS NOT NULL
        ) AS rail_state_item
      ), '[]'::jsonb) AS transfer_rail_states,
      COALESCE((
        SELECT jsonb_agg(event_state_item.normalised_state_value ORDER BY event_state_item.normalised_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.normalised_state, ''))) AS normalised_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.normalised_state, '')), '') IS NOT NULL
        ) AS event_state_item
      ), '[]'::jsonb) AS event_normalised_states,
      COALESCE((
        SELECT jsonb_agg(provider_state_item.provider_state_value ORDER BY provider_state_item.provider_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.provider_state, ''))) AS provider_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.provider_state, '')), '') IS NOT NULL
        ) AS provider_state_item
      ), '[]'::jsonb) AS event_provider_states,
      (SELECT count(*)::integer FROM public.pay_bank_transfer_events AS event_row WHERE event_row.pay_batch_id = p_pay_batch_id) AS transfer_event_count
  ), prepared_counts AS (
    SELECT
      evidence_counts.*,
      status_sets.*,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_unattempted_submit_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) AS remaining_evidence_unresolved_count,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_submit_attempt_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) + COALESCE(evidence_counts.ambiguous_count, 0) + COALESCE(evidence_counts.attempted_but_unproven_count, 0) AS remaining_provider_evidence_required,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_provider_submission_required,
      (
        COALESCE(evidence_counts.transfer_count, 0) > 0
        AND COALESCE(evidence_counts.provider_submitted_count, 0) = COALESCE(evidence_counts.transfer_count, 0)
        AND COALESCE(evidence_counts.failed_count, 0) = 0
        AND COALESCE(evidence_counts.ambiguous_count, 0) = 0
        AND COALESCE(evidence_counts.local_only_count, 0) = 0
        AND COALESCE(evidence_counts.pending_count, 0) = 0
        AND COALESCE(evidence_counts.attempted_but_unproven_count, 0) = 0
      ) AS can_mark_submitted
    FROM evidence_counts
    CROSS JOIN status_sets
  )
  SELECT
    jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'counts_only', false,
      'transfer_count', COALESCE(prepared_counts.transfer_count, 0),
      'transfer_event_count', COALESCE(prepared_counts.transfer_event_count, 0),
      'has_transfer_events', COALESCE(prepared_counts.transfer_event_count, 0) > 0,
      'provider_submitted_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'provider_evidence_present_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'local_idempotency_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_evidence_count', COALESCE(prepared_counts.local_only_count, 0),
      'pending_count', COALESCE(prepared_counts.pending_count, 0),
      'failed_count', COALESCE(prepared_counts.failed_count, 0),
      'ambiguous_count', COALESCE(prepared_counts.ambiguous_count, 0),
      'attempted_but_unproven_count', COALESCE(prepared_counts.attempted_but_unproven_count, 0),
      'provider_attempt_without_external_id_count', COALESCE(prepared_counts.provider_attempt_without_external_id_count, 0)
    )
    || jsonb_build_object(
      'requires_provider_poll_count', COALESCE(prepared_counts.requires_provider_poll_count, 0),
      'authorisation_ready_count', COALESCE(prepared_counts.authorisation_ready_count, 0),
      'authorisation_ready_transfer_count', COALESCE(prepared_counts.authorisation_ready_transfer_count, 0),
      'unattempted_submit_eligible_count', COALESCE(prepared_counts.unattempted_submit_eligible_count, 0),
      'safe_local_cleanup_count', COALESCE(prepared_counts.safe_local_cleanup_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(prepared_counts.provider_attempt_or_evidence_count, 0),
      'provider_or_ambiguous_evidence_count', COALESCE(prepared_counts.provider_or_ambiguous_evidence_count, 0),
      'cancellable_local_auth_request_count', 0,
      'non_cancellable_auth_request_count', 0,
      'same_operation_active_auth_request_count', 0,
      'other_operation_active_auth_request_count', 0,
      'auth_request_provider_risk_count', 0,
      'auth_request_retry_blocker_count', 0,
      'remaining_submit_attempt_required', COALESCE(prepared_counts.remaining_submit_attempt_required, 0),
      'remaining_unattempted_submit_required', COALESCE(prepared_counts.remaining_unattempted_submit_required, 0),
      'remaining_evidence_unresolved_count', COALESCE(prepared_counts.remaining_evidence_unresolved_count, 0)
    )
    || jsonb_build_object(
      'remaining_submit_attempt_required_definition', 'unattempted_submit_eligible_count',
      'remaining_provider_evidence_required', COALESCE(prepared_counts.remaining_provider_evidence_required, 0),
      'remaining_provider_submission_required', COALESCE(prepared_counts.remaining_provider_submission_required, 0),
      'submission_count_semantics', jsonb_build_object(
        'remaining_submit_attempt_required', 'count of transfers currently eligible for an unattempted provider submit',
        'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
        'pending_count', 'evidence-level pending classification, not submit eligibility'
      ),
      'batch_can_be_marked_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_committed', COALESCE(prepared_counts.can_mark_submitted, false) AND COALESCE(prepared_counts.committed_count, 0) = COALESCE(prepared_counts.transfer_count, 0),
      'has_rail_tx_id', COALESCE(prepared_counts.has_rail_tx_id, false),
      'has_local_generated_request_identity', COALESCE(prepared_counts.has_local_generated_request_identity, false),
      'has_external_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'no_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) = false,
      'transfer_statuses', COALESCE(prepared_counts.transfer_statuses, '[]'::jsonb),
      'transfer_rail_states', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb),
      'event_normalised_states', COALESCE(prepared_counts.event_normalised_states, '[]'::jsonb),
      'event_provider_states', COALESCE(prepared_counts.event_provider_states, '[]'::jsonb)
    )
    || jsonb_build_object(
      'evidence_sample', CASE WHEN true THEN COALESCE(prepared_counts.evidence_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'execution_classification_sample', CASE WHEN true THEN COALESCE(prepared_counts.execution_classification_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'has_possible_provider_attempt_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_provider_attempt_request_or_idempotency_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_request_or_idempotency_reference', COALESCE(prepared_counts.local_only_count, 0) > 0 OR COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_submitted_state', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_processing_state', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb) ?| array['PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION'],
      'has_completed_state', COALESCE(prepared_counts.committed_count, 0) > 0,
      'has_failed_or_rejected_provider_state', COALESCE(prepared_counts.failed_count, 0) > 0,
      'has_unknown_or_timeout_state', COALESCE(prepared_counts.ambiguous_count, 0) > 0,
      'requires_provider_poll', COALESCE(prepared_counts.requires_provider_poll_count, 0) > 0,
      'requires_review', COALESCE(prepared_counts.ambiguous_count, 0) > 0 OR (COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0 AND COALESCE(prepared_counts.requires_provider_poll_count, 0) = 0),
      'has_provider_submission_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_payment_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transfer_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transaction_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_external_payment_reference', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'has_external_transfer_reference', COALESCE(prepared_counts.has_external_submission_evidence, false)
    )
  INTO v_submission_evidence
  FROM prepared_counts;

  v_has_external_submission_evidence := COALESCE(
    (v_submission_evidence ->> 'has_external_submission_evidence')::boolean,
    false
  );

  v_alert_actor_user_id := COALESCE(p_actor_user_id, '00000000-0000-0000-0000-000000000000'::uuid);

  IF COALESCE(v_clean_paid_or_settled_success, false) THEN
    v_alert_registry := jsonb_build_object(
      'alerts', '[]'::jsonb,
      'unacknowledged_count', 0,
      'highest_severity', NULL::text,
      'highest_label', NULL::text,
      'clean_paid_or_settled_success', true
    );
  ELSE
    SELECT jsonb_build_object(
      'ok', true,
      'cached', true,
      'alerts', COALESCE(
        CASE
          WHEN jsonb_typeof(alert_display_summary.summary_json->'alerts') = 'array' THEN alert_display_summary.summary_json->'alerts'
          WHEN jsonb_typeof(alert_display_summary.summary_json->'banking_alerts') = 'array' THEN alert_display_summary.summary_json->'banking_alerts'
          ELSE '[]'::jsonb
        END,
        '[]'::jsonb
      ),
      'unacknowledged_count', COALESCE(alert_display_summary.unacknowledged_count, 0),
      'highest_severity', alert_display_summary.highest_severity,
      'highest_label', alert_display_summary.highest_label,
      'banking_alert_hash', alert_display_summary.alert_hash,
      'banking_alert_summary_signature', alert_display_summary.summary_hash,
      'summary_json', COALESCE(alert_display_summary.summary_json, '{}'::jsonb)
    )
    INTO v_alert_registry
    FROM public.banking_alert_display_summary AS alert_display_summary
    WHERE alert_display_summary.actor_user_id = v_alert_actor_user_id;

    IF NOT FOUND THEN
      v_alert_registry := jsonb_build_object(
        'ok', true,
        'cached', true,
        'alerts', '[]'::jsonb,
        'unacknowledged_count', 0,
        'highest_severity', NULL::text,
        'highest_label', NULL::text,
        'summary_json', '{}'::jsonb
      );
    END IF;
  END IF;

  SELECT
    COALESCE(jsonb_agg(alert_scope.alert_json ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC), '[]'::jsonb),
    (array_agg(alert_scope.alert_json ->> 'alert_kind' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'severity' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'label' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'description' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_fingerprint ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    COALESCE(bool_and(alert_scope.acknowledged_for_current_user), false),
    COALESCE(bool_or(alert_scope.acknowledged_for_current_user = false), false)
  INTO
    v_banking_alerts,
    v_banking_alert_kind,
    v_banking_alert_severity,
    v_banking_alert_label,
    v_banking_alert_reason,
    v_banking_alert_fingerprint,
    v_banking_alert_acknowledged_for_user,
    v_banking_alert_requires_attention
  FROM (
    SELECT
      alert_items.alert_json,
      alert_items.alert_json ->> 'alert_fingerprint' AS alert_fingerprint,
      CASE
        WHEN (alert_items.alert_json ->> 'severity_rank') ~ '^[0-9]+$' THEN (alert_items.alert_json ->> 'severity_rank')::integer
        ELSE 0
      END AS severity_rank,
      CASE
        WHEN NULLIF(alert_items.alert_json ->> 'sort_at_utc', '') IS NULL THEN NULL::timestamptz
        ELSE (alert_items.alert_json ->> 'sort_at_utc')::timestamptz
      END AS sort_at_utc,
      COALESCE((alert_items.alert_json ->> 'acknowledged_for_current_user')::boolean, false) AS acknowledged_for_current_user
    FROM jsonb_array_elements(COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)) AS alert_items(alert_json)
    WHERE alert_items.alert_json ->> 'pay_batch_id' = p_pay_batch_id::text
  ) AS alert_scope;

  v_banking_alerts := COALESCE(v_banking_alerts, '[]'::jsonb);
  v_banking_alert_acknowledged_for_user := COALESCE(v_banking_alert_acknowledged_for_user, false);
  v_banking_alert_requires_attention := COALESCE(v_banking_alert_requires_attention, false);

  v_blocked_funds_required_gbp := CASE
    WHEN COALESCE(
      v_batch.last_funds_check_json #>> '{required_gbp}',
      v_batch.last_funds_check_json #>> '{required}',
      v_batch.last_funds_check_json #>> '{required_amount_gbp}',
      v_batch.last_funds_check_json #>> '{required_amount}'
    ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN COALESCE(
        v_batch.last_funds_check_json #>> '{required_gbp}',
        v_batch.last_funds_check_json #>> '{required}',
        v_batch.last_funds_check_json #>> '{required_amount_gbp}',
        v_batch.last_funds_check_json #>> '{required_amount}'
      )::numeric
    ELSE NULL::numeric
  END;

  v_blocked_funds_available_gbp := CASE
    WHEN COALESCE(
      v_batch.last_funds_check_json #>> '{available_gbp}',
      v_batch.last_funds_check_json #>> '{available}',
      v_batch.last_funds_check_json #>> '{available_amount_gbp}',
      v_batch.last_funds_check_json #>> '{available_amount}'
    ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN COALESCE(
        v_batch.last_funds_check_json #>> '{available_gbp}',
        v_batch.last_funds_check_json #>> '{available}',
        v_batch.last_funds_check_json #>> '{available_amount_gbp}',
        v_batch.last_funds_check_json #>> '{available_amount}'
      )::numeric
    ELSE NULL::numeric
  END;

  v_blocked_funds_required_gbp_display := public.cloudtms_format_gbp(v_blocked_funds_required_gbp);
  v_blocked_funds_available_gbp_display := public.cloudtms_format_gbp(v_blocked_funds_available_gbp);

  v_blocked_funds_sufficient := CASE
    WHEN lower(btrim(COALESCE(v_batch.last_funds_check_json #>> '{sufficient}', v_batch.last_funds_check_json #>> '{is_sufficient}', ''))) IN ('true','1','yes','y','on') THEN true
    WHEN lower(btrim(COALESCE(v_batch.last_funds_check_json #>> '{sufficient}', v_batch.last_funds_check_json #>> '{is_sufficient}', ''))) IN ('false','0','no','n','off') THEN false
    ELSE NULL::boolean
  END;

  v_blocked_funds_provider := COALESCE(
    v_batch.last_funds_check_json #>> '{rail_provider}',
    v_batch.last_funds_check_json #>> '{provider}',
    v_batch.rail_provider_snapshot
  );

  v_blocked_funds_env := COALESCE(
    v_batch.last_funds_check_json #>> '{rail_env}',
    v_batch.last_funds_check_json #>> '{env}',
    v_batch.rail_env_snapshot
  );

  v_blocked_funds_account_ref := COALESCE(
    v_batch.last_funds_check_json #>> '{funding_account_ref}',
    v_batch.last_funds_check_json #>> '{account_ref}',
    v_batch.funding_account_ref
  );

  v_no_bank_transfer_events := COALESCE((v_submission_evidence ->> 'transfer_event_count')::integer, 0) = 0;
  v_no_rail_tx_id := COALESCE((v_submission_evidence ->> 'has_rail_tx_id')::boolean, false) = false;
  v_no_provider_submission_reference := (
    COALESCE((v_submission_evidence ->> 'has_provider_submission_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_payment_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_transfer_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_transaction_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_external_payment_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_external_transfer_reference')::boolean, false) = false
  );
  v_no_submitted_or_completed_transfer_state := (
    COALESCE((v_submission_evidence ->> 'has_submitted_state')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_processing_state')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_completed_state')::boolean, false) = false
  );

  v_no_provider_attempt_request_or_idempotency_reference :=
    COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false) = false;

  v_no_possible_provider_attempt_evidence :=
    COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false) = false;

  v_no_external_submission_evidence :=
    COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false) = false;

  v_no_submission_evidence_flags := jsonb_build_object(
    'execution_commit_not_submitted', v_execution_commit_state = 'NOT_SUBMITTED',
    'execution_commit_ref_absent', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NULL,
    'execution_committed_at_absent', v_batch.execution_committed_at_utc IS NULL,
    'no_bank_transfer_events', COALESCE(v_no_bank_transfer_events, false),
    'no_rail_tx_id', COALESCE(v_no_rail_tx_id, false),
    'no_provider_submission_reference', COALESCE(v_no_provider_submission_reference, false),
    'no_submitted_or_completed_transfer_state', COALESCE(v_no_submitted_or_completed_transfer_state, false),
    'no_provider_attempt_request_or_idempotency_reference', COALESCE(v_no_provider_attempt_request_or_idempotency_reference, false),
    'no_possible_provider_attempt_evidence', COALESCE(v_no_possible_provider_attempt_evidence, false),
    'no_external_submission_evidence', COALESCE(v_no_external_submission_evidence, false),
    'no_submission_evidence', COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false),
    'has_local_generated_request_identity', COALESCE((v_submission_evidence ->> 'has_local_generated_request_identity')::boolean, false),
    'has_provider_attempt_request_or_idempotency_reference', COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false),
    'has_possible_provider_attempt_evidence', COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false),
    'has_external_submission_evidence', COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false),
    'submission_evidence', v_submission_evidence
  );

  v_can_retry_blocked_funds := (
    v_batch_status_upper = 'BLOCKED_FUNDS'
    AND v_execution_commit_state = 'NOT_SUBMITTED'
    AND NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NULL
    AND v_batch.execution_committed_at_utc IS NULL
    AND COALESCE(v_active_effective_item_count, 0) > 0
    AND COALESCE(v_no_bank_transfer_events, false) = true
    AND COALESCE(v_no_rail_tx_id, false) = true
    AND COALESCE(v_no_provider_submission_reference, false) = true
    AND COALESCE(v_no_submitted_or_completed_transfer_state, false) = true
    AND COALESCE(v_no_provider_attempt_request_or_idempotency_reference, false) = true
    AND COALESCE(v_no_possible_provider_attempt_evidence, false) = true
    AND COALESCE(v_no_external_submission_evidence, false) = true
    AND COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false) = true
    AND v_blocked_funds_sufficient IS FALSE
  );

  IF v_batch_status_upper = 'BLOCKED_FUNDS' THEN
    v_blocked_funds_alert_payload := jsonb_strip_nulls(
      jsonb_build_object(
        'payload_is_summary', true,
        'summary_source', 'pay_batch_get',
        'alert_kind', 'BLOCKED_FUNDS',
        'issue_kind', 'BLOCKED_FUNDS',
        'compatibility_kind', 'BLOCKED_FUNDS',
        'entity_kind', 'pay_batch',
        'entity_id', p_pay_batch_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'link_target', 'banking_pay_batch',
        'link_tab', 'overview',
        'rail_provider_snapshot', v_batch.rail_provider_snapshot,
        'rail_env_snapshot', v_batch.rail_env_snapshot,
        'provider', v_blocked_funds_provider,
        'rail_provider', v_blocked_funds_provider,
        'rail_env', v_blocked_funds_env
      )
      || jsonb_build_object(
        'funding_account_ref', v_blocked_funds_account_ref,
        'required_gbp', v_blocked_funds_required_gbp,
        'available_gbp', v_blocked_funds_available_gbp,
        'required_gbp_display', v_blocked_funds_required_gbp_display,
        'available_gbp_display', v_blocked_funds_available_gbp_display,
        'sufficient', v_blocked_funds_sufficient,
        'total_bank_out', COALESCE(v_batch.total_bank_out, COALESCE(v_total_amount, 0)),
        'active_effective_item_count', COALESCE(v_active_effective_item_count, 0),
        'active_effective_amount_ex_vat', COALESCE(v_active_effective_amount_ex_vat, 0),
        'active_effective_amount_inc_vat', COALESCE(v_active_effective_amount_inc_vat, 0)
      )
      || jsonb_build_object(
        'can_retry_blocked_funds', COALESCE(v_can_retry_blocked_funds, false),
        'retry_state', v_retry_state,
        'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
        'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
        'retry_in_progress', COALESCE(v_retry_in_progress, false),
        'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
        'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
        'retry_operation_status', v_retry_operation_status,
        'retry_status_label', v_retry_status_label,
        'retry_button_label', v_retry_button_label,
        'retry_button_visible', COALESCE(v_retry_button_visible, false),
        'retry_button_disabled_reason', v_retry_button_disabled_reason
      )
      || jsonb_build_object(
        'execution_commit_state', v_execution_commit_state,
        'has_external_submission_evidence', COALESCE(v_has_external_submission_evidence, false),
        'no_submission_evidence', COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false),
        'no_bank_transfer_events', COALESCE(v_no_bank_transfer_events, false),
        'no_rail_tx_id', COALESCE(v_no_rail_tx_id, false),
        'no_provider_submission_reference', COALESCE(v_no_provider_submission_reference, false),
        'no_submitted_or_completed_transfer_state', COALESCE(v_no_submitted_or_completed_transfer_state, false),
        'no_provider_attempt_request_or_idempotency_reference', COALESCE(v_no_provider_attempt_request_or_idempotency_reference, false),
        'no_possible_provider_attempt_evidence', COALESCE(v_no_possible_provider_attempt_evidence, false),
        'no_external_submission_evidence', COALESCE(v_no_external_submission_evidence, false),
        'current_payment_status_authority', true,
        'payload_contains_affected_rows', false
      )
    );

    IF NULLIF(BTRIM(COALESCE(v_banking_alert_fingerprint, '')), '') IS NULL THEN
      v_banking_alert_fingerprint := public.banking_alert_fingerprint(
        'BLOCKED_FUNDS',
        'pay_batch',
        p_pay_batch_id,
        v_blocked_funds_alert_payload
      );
    END IF;

    v_blocked_funds_reason := concat(
      'Bank unavailable',
      CASE WHEN v_blocked_funds_required_gbp IS NULL THEN '' ELSE ' — required ' || v_blocked_funds_required_gbp_display END,
      CASE WHEN v_blocked_funds_available_gbp IS NULL THEN '' ELSE ', available ' || v_blocked_funds_available_gbp_display END
    );

    IF NULLIF(BTRIM(COALESCE(v_banking_alert_kind, '')), '') IS NULL
       OR COALESCE(v_banking_alert_kind, '') = 'BLOCKED_FUNDS' THEN
      v_banking_alert_kind := 'BLOCKED_FUNDS';
      v_banking_alert_severity := 'critical';
      v_banking_alert_label := 'Bank unavailable — unsent payments can be retried';
      v_banking_alert_reason := v_blocked_funds_reason;
    END IF;

    v_blocked_funds_alert_payload := v_blocked_funds_alert_payload || jsonb_build_object('alert_fingerprint', v_banking_alert_fingerprint);

    IF v_banking_alerts = '[]'::jsonb THEN
      v_banking_alerts := jsonb_build_array(jsonb_build_object(
        'alert_kind', 'BLOCKED_FUNDS',
        'severity', 'critical',
        'severity_rank', 100,
        'entity_kind', 'pay_batch',
        'entity_id', p_pay_batch_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'alert_fingerprint', v_banking_alert_fingerprint,
        'label', 'Bank unavailable — unsent payments can be retried',
        'title', 'Bank unavailable — unsent payments can be retried',
        'description', v_blocked_funds_reason,
        'action_guidance', 'Retry unsent payments from Overview if eligible, or cancel scheduled batch and recalculate.',
        'acknowledged_for_current_user', v_banking_alert_acknowledged_for_user,
        'requires_attention_for_current_user', v_banking_alert_requires_attention,
        'payload_json', v_blocked_funds_alert_payload
      ));
    ELSE
      SELECT COALESCE(
        jsonb_agg(
          CASE
            WHEN COALESCE(alert_item.alert_json ->> 'alert_kind', '') = 'BLOCKED_FUNDS' THEN
              alert_item.alert_json
              || jsonb_build_object(
                'label', 'Bank unavailable — unsent payments can be retried',
                'title', 'Bank unavailable — unsent payments can be retried',
                'description', v_blocked_funds_reason,
                'action_guidance', 'Retry unsent payments from Overview if eligible, or cancel scheduled batch and recalculate.',
                'payload_json', COALESCE(alert_item.alert_json -> 'payload_json', '{}'::jsonb) || v_blocked_funds_alert_payload
              )
            ELSE alert_item.alert_json
          END
          ORDER BY alert_item.alert_ordinality
        ),
        '[]'::jsonb
      )
      INTO v_banking_alerts
      FROM jsonb_array_elements(COALESCE(v_banking_alerts, '[]'::jsonb)) WITH ORDINALITY AS alert_item(alert_json, alert_ordinality);
    END IF;

    v_blocked_funds_payment_issue := jsonb_build_object(
      'issue_kind', 'BLOCKED_FUNDS',
      'severity', 'critical',
      'bank_status_label', 'Bank unavailable — unsent payments can be retried',
      'what_happened', v_blocked_funds_reason,
      'what_happened_label', v_blocked_funds_reason,
      'action_label', 'Retry unsent payments',
      'status_label', 'Urgent action needed',
      'requires_user_action', true,
      'whole_batch_issue', true,
      'can_retry_blocked_funds', v_can_retry_blocked_funds,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false),
      'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
      'retry_operation_status', v_retry_operation_status,
      'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
      'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
      'retry_status_label', v_retry_status_label,
      'retry_button_label', v_retry_button_label,
      'retry_button_visible', COALESCE(v_retry_button_visible, false),
      'retry_button_disabled_reason', v_retry_button_disabled_reason,
      'required_gbp', v_blocked_funds_required_gbp,
      'available_gbp', v_blocked_funds_available_gbp,
      'required_gbp_display', v_blocked_funds_required_gbp_display,
      'available_gbp_display', v_blocked_funds_available_gbp_display,
      'sufficient', v_blocked_funds_sufficient,
      'provider', v_blocked_funds_provider,
      'rail_provider', v_blocked_funds_provider,
      'rail_env', v_blocked_funds_env,
      'funding_account_ref', v_blocked_funds_account_ref,
      'last_funds_check_at_utc', CASE WHEN v_batch.last_funds_check_at_utc IS NULL THEN NULL ELSE v_batch.last_funds_check_at_utc::text END,
      'last_funds_check_json', v_batch.last_funds_check_json,
      'alert_fingerprint', v_banking_alert_fingerprint,
      'no_submission_evidence_flags', v_no_submission_evidence_flags
    );

    v_payment_issues := jsonb_build_array(v_blocked_funds_payment_issue);
  END IF;

  IF v_provider_submit_issue_present AND v_provider_submit_payment_issue IS NOT NULL THEN
    v_payment_issues := COALESCE(v_payment_issues, '[]'::jsonb) || jsonb_build_array(v_provider_submit_payment_issue);

    v_payment_correction := v_payment_correction || jsonb_build_object(
      'provider_submit_review_issue', v_provider_submit_payment_issue,
      'payment_execution_review', v_payment_execution_review,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'payment_issues', v_payment_issues,
      'provider_submit_review_action_required', true,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', v_provider_submit_is_diagnostic_only,
      'requires_user_action', true
    );
  END IF;


  if v_has_cloudtms_csv_export = true then
    if v_execution_commit_state = 'COMMITTED'
       or v_batch_status_upper in ('COMMITTED','PAID','SETTLED')
       or v_has_external_submission_evidence = true then
      v_csv_comparison_transfer_hash := coalesce(v_execution_transfer_hash, v_stable_transfer_hash, v_pending_transfer_hash);
      v_csv_export_match_basis := case
        when v_execution_transfer_hash is not null then 'EXECUTION_INTENT_CURRENT_TRANSFER_HASH'
        when v_stable_transfer_hash is not null then 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH'
        when v_pending_transfer_hash is not null then 'PENDING_TRANSFER_HASH'
        else 'NO_TRANSFER_HASH_AVAILABLE'
      end;
    else
      v_csv_comparison_transfer_hash := coalesce(v_pending_transfer_hash, v_stable_transfer_hash, v_execution_transfer_hash);
      v_csv_export_match_basis := case
        when v_pending_transfer_hash is not null then 'PENDING_TRANSFER_HASH'
        when v_stable_transfer_hash is not null then 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH'
        when v_execution_transfer_hash is not null then 'EXECUTION_INTENT_CURRENT_TRANSFER_HASH'
        else 'NO_TRANSFER_HASH_AVAILABLE'
      end;
    end if;
  else
    v_csv_comparison_transfer_hash := coalesce(v_pending_transfer_hash, v_stable_transfer_hash, v_execution_transfer_hash);
    v_csv_export_match_basis := 'NO_CLOUDTMS_CSV_EXPORT';
  end if;

  v_current_transfer_hash := v_csv_comparison_transfer_hash;
  v_csv_export_matches_current_transfers := (
    v_has_cloudtms_csv_export = true
    and v_bank_csv_export_hash is not null
    and v_csv_comparison_transfer_hash is not null
    and v_bank_csv_export_hash = v_csv_comparison_transfer_hash
  );

  if v_active_auth_execution_intent_json is not null then
    v_execution_mode_pending := upper(nullif(btrim(coalesce(v_active_auth_execution_intent_json->>'execution_mode','')), ''));
    v_suppress_remittances_pending := lower(btrim(coalesce(v_active_auth_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on');
  elsif v_execution_intent_json is not null and jsonb_typeof(v_execution_intent_json) = 'object' then
    v_execution_mode_pending := upper(nullif(btrim(coalesce(v_execution_intent_json->>'execution_mode','')), ''));
    v_suppress_remittances_pending := lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on');
  else
    v_execution_mode_pending := null;
    v_suppress_remittances_pending := false;
  end if;

  v_can_create_bank_csv_file := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
  );
  v_can_start_standard_execution := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_provider_normalized <> 'CSV'
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );
  v_can_start_csv_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
    and v_has_cloudtms_csv_export = true
    and v_csv_export_matches_current_transfers = true
  );
  v_can_start_external_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );

  IF v_provider_submit_issue_present AND COALESCE(v_provider_submit_safe_retry_available, false) IS NOT TRUE THEN
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;

  -- Items returned for audit/debug and UI fallback
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbi.id::text,
        'pay_batch_candidate_id', pbi.pay_batch_candidate_id::text,
        'item_type', pbi.item_type,
        'timesheet_id', case when pbi.timesheet_id is null then null else pbi.timesheet_id::text end,
        'segment_key', pbi.segment_key,
        'source_ref', pbi.source_ref,
        'description', pbi.description,
        'finance_case_id', case when pbi.finance_case_id is null then null else pbi.finance_case_id::text end,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'reservation_id', case when pbi.reservation_id is null then null else pbi.reservation_id::text end,
        'frozen_component_snapshot_json', pbi.frozen_component_snapshot_json,
        'frozen_component_key_type', pbi.frozen_component_key_type,
        'frozen_component_key_value', pbi.frozen_component_key_value,
        'frozen_component_classification', case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end,
        'frozen_source_basis_json', pbi.frozen_source_basis_json,
        'frozen_source_pay_method', pbi.frozen_source_pay_method,
        'frozen_target_pay_method', pbi.frozen_target_pay_method,
        'frozen_resolution_mode', case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end,
        'frozen_resolution_payload_json', pbi.frozen_resolution_payload_json,
        'frozen_resolution_result_json', pbi.frozen_resolution_result_json,
        'frozen_source_amount', pbi.frozen_source_amount,
        'frozen_target_amount_ex_vat', pbi.frozen_target_amount_ex_vat,
        'frozen_target_amount_vat', pbi.frozen_target_amount_vat,
        'frozen_target_amount_inc_vat', pbi.frozen_target_amount_inc_vat,
        'payout_instruction_snapshot_json', pbi.payout_instruction_snapshot_json,
        'paye_treatment', pbi.paye_treatment,
        'is_voided', coalesce(pbi.is_voided, false),
        'amount_ex_vat', pbi.amount_ex_vat,
        'amount_vat', pbi.amount_vat,
        'amount_inc_vat', pbi.amount_inc_vat,
        'pay_channel', pbi.pay_channel,
        'umbrella_id', case when pbi.umbrella_id is null then null else pbi.umbrella_id::text end,
        'pay_bank_transfer_id', case when pbi.pay_bank_transfer_id is null then null else pbi.pay_bank_transfer_id::text end,
        'repayment_week_start', case when pbi.repayment_week_start is null then null else pbi.repayment_week_start::text end
      )
      order by pbi.pay_batch_candidate_id, pbi.id
    ),
    '[]'::jsonb
  )
  into v_items
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc2
    on pbc2.id = pbi.pay_batch_candidate_id
  where pbc2.pay_batch_id = p_pay_batch_id;

  -- ✅ NEW: candidate_breakdown for child modal (aggregates + status rollup)
  with cand as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      pbc.candidate_tms_ref,
      pbc.candidate_display_name,
      pbc.paye_state,
      pbc.gross_preview,
      pbc.awaiting_net_amount,
      pbc.net_bank_amount,
      pbc.overpayment_recovery_taken,
      pbc.loan_repayment_taken,
      pbc.remittance_sent_at_utc,
      pbc.remittance_sent_by_user_id,
      pbc.remittance_trigger_status,
      pbc.last_remittance_error,
      ce.total_item_count,
      ce.active_effective_item_count,
      ce.active_effective_amount_ex_vat,
      ce.active_effective_amount_inc_vat,
      ce.original_frozen_amount_ex_vat,
      ce.original_frozen_amount_inc_vat,
      ce.applied_precancel_item_count,
      ce.applied_unwind_item_count,
      ce.applied_reversal_item_count,
      ce.corrected_item_count,
      ce.payment_issue_badge,
      ce.payment_issue_label,
      ce.payment_issue_kinds,
      ce.current_effective_zero
    from public.pay_batch_candidates pbc
    left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
      on ce.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  ni as (
    select
      pbc.id as pay_batch_candidate_id,
      pni.net_amount,
      pni.source,
      pni.imported_at_utc,
      pni.file_name
    from public.pay_batch_candidates pbc
    left join lateral (
      select
        pni0.net_amount,
        pni0.source,
        pni0.imported_at_utc,
        pni0.file_name
      from public.pay_batch_paye_net_inputs pni0
      where pni0.pay_batch_candidate_id = pbc.id
      order by pni0.imported_at_utc desc
      limit 1
    ) pni on true
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  sums as (
    select
      pbc.id as pay_batch_candidate_id,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then coalesce(pbi.amount_ex_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as paye_total_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then coalesce(pbi.amount_inc_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as umbrella_total_inc_vat
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  fs as (
    select
      pbc.id as pay_batch_candidate_id,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_recovery,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_net_deductions,
      round(coalesce(sum(case when pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as payment_advance_repayment,
      round(coalesce(sum(case when pbi.item_type = 'OVERPAYMENT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as overpayment_recovery,
      round(coalesce(sum(case when (pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') or (pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as repayment
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  tr as (
    select
      pbc.id as pay_batch_candidate_id,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
      )::int as total_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'BLOCKED'
      )::int as blocked_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'FAILED'
      )::int as failed_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'COMPLETED'
      )::int as completed_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'PENDING'
      )::int as pending_transfers
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', c.pay_batch_candidate_id::text,
        'candidate_id', c.candidate_id::text,
        'candidate_tms_ref', c.candidate_tms_ref,
        'candidate_display_name', c.candidate_display_name,
        'batch_kind', v_batch_kind,
        'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
        'paye_state', c.paye_state,
        'paye_net_amount', n.net_amount,
        'paye_net_source', n.source,
        'paye_net_imported_at_utc', n.imported_at_utc,
        'paye_net_file_name', n.file_name,
        'awaiting_net_amount',
          (case
            when v_batch_kind_fixed = 'LOANS' then false
            when v_batch_kind = 'PAYE' then (n.net_amount is null)
            else false
          end),
        'overpayment_recovery_taken', c.overpayment_recovery_taken,
        'loan_repayment_taken', c.loan_repayment_taken,
        'remittance_sent_at_utc', c.remittance_sent_at_utc,
        'remittance_sent_by_user_id', case when c.remittance_sent_by_user_id is null then null else c.remittance_sent_by_user_id::text end,
        'remittance_trigger_status', c.remittance_trigger_status,
        'last_remittance_error', c.last_remittance_error,
        'original_gross_preview', c.gross_preview,
        'original_net_bank_amount', c.net_bank_amount,
        'current_effective_item_count', coalesce(c.active_effective_item_count, 0),
        'active_effective_item_count', coalesce(c.active_effective_item_count, 0),
        'total_item_count', coalesce(c.total_item_count, 0),
        'current_effective_amount_ex_vat', coalesce(c.active_effective_amount_ex_vat, 0),
        'current_effective_amount_inc_vat', coalesce(c.active_effective_amount_inc_vat, 0),
        'original_frozen_amount_ex_vat', coalesce(c.original_frozen_amount_ex_vat, 0),
        'original_frozen_amount_inc_vat', coalesce(c.original_frozen_amount_inc_vat, 0),
        'payment_issue_badge', coalesce(c.payment_issue_badge, false),
        'payment_issue_badge_label', case when coalesce(c.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
        'payment_issue_label', c.payment_issue_label,
        'payment_issue_kinds', coalesce(c.payment_issue_kinds, '[]'::jsonb),
        'applied_precancel_item_count', coalesce(c.applied_precancel_item_count, 0),
        'applied_unwind_item_count', coalesce(c.applied_unwind_item_count, 0),
        'applied_reversal_item_count', coalesce(c.applied_reversal_item_count, 0),
        'corrected_item_count', coalesce(c.corrected_item_count, 0),
        'final_net_paid', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.net_bank_amount end,
        'deductions_summary', jsonb_build_object(
          'gross_positive', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.gross_preview end,
          'manual_debt_recovery', coalesce(fs.manual_debt_recovery,0),
          'manual_debt_net_deductions', coalesce(fs.manual_debt_net_deductions,0),
          'payment_advance_repayment', coalesce(fs.payment_advance_repayment,0),
          'loan_repayment', coalesce(fs.payment_advance_repayment,0),
          'repayment', coalesce(fs.repayment,0),
          'overpayment_recovery', coalesce(fs.overpayment_recovery,0),
          'final_payable', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.net_bank_amount end,
          'awaiting_net_amount', case when v_batch_kind_fixed = 'LOANS' then false else coalesce(c.awaiting_net_amount, false) end,
          'paye_net_amount', n.net_amount
        ),
        'finance_summary', jsonb_build_object(
          'gross_additions_ex_vat', coalesce(fs.gross_additions_ex_vat,0),
          'gross_deductions_ex_vat', coalesce(fs.gross_deductions_ex_vat,0),
          'net_deductions_ex_vat', coalesce(fs.net_deductions_ex_vat,0)
        ),
        'paye_total_ex_vat', s.paye_total_ex_vat,
        'umbrella_total_inc_vat', s.umbrella_total_inc_vat,
        'payment_amount',
          (case
            when coalesce(c.current_effective_zero, false) then 0::numeric
            when v_batch_kind = 'PAYE' then s.paye_total_ex_vat
            when v_batch_kind = 'UMBRELLA' then s.umbrella_total_inc_vat
            else round(coalesce(s.paye_total_ex_vat,0) + coalesce(s.umbrella_total_inc_vat,0),2)
          end),
        'transfer_rollup', jsonb_build_object(
          'total', tr0.total_transfers,
          'pending', tr0.pending_transfers,
          'blocked', tr0.blocked_transfers,
          'failed', tr0.failed_transfers,
          'completed', tr0.completed_transfers
        ),
        'payment_status',
          (case
            when coalesce(c.payment_issue_badge, false) and coalesce(c.active_effective_item_count, 0) = 0 then 'PAYMENT_ISSUE'
            when coalesce(c.payment_issue_badge, false) then 'PAYMENT_ISSUE_PARTIAL'
            when coalesce(tr0.total_transfers,0) = 0 then 'DRAFT'
            when coalesce(tr0.blocked_transfers,0) > 0 then 'BLOCKED'
            when coalesce(tr0.failed_transfers,0) > 0 then 'FAILED'
            when coalesce(tr0.completed_transfers,0) = coalesce(tr0.total_transfers,0) then 'PAID'
            else 'PENDING'
          end)
      )
      order by c.candidate_display_name nulls last, c.candidate_tms_ref nulls last, c.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidate_breakdown
  from cand c
  left join ni n
    on n.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join sums s
    on s.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join fs
    on fs.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join tr tr0
    on tr0.pay_batch_candidate_id = c.pay_batch_candidate_id;

  -- ✅ UPDATED: candidate_lines for expandable table
  -- HARD RULE: do NOT derive units/rate from total_hours; use canonical pay_batch_item_breakdowns.
  with pbci as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      pbc.candidate_display_name,
      pbc.candidate_tms_ref,
      ce.total_item_count,
      ce.active_effective_item_count,
      ce.payment_issue_badge,
      ce.payment_issue_label,
      ce.payment_issue_kinds,
      ce.corrected_item_count
    from public.pay_batch_candidates pbc
    left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
      on ce.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  ts_groups as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.timesheet_id as timesheet_id,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,''))='PAYE' then coalesce(pbi.amount_ex_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as subtotal_paye_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,''))='UMBRELLA' then coalesce(pbi.amount_inc_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as subtotal_umbrella_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is not null
    group by pbc.id, pbc.candidate_id, pbi.timesheet_id
  ),
  ts_enriched as (
    select
      tg.pay_batch_candidate_id,
      tg.candidate_id,
      tg.timesheet_id,
      vts.week_ending_date,
      vts.client_id,
      vts.client_name,
      nullif(btrim(coalesce(vts.hospital_norm,'')), '') as hospital_norm,
      tg.subtotal_paye_ex_vat,
      tg.subtotal_umbrella_inc_vat,
      case
        when v_batch_kind = 'PAYE' then tg.subtotal_paye_ex_vat
        when v_batch_kind = 'UMBRELLA' then tg.subtotal_umbrella_inc_vat
        else round(coalesce(tg.subtotal_paye_ex_vat,0) + coalesce(tg.subtotal_umbrella_inc_vat,0),2)
      end as payment_amount
    from ts_groups tg
    left join public.v_timesheets_summary_base vts
      on vts.timesheet_id = tg.timesheet_id
  ),
  ts_breakdown_rows as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.timesheet_id as timesheet_id,
      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.rate as rate,
      case
        when bool_and(pbib.units is null) then null::numeric
        else round(sum(coalesce(pbib.units,0)),2)
      end as units,
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) as amount_ex_vat,
      round(coalesce(sum(coalesce(pbib.amount_vat,0)),0),2) as amount_vat,
      round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) as amount_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = pbi.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is not null
    group by
      pbc.id,
      pbc.candidate_id,
      pbi.timesheet_id,
      pbib.line_kind,
      pbib.bucket_code,
      pbib.unit_name,
      pbib.rate
    having
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) <> 0
      or round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) <> 0
      or (case when bool_and(pbib.units is null) then 0 else round(sum(coalesce(pbib.units,0)),2) end) <> 0
  ),
  ts_breakdown_json as (
    select
      tbr.pay_batch_candidate_id,
      tbr.candidate_id,
      tbr.timesheet_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'line_kind', tbr.line_kind,
            'bucket_code', tbr.bucket_code,
            'unit_name', tbr.unit_name,
            'units', tbr.units,
            'rate', tbr.rate,
            'amount_ex_vat', tbr.amount_ex_vat,
            'amount_vat', tbr.amount_vat,
            'amount_inc_vat', tbr.amount_inc_vat
          )
          order by
            case upper(coalesce(tbr.line_kind,''))
              when 'TS_BUCKET' then 1
              when 'ADDITIONAL_UNIT' then 2
              when 'MILEAGE' then 3
              when 'EXPENSE' then 4
              when 'ADJUSTMENT' then 5
              when 'CONVERSION_ADJ' then 6
              when 'LOAN_REPAYMENT' then 7
              when 'DEBT_CREATED' then 8
              else 99
            end,
            case upper(coalesce(tbr.bucket_code,''))
              when 'DAY' then 1
              when 'NIGHT' then 2
              when 'SAT' then 3
              when 'SUN' then 4
              when 'BH' then 5
              else 99
            end,
            coalesce(tbr.unit_name,'') asc,
            coalesce(tbr.rate,0) asc
        ),
        '[]'::jsonb
      ) as breakdown_lines
    from ts_breakdown_rows tbr
    group by tbr.pay_batch_candidate_id, tbr.candidate_id, tbr.timesheet_id
  ),
  ts_lines as (
    select
      te.pay_batch_candidate_id,
      te.candidate_id,
      jsonb_build_object(
        'timesheet_id', te.timesheet_id::text,
        'week_ending_date', case when te.week_ending_date is null then null else te.week_ending_date::text end,
        'client_id', case when te.client_id is null then null else te.client_id::text end,
        'client_name', te.client_name,
        'hospital_norm', te.hospital_norm,
        'subtotal_paye_ex_vat', te.subtotal_paye_ex_vat,
        'subtotal_umbrella_inc_vat', te.subtotal_umbrella_inc_vat,
        'payment_amount', te.payment_amount,
        'breakdown_lines', coalesce(tbj.breakdown_lines, '[]'::jsonb)
      ) as ts_line
    from ts_enriched te
    left join ts_breakdown_json tbj
      on tbj.pay_batch_candidate_id = te.pay_batch_candidate_id
     and tbj.timesheet_id = te.timesheet_id
  ),
  non_ts_detail as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type as item_type,
      pbi.source_ref as source_ref,
      pbi.repayment_week_start as repayment_week_start,
      pbi.finance_case_id as finance_case_id,
      pbi.paye_treatment as paye_treatment,
      coalesce(pbi.is_voided, false) as is_voided,
      pbi.description as description,
      upper(coalesce(pbi.pay_channel::text,'')) as pay_channel_txt,
      case when pbi.umbrella_id is null then null else pbi.umbrella_id::text end as umbrella_id_txt,
      coalesce(
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'taxability','')), ''),
        case when vfcr.taxability is null then null else vfcr.taxability::text end
      ) as taxability_txt,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') is not null
          then nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '')
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'NORMAL_PAY_ROUTE'
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'UMBRELLA_COMPANY'
        else case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end
      end as routing_kind_txt,
      coalesce(
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'destination_label','')), ''),
        case
          when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'UMBRELLA_COMPANY' then 'umbrella company'
          when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
          when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'normal PAYE route'
          when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'umbrella company'
          when case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end = 'UMBRELLA_COMPANY' then 'umbrella company'
          when case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
          else null
        end
      ) as destination_label,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'masked_bank_account','')), '') as masked_bank_account,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), '') as beneficiary_name,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as bank_details_hash,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_note','')), '') as bank_details_note,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'is_candidate_directed_oneoff_payout'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.is_candidate_directed_oneoff_payout, false)
      end as is_candidate_directed_oneoff_payout,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_created_by_user_id,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_updated_by_user_id,
      tuc.display_name as bank_details_created_by_display_name,
      tuc.email as bank_details_created_by_email,
      tuu.display_name as bank_details_updated_by_display_name,
      tuu.email as bank_details_updated_by_email,
      case when vfcr.management_group is null then null else vfcr.management_group::text end as management_group,
      vfcr.lifecycle_status_display as lifecycle_status_display,
      vfcr.status as finance_case_status,
      vfcr.payout_status as finance_payout_status,
      coalesce(vfcr.edit_bank_details_allowed, false) as edit_bank_details_allowed,
      pbi.amount_ex_vat as amount_ex_vat,
      pbi.amount_vat as amount_vat,
      pbi.amount_inc_vat as amount_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    left join public.tms_users tuc
      on tuc.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end
    left join public.tms_users tuu
      on tuu.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is null
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  non_ts_groups as (
    select
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type as item_type,
      ntd.source_ref as source_ref,
      ntd.repayment_week_start as repayment_week_start,
      ntd.finance_case_id as finance_case_id,
      max(case when ntd.paye_treatment is null then null else ntd.paye_treatment::text end) as paye_treatment,
      bool_or(coalesce(ntd.is_voided, false)) as is_voided,
      max(ntd.description) as description,
      max(ntd.pay_channel_txt) as pay_channel_txt,
      max(ntd.umbrella_id_txt) as umbrella_id_txt,
      max(ntd.taxability_txt) as taxability_txt,
      max(ntd.routing_kind_txt) as routing_kind_txt,
      max(ntd.destination_label) as destination_label,
      max(ntd.masked_bank_account) as masked_bank_account,
      max(ntd.beneficiary_name) as beneficiary_name,
      max(ntd.bank_details_hash) as bank_details_hash,
      max(ntd.bank_details_note) as bank_details_note,
      max(case when ntd.bank_details_created_by_user_id is null then null else ntd.bank_details_created_by_user_id::text end) as bank_details_created_by_user_id,
      max(ntd.bank_details_created_by_display_name) as bank_details_created_by_display_name,
      max(ntd.bank_details_created_by_email) as bank_details_created_by_email,
      max(case when ntd.bank_details_updated_by_user_id is null then null else ntd.bank_details_updated_by_user_id::text end) as bank_details_updated_by_user_id,
      max(ntd.bank_details_updated_by_display_name) as bank_details_updated_by_display_name,
      max(ntd.bank_details_updated_by_email) as bank_details_updated_by_email,
      bool_or(ntd.appears_on_umbrella_remittance) as appears_on_umbrella_remittance,
      bool_or(ntd.generates_candidate_payment_advice) as generates_candidate_payment_advice,
      bool_or(ntd.is_candidate_directed_oneoff_payout) as is_candidate_directed_oneoff_payout,
      max(ntd.management_group) as management_group,
      max(ntd.lifecycle_status_display) as lifecycle_status_display,
      max(ntd.finance_case_status) as finance_case_status,
      max(ntd.finance_payout_status) as finance_payout_status,
      bool_or(coalesce(ntd.edit_bank_details_allowed, false)) as edit_bank_details_allowed,
      round(coalesce(sum(case when ntd.pay_channel_txt = 'PAYE' then coalesce(ntd.amount_ex_vat,0) else 0 end),0),2) as subtotal_paye_ex_vat,
      round(coalesce(sum(case when ntd.pay_channel_txt = 'UMBRELLA' then coalesce(ntd.amount_inc_vat,0) else 0 end),0),2) as subtotal_umbrella_inc_vat
    from non_ts_detail ntd
    group by
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type,
      ntd.source_ref,
      ntd.repayment_week_start,
      ntd.finance_case_id,
      ntd.taxability_txt,
      ntd.routing_kind_txt,
      ntd.destination_label,
      ntd.masked_bank_account,
      ntd.beneficiary_name,
      ntd.bank_details_hash,
      ntd.bank_details_note,
      ntd.bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name,
      ntd.bank_details_created_by_email,
      ntd.bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email
  ),
  non_ts_breakdown_rows as (
    select
      ntd.pay_batch_candidate_id,
      ntd.candidate_id as candidate_id,
      ntd.item_type as item_type,
      ntd.source_ref as source_ref,
      ntd.repayment_week_start as repayment_week_start,
      ntd.finance_case_id as finance_case_id,
      ntd.taxability_txt as taxability_txt,
      ntd.routing_kind_txt as routing_kind_txt,
      ntd.destination_label as destination_label,
      ntd.masked_bank_account as masked_bank_account,
      ntd.beneficiary_name as beneficiary_name,
      ntd.bank_details_hash as bank_details_hash,
      ntd.bank_details_note as bank_details_note,
      case when ntd.bank_details_created_by_user_id is null then null else ntd.bank_details_created_by_user_id::text end as bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name as bank_details_created_by_display_name,
      ntd.bank_details_created_by_email as bank_details_created_by_email,
      case when ntd.bank_details_updated_by_user_id is null then null else ntd.bank_details_updated_by_user_id::text end as bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name as bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email as bank_details_updated_by_email,
      ntd.appears_on_umbrella_remittance as appears_on_umbrella_remittance,
      ntd.generates_candidate_payment_advice as generates_candidate_payment_advice,
      ntd.is_candidate_directed_oneoff_payout as is_candidate_directed_oneoff_payout,
      ntd.management_group as management_group,
      ntd.lifecycle_status_display as lifecycle_status_display,
      ntd.finance_case_status as finance_case_status,
      ntd.finance_payout_status as finance_payout_status,
      ntd.edit_bank_details_allowed as edit_bank_details_allowed,
      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.rate as rate,
      case
        when bool_and(pbib.units is null) then null::numeric
        else round(sum(coalesce(pbib.units,0)),2)
      end as units,
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) as amount_ex_vat,
      round(coalesce(sum(coalesce(pbib.amount_vat,0)),0),2) as amount_vat,
      round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) as amount_inc_vat
    from non_ts_detail ntd
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = ntd.pay_batch_item_id
    group by
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type,
      ntd.source_ref,
      ntd.repayment_week_start,
      ntd.finance_case_id,
      ntd.taxability_txt,
      ntd.routing_kind_txt,
      ntd.destination_label,
      ntd.masked_bank_account,
      ntd.beneficiary_name,
      ntd.bank_details_hash,
      ntd.bank_details_note,
      ntd.bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name,
      ntd.bank_details_created_by_email,
      ntd.bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email,
      ntd.appears_on_umbrella_remittance,
      ntd.generates_candidate_payment_advice,
      ntd.is_candidate_directed_oneoff_payout,
      ntd.management_group,
      ntd.lifecycle_status_display,
      ntd.finance_case_status,
      ntd.finance_payout_status,
      ntd.edit_bank_details_allowed,
      pbib.line_kind,
      pbib.bucket_code,
      pbib.unit_name,
      pbib.rate
  ),
  non_ts_breakdown_json as (
    select
      ntr.pay_batch_candidate_id,
      ntr.candidate_id,
      ntr.item_type,
      ntr.source_ref,
      ntr.repayment_week_start,
      ntr.finance_case_id,
      ntr.taxability_txt,
      ntr.routing_kind_txt,
      ntr.destination_label,
      ntr.masked_bank_account,
      ntr.beneficiary_name,
      ntr.bank_details_hash,
      ntr.bank_details_note,
      ntr.bank_details_created_by_user_id,
      ntr.bank_details_created_by_display_name,
      ntr.bank_details_created_by_email,
      ntr.bank_details_updated_by_user_id,
      ntr.bank_details_updated_by_display_name,
      ntr.bank_details_updated_by_email,
      ntr.appears_on_umbrella_remittance,
      ntr.generates_candidate_payment_advice,
      ntr.is_candidate_directed_oneoff_payout,
      ntr.management_group,
      ntr.lifecycle_status_display,
      ntr.finance_case_status,
      ntr.finance_payout_status,
      ntr.edit_bank_details_allowed,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'line_kind', ntr.line_kind,
            'bucket_code', ntr.bucket_code,
            'unit_name', ntr.unit_name,
            'units', ntr.units,
            'rate', ntr.rate,
            'amount_ex_vat', ntr.amount_ex_vat,
            'amount_vat', ntr.amount_vat,
            'amount_inc_vat', ntr.amount_inc_vat
          )
          order by
            case upper(coalesce(ntr.line_kind,''))
              when 'TS_BUCKET' then 1
              when 'ADDITIONAL_UNIT' then 2
              when 'MILEAGE' then 3
              when 'EXPENSE' then 4
              when 'ADJUSTMENT' then 5
              when 'CONVERSION_ADJ' then 6
              when 'LOAN_REPAYMENT' then 7
              when 'DEBT_CREATED' then 8
              else 99
            end,
            coalesce(ntr.unit_name,'') asc
        ),
        '[]'::jsonb
      ) as breakdown_lines
    from non_ts_breakdown_rows ntr
    group by
      ntr.pay_batch_candidate_id,
      ntr.candidate_id,
      ntr.item_type,
      ntr.source_ref,
      ntr.repayment_week_start,
      ntr.finance_case_id,
      ntr.taxability_txt,
      ntr.routing_kind_txt,
      ntr.destination_label,
      ntr.masked_bank_account,
      ntr.beneficiary_name,
      ntr.bank_details_hash,
      ntr.bank_details_note,
      ntr.bank_details_created_by_user_id,
      ntr.bank_details_created_by_display_name,
      ntr.bank_details_created_by_email,
      ntr.bank_details_updated_by_user_id,
      ntr.bank_details_updated_by_display_name,
      ntr.bank_details_updated_by_email,
      ntr.appears_on_umbrella_remittance,
      ntr.generates_candidate_payment_advice,
      ntr.is_candidate_directed_oneoff_payout,
      ntr.management_group,
      ntr.lifecycle_status_display,
      ntr.finance_case_status,
      ntr.finance_payout_status,
      ntr.edit_bank_details_allowed
  ),
  candidate_destination_rollup as (
    select
      pbc.id as pay_batch_candidate_id,
      count(distinct
        case
          when pbi.item_type = 'DEBT_CREATED' then null
          when pbi.timesheet_id is not null then
            case
              when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'NORMAL_PAYE_ROUTE'
              when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              else 'ROUTE|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL') || '|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
            end
          else
            case
              when coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then
                'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''), 'NO_HASH')
                || '|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL')
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), 'NO_BENEFICIARY')
              when coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = 'UMBRELLA_COMPANY' then
                'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then
                'NORMAL_PAYE_ROUTE'
              when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' and coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = '' then
                'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              else
                coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), 'NO_ROUTING')
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''), 'NO_HASH')
                || '|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL')
                || '|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
            end
        end
      )::int as destination_count
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  non_ts_lines as (
    select
      ng.pay_batch_candidate_id,
      ng.candidate_id,
      jsonb_build_object(
        'item_type', ng.item_type,
        'source_ref', ng.source_ref,
        'finance_case_id', case when ng.finance_case_id is null then null else ng.finance_case_id::text end,
        'paye_treatment', ng.paye_treatment,
        'is_voided', ng.is_voided,
        'finance_case_reference', coalesce(ng.source_ref, case when ng.finance_case_id is null then null else ng.finance_case_id::text end),
        'repayment_week_start', case when ng.repayment_week_start is null then null else ng.repayment_week_start::text end,
        'week_ending_date', case when ng.repayment_week_start is null then null else (ng.repayment_week_start + 6)::text end,
        'description', ng.description,
        'pay_channel', ng.pay_channel_txt,
        'umbrella_id', ng.umbrella_id_txt,
        'taxability', ng.taxability_txt,
        'routing_kind', ng.routing_kind_txt,
        'destination_label', ng.destination_label,
        'payout_destination', ng.destination_label,
        'masked_bank_account', ng.masked_bank_account,
        'beneficiary_name', ng.beneficiary_name,
        'bank_details_hash', ng.bank_details_hash,
        'bank_details_note', ng.bank_details_note,
        'bank_details_created_by_user_id', ng.bank_details_created_by_user_id,
        'bank_details_created_by_display_name', ng.bank_details_created_by_display_name,
        'bank_details_created_by_email', ng.bank_details_created_by_email,
        'bank_details_updated_by_user_id', ng.bank_details_updated_by_user_id,
        'bank_details_updated_by_display_name', ng.bank_details_updated_by_display_name,
        'bank_details_updated_by_email', ng.bank_details_updated_by_email,
        'appears_on_umbrella_remittance', ng.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', ng.generates_candidate_payment_advice,
        'is_candidate_directed_oneoff_payout', ng.is_candidate_directed_oneoff_payout,
        'management_group', ng.management_group,
        'lifecycle_status_display', ng.lifecycle_status_display,
        'finance_case_status', ng.finance_case_status,
        'finance_payout_status', ng.finance_payout_status,
        'edit_bank_details_allowed', ng.edit_bank_details_allowed,
        'communication_kind',
          case
            when ng.generates_candidate_payment_advice then 'PAYOUT_NOTICE'
            when ng.appears_on_umbrella_remittance then 'REMITTANCE'
            else null
          end,
        'destination_group_key',
          coalesce(ng.routing_kind_txt, 'NO_ROUTING')
          || '|' || coalesce(ng.bank_details_hash, 'NO_HASH')
          || '|' || coalesce(ng.pay_channel_txt, 'NO_CHANNEL')
          || '|' || coalesce(ng.destination_label, 'NO_DESTINATION')
          || '|' || coalesce(ng.beneficiary_name, 'NO_BENEFICIARY'),
        'candidate_has_multiple_payment_destinations', coalesce(cdr.destination_count,0) > 1,
        'is_separate_destination_payment', (coalesce(cdr.destination_count,0) > 1 and nullif(btrim(coalesce(ng.destination_label,'')), '') is not null),
        'different_destination_marker', (coalesce(cdr.destination_count,0) > 1 and nullif(btrim(coalesce(ng.destination_label,'')), '') is not null),
        'subtotal_paye_ex_vat', ng.subtotal_paye_ex_vat,
        'subtotal_umbrella_inc_vat', ng.subtotal_umbrella_inc_vat,
        'payment_amount',
          case
            when v_batch_kind = 'PAYE' then ng.subtotal_paye_ex_vat
            when v_batch_kind = 'UMBRELLA' then ng.subtotal_umbrella_inc_vat
            else round(coalesce(ng.subtotal_paye_ex_vat,0) + coalesce(ng.subtotal_umbrella_inc_vat,0),2)
          end,
        'breakdown_lines', coalesce(ntbj.breakdown_lines, '[]'::jsonb)
      ) as non_ts_line
    from non_ts_groups ng
    left join non_ts_breakdown_json ntbj
      on ntbj.pay_batch_candidate_id = ng.pay_batch_candidate_id
     and ntbj.item_type = ng.item_type
     and ntbj.source_ref is not distinct from ng.source_ref
     and ntbj.repayment_week_start is not distinct from ng.repayment_week_start
     and ntbj.finance_case_id is not distinct from ng.finance_case_id
     and ntbj.taxability_txt is not distinct from ng.taxability_txt
     and ntbj.routing_kind_txt is not distinct from ng.routing_kind_txt
     and ntbj.destination_label is not distinct from ng.destination_label
     and ntbj.masked_bank_account is not distinct from ng.masked_bank_account
     and ntbj.beneficiary_name is not distinct from ng.beneficiary_name
     and ntbj.bank_details_hash is not distinct from ng.bank_details_hash
     and ntbj.bank_details_note is not distinct from ng.bank_details_note
     and ntbj.bank_details_created_by_user_id is not distinct from ng.bank_details_created_by_user_id
     and ntbj.bank_details_created_by_display_name is not distinct from ng.bank_details_created_by_display_name
     and ntbj.bank_details_created_by_email is not distinct from ng.bank_details_created_by_email
     and ntbj.bank_details_updated_by_user_id is not distinct from ng.bank_details_updated_by_user_id
     and ntbj.bank_details_updated_by_display_name is not distinct from ng.bank_details_updated_by_display_name
     and ntbj.bank_details_updated_by_email is not distinct from ng.bank_details_updated_by_email
     and ntbj.appears_on_umbrella_remittance is not distinct from ng.appears_on_umbrella_remittance
     and ntbj.generates_candidate_payment_advice is not distinct from ng.generates_candidate_payment_advice
     and ntbj.is_candidate_directed_oneoff_payout is not distinct from ng.is_candidate_directed_oneoff_payout
     and ntbj.management_group is not distinct from ng.management_group
     and ntbj.lifecycle_status_display is not distinct from ng.lifecycle_status_display
     and ntbj.finance_case_status is not distinct from ng.finance_case_status
     and ntbj.finance_payout_status is not distinct from ng.finance_payout_status
     and ntbj.edit_bank_details_allowed is not distinct from ng.edit_bank_details_allowed
    left join candidate_destination_rollup cdr
      on cdr.pay_batch_candidate_id = ng.pay_batch_candidate_id
  ),
  ts_lines_agg as (
    select
      ts.pay_batch_candidate_id,
      ts.candidate_id,
      coalesce(
        jsonb_agg(
          ts.ts_line
          order by (ts.ts_line->>'week_ending_date')::date desc nulls last, ts.ts_line->>'timesheet_id'
        ),
        '[]'::jsonb
      ) as ts_lines
    from ts_lines ts
    group by ts.pay_batch_candidate_id, ts.candidate_id
  ),
  non_ts_lines_agg as (
    select
      nt.pay_batch_candidate_id,
      nt.candidate_id,
      coalesce(
        jsonb_agg(
          nt.non_ts_line
          order by nt.non_ts_line->>'item_type', nt.non_ts_line->>'source_ref', nt.non_ts_line->>'payout_destination', nt.non_ts_line->>'masked_bank_account', nt.non_ts_line->>'beneficiary_name'
        ),
        '[]'::jsonb
      ) as non_ts_lines
    from non_ts_lines nt
    group by nt.pay_batch_candidate_id, nt.candidate_id
  ),
  cand_lines as (
    select
      p.pay_batch_candidate_id,
      p.candidate_id,
      p.candidate_display_name,
      p.candidate_tms_ref,
      p.total_item_count,
      p.active_effective_item_count,
      p.payment_issue_badge,
      p.payment_issue_label,
      p.payment_issue_kinds,
      p.corrected_item_count,
      coalesce(tsa.ts_lines, '[]'::jsonb) as ts_lines,
      coalesce(nta.non_ts_lines, '[]'::jsonb) as non_ts_lines
    from pbci p
    left join ts_lines_agg tsa
      on tsa.pay_batch_candidate_id = p.pay_batch_candidate_id
     and tsa.candidate_id = p.candidate_id
    left join non_ts_lines_agg nta
      on nta.pay_batch_candidate_id = p.pay_batch_candidate_id
     and nta.candidate_id = p.candidate_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', cl.pay_batch_candidate_id::text,
        'candidate_id', cl.candidate_id::text,
        'candidate_display_name', cl.candidate_display_name,
        'candidate_tms_ref', cl.candidate_tms_ref,
        'total_item_count', coalesce(cl.total_item_count, 0),
        'active_effective_item_count', coalesce(cl.active_effective_item_count, 0),
        'current_effective_item_count', coalesce(cl.active_effective_item_count, 0),
        'payment_issue_badge', coalesce(cl.payment_issue_badge, false),
        'payment_issue_badge_label', case when coalesce(cl.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
        'payment_issue_label', cl.payment_issue_label,
        'payment_issue_kinds', coalesce(cl.payment_issue_kinds, '[]'::jsonb),
        'corrected_item_count', coalesce(cl.corrected_item_count, 0),
        'candidate_lines', jsonb_build_object(
          'ts_lines', cl.ts_lines,
          'non_ts_lines', cl.non_ts_lines,
          'payment_issue_badge', coalesce(cl.payment_issue_badge, false),
          'payment_issue_badge_label', case when coalesce(cl.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
          'payment_issue_label', cl.payment_issue_label,
          'payment_issue_kinds', coalesce(cl.payment_issue_kinds, '[]'::jsonb)
        ),
        'ts_lines', cl.ts_lines,
        'non_ts_lines', cl.non_ts_lines
      )
      order by cl.candidate_display_name nulls last, cl.candidate_tms_ref nulls last, cl.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidate_lines
  from cand_lines cl;

  with cand_src as (
    select
      cand.value as cand_json,
      cand.ordinality as cand_ord
    from jsonb_array_elements(v_candidates) with ordinality as cand(value, ordinality)
  ),
  line_src as (
    select
      ln.value as line_json
    from jsonb_array_elements(v_candidate_lines) as ln(value)
  )
  select coalesce(
    jsonb_agg(
      cand_src.cand_json || jsonb_build_object(
        'candidate_lines',
          coalesce(
            (
              select jsonb_build_object(
                'ts_lines', coalesce(line_src.line_json->'ts_lines', '[]'::jsonb),
                'non_ts_lines', coalesce(line_src.line_json->'non_ts_lines', '[]'::jsonb),
                'payment_issue_badge', coalesce((line_src.line_json->>'payment_issue_badge')::boolean, false),
                'payment_issue_badge_label', line_src.line_json->>'payment_issue_badge_label',
                'payment_issue_label', line_src.line_json->>'payment_issue_label',
                'payment_issue_kinds', coalesce(line_src.line_json->'payment_issue_kinds', '[]'::jsonb)
              )
              from line_src
              where coalesce(line_src.line_json->>'pay_batch_candidate_id','') = coalesce(cand_src.cand_json->>'id','')
              limit 1
            ),
            jsonb_build_object(
              'ts_lines', '[]'::jsonb,
              'non_ts_lines', '[]'::jsonb,
              'payment_issue_badge', coalesce((cand_src.cand_json->>'payment_issue_badge')::boolean, false),
              'payment_issue_badge_label', cand_src.cand_json->>'payment_issue_badge_label',
              'payment_issue_label', cand_src.cand_json->>'payment_issue_label',
              'payment_issue_kinds', coalesce(cand_src.cand_json->'payment_issue_kinds', '[]'::jsonb)
            )
          )
      )
      order by cand_src.cand_ord
    ),
    '[]'::jsonb
  )
  into v_candidates
  from cand_src;


  ---------------------------------------------------------------------------
  -- 3.41: Mirror backend-derived payment action diagnostics onto the actual
  -- Overview / Current Payment Status row surfaces.  The candidate array above
  -- is diagnostic-rich, but the Banking child modal commonly reads
  -- candidate_breakdown / candidate_lines directly; do not leave those surfaces
  -- to infer action eligibility from raw rail state.
  ---------------------------------------------------------------------------
  WITH candidate_action_payloads AS (
    SELECT
      candidate_payload.value->>'id' AS pay_batch_candidate_id,
      candidate_payload.value->>'candidate_id' AS candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'payment_lifecycle_state', candidate_payload.value->'payment_lifecycle_state',
        'payment_lifecycle_label', candidate_payload.value->'payment_lifecycle_label',
        'recommended_action', candidate_payload.value->'recommended_action',
        'row_action', candidate_payload.value->'row_action',
        'row_action_label', candidate_payload.value->'row_action_label',
        'retry_row_context', candidate_payload.value->'retry_row_context',
        'row_cancel_available', candidate_payload.value->'row_cancel_available',
        'can_no_money_unwind', candidate_payload.value->'can_no_money_unwind',
        'can_recover_overpayment', candidate_payload.value->'can_recover_overpayment',
        'manual_adjustment_carry_forward_required', candidate_payload.value->'manual_adjustment_carry_forward_required',
        'manual_adjustments_to_carry_forward', candidate_payload.value->'manual_adjustments_to_carry_forward',
        'manual_adjustments_carried_forward', candidate_payload.value->'manual_adjustments_carried_forward',
        'carry_forward_blockers', candidate_payload.value->'carry_forward_blockers',
        'blocking_paid_evidence_json', candidate_payload.value->'blocking_paid_evidence_json',
        'terminal_no_money_evidence_json', candidate_payload.value->'terminal_no_money_evidence_json',
        'pending_provider_evidence_json', candidate_payload.value->'pending_provider_evidence_json',
        'resolved_full_payment_scope_json', candidate_payload.value->'resolved_full_payment_scope_json',
        'finance_scope_json', candidate_payload.value->'finance_scope_json',
        'provider_failure_reason_group', candidate_payload.value->'provider_failure_reason_group',
        'provider_failure_reason_label', candidate_payload.value->'provider_failure_reason_label',
        'status_update_signature', candidate_payload.value->'status_update_signature',
        'provider_outcome_unknown_evidence_json', candidate_payload.value->'provider_outcome_unknown_evidence_json',
        'provider_webhook_evidence_json', candidate_payload.value->'provider_webhook_evidence_json'
      )) AS action_payload
    FROM jsonb_array_elements(COALESCE(v_candidates, '[]'::jsonb)) AS candidate_payload(value)
    WHERE jsonb_typeof(candidate_payload.value) = 'object'
  ),
  breakdown_rows AS (
    SELECT
      breakdown_payload.value AS row_payload,
      breakdown_payload.ordinality AS row_ordinality,
      action_payloads.action_payload
    FROM jsonb_array_elements(COALESCE(v_candidate_breakdown, '[]'::jsonb)) WITH ORDINALITY AS breakdown_payload(value, ordinality)
    LEFT JOIN candidate_action_payloads AS action_payloads
      ON action_payloads.pay_batch_candidate_id = breakdown_payload.value->>'pay_batch_candidate_id'
      OR action_payloads.candidate_id = breakdown_payload.value->>'candidate_id'
  )
  SELECT COALESCE(
    jsonb_agg(
      breakdown_rows.row_payload || COALESCE(breakdown_rows.action_payload, '{}'::jsonb)
      ORDER BY breakdown_rows.row_ordinality
    ),
    '[]'::jsonb
  )
  INTO v_candidate_breakdown
  FROM breakdown_rows;

  WITH candidate_action_payloads AS (
    SELECT
      candidate_payload.value->>'id' AS pay_batch_candidate_id,
      candidate_payload.value->>'candidate_id' AS candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'payment_lifecycle_state', candidate_payload.value->'payment_lifecycle_state',
        'payment_lifecycle_label', candidate_payload.value->'payment_lifecycle_label',
        'recommended_action', candidate_payload.value->'recommended_action',
        'row_action', candidate_payload.value->'row_action',
        'row_action_label', candidate_payload.value->'row_action_label',
        'retry_row_context', candidate_payload.value->'retry_row_context',
        'row_cancel_available', candidate_payload.value->'row_cancel_available',
        'can_no_money_unwind', candidate_payload.value->'can_no_money_unwind',
        'can_recover_overpayment', candidate_payload.value->'can_recover_overpayment',
        'manual_adjustment_carry_forward_required', candidate_payload.value->'manual_adjustment_carry_forward_required',
        'manual_adjustments_to_carry_forward', candidate_payload.value->'manual_adjustments_to_carry_forward',
        'manual_adjustments_carried_forward', candidate_payload.value->'manual_adjustments_carried_forward',
        'carry_forward_blockers', candidate_payload.value->'carry_forward_blockers',
        'blocking_paid_evidence_json', candidate_payload.value->'blocking_paid_evidence_json',
        'terminal_no_money_evidence_json', candidate_payload.value->'terminal_no_money_evidence_json',
        'pending_provider_evidence_json', candidate_payload.value->'pending_provider_evidence_json',
        'resolved_full_payment_scope_json', candidate_payload.value->'resolved_full_payment_scope_json',
        'finance_scope_json', candidate_payload.value->'finance_scope_json',
        'provider_failure_reason_group', candidate_payload.value->'provider_failure_reason_group',
        'provider_failure_reason_label', candidate_payload.value->'provider_failure_reason_label',
        'status_update_signature', candidate_payload.value->'status_update_signature',
        'provider_outcome_unknown_evidence_json', candidate_payload.value->'provider_outcome_unknown_evidence_json',
        'provider_webhook_evidence_json', candidate_payload.value->'provider_webhook_evidence_json'
      )) AS action_payload
    FROM jsonb_array_elements(COALESCE(v_candidates, '[]'::jsonb)) AS candidate_payload(value)
    WHERE jsonb_typeof(candidate_payload.value) = 'object'
  ),
  line_rows AS (
    SELECT
      line_payload.value AS row_payload,
      line_payload.ordinality AS row_ordinality,
      action_payloads.action_payload
    FROM jsonb_array_elements(COALESCE(v_candidate_lines, '[]'::jsonb)) WITH ORDINALITY AS line_payload(value, ordinality)
    LEFT JOIN candidate_action_payloads AS action_payloads
      ON action_payloads.pay_batch_candidate_id = line_payload.value->>'pay_batch_candidate_id'
      OR action_payloads.candidate_id = line_payload.value->>'candidate_id'
  )
  SELECT COALESCE(
    jsonb_agg(
      line_rows.row_payload
      || COALESCE(line_rows.action_payload, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_lines',
        COALESCE(line_rows.row_payload->'candidate_lines', '{}'::jsonb)
        || COALESCE(line_rows.action_payload, '{}'::jsonb)
      )
      ORDER BY line_rows.row_ordinality
    ),
    '[]'::jsonb
  )
  INTO v_candidate_lines
  FROM line_rows;

  with item_flags as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.finance_case_id as finance_case_id,
      pbi.item_type as item_type,
      pbi.umbrella_id as umbrella_id,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  transfer_remittance_targets as (
    select distinct
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbt.umbrella_id as umbrella_id
    from public.pay_bank_transfers pbt
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = pbt.pay_batch_id
     and pbc.candidate_id = pbt.candidate_id
    where pbt.pay_batch_id = p_pay_batch_id
      and pbt.umbrella_id is not null
      and upper(coalesce(pbt.pay_channel::text,'')) = 'UMBRELLA'
      and upper(coalesce(pbt.status::text,'')) <> 'BLOCKED'
  ),
  rem_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id,
      ifl.umbrella_id
    from item_flags ifl
    where ifl.appears_on_umbrella_remittance = true
      and ifl.umbrella_id is not null

    union

    select distinct
      trt.pay_batch_candidate_id,
      trt.candidate_id,
      trt.umbrella_id
    from transfer_remittance_targets trt
  )
  select jsonb_build_object(
    'candidate_count', count(distinct pbc.id)::int,
    'umbrella_count', count(distinct rt.umbrella_id) filter (where rt.umbrella_id is not null)::int,
    'umbrella_remittance_job_count', count(distinct rt.umbrella_id) filter (where rt.umbrella_id is not null)::int,
    'candidate_copy_job_count', count(distinct pbc.id)::int,
    'job_kinds', case
      when count(distinct pbc.id) = 0 then '[]'::jsonb
      else jsonb_build_array('UMBRELLA_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE')
    end,
    'queued_count', count(distinct pbc.id) filter (where pbc.remittance_sent_at_utc is null and upper(coalesce(pbc.remittance_trigger_status,'')) in ('QUEUED_TO_MAIL_OUTBOX','MAIL_OUTBOX_DUPLICATE_EXISTS'))::int,
    'sent_count', LEAST(count(distinct pbc.id)::int, COALESCE(v_remittance_reconciled_sent_count, 0)),
    'unsent_count', GREATEST(count(distinct pbc.id)::int - LEAST(count(distinct pbc.id)::int, COALESCE(v_remittance_reconciled_sent_count, 0)), 0),
    'error_count', count(distinct pbc.id) filter (where nullif(btrim(coalesce(pbc.last_remittance_error,'')), '') is not null)::int,
    'latest_sent_at_utc', max(pbc.remittance_sent_at_utc),
    'all_sent', case when count(distinct pbc.id) = 0 then false else LEAST(count(distinct pbc.id)::int, COALESCE(v_remittance_reconciled_sent_count, 0)) >= count(distinct pbc.id)::int end,
    'trigger_statuses', coalesce(
      to_jsonb(
        array_agg(distinct pbc.remittance_trigger_status order by pbc.remittance_trigger_status)
        filter (where pbc.remittance_trigger_status is not null and btrim(coalesce(pbc.remittance_trigger_status::text,'')) <> '')
      ),
      '[]'::jsonb
    )
  )
  into v_remittance_summary
  from rem_targets rt
  join public.pay_batch_candidates pbc
    on pbc.id = rt.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id;

  with item_flags as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.finance_case_id as finance_case_id,
      pbi.item_type as item_type,
      pbi.umbrella_id as umbrella_id,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  transfer_remittance_targets as (
    select distinct
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbt.umbrella_id as umbrella_id
    from public.pay_bank_transfers pbt
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = pbt.pay_batch_id
     and pbc.candidate_id = pbt.candidate_id
    where pbt.pay_batch_id = p_pay_batch_id
      and pbt.umbrella_id is not null
      and upper(coalesce(pbt.pay_channel::text,'')) = 'UMBRELLA'
      and upper(coalesce(pbt.status::text,'')) <> 'BLOCKED'
  ),
  rem_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id,
      ifl.umbrella_id
    from item_flags ifl
    where ifl.appears_on_umbrella_remittance = true
      and ifl.umbrella_id is not null

    union

    select distinct
      trt.pay_batch_candidate_id,
      trt.candidate_id,
      trt.umbrella_id
    from transfer_remittance_targets trt
  ),
  payout_notice_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id
    from item_flags ifl
    where ifl.generates_candidate_payment_advice = true
  ),
  outbox_union as (
    select
      'MAIL'::text as outbox_channel,
      upper(coalesce(mo.type::text,'')) as outbox_type,
      upper(coalesce(mo.status::text,'')) as outbox_status,
      mo.reference as reference,
      mo.deterministic_outbox_key as deterministic_outbox_key,
      mo.payment_scope_json as payment_scope_json,
      lower(coalesce(mo.context_kind, '')) as context_kind,
      mo.context_id as context_id,
      upper(coalesce(mo.provider_status, '')) as provider_status,
      mo.created_at_utc as created_at_utc,
      mo.sent_at as sent_at_utc,
      mo.delivered_at as delivered_at_utc,
      mo.read_at as read_at_utc,
      mo.failed_at as failed_at_utc,
      upper(coalesce(mo.recipient_kind::text,'')) as recipient_kind
    from public.mail_outbox mo
    where (
      (lower(coalesce(mo.context_kind,'')) in ('pay_batch', 'pay_batches') and mo.context_id = p_pay_batch_id)
      or coalesce(mo.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
      or mo.deterministic_outbox_key like ('remittance:batch:' || p_pay_batch_id::text || ':%')
      or mo.reference like ('remittance:batch:' || p_pay_batch_id::text || ':%')
      or mo.reference like ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
      or mo.reference like ('payout_notice:pay_batch:' || p_pay_batch_id::text || ':%')
    )

    union all

    select
      upper(coalesce(co.channel::text,'')) as outbox_channel,
      upper(coalesce(co.channel::text,'')) as outbox_type,
      upper(coalesce(co.status::text,'')) as outbox_status,
      coalesce(co.provider_payload_json->>'reference', co.provider_payload_json->>'mail_reference', '') as reference,
      coalesce(co.provider_payload_json->>'deterministic_outbox_key', co.provider_payload_json->>'deterministicOutboxKey', '') as deterministic_outbox_key,
      coalesce(co.provider_payload_json->'payment_scope_json', '{}'::jsonb) as payment_scope_json,
      lower(coalesce(co.context_kind, '')) as context_kind,
      co.context_id as context_id,
      upper(coalesce(co.provider_payload_json->>'provider_status', '')) as provider_status,
      co.created_at_utc as created_at_utc,
      co.sent_at as sent_at_utc,
      co.delivered_at as delivered_at_utc,
      co.read_at as read_at_utc,
      co.failed_at as failed_at_utc,
      upper(coalesce(co.recipient_kind::text,'')) as recipient_kind
    from public.comms_outbox co
    where (
      (lower(coalesce(co.context_kind,'')) in ('pay_batch', 'pay_batches') and co.context_id = p_pay_batch_id)
      or coalesce(co.provider_payload_json #>> '{payment_scope_json,pay_batch_id}', co.provider_payload_json->>'pay_batch_id', '') = p_pay_batch_id::text
      or coalesce(co.provider_payload_json->>'deterministic_outbox_key', co.provider_payload_json->>'deterministicOutboxKey', '') like ('remittance:batch:' || p_pay_batch_id::text || ':%')
      or coalesce(co.provider_payload_json->>'reference', co.provider_payload_json->>'mail_reference', '') like ('remittance:batch:' || p_pay_batch_id::text || ':%')
      or coalesce(co.provider_payload_json->>'reference', co.provider_payload_json->>'mail_reference', '') like ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
      or coalesce(co.provider_payload_json->>'reference', co.provider_payload_json->>'mail_reference', '') like ('payout_notice:pay_batch:' || p_pay_batch_id::text || ':%')
    )
  ),
  rem_outbox as (
    select *
    from outbox_union ou
    where (
        ou.deterministic_outbox_key like ('remittance:batch:' || p_pay_batch_id::text || ':%')
        or ou.reference like ('remittance:batch:' || p_pay_batch_id::text || ':%')
        or ou.reference like ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
        or coalesce(ou.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
        or (ou.context_kind in ('pay_batch', 'pay_batches') and ou.context_id = p_pay_batch_id)
      )
      and (
        (ou.outbox_channel = 'MAIL' and ou.outbox_type = 'REMITTANCE')
        or ou.outbox_channel <> 'MAIL'
      )
  ),
  payout_notice_outbox as (
    select *
    from outbox_union ou
    where ou.reference like ('payout_notice:pay_batch:' || p_pay_batch_id::text || ':%')
      and (
        (ou.outbox_channel = 'MAIL' and ou.outbox_type = 'REMITTANCE')
        or ou.outbox_channel <> 'MAIL'
      )
  )
  select jsonb_build_object(
    'contains_remittance_items', exists(select 1 from rem_targets),
    'contains_payout_notice_items', exists(select 1 from payout_notice_targets),
    'contains_both', exists(select 1 from rem_targets) and exists(select 1 from payout_notice_targets),
    'communication_mode',
      case
        when exists(select 1 from rem_targets) and exists(select 1 from payout_notice_targets) then 'MIXED'
        when exists(select 1 from payout_notice_targets) then 'PAYOUT_NOTICE'
        when exists(select 1 from rem_targets) then 'REMITTANCE'
        else 'NONE'
      end,
    'remittance', jsonb_build_object(
      'contains_items', exists(select 1 from rem_targets),
      'item_count', (select count(*)::int from item_flags ifl where ifl.appears_on_umbrella_remittance = true),
      'job_kinds', case when exists(select 1 from rem_targets) then jsonb_build_array('UMBRELLA_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE') else '[]'::jsonb end,
      'umbrella_remittance_job_count', (select count(distinct rt.umbrella_id)::int from rem_targets rt where rt.umbrella_id is not null),
      'candidate_copy_job_count', (select count(distinct rt.candidate_id)::int from rem_targets rt),
      'candidate_count_targeted', (select count(distinct rt.candidate_id)::int from rem_targets rt),
      'umbrella_count_targeted', (select count(distinct rt.umbrella_id)::int from rem_targets rt where rt.umbrella_id is not null),
      'candidate_count_queued', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and pbc.remittance_sent_at_utc is null
          and upper(coalesce(pbc.remittance_trigger_status,'')) in ('QUEUED_TO_MAIL_OUTBOX','MAIL_OUTBOX_DUPLICATE_EXISTS')
      ),
      'candidate_count_sent', LEAST(
        (select count(distinct rt.pay_batch_candidate_id)::int from rem_targets rt),
        COALESCE(v_remittance_reconciled_sent_count, 0)
      ),
      'candidate_count_unsent', GREATEST(
        (select count(distinct rt.pay_batch_candidate_id)::int from rem_targets rt)
        - LEAST((select count(distinct rt.pay_batch_candidate_id)::int from rem_targets rt), COALESCE(v_remittance_reconciled_sent_count, 0)),
        0
      ),
      'candidate_count_error', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and nullif(btrim(coalesce(pbc.last_remittance_error,'')), '') is not null
      ),
      'latest_sent_at_utc', (
        select max(pbc.remittance_sent_at_utc)
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
      ),
      'all_sent', (
        select case
          when count(distinct rt.pay_batch_candidate_id) = 0 then false
          else LEAST(count(distinct rt.pay_batch_candidate_id)::int, COALESCE(v_remittance_reconciled_sent_count, 0)) >= count(distinct rt.pay_batch_candidate_id)::int
        end
        from rem_targets rt
      ),
      'trigger_statuses', coalesce((
        select to_jsonb(
          array_agg(distinct pbc.remittance_trigger_status order by pbc.remittance_trigger_status)
          filter (where pbc.remittance_trigger_status is not null and btrim(coalesce(pbc.remittance_trigger_status::text,'')) <> '')
        )
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
      ), '[]'::jsonb),
      'outbox_row_count', (select count(*)::int from rem_outbox),
      'outbox_channels', coalesce((
        select to_jsonb(array_agg(oc.outbox_channel order by oc.outbox_channel))
        from (
          select distinct ro.outbox_channel
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_channel,'')), '') is not null
        ) oc
      ), '[]'::jsonb),
      'outbox_statuses', coalesce((
        select to_jsonb(array_agg(os.outbox_status order by os.outbox_status))
        from (
          select distinct ro.outbox_status
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_status,'')), '') is not null
        ) os
      ), '[]'::jsonb),
      'outbox_counts_by_status', coalesce((
        select jsonb_object_agg(osc.outbox_status, osc.status_count)
        from (
          select
            ro.outbox_status,
            count(*)::int as status_count
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_status,'')), '') is not null
          group by ro.outbox_status
        ) osc
      ), '{}'::jsonb),
      'queued_count', (select count(*)::int from rem_outbox ro where ro.outbox_status = 'QUEUED'),
      'sent_count', (select count(*)::int from rem_outbox ro where ro.sent_at_utc is not null or ro.outbox_status = 'SENT'),
      'delivered_count', (select count(*)::int from rem_outbox ro where ro.delivered_at_utc is not null),
      'read_count', (select count(*)::int from rem_outbox ro where ro.read_at_utc is not null),
      'failed_count', (select count(*)::int from rem_outbox ro where ro.failed_at_utc is not null or ro.outbox_status = 'FAILED'),
      'latest_outbox_created_at_utc', (select max(ro.created_at_utc) from rem_outbox ro),
      'latest_outbox_sent_at_utc', (select max(ro.sent_at_utc) from rem_outbox ro)
    ),
    'payout_notice', jsonb_build_object(
      'contains_items', exists(select 1 from payout_notice_targets),
      'item_count', (select count(*)::int from item_flags ifl where ifl.generates_candidate_payment_advice = true),
      'candidate_count_targeted', (select count(distinct pnt.candidate_id)::int from payout_notice_targets pnt),
      'outbox_row_count', (select count(*)::int from payout_notice_outbox),
      'outbox_channels', coalesce((
        select to_jsonb(array_agg(oc.outbox_channel order by oc.outbox_channel))
        from (
          select distinct pno.outbox_channel
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_channel,'')), '') is not null
        ) oc
      ), '[]'::jsonb),
      'outbox_statuses', coalesce((
        select to_jsonb(array_agg(os.outbox_status order by os.outbox_status))
        from (
          select distinct pno.outbox_status
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_status,'')), '') is not null
        ) os
      ), '[]'::jsonb),
      'outbox_counts_by_status', coalesce((
        select jsonb_object_agg(osc.outbox_status, osc.status_count)
        from (
          select
            pno.outbox_status,
            count(*)::int as status_count
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_status,'')), '') is not null
          group by pno.outbox_status
        ) osc
      ), '{}'::jsonb),
      'queued_count', (select count(*)::int from payout_notice_outbox pno where pno.outbox_status = 'QUEUED'),
      'sent_count', (select count(*)::int from payout_notice_outbox pno where pno.sent_at_utc is not null or pno.outbox_status = 'SENT'),
      'delivered_count', (select count(*)::int from payout_notice_outbox pno where pno.delivered_at_utc is not null),
      'read_count', (select count(*)::int from payout_notice_outbox pno where pno.read_at_utc is not null),
      'failed_count', (select count(*)::int from payout_notice_outbox pno where pno.failed_at_utc is not null or pno.outbox_status = 'FAILED'),
      'latest_outbox_created_at_utc', (select max(pno.created_at_utc) from payout_notice_outbox pno),
      'latest_sent_at_utc', (select max(pno.sent_at_utc) from payout_notice_outbox pno)
    )
  )
  into v_communications_summary;

  select jsonb_build_object(
    'gross_additions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2),
    'gross_deductions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'net_deductions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'payout_amount_inc_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT') then coalesce(pbi.amount_inc_vat,0) else 0 end),0),2),
    'recovery_amount_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and pbi.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'finance_case_count', count(distinct pbi.finance_case_id)
  )
  into v_finance_summaries
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbi.finance_case_id is not null
    and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      );

  with finance_items as (
    select
      pbi.finance_case_id,
      max(pbc.candidate_id::text) as candidate_id,
      max(pbc.candidate_display_name) as candidate_display_name,
      max(pbc.candidate_tms_ref) as candidate_tms_ref,
      round(coalesce(sum(coalesce(pbi.amount_ex_vat,0)),0),2) as batch_amount_ex_vat,
      round(coalesce(sum(coalesce(pbi.amount_inc_vat,0)),0),2) as batch_amount_inc_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      coalesce(
        to_jsonb(
          array_agg(distinct pbi.item_type order by pbi.item_type)
          filter (where pbi.item_type is not null and btrim(coalesce(pbi.item_type::text,'')) <> '')
        ),
        '[]'::jsonb
      ) as item_types
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.finance_case_id is not null
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    group by pbi.finance_case_id
  ),
  reservation_rollup as (
    select
      par.finance_case_id,
      case
        when bool_or(upper(coalesce(par.status::text,'')) = 'SETTLED') then 'SETTLED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'COMMITTED') then 'COMMITTED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'RESERVED') then 'RESERVED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'RELEASED') then 'RELEASED'
        else null
      end as lifecycle_state,
      round(coalesce(sum(coalesce(par.reserved_amount,0)),0),2) as reservation_amount,
      coalesce(
        to_jsonb(
          array_agg(distinct par.status order by par.status)
          filter (where par.status is not null and btrim(coalesce(par.status::text,'')) <> '')
        ),
        '[]'::jsonb
      ) as reservation_statuses
    from public.pay_advance_reservations par
    where par.pay_batch_id = p_pay_batch_id
    group by par.finance_case_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'finance_case_id', vf.finance_case_id::text,
        'case_type', vf.case_type,
        'candidate_id', fi.candidate_id,
        'candidate_display_name', fi.candidate_display_name,
        'candidate_tms_ref', fi.candidate_tms_ref,
        'lifecycle_state', coalesce(rr.lifecycle_state, upper(coalesce(vf.status::text,''))),
        'finance_case_status', case when vf.status is null then null else vf.status::text end,
        'payout_status', case when vf.payout_status is null then null else vf.payout_status::text end,
        'payout_or_recovery_status', case when vf.case_type in ('PAYMENT_ADVANCE','MANUAL_CREDIT_ADJUSTMENT') and upper(coalesce(v_batch_kind_fixed,'')) = 'LOANS' then coalesce(vf.payout_status::text, vf.status::text) else vf.status::text end,
        'remaining_amount', vf.outstanding_amount,
        'batch_amount_ex_vat', fi.batch_amount_ex_vat,
        'batch_amount_inc_vat', fi.batch_amount_inc_vat,
        'item_types', fi.item_types,
        'reservation_amount', coalesce(rr.reservation_amount,0),
        'reservation_statuses', coalesce(rr.reservation_statuses,'[]'::jsonb),
        'comment_context', jsonb_build_object(
          'adjustment_comment', vf.adjustment_comment,
          'linked_timesheet_id', case when vf.linked_timesheet_id is null then null else vf.linked_timesheet_id::text end,
          'linked_shift_date', case when vf.linked_shift_date is null then null else vf.linked_shift_date::text end,
          'source_original_paid_amount', vf.source_original_paid_amount,
          'source_corrected_paid_amount', vf.source_corrected_paid_amount,
          'notes', vf.notes
        ),
        'paye_summary', jsonb_build_object(
          'gross_additions_ex_vat', fi.gross_additions_ex_vat,
          'gross_deductions_ex_vat', fi.gross_deductions_ex_vat,
          'net_deductions_ex_vat', fi.net_deductions_ex_vat
        ),
        'is_mixed_case', coalesce(vf.is_mixed_case, false),
        'open_taxable_count', coalesce(vf.open_taxable_count, 0),
        'open_reimbursement_count', coalesce(vf.open_reimbursement_count, 0),
        'unresolved_taxable_count', coalesce(vf.unresolved_taxable_count, 0),
        'stale_count', coalesce(vf.stale_count, 0),
        'component_resolution_summary_json', coalesce(vf.component_resolution_summary_json, '{}'::jsonb),
        'active_snooze_context', case
          when vf.active_snooze_id is null then null
          else jsonb_build_object(
            'snooze_id', vf.active_snooze_id::text,
            'snooze_kind', vf.active_snooze_kind,
            'snooze_until_date', case when vf.active_snooze_until_date is null then null else vf.active_snooze_until_date::text end,
            'note', vf.active_snooze_note,
            'created_at_utc', vf.active_snooze_created_at_utc,
            'updated_at_utc', vf.active_snooze_updated_at_utc
          )
        end
      )
      order by fi.candidate_display_name nulls last, fi.candidate_tms_ref nulls last, vf.finance_case_id
    ),
    '[]'::jsonb
  )
  into v_finance_case_groups
  from finance_items fi
  join public.v_finance_cases_register vf
    on vf.finance_case_id = fi.finance_case_id
  left join reservation_rollup rr
    on rr.finance_case_id = fi.finance_case_id;


  ---------------------------------------------------------------------------
  -- Payment correction / bank evidence summary for Banking Pay batch modal.
  -- This is display/planning metadata only: it does not mutate correction state
  -- and does not reinterpret batch economics from live TSFIN.
  ---------------------------------------------------------------------------

  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', public.pay_bank_transfer_events.id::text,
          'pay_batch_id', public.pay_bank_transfer_events.pay_batch_id::text,
          'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
          'candidate_id', CASE WHEN public.pay_bank_transfer_events.candidate_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.candidate_id::text END,
          'umbrella_id', CASE WHEN public.pay_bank_transfer_events.umbrella_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.umbrella_id::text END,
          'provider_key', public.pay_bank_transfer_events.provider_key,
          'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
          'provider_reference', public.pay_bank_transfer_events.provider_reference,
          'provider_state', public.pay_bank_transfer_events.provider_state,
          'normalised_state', public.pay_bank_transfer_events.normalised_state,
          'event_source', public.pay_bank_transfer_events.event_source,
          'event_time_utc', CASE WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL ELSE public.pay_bank_transfer_events.event_time_utc::text END,
          'received_at_utc', public.pay_bank_transfer_events.received_at_utc::text,
          'amount', public.pay_bank_transfer_events.amount,
          'currency', public.pay_bank_transfer_events.currency,
          'mapping_status', public.pay_bank_transfer_events.mapping_status,
          'mapping_method', public.pay_bank_transfer_events.mapping_method,
          'movement_classification', public.pay_bank_transfer_events.movement_classification,
          'correction_disposition', public.pay_bank_transfer_events.correction_disposition
        )
        ORDER BY public.pay_bank_transfer_events.received_at_utc DESC, public.pay_bank_transfer_events.id DESC
      ),
      '[]'::jsonb
    ),
    COUNT(*)::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED')
    )::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfer_events.normalised_state, ''))) IN ('RETURNED','REVERTED')
    )::integer
  INTO
    v_bank_evidence,
    v_bank_event_count,
    v_bank_failure_event_count,
    v_bank_return_event_count
  FROM public.pay_bank_transfer_events
  WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')
         OR NULLIF(btrim(coalesce(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL
    )::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
         OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
    )::integer,
    COUNT(*) FILTER (
      WHERE (
        NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_tx_id, '')), '') IS NOT NULL
        AND NOT (
          NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_tx_id, '')), '') = ANY(
            ARRAY_REMOVE(ARRAY[
              public.pay_bank_transfers.id::text,
              NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
              NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), '')
            ]::text[], NULL::text)
          )
        )
      )
      OR (
        upper(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) = 'PROVIDER_SUBMISSION_ACCEPTED'
        AND (
          lower(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
          OR NULLIF(btrim(coalesce(
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}',
            ''
          )), '') IS NOT NULL
          OR upper(btrim(coalesce(
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_state}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_state}',
            ''
          ))) IN ('ACCEPTED','SUBMITTED','PROCESSING','SENT','COMPLETED','COMPLETE','APPROVED','EXECUTED','PAID')
        )
      )
      OR EXISTS (
        SELECT 1
        FROM (VALUES
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_event_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_reference}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{rail_submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{external_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{revolut_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_transfer_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{external_transfer_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}')
        ) AS provider_rail_identifier(identifier_value)
        WHERE NULLIF(btrim(coalesce(provider_rail_identifier.identifier_value, '')), '') IS NOT NULL
          AND NOT (
            NULLIF(btrim(coalesce(provider_rail_identifier.identifier_value, '')), '') = ANY(
              ARRAY_REMOVE(ARRAY[
                public.pay_bank_transfers.id::text,
                NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
                NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), '')
              ]::text[], NULL::text)
            )
          )
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS provider_transfer_event
        WHERE provider_transfer_event.pay_batch_id = p_pay_batch_id
          AND provider_transfer_event.pay_bank_transfer_id = public.pay_bank_transfers.id
          AND upper(btrim(coalesce(provider_transfer_event.event_source, ''))) IN (
            'PROVIDER_RESPONSE',
            'PROVIDER_POLL',
            'PROVIDER_WEBHOOK',
            'WEBHOOK',
            'POLL',
            'RAIL_PROVIDER',
            'PROVIDER'
          )
          AND upper(btrim(coalesce(provider_transfer_event.normalised_state, provider_transfer_event.provider_state, provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN (
            'REJECTED',
            'FAILED',
            'ERROR',
            'DECLINED',
            'CANCELLED',
            'CANCELED',
            'MALFORMED',
            'UNKNOWN',
            'TIMEOUT',
            'TIMED_OUT'
          )
          AND upper(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN (
            'PROVIDER_SUBMISSION_REJECTED',
            'PROVIDER_SUBMISSION_FAILED',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
            'NO_PROVIDER_SUBMISSION_ATTEMPTED',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
            'MANUAL_RESOLVED_NO_PAYMENT_MADE'
          )
          AND (
            EXISTS (
              SELECT 1
              FROM (VALUES
                (provider_transfer_event.provider_event_id),
                (provider_transfer_event.provider_reference),
                (provider_transfer_event.raw_payload #>> '{provider_event_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_reference}'),
                (provider_transfer_event.raw_payload #>> '{provider_submission_id}'),
                (provider_transfer_event.raw_payload #>> '{submission_id}'),
                (provider_transfer_event.raw_payload #>> '{rail_submission_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{payment_id}'),
                (provider_transfer_event.raw_payload #>> '{external_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{revolut_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_transfer_id}'),
                (provider_transfer_event.raw_payload #>> '{external_transfer_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
              ) AS provider_event_identifier(identifier_value)
              WHERE NULLIF(btrim(coalesce(provider_event_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (
                  NULLIF(btrim(coalesce(provider_event_identifier.identifier_value, '')), '') = ANY(
                    ARRAY_REMOVE(ARRAY[
                      public.pay_bank_transfers.id::text,
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
                      NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.idempotency_key, '')), '')
                    ]::text[], NULL::text)
                  )
                )
            )
            OR upper(btrim(coalesce(provider_transfer_event.provider_state, provider_transfer_event.normalised_state, provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) IN (
              'ACCEPTED',
              'SUBMITTED',
              'PROCESSING',
              'SENT',
              'COMPLETED',
              'COMPLETE',
              'APPROVED',
              'EXECUTED',
              'PAID'
            )
          )
      )
    )::integer
  INTO
    v_transfer_failure_count,
    v_transfer_completed_count,
    v_transfer_provider_evidence_count
  FROM public.pay_bank_transfers
  WHERE public.pay_bank_transfers.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*)::integer
  INTO
    v_settlement_evidence_count
  FROM (
    SELECT 1
    FROM public.pay_batch_candidates
    WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
        OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
      )

    UNION ALL

    SELECT 1
    FROM public.timesheet_pay_state_history
    WHERE public.timesheet_pay_state_history.pay_batch_id = p_pay_batch_id

    UNION ALL

    SELECT 1
    FROM public.pay_advance_reservations
    WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(public.pay_advance_reservations.status, ''))) = 'SETTLED'
        OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
      )
  ) AS settlement_evidence_rows;

  SELECT
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
        AND public.pay_payment_correction_requests.correction_kind IN ('SETTLED_REVERSAL','MANUAL_EVIDENCE_SETTLED_RETURN')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('REQUESTED','AWAITING_AUTHORISATION')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('AUTHORISED','EXPANDED','PROCESSING')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('BLOCKED','APPLIED_WITH_BLOCKERS')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status = 'FAILED'
    )::integer
  INTO
    v_open_correction_request_count,
    v_open_settled_reversal_request_count,
    v_awaiting_authorisation_count,
    v_processing_request_count,
    v_blocked_request_count,
    v_failed_request_count
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PROCESSING')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'BLOCKED')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_RETRYABLE')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_FINAL')::integer
  INTO
    v_work_item_pending_count,
    v_work_item_processing_count,
    v_work_item_blocked_count,
    v_work_item_failed_retryable_count,
    v_work_item_failed_final_count
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id;

  v_work_item_failed_count := COALESCE(v_work_item_failed_retryable_count, 0) + COALESCE(v_work_item_failed_final_count, 0);
  v_work_item_requires_user_action := (
    COALESCE(v_work_item_blocked_count, 0) > 0
    OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
    OR COALESCE(v_work_item_failed_final_count, 0) > 0
  );
  v_work_item_processing_continues := (
    COALESCE(v_work_item_pending_count, 0) > 0
    OR COALESCE(v_work_item_processing_count, 0) > 0
    OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
  );

  SELECT
    public.pay_payment_correction_requests.id
  INTO
    v_open_correction_request_id
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
    AND public.pay_payment_correction_requests.status IN (
      'REQUESTED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED',
      'EXPANDED',
      'PROCESSING',
      'BLOCKED'
    )
  ORDER BY public.pay_payment_correction_requests.updated_at_utc DESC NULLS LAST,
           public.pay_payment_correction_requests.created_at_utc DESC,
           public.pay_payment_correction_requests.id DESC
  LIMIT 1;

  SELECT
    COALESCE(
      jsonb_build_object(
        'id', latest_correction_request.id::text,
        'pay_batch_id', latest_correction_request.pay_batch_id::text,
        'correction_kind', latest_correction_request.correction_kind,
        'status', latest_correction_request.status,
        'requested_by_user_id', CASE WHEN latest_correction_request.requested_by_user_id IS NULL THEN NULL ELSE latest_correction_request.requested_by_user_id::text END,
        'requested_at_utc', latest_correction_request.requested_at_utc::text,
        'required_quantity', latest_correction_request.required_quantity,
        'approved_count', latest_correction_request.approved_count,
        'golden_key_used', latest_correction_request.golden_key_used,
        'reason', latest_correction_request.reason,
        'selection_json', latest_correction_request.selection_json,
        'plan_json', latest_correction_request.plan_json,
        'source_bank_event_id', CASE WHEN latest_correction_request.source_bank_event_id IS NULL THEN NULL ELSE latest_correction_request.source_bank_event_id::text END,
        'auto_requested', latest_correction_request.auto_requested,
        'authorised_at_utc', CASE WHEN latest_correction_request.authorised_at_utc IS NULL THEN NULL ELSE latest_correction_request.authorised_at_utc::text END,
        'applied_at_utc', CASE WHEN latest_correction_request.applied_at_utc IS NULL THEN NULL ELSE latest_correction_request.applied_at_utc::text END,
        'cancelled_at_utc', CASE WHEN latest_correction_request.cancelled_at_utc IS NULL THEN NULL ELSE latest_correction_request.cancelled_at_utc::text END,
        'updated_at_utc', latest_correction_request.updated_at_utc::text
      ),
      '{}'::jsonb
    ),
    latest_correction_request.status
  INTO
    v_latest_correction_request,
    v_latest_correction_request_status
  FROM (
    SELECT public.pay_payment_correction_requests.*
    FROM public.pay_payment_correction_requests
    WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
    ORDER BY public.pay_payment_correction_requests.updated_at_utc DESC NULLS LAST,
             public.pay_payment_correction_requests.created_at_utc DESC,
             public.pay_payment_correction_requests.id DESC
    LIMIT 1
  ) AS latest_correction_request;

  SELECT
    COUNT(DISTINCT public.pay_batch_items.id)::integer
  INTO
    v_correctable_item_count
  FROM public.pay_batch_items
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
  WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
    AND COALESCE(public.pay_batch_items.is_voided, false) = false
    AND public.pay_batch_items.item_type <> 'DEBT_CREATED';

  SELECT
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'PRE_BANK_CANCEL'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'NO_MONEY_UNWIND'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'SETTLED_REVERSAL'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id)::integer
  INTO
    v_applied_precancel_item_count,
    v_applied_unwind_item_count,
    v_applied_reversal_item_count,
    v_corrected_item_count
  FROM public.pay_payment_correction_items
  WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
    AND public.pay_payment_correction_items.status = 'APPLIED';

  IF (
    COALESCE(v_work_item_pending_count, 0) > 0
    OR COALESCE(v_work_item_processing_count, 0) > 0
    OR COALESCE(v_processing_request_count, 0) > 0
  ) THEN
    v_derived_correction_state := 'PROCESSING';
  ELSIF v_work_item_requires_user_action
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0 THEN
    v_derived_correction_state := 'ACTION_REQUIRED';
  ELSIF COALESCE(v_awaiting_authorisation_count, 0) > 0 THEN
    v_derived_correction_state := 'AWAITING_AUTHORISATION';
  ELSIF v_applied_reversal_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'REVERSED';
    ELSE
      v_derived_correction_state := 'PARTIALLY_REVERSED';
    END IF;
  ELSIF v_applied_unwind_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'NO_MONEY_UNWOUND';
    ELSE
      v_derived_correction_state := 'PARTIALLY_UNWOUND';
    END IF;
  ELSIF v_applied_precancel_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'PRE_BANK_CANCELLED';
    ELSE
      v_derived_correction_state := 'PARTIALLY_PRE_BANK_CANCELLED';
    END IF;
  ELSIF v_bank_return_event_count > 0 THEN
    v_derived_correction_state := 'SETTLED_RETURNED';
  ELSIF v_bank_failure_event_count > 0 OR v_transfer_failure_count > 0 THEN
    v_derived_correction_state := 'ACTION_REQUIRED';
  ELSE
    v_derived_correction_state := 'NONE';
  END IF;

  v_can_cancel_payment_attempt := (
    COALESCE(v_open_correction_request_count, 0) = 0
    AND COALESCE(v_bank_event_count, 0) = 0
    AND COALESCE(v_transfer_provider_evidence_count, 0) = 0
    AND COALESCE(v_transfer_failure_count, 0) = 0
    AND COALESCE(v_transfer_completed_count, 0) = 0
    AND COALESCE(v_settlement_evidence_count, 0) = 0
    AND COALESCE(v_corrected_item_count, 0) = 0
    AND v_execution_commit_state = 'NOT_SUBMITTED'
    AND v_batch_status_upper IN (
      'DRAFT',
      'DRAFT_CREATED',
      'READY',
      'WAITING_BANK_CONFIRM',
      'PARTIAL',
      'BLOCKED_FUNDS',
      'SCHEDULED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED_FOR_PAYMENT',
      'EXECUTING'
    )
  );

  v_can_reverse_settled_payment := (
    COALESCE(v_settlement_evidence_count, 0) > 0
    OR COALESCE(v_transfer_completed_count, 0) > 0
    OR COALESCE(v_bank_return_event_count, 0) > 0
  );

  v_can_unwind_failed_payment := (
    COALESCE(v_bank_failure_event_count, 0) > 0
    OR COALESCE(v_transfer_failure_count, 0) > 0
  ) AND v_can_reverse_settled_payment = false;

  v_can_review_bank_evidence := (
    COALESCE(v_bank_event_count, 0) > 0
    OR COALESCE(v_transfer_provider_evidence_count, 0) > 0
    OR COALESCE(v_open_correction_request_count, 0) > 0
    OR v_derived_correction_state <> 'NONE'
  );

  v_payment_correction := jsonb_build_object(
    'derived_state', v_derived_correction_state,
    'display_state', CASE
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      )
      AND (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'PARTLY_APPLIED_REVIEW_NEEDED'
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      ) THEN 'PROCESSING'
      WHEN (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'ACTION_REQUIRED'
      ELSE v_derived_correction_state
    END,
    'requires_user_action', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED')
      OR COALESCE(v_blocked_request_count, 0) > 0
      OR COALESCE(v_failed_request_count, 0) > 0
      OR v_work_item_requires_user_action
    ),
    'processing_count', GREATEST(
      COALESCE(v_processing_request_count, 0),
      CASE WHEN v_work_item_processing_continues THEN 1 ELSE 0 END
    ),
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'blocked_count', COALESCE(v_blocked_request_count, 0) + COALESCE(v_work_item_blocked_count, 0),
    'failed_count', COALESCE(v_failed_request_count, 0) + COALESCE(v_work_item_failed_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'open_request_id', CASE WHEN v_open_correction_request_id IS NULL THEN NULL ELSE v_open_correction_request_id::text END,
    'latest_request', COALESCE(v_latest_correction_request, '{}'::jsonb),
    'can_plan', true,
    'counts', jsonb_build_object(
      'open_request_count', COALESCE(v_open_correction_request_count, 0),
      'open_settled_reversal_request_count', COALESCE(v_open_settled_reversal_request_count, 0),
      'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
      'processing_request_count', COALESCE(v_processing_request_count, 0),
      'blocked_request_count', COALESCE(v_blocked_request_count, 0),
      'failed_request_count', COALESCE(v_failed_request_count, 0),
      'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
      'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
      'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
      'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
      'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
      'bank_event_count', COALESCE(v_bank_event_count, 0),
      'bank_failure_event_count', COALESCE(v_bank_failure_event_count, 0),
      'bank_return_event_count', COALESCE(v_bank_return_event_count, 0),
      'transfer_failure_count', COALESCE(v_transfer_failure_count, 0),
      'transfer_completed_count', COALESCE(v_transfer_completed_count, 0),
      'settlement_evidence_count', COALESCE(v_settlement_evidence_count, 0),
      'correctable_item_count', COALESCE(v_correctable_item_count, 0),
      'corrected_item_count', COALESCE(v_corrected_item_count, 0),
      'applied_precancel_item_count', COALESCE(v_applied_precancel_item_count, 0),
      'applied_unwind_item_count', COALESCE(v_applied_unwind_item_count, 0),
      'applied_reversal_item_count', COALESCE(v_applied_reversal_item_count, 0)
    )
  );

  IF v_batch_stale_payment_issue IS NOT NULL THEN
    v_payment_correction := v_payment_correction || jsonb_build_object(
      'batch_stale_issue', v_batch_stale_payment_issue,
      'payment_execution_review', v_batch_stale_payment_execution_review,
      'payment_issues', v_payment_issues,
      'batch_stale_action_required', true,
      'requires_user_action', true
    );
  END IF;

  IF v_blocked_funds_payment_issue IS NOT NULL THEN
    v_payment_correction := v_payment_correction || jsonb_build_object(
      'blocked_funds_issue', v_blocked_funds_payment_issue,
      'payment_issues', v_payment_issues,
      'blocked_funds_action_required', true,
      'can_retry_blocked_funds', v_can_retry_blocked_funds,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false),
      'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
      'retry_operation_status', v_retry_operation_status,
      'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
      'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
      'retry_status_label', v_retry_status_label,
      'retry_button_label', v_retry_button_label,
      'retry_button_visible', COALESCE(v_retry_button_visible, false),
      'retry_button_disabled_reason', v_retry_button_disabled_reason,
      'requires_user_action', true
    );
  END IF;

  v_movement_classification := jsonb_build_object(
    'classification', CASE
      WHEN COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
        THEN 'PROCESSING'
      WHEN v_work_item_requires_user_action
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
        THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      WHEN COALESCE(v_awaiting_authorisation_count, 0) > 0
        AND COALESCE(v_open_settled_reversal_request_count, 0) > 0
        THEN 'TRUE_SETTLED_REVERSAL_REQUIRED'
      WHEN COALESCE(v_awaiting_authorisation_count, 0) > 0
        THEN 'AWAITING_AUTHORISATION'
      WHEN COALESCE(v_processing_request_count, 0) > 0
        AND COALESCE(v_blocked_request_count, 0) = 0
        AND COALESCE(v_failed_request_count, 0) = 0
        THEN 'PROCESSING'
      WHEN COALESCE(v_bank_return_event_count, 0) > 0
        AND COALESCE(v_applied_reversal_item_count, 0) = 0
        THEN 'TRUE_SETTLED_REVERSAL_REQUIRED'
      WHEN COALESCE(v_applied_reversal_item_count, 0) > 0
        THEN 'SETTLED_REVERSAL_APPLIED'
      WHEN v_can_unwind_failed_payment THEN 'NO_MONEY_UNWIND'
      WHEN v_can_cancel_payment_attempt THEN 'PRE_BANK_CANCEL'
      WHEN v_can_reverse_settled_payment
        AND (
          COALESCE(v_bank_failure_event_count, 0) > 0
          OR COALESCE(v_transfer_failure_count, 0) > 0
        )
        THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      WHEN v_can_reverse_settled_payment THEN 'SETTLED_NO_CORRECTION_REQUIRED'
      WHEN v_can_review_bank_evidence THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      ELSE 'NONE'
    END,
    'source', 'pay_batch_get_summary',
    'derived_state', v_derived_correction_state,
    'can_reverse_settled_payment', v_can_reverse_settled_payment,
    'settled_reversal_required', (
      (
        COALESCE(v_open_settled_reversal_request_count, 0) > 0
        AND COALESCE(v_processing_request_count, 0) = 0
        AND COALESCE(v_work_item_pending_count, 0) = 0
        AND COALESCE(v_work_item_processing_count, 0) = 0
      )
      OR (
        COALESCE(v_bank_return_event_count, 0) > 0
        AND COALESCE(v_applied_reversal_item_count, 0) = 0
        AND COALESCE(v_processing_request_count, 0) = 0
        AND COALESCE(v_work_item_pending_count, 0) = 0
        AND COALESCE(v_work_item_processing_count, 0) = 0
      )
    ),
    'settlement_evidence_count', COALESCE(v_settlement_evidence_count, 0),
    'bank_failure_event_count', COALESCE(v_bank_failure_event_count, 0),
    'bank_return_event_count', COALESCE(v_bank_return_event_count, 0),
    'open_settled_reversal_request_count', COALESCE(v_open_settled_reversal_request_count, 0),
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'processing_request_count', COALESCE(v_processing_request_count, 0),
    'blocked_request_count', COALESCE(v_blocked_request_count, 0),
    'failed_request_count', COALESCE(v_failed_request_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'applied_reversal_item_count', COALESCE(v_applied_reversal_item_count, 0),
    'transfer_failure_count', COALESCE(v_transfer_failure_count, 0),
    'transfer_completed_count', COALESCE(v_transfer_completed_count, 0)
  );

  IF v_blocked_funds_payment_issue IS NOT NULL THEN
    v_movement_classification := v_movement_classification || jsonb_build_object(
      'blocked_funds_issue', v_blocked_funds_payment_issue,
      'blocked_funds_action_required', true,
      'bank_status_label', 'Bank unavailable — unsent payments can be retried',
      'issue_kind', 'BLOCKED_FUNDS',
      'can_retry_blocked_funds', v_can_retry_blocked_funds
    );
  END IF;

  v_movement_classification := v_movement_classification || jsonb_build_object(
    'classification', CASE
      WHEN v_batch_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_OR_SETTLED'
      WHEN v_batch_recommended_action = 'CHECK_PROVIDER_STATUS' THEN 'PROVIDER_OUTCOME_UNKNOWN'
      WHEN v_batch_recommended_action = 'RETRY_PROVIDER_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
      WHEN v_batch_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN COALESCE(v_batch_payment_lifecycle_state, 'PROVIDER_FAILED_NO_MONEY')
      WHEN v_batch_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN COALESCE(v_batch_payment_lifecycle_state, 'LOCAL_PREPARED_NOT_SENT')
      ELSE COALESCE(v_movement_classification->>'classification', v_batch_payment_lifecycle_state, 'NONE')
    END,
    'payment_lifecycle_state', v_batch_payment_lifecycle_state,
    'payment_lifecycle_label', v_batch_payment_lifecycle_label,
    'recommended_action', v_batch_recommended_action,
    'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
    'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
    'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
    'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
    'can_reverse_settled_payment', false,
    'settled_reversal_required', false,
    'action_source', 'pay_payment_cancelability_diagnostic'
  );

  v_manual_actions := jsonb_build_object(
    'can_cancel_payment_attempt', COALESCE(v_whole_batch_cancel_available, false) OR COALESCE(v_batch_can_pre_provider_cancel, false),
    'can_unwind_failed_payment', lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
    'can_reverse_settled_payment', false,
    'can_recover_overpayment', COALESCE(v_has_actual_recovery_context, false) AND lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
    'can_review_bank_evidence', COALESCE(v_batch_requires_bank_check, false),
    'can_retry_blocked_funds', v_can_retry_blocked_funds,
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_status_label', v_retry_status_label,
    'retry_button_label', v_retry_button_label,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason,
    'payment_lifecycle_state', v_batch_payment_lifecycle_state,
    'payment_lifecycle_label', v_batch_payment_lifecycle_label,
    'recommended_action', v_batch_recommended_action,
    'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
    'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
    'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
    'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb),
    'action_source', 'pay_payment_cancelability_diagnostic'
  );


  SELECT jsonb_build_object(
    'queued_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'QUEUED'),
    'sent_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'SENT'),
    'failed_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'FAILED'),
    'external_correction_notice', false,
    'admin_notice_required', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED','PARTIALLY_UNWOUND','PARTIALLY_REVERSED','REVERSED','NO_MONEY_UNWOUND')
    )
  )
  INTO v_communication_status
  FROM public.mail_outbox
  WHERE public.mail_outbox.context_id = p_pay_batch_id
     OR public.mail_outbox.reference ILIKE '%' || p_pay_batch_id::text || '%';

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'finance_case_id', CASE WHEN correction_finance_rollup.finance_case_id IS NULL THEN NULL ELSE correction_finance_rollup.finance_case_id::text END,
        'correction_item_kind', correction_finance_rollup.correction_item_kind,
        'item_count', correction_finance_rollup.item_count,
        'amount_ex_vat', correction_finance_rollup.amount_ex_vat,
        'amount_inc_vat', correction_finance_rollup.amount_inc_vat
      )
      ORDER BY correction_finance_rollup.finance_case_id::text NULLS LAST, correction_finance_rollup.correction_item_kind
    ),
    '[]'::jsonb
  )
  INTO v_finance_case_correction_summary
  FROM (
    SELECT
      public.pay_payment_correction_items.finance_case_id,
      public.pay_payment_correction_items.correction_item_kind,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(COALESCE(public.pay_payment_correction_items.amount_ex_vat, 0)), 0), 2)::numeric AS amount_ex_vat,
      ROUND(COALESCE(SUM(COALESCE(public.pay_payment_correction_items.amount_inc_vat, 0)), 0), 2)::numeric AS amount_inc_vat
    FROM public.pay_payment_correction_items
    WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
      AND public.pay_payment_correction_items.status = 'APPLIED'
      AND public.pay_payment_correction_items.finance_case_id IS NOT NULL
    GROUP BY
      public.pay_payment_correction_items.finance_case_id,
      public.pay_payment_correction_items.correction_item_kind
  ) AS correction_finance_rollup;

  SELECT jsonb_build_object(
    'request_count', COUNT(DISTINCT public.pay_payment_correction_requests.id),
    'work_items', COALESCE(
      (
        SELECT jsonb_object_agg(work_status_counts.status, work_status_counts.item_count ORDER BY work_status_counts.status)
        FROM (
          SELECT
            public.pay_payment_correction_work_items.status,
            COUNT(*)::integer AS item_count
          FROM public.pay_payment_correction_work_items
          WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id
          GROUP BY public.pay_payment_correction_work_items.status
        ) AS work_status_counts
      ),
      '{}'::jsonb
    ),
    'latest_request_status', v_latest_correction_request_status,
    'display_state', CASE
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      )
      AND (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'PARTLY_APPLIED_REVIEW_NEEDED'
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      ) THEN 'PROCESSING'
      WHEN (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'ACTION_REQUIRED'
      ELSE v_derived_correction_state
    END,
    'open_request_id', CASE WHEN v_open_correction_request_id IS NULL THEN NULL ELSE v_open_correction_request_id::text END,
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'processing_request_count', COALESCE(v_processing_request_count, 0),
    'blocked_request_count', COALESCE(v_blocked_request_count, 0),
    'failed_request_count', COALESCE(v_failed_request_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'requires_user_action', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED')
      OR COALESCE(v_blocked_request_count, 0) > 0
      OR COALESCE(v_failed_request_count, 0) > 0
      OR v_work_item_requires_user_action
    ),
    'processing_continues', v_work_item_processing_continues
  )
  INTO v_correction_progress
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id;


