          'next_retry_description', v_next_retry_description,
          'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
          'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
          'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
          'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
          'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
          'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
          'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb)
        )
        || jsonb_build_object(
          'live_signal_version', COALESCE(v_batch_signal_version, 0),
          'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
          'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
          'alert_version', COALESCE(v_batch_alert_version, 0),
          'overview_version', COALESCE(v_batch_overview_version, 0),
          'last_status_hash', v_batch_last_status_hash,
          'last_alert_hash', v_batch_last_alert_hash,
          'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb),
          'banking_system_snapshot', v_batch.banking_system_snapshot,
          'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,

          -- Neutral (rail-generic) manual confirm aliases (keep legacy keys too)
          'manual_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'manual_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'monzo_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'monzo_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'last_status_checked_at_utc', v_batch.last_status_checked_at_utc,
          'last_funds_check_at_utc', v_batch.last_funds_check_at_utc,
          'last_funds_check_json', v_batch.last_funds_check_json
        ) || jsonb_build_object(
          'funding_account_ref', v_batch.funding_account_ref,
          'blocked_funds_required_gbp', v_blocked_funds_required_gbp,
          'blocked_funds_available_gbp', v_blocked_funds_available_gbp,
          'blocked_funds_required_gbp_display', v_blocked_funds_required_gbp_display,
          'blocked_funds_available_gbp_display', v_blocked_funds_available_gbp_display,
          'blocked_funds_sufficient', v_blocked_funds_sufficient,
          'blocked_funds_provider', v_blocked_funds_provider,
          'blocked_funds_env', v_blocked_funds_env,
          'blocked_funds_account_ref', v_blocked_funds_account_ref,
          'banking_alerts', v_banking_alerts,
          'banking_alert_kind', v_banking_alert_kind,
          'banking_alert_severity', v_banking_alert_severity,
          'banking_alert_label', v_banking_alert_label,
          'banking_alert_reason', v_banking_alert_reason,
          'banking_alert_fingerprint', v_banking_alert_fingerprint,
          'banking_alert_acknowledged_for_user', v_banking_alert_acknowledged_for_user,
          'banking_alert_requires_attention', v_banking_alert_requires_attention
        ))
        || jsonb_build_object(
          'can_retry_blocked_funds', v_can_retry_blocked_funds,
          'no_submission_evidence_flags', v_no_submission_evidence_flags,
          'blocked_funds_payment_issue', v_blocked_funds_payment_issue,
          'payment_issues', v_payment_issues,
          'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
          'payment_execution_review', v_payment_execution_review,
          'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
          'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
          'review_reason_code', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submit_review_reason_code ELSE NULL::text END,
          'provider_submission_status', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submission_status ELSE NULL::text END,
          'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
          'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
          'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
          -- Rail-generic scheduling/execution fields
          'rail_provider_snapshot', v_batch.rail_provider_snapshot,
          'rail_env_snapshot', v_batch.rail_env_snapshot,
          'schedule_kind', v_batch.schedule_kind,
          'scheduled_at_utc', v_batch.scheduled_at_utc,
          'executing_started_at_utc', v_batch.executing_started_at_utc,

          -- Bulk payment reference fields
          'bulk_ref_num', v_batch.bulk_ref_num,
          'bulk_ref_date', case when v_batch.bulk_ref_date is null then null else v_batch.bulk_ref_date::text end,
          'bulk_reference', v_batch.bulk_reference
        )
      ),
      'candidates', v_candidates,
      'transfers', v_transfers,
      'items', v_items
    );
end;
$function$;

-- pay_batch_insert_candidates_from_preview(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_insert_candidates_from_preview(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_existing_count integer := 0;
  v_reused_count integer := 0;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_scope_ids jsonb := '[]'::jsonb;
  v_linked_scope_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'p_operation_id is required for row-backed draft candidate insertion';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'p_actor_user_id is required for row-backed draft candidate insertion';
  END IF;

  IF p_candidate_scope_ids IS NULL OR jsonb_typeof(v_scope_ids) <> 'array' OR jsonb_array_length(v_scope_ids) = 0 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array';
  END IF;

  v_scope_id_count := jsonb_array_length(v_scope_ids);

  IF v_scope_id_count > 100 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids exceeds the 100 row cap: %', v_scope_id_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  ) THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must contain UUID strings only';
  END IF;

  PERFORM 1 FROM public.tms_users AS actor_user WHERE actor_user.id = p_actor_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  PERFORM 1 FROM public.pay_batches AS batch_row WHERE batch_row.id = p_pay_batch_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch % not found', p_pay_batch_id;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_candidate_scope_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_candidate_scope_page ON COMMIT DROP AS
  SELECT scope_row.*
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.id IN (
      SELECT (supplied_scope.scope_value #>> '{}')::uuid
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    )
  ORDER BY scope_row.pay_channel, scope_row.candidate_id, scope_row.id;

  IF (SELECT COUNT(*)::integer FROM pg_temp.tmp_pay_batch_candidate_scope_page) <> v_scope_id_count THEN
    RAISE EXCEPTION 'one or more candidate scope ids do not belong to operation %', p_operation_id;
  END IF;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET pay_batch_id = p_pay_batch_id,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
      WHERE scope_page.id = scope_update.id
    );

  SELECT COUNT(*)::integer
  INTO v_existing_count
  FROM (
    SELECT DISTINCT scope_page.candidate_id
    FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
  ) AS candidate_source
  JOIN public.pay_batch_candidates AS existing_candidate
    ON existing_candidate.pay_batch_id = p_pay_batch_id
   AND existing_candidate.candidate_id = candidate_source.candidate_id;

  WITH candidate_source AS (
    SELECT DISTINCT
      p_pay_batch_id AS pay_batch_id,
      candidate_row.id AS candidate_id,
      candidate_row.tms_ref AS candidate_tms_ref,
      COALESCE(NULLIF(BTRIM(candidate_row.display_name), ''), NULLIF(BTRIM(CONCAT_WS(' ', candidate_row.first_name, candidate_row.last_name)), ''), candidate_row.tms_ref) AS candidate_display_name,
      BOOL_OR(scope_page.pay_channel = 'PAYE') AS has_paye_scope
    FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
    JOIN public.candidates AS candidate_row
      ON candidate_row.id = scope_page.candidate_id
    GROUP BY candidate_row.id, candidate_row.tms_ref, candidate_row.display_name, candidate_row.first_name, candidate_row.last_name
  ), updated_candidates AS (
    UPDATE public.pay_batch_candidates AS existing_candidate
    SET candidate_tms_ref = candidate_source.candidate_tms_ref,
        candidate_display_name = candidate_source.candidate_display_name,
        updated_at = v_now
    FROM candidate_source
    WHERE existing_candidate.pay_batch_id = candidate_source.pay_batch_id
      AND existing_candidate.candidate_id = candidate_source.candidate_id
      AND (
        existing_candidate.candidate_tms_ref IS DISTINCT FROM candidate_source.candidate_tms_ref
        OR existing_candidate.candidate_display_name IS DISTINCT FROM candidate_source.candidate_display_name
      )
    RETURNING existing_candidate.id
  )
  SELECT COUNT(*)::integer INTO v_updated_count FROM updated_candidates;

  WITH candidate_source AS (
    SELECT DISTINCT
      p_pay_batch_id AS pay_batch_id,
      candidate_row.id AS candidate_id,
      candidate_row.tms_ref AS candidate_tms_ref,
      COALESCE(NULLIF(BTRIM(candidate_row.display_name), ''), NULLIF(BTRIM(CONCAT_WS(' ', candidate_row.first_name, candidate_row.last_name)), ''), candidate_row.tms_ref) AS candidate_display_name,
      BOOL_OR(scope_page.pay_channel = 'PAYE') AS has_paye_scope
    FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
    JOIN public.candidates AS candidate_row
      ON candidate_row.id = scope_page.candidate_id
    GROUP BY candidate_row.id, candidate_row.tms_ref, candidate_row.display_name, candidate_row.first_name, candidate_row.last_name
  ), inserted_candidates AS (
    INSERT INTO public.pay_batch_candidates(
      pay_batch_id,
      candidate_id,
      candidate_tms_ref,
      candidate_display_name,
      paye_state,
      mismatch_settlement_choice,
      gross_preview,
      net_bank_amount,
      debt_created,
      loan_repayment_taken,
      overpayment_recovery_taken,
      awaiting_net_amount,
      updated_at
    )
    SELECT
      candidate_source.pay_batch_id,
      candidate_source.candidate_id,
      candidate_source.candidate_tms_ref,
      candidate_source.candidate_display_name,
      CASE WHEN candidate_source.has_paye_scope THEN 'PENDING_NET' ELSE NULL END,
      NULL::text,
      NULL::numeric,
      NULL::numeric,
      0::numeric,
      0::numeric,
      0::numeric,
      candidate_source.has_paye_scope,
      v_now
    FROM candidate_source
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.pay_batch_candidates AS existing_candidate
      WHERE existing_candidate.pay_batch_id = candidate_source.pay_batch_id
        AND existing_candidate.candidate_id = candidate_source.candidate_id
    )
    RETURNING id
  )
  SELECT COUNT(*)::integer INTO v_inserted_count FROM inserted_candidates;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET status = CASE
        WHEN UPPER(BTRIM(COALESCE(scope_update.status, ''))) IN ('PENDING', 'SCOPED', 'ALLOCATED') THEN 'ALLOCATED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
      WHERE scope_page.id = scope_update.id
    );

  SELECT COALESCE(jsonb_agg(candidate_source.candidate_id::text ORDER BY candidate_source.candidate_id::text), '[]'::jsonb)
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT scope_page.candidate_id
    FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
  ) AS candidate_source;

  SELECT COALESCE(jsonb_agg(scope_source.id::text ORDER BY scope_source.id::text), '[]'::jsonb)
  INTO v_candidate_scope_ids
  FROM (
    SELECT DISTINCT scope_page.id
    FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
  ) AS scope_source;

  v_reused_count := GREATEST(COALESCE(v_existing_count, 0) - COALESCE(v_updated_count, 0), 0);

  IF COALESCE(v_inserted_count, 0) + COALESCE(v_reused_count, 0) + COALESCE(v_updated_count, 0) <= 0 THEN
    RAISE EXCEPTION 'DRAFT_CANDIDATE_INSERTION_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_CANDIDATE_INSERTION_EMPTY',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', p_operation_id::text,
              'candidate_scope_count', v_scope_id_count,
              'scope_count', v_scope_id_count,
              'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
              'message', 'Candidate scope rows did not insert, update, or reuse any pay_batch_candidates rows.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_linked_scope_count
  FROM public.banking_pay_operation_candidate_scope AS linked_scope
  WHERE linked_scope.operation_id = p_operation_id
    AND linked_scope.pay_batch_id = p_pay_batch_id
    AND linked_scope.id IN (
      SELECT scope_page.id
      FROM pg_temp.tmp_pay_batch_candidate_scope_page AS scope_page
    );

  IF COALESCE(v_linked_scope_count, 0) <> COALESCE(v_scope_id_count, 0) THEN
    RAISE EXCEPTION 'DRAFT_CANDIDATE_SCOPE_BATCH_LINK_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_CANDIDATE_SCOPE_BATCH_LINK_FAILED',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', p_operation_id::text,
              'candidate_scope_count', v_scope_id_count,
              'scope_count', v_scope_id_count,
              'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
              'linked_scope_count', COALESCE(v_linked_scope_count, 0)
            )::text;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'candidate_scope_count', v_scope_id_count,
    'scope_count', v_scope_id_count,
    'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
    'inserted_candidate_rows', COALESCE(v_inserted_count, 0),
    'reused_candidate_rows', COALESCE(v_reused_count, 0),
    'updated_candidate_rows', COALESCE(v_updated_count, 0),
    'skipped_candidate_rows', 0,
    'failed_candidate_rows', 0,
    'candidate_ids', COALESCE(v_candidate_ids, '[]'::jsonb)
  );
END;
$function$;

-- pay_batch_insert_items_from_preview(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_insert_items_from_preview(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_inserted_count integer := 0;
  v_reused_count integer := 0;
  v_failed_count integer := 0;
  v_expected_allocation_row_count integer := 0;
  v_page_allocation_row_count integer := 0;
  v_ordinary_page_allocation_row_count integer := 0;
  v_deferred_finance_adjustment_row_count integer := 0;
  v_linked_allocation_row_count integer := 0;
  v_scope_expects_item_count integer := 0;
  v_candidate_scope_ids jsonb := '[]'::jsonb;
  v_repaired_existing_item_link_count integer := 0;
  v_synthetic_total_item_rows jsonb := '[]'::jsonb;
  v_pay_date date := NULL::date;
  v_vat_rate_pct numeric := NULL::numeric;
  v_workbench_session_id uuid := NULL::uuid;
  v_operation_type text := NULL::text;
  v_operation_status text := NULL::text;
  v_operation_phase text := NULL::text;
  v_operation_actor_user_id uuid := NULL::uuid;
  v_session_status text := NULL::text;
  v_session_discarded_at_utc timestamptz := NULL::timestamptz;
  v_session_replacement_session_id uuid := NULL::uuid;
  v_session_version bigint := NULL::bigint;
  v_session_source_snapshot_run_id uuid := NULL::uuid;
  v_batch_status text := NULL::text;
  v_batch_execution_commit_state text := NULL::text;
  v_batch_source_workbench_session_id uuid := NULL::uuid;
  v_batch_source_snapshot_run_id uuid := NULL::uuid;
  v_batch_source_session_version bigint := NULL::bigint;
  v_locked_candidate_scope_count integer := 0;
  v_snooze_guard_json jsonb := '{}'::jsonb;
  v_snooze_guard_selected_line_count integer := 0;
  v_active_snooze_count integer := 0;
  v_retention_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_retention_mark_json jsonb := '{}'::jsonb;
  v_locked_allocation_row_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'p_operation_id is required for row-backed draft item insertion';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'p_actor_user_id is required for row-backed draft item insertion';
  END IF;

  IF p_candidate_scope_ids IS NULL OR jsonb_typeof(v_scope_ids) <> 'array' OR jsonb_array_length(v_scope_ids) = 0 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array';
  END IF;

  v_scope_id_count := jsonb_array_length(v_scope_ids);

  IF v_scope_id_count > 100 THEN
    RAISE EXCEPTION 'p_candidate_scope_ids exceeds the 100 row cap: %', v_scope_id_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  ) THEN
    RAISE EXCEPTION 'p_candidate_scope_ids must contain UUID strings only';
  END IF;

  SELECT COALESCE(jsonb_agg(candidate_scope_source.candidate_scope_id_text ORDER BY candidate_scope_source.candidate_scope_id_text), '[]'::jsonb)
  INTO v_candidate_scope_ids
  FROM (
    SELECT DISTINCT BTRIM(supplied_scope.scope_value #>> '{}') AS candidate_scope_id_text
    FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
  ) AS candidate_scope_source;

  IF jsonb_array_length(v_candidate_scope_ids) IS DISTINCT FROM v_scope_id_count THEN
    RAISE EXCEPTION 'DRAFT_ITEM_CANDIDATE_SCOPE_DUPLICATE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_CANDIDATE_SCOPE_DUPLICATE',
              'operation_id', p_operation_id::text,
              'supplied_scope_count', v_scope_id_count,
              'distinct_scope_count', jsonb_array_length(v_candidate_scope_ids),
              'message', 'Candidate scope identifiers must be unique for draft item insertion.'
            )::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT_ITEM_ACTOR_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_ACTOR_NOT_FOUND',
              'actor_user_id', p_actor_user_id::text,
              'message', 'The draft operation actor could not be verified.'
            )::text;
  END IF;

  -- Establish and hold the operation/session authority before taking candidate,
  -- allocation or timesheet locks. A stale source operation is never rebound to
  -- a replacement session inside this independently callable child writer.
  SELECT UPPER(BTRIM(COALESCE(operation_row.operation_type, ''))),
         UPPER(BTRIM(COALESCE(operation_row.status, ''))),
         UPPER(BTRIM(COALESCE(operation_row.phase, ''))),
         operation_row.actor_user_id,
         operation_row.workbench_session_id
  INTO v_operation_type,
       v_operation_status,
       v_operation_phase,
       v_operation_actor_user_id,
       v_workbench_session_id
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE OF operation_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT_ITEM_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'message', 'The DRAFT_CREATE operation could not be found.'
            )::text;
  END IF;

  IF v_operation_type <> 'DRAFT_CREATE'
     OR v_operation_status <> 'RUNNING'
     OR v_operation_phase <> 'INSERT_ITEMS'
     OR v_operation_actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'DRAFT_ITEM_OPERATION_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_OPERATION_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'operation_type', v_operation_type,
              'operation_status', v_operation_status,
              'operation_phase', v_operation_phase,
              'operation_actor_user_id', CASE
                WHEN v_operation_actor_user_id IS NULL THEN NULL
                ELSE v_operation_actor_user_id::text
              END,
              'supplied_actor_user_id', p_actor_user_id::text,
              'workbench_session_id', CASE
                WHEN v_workbench_session_id IS NULL THEN NULL
                ELSE v_workbench_session_id::text
              END,
              'message', 'The operation is not the active INSERT_ITEMS DRAFT_CREATE operation for this actor and Workbench session.'
            )::text;
  END IF;

  SELECT UPPER(BTRIM(COALESCE(session_row.status, ''))),
         session_row.discarded_at_utc,
         session_row.replacement_session_id,
         session_row.version,
         session_row.source_snapshot_run_id
  INTO v_session_status,
       v_session_discarded_at_utc,
       v_session_replacement_session_id,
       v_session_version,
       v_session_source_snapshot_run_id
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_workbench_session_id
  FOR UPDATE OF session_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT_ITEM_WORKBENCH_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_WORKBENCH_SESSION_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'message', 'The operation Workbench session could not be found.'
            )::text;
  END IF;

  IF v_session_status <> 'OPEN'
     OR v_session_discarded_at_utc IS NOT NULL
     OR v_session_replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'DRAFT_ITEM_WORKBENCH_SESSION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_WORKBENCH_SESSION_STALE',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'session_status', v_session_status,
              'discarded_at_utc', CASE
                WHEN v_session_discarded_at_utc IS NULL THEN NULL
                ELSE v_session_discarded_at_utc::text
              END,
              'replacement_session_id', CASE
                WHEN v_session_replacement_session_id IS NULL THEN NULL
                ELSE v_session_replacement_session_id::text
              END,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'The draft operation belongs to a stale or replaced Workbench session. Refresh Banking Pay before creating items.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_locked_candidate_scope_count
  FROM (
    SELECT scope_row.id
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.id IN (
      SELECT supplied_scope.candidate_scope_id_text::uuid
      FROM jsonb_array_elements_text(v_candidate_scope_ids)
        AS supplied_scope(candidate_scope_id_text)
    )
    ORDER BY scope_row.id
    FOR UPDATE OF scope_row
  ) AS locked_candidate_scopes;

  IF v_locked_candidate_scope_count IS DISTINCT FROM v_scope_id_count THEN
    RAISE EXCEPTION 'DRAFT_ITEM_CANDIDATE_SCOPE_TARGET_SET_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_CANDIDATE_SCOPE_TARGET_SET_CHANGED',
              'operation_id', p_operation_id::text,
              'expected_scope_count', v_scope_id_count,
              'locked_scope_count', v_locked_candidate_scope_count,
              'message', 'One or more candidate scopes no longer exist. Refresh Banking Pay before creating items.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.id IN (
      SELECT supplied_scope.candidate_scope_id_text::uuid
      FROM jsonb_array_elements_text(v_candidate_scope_ids)
        AS supplied_scope(candidate_scope_id_text)
    )
      AND (
        scope_row.operation_id IS DISTINCT FROM p_operation_id
        OR scope_row.workbench_session_id IS DISTINCT FROM v_workbench_session_id
        OR scope_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id
        OR UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('SCOPED', 'ALLOCATED', 'DRAFTED')
        OR scope_row.source_session_version IS DISTINCT FROM v_session_version
        OR scope_row.source_snapshot_run_id IS DISTINCT FROM v_session_source_snapshot_run_id
      )
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_CANDIDATE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_CANDIDATE_SCOPE_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'candidate_scope_ids', v_candidate_scope_ids,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'One or more candidate scopes no longer belong to the active operation, Workbench session or draft batch.'
            )::text;
  END IF;

  SELECT batch_row.pay_date,
         UPPER(BTRIM(COALESCE(batch_row.status, ''))),
         UPPER(BTRIM(COALESCE(batch_row.execution_commit_state, ''))),
         batch_row.source_workbench_session_id,
         batch_row.source_snapshot_run_id,
         batch_row.source_session_version
  INTO v_pay_date,
       v_batch_status,
       v_batch_execution_commit_state,
       v_batch_source_workbench_session_id,
       v_batch_source_snapshot_run_id,
       v_batch_source_session_version
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE OF batch_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT_ITEM_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'The draft pay batch could not be found.'
            )::text;
  END IF;

  IF v_pay_date IS NULL THEN
    RAISE EXCEPTION 'DRAFT_ITEM_PAY_BATCH_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_PAY_BATCH_PAY_DATE_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'The draft pay batch has no pay date.'
            )::text;
  END IF;

  IF v_batch_status <> 'DRAFT'
     OR v_batch_execution_commit_state <> 'NOT_SUBMITTED'
     OR v_batch_source_workbench_session_id IS DISTINCT FROM v_workbench_session_id
     OR v_batch_source_snapshot_run_id IS DISTINCT FROM v_session_source_snapshot_run_id
     OR v_batch_source_session_version IS DISTINCT FROM v_session_version THEN
    RAISE EXCEPTION 'DRAFT_ITEM_PAY_BATCH_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_PAY_BATCH_AUTHORITY_INVALID',
              'pay_batch_id', p_pay_batch_id::text,
              'batch_status', v_batch_status,
              'execution_commit_state', v_batch_execution_commit_state,
              'batch_source_workbench_session_id', CASE
                WHEN v_batch_source_workbench_session_id IS NULL THEN NULL
                ELSE v_batch_source_workbench_session_id::text
              END,
              'operation_workbench_session_id', v_workbench_session_id::text,
              'batch_source_session_version', v_batch_source_session_version,
              'operation_session_version', v_session_version,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'The draft batch no longer belongs to the active operation Workbench authority.'
            )::text;
  END IF;

  v_snooze_guard_json := public.pay_workbench_operation_active_snoozes_v1(
    p_operation_id,
    v_workbench_session_id,
    v_candidate_scope_ids
  );

  IF LOWER(BTRIM(COALESCE(v_snooze_guard_json->>'ok', 'false'))) NOT IN ('true', 't', '1') THEN
    RAISE EXCEPTION 'DRAFT_ITEM_SNOOZE_GUARD_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_SNOOZE_GUARD_INVALID',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'message', 'The live snooze authority returned an invalid result.'
            )::text;
  END IF;

  v_snooze_guard_selected_line_count := CASE
    WHEN COALESCE(v_snooze_guard_json->>'selected_line_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_snooze_guard_json->>'selected_line_count')::integer
    ELSE 0
  END;
  v_active_snooze_count := CASE
    WHEN COALESCE(v_snooze_guard_json->>'active_snooze_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_snooze_guard_json->>'active_snooze_count')::integer
    ELSE 0
  END;

  IF v_active_snooze_count > 0 THEN
    RAISE EXCEPTION 'ACTIVE_SNOOZE_PREVENTS_DRAFT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_strip_nulls(
              jsonb_build_object(
                'code', 'ACTIVE_SNOOZE_PREVENTS_DRAFT',
                'message', 'One or more selected payments are currently snoozed. Banking Pay has been refreshed so you can review the updated selection.',
                'operation_id', p_operation_id::text,
                'workbench_session_id', v_workbench_session_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'refresh_required', true,
                'next_action', 'REFRESH_WORKBENCH'
              )
              || COALESCE(v_snooze_guard_json, '{}'::jsonb)
            )::text;
  END IF;

  SELECT finance_window.vat_rate_pct
  INTO v_vat_rate_pct
  FROM public.settings_finance_windows AS finance_window
  WHERE v_pay_date >= finance_window.date_from
    AND v_pay_date <= COALESCE(finance_window.date_to, 'infinity'::date)
  ORDER BY finance_window.date_from DESC, finance_window.id DESC
  LIMIT 1;

  IF v_vat_rate_pct IS NULL THEN
    RAISE EXCEPTION 'VAT rate not found for pay_batch % pay_date %', p_pay_batch_id, v_pay_date;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'allocation_row_id', allocation_row.id::text,
           'candidate_scope_id', allocation_row.candidate_scope_id::text,
           'source_ref', allocation_row.source_ref,
           'timesheet_id', allocation_identity.timesheet_id_text,
           'key_type', allocation_identity.key_type,
           'key_value', allocation_identity.key_value,
           'allocated_amount', allocation_row.allocated_amount,
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED'
         ) ORDER BY allocation_row.sort_order, allocation_row.id), '[]'::jsonb)
  INTO v_synthetic_total_item_rows
  FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
  CROSS JOIN LATERAL (
    SELECT
      NULLIF(BTRIM(COALESCE(
        allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}',
        allocation_row.allocation_basis_json->>'timesheet_id',
        allocation_row.allocation_basis_json#>>'{line,timesheet_id}',
        allocation_row.allocation_basis_json#>>'{line,real_business_timesheet_id}',
        ''
      )), '') AS timesheet_id_text,
      UPPER(NULLIF(BTRIM(COALESCE(
        allocation_row.allocation_basis_json#>>'{economic_key,key_type}',
        allocation_row.allocation_basis_json->>'key_type',
        allocation_row.allocation_basis_json#>>'{line,economic_key,key_type}',
        allocation_row.allocation_basis_json#>>'{line,key_type}',
        allocation_row.allocation_basis_json#>>'{line,component_key_type}',
        ''
      )), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(
        allocation_row.allocation_basis_json#>>'{economic_key,key_value}',
        allocation_row.allocation_basis_json->>'key_value',
        allocation_row.allocation_basis_json#>>'{line,economic_key,key_value}',
        allocation_row.allocation_basis_json#>>'{line,key_value}',
        allocation_row.allocation_basis_json#>>'{line,component_key_value}',
        ''
      )), '') AS key_value,
      LOWER(BTRIM(COALESCE(
        allocation_row.source_ref,
        allocation_row.allocation_basis_json#>>'{line,row_key}',
        allocation_row.allocation_basis_json#>>'{line,line_key}',
        allocation_row.allocation_basis_json#>>'{line,source_ref}',
        allocation_row.allocation_basis_json->>'row_key',
        allocation_row.allocation_basis_json->>'line_key',
        allocation_row.allocation_basis_json->>'source_ref',
        ''
      ))) AS identity_text
  ) AS allocation_identity
  WHERE allocation_row.operation_id = p_operation_id
    AND allocation_row.candidate_scope_id IN (
      SELECT supplied_scope.candidate_scope_id_text::uuid
      FROM jsonb_array_elements_text(v_candidate_scope_ids) AS supplied_scope(candidate_scope_id_text)
    )
    AND UPPER(BTRIM(COALESCE(allocation_row.status, ''))) NOT IN ('FAILED', 'ERROR', 'CANCELLED', 'CANCELED', 'SKIPPED', 'VOIDED')
    AND allocation_identity.key_type = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(allocation_identity.key_value, ''))) = 'TOTAL'
    AND allocation_identity.identity_text LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(allocation_row.allocation_basis_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,resolved_segment_rows_replace_source_total}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS sibling_allocation_row
        CROSS JOIN LATERAL (
          SELECT
            NULLIF(BTRIM(COALESCE(
              sibling_allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}',
              sibling_allocation_row.allocation_basis_json->>'timesheet_id',
              sibling_allocation_row.allocation_basis_json#>>'{line,timesheet_id}',
              sibling_allocation_row.allocation_basis_json#>>'{line,real_business_timesheet_id}',
              ''
            )), '') AS timesheet_id_text,
            UPPER(NULLIF(BTRIM(COALESCE(
              sibling_allocation_row.allocation_basis_json#>>'{economic_key,key_type}',
              sibling_allocation_row.allocation_basis_json->>'key_type',
              sibling_allocation_row.allocation_basis_json#>>'{line,economic_key,key_type}',
              sibling_allocation_row.allocation_basis_json#>>'{line,key_type}',
              sibling_allocation_row.allocation_basis_json#>>'{line,component_key_type}',
              ''
            )), '')) AS key_type,
            LOWER(BTRIM(COALESCE(
              sibling_allocation_row.source_ref,
              sibling_allocation_row.allocation_basis_json#>>'{line,row_key}',
              sibling_allocation_row.allocation_basis_json#>>'{line,line_key}',
              sibling_allocation_row.allocation_basis_json#>>'{line,source_ref}',
              sibling_allocation_row.allocation_basis_json->>'row_key',
              sibling_allocation_row.allocation_basis_json->>'line_key',
              sibling_allocation_row.allocation_basis_json->>'source_ref',
              ''
            ))) AS identity_text
        ) AS sibling_identity
        WHERE sibling_allocation_row.operation_id = allocation_row.operation_id
          AND sibling_allocation_row.candidate_scope_id = allocation_row.candidate_scope_id
          AND sibling_allocation_row.id IS DISTINCT FROM allocation_row.id
          AND UPPER(BTRIM(COALESCE(sibling_allocation_row.status, ''))) NOT IN ('FAILED', 'ERROR', 'CANCELLED', 'CANCELED', 'SKIPPED', 'VOIDED')
          AND sibling_identity.key_type = 'TS_DAY'
          AND sibling_identity.identity_text LIKE '%:segment:%'
          AND sibling_identity.timesheet_id_text IS NOT DISTINCT FROM allocation_identity.timesheet_id_text
      )
    );

  IF jsonb_array_length(COALESCE(v_synthetic_total_item_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'synthetic_total_item_rows', COALESCE(v_synthetic_total_item_rows, '[]'::jsonb),
              'message', 'A stale resolved-timesheet synthetic total row reached item creation. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  WITH existing_linked_items AS (
    SELECT
      allocation_row.id AS allocation_row_id,
      existing_item.id AS pay_batch_item_id
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    JOIN public.pay_batch_candidates AS existing_batch_candidate
      ON existing_batch_candidate.pay_batch_id = p_pay_batch_id
     AND existing_batch_candidate.candidate_id = allocation_row.candidate_id
    JOIN public.pay_batch_items AS existing_item
      ON existing_item.pay_batch_candidate_id = existing_batch_candidate.id
     AND existing_item.operation_source_key = allocation_row.operation_source_key
     AND COALESCE(existing_item.is_voided, false) = false
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_scope_id IN (
        SELECT supplied_scope.candidate_scope_id_text::uuid
        FROM jsonb_array_elements_text(v_candidate_scope_ids) AS supplied_scope(candidate_scope_id_text)
      )
      AND allocation_row.operation_source_key IS NOT NULL
      AND (
        (
          UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) = 'OVERPAYMENT_RECOVERY'
          AND existing_item.item_type = 'OVERPAYMENT_RECOVERY'
        )
        OR (
          UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
          AND existing_item.item_type <> 'OVERPAYMENT_RECOVERY'
        )
      )
      AND UPPER(BTRIM(COALESCE(allocation_row.status, ''))) NOT IN ('FAILED', 'ERROR', 'CANCELLED', 'CANCELED', 'SKIPPED', 'VOIDED')
  ), repaired_existing_links AS (
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET status = 'ITEM_CREATED',
        pay_batch_id = p_pay_batch_id,
        pay_batch_item_id = existing_linked_items.pay_batch_item_id,
        updated_at_utc = v_now
    FROM existing_linked_items
    WHERE allocation_update.id = existing_linked_items.allocation_row_id
      AND (
        allocation_update.pay_batch_id IS DISTINCT FROM p_pay_batch_id
        OR allocation_update.pay_batch_item_id IS DISTINCT FROM existing_linked_items.pay_batch_item_id
        OR UPPER(BTRIM(COALESCE(allocation_update.status, ''))) <> 'ITEM_CREATED'
      )
    RETURNING allocation_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_repaired_existing_item_link_count
  FROM repaired_existing_links;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (
           WHERE allocation_row.pay_batch_id = p_pay_batch_id
             AND allocation_row.pay_batch_item_id IS NOT NULL
             AND EXISTS (
               SELECT 1
               FROM public.pay_batch_items AS existing_item
               JOIN public.pay_batch_candidates AS existing_batch_candidate
                 ON existing_batch_candidate.id = existing_item.pay_batch_candidate_id
               WHERE existing_item.id = allocation_row.pay_batch_item_id
                 AND existing_batch_candidate.pay_batch_id = p_pay_batch_id
                 AND existing_batch_candidate.candidate_id = allocation_row.candidate_id
                 AND COALESCE(existing_item.is_voided, false) = false
                 AND (
                   (
                     UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) = 'OVERPAYMENT_RECOVERY'
                     AND existing_item.item_type = 'OVERPAYMENT_RECOVERY'
                   )
                   OR (
                     UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
                     AND existing_item.item_type <> 'OVERPAYMENT_RECOVERY'
                   )
                 )
             )
         )::integer
  INTO v_expected_allocation_row_count, v_linked_allocation_row_count
  FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
  WHERE allocation_row.operation_id = p_operation_id
    AND allocation_row.candidate_scope_id IN (
      SELECT supplied_scope.candidate_scope_id_text::uuid
      FROM jsonb_array_elements_text(v_candidate_scope_ids) AS supplied_scope(candidate_scope_id_text)
    )
    AND UPPER(BTRIM(COALESCE(allocation_row.status, ''))) NOT IN ('FAILED', 'ERROR', 'CANCELLED', 'CANCELED', 'SKIPPED', 'VOIDED');

  SELECT COUNT(*)::integer
  INTO v_scope_expects_item_count
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.id IN (
      SELECT supplied_scope.candidate_scope_id_text::uuid
      FROM jsonb_array_elements_text(v_candidate_scope_ids) AS supplied_scope(candidate_scope_id_text)
    )
    AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND (
      CASE
        WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page', '') ~ '^[0-9]+$'
          THEN (scope_row.candidate_totals_json->>'selected_row_count_seeded_in_page')::integer
        WHEN COALESCE(scope_row.candidate_totals_json->>'selected_preview_row_count', '') ~ '^[0-9]+$'
          THEN (scope_row.candidate_totals_json->>'selected_preview_row_count')::integer
        WHEN COALESCE(scope_row.candidate_totals_json->>'selected_row_count', '') ~ '^[0-9]+$'
          THEN (scope_row.candidate_totals_json->>'selected_row_count')::integer
        ELSE 0
      END > 0
      OR (
        jsonb_typeof(scope_row.selected_canonical_preview_lines_json) = 'array'
        AND jsonb_array_length(scope_row.selected_canonical_preview_lines_json) > 0
      )
      OR (
        jsonb_typeof(scope_row.effective_canonical_preview_lines_json) = 'array'
        AND jsonb_array_length(scope_row.effective_canonical_preview_lines_json) > 0
      )
    );

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_item_allocation_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_item_allocation_page ON COMMIT DROP AS
  WITH allocation_page_raw AS (
    SELECT
      allocation_row.id,
      allocation_row.operation_id,
      allocation_row.candidate_scope_id,
      allocation_row.pay_batch_id,
      allocation_row.candidate_id,
      allocation_row.pay_channel,
      allocation_row.finance_case_id,
      allocation_row.finance_component_id,
      allocation_row.allocation_type,
      allocation_row.source_ref,
      allocation_row.operation_source_key,
      allocation_row.allocated_amount,
      allocation_row.allocation_basis_json,
      allocation_row.sort_order,
      allocation_row.status
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_scope_id IN (
        SELECT (supplied_scope.scope_value #>> '{}')::uuid
        FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
      )
      AND UPPER(BTRIM(COALESCE(allocation_row.status, ''))) IN ('PENDING', 'ITEM_PENDING')
    ORDER BY allocation_row.candidate_scope_id, allocation_row.sort_order, allocation_row.id
    LIMIT 100
  ), allocation_page_keys AS (
    SELECT
      allocation_page_raw.*,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_page_raw.allocation_basis_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_page_raw.allocation_basis_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{line,timesheet_id}', allocation_page_raw.allocation_basis_json#>>'{line,real_business_timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{line,timesheet_id}', allocation_page_raw.allocation_basis_json#>>'{line,real_business_timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS line_timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{economic_key,key_type}', allocation_page_raw.allocation_basis_json->>'key_type', '')), '')) AS allocation_key_type,
      NULLIF(BTRIM(COALESCE(allocation_page_raw.allocation_basis_json#>>'{economic_key,key_value}', allocation_page_raw.allocation_basis_json->>'key_value', '')), '') AS allocation_key_value
    FROM allocation_page_raw
  ), allocation_timesheet_refs AS (
    SELECT allocation_page_keys.economic_key_timesheet_id AS timesheet_id
    FROM allocation_page_keys
    WHERE allocation_page_keys.economic_key_timesheet_id IS NOT NULL
    UNION
    SELECT allocation_page_keys.line_timesheet_id AS timesheet_id
    FROM allocation_page_keys
    WHERE allocation_page_keys.line_timesheet_id IS NOT NULL
  ), allocation_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT allocation_timesheet_refs.timesheet_id ORDER BY allocation_timesheet_refs.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM allocation_timesheet_refs
  ), allocation_rotation_scope AS (
    SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
      rotation_scope.requested_timesheet_id,
      COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope.family_timesheet_id IS NOT NULL AND rotation_scope.family_is_current IS NOT NULL) AS rotation_scope_resolved,
      COALESCE(rotation_scope.requested_is_canonical, false) AS requested_is_canonical
    FROM allocation_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(allocation_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
    ORDER BY
      rotation_scope.requested_timesheet_id,
      rotation_scope.family_is_current DESC NULLS LAST,
      rotation_scope.family_version DESC NULLS LAST,
      rotation_scope.family_timesheet_id
  ), scope_canonical_line_matches AS (
    SELECT DISTINCT
      allocation_page_keys.id AS allocation_row_id,
      COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id) AS canonical_timesheet_id
    FROM allocation_page_keys
    JOIN public.banking_pay_operation_candidate_scope AS scope_row
      ON scope_row.id = allocation_page_keys.candidate_scope_id
     AND scope_row.operation_id = allocation_page_keys.operation_id
    LEFT JOIN allocation_rotation_scope AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = allocation_page_keys.economic_key_timesheet_id
    LEFT JOIN allocation_rotation_scope AS line_rotation
      ON line_rotation.requested_timesheet_id = allocation_page_keys.line_timesheet_id
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(scope_row.selected_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(scope_row.selected_canonical_preview_lines_json) > 0
          THEN scope_row.selected_canonical_preview_lines_json
        WHEN jsonb_typeof(scope_row.effective_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(scope_row.effective_canonical_preview_lines_json) > 0
          THEN scope_row.effective_canonical_preview_lines_json
        ELSE '[]'::jsonb
      END
    ) AS scope_line(line_json)
    WHERE COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id) IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(scope_line.line_json#>>'{economic_key,timesheet_id}', scope_line.line_json->>'timesheet_id', '')), '') = COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text
      AND UPPER(NULLIF(BTRIM(COALESCE(scope_line.line_json#>>'{economic_key,key_type}', scope_line.line_json->>'key_type', scope_line.line_json->>'component_key_type', '')), '')) IS NOT DISTINCT FROM allocation_page_keys.allocation_key_type
      AND NULLIF(BTRIM(COALESCE(scope_line.line_json#>>'{economic_key,key_value}', scope_line.line_json->>'key_value', scope_line.line_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM allocation_page_keys.allocation_key_value
      AND NULLIF(BTRIM(COALESCE(scope_line.line_json->>'row_key', scope_line.line_json->>'source_ref', '')), '') IS NOT DISTINCT FROM NULLIF(BTRIM(COALESCE(allocation_page_keys.allocation_basis_json->>'row_key', allocation_page_keys.allocation_basis_json#>>'{line,row_key}', allocation_page_keys.source_ref, '')), '')
  )
  SELECT
    allocation_page_keys.id,
    allocation_page_keys.operation_id,
    allocation_page_keys.candidate_scope_id,
    allocation_page_keys.pay_batch_id,
    allocation_page_keys.candidate_id,
    allocation_page_keys.pay_channel,
    allocation_page_keys.finance_case_id,
    allocation_page_keys.finance_component_id,
    allocation_page_keys.allocation_type,
    allocation_page_keys.source_ref,
    allocation_page_keys.operation_source_key,
    allocation_page_keys.allocated_amount,
    allocation_page_keys.allocation_basis_json AS source_allocation_basis_json,
    jsonb_strip_nulls(
      allocation_page_keys.allocation_basis_json
      || CASE
        WHEN COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id) IS NULL THEN '{}'::jsonb
        ELSE jsonb_build_object(
          'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text,
          'economic_key', COALESCE(allocation_page_keys.allocation_basis_json->'economic_key', '{}'::jsonb)
            || jsonb_build_object(
              'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text,
              'key_type', allocation_page_keys.allocation_key_type,
              'key_value', allocation_page_keys.allocation_key_value
            ),
          'line', COALESCE(allocation_page_keys.allocation_basis_json->'line', '{}'::jsonb)
            || jsonb_build_object(
              'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text,
              'real_business_timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text,
              'economic_key', COALESCE(allocation_page_keys.allocation_basis_json#>'{line,economic_key}', '{}'::jsonb)
                || jsonb_build_object(
                  'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id)::text,
                  'key_type', allocation_page_keys.allocation_key_type,
                  'key_value', allocation_page_keys.allocation_key_value
                )
            )
        )
      END
      || CASE
        WHEN allocation_page_keys.economic_key_timesheet_id IS NOT NULL
         AND allocation_page_keys.economic_key_timesheet_id IS DISTINCT FROM COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id) THEN jsonb_build_object(
          'rotation_requested_timesheet_id', allocation_page_keys.economic_key_timesheet_id::text
        )
        ELSE '{}'::jsonb
      END
    ) AS allocation_basis_json,
    allocation_page_keys.sort_order,
    allocation_page_keys.status,
    allocation_page_keys.economic_key_timesheet_id,
    allocation_page_keys.line_timesheet_id,
    COALESCE(economic_key_rotation.canonical_timesheet_id, line_rotation.canonical_timesheet_id) AS canonical_timesheet_id,
    allocation_page_keys.allocation_key_type,
    allocation_page_keys.allocation_key_value,
    CASE
      WHEN allocation_page_keys.economic_key_timesheet_id IS NULL AND allocation_page_keys.line_timesheet_id IS NULL THEN true
      WHEN allocation_page_keys.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN false
      WHEN allocation_page_keys.line_timesheet_id IS NOT NULL AND COALESCE(line_rotation.rotation_scope_resolved, false) = false THEN false
      WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
       AND line_rotation.canonical_timesheet_id IS NOT NULL
       AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_rotation.canonical_timesheet_id THEN false
      WHEN COALESCE(economic_key_rotation.requested_is_canonical, line_rotation.requested_is_canonical, true) = false
       AND scope_canonical_line_matches.allocation_row_id IS NULL THEN false
      ELSE true
    END AS rotation_validation_ok,
    CASE
      WHEN allocation_page_keys.economic_key_timesheet_id IS NULL AND allocation_page_keys.line_timesheet_id IS NULL THEN NULL::text
      WHEN allocation_page_keys.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
      WHEN allocation_page_keys.line_timesheet_id IS NOT NULL AND COALESCE(line_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_LINE_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
      WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
       AND line_rotation.canonical_timesheet_id IS NOT NULL
       AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM line_rotation.canonical_timesheet_id THEN 'ALLOCATION_LINE_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
      WHEN COALESCE(economic_key_rotation.requested_is_canonical, line_rotation.requested_is_canonical, true) = false
       AND scope_canonical_line_matches.allocation_row_id IS NULL THEN 'ALLOCATION_TIMESHEET_ROTATED_WITHOUT_VALIDATED_CANONICAL_SCOPE_ROW'
      ELSE NULL::text
    END AS rotation_validation_failure_reason
  FROM allocation_page_keys
  LEFT JOIN allocation_rotation_scope AS economic_key_rotation
    ON economic_key_rotation.requested_timesheet_id = allocation_page_keys.economic_key_timesheet_id
  LEFT JOIN allocation_rotation_scope AS line_rotation
    ON line_rotation.requested_timesheet_id = allocation_page_keys.line_timesheet_id
  LEFT JOIN scope_canonical_line_matches
    ON scope_canonical_line_matches.allocation_row_id = allocation_page_keys.id;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(allocation_page.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY')::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(allocation_page.allocation_type, ''))) = 'OVERPAYMENT_RECOVERY')::integer
  INTO v_page_allocation_row_count,
       v_ordinary_page_allocation_row_count,
       v_deferred_finance_adjustment_row_count
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_page;

  PERFORM 1
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_page
  WHERE allocation_page.rotation_validation_ok IS NOT TRUE
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', p_operation_id::text,
              'message', 'One or more allocation rows no longer resolve to a validated current canonical timesheet. Refresh draft scope before creating batch items.'
            )::text;
  END IF;

  IF COALESCE(v_ordinary_page_allocation_row_count, 0) <= 0 THEN
    IF COALESCE(v_expected_allocation_row_count, 0) > 0
       AND COALESCE(v_linked_allocation_row_count, 0) = COALESCE(v_expected_allocation_row_count, 0) THEN
      UPDATE public.banking_pay_operation_candidate_scope AS scope_update
      SET pay_batch_id = p_pay_batch_id,
          status = 'DRAFTED',
          updated_at_utc = v_now
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.id IN (
          SELECT supplied_scope.candidate_scope_id_text::uuid
          FROM jsonb_array_elements_text(v_candidate_scope_ids) AS supplied_scope(candidate_scope_id_text)
        );

      RETURN jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'candidate_scope_count', v_scope_id_count,
        'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
        'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
        'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
        'ordinary_page_allocation_row_count', COALESCE(v_ordinary_page_allocation_row_count, 0),
        'deferred_finance_adjustment_rows', COALESCE(v_deferred_finance_adjustment_row_count, 0),
        'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
        'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
        'inserted_item_rows', 0,
        'reused_item_rows', COALESCE(v_linked_allocation_row_count, 0),
        'skipped_item_rows', 0,
        'failed_item_rows', 0,
        'has_more', false
      );
    END IF;

    IF COALESCE(v_deferred_finance_adjustment_row_count, 0) > 0 THEN
      RETURN jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'candidate_scope_count', v_scope_id_count,
        'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
        'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
        'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
        'ordinary_page_allocation_row_count', COALESCE(v_ordinary_page_allocation_row_count, 0),
        'deferred_finance_adjustment_rows', COALESCE(v_deferred_finance_adjustment_row_count, 0),
        'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
        'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
        'inserted_item_rows', 0,
        'reused_item_rows', 0,
        'skipped_item_rows', COALESCE(v_deferred_finance_adjustment_row_count, 0),
        'failed_item_rows', 0,
        'has_more', false
      );
    END IF;

    IF COALESCE(v_scope_expects_item_count, 0) > 0
       OR COALESCE(v_expected_allocation_row_count, 0) > 0 THEN
      RAISE EXCEPTION 'DRAFT_ITEM_ALLOCATION_ROWS_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_ITEM_ALLOCATION_ROWS_EMPTY',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'candidate_scope_count', v_scope_id_count,
                'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
                'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
                'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
                'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
                'scope_expects_item_count', COALESCE(v_scope_expects_item_count, 0),
                'message', 'No pending allocation rows were available and not all expected row-backed allocation rows were already linked to draft items.'
              )::text;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'candidate_scope_count', v_scope_id_count,
      'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
      'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
      'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
      'ordinary_page_allocation_row_count', COALESCE(v_ordinary_page_allocation_row_count, 0),
      'deferred_finance_adjustment_rows', COALESCE(v_deferred_finance_adjustment_row_count, 0),
      'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
      'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
      'inserted_item_rows', 0,
      'reused_item_rows', 0,
      'skipped_item_rows', 0,
      'failed_item_rows', 0,
      'has_more', false
    );
  END IF;


  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'allocation_row_id', allocation_row.id::text,
           'candidate_scope_id', allocation_row.candidate_scope_id::text,
           'source_ref', allocation_row.source_ref,
           'timesheet_id', allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}',
           'key_type', COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type'),
           'key_value', COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value'),
           'allocated_amount', allocation_row.allocated_amount,
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED'
         ) ORDER BY allocation_row.sort_order, allocation_row.id), '[]'::jsonb)
  INTO v_synthetic_total_item_rows
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
  WHERE UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', ''))) = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', ''))) = 'TOTAL'
    AND LOWER(BTRIM(COALESCE(allocation_row.source_ref, allocation_row.allocation_basis_json#>>'{line,row_key}', allocation_row.allocation_basis_json#>>'{line,line_key}', allocation_row.allocation_basis_json#>>'{line,source_ref}', allocation_row.allocation_basis_json->>'row_key', allocation_row.allocation_basis_json->>'line_key', ''))) LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(allocation_row.allocation_basis_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,resolved_segment_rows_replace_source_total}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (allocation_row.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(scope_row.selected_canonical_preview_lines_json) = 'array' THEN scope_row.selected_canonical_preview_lines_json ELSE '[]'::jsonb END) AS selected_line(line_json)
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.id = allocation_row.candidate_scope_id
          AND UPPER(BTRIM(COALESCE(selected_line.line_json#>>'{economic_key,key_type}', selected_line.line_json->>'key_type', ''))) = 'TS_DAY'
          AND LOWER(BTRIM(COALESCE(selected_line.line_json->>'row_key', selected_line.line_json->>'line_key', selected_line.line_json->>'source_ref', ''))) LIKE '%:segment:%'
          AND COALESCE(selected_line.line_json#>>'{economic_key,timesheet_id}', selected_line.line_json->>'timesheet_id', selected_line.line_json->>'real_business_timesheet_id', '') = COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json#>>'{line,timesheet_id}', allocation_row.allocation_basis_json#>>'{line,real_business_timesheet_id}', '')
      )
    );

  IF jsonb_array_length(COALESCE(v_synthetic_total_item_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ITEM_BLOCKED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'synthetic_total_item_rows', COALESCE(v_synthetic_total_item_rows, '[]'::jsonb),
              'message', 'A stale resolved-timesheet synthetic total row reached item creation. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  PERFORM 1
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
  WHERE LOWER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{line,row_key}', allocation_row.allocation_basis_json#>>'{line,line_key}', allocation_row.allocation_basis_json->>'row_key', allocation_row.allocation_basis_json->>'line_key', ''))) LIKE 'timesheet_snapshot:%'
     OR UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{line,source_kind}', allocation_row.allocation_basis_json#>>'{line,source_type}', allocation_row.allocation_basis_json->>'source_kind', allocation_row.allocation_basis_json->>'source_type', ''))) IN (
          'TIMESHEET_SNAPSHOT',
          'TIMESHEET_SNAPSHOT_EVIDENCE',
          'RAW_TIMESHEET_SNAPSHOT',
          'INTERNAL_ONLY',
          'NO_DELTA',
          'EXCLUDED'
        )
     OR UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{line,presentation_section}', allocation_row.allocation_basis_json->>'presentation_section', ''))) <> 'READY_TO_PAY'
     OR LOWER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{line,draftable}', allocation_row.allocation_basis_json->>'draftable', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR LOWER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{line,is_ready_for_draft}', allocation_row.allocation_basis_json->>'is_ready_for_draft', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', ''))) NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
     OR NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', '')), '') IS NULL
     OR ROUND(COALESCE(allocation_row.allocated_amount, 0), 2) = 0
     OR (
       ROUND(COALESCE(allocation_row.allocated_amount, 0), 2) < 0
       AND NOT (
         UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) = 'OVERPAYMENT_RECOVERY'
         AND allocation_row.finance_case_id IS NOT NULL
       )
     )
     OR (
       ROUND(COALESCE(allocation_row.allocated_amount, 0), 2) <= 0
       AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
     )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'MALFORMED_PREVIEW_ALLOCATION_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ALLOCATION_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'Allocation rows from the preview are not valid draftable Ready to Pay rows.'
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_item_allocation_outstanding_components;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_item_allocation_outstanding_components ON COMMIT DROP AS
  SELECT
    outstanding_components.timesheet_id,
    outstanding_components.key_type,
    outstanding_components.key_value,
    outstanding_components.outstanding_ex_vat
  FROM public._pay_outstanding_components(
    ARRAY(
      SELECT DISTINCT allocation_page.canonical_timesheet_id
      FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_page
      WHERE allocation_page.canonical_timesheet_id IS NOT NULL
    ),
    p_pay_batch_id
  ) AS outstanding_components;

  PERFORM 1
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
  CROSS JOIN LATERAL (
    SELECT
      CASE WHEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', allocation_row.allocation_basis_json#>>'{line,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', allocation_row.allocation_basis_json#>>'{line,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', '')), '') AS key_value
  ) AS allocation_key
  CROSS JOIN LATERAL (
    SELECT
      CASE
        WHEN component_counts.object_component_count = 1
         AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
        ELSE NULL::text
      END AS single_fixed_reimbursement_key_type,
      CASE
        WHEN component_counts.object_component_count = 1
         AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
        ELSE NULL::text
      END AS single_fixed_reimbursement_key_value
    FROM (
      SELECT
        (COUNT(*) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
        ))::integer AS object_component_count,
        (COUNT(*) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ))::integer AS fixed_reimbursement_component_count,
        MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ) AS fixed_reimbursement_key_type,
        MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ) AS fixed_reimbursement_key_value
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(allocation_row.allocation_basis_json#>'{line,case_components}') = 'array' THEN allocation_row.allocation_basis_json#>'{line,case_components}'
          ELSE '[]'::jsonb
        END
      ) AS component_element(value)
    ) AS component_counts
  ) AS component_probe
  WHERE UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
    AND component_probe.single_fixed_reimbursement_key_type IS NOT NULL
    AND (
      allocation_key.key_type IS DISTINCT FROM component_probe.single_fixed_reimbursement_key_type
      OR allocation_key.key_value IS DISTINCT FROM component_probe.single_fixed_reimbursement_key_value
    )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'PREVIEW_ALLOCATION_REIMBURSEMENT_KEY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PREVIEW_ALLOCATION_REIMBURSEMENT_KEY_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'A fixed reimbursement preview allocation did not use its EXPENSE_CODE/ADDITIONAL_CODE economic key.'
            )::text;
  END IF;

  PERFORM 1
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
  CROSS JOIN LATERAL (
    SELECT
      CASE WHEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', allocation_row.allocation_basis_json#>>'{line,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', allocation_row.allocation_basis_json#>>'{line,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', '')), '') AS key_value
  ) AS allocation_key
  CROSS JOIN LATERAL (
    SELECT
      CASE
        WHEN component_counts.object_component_count = 1
         AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
        ELSE NULL::text
      END AS single_fixed_reimbursement_key_type,
      CASE
        WHEN component_counts.object_component_count = 1
         AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
        ELSE NULL::text
      END AS single_fixed_reimbursement_key_value
    FROM (
      SELECT
        (COUNT(*) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
        ))::integer AS object_component_count,
        (COUNT(*) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ))::integer AS fixed_reimbursement_component_count,
        MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ) AS fixed_reimbursement_key_type,
        MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
          WHERE component_element.value IS NOT NULL
            AND jsonb_typeof(component_element.value) = 'object'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
            AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        ) AS fixed_reimbursement_key_value
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(allocation_row.allocation_basis_json#>'{line,case_components}') = 'array' THEN allocation_row.allocation_basis_json#>'{line,case_components}'
          ELSE '[]'::jsonb
        END
      ) AS component_element(value)
    ) AS component_counts
  ) AS component_probe
  LEFT JOIN pg_temp.tmp_pay_batch_item_allocation_outstanding_components AS outstanding_component
    ON outstanding_component.timesheet_id = allocation_key.timesheet_id
   AND outstanding_component.key_type = allocation_key.key_type
   AND outstanding_component.key_value = allocation_key.key_value
  WHERE UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
    AND component_probe.single_fixed_reimbursement_key_type IS NOT NULL
    AND allocation_key.key_type = component_probe.single_fixed_reimbursement_key_type
    AND allocation_key.key_value = component_probe.single_fixed_reimbursement_key_value
    AND (
      outstanding_component.outstanding_ex_vat IS NULL
      OR ROUND(COALESCE(outstanding_component.outstanding_ex_vat, 0), 2) <= 0
      OR ROUND(COALESCE(allocation_row.allocated_amount, 0), 2) <= 0
      OR ROUND(COALESCE(allocation_row.allocated_amount, 0), 2) > ROUND(COALESCE(outstanding_component.outstanding_ex_vat, 0), 2)
    )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'PREVIEW_ALLOCATION_REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PREVIEW_ALLOCATION_REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'A selected fixed reimbursement preview allocation no longer has enough outstanding entitlement to draft.'
            )::text;
  END IF;

  PERFORM 1
  FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
  WHERE UPPER(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', ''))) = 'TS_DAY'
    AND NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', '')), '') !~ '^\d{4}-\d{2}-\d{2}$'
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve TS_DAY economic keys to YYYY-MM-DD date buckets';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_item_normalised_rows;
  CREATE TEMPORARY TABLE tmp_pay_batch_item_normalised_rows ON COMMIT DROP AS
  WITH prepared_rows AS (
    SELECT
      allocation_row.id AS allocation_row_id,
      allocation_row.candidate_scope_id,
      allocation_row.operation_id,
      allocation_row.pay_batch_id,
      allocation_row.candidate_id,
      allocation_row.pay_channel,
      allocation_row.finance_case_id,
      allocation_row.finance_component_id,
      allocation_row.source_ref,
      allocation_row.allocation_type,
      allocation_row.operation_source_key,
      allocation_row.allocated_amount,
      allocation_row.allocation_basis_json,
      COALESCE(allocation_row.allocation_basis_json->'line', '{}'::jsonb) AS line_json,
      CASE WHEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,timesheet_id}', allocation_row.allocation_basis_json->>'timesheet_id', '')), '')::uuid ELSE NULL::uuid END AS timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_type}', allocation_row.allocation_basis_json->>'key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(allocation_row.allocation_basis_json#>>'{economic_key,key_value}', allocation_row.allocation_basis_json->>'key_value', '')), '') AS key_value
    FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
    WHERE UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
  ), normalised_source_rows AS (
    SELECT
      prepared_rows.*,
      CASE
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'line_type', prepared_rows.allocation_type, '')) IN ('MANUAL_ADJUSTMENT_CARRY_FORWARD', 'MANUAL_CREDIT_PAYOUT') THEN 'MANUAL_CREDIT_PAYOUT'
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'line_type', prepared_rows.allocation_type, '')) = 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
        WHEN prepared_rows.key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN prepared_rows.key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN prepared_rows.key_type = 'EXPENSE_CODE' AND UPPER(COALESCE(prepared_rows.key_value, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        ELSE 'EXPENSE_DELTA'
      END AS item_type,
      CASE WHEN prepared_rows.key_type IN ('TS_DAY', 'TS_TOTAL') THEN NULLIF(BTRIM(COALESCE(prepared_rows.line_json#>>'{source_basis_json,segment_key}', prepared_rows.line_json#>>'{source_basis,segment_key}', prepared_rows.line_json->>'segment_key', '')), '') ELSE NULL::text END AS segment_key,
      ROUND(COALESCE(prepared_rows.allocated_amount, 0), 2)::numeric(12,2) AS amount_ex_vat,
      CASE
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'classification', prepared_rows.line_json->>'frozen_component_classification', '')) = 'REIMBURSEMENT_GROSS_FIXED' THEN 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'classification', prepared_rows.line_json->>'frozen_component_classification', '')) = 'NET_PAY_FIXED_RECOVERY' THEN 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        ELSE 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      END AS component_classification,
      CASE
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'resolution_mode', prepared_rows.line_json->>'saved_resolution_mode', '')) = 'SUGGESTED_EQUIVALENT_BASIS' THEN 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'resolution_mode', prepared_rows.line_json->>'saved_resolution_mode', '')) = 'MANUAL_REPLACEMENT_RATE' THEN 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
        WHEN UPPER(COALESCE(prepared_rows.line_json->>'resolution_mode', prepared_rows.line_json->>'saved_resolution_mode', '')) = 'MANUAL_AMOUNT' THEN 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
        ELSE NULL::public.pay_finance_component_resolution_mode_enum
      END AS resolution_mode,
      CASE
        WHEN ROUND(COALESCE(prepared_rows.allocated_amount, 0), 2) > 0
         AND UPPER(BTRIM(COALESCE(prepared_rows.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
         AND UPPER(COALESCE(prepared_rows.line_json->>'line_type', prepared_rows.line_json->>'item_type', prepared_rows.allocation_type, '')) NOT IN ('DEBT_CREATED', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY', 'LOAN_PAYOUT')
         AND (
           prepared_rows.key_type IN ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'ADJUSTMENT_CODE', 'EXPENSE_CODE')
           OR UPPER(COALESCE(prepared_rows.line_json->>'line_type', prepared_rows.line_json->>'item_type', prepared_rows.allocation_type, '')) IN ('TIMESHEET_PAYMENT', 'SEGMENT_DELTA', 'EXPENSE_DELTA', 'MILEAGE_DELTA', 'ADJUSTMENT_DELTA')
         ) THEN ROUND(COALESCE(
          (
            SELECT ABS((bucket_resolution.bucket_json->>'source_pay_ex_vat')::numeric)
            FROM jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(prepared_rows.line_json#>'{correction_chain_component,resolution_rows}') = 'array'
                  THEN prepared_rows.line_json#>'{correction_chain_component,resolution_rows}'
                ELSE '[]'::jsonb
              END
            ) AS canonical_resolution(resolution_json)
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(canonical_resolution.resolution_json#>'{payload_json,bucket_resolutions}') = 'array'
                  THEN canonical_resolution.resolution_json#>'{payload_json,bucket_resolutions}'
                ELSE '[]'::jsonb
              END
            ) AS bucket_resolution(bucket_json)
            WHERE UPPER(BTRIM(COALESCE(bucket_resolution.bucket_json->>'component_key_type', ''))) = prepared_rows.key_type
              AND BTRIM(COALESCE(bucket_resolution.bucket_json->>'component_key_value', '')) = prepared_rows.key_value
              AND COALESCE(bucket_resolution.bucket_json->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND ROUND(ABS((bucket_resolution.bucket_json->>'source_pay_ex_vat')::numeric), 2) > 0
            ORDER BY canonical_resolution.resolution_json->>'resolution_id',
                     bucket_resolution.bucket_json->>'component_key_type',
                     bucket_resolution.bucket_json->>'component_key_value'
            LIMIT 1
          ),
          CASE WHEN COALESCE(prepared_rows.line_json->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'source_reservation_amount_ex_vat')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'source_reservation_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'source_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'source_amount_ex_vat')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'source_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'source_entitlement_amount_ex_vat')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'source_entitlement_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'frozen_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'frozen_source_amount')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'frozen_source_amount')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'pay_outstanding_clamped_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'pay_outstanding_clamped_amount_ex_vat')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'pay_outstanding_clamped_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'pay_outstanding_available_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json->>'pay_outstanding_available_ex_vat')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json->>'pay_outstanding_available_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{source_basis_json,source_reservation_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{source_basis_json,source_reservation_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{source_basis_json,source_reservation_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{source_basis_json,source_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{source_basis_json,source_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{source_basis_json,source_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{source_basis_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{source_basis_json,source_pay_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{source_basis_json,source_pay_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{frozen_source_basis_json,source_reservation_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{frozen_source_basis_json,source_reservation_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{frozen_source_basis_json,source_reservation_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{frozen_source_basis_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{frozen_source_basis_json,source_pay_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{frozen_source_basis_json,source_pay_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_reservation_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_reservation_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_reservation_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_pay_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_pay_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_basis_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_basis_json,source_pay_ex_vat}')::numeric), 2) > 0 THEN ABS((prepared_rows.line_json#>>'{frozen_component_snapshot_json,source_basis_json,source_pay_ex_vat}')::numeric) ELSE NULL::numeric END,
          ABS(COALESCE(prepared_rows.allocated_amount, 0))
        ), 2)::numeric(12,2)
        ELSE ROUND(COALESCE(
          CASE WHEN COALESCE(prepared_rows.line_json->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((prepared_rows.line_json->>'source_reservation_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(prepared_rows.line_json->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((prepared_rows.line_json->>'source_entitlement_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          ABS(COALESCE(prepared_rows.allocated_amount, 0))
        ), 2)::numeric(12,2)
      END AS frozen_source_amount
    FROM prepared_rows
  ), normalised_rows AS (
    SELECT
      normalised_source_rows.*,
      payee_resolution.resolved_umbrella_id,
      COALESCE(umbrella_row.vat_chargeable, false) AS umbrella_vat_chargeable,
      payout_route.routing_kind,
      payout_route.payee_entity_kind,
      payout_route.payee_entity_id,
      payout_route.beneficiary_name,
      payout_route.destination_label,
      payout_route.sort_code,
      payout_route.account_number,
      payout_route.bank_details_hash,
      payout_route.week_ending_bucket,
      payout_route.payout_instruction_error_code,
      jsonb_strip_nulls(jsonb_build_object(
        'routing_kind', payout_route.routing_kind,
        'payee_entity_kind', payout_route.payee_entity_kind,
        'payee_entity_id', CASE WHEN payout_route.payee_entity_id IS NULL THEN NULL ELSE payout_route.payee_entity_id::text END,
        'umbrella_id', CASE WHEN payout_route.payee_entity_kind = 'UMBRELLA' AND payee_resolution.resolved_umbrella_id IS NOT NULL THEN payee_resolution.resolved_umbrella_id::text ELSE NULL END,
        'beneficiary_name', payout_route.beneficiary_name,
        'payee_name', payout_route.beneficiary_name,
        'sort_code', payout_route.sort_code,
        'account_number', payout_route.account_number,
        'bank_details_hash', payout_route.bank_details_hash,
        'destination_label', payout_route.destination_label,
        'week_ending_bucket', CASE WHEN payout_route.week_ending_bucket IS NULL THEN NULL ELSE payout_route.week_ending_bucket::text END
      )) AS payout_instruction_snapshot_json,
      ROUND(COALESCE((vat_calculation.vat_json->>'vat')::numeric, 0), 2)::numeric(12,2) AS amount_vat,
      ROUND(COALESCE((vat_calculation.vat_json->>'inc')::numeric, normalised_source_rows.amount_ex_vat, 0), 2)::numeric(12,2) AS amount_inc_vat
    FROM normalised_source_rows
    JOIN public.candidates AS candidate_row
      ON candidate_row.id = normalised_source_rows.candidate_id
    LEFT JOIN public.banking_pay_operation_candidate_scope AS scope_row
      ON scope_row.id = normalised_source_rows.candidate_scope_id
     AND scope_row.operation_id = p_operation_id
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN UPPER(BTRIM(COALESCE(normalised_source_rows.pay_channel, ''))) = 'UMBRELLA' THEN
            COALESCE(
              CASE
                WHEN NULLIF(BTRIM(COALESCE(scope_row.effective_non_paye_payee_json->>'umbrella_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN NULLIF(BTRIM(COALESCE(scope_row.effective_non_paye_payee_json->>'umbrella_id', '')), '')::uuid
                ELSE NULL::uuid
              END,
              candidate_row.umbrella_id
            )
          ELSE NULL::uuid
        END AS resolved_umbrella_id
    ) AS payee_resolution
    LEFT JOIN public.umbrellas AS umbrella_row
      ON umbrella_row.id = payee_resolution.resolved_umbrella_id
    CROSS JOIN LATERAL (
      SELECT
        UPPER(BTRIM(COALESCE(normalised_source_rows.pay_channel, ''))) AS channel_upper,
        NULLIF(BTRIM(COALESCE(umbrella_row.name, '')), '') AS umbrella_name,
        NULLIF(BTRIM(COALESCE(umbrella_row.sort_code, '')), '') AS umbrella_sort_code,
        NULLIF(BTRIM(COALESCE(umbrella_row.account_number, '')), '') AS umbrella_account_number,
        NULLIF(BTRIM(COALESCE(umbrella_row.bank_details_hash, '')), '') AS umbrella_bank_details_hash,
        COALESCE(
          NULLIF(BTRIM(candidate_row.account_holder), ''),
          NULLIF(BTRIM(candidate_row.display_name), ''),
          NULLIF(BTRIM(CONCAT_WS(' ', NULLIF(BTRIM(candidate_row.first_name), ''), NULLIF(BTRIM(candidate_row.last_name), ''))), '')
        ) AS candidate_payee_name,
        NULLIF(BTRIM(COALESCE(candidate_row.sort_code, '')), '') AS candidate_sort_code,
        NULLIF(BTRIM(COALESCE(candidate_row.account_number, '')), '') AS candidate_account_number,
        NULLIF(BTRIM(COALESCE(candidate_row.bank_details_hash, '')), '') AS candidate_bank_details_hash,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(
            normalised_source_rows.line_json->>'week_ending_bucket',
            normalised_source_rows.line_json->>'week_ending_date',
            normalised_source_rows.line_json#>>'{timesheet,week_ending_date}',
            normalised_source_rows.allocation_basis_json->>'week_ending_bucket',
            normalised_source_rows.allocation_basis_json->>'week_ending_date',
            normalised_source_rows.allocation_basis_json#>>'{timesheet,week_ending_date}',
            ''
          )), '') ~ '^\d{4}-\d{2}-\d{2}$'
            THEN NULLIF(BTRIM(COALESCE(
              normalised_source_rows.line_json->>'week_ending_bucket',
              normalised_source_rows.line_json->>'week_ending_date',
              normalised_source_rows.line_json#>>'{timesheet,week_ending_date}',
              normalised_source_rows.allocation_basis_json->>'week_ending_bucket',
              normalised_source_rows.allocation_basis_json->>'week_ending_date',
              normalised_source_rows.allocation_basis_json#>>'{timesheet,week_ending_date}',
              ''
            )), '')::date
          ELSE NULL::date
        END AS resolved_week_ending_bucket
    ) AS payout_source
    CROSS JOIN LATERAL (
      SELECT
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN 'UMBRELLA_COMPANY' ELSE 'NORMAL_PAY_ROUTE' END AS routing_kind,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN 'UMBRELLA' ELSE 'CANDIDATE' END AS payee_entity_kind,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payee_resolution.resolved_umbrella_id ELSE candidate_row.id END AS payee_entity_id,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payout_source.umbrella_name ELSE payout_source.candidate_payee_name END AS beneficiary_name,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payout_source.umbrella_name ELSE payout_source.candidate_payee_name END AS destination_label,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payout_source.umbrella_sort_code ELSE payout_source.candidate_sort_code END AS sort_code,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payout_source.umbrella_account_number ELSE payout_source.candidate_account_number END AS account_number,
        CASE WHEN payout_source.channel_upper = 'UMBRELLA' THEN payout_source.umbrella_bank_details_hash ELSE payout_source.candidate_bank_details_hash END AS bank_details_hash,
        payout_source.resolved_week_ending_bucket AS week_ending_bucket,
        CASE
          WHEN payout_source.channel_upper = 'UMBRELLA' AND payee_resolution.resolved_umbrella_id IS NULL THEN 'PAYOUT_INSTRUCTION_UMBRELLA_REQUIRED'
          WHEN payout_source.channel_upper = 'UMBRELLA' AND umbrella_row.id IS NULL THEN 'PAYOUT_INSTRUCTION_UMBRELLA_NOT_FOUND'
          WHEN payout_source.channel_upper = 'UMBRELLA' AND COALESCE(umbrella_row.enabled, false) IS NOT TRUE THEN 'PAYOUT_INSTRUCTION_UMBRELLA_DISABLED'
          WHEN payout_source.channel_upper = 'UMBRELLA' AND (
            payout_source.umbrella_name IS NULL
            OR length(regexp_replace(COALESCE(payout_source.umbrella_sort_code, ''), '[^0-9]', '', 'g')) <> 6
            OR NULLIF(regexp_replace(COALESCE(payout_source.umbrella_account_number, ''), '[^0-9]', '', 'g'), '') IS NULL
            OR payout_source.umbrella_bank_details_hash IS NULL
          ) THEN 'PAYOUT_INSTRUCTION_UMBRELLA_BANK_DETAILS_MISSING'
          WHEN payout_source.channel_upper = 'PAYE' AND (
            payout_source.candidate_payee_name IS NULL
            OR length(regexp_replace(COALESCE(payout_source.candidate_sort_code, ''), '[^0-9]', '', 'g')) <> 6
            OR NULLIF(regexp_replace(COALESCE(payout_source.candidate_account_number, ''), '[^0-9]', '', 'g'), '') IS NULL
            OR payout_source.candidate_bank_details_hash IS NULL
          ) THEN 'PAYOUT_INSTRUCTION_PAYE_BANK_DETAILS_MISSING'
          WHEN payout_source.channel_upper NOT IN ('PAYE', 'UMBRELLA') THEN 'PAYOUT_INSTRUCTION_PAY_CHANNEL_UNSUPPORTED'
          ELSE NULL::text
        END AS payout_instruction_error_code
    ) AS payout_route
    CROSS JOIN LATERAL (
      SELECT public._pay_umbrella_vat_calc(
        normalised_source_rows.amount_ex_vat,
        v_vat_rate_pct,
        payout_source.channel_upper = 'UMBRELLA'
          AND COALESCE(umbrella_row.vat_chargeable, false)
      ) AS vat_json
    ) AS vat_calculation
  )
  SELECT normalised_rows.*
  FROM normalised_rows;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_batch_item_normalised_rows AS validation_rows
    WHERE validation_rows.payout_instruction_error_code IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'PAYOUT_INSTRUCTION_FREEZE_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = (
              SELECT jsonb_build_object(
                'code', 'PAYOUT_INSTRUCTION_FREEZE_FAILED',
                'message', COALESCE(
                  MIN(failure_rows.failure_message) FILTER (WHERE failure_rows.failure_message IS NOT NULL),
                  'Draft payout instructions could not be frozen from the resolved payee bank details.'
                ),
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'first_failure_code', MIN(failure_rows.payout_instruction_error_code) FILTER (WHERE failure_rows.payout_instruction_error_code IS NOT NULL),
                'first_failure_message', MIN(failure_rows.failure_message) FILTER (WHERE failure_rows.failure_message IS NOT NULL),
                'failures', COALESCE(jsonb_agg(jsonb_build_object(
                  'allocation_row_id', failure_rows.allocation_row_id::text,
                  'candidate_id', failure_rows.candidate_id::text,
                  'pay_channel', failure_rows.pay_channel,
                  'umbrella_id', CASE WHEN failure_rows.resolved_umbrella_id IS NULL THEN NULL ELSE failure_rows.resolved_umbrella_id::text END,
                  'code', failure_rows.payout_instruction_error_code,
                  'message', failure_rows.failure_message
                ) ORDER BY failure_rows.allocation_row_id), '[]'::jsonb)
              )::text
              FROM (
                SELECT validation_rows.allocation_row_id,
                       validation_rows.candidate_id,
                       validation_rows.pay_channel,
                       validation_rows.resolved_umbrella_id,
                       validation_rows.payout_instruction_error_code,
                       CASE validation_rows.payout_instruction_error_code
                         WHEN 'PAYOUT_INSTRUCTION_UMBRELLA_REQUIRED' THEN 'Umbrella payment cannot be drafted because the candidate has no resolved umbrella payee.'
                         WHEN 'PAYOUT_INSTRUCTION_UMBRELLA_NOT_FOUND' THEN 'Umbrella payment cannot be drafted because the resolved umbrella payee was not found.'
                         WHEN 'PAYOUT_INSTRUCTION_UMBRELLA_DISABLED' THEN 'Umbrella payment cannot be drafted because the resolved umbrella is disabled.'
                         WHEN 'PAYOUT_INSTRUCTION_UMBRELLA_BANK_DETAILS_MISSING' THEN 'Umbrella payment cannot be drafted because the enabled umbrella is missing mandatory bank details.'
                         WHEN 'PAYOUT_INSTRUCTION_PAYE_BANK_DETAILS_MISSING' THEN 'PAYE payment cannot be drafted because the candidate is missing mandatory bank details.'
                         WHEN 'PAYOUT_INSTRUCTION_PAY_CHANNEL_UNSUPPORTED' THEN 'Payment cannot be drafted because the pay channel is unsupported for bank payout freezing.'
                         ELSE 'Draft payout instructions could not be frozen from the resolved payee bank details.'
                       END AS failure_message
                FROM pg_temp.tmp_pay_batch_item_normalised_rows AS validation_rows
                WHERE validation_rows.payout_instruction_error_code IS NOT NULL
                ORDER BY validation_rows.allocation_row_id
                LIMIT 25
              ) AS failure_rows
            );
  END IF;

  -- This child writer is independently callable. Lock and revalidate the exact
  -- allocation page, then establish the sticky retention marker transactionally
  -- before any durable pay_batch_items row can be created.
  SELECT COUNT(*)::integer
  INTO v_locked_allocation_row_count
  FROM (
    SELECT allocation_current.id
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_current
    JOIN pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
      ON normalised_rows.allocation_row_id = allocation_current.id
    ORDER BY allocation_current.id
    FOR UPDATE OF allocation_current
  ) AS locked_allocations;

  IF v_locked_allocation_row_count IS DISTINCT FROM (
    SELECT COUNT(*)::integer
    FROM pg_temp.tmp_pay_batch_item_normalised_rows
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_ALLOCATION_TARGET_SET_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_ALLOCATION_TARGET_SET_CHANGED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'The exact draft allocation target set changed before durable item creation. Refresh Banking Pay and try again.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
    JOIN pg_temp.tmp_pay_batch_item_allocation_page AS allocation_snapshot
      ON allocation_snapshot.id = normalised_rows.allocation_row_id
    JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation_current
      ON allocation_current.id = normalised_rows.allocation_row_id
    WHERE allocation_current.operation_id IS DISTINCT FROM allocation_snapshot.operation_id
       OR allocation_current.candidate_scope_id IS DISTINCT FROM allocation_snapshot.candidate_scope_id
       OR allocation_current.pay_batch_id IS DISTINCT FROM allocation_snapshot.pay_batch_id
       OR allocation_current.candidate_id IS DISTINCT FROM allocation_snapshot.candidate_id
       OR allocation_current.pay_channel IS DISTINCT FROM allocation_snapshot.pay_channel
       OR allocation_current.finance_case_id IS DISTINCT FROM allocation_snapshot.finance_case_id
       OR allocation_current.finance_component_id IS DISTINCT FROM allocation_snapshot.finance_component_id
       OR allocation_current.allocation_type IS DISTINCT FROM allocation_snapshot.allocation_type
       OR allocation_current.source_ref IS DISTINCT FROM allocation_snapshot.source_ref
       OR allocation_current.operation_source_key IS DISTINCT FROM allocation_snapshot.operation_source_key
       OR allocation_current.allocated_amount IS DISTINCT FROM allocation_snapshot.allocated_amount
       OR allocation_current.allocation_basis_json IS DISTINCT FROM allocation_snapshot.source_allocation_basis_json
       OR allocation_current.status IS DISTINCT FROM allocation_snapshot.status
       OR UPPER(BTRIM(COALESCE(allocation_current.status, ''))) NOT IN ('PENDING', 'ITEM_PENDING')
       OR allocation_current.operation_id IS DISTINCT FROM p_operation_id
       OR allocation_current.candidate_scope_id IS DISTINCT FROM normalised_rows.candidate_scope_id
       OR allocation_current.candidate_id IS DISTINCT FROM normalised_rows.candidate_id
       OR allocation_current.operation_source_key IS DISTINCT FROM normalised_rows.operation_source_key
       OR allocation_snapshot.canonical_timesheet_id IS DISTINCT FROM normalised_rows.timesheet_id
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_ALLOCATION_IDENTITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_ALLOCATION_IDENTITY_CHANGED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'A selected draft allocation changed identity or state before durable item creation. Refresh Banking Pay and try again.'
            )::text;
  END IF;

  -- Every exact ordinary allocation candidate/scope must have been represented
  -- in the authoritative snooze guard before retention or durable item creation.
  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp._bpay_draft_snooze_guard_scope AS guard_scope
      WHERE guard_scope.candidate_scope_id = normalised_rows.candidate_scope_id
        AND guard_scope.candidate_id = normalised_rows.candidate_id
    )
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_SNOOZE_GUARD_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_SNOOZE_GUARD_SCOPE_MISMATCH',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'guarded_selected_line_count', v_snooze_guard_selected_line_count,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'One or more final allocation candidates were not covered by the live snooze authority. Refresh Banking Pay before creating items.'
            )::text;
  END IF;

  SELECT COALESCE(
           ARRAY_AGG(DISTINCT normalised_rows.timesheet_id ORDER BY normalised_rows.timesheet_id),
           ARRAY[]::uuid[]
         )
  INTO v_retention_timesheet_ids
  FROM pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
  WHERE normalised_rows.timesheet_id IS NOT NULL;

  IF COALESCE(ARRAY_LENGTH(v_retention_timesheet_ids, 1), 0) > 0 THEN
    -- Re-resolve after the allocation-row lock in case that lock acquisition waited.
    IF EXISTS (
      WITH requested_timesheets AS (
        SELECT requested.timesheet_id
        FROM unnest(v_retention_timesheet_ids) AS requested(timesheet_id)
      ), current_rotation AS (
        SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
          rotation_scope.requested_timesheet_id,
          rotation_scope.canonical_timesheet_id,
          rotation_scope.family_timesheet_id,
          rotation_scope.family_is_current,
          rotation_scope.requested_is_canonical
        FROM public._pay_timesheet_rotation_scope(v_retention_timesheet_ids) AS rotation_scope
        ORDER BY
          rotation_scope.requested_timesheet_id,
          rotation_scope.family_is_current DESC NULLS LAST,
          rotation_scope.family_version DESC NULLS LAST,
          rotation_scope.family_timesheet_id
      )
      SELECT 1
      FROM requested_timesheets AS requested
      LEFT JOIN current_rotation AS rotation_scope
        ON rotation_scope.requested_timesheet_id = requested.timesheet_id
      WHERE rotation_scope.requested_timesheet_id IS NULL
         OR rotation_scope.canonical_timesheet_id IS DISTINCT FROM requested.timesheet_id
         OR COALESCE(rotation_scope.requested_is_canonical, false) IS NOT TRUE
         OR rotation_scope.family_timesheet_id IS NULL
         OR rotation_scope.family_is_current IS NULL
    ) THEN
      RAISE EXCEPTION 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'message', 'One or more allocation rows no longer resolve to the same current canonical timesheet. Refresh draft scope before creating batch items.'
              )::text;
    END IF;

    -- The helper deterministically locks every exact persisted timesheet identity
    -- and inserts the sticky marker in this same transaction.
    v_retention_mark_json := public.timesheet_financial_retention_mark_v1(v_retention_timesheet_ids);

    -- The marker helper may have waited on a timesheet lock. Revalidate current
    -- rotation after that wait; any failure rolls back both marker and item work.
    IF EXISTS (
      WITH requested_timesheets AS (
        SELECT requested.timesheet_id
        FROM unnest(v_retention_timesheet_ids) AS requested(timesheet_id)
      ), current_rotation AS (
        SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
          rotation_scope.requested_timesheet_id,
          rotation_scope.canonical_timesheet_id,
          rotation_scope.family_timesheet_id,
          rotation_scope.family_is_current,
          rotation_scope.requested_is_canonical
        FROM public._pay_timesheet_rotation_scope(v_retention_timesheet_ids) AS rotation_scope
        ORDER BY
          rotation_scope.requested_timesheet_id,
          rotation_scope.family_is_current DESC NULLS LAST,
          rotation_scope.family_version DESC NULLS LAST,
          rotation_scope.family_timesheet_id
      )
      SELECT 1
      FROM requested_timesheets AS requested
      LEFT JOIN current_rotation AS rotation_scope
        ON rotation_scope.requested_timesheet_id = requested.timesheet_id
      WHERE rotation_scope.requested_timesheet_id IS NULL
         OR rotation_scope.canonical_timesheet_id IS DISTINCT FROM requested.timesheet_id
         OR COALESCE(rotation_scope.requested_is_canonical, false) IS NOT TRUE
         OR rotation_scope.family_timesheet_id IS NULL
         OR rotation_scope.family_is_current IS NULL
    ) THEN
      RAISE EXCEPTION 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_ITEM_ROTATED_ALLOCATION_STALE',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'message', 'One or more allocation rows changed current canonical timesheet while retention was being established. Refresh draft scope before creating batch items.'
              )::text;
    END IF;
  END IF;

  -- Revalidate operation, session, batch and candidate-scope authority after
  -- allocation and timesheet/retention waits. These rows were locked earlier;
  -- this check also protects against any change made by this transaction.
  IF NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND UPPER(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'DRAFT_CREATE'
      AND UPPER(BTRIM(COALESCE(operation_row.status, ''))) = 'RUNNING'
      AND UPPER(BTRIM(COALESCE(operation_row.phase, ''))) = 'INSERT_ITEMS'
      AND operation_row.actor_user_id = p_actor_user_id
      AND operation_row.workbench_session_id = v_workbench_session_id
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_OPERATION_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_OPERATION_AUTHORITY_CHANGED',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'message', 'The active DRAFT_CREATE operation authority changed before durable item creation.'
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_workbench_session_id
      AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL
      AND session_row.replacement_session_id IS NULL
      AND session_row.version IS NOT DISTINCT FROM v_session_version
      AND session_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_source_snapshot_run_id
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_WORKBENCH_SESSION_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_WORKBENCH_SESSION_AUTHORITY_CHANGED',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'The Workbench session authority changed before durable item creation.'
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id
      AND UPPER(BTRIM(COALESCE(batch_row.status, ''))) = 'DRAFT'
      AND UPPER(BTRIM(COALESCE(batch_row.execution_commit_state, ''))) = 'NOT_SUBMITTED'
      AND batch_row.source_workbench_session_id = v_workbench_session_id
      AND batch_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_source_snapshot_run_id
      AND batch_row.source_session_version IS NOT DISTINCT FROM v_session_version
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_PAY_BATCH_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_PAY_BATCH_AUTHORITY_CHANGED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'The draft pay batch authority changed before durable item creation.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_locked_candidate_scope_count
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.id IN (
    SELECT supplied_scope.candidate_scope_id_text::uuid
    FROM jsonb_array_elements_text(v_candidate_scope_ids)
      AS supplied_scope(candidate_scope_id_text)
  )
    AND scope_row.operation_id = p_operation_id
    AND scope_row.workbench_session_id = v_workbench_session_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('SCOPED', 'ALLOCATED', 'DRAFTED')
    AND scope_row.source_session_version IS NOT DISTINCT FROM v_session_version
    AND scope_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_source_snapshot_run_id;

  IF v_locked_candidate_scope_count IS DISTINCT FROM v_scope_id_count THEN
    RAISE EXCEPTION 'DRAFT_ITEM_CANDIDATE_SCOPE_AUTHORITY_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_CANDIDATE_SCOPE_AUTHORITY_CHANGED',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'candidate_scope_ids', v_candidate_scope_ids,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'Candidate-scope authority changed before durable item creation.'
            )::text;
  END IF;

  -- Option B: repeat the authoritative snooze check after retention marking and
  -- all post-wait identity validation, immediately before the first item insert.
  -- Any conflict rolls the retention marker and item work back together.
  v_snooze_guard_json := public.pay_workbench_operation_active_snoozes_v1(
    p_operation_id,
    v_workbench_session_id,
    v_candidate_scope_ids
  );

  IF LOWER(BTRIM(COALESCE(v_snooze_guard_json->>'ok', 'false'))) NOT IN ('true', 't', '1') THEN
    RAISE EXCEPTION 'DRAFT_ITEM_FINAL_SNOOZE_GUARD_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_FINAL_SNOOZE_GUARD_INVALID',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'message', 'The final live snooze authority returned an invalid result.'
            )::text;
  END IF;

  v_snooze_guard_selected_line_count := CASE
    WHEN COALESCE(v_snooze_guard_json->>'selected_line_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_snooze_guard_json->>'selected_line_count')::integer
    ELSE 0
  END;
  v_active_snooze_count := CASE
    WHEN COALESCE(v_snooze_guard_json->>'active_snooze_count', '') ~ '^[0-9]{1,9}$'
      THEN (v_snooze_guard_json->>'active_snooze_count')::integer
    ELSE 0
  END;

  IF v_active_snooze_count > 0 THEN
    RAISE EXCEPTION 'ACTIVE_SNOOZE_PREVENTS_DRAFT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_strip_nulls(
              jsonb_build_object(
                'code', 'ACTIVE_SNOOZE_PREVENTS_DRAFT',
                'message', 'One or more selected payments are currently snoozed. Banking Pay has been refreshed so you can review the updated selection.',
                'operation_id', p_operation_id::text,
                'workbench_session_id', v_workbench_session_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'refresh_required', true,
                'next_action', 'REFRESH_WORKBENCH'
              )
              || COALESCE(v_snooze_guard_json, '{}'::jsonb)
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp._bpay_draft_snooze_guard_scope AS guard_scope
      WHERE guard_scope.candidate_scope_id = normalised_rows.candidate_scope_id
        AND guard_scope.candidate_id = normalised_rows.candidate_id
    )
  ) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_FINAL_SNOOZE_GUARD_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_FINAL_SNOOZE_GUARD_SCOPE_MISMATCH',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_workbench_session_id::text,
              'pay_batch_id', p_pay_batch_id::text,
              'guarded_selected_line_count', v_snooze_guard_selected_line_count,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH',
              'message', 'One or more final allocation candidates were not covered by the final live snooze authority.'
            )::text;
  END IF;

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'INSERT_ITEMS','REGISTER',
    jsonb_build_array(
      jsonb_build_object('relation_name','pay_batch_items','operation','INSERT'),
      jsonb_build_object('relation_name','pay_batch_items','operation','UPDATE')
    ),jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  WITH inserted_items AS (
    INSERT INTO public.pay_batch_items(
      pay_batch_candidate_id,
      item_type,
      timesheet_id,
      segment_key,
      source_ref,
      description,
      amount_ex_vat,
      amount_vat,
      amount_inc_vat,
      pay_channel,
      umbrella_id,
      is_mismatch,
      finance_case_id,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json,
      operation_source_key
    )
    SELECT
      pay_batch_candidate.id,
      normalised_rows.item_type,
      normalised_rows.timesheet_id,
      normalised_rows.segment_key,
      COALESCE(NULLIF(BTRIM(normalised_rows.source_ref), ''), normalised_rows.allocation_basis_json->>'row_key', normalised_rows.operation_source_key),
      COALESCE(NULLIF(BTRIM(normalised_rows.line_json->>'description'), ''), NULLIF(BTRIM(normalised_rows.line_json->>'label'), ''), normalised_rows.item_type),
      normalised_rows.amount_ex_vat,
      normalised_rows.amount_vat,
      normalised_rows.amount_inc_vat,
      normalised_rows.pay_channel,
      normalised_rows.resolved_umbrella_id,
      false,
      normalised_rows.finance_case_id,
      normalised_rows.finance_component_id,
      jsonb_strip_nulls(
        COALESCE(normalised_rows.line_json->'frozen_component_snapshot_json', normalised_rows.line_json->'component_snapshot_json', '{}'::jsonb)
        || jsonb_build_object(
          'source', 'banking_pay_operation_candidate_allocation_rows',
          'allocation_row_id', normalised_rows.allocation_row_id::text,
          'operation_source_key', normalised_rows.operation_source_key,
          'timesheet_id', CASE WHEN normalised_rows.timesheet_id IS NULL THEN NULL ELSE normalised_rows.timesheet_id::text END,
          'component_key_type', normalised_rows.key_type,
          'component_key_value', normalised_rows.key_value,
          'source_family_key', NULLIF(BTRIM(COALESCE(normalised_rows.line_json->>'source_family_key', '')), ''),
          'correction_chain_residual', CASE
            WHEN NULLIF(BTRIM(COALESCE(normalised_rows.line_json->>'source_family_key', '')), '') LIKE 'correction-chain:%'
             AND jsonb_typeof(normalised_rows.line_json->'correction_chain_residual') = 'object'
              THEN normalised_rows.line_json->'correction_chain_residual'
            ELSE NULL
          END
        )
        || CASE
          WHEN normalised_rows.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
           AND ROUND(COALESCE(normalised_rows.amount_ex_vat, 0), 2) > 0
           AND ROUND(ABS(COALESCE(normalised_rows.frozen_source_amount, 0)), 2) > 0 THEN jsonb_build_object(
            'source_pay_ex_vat', normalised_rows.frozen_source_amount,
            'source_amount_ex_vat', normalised_rows.frozen_source_amount,
            'source_entitlement_amount_ex_vat', normalised_rows.frozen_source_amount,
            'source_reservation_amount_ex_vat', normalised_rows.frozen_source_amount,
            'frozen_source_amount', normalised_rows.frozen_source_amount
          )
          ELSE '{}'::jsonb
        END
        || CASE
          WHEN normalised_rows.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
           AND ROUND(COALESCE(normalised_rows.amount_ex_vat, 0), 2) > 0
           AND ROUND(ABS(COALESCE(normalised_rows.frozen_source_amount, 0)), 2) > 0 THEN jsonb_build_object(
            'source_basis_json',
            COALESCE(
              normalised_rows.line_json#>'{frozen_component_snapshot_json,source_basis_json}',
              normalised_rows.line_json#>'{component_snapshot_json,source_basis_json}',
              normalised_rows.line_json->'source_basis_json',
              '{}'::jsonb
            )
            || jsonb_build_object(
              'source_pay_ex_vat', normalised_rows.frozen_source_amount,
              'source_amount_ex_vat', normalised_rows.frozen_source_amount,
              'source_entitlement_amount_ex_vat', normalised_rows.frozen_source_amount,
              'source_reservation_amount_ex_vat', normalised_rows.frozen_source_amount
            )
          )
          ELSE '{}'::jsonb
        END
      ),
      normalised_rows.key_type,
      normalised_rows.key_value,
      normalised_rows.component_classification,
      jsonb_strip_nulls(
        COALESCE(normalised_rows.line_json->'source_basis_json', normalised_rows.line_json#>'{economic_key}', '{}'::jsonb)
        || jsonb_build_object(
          'source', 'banking_pay_workbench_preview_rows',
          'allocation_row_id', normalised_rows.allocation_row_id::text,
          'timesheet_id', CASE WHEN normalised_rows.timesheet_id IS NULL THEN NULL ELSE normalised_rows.timesheet_id::text END,
          'key_type', normalised_rows.key_type,
          'key_value', normalised_rows.key_value,
          'source_family_key', NULLIF(BTRIM(COALESCE(normalised_rows.line_json->>'source_family_key', '')), ''),
          'correction_chain_residual', CASE
            WHEN NULLIF(BTRIM(COALESCE(normalised_rows.line_json->>'source_family_key', '')), '') LIKE 'correction-chain:%'
             AND jsonb_typeof(normalised_rows.line_json->'correction_chain_residual') = 'object'
              THEN normalised_rows.line_json->'correction_chain_residual'
            ELSE NULL
          END
        )
        || CASE
          WHEN normalised_rows.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
           AND ROUND(COALESCE(normalised_rows.amount_ex_vat, 0), 2) > 0
           AND ROUND(ABS(COALESCE(normalised_rows.frozen_source_amount, 0)), 2) > 0 THEN jsonb_build_object(
            'source_pay_ex_vat', normalised_rows.frozen_source_amount,
            'source_amount_ex_vat', normalised_rows.frozen_source_amount,
            'source_entitlement_amount_ex_vat', normalised_rows.frozen_source_amount,
            'source_reservation_amount_ex_vat', normalised_rows.frozen_source_amount
          )
          ELSE '{}'::jsonb
        END
      ),
      COALESCE(NULLIF(UPPER(BTRIM(normalised_rows.line_json->>'source_pay_method')), ''), normalised_rows.pay_channel),
      normalised_rows.pay_channel,
      normalised_rows.resolution_mode,
      CASE WHEN jsonb_typeof(normalised_rows.line_json->'resolution_payload_json') = 'object' THEN normalised_rows.line_json->'resolution_payload_json' ELSE normalised_rows.line_json END,
      jsonb_strip_nulls(
        COALESCE(normalised_rows.line_json->'resolution_result_json', '{}'::jsonb)
        || jsonb_build_object(
          'source_amount_ex_vat', normalised_rows.frozen_source_amount,
          'target_amount_ex_vat', normalised_rows.amount_ex_vat,
          'target_amount_vat', normalised_rows.amount_vat,
          'target_amount_inc_vat', normalised_rows.amount_inc_vat
        )
      ),
      normalised_rows.frozen_source_amount,
      normalised_rows.amount_ex_vat,
      normalised_rows.amount_vat,
      normalised_rows.amount_inc_vat,
      normalised_rows.payout_instruction_snapshot_json,
      normalised_rows.operation_source_key
    FROM pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.pay_batch_id = p_pay_batch_id
     AND pay_batch_candidate.candidate_id = normalised_rows.candidate_id
    ON CONFLICT (pay_batch_candidate_id, operation_source_key) WHERE operation_source_key IS NOT NULL DO NOTHING
    RETURNING public.pay_batch_items.id, public.pay_batch_items.operation_source_key
  )
  SELECT COUNT(*)::integer
  INTO v_inserted_count
  FROM inserted_items;

  WITH matched_items AS (
    SELECT allocation_row.id AS allocation_row_id,
           pay_batch_item.id AS pay_batch_item_id
    FROM pg_temp.tmp_pay_batch_item_allocation_page AS allocation_row
    JOIN public.banking_pay_operation_candidate_scope AS scope_row
      ON scope_row.id = allocation_row.candidate_scope_id
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.pay_batch_id = p_pay_batch_id
     AND pay_batch_candidate.candidate_id = allocation_row.candidate_id
    JOIN public.pay_batch_items AS pay_batch_item
      ON pay_batch_item.pay_batch_candidate_id = pay_batch_candidate.id
     AND pay_batch_item.operation_source_key = allocation_row.operation_source_key
     AND COALESCE(pay_batch_item.is_voided, false) = false
     AND UPPER(BTRIM(COALESCE(allocation_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
  ), repaired_item_snapshots AS (
    UPDATE public.pay_batch_items AS item_update
    SET payout_instruction_snapshot_json = normalised_rows.payout_instruction_snapshot_json,
        updated_at = v_now
    FROM matched_items
    JOIN pg_temp.tmp_pay_batch_item_normalised_rows AS normalised_rows
      ON normalised_rows.allocation_row_id = matched_items.allocation_row_id
    WHERE item_update.id = matched_items.pay_batch_item_id
      AND item_update.payout_instruction_snapshot_json IS NULL
    RETURNING item_update.id
  ), updated_allocations AS (
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET status = 'ITEM_CREATED',
        pay_batch_id = p_pay_batch_id,
        pay_batch_item_id = matched_items.pay_batch_item_id,
        updated_at_utc = v_now
    FROM matched_items
    WHERE allocation_update.id = matched_items.allocation_row_id
    RETURNING allocation_update.id
  )
  SELECT COUNT(*)::integer,
         GREATEST(COUNT(*)::integer - COALESCE(v_inserted_count, 0), 0)
  INTO v_linked_allocation_row_count, v_reused_count
  FROM updated_allocations;

  IF COALESCE(v_linked_allocation_row_count, 0) <= 0
     AND COALESCE(v_ordinary_page_allocation_row_count, 0) > 0 THEN
    RAISE EXCEPTION 'DRAFT_ITEM_INSERTION_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_INSERTION_EMPTY',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', p_operation_id::text,
              'candidate_scope_count', v_scope_id_count,
              'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
              'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
              'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
              'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
              'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
              'inserted_item_rows', COALESCE(v_inserted_count, 0),
              'reused_item_rows', COALESCE(v_reused_count, 0),
              'message', 'Draft item insertion produced no linked batch items for row-backed selected allocation rows.'
            )::text;
  END IF;

  IF COALESCE(v_linked_allocation_row_count, 0) <> COALESCE(v_ordinary_page_allocation_row_count, 0) THEN
    RAISE EXCEPTION 'DRAFT_ITEM_LINKAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ITEM_LINKAGE_INCOMPLETE',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', p_operation_id::text,
              'candidate_scope_count', v_scope_id_count,
              'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
              'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
              'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
              'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
              'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
              'inserted_item_rows', COALESCE(v_inserted_count, 0),
              'reused_item_rows', COALESCE(v_reused_count, 0),
              'message', 'One or more row-backed allocation rows were not linked to draft items.'
            )::text;
  END IF;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET pay_batch_id = p_pay_batch_id,
      status = CASE
        WHEN NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_remaining
          WHERE allocation_remaining.candidate_scope_id = scope_update.id
            AND UPPER(BTRIM(COALESCE(allocation_remaining.status, ''))) IN ('PENDING', 'ITEM_PENDING')
        ) THEN 'DRAFTED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND scope_update.id IN (
      SELECT (supplied_scope.scope_value #>> '{}')::uuid
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
    );

  PERFORM private.pay_workbench_draft_expected_effects_v1(
    p_operation_id,'INSERT_ITEMS','ASSERT_COMPLETE','[]'::jsonb,
    jsonb_build_object('pay_batch_id',p_pay_batch_id)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'candidate_scope_count', v_scope_id_count,
    'candidate_scope_ids', COALESCE(v_candidate_scope_ids, '[]'::jsonb),
    'allocation_row_count', COALESCE(v_expected_allocation_row_count, 0),
    'page_allocation_row_count', COALESCE(v_page_allocation_row_count, 0),
    'linked_allocation_rows', COALESCE(v_linked_allocation_row_count, 0),
    'repaired_existing_item_links', COALESCE(v_repaired_existing_item_link_count, 0),
    'inserted_item_rows', COALESCE(v_inserted_count, 0),
    'reused_item_rows', COALESCE(v_reused_count, 0),
    'skipped_item_rows', 0,
    'failed_item_rows', COALESCE(v_failed_count, 0),
    'retention_mark', COALESCE(v_retention_mark_json, '{}'::jsonb),
    'has_more', EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_candidate_allocation_rows AS remaining_row
      WHERE remaining_row.operation_id = p_operation_id
        AND remaining_row.candidate_scope_id IN (
          SELECT (supplied_scope.scope_value #>> '{}')::uuid
          FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
        )
        AND UPPER(BTRIM(COALESCE(remaining_row.status, ''))) IN ('PENDING', 'ITEM_PENDING')
        AND UPPER(BTRIM(COALESCE(remaining_row.allocation_type, ''))) <> 'OVERPAYMENT_RECOVERY'
    )
  );
END;
$function$;

-- pay_batch_mark_blocked_funds(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_mark_blocked_funds(p_pay_batch_id uuid, p_actor_user_id uuid, p_funds_check_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch record;
  v_now timestamptz := now();
  v_funds_check_json jsonb := '{}'::jsonb;
  v_submission_evidence jsonb := '{}'::jsonb;
  v_reservation_status_summary jsonb := '[]'::jsonb;
  v_authoritative_payment_date date := NULL::date;
  v_authoritative_payment_date_source text := NULL::text;
  v_active_item_count integer := 0;
  v_required_gbp_text text := NULL::text;
  v_available_gbp_text text := NULL::text;
  v_funding_account_ref text := NULL::text;
  v_rail_provider text := NULL::text;
  v_rail_env text := NULL::text;
  v_alert_payload jsonb := '{}'::jsonb;
  v_alert_fingerprint text := NULL::text;
  v_notice_result jsonb := '{}'::jsonb;
  v_current_operation_id_text text := NULL::text;
  v_current_operation_id uuid := NULL::uuid;
  v_cancelled_auth_request_ids jsonb := '[]'::jsonb;
  v_auth_requests_cancelled integer := 0;
  v_auth_tokens_voided integer := 0;
  v_transfer_scope_rows_skipped integer := 0;
  v_item_links_cleared integer := 0;
  v_transfer_rows_deleted integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: actor_user_id is required';
  END IF;

  IF p_funds_check_json IS NOT NULL AND COALESCE(jsonb_typeof(p_funds_check_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: funds_check_json must be a JSON object';
  END IF;

  v_funds_check_json := COALESCE(p_funds_check_json, '{}'::jsonb);

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.authoritative_payment_date,
    public.pay_batches.authoritative_payment_date_source,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.funding_account_ref,
    public.pay_batches.pay_date,
    public.pay_batches.bulk_reference,
    public.pay_batches.execution_intent_json
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id
  FOR UPDATE;

  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_batch not found';
  END IF;

  IF upper(btrim(coalesce(v_batch.status, ''))) NOT IN ('DRAFT', 'READY', 'SCHEDULED', 'EXECUTING', 'AUTHORISED_FOR_PAYMENT', 'BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch status must be DRAFT, READY, SCHEDULED, EXECUTING, AUTHORISED_FOR_PAYMENT or BLOCKED_FUNDS (current=%)', v_batch.status;
  END IF;

  IF upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has already crossed execution commit boundary (execution_commit_state=%)', v_batch.execution_commit_state;
  END IF;

  IF nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has execution_commit_ref and cannot be marked blocked funds safely';
  END IF;

  IF v_batch.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has execution_committed_at_utc and cannot be marked blocked funds safely';
  END IF;

  v_current_operation_id_text := NULLIF(BTRIM(COALESCE(v_batch.execution_intent_json ->> 'operation_id', '')), '');

  IF v_current_operation_id_text IS NOT NULL THEN
    IF v_current_operation_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'pay_batch_mark_blocked_funds: execution_intent_json.operation_id is not a valid uuid';
    END IF;

    v_current_operation_id := v_current_operation_id_text::uuid;
  END IF;

  v_submission_evidence := public.pay_batch_submission_evidence(p_pay_batch_id);

  IF COALESCE((v_submission_evidence ->> 'transfer_event_count')::integer, 0) <> 0 THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_bank_transfer_events exist for this batch and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: provider-attempt request or idempotency evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: possible provider-attempt evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: transfer/provider evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false) <> true THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: no-submission evidence check failed and the blocked-funds pre-submission path is unsafe';
  END IF;

  SELECT count(*)::integer
  INTO v_active_item_count
  FROM public.pay_batch_candidates
  JOIN public.pay_batch_items
    ON public.pay_batch_items.pay_batch_candidate_id = public.pay_batch_candidates.id
  WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
    AND COALESCE(public.pay_batch_items.is_voided, false) = false;

  IF COALESCE(v_active_item_count, 0) <= 0 THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: no active frozen batch items exist for this batch';
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_mark_blocked_cancelled_auth_requests (
    auth_request_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_mark_blocked_cancelled_auth_requests;

  WITH cancelled_auth_requests AS (
    UPDATE public.pay_batch_auth_requests AS auth_request_to_cancel
    SET
      state = 'CANCELLED',
      finalised_at_utc = COALESCE(auth_request_to_cancel.finalised_at_utc, v_now),
      finalised_by_user_id = COALESCE(auth_request_to_cancel.finalised_by_user_id, p_actor_user_id),
      execution_intent_json = jsonb_strip_nulls(
        COALESCE(auth_request_to_cancel.execution_intent_json, '{}'::jsonb)
        || jsonb_build_object(
          'cancelled_by_blocked_funds', true,
          'blocked_funds_at_utc', v_now::text,
          'blocked_funds_by_user_id', p_actor_user_id::text,
          'blocked_funds_operation_id', CASE WHEN v_current_operation_id IS NULL THEN NULL ELSE v_current_operation_id::text END
        )
      )
    WHERE auth_request_to_cancel.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(auth_request_to_cancel.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND (
        v_current_operation_id IS NULL
        OR NULLIF(BTRIM(COALESCE(auth_request_to_cancel.execution_intent_json ->> 'operation_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(auth_request_to_cancel.execution_intent_json ->> 'operation_id', '')), '') = v_current_operation_id::text
      )
    RETURNING auth_request_to_cancel.id
  )
  INSERT INTO pg_temp.tmp_mark_blocked_cancelled_auth_requests (auth_request_id)
  SELECT cancelled_auth_requests.id
  FROM cancelled_auth_requests
  ON CONFLICT DO NOTHING;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(cancelled_auth_request.auth_request_id::text) ORDER BY cancelled_auth_request.auth_request_id), '[]'::jsonb)
  INTO v_auth_requests_cancelled,
       v_cancelled_auth_request_ids
  FROM pg_temp.tmp_mark_blocked_cancelled_auth_requests AS cancelled_auth_request;

  WITH voided_tokens AS (
    UPDATE public.pay_batch_auth_tokens AS auth_token_to_void
    SET
      used_at_utc = COALESCE(auth_token_to_void.used_at_utc, v_now),
      expires_at_utc = CASE
        WHEN auth_token_to_void.expires_at_utc IS NULL THEN v_now
        WHEN auth_token_to_void.expires_at_utc > v_now THEN v_now
        ELSE auth_token_to_void.expires_at_utc
      END
    FROM pg_temp.tmp_mark_blocked_cancelled_auth_requests AS cancelled_auth_request
    WHERE auth_token_to_void.auth_request_id = cancelled_auth_request.auth_request_id
      AND (
        auth_token_to_void.used_at_utc IS NULL
        OR auth_token_to_void.expires_at_utc IS NULL
        OR auth_token_to_void.expires_at_utc > v_now
      )
    RETURNING auth_token_to_void.token
  )
  SELECT COUNT(*)::integer
  INTO v_auth_tokens_voided
  FROM voided_tokens;

  v_authoritative_payment_date := v_batch.authoritative_payment_date;
  v_authoritative_payment_date_source := v_batch.authoritative_payment_date_source;

  v_required_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{required_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount}'), '')
  );

  v_available_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{available_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount}'), '')
  );

  v_funding_account_ref := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{account_ref}'), ''),
    NULLIF(BTRIM(v_batch.funding_account_ref), '')
  );

  v_rail_provider := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_provider}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{provider}'), ''),
    NULLIF(BTRIM(v_batch.rail_provider_snapshot), '')
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_env}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{env}'), ''),
    NULLIF(BTRIM(v_batch.rail_env_snapshot), '')
  );

  IF v_current_operation_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_to_skip
    SET
      status = 'SKIPPED',
      pay_bank_transfer_id = NULL,
      updated_at_utc = v_now
    WHERE scope_to_skip.pay_batch_id = p_pay_batch_id
      AND scope_to_skip.operation_id = v_current_operation_id
      AND upper(btrim(coalesce(scope_to_skip.status, ''))) IN ('PENDING', 'PREPARED')
      AND scope_to_skip.pay_bank_transfer_id IS NOT NULL;

    GET DIAGNOSTICS v_transfer_scope_rows_skipped = ROW_COUNT;
  END IF;

  UPDATE public.pay_batch_items AS batch_item_to_unlink
  SET pay_bank_transfer_id = NULL
  FROM public.pay_batch_candidates AS batch_candidate_to_unlink
  WHERE batch_candidate_to_unlink.id = batch_item_to_unlink.pay_batch_candidate_id
    AND batch_candidate_to_unlink.pay_batch_id = p_pay_batch_id
    AND batch_item_to_unlink.pay_bank_transfer_id IS NOT NULL;

  GET DIAGNOSTICS v_item_links_cleared = ROW_COUNT;

  DELETE FROM public.pay_bank_transfers AS transfer_to_delete
  WHERE transfer_to_delete.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_transfer_rows_deleted = ROW_COUNT;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_mark_blocked_rewound_reservations (
    reservation_id uuid NOT NULL,
    finance_case_id uuid NOT NULL,
    finance_component_id uuid NULL,
    previous_status text NOT NULL,
    previous_committed_at_utc timestamptz NULL,
    reserved_amount numeric NULL,
    repayment_week_start date NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_mark_blocked_rewound_reservations;

  INSERT INTO pg_temp.tmp_mark_blocked_rewound_reservations (
    reservation_id,
    finance_case_id,
    finance_component_id,
    previous_status,
    previous_committed_at_utc,
    reserved_amount,
    repayment_week_start
  )
  SELECT
    public.pay_advance_reservations.id,
    public.pay_advance_reservations.finance_case_id,
    public.pay_advance_reservations.finance_component_id,
    upper(coalesce(public.pay_advance_reservations.status, '')),
    public.pay_advance_reservations.committed_at_utc,
    public.pay_advance_reservations.reserved_amount,
    public.pay_advance_reservations.repayment_week_start
  FROM public.pay_advance_reservations
  WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(public.pay_advance_reservations.status, '')) = 'COMMITTED'
    AND public.pay_advance_reservations.settled_at_utc IS NULL
    AND public.pay_advance_reservations.released_at_utc IS NULL;

  UPDATE public.pay_advance_reservations AS reservation_to_rewind
  SET
    status = 'RESERVED',
    committed_at_utc = NULL,
    updated_by_user_id = p_actor_user_id
  WHERE reservation_to_rewind.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(reservation_to_rewind.status, '')) = 'COMMITTED'
    AND reservation_to_rewind.settled_at_utc IS NULL
    AND reservation_to_rewind.released_at_utc IS NULL;

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    finance_component_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    rewound_reservation.finance_case_id,
    'RESERVATION_REWOUND_TO_RESERVED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    rewound_reservation.reservation_id,
    rewound_reservation.finance_component_id,
    jsonb_build_object(
      'reservation_status', rewound_reservation.previous_status,
      'committed_at_utc', rewound_reservation.previous_committed_at_utc,
      'reserved_amount', rewound_reservation.reserved_amount,
      'repayment_week_start', rewound_reservation.repayment_week_start,
      'batch_status', v_batch.status,
      'execution_commit_state', v_batch.execution_commit_state
    ),
    jsonb_build_object(
      'reservation_status', 'RESERVED',
      'committed_at_utc', NULL,
      'reserved_amount', rewound_reservation.reserved_amount,
      'repayment_week_start', rewound_reservation.repayment_week_start,
      'batch_status', 'BLOCKED_FUNDS',
      'execution_commit_state', 'NOT_SUBMITTED',
      'repair_reason', 'blocked_funds_pre_submission_reservation_rewind'
    ),
    'blocked_funds_pre_submission_reservation_rewind',
    'Blocked funds before provider submission: local finance reservation rewound from COMMITTED to RESERVED.'
  FROM pg_temp.tmp_mark_blocked_rewound_reservations AS rewound_reservation;

  UPDATE public.pay_batches AS blocked_batch
  SET
    status = 'BLOCKED_FUNDS',
    last_funds_check_at_utc = v_now,
    last_funds_check_json = v_funds_check_json,
    schedule_kind = NULL,
    scheduled_at_utc = NULL,
    scheduled_by_user_id = NULL,
    execution_intent_json = jsonb_strip_nulls(
      COALESCE(blocked_batch.execution_intent_json, '{}'::jsonb)
      || jsonb_build_object(
        'blocked_funds', true,
        'blocked_funds_at_utc', v_now::text,
        'blocked_funds_by_user_id', p_actor_user_id::text,
        'blocked_funds_operation_id', CASE WHEN v_current_operation_id IS NULL THEN NULL ELSE v_current_operation_id::text END,
        'blocked_funds_auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
        'blocked_funds_cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb)
      )
    )
  WHERE blocked_batch.id = p_pay_batch_id;

  v_alert_payload := public.banking_alert_payload_for_pay_batch('BLOCKED_FUNDS', p_pay_batch_id);

  v_alert_fingerprint := public.banking_alert_fingerprint(
    'BLOCKED_FUNDS',
    'pay_batch',
    p_pay_batch_id,
    v_alert_payload
  );

  v_alert_payload := v_alert_payload || jsonb_build_object('alert_fingerprint', v_alert_fingerprint);

  v_notice_result := public.pay_payment_return_admin_notice_queue(
    'BLOCKED_FUNDS',
    p_pay_batch_id,
    v_rail_provider,
    NULL::text,
    v_alert_payload || jsonb_build_object(
      'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
      'bulk_reference', v_batch.bulk_reference,
      'status', 'BLOCKED_FUNDS'
    )
  );

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    public.pay_advance_reservations.finance_case_id,
    'FUNDS_BLOCKED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    public.pay_advance_reservations.id,
    jsonb_build_object(
      'reservation_status', public.pay_advance_reservations.status,
      'authoritative_payment_date', v_authoritative_payment_date,
      'authoritative_payment_date_source', v_authoritative_payment_date_source
    ),
    jsonb_build_object(
      'reservation_status', public.pay_advance_reservations.status,
      'batch_status', 'BLOCKED_FUNDS',
      'authoritative_payment_date', v_authoritative_payment_date,
      'authoritative_payment_date_source', v_authoritative_payment_date_source,
      'banking_alert_fingerprint', v_alert_fingerprint
    ),
    'funds_blocked',
    NULL::text
  FROM public.pay_advance_reservations
  WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(public.pay_advance_reservations.status, '')) IN ('RESERVED', 'COMMITTED');

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'status', reservation_summary.reservation_status,
        'count', reservation_summary.reservation_count,
        'amount', reservation_summary.reservation_amount
      )
      ORDER BY reservation_summary.reservation_status
    ),
    '[]'::jsonb
  )
  INTO v_reservation_status_summary
  FROM (
    SELECT
      upper(coalesce(public.pay_advance_reservations.status, '')) AS reservation_status,
      count(*)::integer AS reservation_count,
      round(coalesce(sum(public.pay_advance_reservations.reserved_amount), 0), 2) AS reservation_amount
    FROM public.pay_advance_reservations
    WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
      AND upper(coalesce(public.pay_advance_reservations.status, '')) IN ('RESERVED', 'COMMITTED')
    GROUP BY upper(coalesce(public.pay_advance_reservations.status, ''))
  ) AS reservation_summary;

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_MARK_BLOCKED_FUNDS:OK',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'status', 'BLOCKED_FUNDS',
        'authoritative_payment_date', v_authoritative_payment_date,
        'authoritative_payment_date_source', v_authoritative_payment_date_source,
        'reservation_status_summary', v_reservation_status_summary,
        'funds_check_json', v_funds_check_json,
        'submission_evidence', v_submission_evidence,
        'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
        'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
        'transfer_scope_rows_skipped', COALESCE(v_transfer_scope_rows_skipped, 0),
        'item_links_cleared', COALESCE(v_item_links_cleared, 0),
        'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
        'banking_alert_fingerprint', v_alert_fingerprint,
        'admin_notice_result', v_notice_result
      ),
      'pay_batches',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'status', 'BLOCKED_FUNDS',
    'last_funds_check_at_utc', v_now::text,
    'last_funds_check_json', v_funds_check_json,
    'authoritative_payment_date', CASE WHEN v_authoritative_payment_date IS NULL THEN NULL ELSE v_authoritative_payment_date::text END,
    'authoritative_payment_date_source', v_authoritative_payment_date_source,
    'reservation_status_summary', v_reservation_status_summary,
    'submission_evidence', v_submission_evidence,
    'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
    'cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb),
    'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
    'transfer_scope_rows_skipped', COALESCE(v_transfer_scope_rows_skipped, 0),
    'item_links_cleared', COALESCE(v_item_links_cleared, 0),
    'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
    'banking_alert_kind', 'BLOCKED_FUNDS',
    'banking_alert_fingerprint', v_alert_fingerprint,
    'banking_alert_payload', v_alert_payload,
    'blocked_funds_required_gbp', v_required_gbp_text,
    'blocked_funds_available_gbp', v_available_gbp_text,
    'blocked_funds_provider', v_rail_provider,
    'blocked_funds_env', v_rail_env,
    'blocked_funds_account_ref', v_funding_account_ref,
    'admin_notice_result', v_notice_result
  );
END;
$function$;

-- pay_batch_payment_status_page_v1(uuid,uuid,jsonb,text,text,integer,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_payment_status_page_v1(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_filter_json jsonb DEFAULT '{}'::jsonb, p_sort_key text DEFAULT 'STATUS'::text, p_sort_direction text DEFAULT 'ASC'::text, p_limit integer DEFAULT 25, p_cursor_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '5000ms'
AS $function$
DECLARE
    v_batch public.pay_batches%ROWTYPE;
    v_filter jsonb := coalesce(p_filter_json, '{}'::jsonb);
    v_sort_key text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_sort_key, '')));
    v_sort_direction text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_sort_direction, '')));
    v_snapshot_token text;
    v_explicit_snapshot_token text;
    v_active_batch_scope_hash text;
    v_rows jsonb := '[]'::jsonb;
    v_row_count integer := 0;
    v_total_matching_count integer := 0;
    v_eligible_matching_count integer := 0;
    v_selected_amount_pence_available bigint := 0;
    v_active_overview_candidate_count integer := 0;
    v_active_overview_amount_pence bigint := 0;
    v_original_overview_amount_pence bigint := 0;
    v_active_paye_schedule_line_count integer := 0;
    v_active_paye_schedule_amount_pence bigint := 0;
    v_has_more boolean := false;
    v_next_cursor_json jsonb := NULL;
    v_previous_cursor_json jsonb := NULL;
    v_last_row jsonb;
    v_latest_correction_request jsonb := NULL;
    v_batch_terminal boolean := false;
BEGIN
    IF p_pay_batch_id IS NULL THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'The Banking Pay batch was not found.'
        );
    END IF;

    IF pg_catalog.jsonb_typeof(v_filter) <> 'object' THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'FILTER_INVALID',
            'message', 'The payment-status filter is invalid.'
        );
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(v_filter) AS filter_key(key_name)
        WHERE filter_key.key_name NOT IN (
            'status',
            'action',
            'search',
            'actionable_only',
            'pay_channel',
            'excluded_candidate_tokens',
            'included_candidate_tokens'
        )
    ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'FILTER_INVALID',
            'message', 'The payment-status filter contains an unsupported field.'
        );
    END IF;

    IF (v_filter ? 'excluded_candidate_tokens'
        AND pg_catalog.jsonb_typeof(v_filter -> 'excluded_candidate_tokens') <> 'array')
       OR (v_filter ? 'included_candidate_tokens'
        AND pg_catalog.jsonb_typeof(v_filter -> 'included_candidate_tokens') <> 'array') THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'FILTER_INVALID',
            'message', 'The payment-status candidate filter is invalid.'
        );
    END IF;

    IF v_sort_key NOT IN ('STATUS', 'CANDIDATE', 'AMOUNT')
       OR v_sort_direction NOT IN ('ASC', 'DESC') THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'SORT_INVALID',
            'message', 'The payment-status sort is invalid.'
        );
    END IF;

    IF p_limit IS NULL OR p_limit NOT IN (25, 50, 75, 100) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'PAGE_SIZE_INVALID',
            'message', 'The page size must be 25, 50, 75 or 100.'
        );
    END IF;

    IF p_cursor_json IS NOT NULL
       AND (
           pg_catalog.jsonb_typeof(p_cursor_json) <> 'object'
           OR p_cursor_json ->> 'snapshot_token' IS NULL
           OR p_cursor_json ->> 'sort_key' IS DISTINCT FROM v_sort_key
           OR p_cursor_json ->> 'sort_direction' IS DISTINCT FROM v_sort_direction
           OR p_cursor_json ->> 'last_pay_batch_candidate_id' IS NULL
           OR p_cursor_json ->> 'last_pay_batch_candidate_id'
                !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'CURSOR_INVALID',
            'message', 'The payment-status cursor is invalid.'
        );
    END IF;

    SELECT batch_row.*
    INTO v_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_pay_batch_id;

    IF NOT FOUND THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'The Banking Pay batch was not found.'
        );
    END IF;

    v_batch_terminal := pg_catalog.upper(pg_catalog.btrim(coalesce(v_batch.status, ''))) IN (
        'COMMITTED', 'COMPLETED', 'PAID', 'SETTLED', 'CANCELLED', 'CANCELED'
    );

    IF p_actor_user_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM public.tms_users AS actor_user
        WHERE actor_user.id = p_actor_user_id
          AND coalesce(actor_user.is_active, false)
    ) THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'code', 'PERMISSION_DENIED',
            'message', 'You do not have permission to view this payment status.'
        );
    END IF;

    v_active_batch_scope_hash := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 2,
            'pay_batch_id', p_pay_batch_id,
            'batch_status', v_batch.status,
            'total_bank_out_pence', pg_catalog.round(coalesce(v_batch.total_bank_out, 0) * 100)::bigint,
            'source_scope_change_generation', v_batch.source_scope_change_generation,
            'execution_commit_state', v_batch.execution_commit_state,
            'execution_commit_ref', v_batch.execution_commit_ref,
            'execution_committed_at_utc', v_batch.execution_committed_at_utc,
            'execution_intent_json', v_batch.execution_intent_json,
            'rail_provider_snapshot', v_batch.rail_provider_snapshot,
            'rail_env_snapshot', v_batch.rail_env_snapshot,
            'freshness_validation_status', v_batch.freshness_validation_status,
            'freshness_result_hash', v_batch.freshness_result_hash,
            'freshness_scope_hash', v_batch.freshness_scope_hash,
            'schedule_kind', v_batch.schedule_kind,
            'scheduled_at_utc', v_batch.scheduled_at_utc,
            'active_authorisation', (
                SELECT pg_catalog.jsonb_build_object(
                    'auth_request_id', auth_row.id,
                    'state', auth_row.state,
                    'required_quantity', auth_row.required_quantity,
                    'schedule_kind', auth_row.schedule_kind,
                    'scheduled_at_utc', auth_row.scheduled_at_utc,
                    'execution_intent_json', auth_row.execution_intent_json
                )
                FROM public.pay_batch_auth_requests AS auth_row
                WHERE auth_row.pay_batch_id = p_pay_batch_id
                  AND auth_row.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
                ORDER BY auth_row.created_at_utc DESC, auth_row.id DESC
                LIMIT 1
            ),
            'change_signal', (
                SELECT pg_catalog.jsonb_build_object(
                    'version', coalesce(signal_row.version, 0),
                    'payment_status_version', coalesce(signal_row.payment_status_version, 0),
                    'correction_progress_version', coalesce(signal_row.correction_progress_version, 0),
                    'overview_version', coalesce(signal_row.overview_version, 0),
                    'last_changed_at_utc', signal_row.last_changed_at_utc
                )
                FROM public.banking_pay_batch_change_signals AS signal_row
                WHERE signal_row.pay_batch_id = p_pay_batch_id
            ),
            'scope_version_authority', 'banking_pay_batch_change_signals'
        )
    );

    v_snapshot_token := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 1,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'filter', v_filter,
            'sort_key', v_sort_key,
            'sort_direction', v_sort_direction
        )
    );

    -- EXPLICIT selection deliberately carries no filter authority. Bind a
    -- second token to that exact empty-filter contract so a filtered review
    -- can still submit an explicit UUID set without changing either scope.
    v_explicit_snapshot_token := private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
            'version', 1,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'filter', '{}'::jsonb,
            'sort_key', v_sort_key,
            'sort_direction', v_sort_direction
        )
    );

    IF p_cursor_json IS NOT NULL
       AND p_cursor_json ->> 'snapshot_token' IS DISTINCT FROM v_snapshot_token THEN
        RETURN pg_catalog.jsonb_build_object(
            'ok', false,
            'pay_batch_id', p_pay_batch_id,
            'snapshot_token', v_snapshot_token,
            'active_batch_scope_hash', v_active_batch_scope_hash,
            'code', 'PAYMENT_STATUS_SNAPSHOT_STALE',
            'message', 'Payment status changed. Refresh and select the payments again.'
        );
    END IF;

    WITH batch_provider_payloads AS MATERIALIZED (
        SELECT
            'OPERATION'::text AS evidence_source,
            operation_row.id AS operation_id,
            NULL::uuid AS chunk_id,
            operation_payload.payload_name,
            coalesce(operation_payload.payload_json, '{}'::jsonb) AS payload_json
        FROM public.banking_pay_operations AS operation_row
        CROSS JOIN LATERAL (VALUES
            ('progress_json'::text, operation_row.progress_json),
            ('result_json'::text, operation_row.result_json),
            ('error_json'::text, operation_row.error_json)
        ) AS operation_payload(payload_name, payload_json)
        WHERE operation_row.pay_batch_id = p_pay_batch_id
          AND pg_catalog.upper(coalesce(operation_row.operation_type, '')) LIKE '%PAY%'

        UNION ALL

        SELECT
            'CHUNK'::text AS evidence_source,
            operation_row.id AS operation_id,
            chunk_row.id AS chunk_id,
            chunk_payload.payload_name,
            coalesce(chunk_payload.payload_json, '{}'::jsonb) AS payload_json
        FROM public.banking_pay_operation_chunks AS chunk_row
        JOIN public.banking_pay_operations AS operation_row
          ON operation_row.id = chunk_row.operation_id
        CROSS JOIN LATERAL (VALUES
            ('payload_json'::text, chunk_row.payload_json),
            ('result_json'::text, chunk_row.result_json),
            ('error_json'::text, chunk_row.error_json)
        ) AS chunk_payload(payload_name, payload_json)
        WHERE operation_row.pay_batch_id = p_pay_batch_id
    ), batch_provider_payload_flags AS MATERIALIZED (
    SELECT
      batch_provider_payloads.evidence_source,
      batch_provider_payloads.operation_id,
      batch_provider_payloads.chunk_id,
      batch_provider_payloads.payload_name,
      batch_provider_payloads.payload_json,
      (
        lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerRequestSent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_request_sent_confirmed', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerRequestSentConfirmed', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'request_sent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'requestSent', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'request_dispatched', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'requestDispatched', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_submit_attempted', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerSubmitAttempted', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_evidence,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerEvidence,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{diagnostic,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{diagnostic,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{outcome,provider_request_sent}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{outcome,providerRequestSent}', '')), '')) IN ('true','t','yes','y','1')
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_request_sent_at_utc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_request_sent_at_utc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'requestSentAtUtc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'requestSentAtUtc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerRequestSentAtUtc', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerRequestSentAtUtc', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,requestSentAtUtc}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,requestSentAtUtc}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_request_sent_count', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json->>'provider_request_sent_count')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerRequestSentCount', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json->>'providerRequestSentCount')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_call_sent_count', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json->>'provider_call_sent_count')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerCallSentCount', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json->>'providerCallSentCount')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent_count}', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_request_sent_count}')::numeric > 0
        )
        OR (
          NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSentCount}', '')), '') ~ '^[0-9]+(\.[0-9]+)?$'
          AND (batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerRequestSentCount}')::numeric > 0
        )
      ) AS has_provider_request_sent,
      (
        lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_outcome_unknown', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerOutcomeUnknown', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'request_sent_no_response', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'requestSentNoResponse', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_outcome_unknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerOutcomeUnknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{diagnostic,provider_outcome_unknown}', '')), '')) IN ('true','t','yes','y','1')
        OR lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{diagnostic,providerOutcomeUnknown}', '')), '')) IN ('true','t','yes','y','1')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'code', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'error_code', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'status', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'outcome', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{error,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
        OR upper(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,code}', '')), '')) IN ('REQUEST_SENT_NO_RESPONSE', 'PROVIDER_OUTCOME_UNKNOWN', 'SUBMISSION_UNKNOWN')
      ) AS has_provider_outcome_unknown,
      (
        (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'rail_tx_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'rail_tx_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'railTxId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'railTxId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_transaction_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_transaction_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerTransactionId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerTransactionId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_payment_id', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'provider_payment_id', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerPaymentId', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json->>'providerPaymentId', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,transaction_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,transaction_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,transactionId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,transactionId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,payment_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,payment_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,paymentId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider,paymentId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_transaction_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_transaction_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_payment_id}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{provider_submit_diagnostic,provider_payment_id}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerTransactionId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerTransactionId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerPaymentId}', '')), '') IS NOT NULL AND lower(NULLIF(btrim(COALESCE(batch_provider_payloads.payload_json #>> '{providerSubmitDiagnostic,providerPaymentId}', '')), '')) NOT IN ('null','false','true','none','n/a','na','local','local_only'))
        OR (batch_provider_payloads.payload_json ? 'provider_response' AND batch_provider_payloads.payload_json->'provider_response' IS NOT NULL AND batch_provider_payloads.payload_json->'provider_response' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'provider_response') = 'object' AND batch_provider_payloads.payload_json->'provider_response' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response') = 'array' AND batch_provider_payloads.payload_json->'provider_response' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response') = 'number')))
        OR (batch_provider_payloads.payload_json ? 'provider_response_json' AND batch_provider_payloads.payload_json->'provider_response_json' IS NOT NULL AND batch_provider_payloads.payload_json->'provider_response_json' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'provider_response_json') = 'object' AND batch_provider_payloads.payload_json->'provider_response_json' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response_json') = 'array' AND batch_provider_payloads.payload_json->'provider_response_json' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_response_json') = 'number')))
        OR (batch_provider_payloads.payload_json ? 'submit_response' AND batch_provider_payloads.payload_json->'submit_response' IS NOT NULL AND batch_provider_payloads.payload_json->'submit_response' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'submit_response') = 'object' AND batch_provider_payloads.payload_json->'submit_response' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'submit_response') = 'array' AND batch_provider_payloads.payload_json->'submit_response' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'submit_response') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'submit_response')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'submit_response')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'submit_response') = 'number')))
        OR (batch_provider_payloads.payload_json ? 'response_json' AND batch_provider_payloads.payload_json->'response_json' IS NOT NULL AND batch_provider_payloads.payload_json->'response_json' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'response_json') = 'object' AND batch_provider_payloads.payload_json->'response_json' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'response_json') = 'array' AND batch_provider_payloads.payload_json->'response_json' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'response_json') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'response_json')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'response_json')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'response_json') = 'number')))
        OR (batch_provider_payloads.payload_json ? 'provider_result' AND batch_provider_payloads.payload_json->'provider_result' IS NOT NULL AND batch_provider_payloads.payload_json->'provider_result' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'provider_result') = 'object' AND batch_provider_payloads.payload_json->'provider_result' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_result') = 'array' AND batch_provider_payloads.payload_json->'provider_result' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_result') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_result')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_result')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_result') = 'number')))
        OR (batch_provider_payloads.payload_json ? 'provider_payload' AND batch_provider_payloads.payload_json->'provider_payload' IS NOT NULL AND batch_provider_payloads.payload_json->'provider_payload' <> 'null'::jsonb AND ((jsonb_typeof(batch_provider_payloads.payload_json->'provider_payload') = 'object' AND batch_provider_payloads.payload_json->'provider_payload' <> '{}'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_payload') = 'array' AND batch_provider_payloads.payload_json->'provider_payload' <> '[]'::jsonb) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_payload') = 'string' AND NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_payload')::text)), '') IS NOT NULL AND lower(NULLIF(btrim(trim(both '"' from (batch_provider_payloads.payload_json->'provider_payload')::text)), '')) NOT IN ('null','false','true','none','n/a','na')) OR (jsonb_typeof(batch_provider_payloads.payload_json->'provider_payload') = 'number')))
      ) AS has_provider_payload_evidence
    FROM batch_provider_payloads
    ), batch_provider_operation_facts AS MATERIALIZED (
        SELECT
            EXISTS (
                SELECT 1
                FROM public.banking_pay_operations AS provider_operation
                WHERE provider_operation.pay_batch_id = p_pay_batch_id
                  AND provider_operation.operation_type IN (
                      'PAYMENT_EXECUTE',
                      'PAYMENT_RETRY_BLOCKED_FUNDS'
                  )
                  AND provider_operation.status IN (
                      'QUEUED',
                      'RUNNING',
                      'PROCESSING',
                      'CLAIMED',
                      'IN_PROGRESS'
                  )
                  AND NOT (
                      pg_catalog.upper(pg_catalog.btrim(coalesce(provider_operation.phase, ''))) = 'SCHEDULE_PAYMENT'
                      AND pg_catalog.upper(pg_catalog.btrim(coalesce(provider_operation.resume_reason, ''))) IN (
                          'WAIT_FOR_SCHEDULED_NO_BANK_PAYMENT',
                          'WAIT_FOR_SCHEDULED_LOCAL_MANUAL_SETTLEMENT'
                      )
                  )
            ) AS provider_submission_in_progress,
            coalesce(pg_catalog.bool_or(has_provider_outcome_unknown), false)
                AS provider_outcome_unknown,
            coalesce(pg_catalog.bool_or(
                has_provider_request_sent OR has_provider_payload_evidence
            ), false) AS provider_request_sent,
            coalesce(pg_catalog.bool_or(has_provider_payload_evidence), false)
                AS provider_payload_evidence_present
        FROM batch_provider_payload_flags
    ), batch_unscoped_event_facts AS MATERIALIZED (
        SELECT
            coalesce(pg_catalog.bool_or(unscoped_movement.is_final_money_moved), false)
                AS final_money_moved,
            coalesce(pg_catalog.bool_or(unscoped_movement.is_terminal_no_money), false)
                AS terminal_no_money,
            coalesce(pg_catalog.bool_or(unscoped_movement.is_pending_non_final), false)
                AS pending_non_final,
            coalesce(pg_catalog.bool_or(
                (
                    unscoped_movement.cash_state = 'UNKNOWN'
                    OR pg_catalog.upper(coalesce(unscoped_event.normalised_state, ''))
                        IN ('UNKNOWN', 'OUTCOME_UNKNOWN', 'PROVIDER_UNKNOWN')
                    OR pg_catalog.upper(coalesce(unscoped_event.mapping_status, ''))
                        IN ('UNMATCHED', 'AMBIGUOUS', 'REVIEW_REQUIRED')
                    OR unscoped_event.movement_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
                    OR pg_catalog.upper(coalesce(unscoped_event.provider_failure_reason_group, ''))
                        IN ('WEBHOOK_UNMATCHED', 'PROVIDER_UNKNOWN')
                )
                AND pg_catalog.upper(coalesce(unscoped_event.provider_failure_reason_group, ''))
                    <> 'PROVIDER_OUTAGE'
            ), false) AS provider_outcome_unknown,
            coalesce(pg_catalog.bool_or(
                pg_catalog.upper(coalesce(unscoped_event.provider_failure_reason_group, '')) = 'PROVIDER_OUTAGE'
                AND pg_catalog.upper(coalesce(unscoped_event.mapping_status, '')) = 'MATCHED'
            ), false) AS provider_outage,
            coalesce(pg_catalog.bool_or(
                nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_transaction_id, '')), '') IS NOT NULL
                OR nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_event_key, '')), '') IS NOT NULL
            ), false) AS provider_external_id_present,
            coalesce(pg_catalog.bool_or(true), false) AS provider_event_present,
            coalesce(pg_catalog.bool_or(
                nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_transaction_id, '')), '') IS NOT NULL
                OR nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_event_key, '')), '') IS NOT NULL
                OR unscoped_event.provider_event_transport IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL')
                OR (
                    unscoped_event.provider_event_transport = 'PROVIDER_WEBHOOK'
                    AND unscoped_event.provider_signature_valid IS TRUE
                    AND unscoped_event.provider_webhook_receipt_id IS NOT NULL
                    AND unscoped_receipt.status IS NOT NULL
                    AND pg_catalog.upper(coalesce(unscoped_receipt.status, ''))
                        NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
                    AND unscoped_receipt.signature_valid IS TRUE
                    AND unscoped_receipt.provider_key IS NOT DISTINCT FROM unscoped_event.provider_key
                    AND unscoped_receipt.rail_env IS NOT DISTINCT FROM unscoped_event.rail_env
                    AND nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_event_key, '')), '') IS NOT NULL
                    AND unscoped_receipt.provider_event_key = unscoped_event.provider_event_key
                )
                OR (
                    unscoped_event.provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
                    AND unscoped_event.provider_webhook_receipt_id IS NOT NULL
                    AND unscoped_receipt.status IS NOT NULL
                    AND pg_catalog.upper(coalesce(unscoped_receipt.status, ''))
                        NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
                    AND unscoped_receipt.provider_key IS NOT DISTINCT FROM unscoped_event.provider_key
                    AND unscoped_receipt.rail_env IS NOT DISTINCT FROM unscoped_event.rail_env
                    AND nullif(pg_catalog.btrim(coalesce(unscoped_event.provider_event_key, '')), '') IS NOT NULL
                    AND unscoped_receipt.provider_event_key = unscoped_event.provider_event_key
                )
            ), false) AS provider_request_sent
        FROM public.pay_bank_transfer_events AS unscoped_event
        LEFT JOIN public.bank_provider_webhook_receipts AS unscoped_receipt
          ON unscoped_receipt.id = unscoped_event.provider_webhook_receipt_id
        CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
            unscoped_event.normalised_state,
            unscoped_event.provider_state,
            coalesce(unscoped_event.raw_payload, '{}'::jsonb),
            pg_catalog.jsonb_build_object(
                'provider_key', unscoped_event.provider_key,
                'provider_event_type', unscoped_event.provider_event_type,
                'provider_event_transport', unscoped_event.provider_event_transport,
                'provider_event_key', unscoped_event.provider_event_key
            )
        ) AS unscoped_movement
        WHERE unscoped_event.pay_batch_id = p_pay_batch_id
          AND unscoped_event.pay_bank_transfer_id IS NULL
    ), candidate_status_index AS MATERIALIZED (
        -- This is the key-selection index only.  It uses bounded indexed EXISTS
        -- probes and scalar latest-row lookups; all item/work/correction/provider
        -- rollups and JSON construction occur only after page_keys (<=100).
        SELECT candidate_row.id AS pay_batch_candidate_id,
               candidate_row.candidate_id,
               candidate_row.candidate_display_name,
               candidate_row.net_bank_amount,
               candidate_row.settlement_status,
               CASE WHEN EXISTS (
                 SELECT 1 FROM public.pay_batch_items AS active_item
                 WHERE active_item.pay_batch_candidate_id = candidate_row.id
                   AND COALESCE(active_item.is_voided, false) IS NOT TRUE
               ) THEN 1 ELSE 0 END::integer AS active_item_count,
               NOT EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS selected_scope_item
                 JOIN public.pay_batch_items AS shared_scope_item
                   ON shared_scope_item.pay_bank_transfer_id = selected_scope_item.pay_bank_transfer_id
                  AND shared_scope_item.id IS DISTINCT FROM selected_scope_item.id
                 JOIN public.pay_batch_candidates AS shared_scope_candidate
                   ON shared_scope_candidate.id = shared_scope_item.pay_batch_candidate_id
                 WHERE selected_scope_item.pay_batch_candidate_id = candidate_row.id
                   AND COALESCE(selected_scope_item.is_voided, false) IS NOT TRUE
                   AND selected_scope_item.pay_bank_transfer_id IS NOT NULL
                   AND shared_scope_candidate.pay_batch_id = p_pay_batch_id
                   AND NOT (
                     shared_scope_item.pay_batch_candidate_id = candidate_row.id
                     AND COALESCE(shared_scope_item.is_voided, false) IS NOT TRUE
                   )
               ) AS complete_candidate_instruction_scope,
               EXISTS (
                 SELECT 1
                 FROM public.banking_pay_operation_transfer_scope_items AS resolution_scope_item
                 JOIN public.banking_pay_operation_transfer_scope AS resolution_scope
                   ON resolution_scope.id = resolution_scope_item.transfer_scope_id
                  AND resolution_scope.operation_id = resolution_scope_item.operation_id
                  AND resolution_scope.pay_batch_id = resolution_scope_item.pay_batch_id
                 JOIN public.banking_pay_operations AS resolution_operation
                   ON resolution_operation.id = resolution_scope.operation_id
                  AND resolution_operation.pay_batch_id = resolution_scope.pay_batch_id
                 WHERE resolution_scope_item.pay_batch_id = p_pay_batch_id
                   AND resolution_scope_item.pay_batch_candidate_id = candidate_row.id
                   AND resolution_scope.pay_bank_transfer_id IS NOT NULL
                   AND resolution_operation.status <> 'CANCELLED'
               ) AS has_resolution_context,
               EXISTS (
                 SELECT 1 FROM public.pay_batch_items AS paye_item
                 WHERE paye_item.pay_batch_candidate_id = candidate_row.id
                   AND COALESCE(paye_item.is_voided, false) IS NOT TRUE
                   AND paye_item.pay_channel = 'PAYE'
               ) AS has_paye_item,
               EXISTS (
                 SELECT 1 FROM public.pay_batch_items AS non_paye_item
                 WHERE non_paye_item.pay_batch_candidate_id = candidate_row.id
                   AND COALESCE(non_paye_item.is_voided, false) IS NOT TRUE
                   AND non_paye_item.pay_channel <> 'PAYE'
               ) AS has_non_paye_item,
               (NOT EXISTS (
                  SELECT 1 FROM public.pay_batch_items AS active_item
                  WHERE active_item.pay_batch_candidate_id = candidate_row.id
                    AND COALESCE(active_item.is_voided, false) IS NOT TRUE
                ) OR EXISTS (
                  SELECT 1 FROM public.pay_payment_correction_items AS removed_item
                  WHERE removed_item.pay_batch_id = p_pay_batch_id
                    AND removed_item.pay_batch_candidate_id = candidate_row.id
                    AND removed_item.status = 'APPLIED'
                    AND removed_item.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND')
                )) AS removed,
               EXISTS (
                 SELECT 1 FROM public.pay_payment_correction_items AS released_item
                 WHERE released_item.pay_batch_id = p_pay_batch_id
                   AND released_item.pay_batch_candidate_id = candidate_row.id
                   AND released_item.status = 'APPLIED'
                   AND released_item.correction_item_kind = 'NO_MONEY_UNWIND'
               ) AS released,
               (candidate_row.settlement_status IN ('SETTLED','PAID') OR EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS event_item
                 JOIN public.pay_bank_transfer_events AS paid_event
                   ON paid_event.pay_bank_transfer_id = event_item.pay_bank_transfer_id
                 CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   paid_event.normalised_state,
                   paid_event.provider_state,
                   coalesce(paid_event.raw_payload, '{}'::jsonb),
                   pg_catalog.jsonb_build_object(
                     'provider_key', paid_event.provider_key,
                     'provider_event_type', paid_event.provider_event_type,
                     'provider_event_transport', paid_event.provider_event_transport,
                     'provider_event_key', paid_event.provider_event_key
                   )
                 ) AS paid_movement
                 WHERE event_item.pay_batch_candidate_id = candidate_row.id
                   AND paid_event.pay_batch_id = p_pay_batch_id
                   AND paid_movement.is_final_money_moved
               ) OR EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS transfer_item
                 JOIN public.pay_bank_transfers AS paid_transfer
                   ON paid_transfer.id = transfer_item.pay_bank_transfer_id
                 CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   paid_transfer.status,
                   paid_transfer.rail_state,
                   coalesce(paid_transfer.rail_meta_json, '{}'::jsonb),
                   pg_catalog.jsonb_build_object(
                     'provider_key', paid_transfer.rail_provider,
                     'rail_env', paid_transfer.rail_env,
                     'request_id', paid_transfer.request_id,
                     'rail_tx_id', paid_transfer.rail_tx_id
                   )
                 ) AS paid_transfer_movement
                 WHERE transfer_item.pay_batch_candidate_id = candidate_row.id
                   AND paid_transfer_movement.is_final_money_moved
                ) OR unscoped_event_facts.final_money_moved) AS paid_or_settled,
               (EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS event_item
                 JOIN public.pay_bank_transfer_events AS no_money_event
                   ON no_money_event.pay_bank_transfer_id = event_item.pay_bank_transfer_id
                 CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   no_money_event.normalised_state,
                   no_money_event.provider_state,
                   coalesce(no_money_event.raw_payload, '{}'::jsonb),
                   pg_catalog.jsonb_build_object(
                     'provider_key', no_money_event.provider_key,
                     'provider_event_type', no_money_event.provider_event_type,
                     'provider_event_transport', no_money_event.provider_event_transport,
                     'provider_event_key', no_money_event.provider_event_key
                   )
                 ) AS no_money_movement
                 WHERE event_item.pay_batch_candidate_id = candidate_row.id
                   AND no_money_event.pay_batch_id = p_pay_batch_id
                   AND no_money_movement.is_terminal_no_money
               ) OR EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS transfer_item
                 JOIN public.pay_bank_transfers AS failed_transfer
                   ON failed_transfer.id = transfer_item.pay_bank_transfer_id
                 CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   failed_transfer.status,
                   failed_transfer.rail_state,
                   coalesce(failed_transfer.rail_meta_json, '{}'::jsonb),
                   pg_catalog.jsonb_build_object(
                     'provider_key', failed_transfer.rail_provider,
                     'rail_env', failed_transfer.rail_env,
                     'request_id', failed_transfer.request_id,
                     'rail_tx_id', failed_transfer.rail_tx_id
                   )
                 ) AS failed_transfer_movement
                 WHERE transfer_item.pay_batch_candidate_id = candidate_row.id
                   AND failed_transfer_movement.is_terminal_no_money
                ) OR unscoped_event_facts.terminal_no_money) AS terminal_no_money,
               (EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS event_item
                  JOIN public.pay_bank_transfer_events AS ambiguous_event
                   ON ambiguous_event.pay_bank_transfer_id = event_item.pay_bank_transfer_id
                 CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   ambiguous_event.normalised_state,
                   ambiguous_event.provider_state,
                   coalesce(ambiguous_event.raw_payload, '{}'::jsonb),
                   pg_catalog.jsonb_build_object(
                     'provider_key', ambiguous_event.provider_key,
                     'provider_event_type', ambiguous_event.provider_event_type,
                     'provider_event_transport', ambiguous_event.provider_event_transport,
                     'provider_event_key', ambiguous_event.provider_event_key
                   )
                 ) AS ambiguous_movement
                  WHERE event_item.pay_batch_candidate_id = candidate_row.id
                    AND ambiguous_event.pay_batch_id = p_pay_batch_id
                    AND (
                      ambiguous_movement.cash_state = 'UNKNOWN'
                      OR ambiguous_event.mapping_status IN ('UNMATCHED', 'AMBIGUOUS', 'REVIEW_REQUIRED')
                      OR ambiguous_event.movement_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
                      OR ambiguous_event.provider_failure_reason_group IN ('WEBHOOK_UNMATCHED', 'PROVIDER_UNKNOWN')
                    )
                    AND pg_catalog.upper(coalesce(ambiguous_event.provider_failure_reason_group, '')) <> 'PROVIDER_OUTAGE'
                ) OR EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS transfer_item
                  JOIN public.pay_bank_transfers AS unknown_transfer
                    ON unknown_transfer.id = transfer_item.pay_bank_transfer_id
                  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                    unknown_transfer.status,
                    unknown_transfer.rail_state,
                    coalesce(unknown_transfer.rail_meta_json, '{}'::jsonb),
                    pg_catalog.jsonb_build_object(
                      'provider_key', unknown_transfer.rail_provider,
                      'rail_env', unknown_transfer.rail_env,
                      'request_id', unknown_transfer.request_id,
                      'rail_tx_id', unknown_transfer.rail_tx_id
                    )
                  ) AS unknown_transfer_movement
                  WHERE transfer_item.pay_batch_candidate_id = candidate_row.id
                    AND unknown_transfer_movement.cash_state = 'UNKNOWN'
                ) OR unscoped_event_facts.provider_outcome_unknown) AS provider_outcome_unknown,
               (EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS event_item
                  JOIN public.pay_bank_transfer_events AS pending_event
                    ON pending_event.pay_bank_transfer_id = event_item.pay_bank_transfer_id
                  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                    pending_event.normalised_state,
                    pending_event.provider_state,
                    coalesce(pending_event.raw_payload, '{}'::jsonb),
                    pg_catalog.jsonb_build_object(
                      'provider_key', pending_event.provider_key,
                      'provider_event_type', pending_event.provider_event_type,
                      'provider_event_transport', pending_event.provider_event_transport,
                      'provider_event_key', pending_event.provider_event_key
                    )
                  ) AS pending_event_movement
                  WHERE event_item.pay_batch_candidate_id = candidate_row.id
                    AND pending_event.pay_batch_id = p_pay_batch_id
                    AND pending_event_movement.is_pending_non_final
                ) OR EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS transfer_item
                  JOIN public.pay_bank_transfers AS pending_transfer
                    ON pending_transfer.id = transfer_item.pay_bank_transfer_id
                  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
                    pending_transfer.status,
                    pending_transfer.rail_state,
                    coalesce(pending_transfer.rail_meta_json, '{}'::jsonb),
                    pg_catalog.jsonb_build_object(
                      'provider_key', pending_transfer.rail_provider,
                      'rail_env', pending_transfer.rail_env,
                      'request_id', pending_transfer.request_id,
                      'rail_tx_id', pending_transfer.rail_tx_id
                    )
                  ) AS pending_transfer_movement
                  WHERE transfer_item.pay_batch_candidate_id = candidate_row.id
                    AND pending_transfer_movement.is_pending_non_final
                ) OR unscoped_event_facts.pending_non_final) AS provider_pending_non_final,
               (EXISTS (
                  SELECT 1
                  FROM public.pay_batch_items AS outage_item
                  JOIN public.pay_bank_transfer_events AS outage_event
                    ON outage_event.pay_bank_transfer_id = outage_item.pay_bank_transfer_id
                  WHERE outage_item.pay_batch_candidate_id = candidate_row.id
                    AND outage_event.pay_batch_id = p_pay_batch_id
                    AND pg_catalog.upper(coalesce(outage_event.provider_failure_reason_group, '')) = 'PROVIDER_OUTAGE'
                    AND pg_catalog.upper(coalesce(outage_event.mapping_status, '')) = 'MATCHED'
                ) OR unscoped_event_facts.provider_outage) AS provider_outage,
               (
                 provider_facts.provider_request_sent
                 OR unscoped_event_facts.provider_request_sent
                 OR EXISTS (
                    SELECT 1
                    FROM public.pay_batch_items AS request_item
                    JOIN public.pay_bank_transfers AS request_transfer
                      ON request_transfer.id = request_item.pay_bank_transfer_id
                    WHERE request_item.pay_batch_candidate_id = candidate_row.id
                      AND (
                        nullif(pg_catalog.btrim(coalesce(request_transfer.rail_tx_id, '')), '') IS NOT NULL
                        OR pg_catalog.upper(coalesce(request_transfer.status, '')) IN (
                          'REQUEST_SENT', 'PROVIDER_REQUEST_SENT', 'SUBMITTED', 'SENT',
                          'PROCESSING', 'ACCEPTED', 'PROVIDER_SUBMITTED',
                          'SUBMISSION_UNKNOWN', 'REQUEST_SENT_NO_RESPONSE'
                        )
                        OR pg_catalog.lower(nullif(pg_catalog.btrim(coalesce(
                             request_transfer.rail_meta_json ->> 'provider_request_sent', ''
                           )), '')) IN ('true', 't', 'yes', 'y', '1')
                        OR pg_catalog.lower(nullif(pg_catalog.btrim(coalesce(
                             request_transfer.rail_meta_json ->> 'request_sent', ''
                           )), '')) IN ('true', 't', 'yes', 'y', '1')
                        OR pg_catalog.lower(nullif(pg_catalog.btrim(coalesce(
                             request_transfer.rail_meta_json ->> 'provider_submit_attempted', ''
                           )), '')) IN ('true', 't', 'yes', 'y', '1')
                        OR nullif(pg_catalog.btrim(coalesce(
                             request_transfer.rail_meta_json ->> 'request_sent_at_utc', ''
                           )), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(
                             request_transfer.rail_meta_json ->> 'provider_request_sent_at_utc', ''
                           )), '') IS NOT NULL
                        OR (
                             request_transfer.rail_meta_json ? 'provider_response'
                             AND request_transfer.rail_meta_json -> 'provider_response' IS NOT NULL
                             AND request_transfer.rail_meta_json -> 'provider_response' <> 'null'::jsonb
                           )
                      )
                 )
                 OR EXISTS (
                    SELECT 1
                    FROM public.pay_batch_items AS request_event_item
                    JOIN public.pay_bank_transfer_events AS request_event
                      ON request_event.pay_bank_transfer_id = request_event_item.pay_bank_transfer_id
                    LEFT JOIN public.bank_provider_webhook_receipts AS request_receipt
                      ON request_receipt.id = request_event.provider_webhook_receipt_id
                    WHERE request_event_item.pay_batch_candidate_id = candidate_row.id
                      AND request_event.pay_batch_id = p_pay_batch_id
                      AND (
                        nullif(pg_catalog.btrim(coalesce(request_event.provider_transaction_id, '')), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(request_event.provider_event_key, '')), '') IS NOT NULL
                        OR request_event.provider_event_transport IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL')
                        OR (
                          request_event.provider_event_transport = 'PROVIDER_WEBHOOK'
                          AND request_event.provider_signature_valid IS TRUE
                          AND request_event.provider_webhook_receipt_id IS NOT NULL
                          AND request_receipt.status IS NOT NULL
                          AND pg_catalog.upper(coalesce(request_receipt.status, ''))
                              NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL', 'FAILED_RETRYABLE')
                          AND request_receipt.signature_valid IS TRUE
                          AND request_receipt.provider_key IS NOT DISTINCT FROM request_event.provider_key
                          AND request_receipt.rail_env IS NOT DISTINCT FROM request_event.rail_env
                          AND nullif(pg_catalog.btrim(coalesce(request_event.provider_event_key, '')), '') IS NOT NULL
                          AND request_receipt.provider_event_key = request_event.provider_event_key
                        )
                        OR (
                          request_event.provider_event_transport = 'FAILED_WEBHOOK_REPLAY'
                          AND request_event.provider_webhook_receipt_id IS NOT NULL
                          AND request_receipt.status IS NOT NULL
                          AND pg_catalog.upper(coalesce(request_receipt.status, ''))
                              NOT IN ('SIGNATURE_INVALID', 'FAILED_FINAL')
                          AND request_receipt.provider_key IS NOT DISTINCT FROM request_event.provider_key
                          AND request_receipt.rail_env IS NOT DISTINCT FROM request_event.rail_env
                          AND nullif(pg_catalog.btrim(coalesce(request_event.provider_event_key, '')), '') IS NOT NULL
                          AND request_receipt.provider_event_key = request_event.provider_event_key
                        )
                      )
                 )
               ) AS provider_request_sent,
               (
                 unscoped_event_facts.provider_external_id_present
                 OR EXISTS (
                    SELECT 1
                    FROM public.pay_batch_items AS external_item
                    JOIN public.pay_bank_transfers AS external_transfer
                      ON external_transfer.id = external_item.pay_bank_transfer_id
                    WHERE external_item.pay_batch_candidate_id = candidate_row.id
                      AND (
                        nullif(pg_catalog.btrim(coalesce(external_transfer.rail_tx_id, '')), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(
                             external_transfer.rail_meta_json ->> 'rail_tx_id', ''
                           )), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(
                             external_transfer.rail_meta_json ->> 'provider_transaction_id', ''
                           )), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(
                             external_transfer.rail_meta_json ->> 'provider_payment_id', ''
                           )), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(
                             external_transfer.rail_meta_json ->> 'provider_reference', ''
                           )), '') IS NOT NULL
                      )
                 )
                 OR EXISTS (
                    SELECT 1
                    FROM public.pay_batch_items AS external_event_item
                    JOIN public.pay_bank_transfer_events AS external_event
                      ON external_event.pay_bank_transfer_id = external_event_item.pay_bank_transfer_id
                    WHERE external_event_item.pay_batch_candidate_id = candidate_row.id
                      AND external_event.pay_batch_id = p_pay_batch_id
                      AND (
                        nullif(pg_catalog.btrim(coalesce(external_event.provider_transaction_id, '')), '') IS NOT NULL
                        OR nullif(pg_catalog.btrim(coalesce(external_event.provider_event_key, '')), '') IS NOT NULL
                      )
                 )
               ) AS provider_external_id_present,
               (
                 unscoped_event_facts.provider_event_present
                 OR EXISTS (
                    SELECT 1
                    FROM public.pay_batch_items AS provider_event_item
                    JOIN public.pay_bank_transfer_events AS provider_event
                      ON provider_event.pay_bank_transfer_id = provider_event_item.pay_bank_transfer_id
                    WHERE provider_event_item.pay_batch_candidate_id = candidate_row.id
                      AND provider_event.pay_batch_id = p_pay_batch_id
                 )
               ) AS provider_event_present,
               EXISTS (
                 SELECT 1
                 FROM public.pay_batch_items AS manual_item
                 JOIN public.pay_batch_candidates AS manual_candidate
                   ON manual_candidate.id = manual_item.pay_batch_candidate_id
                 LEFT JOIN public.pay_bank_transfers AS manual_transfer
                   ON manual_transfer.id = manual_item.pay_bank_transfer_id
                 LEFT JOIN public.candidates AS manual_candidate_record
                   ON manual_candidate_record.id = manual_candidate.candidate_id
                 WHERE manual_candidate.pay_batch_id = p_pay_batch_id
                   AND manual_item.pay_batch_candidate_id = candidate_row.id
                   AND (
                     pg_catalog.upper(coalesce(manual_item.item_type, '')) LIKE '%MANUAL%'
                     OR pg_catalog.upper(coalesce(manual_item.item_type, '')) LIKE '%ADJUSTMENT%'
                     OR pg_catalog.upper(coalesce(manual_item.item_type, '')) LIKE '%DEBT%'
                     OR pg_catalog.upper(coalesce(manual_item.item_type, '')) LIKE '%CREDIT%'
                     OR pg_catalog.upper(coalesce(manual_item.item_type, '')) IN (
                       'ADJUSTMENT_DELTA', 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
                       'MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY',
                       'FINANCE_ADJUSTMENT'
                     )
                     OR pg_catalog.upper(coalesce(manual_item.source_ref, '')) LIKE 'MANUAL%'
                     OR pg_catalog.upper(coalesce(manual_item.operation_source_key, '')) LIKE 'MANUAL%'
                   )
                   AND NOT EXISTS (
                     SELECT 1
                     FROM public.pay_manual_adjustment_carry_forwards AS existing_target
                     WHERE existing_target.target_pay_batch_item_id = manual_item.id
                   )
                   AND pg_catalog.upper(coalesce(manual_item.source_ref, '')) NOT LIKE 'CARRY_FORWARD:%'
                   AND pg_catalog.upper(coalesce(manual_item.operation_source_key, '')) NOT LIKE 'CARRY_FORWARD:%'
                   AND manual_item.finance_case_id IS NULL
                   AND manual_item.finance_component_id IS NULL
                   AND manual_item.reservation_id IS NULL
                   AND manual_item.timesheet_id IS NULL
                   AND pg_catalog.upper(coalesce(manual_item.operation_source_key, '')) NOT LIKE ALL (
                     ARRAY['TIMESHEET:%', 'TS:%', 'SEG:%', 'ADJ:%', 'EXPENSE:%',
                           'MILEAGE:%', 'ADDITIONAL%', 'FINANCE:%', 'FINANCE_CASE:%',
                           'RESERVATION:%', 'ADVANCE:%']
                   )
                   AND pg_catalog.upper(coalesce(manual_item.source_ref, '')) NOT LIKE ALL (
                     ARRAY['TS:%', 'SEG:%', 'ADJ:%', 'EXPENSE:%', 'MILEAGE:%', 'ADDITIONAL%']
                   )
                   AND NOT (
                     manual_item.amount_inc_vat IS NOT NULL
                     AND pg_catalog.round(manual_item.amount_inc_vat, 2) <> 0
                     AND manual_item.amount_ex_vat IS NOT NULL
                     AND manual_item.amount_vat IS NOT NULL
                     AND nullif(pg_catalog.btrim(coalesce(manual_item.description, '')), '') IS NOT NULL
                     AND manual_candidate.candidate_id IS NOT NULL
                     AND pg_catalog.upper(pg_catalog.btrim(coalesce(manual_item.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
                     AND (
                       pg_catalog.upper(pg_catalog.btrim(coalesce(manual_item.pay_channel, ''))) = 'PAYE'
                       OR coalesce(
                         manual_item.umbrella_id,
                         manual_transfer.umbrella_id,
                         manual_candidate_record.umbrella_id,
                         CASE
                           WHEN pg_catalog.upper(coalesce(manual_transfer.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY')
                           THEN manual_transfer.payee_entity_id
                           ELSE NULL::uuid
                         END
                       ) IS NOT NULL
                     )
                   )
               ) AS manual_carry_forward_blocked,
               EXISTS (
                 SELECT 1
                 FROM public.pay_manual_adjustment_carry_forwards AS carry_forward
                 LEFT JOIN public.pay_batch_items AS target_item
                   ON target_item.id = carry_forward.target_pay_batch_item_id
                 LEFT JOIN public.pay_batch_candidates AS target_candidate
                   ON target_candidate.id = target_item.pay_batch_candidate_id
                 LEFT JOIN public.pay_batch_items AS source_item
                   ON source_item.id = carry_forward.source_pay_batch_item_id
                 LEFT JOIN public.pay_batch_candidates AS source_candidate
                   ON source_candidate.id = source_item.pay_batch_candidate_id
                 LEFT JOIN public.pay_bank_transfers AS source_transfer
                   ON source_transfer.id = source_item.pay_bank_transfer_id
                 LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
                   source_transfer.status,
                   source_transfer.rail_state,
                   coalesce(source_transfer.rail_meta_json, '{}'::jsonb),
                   coalesce(source_transfer.rail_meta_json, '{}'::jsonb)
                 ) AS source_movement ON source_item.pay_bank_transfer_id IS NOT NULL
                 WHERE (
                   carry_forward.candidate_id = candidate_row.candidate_id
                   OR target_item.pay_batch_candidate_id = candidate_row.id
                   OR source_item.pay_batch_candidate_id = candidate_row.id
                 )
                   AND (
                     carry_forward.status IN ('CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW')
                     OR (
                       carry_forward.status = 'CONSUMED_IN_BATCH'
                       AND carry_forward.target_pay_batch_id IS DISTINCT FROM p_pay_batch_id
                     )
                     OR (
                       carry_forward.status = 'RESERVED_IN_DRAFT'
                       AND carry_forward.target_pay_batch_id IS NOT NULL
                       AND carry_forward.target_pay_batch_id IS DISTINCT FROM p_pay_batch_id
                     )
                     OR (
                       carry_forward.status = 'RESERVED_IN_DRAFT'
                       AND carry_forward.target_pay_batch_id = p_pay_batch_id
                       AND target_item.id IS NULL
                     )
                     OR (
                       carry_forward.status = 'RESERVED_IN_DRAFT'
                       AND carry_forward.target_pay_batch_id = p_pay_batch_id
                       AND coalesce(target_item.is_voided, false)
                     )
                     OR (
                       carry_forward.status = 'RESERVED_IN_DRAFT'
                       AND carry_forward.target_pay_batch_id = p_pay_batch_id
                       AND (
                         pg_catalog.round(coalesce(carry_forward.amount_ex_vat, 0), 2)
                           <> pg_catalog.round(coalesce(target_item.amount_ex_vat, 0), 2)
                         OR pg_catalog.round(coalesce(carry_forward.amount_vat, 0), 2)
                           <> pg_catalog.round(coalesce(target_item.amount_vat, 0), 2)
                         OR pg_catalog.round(coalesce(carry_forward.amount_inc_vat, 0), 2)
                           <> pg_catalog.round(coalesce(target_item.amount_inc_vat, 0), 2)
                       )
                     )
                     OR (
                       source_item.id IS NOT NULL
                       AND (
                         pg_catalog.round(coalesce(carry_forward.amount_ex_vat, 0), 2)
                           <> pg_catalog.round(coalesce(source_item.amount_ex_vat, 0), 2)
                         OR pg_catalog.round(coalesce(carry_forward.amount_vat, 0), 2)
                           <> pg_catalog.round(coalesce(source_item.amount_vat, 0), 2)
                         OR pg_catalog.round(coalesce(carry_forward.amount_inc_vat, 0), 2)
                           <> pg_catalog.round(coalesce(source_item.amount_inc_vat, 0), 2)
                       )
                     )
                     OR pg_catalog.upper(coalesce(source_candidate.settlement_status, '')) = 'SETTLED'
                     OR source_candidate.settled_at_utc IS NOT NULL
                     OR coalesce(source_movement.is_final_money_moved, false)
                     OR (
                       carry_forward.status = 'PENDING_CARRY_FORWARD'
                       AND carry_forward.candidate_id = candidate_row.candidate_id
                       AND NOT EXISTS (
                         SELECT 1
                         FROM public.pay_batch_items AS represented_item
                         JOIN public.pay_batch_candidates AS represented_candidate
                           ON represented_candidate.id = represented_item.pay_batch_candidate_id
                         WHERE represented_candidate.pay_batch_id = p_pay_batch_id
                           AND represented_candidate.candidate_id = carry_forward.candidate_id
                           AND pg_catalog.upper(pg_catalog.btrim(coalesce(represented_item.pay_channel, '')))
                             = pg_catalog.upper(pg_catalog.btrim(coalesce(carry_forward.pay_channel, '')))
                           AND coalesce(represented_item.is_voided, false) IS NOT TRUE
                           AND (
                             represented_item.id = carry_forward.target_pay_batch_item_id
                             OR pg_catalog.lower(coalesce(represented_item.operation_source_key, ''))
                               = 'carry_forward:' || carry_forward.id::text
                             OR pg_catalog.lower(coalesce(represented_item.source_ref, ''))
                               = 'carry_forward:' || carry_forward.id::text
                           )
                       )
                     )
                   )
               ) AS carry_forward_freshness_blocked,
               (
                 SELECT work_row.status
                 FROM public.pay_payment_correction_work_items AS work_row
                 WHERE work_row.pay_batch_id = p_pay_batch_id
                   AND work_row.pay_batch_candidate_id = candidate_row.id
                 ORDER BY work_row.created_at_utc DESC, work_row.id DESC LIMIT 1
               ) AS latest_work_status,
               COALESCE((
                 SELECT member_row.active_amount
                 FROM public.pay_payment_correction_request_candidates AS member_row
                 JOIN public.pay_payment_correction_requests AS request_row
                   ON request_row.id = member_row.correction_request_id
                 WHERE request_row.pay_batch_id = p_pay_batch_id
                   AND member_row.pay_batch_candidate_id = candidate_row.id
                 ORDER BY CASE WHEN request_row.status IN ('APPLIED','APPLIED_WITH_BLOCKERS') THEN 0 ELSE 1 END,
                          request_row.updated_at_utc DESC, request_row.id DESC LIMIT 1
               ), CASE
                    WHEN EXISTS (
                      SELECT 1
                      FROM public.pay_batch_items AS paye_scope_item
                      WHERE paye_scope_item.pay_batch_candidate_id = candidate_row.id
                        AND COALESCE(paye_scope_item.is_voided, false) IS NOT TRUE
                        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(paye_scope_item.pay_channel, ''))) = 'PAYE'
                    ) THEN
                      COALESCE((
                        SELECT paye_input.net_amount
                        FROM public.pay_batch_paye_net_inputs AS paye_input
                        WHERE paye_input.pay_batch_candidate_id = candidate_row.id
                        ORDER BY paye_input.imported_at_utc DESC, paye_input.id DESC
                        LIMIT 1
                      ), 0)
                      + COALESCE((
                        SELECT pg_catalog.sum(umbrella_scope_item.amount_inc_vat)
                        FROM public.pay_batch_items AS umbrella_scope_item
                        WHERE umbrella_scope_item.pay_batch_candidate_id = candidate_row.id
                          AND COALESCE(umbrella_scope_item.is_voided, false) IS NOT TRUE
                          AND pg_catalog.upper(pg_catalog.btrim(COALESCE(umbrella_scope_item.pay_channel, ''))) = 'UMBRELLA'
                      ), 0)
                    ELSE candidate_row.net_bank_amount
                  END, 0)::numeric(14,2) AS reviewed_payment_amount
        FROM public.pay_batch_candidates AS candidate_row
        CROSS JOIN batch_provider_operation_facts AS provider_facts
        CROSS JOIN batch_unscoped_event_facts AS unscoped_event_facts
        WHERE candidate_row.pay_batch_id = p_pay_batch_id
    ), candidate_provider_precedence_index AS MATERIALIZED (
        SELECT candidate_status_index.*,
               CASE
                 WHEN candidate_status_index.paid_or_settled THEN 'FINAL_PAID'
                 WHEN candidate_status_index.provider_outcome_unknown
                      OR provider_facts.provider_outcome_unknown THEN 'PROVIDER_OUTCOME_UNKNOWN'
                  WHEN (
                         candidate_status_index.provider_request_sent
                         OR candidate_status_index.provider_external_id_present
                         OR provider_facts.provider_submission_in_progress
                         OR (
                           candidate_status_index.provider_pending_non_final
                           AND candidate_status_index.provider_event_present
                         )
                       )
                      AND candidate_status_index.terminal_no_money IS NOT TRUE
                      AND candidate_status_index.paid_or_settled IS NOT TRUE
                   THEN 'PENDING_NON_FINAL'
                 WHEN candidate_status_index.provider_outage
                      AND candidate_status_index.provider_request_sent IS NOT TRUE
                      AND candidate_status_index.provider_external_id_present IS NOT TRUE
                      AND provider_facts.provider_submission_in_progress IS NOT TRUE
                   THEN 'PROVIDER_OUTAGE_RETRY_LATER'
                 WHEN candidate_status_index.terminal_no_money THEN 'TERMINAL_NO_MONEY'
                 ELSE 'NO_TRANSFER_EVIDENCE'
               END AS canonical_provider_state,
               (
                 candidate_status_index.provider_outcome_unknown
                 OR provider_facts.provider_outcome_unknown
                 OR (
                    (
                      candidate_status_index.provider_request_sent
                      OR candidate_status_index.provider_external_id_present
                      OR provider_facts.provider_submission_in_progress
                      OR (
                        candidate_status_index.provider_pending_non_final
                        AND candidate_status_index.provider_event_present
                      )
                    )
                   AND candidate_status_index.terminal_no_money IS NOT TRUE
                   AND candidate_status_index.paid_or_settled IS NOT TRUE
                 )
               ) AS ambiguous
        FROM candidate_status_index
        CROSS JOIN batch_provider_operation_facts AS provider_facts
    ), candidate_release_eligibility_index AS MATERIALIZED (
        SELECT candidate_provider_precedence_index.*,
               (
                  v_batch_terminal IS NOT TRUE
                  AND
                  candidate_provider_precedence_index.canonical_provider_state = 'TERMINAL_NO_MONEY'
                  AND candidate_provider_precedence_index.paid_or_settled IS NOT TRUE
                  AND candidate_provider_precedence_index.ambiguous IS NOT TRUE
                  AND candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'BLOCKED'
                  AND candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'FAILED_FINAL'
                  AND candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'FAILED_RETRYABLE'
                  AND candidate_provider_precedence_index.manual_carry_forward_blocked IS NOT TRUE
                  AND candidate_provider_precedence_index.carry_forward_freshness_blocked IS NOT TRUE
                  AND candidate_provider_precedence_index.complete_candidate_instruction_scope
                  AND provider_facts.provider_submission_in_progress IS NOT TRUE
                  AND provider_facts.provider_outcome_unknown IS NOT TRUE
                ) AS release_failed_payment_eligible,
                (
                  v_batch_terminal IS NOT TRUE
                  AND
                  candidate_provider_precedence_index.removed IS NOT TRUE
                  AND candidate_provider_precedence_index.active_item_count > 0
                  AND candidate_provider_precedence_index.canonical_provider_state = 'NO_TRANSFER_EVIDENCE'
                  AND candidate_provider_precedence_index.paid_or_settled IS NOT TRUE
                  AND candidate_provider_precedence_index.ambiguous IS NOT TRUE
                  AND candidate_provider_precedence_index.provider_request_sent IS NOT TRUE
                  AND candidate_provider_precedence_index.provider_external_id_present IS NOT TRUE
                  AND candidate_provider_precedence_index.provider_outcome_unknown IS NOT TRUE
                  AND candidate_provider_precedence_index.provider_outage IS NOT TRUE
                  AND candidate_provider_precedence_index.terminal_no_money IS NOT TRUE
                  -- A terminal historical attempt is audit evidence, not current
                  -- Draft authority.  A fresh Draft retry must still pass every
                  -- provider, frozen-scope, carry-forward and completeness fence.
                  AND (
                    v_batch.status = 'DRAFT'
                    OR (
                      candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'BLOCKED'
                      AND candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'FAILED_FINAL'
                      AND candidate_provider_precedence_index.latest_work_status IS DISTINCT FROM 'FAILED_RETRYABLE'
                    )
                  )
                  AND candidate_provider_precedence_index.manual_carry_forward_blocked IS NOT TRUE
                  AND candidate_provider_precedence_index.carry_forward_freshness_blocked IS NOT TRUE
                  AND candidate_provider_precedence_index.complete_candidate_instruction_scope
                  AND provider_facts.provider_submission_in_progress IS NOT TRUE
                  AND provider_facts.provider_outcome_unknown IS NOT TRUE
                ) AS pre_provider_cancel_eligible
        FROM candidate_provider_precedence_index
        CROSS JOIN batch_provider_operation_facts AS provider_facts
    ), candidate_classified_index AS MATERIALIZED (
        SELECT candidate_release_eligibility_index.*,
               CASE
                 WHEN removed AND released THEN 'RELEASED'
                 WHEN removed THEN 'CANCELLED'
                 WHEN paid_or_settled THEN 'SETTLED'
                 WHEN v_batch.status = 'DRAFT' AND pre_provider_cancel_eligible THEN 'ACTIVE'
                 WHEN latest_work_status = 'BLOCKED' THEN 'BLOCKED'
                 WHEN latest_work_status IN ('FAILED_FINAL','FAILED_RETRYABLE') THEN 'FAILED'
                 WHEN canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'BLOCKED'
                 WHEN release_failed_payment_eligible THEN 'NOT_PAID'
                 WHEN ambiguous THEN 'AMBIGUOUS'
                 WHEN terminal_no_money THEN 'BLOCKED'
                 ELSE 'ACTIVE'
               END AS payment_display_state,
               CASE
                 WHEN removed OR paid_or_settled THEN ARRAY[]::text[]
                 WHEN v_batch_terminal THEN ARRAY[]::text[]
                 WHEN v_batch.status = 'DRAFT' AND pre_provider_cancel_eligible
                   THEN ARRAY['DRAFT_CANCEL']::text[]
                 WHEN latest_work_status IN ('BLOCKED', 'FAILED_FINAL', 'FAILED_RETRYABLE') THEN ARRAY[]::text[]
                 WHEN canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN ARRAY[]::text[]
                 WHEN v_batch.status = 'DRAFT' THEN ARRAY[]::text[]
                 WHEN release_failed_payment_eligible THEN ARRAY['RELEASE_FAILED_PAYMENT']::text[]
                 WHEN ambiguous AND has_resolution_context THEN ARRAY['RESOLVE_PAYMENT_STATUS']::text[]
                 WHEN ambiguous THEN ARRAY[]::text[]
                 WHEN terminal_no_money THEN ARRAY[]::text[]
                 WHEN pre_provider_cancel_eligible THEN ARRAY['CANCEL_PAYMENT']::text[]
                 ELSE ARRAY[]::text[]
               END AS available_actions,
               pg_catalog.round(reviewed_payment_amount * 100)::bigint AS original_payment_amount_pence,
                CASE WHEN removed THEN 70 WHEN paid_or_settled THEN 60
                     WHEN v_batch.status = 'DRAFT' AND pre_provider_cancel_eligible THEN 10
                     WHEN latest_work_status = 'BLOCKED' THEN 50
                     WHEN canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 50
                     WHEN release_failed_payment_eligible THEN 40
                    WHEN ambiguous THEN 30
                    WHEN terminal_no_money THEN 50
                    ELSE 10 END AS status_rank
        FROM candidate_release_eligibility_index
    ), candidate_filtered_index AS MATERIALIZED (
        SELECT classified_index.*
        FROM candidate_classified_index AS classified_index
        WHERE (NULLIF(pg_catalog.btrim(v_filter->>'search'), '') IS NULL
               OR pg_catalog.lower(classified_index.candidate_display_name)
                  LIKE '%' || pg_catalog.lower(pg_catalog.btrim(v_filter->>'search')) || '%')
          AND (NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter->>'status')), '') IS NULL
               OR classified_index.payment_display_state = pg_catalog.upper(pg_catalog.btrim(v_filter->>'status')))
          AND (NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter->>'action')), '') IS NULL
               OR pg_catalog.upper(pg_catalog.btrim(v_filter->>'action')) = ANY(classified_index.available_actions))
          AND (COALESCE((v_filter->>'actionable_only')::boolean, false) IS NOT TRUE
               OR pg_catalog.cardinality(classified_index.available_actions) > 0)
          AND (NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter->>'pay_channel')), '') IS NULL
               OR (pg_catalog.upper(pg_catalog.btrim(v_filter->>'pay_channel')) = 'PAYE'
                   AND classified_index.has_paye_item))
          AND NOT EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
              COALESCE(v_filter->'excluded_candidate_tokens', '[]'::jsonb)
            ) AS excluded_token(value)
            WHERE excluded_token.value = classified_index.pay_batch_candidate_id::text
          )
          AND (NOT (v_filter ? 'included_candidate_tokens') OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
              v_filter->'included_candidate_tokens'
            ) AS included_token(value)
            WHERE included_token.value = classified_index.pay_batch_candidate_id::text
          ))
    ), candidate_after_cursor AS MATERIALIZED (
        SELECT filtered_index.*
        FROM candidate_filtered_index AS filtered_index
        WHERE p_cursor_json IS NULL OR
          (v_sort_key = 'STATUS' AND (
            (v_sort_direction = 'ASC' AND (filtered_index.status_rank,
              pg_catalog.lower(filtered_index.candidate_display_name), filtered_index.pay_batch_candidate_id) >
              ((p_cursor_json->>'last_status_rank')::integer,
               p_cursor_json->>'last_candidate_name',
               (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))
            OR (v_sort_direction = 'DESC' AND (filtered_index.status_rank,
              pg_catalog.lower(filtered_index.candidate_display_name), filtered_index.pay_batch_candidate_id) <
              ((p_cursor_json->>'last_status_rank')::integer,
               p_cursor_json->>'last_candidate_name',
               (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))))
          OR (p_cursor_json IS NOT NULL AND v_sort_key = 'CANDIDATE' AND (
            (v_sort_direction = 'ASC' AND (pg_catalog.lower(filtered_index.candidate_display_name),
              filtered_index.pay_batch_candidate_id) >
              (p_cursor_json->>'last_candidate_name', (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))
            OR (v_sort_direction = 'DESC' AND (pg_catalog.lower(filtered_index.candidate_display_name),
              filtered_index.pay_batch_candidate_id) <
              (p_cursor_json->>'last_candidate_name', (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))))
          OR (p_cursor_json IS NOT NULL AND v_sort_key = 'AMOUNT' AND (
            (v_sort_direction = 'ASC' AND (filtered_index.original_payment_amount_pence,
              filtered_index.pay_batch_candidate_id) >
              ((p_cursor_json->>'last_amount_pence')::bigint,
               (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))
            OR (v_sort_direction = 'DESC' AND (filtered_index.original_payment_amount_pence,
              filtered_index.pay_batch_candidate_id) <
              ((p_cursor_json->>'last_amount_pence')::bigint,
               (p_cursor_json->>'last_pay_batch_candidate_id')::uuid))))
    ), page_keys AS MATERIALIZED (
        SELECT candidate_after_cursor.pay_batch_candidate_id
        FROM candidate_after_cursor
        ORDER BY
          CASE WHEN v_sort_key = 'STATUS' AND v_sort_direction = 'ASC' THEN status_rank END ASC,
          CASE WHEN v_sort_key = 'STATUS' AND v_sort_direction = 'DESC' THEN status_rank END DESC,
          CASE WHEN v_sort_key IN ('STATUS','CANDIDATE') AND v_sort_direction = 'ASC'
            THEN pg_catalog.lower(candidate_display_name) END ASC,
          CASE WHEN v_sort_key IN ('STATUS','CANDIDATE') AND v_sort_direction = 'DESC'
            THEN pg_catalog.lower(candidate_display_name) END DESC,
          CASE WHEN v_sort_key = 'AMOUNT' AND v_sort_direction = 'ASC' THEN original_payment_amount_pence END ASC,
          CASE WHEN v_sort_key = 'AMOUNT' AND v_sort_direction = 'DESC' THEN original_payment_amount_pence END DESC,
          CASE WHEN v_sort_direction = 'ASC' THEN pay_batch_candidate_id END ASC,
          CASE WHEN v_sort_direction = 'DESC' THEN pay_batch_candidate_id END DESC
        LIMIT p_limit + 1
    ), item_rollup AS (
        SELECT item_candidate.id AS pay_batch_candidate_id,
               pg_catalog.count(*)::integer AS original_item_count,
               pg_catalog.count(*) FILTER (
                   WHERE coalesce(batch_item.is_voided, false) IS NOT TRUE
               )::integer AS active_item_count,
               pg_catalog.bool_or(batch_item.pay_channel = 'PAYE') AS has_paye_item,
               pg_catalog.bool_or(batch_item.pay_channel <> 'PAYE') AS has_non_paye_item,
               pg_catalog.array_agg(DISTINCT batch_item.pay_bank_transfer_id)
                   FILTER (WHERE batch_item.pay_bank_transfer_id IS NOT NULL) AS transfer_ids
        FROM public.pay_batch_candidates AS item_candidate
        JOIN page_keys ON page_keys.pay_batch_candidate_id = item_candidate.id
        JOIN public.pay_batch_items AS batch_item
          ON batch_item.pay_batch_candidate_id = item_candidate.id
        WHERE item_candidate.pay_batch_id = p_pay_batch_id
        GROUP BY item_candidate.id
    ), correction_rollup AS (
        SELECT correction_item.pay_batch_candidate_id,
               pg_catalog.bool_or(
                   correction_item.status = 'APPLIED'
                   AND correction_item.correction_item_kind IN (
                       'PRE_BANK_CANCEL',
                       'NO_MONEY_UNWIND'
                   )
                ) AS has_applied_removal,
               pg_catalog.bool_or(
                   correction_item.status = 'APPLIED'
                   AND correction_item.correction_item_kind = 'NO_MONEY_UNWIND'
               ) AS has_applied_release,
               pg_catalog.bool_or(
                   correction_item.status = 'APPLIED'
                   AND correction_item.correction_item_kind = 'PRE_BANK_CANCEL'
               ) AS has_applied_cancel,
               pg_catalog.max(correction_item.applied_at_utc) AS removed_at_utc
        FROM public.pay_payment_correction_items AS correction_item
        JOIN page_keys ON page_keys.pay_batch_candidate_id = correction_item.pay_batch_candidate_id
        WHERE correction_item.pay_batch_id = p_pay_batch_id
        GROUP BY correction_item.pay_batch_candidate_id
    ), latest_removal_request AS (
        SELECT DISTINCT ON (correction_item.pay_batch_candidate_id)
               correction_item.pay_batch_candidate_id,
               correction_item.correction_request_id
        FROM public.pay_payment_correction_items AS correction_item
        JOIN page_keys ON page_keys.pay_batch_candidate_id = correction_item.pay_batch_candidate_id
        JOIN public.pay_payment_correction_requests AS request_row
          ON request_row.id = correction_item.correction_request_id
         AND request_row.pay_batch_id = correction_item.pay_batch_id
        WHERE correction_item.pay_batch_id = p_pay_batch_id
          AND correction_item.status = 'APPLIED'
          AND correction_item.correction_item_kind IN (
              'PRE_BANK_CANCEL',
              'NO_MONEY_UNWIND'
          )
        ORDER BY correction_item.pay_batch_candidate_id,
                 correction_item.applied_at_utc DESC NULLS LAST,
                 request_row.updated_at_utc DESC,
                 correction_item.correction_request_id DESC
    ), removed_amount_rollup AS (
        SELECT latest_removal.pay_batch_candidate_id,
               pg_catalog.sum(correction_item.source_amount) AS removed_frozen_source_amount,
               pg_catalog.sum(
                   coalesce(frozen_batch_item.amount_inc_vat, correction_item.amount_inc_vat)
               ) AS removed_frozen_payable_amount,
               pg_catalog.max(member_row.active_amount) AS removed_reviewed_payment_amount
        FROM latest_removal_request AS latest_removal
        JOIN public.pay_payment_correction_items AS correction_item
          ON correction_item.correction_request_id = latest_removal.correction_request_id
         AND correction_item.pay_batch_candidate_id = latest_removal.pay_batch_candidate_id
         AND correction_item.status = 'APPLIED'
         AND correction_item.correction_item_kind IN (
             'PRE_BANK_CANCEL',
              'NO_MONEY_UNWIND'
          )
        LEFT JOIN public.pay_batch_items AS frozen_batch_item
          ON frozen_batch_item.id = correction_item.pay_batch_item_id
        LEFT JOIN public.pay_payment_correction_request_candidates AS member_row
          ON member_row.correction_request_id = latest_removal.correction_request_id
         AND member_row.pay_batch_candidate_id = latest_removal.pay_batch_candidate_id
        GROUP BY latest_removal.pay_batch_candidate_id
    ), work_rollup AS (
        SELECT work_item.pay_batch_candidate_id,
               (pg_catalog.array_agg(work_item.status ORDER BY work_item.created_at_utc DESC, work_item.id DESC))[1]
                   AS latest_work_status,
               pg_catalog.max(work_item.attempt_count)::integer AS attempt_count,
               (pg_catalog.array_agg(work_item.last_error ORDER BY work_item.created_at_utc DESC, work_item.id DESC))[1]
                   AS last_error,
               (pg_catalog.array_agg(request_row.status ORDER BY work_item.created_at_utc DESC, work_item.id DESC))[1]
                   AS latest_request_status
        FROM public.pay_payment_correction_work_items AS work_item
        JOIN page_keys ON page_keys.pay_batch_candidate_id = work_item.pay_batch_candidate_id
        LEFT JOIN public.pay_payment_correction_requests AS request_row
          ON request_row.id = work_item.correction_request_id
        WHERE work_item.pay_batch_id = p_pay_batch_id
        GROUP BY work_item.pay_batch_candidate_id
    ), membership_history AS (
        SELECT DISTINCT ON (member_row.pay_batch_candidate_id)
               member_row.pay_batch_candidate_id,
               member_row.active_amount AS reviewed_payment_amount,
               request_row.status AS membership_request_status
        FROM public.pay_payment_correction_request_candidates AS member_row
        JOIN page_keys ON page_keys.pay_batch_candidate_id = member_row.pay_batch_candidate_id
        JOIN public.pay_payment_correction_requests AS request_row
          ON request_row.id = member_row.correction_request_id
        WHERE request_row.pay_batch_id = p_pay_batch_id
        ORDER BY
            member_row.pay_batch_candidate_id,
            CASE
                WHEN request_row.status IN ('APPLIED', 'APPLIED_WITH_BLOCKERS') THEN 0
                WHEN request_row.status IN ('PROCESSING', 'EXPANDED', 'AUTHORISED') THEN 1
                ELSE 2
            END,
            request_row.updated_at_utc DESC,
            request_row.id DESC
    ), provider_rollup AS (
        SELECT item_candidate.id AS pay_batch_candidate_id,
               pg_catalog.bool_or(
                   transfer_event.normalised_state IN ('COMPLETED', 'PAID', 'SETTLED')
               ) AS has_paid_evidence,
               pg_catalog.bool_or(
                   transfer_event.normalised_state IN (
                       'FAILED',
                       'REJECTED',
                       'CANCELLED',
                       'CONFIRMED_NOT_PAID'
                   )
               ) AS has_terminal_no_money,
               pg_catalog.bool_or(
                   transfer_event.normalised_state IN (
                       'UNKNOWN',
                       'PENDING',
                       'SUBMITTED',
                       'PROCESSING'
                   )
                   OR transfer_event.movement_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
               ) AS has_ambiguous_evidence,
               pg_catalog.max(transfer_event.event_time_utc) AS latest_event_time_utc
        FROM public.pay_batch_candidates AS item_candidate
        JOIN page_keys ON page_keys.pay_batch_candidate_id = item_candidate.id
        JOIN public.pay_batch_items AS provider_item
          ON provider_item.pay_batch_candidate_id = item_candidate.id
        LEFT JOIN public.pay_bank_transfer_events AS transfer_event
          ON transfer_event.pay_bank_transfer_id = provider_item.pay_bank_transfer_id
        WHERE item_candidate.pay_batch_id = p_pay_batch_id
        GROUP BY item_candidate.id
    ), transfer_rollup AS (
        SELECT item_candidate.id AS pay_batch_candidate_id,
               pg_catalog.bool_or(
                   bank_transfer.status IN ('FAILED', 'CANCELLED')
                   OR bank_transfer.rail_state IN ('FAILED', 'CANCELLED')
               ) AS transfer_failed,
               pg_catalog.bool_or(
                   bank_transfer.status IN ('SUBMITTED', 'PROCESSING', 'PENDING')
                   OR bank_transfer.rail_state IN ('SUBMITTED', 'PROCESSING', 'PENDING')
               ) AS transfer_pending,
               pg_catalog.count(DISTINCT bank_transfer.transfer_group_key)
                   FILTER (WHERE bank_transfer.transfer_group_key IS NOT NULL)::integer
                   AS shared_instruction_count
        FROM public.pay_batch_candidates AS item_candidate
        JOIN page_keys ON page_keys.pay_batch_candidate_id = item_candidate.id
        JOIN public.pay_batch_items AS transfer_item
          ON transfer_item.pay_batch_candidate_id = item_candidate.id
        LEFT JOIN public.pay_bank_transfers AS bank_transfer
          ON bank_transfer.id = transfer_item.pay_bank_transfer_id
        WHERE item_candidate.pay_batch_id = p_pay_batch_id
        GROUP BY item_candidate.id
    ), base AS (
        SELECT candidate_row.id AS pay_batch_candidate_id,
               candidate_row.candidate_id,
               candidate_row.candidate_display_name,
               candidate_row.net_bank_amount,
               pg_catalog.round(
                   coalesce(
                       CASE
                           WHEN coalesce(correction_rollup.has_applied_removal, false)
                             OR coalesce(item_rollup.active_item_count, 0) = 0
                           THEN membership_history.reviewed_payment_amount
                           ELSE NULL::numeric
                       END,
                       status_index.reviewed_payment_amount,
                       0
                   ) * 100
               )::bigint
                   AS original_payment_amount_pence,
               CASE
                   WHEN coalesce(correction_rollup.has_applied_removal, false)
                     OR coalesce(item_rollup.active_item_count, 0) = 0
                   THEN pg_catalog.round(
                       coalesce(removed_amount_rollup.removed_frozen_source_amount, 0) * 100
                   )::bigint
                   ELSE NULL::bigint
               END AS cancelled_gross_base_amount_pence,
               CASE
                   WHEN coalesce(correction_rollup.has_applied_removal, false)
                     OR coalesce(item_rollup.active_item_count, 0) = 0
                   THEN pg_catalog.round(
                       coalesce(
                           removed_amount_rollup.removed_frozen_payable_amount,
                           removed_amount_rollup.removed_reviewed_payment_amount,
                           0
                       ) * 100
                   )::bigint
                   ELSE NULL::bigint
               END AS cancelled_payable_amount_pence,
               CASE
                   WHEN coalesce(correction_rollup.has_applied_removal, false)
                     OR coalesce(item_rollup.active_item_count, 0) = 0
                   THEN pg_catalog.round(
                       coalesce(
                           removed_amount_rollup.removed_reviewed_payment_amount,
                           membership_history.reviewed_payment_amount,
                           candidate_row.net_bank_amount,
                           0
                       ) * 100
                   )::bigint
                   ELSE NULL::bigint
               END AS cancelled_bank_amount_pence,
               coalesce(item_rollup.active_item_count, 0) AS active_item_count,
               coalesce(item_rollup.has_paye_item, false) AS has_paye_item,
               coalesce(item_rollup.has_non_paye_item, false) AS has_non_paye_item,
               CASE
                   WHEN coalesce(item_rollup.has_paye_item, false)
                    AND coalesce(item_rollup.has_non_paye_item, false) THEN 'MIXED'
                   WHEN coalesce(item_rollup.has_paye_item, false) THEN 'PAYE'
                   ELSE 'UMBRELLA'
               END AS pay_channel,
               coalesce(correction_rollup.has_applied_removal, false)
                   OR coalesce(item_rollup.active_item_count, 0) = 0 AS removed,
               coalesce(correction_rollup.has_applied_release, false) AS released,
               coalesce(correction_rollup.has_applied_cancel, false) AS cancelled,
                status_index.paid_or_settled,
                status_index.terminal_no_money,
                status_index.ambiguous,
                status_index.has_resolution_context,
                status_index.canonical_provider_state,
                status_index.complete_candidate_instruction_scope,
                status_index.release_failed_payment_eligible,
                 status_index.pre_provider_cancel_eligible,
               status_index.latest_work_status,
               coalesce(work_rollup.attempt_count, 0) AS attempt_count,
               work_rollup.last_error,
               coalesce(
                   work_rollup.latest_request_status,
                   membership_history.membership_request_status
               ) AS latest_request_status,
               provider_rollup.latest_event_time_utc,
               coalesce(transfer_rollup.shared_instruction_count, 0) AS shared_instruction_count
         FROM public.pay_batch_candidates AS candidate_row
         JOIN page_keys ON page_keys.pay_batch_candidate_id = candidate_row.id
         JOIN candidate_classified_index AS status_index
           ON status_index.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN item_rollup ON item_rollup.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN correction_rollup ON correction_rollup.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN removed_amount_rollup ON removed_amount_rollup.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN work_rollup ON work_rollup.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN membership_history ON membership_history.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN provider_rollup ON provider_rollup.pay_batch_candidate_id = candidate_row.id
        LEFT JOIN transfer_rollup ON transfer_rollup.pay_batch_candidate_id = candidate_row.id
        WHERE candidate_row.pay_batch_id = p_pay_batch_id
    ), classified AS (
        SELECT base.*,
               CASE
                   WHEN base.removed AND base.released THEN 'RELEASED'
                   WHEN base.removed THEN 'CANCELLED'
                    WHEN base.paid_or_settled THEN 'SETTLED'
                    WHEN v_batch.status = 'DRAFT' AND base.pre_provider_cancel_eligible THEN 'ACTIVE'
                    WHEN base.latest_work_status = 'BLOCKED' THEN 'BLOCKED'
                    WHEN base.latest_work_status IN ('FAILED_FINAL', 'FAILED_RETRYABLE') THEN 'FAILED'
                    WHEN base.canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'BLOCKED'
                     WHEN base.release_failed_payment_eligible THEN 'NOT_PAID'
                    WHEN base.ambiguous THEN 'AMBIGUOUS'
                    WHEN base.terminal_no_money THEN 'BLOCKED'
                    ELSE 'ACTIVE'
                END AS payment_display_state,
                  CASE
                      WHEN base.removed OR base.paid_or_settled THEN ARRAY[]::text[]
                      WHEN v_batch_terminal THEN ARRAY[]::text[]
                      WHEN v_batch.status = 'DRAFT' AND base.pre_provider_cancel_eligible
                        THEN ARRAY['DRAFT_CANCEL']::text[]
                      WHEN base.latest_work_status IN ('BLOCKED', 'FAILED_FINAL', 'FAILED_RETRYABLE') THEN ARRAY[]::text[]
                      WHEN base.canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN ARRAY[]::text[]
                      WHEN v_batch.status = 'DRAFT' THEN ARRAY[]::text[]
                     WHEN base.release_failed_payment_eligible THEN ARRAY['RELEASE_FAILED_PAYMENT']::text[]
                    WHEN base.ambiguous AND base.has_resolution_context THEN ARRAY['RESOLVE_PAYMENT_STATUS']::text[]
                    WHEN base.ambiguous THEN ARRAY[]::text[]
                    WHEN base.terminal_no_money THEN ARRAY[]::text[]
                    WHEN base.pre_provider_cancel_eligible THEN ARRAY['CANCEL_PAYMENT']::text[]
                    ELSE ARRAY[]::text[]
               END AS available_actions,
               CASE
                   WHEN base.removed OR base.paid_or_settled THEN 0::bigint
                   ELSE base.original_payment_amount_pence
               END AS active_payment_amount_pence,
               CASE
                    WHEN base.removed THEN 70
                    WHEN base.paid_or_settled THEN 60
                    WHEN v_batch.status = 'DRAFT' AND base.pre_provider_cancel_eligible THEN 10
                    WHEN base.latest_work_status = 'BLOCKED' THEN 50
                    WHEN base.canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 50
                     WHEN base.release_failed_payment_eligible THEN 40
                    WHEN base.ambiguous THEN 30
                    WHEN base.terminal_no_money THEN 50
                    ELSE 10
               END AS status_rank
        FROM base
    ), filtered AS (
        SELECT classified.*
        FROM classified
        WHERE (
                NULLIF(pg_catalog.btrim(v_filter ->> 'search'), '') IS NULL
                OR pg_catalog.lower(classified.candidate_display_name)
                    LIKE '%' || pg_catalog.lower(pg_catalog.btrim(v_filter ->> 'search')) || '%'
              )
          AND (
                NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'status')), '') IS NULL
                OR classified.payment_display_state = pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'status'))
              )
          AND (
                NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'action')), '') IS NULL
                OR pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'action')) = ANY(classified.available_actions)
              )
          AND (
                coalesce((v_filter ->> 'actionable_only')::boolean, false) IS NOT TRUE
                OR pg_catalog.cardinality(classified.available_actions) > 0
              )
          AND (
                NULLIF(pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'pay_channel')), '') IS NULL
                OR (
                    pg_catalog.upper(pg_catalog.btrim(v_filter ->> 'pay_channel')) = 'PAYE'
                    AND classified.has_paye_item
                )
              )
          AND NOT EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements_text(
                    coalesce(v_filter -> 'excluded_candidate_tokens', '[]'::jsonb)
                ) AS excluded_token(token_value)
                WHERE excluded_token.token_value = classified.pay_batch_candidate_id::text
              )
          AND (
                NOT (v_filter ? 'included_candidate_tokens')
                OR EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_array_elements_text(
                        v_filter -> 'included_candidate_tokens'
                    ) AS included_token(token_value)
                    WHERE included_token.token_value = classified.pay_batch_candidate_id::text
                )
              )
    ), after_cursor AS (
        SELECT filtered.*
        FROM filtered
        WHERE p_cursor_json IS NULL
           OR (
               v_sort_key = 'STATUS'
               AND (
                   (v_sort_direction = 'ASC' AND (
                       filtered.status_rank,
                       pg_catalog.lower(filtered.candidate_display_name),
                       filtered.pay_batch_candidate_id
                   ) > (
                       (p_cursor_json ->> 'last_status_rank')::integer,
                       p_cursor_json ->> 'last_candidate_name',
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
                   OR (v_sort_direction = 'DESC' AND (
                       filtered.status_rank,
                       pg_catalog.lower(filtered.candidate_display_name),
                       filtered.pay_batch_candidate_id
                   ) < (
                       (p_cursor_json ->> 'last_status_rank')::integer,
                       p_cursor_json ->> 'last_candidate_name',
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
               )
           )
           OR (
               p_cursor_json IS NOT NULL
               AND v_sort_key = 'CANDIDATE'
               AND (
                   (v_sort_direction = 'ASC' AND (
                       pg_catalog.lower(filtered.candidate_display_name),
                       filtered.pay_batch_candidate_id
                   ) > (
                       p_cursor_json ->> 'last_candidate_name',
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
                   OR (v_sort_direction = 'DESC' AND (
                       pg_catalog.lower(filtered.candidate_display_name),
                       filtered.pay_batch_candidate_id
                   ) < (
                       p_cursor_json ->> 'last_candidate_name',
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
               )
           )
           OR (
               p_cursor_json IS NOT NULL
               AND v_sort_key = 'AMOUNT'
               AND (
                   (v_sort_direction = 'ASC' AND (
                       filtered.original_payment_amount_pence,
                       filtered.pay_batch_candidate_id
                   ) > (
                       (p_cursor_json ->> 'last_amount_pence')::bigint,
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
                   OR (v_sort_direction = 'DESC' AND (
                       filtered.original_payment_amount_pence,
                       filtered.pay_batch_candidate_id
                   ) < (
                       (p_cursor_json ->> 'last_amount_pence')::bigint,
                       (p_cursor_json ->> 'last_pay_batch_candidate_id')::uuid
                   ))
               )
           )
    ), paged AS (
        SELECT after_cursor.*
        FROM after_cursor
        ORDER BY
            CASE WHEN v_sort_key = 'STATUS' AND v_sort_direction = 'ASC' THEN after_cursor.status_rank END ASC,
            CASE WHEN v_sort_key = 'STATUS' AND v_sort_direction = 'DESC' THEN after_cursor.status_rank END DESC,
            CASE WHEN v_sort_key IN ('STATUS', 'CANDIDATE') AND v_sort_direction = 'ASC'
                THEN pg_catalog.lower(after_cursor.candidate_display_name) END ASC,
            CASE WHEN v_sort_key IN ('STATUS', 'CANDIDATE') AND v_sort_direction = 'DESC'
                THEN pg_catalog.lower(after_cursor.candidate_display_name) END DESC,
            CASE WHEN v_sort_key = 'AMOUNT' AND v_sort_direction = 'ASC'
                THEN after_cursor.original_payment_amount_pence END ASC,
            CASE WHEN v_sort_key = 'AMOUNT' AND v_sort_direction = 'DESC'
                THEN after_cursor.original_payment_amount_pence END DESC,
            CASE WHEN v_sort_direction = 'ASC' THEN after_cursor.pay_batch_candidate_id END ASC,
            CASE WHEN v_sort_direction = 'DESC' THEN after_cursor.pay_batch_candidate_id END DESC
        LIMIT p_limit + 1
    ), page_rows AS (
        SELECT paged.*,
               pg_catalog.row_number() OVER () AS page_ordinal
        FROM paged
        LIMIT p_limit
    )
    SELECT
        coalesce(
            pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'row_key', page_rows.pay_batch_candidate_id::text,
                    'candidate_token', page_rows.pay_batch_candidate_id::text,
                    'candidate/payee_display', page_rows.candidate_display_name,
                    'pay_channel', page_rows.pay_channel,
                    'original_amount', (page_rows.original_payment_amount_pence::numeric / 100)::numeric(14,2),
                    'active_amount', (page_rows.active_payment_amount_pence::numeric / 100)::numeric(14,2),
                    'display_status', page_rows.payment_display_state,
                    'is_active', NOT page_rows.removed AND NOT page_rows.paid_or_settled,
                    'is_cancelled', page_rows.removed AND NOT page_rows.released,
                    'is_paid', page_rows.paid_or_settled,
                    'is_settled', page_rows.paid_or_settled,
                    'is_not_paid', page_rows.release_failed_payment_eligible AND NOT page_rows.removed,
                    'is_released', page_rows.removed AND page_rows.released,
                    'eligible_action_codes', page_rows.available_actions,
                    'plain_blocker', CASE
                        WHEN page_rows.paid_or_settled THEN 'Paid or settled payments cannot be cancelled.'
                        WHEN page_rows.payment_display_state = 'AMBIGUOUS' THEN 'The bank payment status must be resolved before continuing.'
                        WHEN NOT (
                               v_batch.status = 'DRAFT'
                               AND coalesce(page_rows.pre_provider_cancel_eligible, false)
                             )
                             AND page_rows.latest_work_status = 'BLOCKED'
                            THEN 'This payment could not be changed because its status or source ownership changed.'
                        WHEN NOT (
                               v_batch.status = 'DRAFT'
                               AND coalesce(page_rows.pre_provider_cancel_eligible, false)
                             )
                             AND page_rows.latest_work_status IN ('FAILED_FINAL', 'FAILED_RETRYABLE')
                            THEN 'CloudTMS could not complete this payment change.'
                        WHEN page_rows.canonical_provider_state = 'PROVIDER_OUTAGE_RETRY_LATER'
                            THEN 'The bank is temporarily unavailable. This payment cannot be changed until provider status is rechecked.'
                        WHEN page_rows.terminal_no_money AND page_rows.release_failed_payment_eligible IS NOT TRUE
                            THEN 'This failed payment cannot be released until its complete payment scope and evidence are safe.'
                        WHEN page_rows.payment_display_state = 'ACTIVE'
                             AND v_batch.status <> 'DRAFT'
                             AND page_rows.pre_provider_cancel_eligible IS NOT TRUE
                            THEN 'This payment cannot be cancelled until its complete payment scope and evidence are safe.'
                        ELSE NULL::text
                    END,
                    'correction_request_status', page_rows.latest_request_status,
                    'correction_work_status', page_rows.latest_work_status,
                    'progress_display', CASE
                        WHEN page_rows.latest_work_status IN ('PENDING', 'PROCESSING', 'FAILED_RETRYABLE') THEN 'Cancellation is in progress'
                        WHEN page_rows.payment_display_state = 'CANCELLED' THEN 'Cancellation complete'
                        WHEN page_rows.payment_display_state = 'RELEASED' THEN 'Release complete'
                        ELSE NULL::text
                    END,
                    'snapshot_token', v_snapshot_token,
                    'resolution_context', CASE
                        WHEN 'RESOLVE_PAYMENT_STATUS' = ANY(page_rows.available_actions) THEN
                            pg_catalog.jsonb_build_object(
                                'version', 1,
                                'candidate_token', page_rows.pay_batch_candidate_id::text,
                                'active_batch_scope_hash', v_active_batch_scope_hash,
                                'context_token', private.pay_payment_correction_sha256_v1(
                                    pg_catalog.jsonb_build_object(
                                        'version', 1,
                                        'pay_batch_id', p_pay_batch_id,
                                        'candidate_token', page_rows.pay_batch_candidate_id,
                                        'active_batch_scope_hash', v_active_batch_scope_hash
                                    )
                                )
                            )
                        ELSE NULL::jsonb
                    END,
                    'stable_sort_cursor', pg_catalog.jsonb_build_object(
                        'status_rank', page_rows.status_rank,
                        'candidate_name', pg_catalog.lower(page_rows.candidate_display_name),
                        'amount_pence', page_rows.original_payment_amount_pence,
                        'pay_batch_candidate_id', page_rows.pay_batch_candidate_id
                    ),
                    'pay_batch_candidate_id', page_rows.pay_batch_candidate_id,
                    'selection_token', page_rows.pay_batch_candidate_id::text,
                    'candidate_id', page_rows.candidate_id,
                    'candidate_display_name', page_rows.candidate_display_name,
                    'payment_display_state', page_rows.payment_display_state,
                    'release_failed_payment_eligible', page_rows.release_failed_payment_eligible,
                    'pre_provider_cancel_eligible', page_rows.pre_provider_cancel_eligible,
                    'draft_cancel_eligible', v_batch.status = 'DRAFT' AND page_rows.pre_provider_cancel_eligible,
                    'complete_candidate_instruction_scope', page_rows.complete_candidate_instruction_scope,
                    'available_actions', page_rows.available_actions,
                    'original_payment_amount_pence', page_rows.original_payment_amount_pence,
                    'active_payment_amount_pence', page_rows.active_payment_amount_pence,
                    'cancelled_gross_base_amount_pence', page_rows.cancelled_gross_base_amount_pence,
                    'cancelled_payable_amount_pence', page_rows.cancelled_payable_amount_pence,
                    'cancelled_bank_amount_pence', page_rows.cancelled_bank_amount_pence,
                    'include_in_active_overview', NOT page_rows.removed,
                    'include_in_active_paye_schedule', page_rows.has_paye_item AND NOT page_rows.removed,
                    'active_item_count', page_rows.active_item_count,
                    'work_status', page_rows.latest_work_status,
                    'attempt_count', page_rows.attempt_count,
                    'failure_reason', CASE
                        WHEN NOT (
                               v_batch.status = 'DRAFT'
                               AND coalesce(page_rows.pre_provider_cancel_eligible, false)
                             )
                             AND page_rows.latest_work_status IN ('BLOCKED', 'FAILED_FINAL', 'FAILED_RETRYABLE')
                            THEN CASE
                                WHEN page_rows.latest_work_status = 'BLOCKED' THEN 'This payment could not be changed because its status or source ownership changed.'
                                ELSE 'CloudTMS could not complete this payment change.'
                            END
                        ELSE NULL
                    END,
                    'shared_instruction', page_rows.shared_instruction_count > 0,
                    'latest_evidence_at_utc', page_rows.latest_event_time_utc
                )
                ORDER BY page_rows.page_ordinal
            ),
            '[]'::jsonb
        ),
        pg_catalog.count(*)::integer,
        (
            SELECT pg_catalog.count(*)::integer
            FROM candidate_filtered_index
        ),
        (
            SELECT pg_catalog.count(*)::integer
            FROM candidate_filtered_index
            WHERE pg_catalog.cardinality(candidate_filtered_index.available_actions) > 0
        ),
        (
            SELECT coalesce(pg_catalog.sum(candidate_filtered_index.original_payment_amount_pence), 0)::bigint
            FROM candidate_filtered_index
            WHERE pg_catalog.cardinality(candidate_filtered_index.available_actions) > 0
        ),
        (
            SELECT pg_catalog.count(*)::integer
            FROM candidate_classified_index
            WHERE NOT candidate_classified_index.removed
        ),
        (
            SELECT coalesce(pg_catalog.sum(
                CASE WHEN candidate_classified_index.removed
                     THEN 0::bigint
                     ELSE candidate_classified_index.original_payment_amount_pence END
            ), 0)::bigint
            FROM candidate_classified_index
        ),
        (
            SELECT coalesce(pg_catalog.sum(candidate_classified_index.original_payment_amount_pence), 0)::bigint
            FROM candidate_classified_index
        ),
        (
            SELECT pg_catalog.count(*)::integer
            FROM candidate_classified_index
            WHERE candidate_classified_index.has_paye_item
              AND NOT candidate_classified_index.removed
        ),
        (
            SELECT coalesce(pg_catalog.sum(candidate_classified_index.original_payment_amount_pence), 0)::bigint
            FROM candidate_classified_index
            WHERE candidate_classified_index.has_paye_item
              AND NOT candidate_classified_index.removed
        ),
        (
            SELECT pg_catalog.to_jsonb(last_page_row)
            FROM page_rows AS last_page_row
            ORDER BY last_page_row.page_ordinal DESC
            LIMIT 1
        ),
        (
            SELECT pg_catalog.count(*) > p_limit
            FROM paged
        )
    INTO
        v_rows,
        v_row_count,
        v_total_matching_count,
        v_eligible_matching_count,
        v_selected_amount_pence_available,
        v_active_overview_candidate_count,
        v_active_overview_amount_pence,
        v_original_overview_amount_pence,
        v_active_paye_schedule_line_count,
        v_active_paye_schedule_amount_pence,
        v_last_row,
        v_has_more
    FROM page_rows;

    IF v_last_row IS NOT NULL AND v_has_more THEN
        v_next_cursor_json := pg_catalog.jsonb_build_object(
            'snapshot_token', v_snapshot_token,
            'sort_key', v_sort_key,
            'sort_direction', v_sort_direction,
            'last_status_rank', (v_last_row ->> 'status_rank')::integer,
            'last_candidate_name', pg_catalog.lower(v_last_row ->> 'candidate_display_name'),
            'last_amount_pence', (v_last_row ->> 'original_payment_amount_pence')::bigint,
            'last_pay_batch_candidate_id', v_last_row ->> 'pay_batch_candidate_id',
            'previous_cursor_json', p_cursor_json
        );
    END IF;

    v_previous_cursor_json := CASE
        WHEN p_cursor_json IS NULL THEN NULL
        ELSE p_cursor_json -> 'previous_cursor_json'
    END;

    SELECT pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'id', request_row.id,
        'correction_request_id', request_row.id,
        'status', request_row.status,
        'request_status', request_row.status,
        'requested_at_utc', request_row.requested_at_utc,
        'updated_at_utc', request_row.updated_at_utc,
        'is_active', request_row.status IN (
            'PLANNING', 'PLANNED', 'REQUESTED', 'AWAITING_AUTHORISATION',
            'AUTHORISED', 'EXPANDED', 'PROCESSING'
        ),
        'is_terminal', request_row.status IN (
            'APPLIED', 'APPLIED_WITH_BLOCKERS', 'BLOCKED', 'FAILED',
            'REJECTED', 'CANCELLED'
        ),
        'user_title', CASE
            WHEN request_row.status IN (
                'PLANNING', 'PLANNED', 'REQUESTED', 'AWAITING_AUTHORISATION',
                'AUTHORISED', 'EXPANDED', 'PROCESSING'
            ) THEN 'Payment cancellation in progress'
            ELSE 'Latest payment cancellation'
        END,
        'request_kind', COALESCE(
            NULLIF(request_row.selection_json->>'requested_action', ''),
            NULLIF(request_row.plan_json->>'requested_action', ''),
            request_row.correction_kind
        )
    ))
    INTO v_latest_correction_request
    FROM public.pay_payment_correction_requests AS request_row
    WHERE request_row.pay_batch_id = p_pay_batch_id
    ORDER BY
        CASE
            WHEN request_row.status IN (
                'PLANNING', 'PLANNED', 'REQUESTED', 'AWAITING_AUTHORISATION',
                'AUTHORISED', 'EXPANDED', 'PROCESSING'
            ) THEN 0
            ELSE 1
        END,
        request_row.updated_at_utc DESC,
        request_row.id DESC
    LIMIT 1;

    RETURN pg_catalog.jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id,
        'snapshot_token', v_snapshot_token,
        'explicit_snapshot_token', v_explicit_snapshot_token,
        'active_batch_scope_hash', v_active_batch_scope_hash,
        'sort_key', v_sort_key,
        'sort_direction', v_sort_direction,
        'page_size', p_limit,
        'row_count', v_row_count,
        'has_more', v_has_more,
        'total_matching_count', v_total_matching_count,
        'eligible_matching_count', v_eligible_matching_count,
        'selected_amount_pence_available', v_selected_amount_pence_available,
        'active_overview_candidate_count', v_active_overview_candidate_count,
        'active_overview_amount_pence', v_active_overview_amount_pence,
        'original_overview_amount_pence', v_original_overview_amount_pence,
        'active_paye_schedule_line_count', v_active_paye_schedule_line_count,
        'active_paye_schedule_amount_pence', v_active_paye_schedule_amount_pence,
        'latest_correction_request', v_latest_correction_request,
        'latest_correction_request_id', v_latest_correction_request->>'id',
        'rows', v_rows,
        'next_cursor_json', v_next_cursor_json,
        'previous_cursor_json', v_previous_cursor_json,
        'page_label', CASE
            WHEN v_total_matching_count = 0 THEN '0 of 0'
            ELSE 'Showing ' || v_row_count::text || ' of ' || v_total_matching_count::text
        END,
        'code', 'PAYMENT_STATUS_PAGE_OK',
        'message', NULL,
        'continuation', pg_catalog.jsonb_build_object(
            'required', false,
            'operation_id', NULL,
            'operation_type', NULL,
            'pay_batch_id', p_pay_batch_id,
            'root_operation_id', NULL,
            'phase', NULL,
            'run_after_utc', NULL,
            'reason', 'STATUS_READ_ONLY',
            'successor_relation', 'NONE',
            'requires_user_action', false,
            'terminal', true
        )
    );
END
$function$;

-- pay_batch_populate_candidate_summaries(uuid,text,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_populate_candidate_summaries(p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_now_utc timestamptz := now();
  v_stage text := NULL;
  v_rows_upd_candidates_summaries integer := 0;
  v_rows_inserted_summaries integer := 0;
  v_rows_failed_summaries integer := 0;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;
  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct selected_preview_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row;
  END IF;


v_stage := 'STAGE_18_POPULATE_CANDIDATE_SUMMARIES';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with
  sums as (
    select
      pbc.id as pay_batch_candidate_id,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type not in ('OVERPAYMENT_RECOVERY', 'LOAN_REPAYMENT', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_PAYOUT', 'LOAN_PAYOUT', 'DEBT_CREATED')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type <> 'DEBT_CREATED'
          then pbi.amount_inc_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_inc,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('GROSS_ADD','GROSS_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as gross_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('NET_ADD','NET_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as net_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'OVERPAYMENT_RECOVERY'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as overpayment_recovery_taken_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'LOAN_REPAYMENT'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as loan_repayment_taken_ex

    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
    group by pbc.id
  ),
  paye_net as (
    select
      pni.pay_batch_candidate_id,
      pni.net_amount::numeric(12,2) as net_amount
    from public.pay_batch_paye_net_inputs pni
  )
  update public.pay_batch_candidates pbc
  set
    awaiting_net_amount = (
      (v_scope = 'PAYE')
      and not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni2
        where pni2.pay_batch_candidate_id = pbc.id
      )
    ),

    gross_preview = case
      when (v_scope = 'PAYE') then round(coalesce(sums.earnings_ex, 0) + coalesce(sums.gross_adjustments_ex_sum, 0), 2)::numeric(12,2)
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    overpayment_recovery_taken = sums.overpayment_recovery_taken_ex,
    loan_repayment_taken = sums.loan_repayment_taken_ex,

    net_bank_amount = case
      when (v_scope = 'PAYE') then
        case
          when (
            (v_scope = 'PAYE')
            and not exists (
              select 1
              from public.pay_batch_paye_net_inputs pni3
              where pni3.pay_batch_candidate_id = pbc.id
            )
          ) then null
          else greatest(
            round(coalesce(pn.net_amount, 0) + coalesce(sums.net_adjustments_ex_sum, 0), 2),
            0
          )::numeric(12,2)
        end
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    mismatch_settlement_choice = null,
    updated_at = v_now_utc
  from sums
  left join paye_net pn
    on pn.pay_batch_candidate_id = sums.pay_batch_candidate_id
  where pbc.id = sums.pay_batch_candidate_id
    and pbc.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids));

  get diagnostics v_rows_upd_candidates_summaries = row_count;

  

  PERFORM public.pay_batch_display_summary_refresh(v_batch_id);

  PERFORM public.banking_pay_batch_signal_touch(
    p_pay_batch_id => v_batch_id,
    p_change_reason => 'CANDIDATE_SUMMARIES_UPDATED',
    p_change_source => 'pay_batch_populate_candidate_summaries',
    p_change_scope_json => jsonb_build_object(
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'candidate_ids', to_jsonb(COALESCE(v_candidate_ids, ARRAY[]::uuid[])),
      'pay_channel_scope', v_scope
    ),
    p_touch_payment_status => false,
    p_touch_correction_progress => false,
    p_touch_alerts => false,
    p_touch_overview => true
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'summaries_inserted', coalesce(v_rows_inserted_summaries, 0),
    'summaries_updated', coalesce(v_rows_upd_candidates_summaries, 0),
    'failed_count', coalesce(v_rows_failed_summaries, 0),
    'updated_candidate_rows', coalesce(v_rows_upd_candidates_summaries, 0)
  );
END;
$function$;

-- pay_batch_prepare(uuid,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_batch_prepare(p_pay_batch_id uuid, p_actor_user_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_freshness_result_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_summary_json jsonb := '{}'::jsonb;
  v_fresh_json jsonb := '{}'::jsonb;
  v_blockers_json jsonb := '[]'::jsonb;
  v_warnings_json jsonb := '[]'::jsonb;
  v_next_required_phase text := 'START_AUTHORISATION';
  v_ready boolean := false;
  v_is_stale boolean := false;
  v_batch_status text := NULL::text;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_mode text := 'STANDARD_BANK';
  v_execution_mode_raw text := NULL::text;
  v_is_local_manual_mode boolean := false;
  v_operation_input_json jsonb := '{}'::jsonb;
  v_manual_confirmation_mode text := NULL::text;
  v_csv_uploaded_confirmed boolean := false;
  v_csv_bank_confirm_ref text := NULL::text;
  v_external_settlement_comment text := NULL::text;
  v_payment_date_text text := NULL::text;
  v_operation_projection_scope text := NULL::text;
  v_operation_projection_proof_source text := NULL::text;
  v_operation_server_owned_projection_proof boolean := false;
  v_operation_global_paye_net_state_hash text := NULL::text;
  v_operation_global_bank_payment_projection_hash text := NULL::text;
  v_operation_scoped_paye_net_state_hash text := NULL::text;
  v_operation_scoped_bank_payment_projection_hash text := NULL::text;
  v_operation_global_missing_count integer := NULL::integer;
  v_operation_global_zero_count integer := NULL::integer;
  v_operation_global_positive_count integer := NULL::integer;
  v_operation_global_invalid_count integer := NULL::integer;
  v_operation_scoped_missing_count integer := NULL::integer;
  v_operation_scoped_zero_count integer := NULL::integer;
  v_operation_scoped_positive_count integer := NULL::integer;
  v_operation_scoped_positive_total numeric(14,2) := NULL::numeric;
  v_operation_scoped_invalid_count integer := NULL::integer;
  v_operation_bank_csv_generated boolean := false;
  v_operation_bank_csv_current boolean := false;
  v_operation_bank_csv_scope text := NULL::text;
  v_operation_bank_csv_paye_net_state_hash text := NULL::text;
  v_operation_bank_csv_bank_payment_projection_hash text := NULL::text;
  v_operation_bank_csv_row_count integer := NULL::integer;
  v_operation_bank_csv_total_amount numeric(14,2) := NULL::numeric;
  v_bank_csv_export_json jsonb := '{}'::jsonb;
  v_stored_csv_scope text := NULL::text;
  v_stored_csv_paye_net_state_hash text := NULL::text;
  v_stored_csv_bank_payment_projection_hash text := NULL::text;
  v_stored_csv_row_count integer := NULL::integer;
  v_stored_csv_total_amount numeric(14,2) := NULL::numeric;
  v_projection_proof_valid boolean := false;
  v_csv_proof_valid boolean := false;
  v_external_proof_valid boolean := false;
  v_mode_specific_proof_valid boolean := true;
  v_provider_scope_evidence_count integer := 0;
  v_provider_attempt_row_count integer := 0;
  v_provider_event_count integer := 0;
  v_provider_transfer_evidence_count integer := 0;
  v_provider_submit_chunk_count integer := 0;
  v_provider_boundary_evidence_count integer := 0;
  v_scope_item_transfer_link_mismatch_count integer := 0;
  v_scope_item_count_mismatch_count integer := 0;
  v_scope_item_amount_mismatch_count integer := 0;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_transfer_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_authorisation_ready_transfer_count integer := 0;
  v_unattempted_submit_eligible_transfer_count integer := 0;
  v_remaining_unattempted_submit_required integer := 0;
  v_provider_attempt_or_evidence_transfer_count integer := 0;
  v_provider_or_ambiguous_evidence_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_canonical_pending_status_transfer_count integer := 0;
  v_safe_local_cleanup_transfer_count integer := 0;
  v_unsafe_transfer_count integer := 0;
  v_scoped_failed_or_blocked_transfer_count integer := 0;
  v_scoped_blocked_transfer_count integer := 0;
  v_scoped_operation_scope_count integer := 0;
  v_scoped_scope_prepared_count integer := 0;
  v_scoped_scope_pending_count integer := 0;
  v_scoped_scope_failed_count integer := 0;
  v_scoped_scope_skipped_count integer := 0;
  v_scoped_scope_without_transfer_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_auth_request_retry_blocker_count integer := 0;
  v_all_scoped_operation_scopes_authorisation_ready boolean := false;
  v_pay_channel_scope text := 'ALL';
  v_failed_transfer_count integer := 0;
  v_blocked_transfer_count integer := 0;
  v_submitted_transfer_count integer := 0;
  v_awaiting_net_count integer := 0;
  v_blocker_count integer := 0;
  v_warning_count integer := 0;
  v_diff_sample jsonb := '[]'::jsonb;
  v_operation_mode boolean := false;
  v_expected_freshness_hash text := null;
  v_expected_freshness_scope_hash text := null;
  v_batch_freshness_hash text := null;
  v_batch_freshness_scope_hash text := null;
  v_batch_freshness_status text := null;
  v_batch_freshness_json jsonb := '{}'::jsonb;
  v_large_batch boolean := false;
  v_scope_amount_total numeric(14,2) := 0;
  v_transfer_amount_total numeric(14,2) := 0;
  v_scope_item_amount_total numeric(14,2) := 0;
  v_batch_item_amount_total numeric(14,2) := 0;
  v_scope_prepared_amount_mismatch_count integer := 0;
  v_scope_prepared_hash_missing_count integer := 0;
  v_scope_provider_not_ready_count integer := 0;
  v_scope_item_rollup_pending_count integer := 0;
  v_payout_instruction_missing_count integer := 0;
  v_transfer_identity_mismatch_count integer := 0;
  v_transfer_amount_mismatch_count integer := 0;
  v_transfer_currency_mismatch_count integer := 0;
  v_transfer_status_not_pending_count integer := 0;
  v_transfer_external_state_count integer := 0;
  v_transfer_proof_hash text := NULL::text;
  v_transfer_scope_hash text := NULL::text;
  v_transfer_proof_hash_mismatch_count integer := 0;
  v_local_manual_zero_only_scope boolean := false;
  v_display_summary_row public.pay_batch_display_summary%ROWTYPE;
  v_operation_progress_json jsonb := '{}'::jsonb;
  v_operation_freshness_summary_json jsonb := '{}'::jsonb;
  v_operation_transfer_proof_json jsonb := '{}'::jsonb;
  v_operation_prepare_proof_json jsonb := '{}'::jsonb;
  v_operation_proof_status text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('OPERATION_ADVANCE');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_prepare: pay_batch_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_prepare: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'ACTOR_USER_NOT_FOUND',
      'message', 'pay_batch_prepare: actor_user was not found or is inactive',
      'actor_user_id', p_actor_user_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_prepare: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  v_batch_status := upper(btrim(coalesce(v_batch_row.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  v_operation_mode := p_operation_id IS NOT NULL OR nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_batch_prepare: operation was not found',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_batch_prepare: operation belongs to another batch or is not bound to this batch',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_operation_input_json := COALESCE(v_operation_row.input_json, '{}'::jsonb);
    v_execution_mode_raw := UPPER(BTRIM(COALESCE(v_operation_input_json->>'execution_mode', '')));
    v_execution_mode := CASE
      WHEN v_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
      WHEN v_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
      WHEN v_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
      ELSE NULL::text
    END;

    IF v_execution_mode IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_EXECUTION_MODE_INVALID',
        'message', 'The durable payment execution mode is missing or unsupported.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'execution_mode_raw', NULLIF(v_execution_mode_raw, ''),
        'supported_execution_modes', jsonb_build_array('STANDARD_BANK', 'CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_is_local_manual_mode := v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT');

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_ACTOR_MISMATCH',
        'message', 'pay_batch_prepare: operation belongs to another actor',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_expected_freshness_hash := COALESCE(
      NULLIF(BTRIM(COALESCE(p_freshness_result_hash, '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_input_json->>'freshness_result_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_row.result_json #>> '{freshness,freshness_result_hash}', '')), '')
    );
    v_expected_freshness_scope_hash := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_row.progress_json->>'freshness_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_input_json->>'freshness_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_row.result_json #>> '{freshness,freshness_scope_hash}', '')), '')
    );
    v_pay_channel_scope := UPPER(BTRIM(COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_input_json->>'pay_channel_scope', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_input_json->>'payChannelScope', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_row.config_json->>'pay_channel_scope', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_row.config_json->>'payChannelScope', '')), ''),
      'ALL'
    )));
    IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'LOANS', 'ALL') THEN
      v_pay_channel_scope := 'ALL';
    END IF;

    v_manual_confirmation_mode := UPPER(NULLIF(BTRIM(COALESCE(v_operation_input_json->>'manual_confirmation_mode', '')), ''));
    v_csv_uploaded_confirmed := LOWER(BTRIM(COALESCE(v_operation_input_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_csv_bank_confirm_ref := NULLIF(BTRIM(COALESCE(v_operation_input_json->>'csv_bank_confirm_ref', '')), '');
    v_external_settlement_comment := NULLIF(BTRIM(COALESCE(v_operation_input_json->>'external_settlement_comment', '')), '');
    v_payment_date_text := NULLIF(BTRIM(COALESCE(v_operation_input_json->>'payment_date', '')), '');
    v_operation_projection_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'pay_channel_scope',
      v_operation_input_json->>'projection_scope',
      v_operation_input_json->>'scope',
      ''
    )), ''));
    v_operation_projection_proof_source := UPPER(NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'payment_projection_proof_source',
      v_operation_input_json->>'proof_source',
      ''
    )), ''));
    v_operation_server_owned_projection_proof := LOWER(BTRIM(COALESCE(v_operation_input_json->>'server_owned_payment_projection_proof', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_operation_global_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'global_paye_net_state_hash',
      v_operation_input_json->>'current_global_paye_net_state_hash',
      ''
    )), '');
    v_operation_global_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'global_bank_payment_projection_hash',
      v_operation_input_json->>'current_global_bank_payment_projection_hash',
      ''
    )), '');
    v_operation_scoped_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'scoped_paye_net_state_hash',
      v_operation_input_json->>'current_scoped_paye_net_state_hash',
      v_operation_input_json->>'paye_net_state_hash',
      v_operation_input_json->>'current_paye_net_state_hash',
      ''
    )), '');
    v_operation_scoped_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'scoped_bank_payment_projection_hash',
      v_operation_input_json->>'current_scoped_bank_payment_projection_hash',
      v_operation_input_json->>'bank_payment_projection_hash',
      v_operation_input_json->>'current_bank_payment_projection_hash',
      ''
    )), '');

    IF COALESCE(v_operation_input_json->>'global_missing_explicit_paye_input_count', v_operation_input_json->>'missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_operation_global_missing_count := COALESCE(v_operation_input_json->>'global_missing_explicit_paye_input_count', v_operation_input_json->>'missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'global_explicit_zero_count', v_operation_input_json->>'explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_operation_global_zero_count := COALESCE(v_operation_input_json->>'global_explicit_zero_count', v_operation_input_json->>'explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'global_positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_operation_global_positive_count := (v_operation_input_json->>'global_positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'global_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_operation_global_invalid_count := (v_operation_input_json->>'global_invalid_payment_row_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'scoped_missing_explicit_paye_input_count', '') ~ '^[0-9]+$' THEN
      v_operation_scoped_missing_count := (v_operation_input_json->>'scoped_missing_explicit_paye_input_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'scoped_explicit_zero_count', '') ~ '^[0-9]+$' THEN
      v_operation_scoped_zero_count := (v_operation_input_json->>'scoped_explicit_zero_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'scoped_positive_bank_payment_count', v_operation_input_json->>'positive_bank_payment_count', '') ~ '^[0-9]+$' THEN
      v_operation_scoped_positive_count := COALESCE(v_operation_input_json->>'scoped_positive_bank_payment_count', v_operation_input_json->>'positive_bank_payment_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'scoped_positive_bank_payment_total', v_operation_input_json->>'positive_bank_payment_total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_operation_scoped_positive_total := ROUND(COALESCE(v_operation_input_json->>'scoped_positive_bank_payment_total', v_operation_input_json->>'positive_bank_payment_total')::numeric, 2)::numeric(14,2);
    END IF;
    IF COALESCE(v_operation_input_json->>'scoped_invalid_payment_row_count', '') ~ '^[0-9]+$' THEN
      v_operation_scoped_invalid_count := (v_operation_input_json->>'scoped_invalid_payment_row_count')::integer;
    END IF;

    v_operation_bank_csv_generated := LOWER(BTRIM(COALESCE(v_operation_input_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_operation_bank_csv_current := LOWER(BTRIM(COALESCE(v_operation_input_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_operation_bank_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(v_operation_input_json->>'bank_csv_scope', '')), ''));
    v_operation_bank_csv_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'bank_csv_scoped_paye_net_state_hash',
      v_operation_input_json->>'bank_csv_paye_net_state_hash',
      ''
    )), '');
    v_operation_bank_csv_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_operation_input_json->>'bank_csv_scoped_bank_payment_projection_hash',
      v_operation_input_json->>'bank_csv_bank_payment_projection_hash',
      ''
    )), '');
    IF COALESCE(v_operation_input_json->>'bank_csv_row_count', '') ~ '^[0-9]+$' THEN
      v_operation_bank_csv_row_count := (v_operation_input_json->>'bank_csv_row_count')::integer;
    END IF;
    IF COALESCE(v_operation_input_json->>'bank_csv_total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_operation_bank_csv_total_amount := ROUND((v_operation_input_json->>'bank_csv_total_amount')::numeric, 2)::numeric(14,2);
    END IF;

    v_bank_csv_export_json := CASE
      WHEN JSONB_TYPEOF(v_batch_row.bank_csv_export_json) = 'object' THEN COALESCE(v_batch_row.bank_csv_export_json, '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_stored_csv_scope := UPPER(NULLIF(BTRIM(COALESCE(
      v_bank_csv_export_json->>'scope',
      v_bank_csv_export_json->>'pay_channel_scope',
      v_bank_csv_export_json->>'payChannelScope',
      ''
    )), ''));
    v_stored_csv_paye_net_state_hash := NULLIF(BTRIM(COALESCE(
      v_bank_csv_export_json->>'scoped_paye_net_state_hash',
      v_bank_csv_export_json->>'current_scoped_paye_net_state_hash',
      v_bank_csv_export_json->>'paye_net_state_hash',
      v_bank_csv_export_json->>'current_paye_net_state_hash',
      v_bank_csv_export_json->>'payeNetStateHash',
      v_bank_csv_export_json->>'scopedPayeNetStateHash',
      ''
    )), '');
    v_stored_csv_bank_payment_projection_hash := NULLIF(BTRIM(COALESCE(
      v_bank_csv_export_json->>'scoped_bank_payment_projection_hash',
      v_bank_csv_export_json->>'current_scoped_bank_payment_projection_hash',
      v_bank_csv_export_json->>'bank_payment_projection_hash',
      v_bank_csv_export_json->>'current_bank_payment_projection_hash',
      v_bank_csv_export_json->>'bankPaymentProjectionHash',
      v_bank_csv_export_json->>'scopedBankPaymentProjectionHash',
      ''
    )), '');
    IF COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount', '') ~ '^[0-9]+$' THEN
      v_stored_csv_row_count := COALESCE(v_bank_csv_export_json->>'row_count', v_bank_csv_export_json->>'rowCount')::integer;
    END IF;
    IF COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', v_bank_csv_export_json->>'total', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_stored_csv_total_amount := ROUND(COALESCE(v_bank_csv_export_json->>'total_amount', v_bank_csv_export_json->>'totalAmount', v_bank_csv_export_json->>'total')::numeric, 2)::numeric(14,2);
    END IF;

    v_projection_proof_valid := (
      v_operation_server_owned_projection_proof
      AND v_operation_projection_proof_source IS NOT NULL
      AND v_operation_projection_scope IS NOT DISTINCT FROM v_pay_channel_scope
      AND v_operation_global_paye_net_state_hash IS NOT NULL
      AND v_operation_global_bank_payment_projection_hash IS NOT NULL
      AND v_operation_scoped_paye_net_state_hash IS NOT NULL
      AND v_operation_scoped_bank_payment_projection_hash IS NOT NULL
      AND v_operation_global_missing_count IS NOT NULL
      AND v_operation_global_zero_count IS NOT NULL
      AND v_operation_global_positive_count IS NOT NULL
      AND v_operation_global_invalid_count IS NOT NULL
      AND v_operation_scoped_missing_count IS NOT NULL
      AND v_operation_scoped_zero_count IS NOT NULL
      AND v_operation_scoped_positive_count IS NOT NULL
      AND v_operation_scoped_positive_total IS NOT NULL
      AND v_operation_scoped_invalid_count IS NOT NULL
      AND v_operation_global_missing_count = 0
      AND v_operation_scoped_missing_count = 0
      AND v_operation_global_invalid_count = 0
      AND v_operation_scoped_invalid_count = 0
      AND (v_operation_scoped_positive_count > 0 OR v_operation_scoped_zero_count > 0)
    );

    v_csv_proof_valid := (
      v_execution_mode = 'CSV_SETTLEMENT'
      AND v_projection_proof_valid
      AND v_operation_bank_csv_generated
      AND v_operation_bank_csv_current
      AND v_bank_csv_export_json <> '{}'::jsonb
      AND v_operation_bank_csv_scope IS NOT DISTINCT FROM v_pay_channel_scope
      AND v_stored_csv_scope IS NOT DISTINCT FROM v_pay_channel_scope
      AND v_operation_bank_csv_paye_net_state_hash IS NOT DISTINCT FROM v_operation_scoped_paye_net_state_hash
      AND v_operation_bank_csv_bank_payment_projection_hash IS NOT DISTINCT FROM v_operation_scoped_bank_payment_projection_hash
      AND v_stored_csv_paye_net_state_hash IS NOT DISTINCT FROM v_operation_scoped_paye_net_state_hash
      AND v_stored_csv_bank_payment_projection_hash IS NOT DISTINCT FROM v_operation_scoped_bank_payment_projection_hash
      AND v_operation_bank_csv_row_count IS NOT DISTINCT FROM v_operation_scoped_positive_count
      AND v_stored_csv_row_count IS NOT DISTINCT FROM v_operation_scoped_positive_count
      AND ROUND(COALESCE(v_operation_bank_csv_total_amount, 0), 2) IS NOT DISTINCT FROM ROUND(COALESCE(v_operation_scoped_positive_total, 0), 2)
      AND ROUND(COALESCE(v_stored_csv_total_amount, 0), 2) IS NOT DISTINCT FROM ROUND(COALESCE(v_operation_scoped_positive_total, 0), 2)
      AND v_csv_uploaded_confirmed
      AND v_payment_date_text IS NOT NULL
      AND (
        (
          v_operation_scoped_positive_count > 0
          AND v_csv_bank_confirm_ref IS NOT NULL
          AND v_manual_confirmation_mode = 'BANK_UPLOAD_CONFIRMED'
        )
        OR (
          v_operation_scoped_positive_count = 0
          AND v_operation_scoped_zero_count > 0
          AND v_manual_confirmation_mode = 'ZERO_ROW_REVIEW_NO_BANK_PAYMENT'
        )
      )
    );

    v_external_proof_valid := (
      v_execution_mode = 'EXTERNAL_SETTLEMENT'
      AND v_projection_proof_valid
      AND v_payment_date_text IS NOT NULL
      AND (
        (
          v_operation_scoped_positive_count > 0
          AND v_external_settlement_comment IS NOT NULL
          AND v_manual_confirmation_mode = 'EXTERNAL_SETTLEMENT_CONFIRMED'
        )
        OR (
          v_operation_scoped_positive_count = 0
          AND v_operation_scoped_zero_count > 0
          AND v_manual_confirmation_mode = 'NO_BANK_PAYMENT_CONFIRMED'
        )
      )
    );

    v_mode_specific_proof_valid := CASE
      WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_proof_valid
      WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_proof_valid
      ELSE true
    END;

    v_local_manual_zero_only_scope := (
      v_is_local_manual_mode
      AND COALESCE(v_operation_scoped_positive_count, 0) = 0
      AND COALESCE(v_operation_scoped_zero_count, 0) > 0
      AND v_mode_specific_proof_valid IS TRUE
    );
  ELSE
    v_expected_freshness_hash := NULLIF(BTRIM(COALESCE(p_freshness_result_hash, '')), '');
  END IF;


  v_batch_freshness_status := upper(btrim(coalesce(v_batch_row.freshness_validation_status, '')));
  v_batch_freshness_hash := nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '');
  v_batch_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), '');
  v_batch_freshness_json := coalesce(v_batch_row.freshness_result_json, '{}'::jsonb);

  IF p_operation_id IS NOT NULL THEN
    v_operation_progress_json := COALESCE(v_operation_row.progress_json, '{}'::jsonb);
    v_operation_freshness_summary_json := CASE
      WHEN JSONB_TYPEOF(v_operation_progress_json->'freshness_summary') = 'object' THEN COALESCE(v_operation_progress_json->'freshness_summary', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_operation_transfer_proof_json := COALESCE(
      CASE WHEN JSONB_TYPEOF(v_operation_progress_json->'prepared_transfer_proof') = 'object' THEN v_operation_progress_json->'prepared_transfer_proof' ELSE NULL::jsonb END,
      CASE WHEN JSONB_TYPEOF(v_operation_progress_json->'transfer_prepare_proof') = 'object' THEN v_operation_progress_json->'transfer_prepare_proof' ELSE NULL::jsonb END,
      CASE WHEN JSONB_TYPEOF(v_operation_progress_json->'transfer_scope_proof') = 'object' THEN v_operation_progress_json->'transfer_scope_proof' ELSE NULL::jsonb END,
      CASE WHEN JSONB_TYPEOF(v_operation_progress_json#>'{pay_batch_prepare_proof,summary}') = 'object' THEN v_operation_progress_json#>'{pay_batch_prepare_proof,summary}' ELSE NULL::jsonb END,
      '{}'::jsonb
    );
    v_transfer_proof_hash := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_transfer_proof_json->>'prepared_transfer_proof_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_transfer_proof_json->>'prepared_transfer_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_transfer_proof_json->>'transfer_prepare_proof_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_transfer_proof_json->>'transfer_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation_transfer_proof_json->>'prepared_result_hash', '')), '')
    );

    SELECT COUNT(*)::integer
    INTO v_candidate_count
    FROM public.pay_batch_candidates AS proof_candidate
    WHERE proof_candidate.pay_batch_id = p_pay_batch_id;

    SELECT
      COUNT(*) FILTER (
        WHERE COALESCE(proof_item.is_voided, false) = false
          AND COALESCE(proof_item.item_type, '') <> 'DEBT_CREATED'
      )::integer,
      ROUND(COALESCE(SUM(
        CASE
          WHEN COALESCE(proof_item.is_voided, false) = false
           AND COALESCE(proof_item.item_type, '') <> 'DEBT_CREATED'
            THEN COALESCE(proof_item.amount_inc_vat, proof_item.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric(14,2),
      COUNT(*) FILTER (
        WHERE COALESCE(proof_item.is_voided, false) = false
          AND COALESCE(proof_item.amount_inc_vat, proof_item.amount_ex_vat, 0) <> 0
          AND COALESCE(proof_item.item_type, '') <> 'DEBT_CREATED'
          AND NOT (
            UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
          )
          AND proof_item.payout_instruction_snapshot_json IS NULL
      )::integer
    INTO
      v_item_count,
      v_batch_item_amount_total,
      v_payout_instruction_missing_count
    FROM public.pay_batch_items AS proof_item
    JOIN public.pay_batch_candidates AS proof_candidate
      ON proof_candidate.id = proof_item.pay_batch_candidate_id
     AND proof_candidate.pay_batch_id = p_pay_batch_id
    WHERE (
      v_pay_channel_scope = 'ALL'
      OR UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = v_pay_channel_scope
      OR (
        v_pay_channel_scope = 'LOANS'
        AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
        AND UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = 'PAYE'
      )
    );

    SELECT COUNT(*)::integer
    INTO v_awaiting_net_count
    FROM public.pay_batch_candidates AS proof_candidate
    WHERE proof_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(proof_candidate.awaiting_net_amount, false) = true
      AND (
        v_pay_channel_scope = 'ALL'
        OR EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS proof_item
          WHERE proof_item.pay_batch_candidate_id = proof_candidate.id
            AND COALESCE(proof_item.is_voided, false) = false
            AND (
              UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = v_pay_channel_scope
              OR (
                v_pay_channel_scope = 'LOANS'
                AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
                AND UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = 'PAYE'
              )
            )
        )
      );

    WITH scoped_scope AS MATERIALIZED (
      SELECT
        operation_scope.id AS transfer_scope_id,
        operation_scope.operation_id,
        operation_scope.pay_batch_id,
        operation_scope.pay_channel,
        operation_scope.transfer_group_key,
        operation_scope.currency,
        operation_scope.amount,
        operation_scope.status,
        operation_scope.pay_bank_transfer_id,
        operation_scope.provider_submit_ready,
        operation_scope.provider_submit_state,
        operation_scope.provider_submit_chunk_id,
        operation_scope.provider_submit_claimed_at_utc,
        operation_scope.provider_submit_attempt_count,
        operation_scope.provider_idempotency_key,
        operation_scope.provider_request_id,
        operation_scope.provider_transaction_id,
        operation_scope.provider_request_prepared_at_utc,
        operation_scope.provider_request_sending_at_utc,
        operation_scope.provider_request_sent_at_utc,
        operation_scope.provider_response_at_utc,
        operation_scope.provider_submission_status,
        operation_scope.provider_review_required,
        operation_scope.provider_unsafe_reason,
        operation_scope.prepared_item_count,
        operation_scope.prepared_amount_total,
        operation_scope.prepared_scope_hash,
        operation_scope.prepared_result_hash,
        linked_transfer.id AS linked_transfer_id,
        linked_transfer.pay_batch_id AS linked_transfer_pay_batch_id,
        linked_transfer.pay_channel AS linked_transfer_pay_channel,
        linked_transfer.transfer_group_key AS linked_transfer_group_key,
        linked_transfer.amount AS linked_transfer_amount,
        linked_transfer.currency AS linked_transfer_currency,
        linked_transfer.status AS linked_transfer_status,
        linked_transfer.request_id AS linked_transfer_request_id,
        linked_transfer.rail_tx_id AS linked_transfer_rail_tx_id,
        linked_transfer.rail_state AS linked_transfer_rail_state,
        linked_transfer.completed_at_utc AS linked_transfer_completed_at_utc,
        linked_transfer.failed_reason AS linked_transfer_failed_reason,
        linked_transfer.rail_meta_json AS linked_transfer_rail_meta_json,
        COALESCE(scope_item_proof.item_count, 0) AS scope_item_count,
        COALESCE(scope_item_proof.item_amount_total, 0)::numeric(14,2) AS scope_item_amount_total,
        COALESCE(scope_item_proof.rollup_pending_count, 0) AS scope_item_rollup_pending_count,
        COALESCE(scope_item_proof.transfer_link_mismatch_count, 0) AS scope_item_transfer_link_mismatch_count
      FROM public.banking_pay_operation_transfer_scope AS operation_scope
      LEFT JOIN public.pay_bank_transfers AS linked_transfer
        ON linked_transfer.id = operation_scope.pay_bank_transfer_id
       AND linked_transfer.pay_batch_id = operation_scope.pay_batch_id
      LEFT JOIN LATERAL (
        SELECT
          COUNT(scope_item.id)::integer AS item_count,
          ROUND(COALESCE(SUM(scope_item.item_amount), 0), 2)::numeric(14,2) AS item_amount_total,
          COUNT(scope_item.id) FILTER (
            WHERE UPPER(BTRIM(COALESCE(scope_item.rollup_status, ''))) NOT IN ('ROLLED_UP', 'ROLLEDUP', 'READY', 'PREPARED', 'COMPLETE', 'COMPLETED')
          )::integer AS rollup_pending_count,
          COUNT(scope_item.id) FILTER (
            WHERE batch_item.id IS NULL
               OR batch_item.pay_bank_transfer_id IS DISTINCT FROM operation_scope.pay_bank_transfer_id
          )::integer AS transfer_link_mismatch_count
        FROM public.banking_pay_operation_transfer_scope_items AS scope_item
        LEFT JOIN public.pay_batch_items AS batch_item
          ON batch_item.id = scope_item.pay_batch_item_id
        WHERE scope_item.operation_id = operation_scope.operation_id
          AND scope_item.pay_batch_id = operation_scope.pay_batch_id
          AND scope_item.transfer_scope_id = operation_scope.id
      ) AS scope_item_proof ON true
      WHERE operation_scope.operation_id = p_operation_id
        AND operation_scope.pay_batch_id = p_pay_batch_id
        AND (
          v_pay_channel_scope = 'ALL'
          OR UPPER(BTRIM(COALESCE(operation_scope.pay_channel, ''))) = v_pay_channel_scope
          OR (
            v_pay_channel_scope = 'LOANS'
            AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) = 'LOANS'
            AND UPPER(BTRIM(COALESCE(operation_scope.pay_channel, ''))) = 'PAYE'
          )
        )
    ), scope_evidence AS MATERIALIZED (
      SELECT
        scoped_scope.*,
        (
          scoped_scope.linked_transfer_id IS NOT NULL
          AND scoped_scope.linked_transfer_pay_batch_id IS NOT DISTINCT FROM scoped_scope.pay_batch_id
          AND scoped_scope.linked_transfer_pay_channel IS NOT DISTINCT FROM scoped_scope.pay_channel
          AND scoped_scope.linked_transfer_group_key IS NOT DISTINCT FROM scoped_scope.transfer_group_key
          AND ROUND(COALESCE(scoped_scope.linked_transfer_amount, 0), 2) IS NOT DISTINCT FROM ROUND(COALESCE(scoped_scope.amount, 0), 2)
          AND UPPER(BTRIM(COALESCE(scoped_scope.linked_transfer_currency, 'GBP'))) IS NOT DISTINCT FROM UPPER(BTRIM(COALESCE(scoped_scope.currency, 'GBP')))
        ) AS transfer_identity_clean,
        (
          scoped_scope.linked_transfer_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(scoped_scope.linked_transfer_status, ''))) = 'PENDING'
          AND NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_rail_tx_id, '')), '') IS NULL
          AND scoped_scope.linked_transfer_completed_at_utc IS NULL
          AND NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_failed_reason, '')), '') IS NULL
          AND UPPER(BTRIM(COALESCE(scoped_scope.linked_transfer_rail_state, ''))) IN ('', 'LOCAL', 'PENDING')
        ) AS transfer_local_state_clean,
        EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS transfer_event
          WHERE transfer_event.pay_batch_id = p_pay_batch_id
            AND (
              transfer_event.pay_bank_transfer_id = scoped_scope.linked_transfer_id
              OR (
                transfer_event.pay_bank_transfer_id IS NULL
                AND (
                  NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = scoped_scope.linked_transfer_id::text
                  OR NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_request_id, '')), '')
                  OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_request_id, '')), '')
                  OR NULLIF(BTRIM(COALESCE(transfer_event.provider_request_id, '')), '') = NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_request_id, '')), '')
                  OR NULLIF(BTRIM(COALESCE(transfer_event.provider_transaction_id, '')), '') = NULLIF(BTRIM(COALESCE(scoped_scope.linked_transfer_rail_tx_id, '')), '')
                )
              )
            )
            AND (
              UPPER(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
              OR NULLIF(BTRIM(COALESCE(transfer_event.provider_request_id, '')), '') IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_event.provider_transaction_id, '')), '') IS NOT NULL
              OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') IS NOT NULL
              OR transfer_event.provider_webhook_receipt_id IS NOT NULL
            )
        ) AS provider_event_present,
        EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_provider_attempts AS provider_attempt
          WHERE provider_attempt.operation_id = p_operation_id
            AND (
              provider_attempt.transfer_scope_id = scoped_scope.transfer_scope_id
              OR provider_attempt.transfer_scope_id IS NULL
            )
        ) AS provider_attempt_present,
        (
          COALESCE(scoped_scope.provider_submit_attempt_count, 0) > 0
          OR scoped_scope.provider_submit_chunk_id IS NOT NULL
          OR scoped_scope.provider_submit_claimed_at_utc IS NOT NULL
          OR scoped_scope.provider_request_prepared_at_utc IS NOT NULL
          OR scoped_scope.provider_request_sending_at_utc IS NOT NULL
          OR scoped_scope.provider_request_sent_at_utc IS NOT NULL
          OR scoped_scope.provider_response_at_utc IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(scoped_scope.provider_transaction_id, '')), '') IS NOT NULL
          OR UPPER(BTRIM(COALESCE(scoped_scope.provider_submit_state, 'NOT_READY'))) IN (
            'CLAIMED', 'REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL',
            'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'CHUNK_FINALISED'
          )
        ) AS provider_dispatch_started,
        (
          UPPER(BTRIM(COALESCE(scoped_scope.status, ''))) = 'PREPARED'
          AND COALESCE(scoped_scope.prepared_item_count, 0) > 0
          AND NULLIF(BTRIM(COALESCE(scoped_scope.prepared_scope_hash, '')), '') IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(scoped_scope.prepared_result_hash, '')), '') IS NOT NULL
          AND ROUND(COALESCE(scoped_scope.prepared_amount_total, 0), 2) IS NOT DISTINCT FROM ROUND(COALESCE(scoped_scope.amount, 0), 2)
          AND ROUND(COALESCE(scoped_scope.prepared_amount_total, 0), 2) > 0
          AND scoped_scope.scope_item_count = COALESCE(scoped_scope.prepared_item_count, 0)
          AND scoped_scope.scope_item_rollup_pending_count = 0
          AND scoped_scope.scope_item_transfer_link_mismatch_count = 0
          AND ROUND(COALESCE(scoped_scope.scope_item_amount_total, 0), 2) IS NOT DISTINCT FROM ROUND(COALESCE(scoped_scope.amount, 0), 2)
        ) AS frozen_scope_proof_clean
      FROM scoped_scope
    ), scope_readiness AS MATERIALIZED (
      SELECT
        scope_evidence.*,
        (
          scope_evidence.transfer_identity_clean
          AND scope_evidence.transfer_local_state_clean
          AND scope_evidence.provider_event_present IS NOT TRUE
          AND scope_evidence.provider_attempt_present IS NOT TRUE
          AND scope_evidence.provider_dispatch_started IS NOT TRUE
        ) AS transfer_evidence_clean,
        CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN
            COALESCE(scope_evidence.provider_submit_ready, false) = true
            AND UPPER(BTRIM(COALESCE(scope_evidence.provider_submit_state, ''))) = 'READY'
            AND COALESCE(scope_evidence.provider_review_required, false) = false
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_unsafe_reason, '')), '') IS NULL
          ELSE
            v_mode_specific_proof_valid
            AND COALESCE(scope_evidence.provider_submit_ready, false) = false
            AND UPPER(BTRIM(COALESCE(scope_evidence.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
            AND scope_evidence.provider_submit_chunk_id IS NULL
            AND scope_evidence.provider_submit_claimed_at_utc IS NULL
            AND COALESCE(scope_evidence.provider_submit_attempt_count, 0) = 0
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_idempotency_key, '')), '') IS NULL
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_request_id, '')), '') IS NULL
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_transaction_id, '')), '') IS NULL
            AND scope_evidence.provider_request_prepared_at_utc IS NULL
            AND scope_evidence.provider_request_sending_at_utc IS NULL
            AND scope_evidence.provider_request_sent_at_utc IS NULL
            AND scope_evidence.provider_response_at_utc IS NULL
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_submission_status, '')), '') IS NULL
            AND COALESCE(scope_evidence.provider_review_required, false) = false
            AND NULLIF(BTRIM(COALESCE(scope_evidence.provider_unsafe_reason, '')), '') IS NULL
        END AS mode_route_ready
      FROM scope_evidence
    )
    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'PREPARED')::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) IN ('PENDING', 'ROLLED_UP'))::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'FAILED')::integer,
      COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'SKIPPED')::integer,
      COUNT(*) FILTER (WHERE scope_readiness.pay_bank_transfer_id IS NULL OR scope_readiness.linked_transfer_id IS NULL)::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.frozen_scope_proof_clean
          AND scope_readiness.transfer_evidence_clean
          AND scope_readiness.mode_route_ready
      )::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.provider_event_present
           OR scope_readiness.provider_attempt_present
           OR scope_readiness.provider_dispatch_started
           OR scope_readiness.transfer_local_state_clean IS NOT TRUE
           OR (
             v_is_local_manual_mode
             AND (
               COALESCE(scope_readiness.provider_submit_ready, false) = true
               OR UPPER(BTRIM(COALESCE(scope_readiness.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
               OR NULLIF(BTRIM(COALESCE(scope_readiness.provider_idempotency_key, '')), '') IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(scope_readiness.provider_request_id, '')), '') IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(scope_readiness.provider_submission_status, '')), '') IS NOT NULL
             )
           )
      )::integer,
      COUNT(*) FILTER (WHERE scope_readiness.transfer_identity_clean IS NOT TRUE)::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.linked_transfer_id IS NOT NULL
          AND ROUND(COALESCE(scope_readiness.linked_transfer_amount, 0), 2) IS DISTINCT FROM ROUND(COALESCE(scope_readiness.amount, 0), 2)
      )::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.linked_transfer_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(scope_readiness.linked_transfer_currency, 'GBP'))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(scope_readiness.currency, 'GBP')))
      )::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.linked_transfer_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(scope_readiness.linked_transfer_status, ''))) <> 'PENDING'
      )::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.linked_transfer_id IS NOT NULL
          AND scope_readiness.transfer_local_state_clean IS NOT TRUE
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'PREPARED'
          AND scope_readiness.mode_route_ready IS NOT TRUE
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'PREPARED'
          AND (
            NULLIF(BTRIM(COALESCE(scope_readiness.prepared_scope_hash, '')), '') IS NULL
            OR NULLIF(BTRIM(COALESCE(scope_readiness.prepared_result_hash, '')), '') IS NULL
          )
      )::integer,
      COUNT(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(scope_readiness.status, ''))) = 'PREPARED'
          AND ROUND(COALESCE(scope_readiness.prepared_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(scope_readiness.amount, 0), 2)
      )::integer,
      COALESCE(SUM(scope_readiness.scope_item_rollup_pending_count), 0)::integer,
      COALESCE(SUM(scope_readiness.scope_item_transfer_link_mismatch_count), 0)::integer,
      COUNT(*) FILTER (
        WHERE scope_readiness.scope_item_count IS DISTINCT FROM COALESCE(scope_readiness.prepared_item_count, 0)
      )::integer,
      COUNT(*) FILTER (
        WHERE ROUND(COALESCE(scope_readiness.scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(scope_readiness.amount, 0), 2)
      )::integer,
      ROUND(COALESCE(SUM(scope_readiness.amount), 0), 2)::numeric(14,2),
      ROUND(COALESCE(SUM(scope_readiness.linked_transfer_amount), 0), 2)::numeric(14,2),
      ROUND(COALESCE(SUM(scope_readiness.scope_item_amount_total), 0), 2)::numeric(14,2),
      MD5(COALESCE(STRING_AGG(
        scope_readiness.transfer_scope_id::text || ':' ||
        COALESCE(scope_readiness.pay_bank_transfer_id::text, '') || ':' ||
        COALESCE(scope_readiness.status, '') || ':' ||
        ROUND(COALESCE(scope_readiness.amount, 0), 2)::text || ':' ||
        COALESCE(scope_readiness.prepared_scope_hash, '') || ':' ||
        COALESCE(scope_readiness.prepared_result_hash, ''),
        '|' ORDER BY scope_readiness.transfer_scope_id
      ), 'NO_SCOPE'))
    INTO
      v_scoped_operation_scope_count,
      v_scoped_scope_prepared_count,
      v_scoped_scope_pending_count,
      v_scoped_scope_failed_count,
      v_scoped_scope_skipped_count,
      v_scoped_scope_without_transfer_count,
      v_authorisation_ready_transfer_count,
      v_unsafe_transfer_count,
      v_transfer_identity_mismatch_count,
      v_transfer_amount_mismatch_count,
      v_transfer_currency_mismatch_count,
      v_transfer_status_not_pending_count,
      v_transfer_external_state_count,
      v_scope_provider_not_ready_count,
      v_scope_prepared_hash_missing_count,
      v_scope_prepared_amount_mismatch_count,
      v_scope_item_rollup_pending_count,
      v_scope_item_transfer_link_mismatch_count,
      v_scope_item_count_mismatch_count,
      v_scope_item_amount_mismatch_count,
      v_scope_amount_total,
      v_transfer_amount_total,
      v_scope_item_amount_total,
      v_transfer_scope_hash
    FROM scope_readiness;

    v_transfer_proof_hash_mismatch_count := CASE
      WHEN v_transfer_proof_hash IS NOT NULL
       AND v_transfer_scope_hash IS NOT NULL
       AND v_transfer_proof_hash IS DISTINCT FROM v_transfer_scope_hash THEN 1
      ELSE 0
    END;

    IF v_is_local_manual_mode THEN
      SELECT COUNT(*)::integer
      INTO v_provider_scope_evidence_count
      FROM public.banking_pay_operation_transfer_scope AS provider_scope
      WHERE provider_scope.operation_id = p_operation_id
        AND provider_scope.pay_batch_id = p_pay_batch_id
        AND (
          COALESCE(provider_scope.provider_submit_ready, false) = true
          OR UPPER(BTRIM(COALESCE(provider_scope.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
          OR provider_scope.provider_submit_chunk_id IS NOT NULL
          OR provider_scope.provider_submit_claimed_at_utc IS NOT NULL
          OR COALESCE(provider_scope.provider_submit_attempt_count, 0) > 0
          OR NULLIF(BTRIM(COALESCE(provider_scope.provider_idempotency_key, '')), '') IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(provider_scope.provider_request_id, '')), '') IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(provider_scope.provider_transaction_id, '')), '') IS NOT NULL
          OR provider_scope.provider_request_prepared_at_utc IS NOT NULL
          OR provider_scope.provider_request_sending_at_utc IS NOT NULL
          OR provider_scope.provider_request_sent_at_utc IS NOT NULL
          OR provider_scope.provider_response_at_utc IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(provider_scope.provider_submission_status, '')), '') IS NOT NULL
        );

      SELECT COUNT(*)::integer
      INTO v_provider_attempt_row_count
      FROM public.banking_pay_operation_provider_attempts AS provider_attempt
      WHERE provider_attempt.operation_id = p_operation_id
         OR provider_attempt.pay_batch_id = p_pay_batch_id;

      SELECT COUNT(*)::integer
      INTO v_provider_event_count
      FROM public.pay_bank_transfer_events AS transfer_event
      WHERE transfer_event.pay_batch_id = p_pay_batch_id
        AND (
          UPPER(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
          OR NULLIF(BTRIM(COALESCE(transfer_event.provider_request_id, '')), '') IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(transfer_event.provider_transaction_id, '')), '') IS NOT NULL
          OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') IS NOT NULL
          OR transfer_event.provider_webhook_receipt_id IS NOT NULL
        );

      SELECT COUNT(*)::integer
      INTO v_provider_transfer_evidence_count
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = p_pay_batch_id
        AND (
          UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
          OR transfer_row.completed_at_utc IS NOT NULL
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
          OR UPPER(BTRIM(COALESCE(transfer_row.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), '') IS NOT NULL
          OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        );

      SELECT COUNT(*)::integer
      INTO v_provider_submit_chunk_count
      FROM public.banking_pay_operation_chunks AS provider_chunk
      WHERE provider_chunk.operation_id = p_operation_id
        AND (
          UPPER(BTRIM(COALESCE(provider_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
          OR UPPER(BTRIM(COALESCE(provider_chunk.phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND', 'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES')
        );

      v_provider_boundary_evidence_count := COALESCE(v_provider_scope_evidence_count, 0)
        + COALESCE(v_provider_attempt_row_count, 0)
        + COALESCE(v_provider_event_count, 0)
        + COALESCE(v_provider_transfer_evidence_count, 0)
        + COALESCE(v_provider_submit_chunk_count, 0);
    END IF;

    IF v_execution_commit_state <> 'NOT_SUBMITTED'
       OR NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
       OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'EXECUTION_STATE_CONFLICT',
        'message', 'This payment batch has already crossed the execution boundary and cannot be prepared again.',
        'execution_commit_state', v_execution_commit_state
      ));
    END IF;

    IF v_batch_status IN ('CANCELLED', 'CANCELED') THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'BATCH_CANCELLED',
        'message', 'The payment batch has been cancelled.'
      ));
    ELSIF v_batch_status <> 'DRAFT' THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'BATCH_STATUS_NOT_DRAFT',
        'message', 'Only a DRAFT batch can be prepared for payment execution.',
        'batch_status', v_batch_row.status
      ));
    END IF;

    IF v_candidate_count <= 0 THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'NO_CANDIDATES',
        'message', 'The payment batch has no candidates.'
      ));
    END IF;

    IF v_item_count <= 0 THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'NO_PAYMENT_ITEMS',
        'message', 'The payment batch has no payment items in the requested frozen scope.'
      ));
    END IF;

    IF v_awaiting_net_count > 0
       OR COALESCE(v_operation_global_missing_count, 0) > 0
       OR COALESCE(v_operation_scoped_missing_count, 0) > 0 THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'PAYE_NET_REQUIRED',
        'message', 'PAYE net amounts are required before this batch can proceed.',
        'candidate_count', v_awaiting_net_count,
        'global_missing_explicit_paye_input_count', v_operation_global_missing_count,
        'scoped_missing_explicit_paye_input_count', v_operation_scoped_missing_count
      ));
    END IF;

    IF v_batch_freshness_status <> 'PASSED'
       OR v_batch_freshness_hash IS NULL
       OR COALESCE((v_batch_freshness_json->>'is_stale')::boolean, false) IS TRUE THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', CASE WHEN v_batch_freshness_status = 'STALE' THEN 'BATCH_STALE' ELSE 'FRESHNESS_REQUIRED' END,
        'message', 'Chunked freshness must pass before this payment batch can be prepared.',
        'freshness_validation_status', NULLIF(v_batch_freshness_status, ''),
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'stale_reasons', COALESCE(v_batch_freshness_json->'stale_reasons', '[]'::jsonb)
      ));
    ELSIF v_expected_freshness_hash IS NULL THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'The payment operation does not carry a completed freshness result hash.',
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_batch_freshness_hash IS DISTINCT FROM v_expected_freshness_hash THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'The stored freshness result does not match the operation freshness result.',
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_batch_freshness_hash
      ));
    ELSIF v_expected_freshness_scope_hash IS NOT NULL
       AND v_batch_freshness_scope_hash IS DISTINCT FROM v_expected_freshness_scope_hash THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'The stored freshness scope does not match the operation freshness scope.',
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    END IF;

    IF v_is_local_manual_mode AND v_projection_proof_valid IS NOT TRUE THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'LOCAL_MANUAL_SETTLEMENT_PROJECTION_PROOF_INVALID',
        'message', 'Local/manual settlement requires the complete server-owned frozen payment projection proof.',
        'execution_mode', v_execution_mode,
        'pay_channel_scope', v_pay_channel_scope,
        'projection_proof_source', v_operation_projection_proof_source,
        'server_owned_payment_projection_proof', v_operation_server_owned_projection_proof,
        'global_missing_count', v_operation_global_missing_count,
        'scoped_missing_count', v_operation_scoped_missing_count,
        'global_invalid_count', v_operation_global_invalid_count,
        'scoped_invalid_count', v_operation_scoped_invalid_count
      ));
    END IF;

    IF v_execution_mode = 'CSV_SETTLEMENT' AND v_csv_proof_valid IS NOT TRUE THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'CSV_SETTLEMENT_PROOF_INVALID',
        'message', 'The current CloudTMS Bank CSV proof, upload confirmation, or positive-route bank confirmation does not match the frozen authorised scope.',
        'requested_scope', v_pay_channel_scope,
        'stored_csv_scope', v_stored_csv_scope,
        'operation_csv_scope', v_operation_bank_csv_scope,
        'stored_csv_row_count', v_stored_csv_row_count,
        'operation_csv_row_count', v_operation_bank_csv_row_count,
        'expected_positive_row_count', v_operation_scoped_positive_count,
        'stored_csv_total_amount', v_stored_csv_total_amount,
        'operation_csv_total_amount', v_operation_bank_csv_total_amount,
        'expected_positive_total_amount', v_operation_scoped_positive_total,
        'csv_uploaded_confirmed', v_csv_uploaded_confirmed,
        'csv_bank_confirm_ref_present', v_csv_bank_confirm_ref IS NOT NULL,
        'manual_confirmation_mode', v_manual_confirmation_mode
      ));
    ELSIF v_execution_mode = 'EXTERNAL_SETTLEMENT' AND v_external_proof_valid IS NOT TRUE THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'EXTERNAL_SETTLEMENT_PROOF_INVALID',
        'message', 'External settlement requires the complete frozen projection and external/manual confirmation evidence.',
        'pay_channel_scope', v_pay_channel_scope,
        'payment_date_present', v_payment_date_text IS NOT NULL,
        'external_settlement_comment_present', v_external_settlement_comment IS NOT NULL,
        'manual_confirmation_mode', v_manual_confirmation_mode,
        'scoped_positive_bank_payment_count', v_operation_scoped_positive_count,
        'scoped_explicit_zero_count', v_operation_scoped_zero_count
      ));
    END IF;

    IF v_is_local_manual_mode AND v_provider_boundary_evidence_count > 0 THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
        'message', 'Local/manual settlement cannot continue because provider or bank-dispatch evidence exists.',
        'execution_mode', v_execution_mode,
        'provider_scope_evidence_count', COALESCE(v_provider_scope_evidence_count, 0),
        'provider_attempt_row_count', COALESCE(v_provider_attempt_row_count, 0),
        'provider_event_count', COALESCE(v_provider_event_count, 0),
        'provider_transfer_evidence_count', COALESCE(v_provider_transfer_evidence_count, 0),
        'provider_submit_chunk_count', COALESCE(v_provider_submit_chunk_count, 0),
        'provider_boundary_evidence_count', COALESCE(v_provider_boundary_evidence_count, 0)
      ));
    END IF;

    IF v_local_manual_zero_only_scope IS NOT TRUE
       AND (
         COALESCE(v_scoped_operation_scope_count, 0) <= 0
         OR v_transfer_proof_hash IS NULL
         OR v_transfer_scope_hash IS NULL
       ) THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', 'OPERATION_TRANSFER_SCOPE_PROOF_MISSING',
        'message', 'A persisted prepared transfer proof and frozen operation transfer scope are required before prepare can complete.',
        'operation_id', p_operation_id::text,
        'execution_mode', v_execution_mode,
        'persisted_transfer_proof_hash', v_transfer_proof_hash,
        'current_transfer_scope_hash', v_transfer_scope_hash
      ));
    ELSIF v_local_manual_zero_only_scope IS NOT TRUE
       AND (
         COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         OR COALESCE(v_scoped_scope_pending_count, 0) > 0
       OR COALESCE(v_scoped_scope_failed_count, 0) > 0
       OR COALESCE(v_scoped_scope_skipped_count, 0) > 0
       OR COALESCE(v_scoped_scope_without_transfer_count, 0) > 0
       OR COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
       OR COALESCE(v_unsafe_transfer_count, 0) > 0
       OR (v_execution_mode = 'STANDARD_BANK' AND COALESCE(v_scope_provider_not_ready_count, 0) > 0)
       OR COALESCE(v_scope_prepared_hash_missing_count, 0) > 0
       OR COALESCE(v_scope_prepared_amount_mismatch_count, 0) > 0
       OR COALESCE(v_scope_item_rollup_pending_count, 0) > 0
       OR COALESCE(v_scope_item_transfer_link_mismatch_count, 0) > 0
       OR COALESCE(v_transfer_proof_hash_mismatch_count, 0) > 0
       OR COALESCE(v_scope_item_count_mismatch_count, 0) > 0
       OR COALESCE(v_scope_item_amount_mismatch_count, 0) > 0
       OR COALESCE(v_payout_instruction_missing_count, 0) > 0
       OR ROUND(COALESCE(v_scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_scope_amount_total, 0), 2)
       OR ROUND(COALESCE(v_transfer_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_scope_amount_total, 0), 2)
       ) THEN
      v_blockers_json := v_blockers_json || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'code', CASE
          WHEN COALESCE(v_unsafe_transfer_count, 0) > 0 OR COALESCE(v_provider_boundary_evidence_count, 0) > 0
            THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED'
          ELSE 'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED'
        END,
        'message', CASE
          WHEN v_is_local_manual_mode
            THEN 'Every local/manual settlement transfer scope must be prepared, proofed, item-linked, amount-matched, and free of provider evidence before authorisation can start.'
          ELSE 'Every scoped transfer group must be prepared, proofed, provider-ready, and linked to a safe bank transfer before authorisation can start.'
        END,
        'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
        'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'scope_provider_not_ready_count', COALESCE(v_scope_provider_not_ready_count, 0),
        'scope_prepared_hash_missing_count', COALESCE(v_scope_prepared_hash_missing_count, 0),
        'scope_prepared_amount_mismatch_count', COALESCE(v_scope_prepared_amount_mismatch_count, 0),
        'scope_item_rollup_pending_count', COALESCE(v_scope_item_rollup_pending_count, 0),
        'scope_item_transfer_link_mismatch_count', COALESCE(v_scope_item_transfer_link_mismatch_count, 0),
        'transfer_proof_hash_mismatch_count', COALESCE(v_transfer_proof_hash_mismatch_count, 0),
        'persisted_transfer_proof_hash', v_transfer_proof_hash,
        'current_transfer_scope_hash', v_transfer_scope_hash,
        'scope_item_count_mismatch_count', COALESCE(v_scope_item_count_mismatch_count, 0),
        'scope_item_amount_mismatch_count', COALESCE(v_scope_item_amount_mismatch_count, 0),
        'payout_instruction_missing_count', COALESCE(v_payout_instruction_missing_count, 0)
      ));
    END IF;

    v_blocker_count := JSONB_ARRAY_LENGTH(v_blockers_json);
    v_warning_count := JSONB_ARRAY_LENGTH(v_warnings_json);
    v_ready := v_blocker_count = 0;
    v_all_scoped_operation_scopes_authorisation_ready := v_ready;
    v_next_required_phase := CASE
      WHEN v_execution_commit_state <> 'NOT_SUBMITTED' THEN 'STOP_EXECUTION_BOUNDARY_CROSSED'
      WHEN EXISTS (
        SELECT 1
        FROM JSONB_ARRAY_ELEMENTS(v_blockers_json) AS blocker(elem)
        WHERE blocker.elem->>'code' IN (
          'BATCH_STALE', 'FRESHNESS_REQUIRED', 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION',
          'FRESHNESS_RESULT_HASH_MISMATCH', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING'
        )
      ) THEN 'VALIDATE_FRESHNESS'
      WHEN v_batch_status IN ('CANCELLED', 'CANCELED') THEN 'STOP_CANCELLED'
      WHEN v_blocker_count > 0 THEN 'RESOLVE_BLOCKERS'
      ELSE 'START_AUTHORISATION'
    END;

    v_summary_json := JSONB_BUILD_OBJECT(
      'mode', 'OPERATION_PROOF',
      'execution_mode', v_execution_mode,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'item_count', COALESCE(v_item_count, 0),
      'transfer_count', COALESCE(v_scoped_operation_scope_count, 0),
      'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'local_settlement_evidence_only', v_is_local_manual_mode,
      'local_manual_zero_only_scope', v_local_manual_zero_only_scope,
      'mode_specific_proof_valid', v_mode_specific_proof_valid,
      'persisted_transfer_proof_hash', v_transfer_proof_hash,
      'prepared_transfer_proof_hash', v_transfer_scope_hash,
      'transfer_proof_hash_mismatch_count', COALESCE(v_transfer_proof_hash_mismatch_count, 0),
      'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
      'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
      'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
      'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2)
    );

    v_operation_prepare_proof_json := JSONB_BUILD_OBJECT(
      'checked_at_utc', v_now::text,
      'ready', v_ready,
      'blocker_count', v_blocker_count,
      'execution_mode', v_execution_mode,
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'local_settlement_evidence_only', v_is_local_manual_mode,
      'local_manual_zero_only_scope', v_local_manual_zero_only_scope,
      'mode_specific_proof_valid', v_mode_specific_proof_valid,
      'projection_proof_valid', v_projection_proof_valid,
      'csv_proof_valid', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_proof_valid ELSE NULL::boolean END,
      'external_proof_valid', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_proof_valid ELSE NULL::boolean END,
      'provider_boundary_evidence_count', CASE WHEN v_is_local_manual_mode THEN COALESCE(v_provider_boundary_evidence_count, 0) ELSE NULL::integer END,
      'persisted_transfer_proof_hash', v_transfer_proof_hash,
      'prepared_transfer_proof_hash', v_transfer_scope_hash,
      'transfer_proof_hash_mismatch_count', COALESCE(v_transfer_proof_hash_mismatch_count, 0),
      'freshness_result_hash', v_batch_freshness_hash,
      'freshness_scope_hash', v_batch_freshness_scope_hash,
      'pay_channel_scope', v_pay_channel_scope,
      'summary', v_summary_json
    );

    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = JSONB_STRIP_NULLS(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || JSONB_BUILD_OBJECT(
            'pay_batch_prepare_proof', v_operation_prepare_proof_json,
            'execution_mode', v_execution_mode,
            'provider_submission_required', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
            'provider_submission_attempted', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
            'submitted_to_bank', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
            'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
            'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
            'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
            'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END
          )
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN JSONB_BUILD_OBJECT(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'ready', v_ready,
      'ready_flag', v_ready,
      'proof_mode', true,
      'used_operation_scope_proof', true,
      'pay_batch_prepare_skipped_full_classification', true,
      'blocker_count', v_blocker_count,
      'warning_count', v_warning_count,
      'blockers', v_blockers_json,
      'warnings', v_warnings_json,
      'next_required_phase', v_next_required_phase,
      'execution_summary', v_summary_json,
      'batch_status', v_batch_row.status,
      'execution_commit_state', v_execution_commit_state,
      'execution_mode', v_execution_mode,
      'pay_channel_scope', v_pay_channel_scope,
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'local_settlement_evidence_only', v_is_local_manual_mode,
      'mode_specific_proof_valid', v_mode_specific_proof_valid,
      'projection_proof_valid', v_projection_proof_valid,
      'csv_proof_valid', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_proof_valid ELSE NULL::boolean END,
      'external_proof_valid', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_proof_valid ELSE NULL::boolean END,
      'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
      'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
      'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
      'all_scoped_operation_scopes_authorisation_ready', COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false),
      'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
      'provider_boundary_evidence_count', CASE WHEN v_is_local_manual_mode THEN COALESCE(v_provider_boundary_evidence_count, 0) ELSE 0 END,
      'transfer_proof_hash_mismatch_count', COALESCE(v_transfer_proof_hash_mismatch_count, 0),
      'freshness', JSONB_BUILD_OBJECT(
        'freshness_validation_status', v_batch_freshness_status,
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'expected_freshness_result_hash', v_expected_freshness_hash
      ),
      'prepared_transfer_proof', v_operation_prepare_proof_json,
      'server_utc', v_now
    ) || JSONB_STRIP_NULLS(JSONB_BUILD_OBJECT(
      'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
      'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
      'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
      'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END,
      'payment_date', CASE WHEN v_is_local_manual_mode THEN v_payment_date_text ELSE NULL::text END
    ));
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_candidate_count
    FROM public.pay_batch_candidates AS proof_candidate
    WHERE proof_candidate.pay_batch_id = p_pay_batch_id;

    SELECT
      count(*)::integer,
      round(coalesce(sum(CASE WHEN COALESCE(proof_item.is_voided, false) = false AND proof_item.item_type <> 'DEBT_CREATED' THEN COALESCE(proof_item.amount_inc_vat, proof_item.amount_ex_vat, 0) ELSE 0 END), 0), 2)::numeric(14,2),
      count(*) FILTER (
        WHERE COALESCE(proof_item.is_voided, false) = false
          AND COALESCE(proof_item.amount_inc_vat, proof_item.amount_ex_vat, 0) <> 0
          AND proof_item.item_type <> 'DEBT_CREATED'
          AND NOT (
            UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
          )
          AND proof_item.payout_instruction_snapshot_json IS NULL
      )::integer
    INTO v_item_count, v_batch_item_amount_total, v_payout_instruction_missing_count
    FROM public.pay_batch_items AS proof_item
    JOIN public.pay_batch_candidates AS proof_candidate
      ON proof_candidate.id = proof_item.pay_batch_candidate_id
    WHERE proof_candidate.pay_batch_id = p_pay_batch_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = v_pay_channel_scope
      );

    SELECT count(*)::integer
    INTO v_awaiting_net_count
    FROM public.pay_batch_candidates AS proof_candidate
    WHERE proof_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(proof_candidate.awaiting_net_amount, false) = true
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS proof_item
          WHERE proof_item.pay_batch_candidate_id = proof_candidate.id
            AND UPPER(BTRIM(COALESCE(proof_item.pay_channel, ''))) = v_pay_channel_scope
            AND COALESCE(proof_item.is_voided, false) = false
        )
      );

    SELECT
      count(*)::integer,
      count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'PREPARED')::integer,
      count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) IN ('PENDING', 'QUEUED', 'RUNNING'))::integer,
      count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'FAILED')::integer,
      count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'SKIPPED')::integer,
      count(*) FILTER (WHERE operation_scope.pay_bank_transfer_id IS NULL OR linked_transfer.id IS NULL)::integer,
      count(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'PREPARED'
          AND linked_transfer.id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(linked_transfer.status, ''))) = 'PENDING'
          AND linked_transfer.pay_batch_id = operation_scope.pay_batch_id
          AND linked_transfer.pay_channel = operation_scope.pay_channel
          AND linked_transfer.transfer_group_key = operation_scope.transfer_group_key
          AND ROUND(COALESCE(linked_transfer.amount, 0), 2) = ROUND(COALESCE(operation_scope.amount, 0), 2)
          AND UPPER(BTRIM(COALESCE(linked_transfer.currency, 'GBP'))) = UPPER(BTRIM(COALESCE(operation_scope.currency, 'GBP')))
          AND NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), '') IS NULL
          AND linked_transfer.completed_at_utc IS NULL
          AND NULLIF(BTRIM(COALESCE(linked_transfer.failed_reason, '')), '') IS NULL
          AND UPPER(BTRIM(COALESCE(linked_transfer.rail_state, ''))) IN ('', 'LOCAL', 'PENDING')
          AND COALESCE(operation_scope.provider_submit_ready, false) = true
          AND UPPER(BTRIM(COALESCE(operation_scope.provider_submit_state, ''))) = 'READY'
          AND COALESCE(operation_scope.provider_review_required, false) = false
          AND NULLIF(BTRIM(COALESCE(operation_scope.provider_unsafe_reason, '')), '') IS NULL
          AND NULLIF(BTRIM(COALESCE(operation_scope.prepared_scope_hash, '')), '') IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(operation_scope.prepared_result_hash, '')), '') IS NOT NULL
          AND ROUND(COALESCE(operation_scope.prepared_amount_total, 0), 2) = ROUND(COALESCE(operation_scope.amount, 0), 2)
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_bank_transfer_events AS transfer_event
            WHERE transfer_event.pay_batch_id = p_pay_batch_id
              AND (
                transfer_event.pay_bank_transfer_id = linked_transfer.id
                OR (
                  transfer_event.pay_bank_transfer_id IS NULL
                  AND (
                    NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = linked_transfer.id::text
                    OR NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), '')
                    OR NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), '')
                    OR NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = NULLIF(BTRIM(COALESCE(linked_transfer.payment_reference, '')), '')
                    OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), '')
                    OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{idempotency_key}', '')), '')
                  )
                )
              )
          )
      )::integer,
      count(*) FILTER (
        WHERE linked_transfer.id IS NOT NULL
          AND (
            UPPER(BTRIM(COALESCE(linked_transfer.status, ''))) <> 'PENDING'
            OR linked_transfer.pay_batch_id IS DISTINCT FROM operation_scope.pay_batch_id
            OR linked_transfer.pay_channel IS DISTINCT FROM operation_scope.pay_channel
            OR linked_transfer.transfer_group_key IS DISTINCT FROM operation_scope.transfer_group_key
            OR ROUND(COALESCE(linked_transfer.amount, 0), 2) IS DISTINCT FROM ROUND(COALESCE(operation_scope.amount, 0), 2)
            OR UPPER(BTRIM(COALESCE(linked_transfer.currency, 'GBP'))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(operation_scope.currency, 'GBP')))
            OR NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), '') IS NOT NULL
            OR linked_transfer.completed_at_utc IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(linked_transfer.failed_reason, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(linked_transfer.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
            OR EXISTS (
              SELECT 1
              FROM public.pay_bank_transfer_events AS transfer_event
              WHERE transfer_event.pay_batch_id = p_pay_batch_id
                AND transfer_event.pay_bank_transfer_id = linked_transfer.id
            )
          )
      )::integer,
      count(*) FILTER (WHERE linked_transfer.id IS NOT NULL AND linked_transfer.pay_batch_id IS DISTINCT FROM operation_scope.pay_batch_id)::integer,
      count(*) FILTER (WHERE linked_transfer.id IS NOT NULL AND ROUND(COALESCE(linked_transfer.amount, 0), 2) IS DISTINCT FROM ROUND(COALESCE(operation_scope.amount, 0), 2))::integer,
      count(*) FILTER (WHERE linked_transfer.id IS NOT NULL AND UPPER(BTRIM(COALESCE(linked_transfer.currency, 'GBP'))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(operation_scope.currency, 'GBP'))))::integer,
      count(*) FILTER (WHERE linked_transfer.id IS NOT NULL AND UPPER(BTRIM(COALESCE(linked_transfer.status, ''))) <> 'PENDING')::integer,
      count(*) FILTER (
        WHERE linked_transfer.id IS NOT NULL
          AND (
            NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), '') IS NOT NULL
            OR linked_transfer.completed_at_utc IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(linked_transfer.failed_reason, '')), '') IS NOT NULL
            OR UPPER(BTRIM(COALESCE(linked_transfer.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
          )
      )::integer,
      count(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'PREPARED'
          AND (
            COALESCE(operation_scope.provider_submit_ready, false) IS NOT TRUE
            OR UPPER(BTRIM(COALESCE(operation_scope.provider_submit_state, ''))) <> 'READY'
            OR COALESCE(operation_scope.provider_review_required, false) = true
            OR NULLIF(BTRIM(COALESCE(operation_scope.provider_unsafe_reason, '')), '') IS NOT NULL
          )
      )::integer,
      count(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'PREPARED'
          AND (
            NULLIF(BTRIM(COALESCE(operation_scope.prepared_scope_hash, '')), '') IS NULL
            OR NULLIF(BTRIM(COALESCE(operation_scope.prepared_result_hash, '')), '') IS NULL
          )
      )::integer,
      count(*) FILTER (
        WHERE UPPER(BTRIM(COALESCE(operation_scope.status, ''))) = 'PREPARED'
          AND ROUND(COALESCE(operation_scope.prepared_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(operation_scope.amount, 0), 2)
      )::integer,
      round(COALESCE(sum(operation_scope.amount), 0), 2)::numeric(14,2),
      round(COALESCE(sum(linked_transfer.amount), 0), 2)::numeric(14,2),
      md5(COALESCE(string_agg(
        operation_scope.id::text || ':' ||
        COALESCE(operation_scope.pay_bank_transfer_id::text, '') || ':' ||
        COALESCE(operation_scope.status, '') || ':' ||
        ROUND(COALESCE(operation_scope.amount, 0), 2)::text || ':' ||
        COALESCE(operation_scope.prepared_scope_hash, '') || ':' ||
        COALESCE(operation_scope.prepared_result_hash, ''),
        '|' ORDER BY operation_scope.id
      ), 'NO_SCOPE')) AS transfer_scope_hash
    INTO
      v_scoped_operation_scope_count,
      v_scoped_scope_prepared_count,
      v_scoped_scope_pending_count,
      v_scoped_scope_failed_count,
      v_scoped_scope_skipped_count,
      v_scoped_scope_without_transfer_count,
      v_authorisation_ready_transfer_count,
      v_unsafe_transfer_count,
      v_transfer_identity_mismatch_count,
      v_transfer_amount_mismatch_count,
      v_transfer_currency_mismatch_count,
      v_transfer_status_not_pending_count,
      v_transfer_external_state_count,
      v_scope_provider_not_ready_count,
      v_scope_prepared_hash_missing_count,
      v_scope_prepared_amount_mismatch_count,
      v_scope_amount_total,
      v_transfer_amount_total,
      v_transfer_scope_hash
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    LEFT JOIN public.pay_bank_transfers AS linked_transfer
      ON linked_transfer.id = operation_scope.pay_bank_transfer_id
     AND linked_transfer.pay_batch_id = operation_scope.pay_batch_id
    WHERE operation_scope.pay_batch_id = p_pay_batch_id
      AND operation_scope.operation_id = p_operation_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR UPPER(BTRIM(COALESCE(operation_scope.pay_channel, ''))) = v_pay_channel_scope
      );

    SELECT
      count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_item.rollup_status, ''))) NOT IN ('ROLLED_UP', 'ROLLEDUP', 'READY', 'PREPARED', 'COMPLETE', 'COMPLETED'))::integer,
      round(COALESCE(sum(scope_item.item_amount), 0), 2)::numeric(14,2)
    INTO v_scope_item_rollup_pending_count, v_scope_item_amount_total
    FROM public.banking_pay_operation_transfer_scope_items AS scope_item
    WHERE scope_item.pay_batch_id = p_pay_batch_id
      AND scope_item.operation_id = p_operation_id
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS operation_scope
        WHERE operation_scope.id = scope_item.transfer_scope_id
          AND operation_scope.pay_batch_id = scope_item.pay_batch_id
          AND operation_scope.operation_id = scope_item.operation_id
          AND (
            v_pay_channel_scope IN ('ALL', 'ANY', '*')
            OR UPPER(BTRIM(COALESCE(operation_scope.pay_channel, ''))) = v_pay_channel_scope
          )
      );

    IF v_execution_commit_state <> 'NOT_SUBMITTED'
       OR NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
       OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'EXECUTION_STATE_CONFLICT',
        'message', 'This payment batch has already crossed the execution boundary and cannot be prepared again.',
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref', v_batch_row.execution_commit_ref,
        'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END
      ));
    END IF;

    IF v_batch_status IN ('CANCELLED', 'CANCELED') THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BATCH_CANCELLED',
        'message', 'The payment batch has been cancelled.'
      ));
    ELSIF v_batch_status <> 'DRAFT' THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BATCH_STATUS_NOT_DRAFT',
        'message', 'Only a DRAFT batch can be prepared for payment execution.',
        'batch_status', v_batch_row.status
      ));
    END IF;

    IF v_candidate_count <= 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'NO_CANDIDATES',
        'message', 'The payment batch has no candidates.'
      ));
    END IF;

    IF v_item_count <= 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'NO_PAYMENT_ITEMS',
        'message', 'The payment batch has no payment items.'
      ));
    END IF;

    IF v_awaiting_net_count > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'PAYE_NET_REQUIRED',
        'message', 'PAYE net amounts are required before this batch can proceed.',
        'candidate_count', v_awaiting_net_count
      ));
    END IF;

    IF v_batch_freshness_status <> 'PASSED'
       OR v_batch_freshness_hash IS NULL
       OR COALESCE((v_batch_freshness_json->>'is_stale')::boolean, false) IS TRUE THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', CASE WHEN v_batch_freshness_status = 'STALE' THEN 'BATCH_STALE' ELSE 'FRESHNESS_REQUIRED' END,
        'message', 'Chunked freshness must pass before this payment batch can be prepared.',
        'freshness_validation_status', NULLIF(v_batch_freshness_status, ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'stale_reasons', COALESCE(v_batch_freshness_json->'stale_reasons', '[]'::jsonb),
        'diff_sample', COALESCE(v_batch_freshness_json->'diff_sample', COALESCE(v_batch_freshness_json->'diff', '[]'::jsonb))
      ));
    ELSIF v_expected_freshness_hash IS NULL THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'The payment operation does not carry a completed freshness result hash.',
        'freshness_validation_status', NULLIF(v_batch_freshness_status, ''),
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_batch_freshness_hash IS DISTINCT FROM v_expected_freshness_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'The stored freshness result does not match the operation freshness result.',
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_expected_freshness_scope_hash IS NOT NULL AND v_batch_freshness_scope_hash IS DISTINCT FROM v_expected_freshness_scope_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'The stored freshness scope does not match the operation freshness scope.',
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_batch_freshness_scope_hash,
        'freshness_result_hash', v_batch_freshness_hash
      ));
    END IF;

    IF COALESCE(v_scoped_operation_scope_count, 0) <= 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
        'message', 'No operation-scoped bank transfer groups are prepared for this payment execution attempt.',
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_pay_channel_scope
      ));
    ELSIF COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
       OR COALESCE(v_scoped_scope_pending_count, 0) > 0
       OR COALESCE(v_scoped_scope_failed_count, 0) > 0
       OR COALESCE(v_scoped_scope_skipped_count, 0) > 0
       OR COALESCE(v_scoped_scope_without_transfer_count, 0) > 0
       OR COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
       OR COALESCE(v_unsafe_transfer_count, 0) > 0
       OR COALESCE(v_scope_provider_not_ready_count, 0) > 0
       OR COALESCE(v_scope_prepared_hash_missing_count, 0) > 0
       OR COALESCE(v_scope_prepared_amount_mismatch_count, 0) > 0
       OR COALESCE(v_scope_item_rollup_pending_count, 0) > 0
       OR ROUND(COALESCE(v_scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_scope_amount_total, 0), 2)
       OR ROUND(COALESCE(v_scope_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_batch_item_amount_total, 0), 2)
       OR ROUND(COALESCE(v_scope_item_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_batch_item_amount_total, 0), 2)
       OR ROUND(COALESCE(v_transfer_amount_total, 0), 2) IS DISTINCT FROM ROUND(COALESCE(v_scope_amount_total, 0), 2) THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', CASE WHEN COALESCE(v_unsafe_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED' END,
        'message', 'Every scoped transfer group must be prepared, proofed, local-only, and linked to a safe bank transfer before authorisation can start.',
        'operation_id', p_operation_id::text,
        'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
        'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
        'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
        'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
        'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
        'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'provider_not_ready_count', COALESCE(v_scope_provider_not_ready_count, 0),
        'prepared_hash_missing_count', COALESCE(v_scope_prepared_hash_missing_count, 0),
        'prepared_amount_mismatch_count', COALESCE(v_scope_prepared_amount_mismatch_count, 0),
        'scope_item_rollup_pending_count', COALESCE(v_scope_item_rollup_pending_count, 0),
        'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
        'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
        'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
        'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2),
        'pay_channel_scope', v_pay_channel_scope
      ));
    END IF;

    IF COALESCE(v_payout_instruction_missing_count, 0) > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FROZEN_PAYOUT_INSTRUCTION_MISSING',
        'message', 'Every payable frozen batch item must have a payout instruction snapshot before authorisation can start.',
        'missing_count', COALESCE(v_payout_instruction_missing_count, 0)
      ));
    END IF;

    v_blocker_count := jsonb_array_length(v_blockers_json);
    v_warning_count := jsonb_array_length(v_warnings_json);
    v_ready := v_blocker_count = 0;
    v_all_scoped_operation_scopes_authorisation_ready := (
      COALESCE(v_scoped_operation_scope_count, 0) > 0
      AND COALESCE(v_scoped_scope_prepared_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_authorisation_ready_transfer_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_unsafe_transfer_count, 0) = 0
    );

    v_next_required_phase := CASE
      WHEN v_execution_commit_state <> 'NOT_SUBMITTED' THEN 'STOP_EXECUTION_BOUNDARY_CROSSED'
      WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers_json) AS blocker(elem) WHERE blocker.elem->>'code' IN ('BATCH_STALE','FRESHNESS_REQUIRED','FRESHNESS_REQUIRES_CHUNKED_VALIDATION','FRESHNESS_RESULT_HASH_MISMATCH','OPERATION_FRESHNESS_RESULT_HASH_MISSING')) THEN 'VALIDATE_FRESHNESS'
      WHEN v_batch_status IN ('CANCELLED', 'CANCELED') THEN 'STOP_CANCELLED'
      WHEN v_blocker_count > 0 THEN 'RESOLVE_BLOCKERS'
      ELSE 'START_AUTHORISATION'
    END;

    v_summary_json := jsonb_build_object(
      'mode', 'OPERATION_PROOF',
      'candidate_count', COALESCE(v_candidate_count, 0),
      'item_count', COALESCE(v_item_count, 0),
      'transfer_count', COALESCE(v_scoped_operation_scope_count, 0),
      'pending_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
      'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
      'provider_attempt_or_evidence_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
      'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
      'blocked_transfer_count', COALESCE(v_scoped_failed_or_blocked_transfer_count, 0),
      'prepared_transfer_proof_hash', v_transfer_scope_hash,
      'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
      'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
      'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
      'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2)
    );

    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = jsonb_strip_nulls(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'pay_batch_prepare_proof', jsonb_build_object(
              'checked_at_utc', v_now::text,
              'ready', v_ready,
              'blocker_count', v_blocker_count,
              'prepared_transfer_proof_hash', v_transfer_scope_hash,
              'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
              'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
              'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
              'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2),
              'freshness_result_hash', v_batch_freshness_hash,
              'freshness_scope_hash', v_batch_freshness_scope_hash,
              'pay_channel_scope', v_pay_channel_scope
            )
          )
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'ready', v_ready,
      'ready_flag', v_ready,
      'proof_mode', true,
      'used_operation_scope_proof', true,
      'pay_batch_prepare_skipped_full_classification', true,
      'blocker_count', v_blocker_count,
      'warning_count', v_warning_count,
      'blockers', v_blockers_json,
      'warnings', v_warnings_json,
      'next_required_phase', v_next_required_phase,
      'execution_summary', v_summary_json,
      'batch_status', v_batch_row.status,
      'execution_commit_state', v_execution_commit_state,
      'execution_mode', v_execution_mode,
      'pay_channel_scope', v_pay_channel_scope,
      'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
      'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
      'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
      'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
      'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
      'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
      'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
      'all_scoped_operation_scopes_authorisation_ready', COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false),
      'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
      'freshness', jsonb_build_object(
        'freshness_validation_status', v_batch_freshness_status,
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'freshness_result_json', v_batch_freshness_json
      ),
      'prepared_transfer_proof', jsonb_build_object(
        'prepared_transfer_proof_hash', v_transfer_scope_hash,
        'scope_amount_total', ROUND(COALESCE(v_scope_amount_total, 0), 2),
        'transfer_amount_total', ROUND(COALESCE(v_transfer_amount_total, 0), 2),
        'scope_item_amount_total', ROUND(COALESCE(v_scope_item_amount_total, 0), 2),
        'batch_item_amount_total', ROUND(COALESCE(v_batch_item_amount_total, 0), 2),
        'payout_instruction_missing_count', COALESCE(v_payout_instruction_missing_count, 0)
      ),
      'server_utc', v_now
    );
  END IF;

  v_summary_json := public.pay_batch_execution_summary_get(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id
  );

  v_execution_mode_raw := UPPER(BTRIM(COALESCE(
    v_summary_json->>'execution_mode',
    v_batch_row.execution_intent_json->>'execution_mode',
    v_batch_row.execution_intent_json->>'mode',
    'STANDARD_BANK'
  )));
  v_execution_mode := CASE
    WHEN v_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE 'STANDARD_BANK'
  END;
  v_is_local_manual_mode := v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT');

  v_candidate_count := coalesce(NULLIF(v_summary_json->>'candidate_count', '')::integer, 0);
  v_item_count := coalesce(NULLIF(v_summary_json->>'item_count', '')::integer, 0);
  v_transfer_count := coalesce(NULLIF(v_summary_json->>'transfer_count', '')::integer, 0);
  v_pending_transfer_count := coalesce(NULLIF(v_summary_json->>'pending_transfer_count', '')::integer, 0);
  v_authorisation_ready_transfer_count := coalesce(NULLIF(v_summary_json->>'authorisation_ready_transfer_count', '')::integer, 0);
  v_unattempted_submit_eligible_transfer_count := coalesce(NULLIF(v_summary_json->>'unattempted_submit_eligible_transfer_count', '')::integer, 0);
  v_remaining_unattempted_submit_required := coalesce(NULLIF(v_summary_json->>'remaining_unattempted_submit_required', '')::integer, v_unattempted_submit_eligible_transfer_count);
  v_provider_attempt_or_evidence_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_attempt_or_evidence_transfer_count', '')::integer, 0);
  v_provider_or_ambiguous_evidence_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_or_ambiguous_evidence_transfer_count', '')::integer, 0);
  v_local_only_transfer_count := coalesce(NULLIF(v_summary_json->>'local_only_transfer_count', '')::integer, 0);
  v_canonical_pending_status_transfer_count := coalesce(NULLIF(v_summary_json->>'canonical_pending_status_transfer_count', '')::integer, 0);
  v_safe_local_cleanup_transfer_count := coalesce(NULLIF(v_summary_json->>'safe_local_cleanup_transfer_count', '')::integer, 0);
  SELECT
    count(*) FILTER (WHERE classified_transfer.is_authorisation_ready)::integer,
    count(*) FILTER (WHERE classified_transfer.is_unattempted_submit_eligible)::integer,
    count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt)::integer,
    count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt OR classified_transfer.has_ambiguous_external_evidence)::integer,
    count(*) FILTER (WHERE classified_transfer.status_upper = 'PENDING')::integer,
    count(*) FILTER (
      WHERE classified_transfer.pay_bank_transfer_id IS NOT NULL
        AND classified_transfer.is_authorisation_ready IS NOT TRUE
        AND (
          classified_transfer.has_provider_submission_evidence
          OR classified_transfer.has_provider_event_evidence
          OR classified_transfer.has_provider_attempt_without_external_id
          OR classified_transfer.has_operation_submit_attempt
          OR classified_transfer.has_ambiguous_external_evidence
          OR classified_transfer.is_failed_or_blocked
          OR classified_transfer.is_terminal_or_completed
          OR classified_transfer.has_different_operation_scope
          OR classified_transfer.has_stale_auth_request_evidence
          OR classified_transfer.has_non_cancellable_auth_request
          OR NULLIF(BTRIM(COALESCE(classified_transfer.unsafe_reason, '')), '') IS NOT NULL
        )
    )::integer,
    count(*) FILTER (WHERE classified_transfer.is_failed_or_blocked IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_transfer.status_upper = 'BLOCKED'
         OR classified_transfer.rail_state_upper = 'BLOCKED'
    )::integer,
    count(DISTINCT classified_transfer.auth_request_id) FILTER (
      WHERE classified_transfer.auth_request_id IS NOT NULL
        AND classified_transfer.has_non_cancellable_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_transfer.auth_request_id) FILTER (
      WHERE classified_transfer.auth_request_id IS NOT NULL
        AND (
          classified_transfer.has_non_cancellable_auth_request IS TRUE
          OR classified_transfer.has_auth_request_provider_risk IS TRUE
          OR classified_transfer.has_other_operation_active_auth_request IS TRUE
        )
    )::integer
  INTO v_authorisation_ready_transfer_count,
       v_unattempted_submit_eligible_transfer_count,
       v_provider_attempt_or_evidence_transfer_count,
       v_provider_or_ambiguous_evidence_transfer_count,
       v_canonical_pending_status_transfer_count,
       v_unsafe_transfer_count,
       v_scoped_failed_or_blocked_transfer_count,
       v_scoped_blocked_transfer_count,
       v_non_cancellable_auth_request_count,
       v_auth_request_retry_blocker_count
  FROM public.pay_bank_transfer_execution_classify(
    p_pay_batch_id => p_pay_batch_id,
    p_pay_channel_scope => v_pay_channel_scope,
    p_operation_id => p_operation_id,
    p_include_unscoped_transfers => CASE WHEN p_operation_id IS NULL THEN true ELSE false END,
    p_action_context => 'PREPARE_ACTION'
  ) AS classified_transfer
  WHERE (
    p_operation_id IS NULL
    OR EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS scoped_operation_filter
      WHERE scoped_operation_filter.pay_batch_id = p_pay_batch_id
        AND scoped_operation_filter.operation_id = p_operation_id
        AND (
          v_pay_channel_scope IN ('ALL', 'ANY', '*')
          OR upper(btrim(coalesce(scoped_operation_filter.pay_channel, ''))) = v_pay_channel_scope
        )
        AND (
          scoped_operation_filter.id = classified_transfer.scope_id
          OR (
            classified_transfer.pay_bank_transfer_id IS NOT NULL
            AND scoped_operation_filter.pay_bank_transfer_id = classified_transfer.pay_bank_transfer_id
          )
        )
    )
  );

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PREPARED')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PENDING')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'FAILED')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'SKIPPED')::integer,
           count(*) FILTER (WHERE operation_scope.pay_bank_transfer_id IS NULL)::integer
    INTO v_scoped_operation_scope_count,
         v_scoped_scope_prepared_count,
         v_scoped_scope_pending_count,
         v_scoped_scope_failed_count,
         v_scoped_scope_skipped_count,
         v_scoped_scope_without_transfer_count
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.pay_batch_id = p_pay_batch_id
      AND operation_scope.operation_id = p_operation_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR upper(btrim(coalesce(operation_scope.pay_channel, ''))) = v_pay_channel_scope
      );

    v_all_scoped_operation_scopes_authorisation_ready := (
      COALESCE(v_scoped_operation_scope_count, 0) > 0
      AND COALESCE(v_scoped_scope_prepared_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_scoped_scope_pending_count, 0) = 0
      AND COALESCE(v_scoped_scope_failed_count, 0) = 0
      AND COALESCE(v_scoped_scope_skipped_count, 0) = 0
      AND COALESCE(v_scoped_scope_without_transfer_count, 0) = 0
      AND COALESCE(v_authorisation_ready_transfer_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) = 0
      AND COALESCE(v_non_cancellable_auth_request_count, 0) = 0
    );
  END IF;
  v_remaining_unattempted_submit_required := COALESCE(v_unattempted_submit_eligible_transfer_count, 0);
  v_failed_transfer_count := coalesce(NULLIF(v_summary_json->>'failed_transfer_count', '')::integer, 0);
  v_blocked_transfer_count := coalesce(NULLIF(v_summary_json->>'blocked_transfer_count', '')::integer, 0);
  v_submitted_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_submitted_transfer_count', '')::integer, coalesce(NULLIF(v_summary_json->>'submitted_transfer_count', '')::integer, 0));

  v_batch_freshness_status := upper(btrim(coalesce(v_batch_row.freshness_validation_status, '')));
  v_batch_freshness_hash := nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '');
  v_batch_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), '');
  v_batch_freshness_json := coalesce(v_batch_row.freshness_result_json, '{}'::jsonb);

  IF v_execution_commit_state <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has already crossed the execution boundary and cannot be prepared again.',
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_batch_row.execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END
    ));
  ELSIF v_operation_mode THEN
    IF v_batch_freshness_status <> 'PASSED' THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', CASE WHEN v_batch_freshness_status = 'STALE' THEN 'BATCH_STALE' ELSE 'FRESHNESS_REQUIRED' END,
        'message', 'Chunked freshness must pass before this payment batch can be prepared.',
        'freshness_validation_status', nullif(v_batch_freshness_status, ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'stale_reasons', coalesce(v_batch_freshness_json->'stale_reasons', '[]'::jsonb),
        'diff_sample', coalesce(v_batch_freshness_json->'diff_sample', '[]'::jsonb)
      ));
    ELSIF p_operation_id IS NOT NULL AND v_expected_freshness_hash IS NULL THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'The payment operation does not carry a completed freshness result hash.',
        'freshness_validation_status', nullif(v_batch_freshness_status, ''),
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_expected_freshness_hash IS NOT NULL AND v_batch_freshness_hash IS DISTINCT FROM v_expected_freshness_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'The stored freshness result does not match the operation freshness result.',
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_expected_freshness_scope_hash IS NOT NULL AND v_batch_freshness_scope_hash IS DISTINCT FROM v_expected_freshness_scope_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'The stored freshness scope does not match the operation freshness scope.',
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_batch_freshness_scope_hash,
        'freshness_result_hash', v_batch_freshness_hash
      ));
    END IF;
  ELSE
    v_large_batch := coalesce(v_candidate_count, 0) > 100 OR coalesce(v_item_count, 0) > 250 OR coalesce(v_transfer_count, 0) > 100;

    IF v_large_batch THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION',
        'message', 'This batch must use chunked freshness validation before payment can continue.',
        'candidate_count', v_candidate_count,
        'item_count', v_item_count,
        'transfer_count', v_transfer_count
      ));
    ELSE
      v_fresh_json := public.pay_batch_validate_freshness(
        p_pay_batch_id => p_pay_batch_id,
        p_actor_user_id => p_actor_user_id,
        p_allow_large_full_scan => false
      );
      v_is_stale := coalesce((v_fresh_json->>'is_stale')::boolean, false);

      IF v_is_stale THEN
        SELECT coalesce(jsonb_agg(diff_row.elem), '[]'::jsonb)
        INTO v_diff_sample
        FROM (
          SELECT diff_elem.elem
          FROM jsonb_array_elements(coalesce(v_fresh_json->'diff', '[]'::jsonb)) AS diff_elem(elem)
          LIMIT 20
        ) AS diff_row;

        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', CASE WHEN coalesce((v_fresh_json->>'requires_chunked_freshness')::boolean, false) THEN 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' ELSE 'BATCH_STALE' END,
          'message', CASE WHEN coalesce((v_fresh_json->>'requires_chunked_freshness')::boolean, false) THEN 'This batch must use chunked freshness validation before payment can continue.' ELSE 'The payment batch is no longer up to date and must be regenerated before payment can continue.' END,
          'stale_reasons', coalesce(v_fresh_json->'stale_reasons', '[]'::jsonb),
          'diff_sample', v_diff_sample
        ));
      END IF;
    END IF;
  END IF;

  IF v_batch_status IN ('CANCELLED', 'CANCELED') THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'BATCH_CANCELLED',
      'message', 'The payment batch has been cancelled.'
    ));
  END IF;

  IF v_candidate_count <= 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'NO_CANDIDATES',
      'message', 'The payment batch has no candidates.'
    ));
  END IF;

  IF v_item_count <= 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'NO_PAYMENT_ITEMS',
      'message', 'The payment batch has no payment items.'
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_awaiting_net_count
  FROM public.pay_batch_candidates AS batch_candidate
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id
    AND coalesce(batch_candidate.awaiting_net_amount, false) = true;

  IF v_awaiting_net_count > 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'PAYE_NET_REQUIRED',
      'message', 'PAYE net amounts are required before this batch can proceed.',
      'candidate_count', v_awaiting_net_count
    ));
  END IF;

  IF v_execution_mode = 'STANDARD_BANK' THEN
    IF v_transfer_count <= 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BANK_TRANSFERS_NOT_PREPARED',
        'message', 'Bank transfer groups must be prepared before payment authorisation can start.'
      ));
    END IF;

    IF p_operation_id IS NULL THEN
      IF v_blocked_transfer_count > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BLOCKED_TRANSFERS',
          'message', 'One or more bank transfers are blocked and must be corrected before submission.',
          'blocked_transfer_count', v_blocked_transfer_count
        ));
      END IF;

      IF v_failed_transfer_count > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'FAILED_TRANSFERS',
          'message', 'One or more bank transfers are failed and must be corrected before submission.',
          'failed_transfer_count', v_failed_transfer_count
        ));
      END IF;
    ELSE
      IF COALESCE(v_scoped_blocked_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BLOCKED_TRANSFERS',
          'message', 'One or more scoped bank transfers are blocked and must be corrected before submission.',
          'operation_id', p_operation_id::text,
          'blocked_transfer_count', COALESCE(v_scoped_blocked_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_failed_or_blocked_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'FAILED_TRANSFERS',
          'message', 'One or more scoped bank transfers are failed or blocked and must be corrected before submission.',
          'operation_id', p_operation_id::text,
          'failed_transfer_count', COALESCE(v_scoped_failed_or_blocked_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;
    END IF;

    IF p_operation_id IS NOT NULL THEN
      IF COALESCE(v_scoped_operation_scope_count, 0) <= 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
          'message', 'No operation-scoped bank transfer groups are prepared for this payment execution attempt.',
          'operation_id', p_operation_id::text,
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         OR COALESCE(v_scoped_scope_pending_count, 0) > 0
         OR COALESCE(v_scoped_scope_failed_count, 0) > 0
         OR COALESCE(v_scoped_scope_skipped_count, 0) > 0
         OR COALESCE(v_scoped_scope_without_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED',
          'message', 'Every scoped transfer group must be prepared and linked to a safe local bank transfer before authorisation can start.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
          'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
          'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
          'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
          'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
          'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment execution attempt.',
          'operation_id', p_operation_id::text,
          'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
          'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED',
          'message', 'One or more scoped bank transfers have provider submission evidence or ambiguous provider state and must be reviewed before this batch can be authorised again.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
          'batch_submitted_transfer_count', COALESCE(v_submitted_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_operation_scope_count, 0) > 0
         AND COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         AND COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) = 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'NO_AUTHORISATION_READY_TRANSFERS',
          'message', 'All scoped bank transfer groups must be authorisation-ready before authorisation can start.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'safe_local_cleanup_transfer_count', COALESCE(v_safe_local_cleanup_transfer_count, 0),
          'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;
    END IF;

    IF p_operation_id IS NULL AND COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
        'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment batch.',
        'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
        'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    END IF;

    IF p_operation_id IS NULL AND v_provider_or_ambiguous_evidence_transfer_count > 0 AND v_transfer_count > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED',
        'message', 'One or more bank transfers have provider submission evidence or ambiguous provider state and must be reviewed before this batch can be authorised again.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
        'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'submitted_transfer_count', COALESCE(v_submitted_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    ELSIF p_operation_id IS NULL AND v_authorisation_ready_transfer_count <= 0 AND v_transfer_count > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'NO_AUTHORISATION_READY_TRANSFERS',
        'message', 'No safe locally prepared bank transfers are available for authorisation.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
        'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
        'safe_local_cleanup_transfer_count', COALESCE(v_safe_local_cleanup_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    ELSIF v_pending_transfer_count <= 0 AND v_authorisation_ready_transfer_count > 0 THEN
      v_warnings_json := v_warnings_json || jsonb_build_array(jsonb_build_object(
        'code', 'EVIDENCE_PENDING_COUNT_ZERO_AUTHORISATION_READY_PRESENT',
        'message', 'Evidence pending count is zero, but safe local transfers are ready for authorisation.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'evidence_pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    END IF;
  END IF;

  v_blocker_count := jsonb_array_length(v_blockers_json);
  v_warning_count := jsonb_array_length(v_warnings_json);
  v_ready := v_blocker_count = 0;

  v_next_required_phase := CASE
    WHEN v_execution_commit_state <> 'NOT_SUBMITTED' THEN 'STOP_EXECUTION_BOUNDARY_CROSSED'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers_json) AS blocker(elem) WHERE blocker.elem->>'code' IN ('BATCH_STALE','FRESHNESS_REQUIRED','FRESHNESS_REQUIRES_CHUNKED_VALIDATION','FRESHNESS_RESULT_HASH_MISMATCH')) THEN 'VALIDATE_FRESHNESS'
    WHEN v_batch_status IN ('CANCELLED', 'CANCELED') THEN 'STOP_CANCELLED'
    WHEN v_is_local_manual_mode AND v_ready THEN 'START_AUTHORISATION'
    WHEN v_transfer_count <= 0 THEN 'PREPARE_TRANSFER_SCOPE'
    WHEN v_blocker_count > 0 THEN 'RESOLVE_BLOCKERS'
    WHEN v_execution_mode IN ('STANDARD_BANK', 'BANK') AND p_operation_id IS NOT NULL AND COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false) IS NOT TRUE THEN 'RESOLVE_BLOCKERS'
    WHEN v_execution_mode IN ('STANDARD_BANK', 'BANK') AND v_authorisation_ready_transfer_count <= 0 THEN 'RESOLVE_BLOCKERS'
    ELSE 'START_AUTHORISATION'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'ready', v_ready,
    'ready_flag', v_ready,
    'blocker_count', v_blocker_count,
    'warning_count', v_warning_count,
    'blockers', v_blockers_json,
    'warnings', v_warnings_json,
    'next_required_phase', v_next_required_phase,
    'execution_summary', v_summary_json,
    'batch_status', v_batch_row.status,
    'execution_commit_state', v_execution_commit_state,
    'execution_mode', v_execution_mode,
    'pay_channel_scope', v_pay_channel_scope,
    'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
    'provider_submission_attempted', false,
    'submitted_to_bank', false,
    'local_settlement_evidence_only', v_is_local_manual_mode,
    'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
    'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
    'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
    'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
    'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
    'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
    'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
    'all_scoped_operation_scopes_authorisation_ready', COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false),
    'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
    'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
    'unattempted_submit_eligible_transfer_count', COALESCE(v_unattempted_submit_eligible_transfer_count, 0),
    'remaining_unattempted_submit_required', COALESCE(v_remaining_unattempted_submit_required, 0),
    'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
    'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
    'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
    'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
    'scoped_failed_or_blocked_transfer_count', COALESCE(v_scoped_failed_or_blocked_transfer_count, 0),
    'scoped_blocked_transfer_count', COALESCE(v_scoped_blocked_transfer_count, 0),
    'evidence_pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
    'freshness', jsonb_build_object(
      'freshness_validation_status', v_batch_freshness_status,
      'freshness_result_hash', v_batch_freshness_hash,
      'freshness_scope_hash', v_batch_freshness_scope_hash,
      'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
      'expected_freshness_result_hash', v_expected_freshness_hash,
      'freshness_result_json', v_batch_freshness_json
    ),
    'schedule_state', coalesce(v_summary_json->'schedule_state', '{}'::jsonb),
    'authorisation_state', coalesce(v_summary_json->'authorisation_state', '{}'::jsonb),
    'blocked_funds_state', coalesce(v_summary_json->'blocked_funds_state', '{}'::jsonb),
    'settlement_state', coalesce(v_summary_json->'settlement_state', '{}'::jsonb),
    'remittance_state', coalesce(v_summary_json->'remittance_state', '{}'::jsonb),
    'server_utc', v_now
  );
END;
$function$;

-- pay_batch_schedule(uuid,text,timestamp with time zone,text,jsonb,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_batch_schedule(p_pay_batch_id uuid, p_schedule_kind text, p_scheduled_at_utc timestamp with time zone, p_funding_account_ref text, p_warning_hours_json jsonb, p_actor_user_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_freshness_result_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
declare
  v_kind text := upper(btrim(coalesce(p_schedule_kind,'')));
  v_batch record;
  v_cfg record;

  v_provider text := null;

  v_sched_at timestamptz;
  v_warn jsonb;
  v_authoritative_payment_date date;
  v_commit_ts timestamptz := now();

  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_funding text := nullif(btrim(coalesce(p_funding_account_ref,'')), '');

  v_missing_bank int := 0;
  v_blocked_name int := 0;
  v_missing_map int := 0;
  v_pending_transfers int := 0;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_batch_kind_fixed text := null;
  v_bad_loans_payee_ct int := 0;

  v_reservations_committed_count int := 0;
  v_reservations_committed_amount numeric := 0;

  v_worker_communications jsonb := '{}'::jsonb;
  v_comm_result jsonb := '{}'::jsonb;
  v_comm_error text := null;
  v_comm_trigger_status text := null;
  v_comm_message_kind text := null;

  v_payout_notice_result jsonb := '{}'::jsonb;
  v_payout_notice_trigger_status text := null;
  v_payout_notice_error text := null;
  v_payout_notice_dispatch_required boolean := false;
  v_payout_notice_targeted_count int := 0;

  v_remittance_result jsonb := '{}'::jsonb;
  v_remittance_trigger_status text := null;
  v_remittance_error text := null;
  v_remittance_dispatch_required boolean := false;
  v_remittance_targeted_count int := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_execution_intent_json jsonb := '{}'::jsonb;
  v_execution_mode text := 'STANDARD_BANK';
  v_suppress_remittances boolean := false;
  v_has_external_submission_evidence boolean := false;
  v_submission_evidence_json jsonb := '{}'::jsonb;
  v_intent_payment_date date := null;
  v_batch_status_upper text := null;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_mode boolean := false;
  v_expected_freshness_hash text := null;
  v_expected_freshness_scope_hash text := null;
  v_stored_freshness_status text := null;
  v_stored_freshness_hash text := null;
  v_stored_freshness_scope_hash text := null;
  v_timing_setting_if_known text := null;
  v_mutation_guard jsonb := '{}'::jsonb;
  v_current_active_scope_hash text := null::text;
begin
  PERFORM public.banking_pay_hot_path_budget_apply('OPERATION_ADVANCE');

  if p_pay_batch_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_schedule: pay_batch_id is required'
    )::text;
  end if;
  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_schedule: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_kind not in ('IMMEDIATE','SCHEDULED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'INVALID_SCHEDULE_KIND',
      'message', 'pay_batch_schedule: invalid schedule_kind (IMMEDIATE|SCHEDULED)',
      'schedule_kind', v_kind,
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_mutation_guard := private.pay_payment_mutation_guard_v1(
    p_pay_batch_id,
    NULL::uuid,
    'NEW_PAYMENT_ACTION'
  );

  if coalesce((v_mutation_guard->>'blocked')::boolean, true) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', coalesce(
        v_mutation_guard->>'code',
        'PAYMENT_CHANGE_IN_PROGRESS'
      ),
      'message', coalesce(
        v_mutation_guard->>'message',
        'A payment change is in progress.'
      ),
      'pay_batch_id', p_pay_batch_id
    )::text using errcode = 'P0001';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.schedule_kind,
    pb.scheduled_at_utc,
    pb.scheduled_by_user_id,
    pb.funding_account_ref,
    pb.funds_warning_hours_json,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.source_workbench_session_id,
    pb.source_snapshot_run_id,
    pb.source_session_version
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_schedule: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_execution_commit_state <> 'NOT_SUBMITTED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_batch_schedule: batch has already crossed the execution submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_batch_kind_fixed := upper(btrim(coalesce(v_batch.batch_kind_fixed,'')));
  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));

  if v_batch_status_upper in ('COMMITTED','PAID','SETTLED','CANCELLED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'BATCH_NOT_SCHEDULABLE',
      'message', 'pay_batch_schedule: batch status cannot be scheduled or authorised',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    select pbar_intent.execution_intent_json
    into v_execution_intent_json
    from public.pay_batch_auth_requests pbar_intent
    where pbar_intent.pay_batch_id = p_pay_batch_id
      and pbar_intent.state in ('AWAITING','AUTHORISED')
      and pbar_intent.execution_intent_json is not null
    order by pbar_intent.created_at_utc desc, pbar_intent.id desc
    limit 1;

    if v_execution_intent_json is null or jsonb_typeof(v_execution_intent_json) <> 'object' then
      v_execution_intent_json := '{}'::jsonb;
    end if;
  end if;

  v_execution_mode := upper(btrim(coalesce(v_execution_intent_json->>'execution_mode', 'STANDARD_BANK')));
  if v_execution_mode = '' then
    v_execution_mode := 'STANDARD_BANK';
  end if;
  if v_execution_mode not in ('STANDARD_BANK','CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'INVALID_EXECUTION_MODE',
      'message', 'pay_batch_schedule: invalid frozen execution_mode',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_mode', v_execution_mode
    )::text;
  end if;

  v_current_active_scope_hash := private.pay_payment_correction_sha256_v1(
    jsonb_build_object(
      'version', 1,
      'pay_batch_id', p_pay_batch_id,
      'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
      'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
      'active_items', (
        select coalesce(
          jsonb_agg(
            jsonb_build_array(
              candidate_row.id,
              item_row.id,
              round(coalesce(item_row.amount_inc_vat, 0) * 100)::bigint,
              item_row.item_type,
              item_row.pay_channel,
              item_row.reservation_id,
              item_row.finance_component_id,
              item_row.pay_bank_transfer_id
            )
            order by candidate_row.id, item_row.id
          ),
          '[]'::jsonb
        )
        from public.pay_batch_candidates as candidate_row
        join public.pay_batch_items as item_row
          on item_row.pay_batch_candidate_id = candidate_row.id
        where candidate_row.pay_batch_id = p_pay_batch_id
          and coalesce(item_row.is_voided, false) is not true
      )
    )
  );

  if nullif(btrim(coalesce(v_execution_intent_json->>'active_scope_hash', '')), '') is not null
     and v_execution_intent_json->>'active_scope_hash' is distinct from v_current_active_scope_hash then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'REAUTHORISATION_REQUIRED',
      'message', 'The authorised payment scope has changed and must be reviewed again.',
      'pay_batch_id', p_pay_batch_id
    )::text using errcode = 'P0001';
  end if;

  v_execution_intent_json := v_execution_intent_json || jsonb_build_object(
    'active_scope_hash', v_current_active_scope_hash
  );

  v_suppress_remittances := lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) in ('true','1','yes','y','on');

  if nullif(btrim(coalesce(v_execution_intent_json->>'payment_date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_intent_payment_date := (v_execution_intent_json->>'payment_date')::date;
  else
    v_intent_payment_date := null;
  end if;

  v_operation_mode := p_operation_id IS NOT NULL OR nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL;

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_remittance_send_timing), ''), 'ON_EXECUTION')
  INTO v_timing_setting_if_known
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_timing_setting_if_known := upper(coalesce(nullif(btrim(v_timing_setting_if_known), ''), 'ON_EXECUTION'));

  IF v_timing_setting_if_known NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    v_timing_setting_if_known := 'ON_EXECUTION';
  END IF;

  v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_stored_freshness_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');

  if p_operation_id is not null then
    select operation_row.*
    into v_operation_row
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
    for update;

    if not found then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_batch_schedule: operation was not found',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    end if;

    if v_operation_row.pay_batch_id is not null and v_operation_row.pay_batch_id <> p_pay_batch_id then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_batch_schedule: operation belongs to another batch',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_operation_row.pay_batch_id::text
      )::text;
    end if;

    if v_operation_row.actor_user_id is not null and v_operation_row.actor_user_id <> p_actor_user_id then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_ACTOR_MISMATCH',
        'message', 'pay_batch_schedule: operation belongs to another actor',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    end if;

    v_expected_freshness_hash := coalesce(
      nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_result_hash}', '')), '')
    );
    v_expected_freshness_scope_hash := coalesce(
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_scope_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_scope_hash}', '')), '')
    );
  else
    v_expected_freshness_hash := nullif(btrim(coalesce(p_freshness_result_hash, '')), '');
  end if;

  if v_operation_mode then
    if v_stored_freshness_status <> 'PASSED' then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_NOT_PASSED',
        'message', 'pay_batch_schedule: completed passing chunked freshness is required before scheduling',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;

    if p_operation_id is not null and v_expected_freshness_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'pay_batch_schedule: operation mode requires the operation to carry the completed freshness result hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;

    if v_expected_freshness_hash is not null and v_stored_freshness_hash is distinct from v_expected_freshness_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'pay_batch_schedule: operation freshness hash does not match stored batch freshness hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_stored_freshness_hash
      )::text;
    end if;

    if v_expected_freshness_scope_hash is not null and v_stored_freshness_scope_hash is distinct from v_expected_freshness_scope_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'pay_batch_schedule: operation freshness scope hash does not match stored batch freshness scope hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;
  else
    v_fresh := public.pay_batch_validate_freshness(
      p_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id,
      p_allow_large_full_scan => false
    );
    v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
    v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

    if v_is_stale = true then
      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
        into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      begin
        perform public._imp_debug_audit(
          p_actor_user_id,
          'PAY_BATCH_SCHEDULE:STALE',
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'stale_reasons', v_stale_reasons,
            'diff_sample', v_diff_sample
          ),
          'pay_batches',
          p_pay_batch_id::text
        );
      exception when others then
        null;
      end;

      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
        'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_batch_schedule: chunked freshness validation is required before proceeding' else 'pay_batch_schedule: batch is stale; regenerate draft before proceeding' end,
        'pay_batch_id', p_pay_batch_id::text,
        'stale_reasons', v_stale_reasons,
        'diff', v_diff_sample
      )::text;
    end if;
  end if;

  v_provider := upper(btrim(coalesce(v_batch.rail_provider_snapshot,'')));
  if v_provider = 'REV' then
    v_provider := 'REVOLUT';
  end if;
  if v_provider = '' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'RAIL_PROVIDER_MISSING_ON_BATCH',
      'message', 'pay_batch_schedule: rail_provider_snapshot missing on batch; blank provider is not treated as CSV',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_provider not in ('REVOLUT','CSV') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'UNKNOWN_RAIL_PROVIDER',
      'message', 'pay_batch_schedule: unsupported rail_provider_snapshot',
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select
    sd.funds_warning_hours_json,
    sd.rail_supports_name_check,
    sd.rail_supports_scheduling,
    sd.rail_default_funding_account_ref
  into v_cfg
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cfg.funds_warning_hours_json is null
     and v_cfg.rail_supports_name_check is null
     and v_cfg.rail_supports_scheduling is null
     and v_cfg.rail_default_funding_account_ref is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_batch_schedule: settings_defaults missing (id=1)',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  if v_execution_mode <> 'STANDARD_BANK' then
    v_warn := coalesce(p_warning_hours_json, coalesce(v_cfg.funds_warning_hours_json, '[]'::jsonb));
    if v_warn is not null and jsonb_typeof(v_warn) <> 'array' then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'WARNING_HOURS_JSON_INVALID',
        'message', 'pay_batch_schedule: warning_hours_json must be a JSON array',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode
      )::text;
    end if;

    if v_kind = 'IMMEDIATE' then
      v_sched_at := now();
    else
      if p_scheduled_at_utc is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_SCHEDULE',
          'code', 'SCHEDULED_AT_REQUIRED',
          'message', 'pay_batch_schedule: scheduled_at_utc is required when schedule_kind=SCHEDULED',
          'pay_batch_id', p_pay_batch_id::text,
          'schedule_kind', v_kind,
          'execution_mode', v_execution_mode
        )::text;
      end if;
      v_sched_at := p_scheduled_at_utc;
    end if;

    v_authoritative_payment_date := coalesce(
      v_intent_payment_date,
      (v_sched_at at time zone 'Europe/London')::date,
      v_batch.authoritative_payment_date,
      v_batch.pay_date
    );

    select count(*)::int
    into v_pending_transfers
    from public.pay_bank_transfers pbt_non_native_pending
    where pbt_non_native_pending.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_non_native_pending.status,'')) = 'PENDING';

    if v_pending_transfers = 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'NO_PENDING_TRANSFERS',
        'message', 'pay_batch_schedule: no PENDING transfers exist for this batch (execute-bank required first)',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode,
        'ui_hint', 'RERUN_PREVIEW_OR_EXECUTE_BANK'
      )::text;
    end if;

    if v_batch_kind_fixed = 'LOANS' then
      select count(*)::int
      into v_bad_loans_payee_ct
      from public.pay_bank_transfers pbt_non_native_loans
      where pbt_non_native_loans.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt_non_native_loans.status,'')) = 'PENDING'
        and upper(
          coalesce(
            pbt_non_native_loans.payee_entity_kind,
            case
              when upper(coalesce(pbt_non_native_loans.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA'
              else 'CANDIDATE'
            end
          )
        ) <> 'CANDIDATE';

      if v_bad_loans_payee_ct > 0 then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
          'code', 'LOANS_PAYEE_MUST_BE_CANDIDATE',
          'message', 'pay_batch_schedule: LOANS batches must pay candidates (not umbrellas)',
          'pay_batch_id', p_pay_batch_id::text,
          'bad_transfer_count', v_bad_loans_payee_ct,
          'execution_mode', v_execution_mode,
          'ui_hint', 'REGENERATE_TRANSFERS_AS_CANDIDATE_PAYEES'
        )::text;
      end if;
    end if;

    v_submission_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id);
    v_has_external_submission_evidence := coalesce((v_submission_evidence_json->>'has_external_submission_evidence')::boolean, false);

    if v_has_external_submission_evidence = true then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'EXTERNAL_SUBMISSION_EXISTS',
        'message', 'pay_batch_schedule: CSV/external settlement cannot be scheduled after native rail submission evidence exists',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode
      )::text;
    end if;

    update public.pay_batches pb_non_native
    set
      schedule_kind = v_kind,
      scheduled_at_utc = v_sched_at,
      scheduled_by_user_id = p_actor_user_id,
      funding_account_ref = v_funding,
      funds_warning_hours_json = v_warn,
      authoritative_payment_date = v_authoritative_payment_date,
      authoritative_payment_date_source = 'EXECUTION_INTENT_PAYMENT_DATE',
      execution_intent_json = coalesce(v_execution_intent_json, '{}'::jsonb) || jsonb_build_object(
        'execution_mode', v_execution_mode,
        'payment_date', v_authoritative_payment_date::text,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'suppress_remittances', v_suppress_remittances,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      ),
      execution_commit_state = coalesce(nullif(btrim(coalesce(pb_non_native.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    where pb_non_native.id = p_pay_batch_id;

    begin
      v_comm_result := public.pay_remittance_maybe_queue_for_trigger(
        p_pay_batch_id => p_pay_batch_id,
        p_trigger => 'ON_EXECUTION',
        p_scope => 'ALL',
        p_actor_user_id => p_actor_user_id,
        p_only_confirmed => false,
        p_root_operation_id => CASE WHEN v_operation_mode THEN p_operation_id ELSE NULL::uuid END,
        p_operation_mode => v_operation_mode
      );

      if coalesce((v_comm_result->>'ok')::boolean, true) = false then
        raise exception '%', coalesce(
          nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
          nullif(btrim(coalesce(v_comm_result #>> '{queue_result,error}','')), ''),
          'pay_batch_schedule: remittance/payout notice queue timing gate failed'
        );
      end if;

      v_comm_message_kind := coalesce(
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,message_kind}', '')), ''),
        case when v_batch_kind_fixed in ('LOANS','LOAN','FINANCE_PAYOUTS','PAYOUTS') then 'PAYOUT_NOTICE' else 'REMITTANCE' end
      );

      v_comm_trigger_status := coalesce(
        nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,trigger_status}', '')), ''),
        case
          when lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_DEFERRED_BY_TIMING'
          when lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on') then 'SUPPRESSED_BY_EXECUTION_INTENT'
          when lower(btrim(coalesce(v_comm_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on') then 'QUEUE_STAGE_BUILD_READY'
          else 'NO_QUEUEABLE_REMITTANCE_OR_PAYOUT_NOTICE_JOB'
        end
      );

      v_comm_error := coalesce(
        nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,error}','')), '')
      );

      if upper(coalesce(v_comm_message_kind, '')) = 'PAYOUT_NOTICE' then
        v_payout_notice_result := coalesce(v_comm_result->'queue_result', v_comm_result);
        v_remittance_result := jsonb_build_object(
          'ok', true,
          'trigger_status', 'NOT_APPLICABLE_FOR_FINANCE_PAYOUT_BATCH',
          'message_kind', 'REMITTANCE',
          'automatic_commit_stage', true,
          'dispatch_required', false,
          'pay_batch_id', p_pay_batch_id::text,
          'scope', 'ALL'
        );
        v_payout_notice_trigger_status := v_comm_trigger_status;
        v_payout_notice_error := v_comm_error;
        v_payout_notice_dispatch_required := lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_payout_notice_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on');
        v_remittance_trigger_status := 'NOT_APPLICABLE_FOR_FINANCE_PAYOUT_BATCH';
        v_remittance_error := null;
        v_remittance_dispatch_required := false;
        if btrim(coalesce(v_payout_notice_result->>'candidate_count_targeted', '')) ~ '^[0-9]+$' then
          v_payout_notice_targeted_count := (v_payout_notice_result->>'candidate_count_targeted')::int;
        else
          v_payout_notice_targeted_count := 0;
        end if;
        v_remittance_targeted_count := 0;
      else
        v_remittance_result := coalesce(v_comm_result->'queue_result', v_comm_result);
        v_payout_notice_result := jsonb_build_object(
          'ok', true,
          'trigger_status', 'NOT_APPLICABLE_FOR_STANDARD_PAY_BATCH',
          'message_kind', 'PAYOUT_NOTICE',
          'automatic_commit_stage', true,
          'dispatch_required', false,
          'pay_batch_id', p_pay_batch_id::text
        );
        v_remittance_trigger_status := v_comm_trigger_status;
        v_remittance_error := v_comm_error;
        v_remittance_dispatch_required := lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_remittance_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on');
        v_payout_notice_trigger_status := 'NOT_APPLICABLE_FOR_STANDARD_PAY_BATCH';
        v_payout_notice_error := null;
        v_payout_notice_dispatch_required := false;
        if btrim(coalesce(v_remittance_result->>'candidate_count_targeted', '')) ~ '^[0-9]+$' then
          v_remittance_targeted_count := (v_remittance_result->>'candidate_count_targeted')::int;
        else
          v_remittance_targeted_count := 0;
        end if;
        v_payout_notice_targeted_count := 0;
      end if;
    exception when others then
      v_comm_trigger_status := 'COMMIT_STAGE_QUEUE_TIMING_GATE_ERROR';
      v_comm_error := left(coalesce(SQLERRM, 'UNKNOWN_COMMS_ERROR'), 1000);
      v_comm_message_kind := coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE');
      v_payout_notice_result := jsonb_build_object(
        'ok', false,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', 'PAYOUT_NOTICE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id::text
      );
      v_remittance_result := jsonb_build_object(
        'ok', false,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', 'REMITTANCE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL'
      );
      v_payout_notice_dispatch_required := false;
      v_remittance_dispatch_required := false;
      v_payout_notice_targeted_count := 0;
      v_remittance_targeted_count := 0;
      v_comm_result := jsonb_build_object(
        'ok', false,
        'trigger', 'ON_EXECUTION',
        'configured_timing', v_timing_setting_if_known,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', v_comm_message_kind,
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'operation_id', NULL::text,
        'deferred', false,
        'suppressed', false,
        'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
        'remittance', coalesce(v_remittance_result, '{}'::jsonb),
        'queue_result', jsonb_build_object(
          'ok', false,
          'trigger', 'ON_EXECUTION',
          'configured_timing', v_timing_setting_if_known,
          'trigger_status', v_comm_trigger_status,
          'error', v_comm_error,
          'operation_id', NULL::text,
          'deferred', false,
          'suppressed', false
        ),
        'execution_mode', v_execution_mode
      );
    end;

    v_comm_result := coalesce(v_comm_result, '{}'::jsonb) || jsonb_build_object(
      'trigger', coalesce(nullif(btrim(coalesce(v_comm_result->>'trigger', '')), ''), 'ON_EXECUTION'),
      'configured_timing', coalesce(nullif(btrim(coalesce(v_comm_result->>'configured_timing', '')), ''), nullif(btrim(coalesce(v_comm_result#>>'{queue_result,configured_timing}', '')), ''), v_timing_setting_if_known),
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb)
    );

    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', true,
      'message_kind', coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'dispatch_required', (v_payout_notice_dispatch_required = true or v_remittance_dispatch_required = true),
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
      'result', coalesce(v_comm_result, '{}'::jsonb),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances
    );

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:NON_NATIVE_MODE_OK',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'execution_mode', v_execution_mode,
          'schedule_kind', v_kind,
          'scheduled_at_utc', v_sched_at::text,
          'authoritative_payment_date', v_authoritative_payment_date::text,
          'pending_transfers', v_pending_transfers,
          'worker_communications', v_worker_communications
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    return jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'status', (select pb_non_native_ret.status from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'schedule_kind', v_kind,
      'scheduled_at_utc', v_sched_at::text,
      'authoritative_payment_date', v_authoritative_payment_date::text,
      'authoritative_payment_date_source', 'EXECUTION_INTENT_PAYMENT_DATE',
      'funding_account_ref', v_funding,
      'funds_warning_hours_json', v_warn,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot,
      'rail_env_snapshot', v_batch.rail_env_snapshot,
      'execution_mode', v_execution_mode,
      'execution_intent_json', (select pb_non_native_ret.execution_intent_json from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_commit_state', (select pb_non_native_ret.execution_commit_state from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_commit_ref', (select pb_non_native_ret.execution_commit_ref from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb_non_native_ret.execution_committed_at_utc is null then null else pb_non_native_ret.execution_committed_at_utc::text end from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'finance_reservations', jsonb_build_object(
        'committed_count', 0,
        'committed_amount', 0
      ),
      'remittance_trigger', 'ON_EXECUTION',
      'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
      'remittance_deferred', lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on'),
      'remittance_suppressed', lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on'),
      'remittance_operation_queued', lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on'),
      'remittance_child_operation_id', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'operation_id', '')), ''),
        nullif(btrim(coalesce(v_comm_result#>>'{queue_result,operation_id}', '')), '')
      ),
      'remittance_trigger_status', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
        nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}', '')), ''),
        v_comm_trigger_status
      ),
      'remittance_message_kind', v_comm_message_kind,
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb)
    );
  end if;

  if v_provider = 'CSV' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SCHEDULING_NOT_SUPPORTED_FOR_MANUAL_RAIL',
      'message', format('pay_batch_schedule: scheduling is not supported for manual rail_provider_snapshot=%s', v_batch.rail_provider_snapshot),
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  if coalesce(v_cfg.rail_supports_scheduling,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SCHEDULING_DISABLED_IN_SETTINGS',
      'message', 'pay_batch_schedule: scheduling is not enabled in settings_defaults (rail_supports_scheduling=false)',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_need_name_check := (coalesce(v_cfg.rail_supports_name_check,false) = true);
  v_requires_payee_map := true;

  v_warn := coalesce(p_warning_hours_json, v_cfg.funds_warning_hours_json);
  if v_warn is not null and jsonb_typeof(v_warn) <> 'array' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'WARNING_HOURS_JSON_INVALID',
      'message', 'pay_batch_schedule: warning_hours_json must be a JSON array',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  if v_kind = 'IMMEDIATE' then
    v_sched_at := now();
  else
    if p_scheduled_at_utc is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'SCHEDULED_AT_REQUIRED',
        'message', 'pay_batch_schedule: scheduled_at_utc is required when schedule_kind=SCHEDULED',
        'pay_batch_id', p_pay_batch_id::text,
        'schedule_kind', v_kind
      )::text;
    end if;
    v_sched_at := p_scheduled_at_utc;
  end if;

  v_authoritative_payment_date := (v_sched_at at time zone 'Europe/London')::date;

  if v_funding is null then
    v_funding := nullif(btrim(coalesce(v_cfg.rail_default_funding_account_ref,'')), '');
  end if;
  if v_funding is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'FUNDING_ACCOUNT_REQUIRED',
      'message', format('pay_batch_schedule: funding_account_ref is required for this rail (provider=%s)', v_batch.rail_provider_snapshot),
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select count(*)::int
  into v_pending_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) = 'PENDING';

  if v_pending_transfers = 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'NO_PENDING_TRANSFERS',
      'message', 'pay_batch_schedule: no PENDING transfers exist for this batch (execute-bank required first)',
      'pay_batch_id', p_pay_batch_id::text,
      'ui_hint', 'RERUN_PREVIEW_OR_EXECUTE_BANK'
    )::text;
  end if;

  if v_batch_kind_fixed = 'LOANS' then
    select count(*)::int
    into v_bad_loans_payee_ct
    from public.pay_bank_transfers pbt2
    where pbt2.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt2.status,'')) = 'PENDING'
      and upper(
        coalesce(
          pbt2.payee_entity_kind,
          case
            when upper(coalesce(pbt2.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA'
            else 'CANDIDATE'
          end
        )
      ) <> 'CANDIDATE';

    if v_bad_loans_payee_ct > 0 then
      begin
        perform public._imp_debug_audit(
          p_actor_user_id,
          'PAY_BATCH_SCHEDULE:BLOCKED_LOANS_PAYEE_KIND',
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'bad_transfer_count', v_bad_loans_payee_ct
          ),
          'pay_batches',
          p_pay_batch_id::text
        );
      exception when others then
        null;
      end;

      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
        'code', 'LOANS_PAYEE_MUST_BE_CANDIDATE',
        'message', 'pay_batch_schedule: LOANS batches must pay candidates (not umbrellas)',
        'pay_batch_id', p_pay_batch_id::text,
        'bad_transfer_count', v_bad_loans_payee_ct,
        'ui_hint', 'REGENERATE_TRANSFERS_AS_CANDIDATE_PAYEES'
      )::text;
    end if;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(case when t.bank_hash is null or btrim(t.bank_hash) = '' then 1 else 0 end)::int
  into v_missing_bank
  from t;

  if v_missing_bank > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_BANK_DETAILS',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_missing_bank
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_BANK_DETAILS',
      'message', format('pay_batch_schedule: BLOCKED_BANK_DETAILS for %s payee(s)', v_missing_bank::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_missing_bank,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(
      case
        when v_need_name_check = true then
          case
            when coalesce(bnc.status,'UNVERIFIED') = 'PASS' then 0
            when (bnc.override_reason is not null and bnc.override_hash = t.bank_hash) then 0
            else 1
          end
        else 0
      end
    )::int
  into v_blocked_name
  from t
  left join public.bank_name_checks bnc
    on bnc.rail_provider = v_batch.rail_provider_snapshot
   and bnc.rail_env = v_batch.rail_env_snapshot
   and bnc.entity_kind = t.payee_kind
   and bnc.entity_id = t.payee_id
   and bnc.bank_details_hash = t.bank_hash;

  if v_blocked_name > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_NAME_CHECK',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_blocked_name
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_NAME_CHECK',
      'message', format('pay_batch_schedule: BLOCKED_NAME_CHECK for %s payee(s)', v_blocked_name::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_blocked_name,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(
      case
        when v_requires_payee_map = true then
          case when bpm.payee_id is null then 1 else 0 end
        else 0
      end
    )::int
  into v_missing_map
  from t
  left join public.bank_payee_map bpm
    on bpm.rail_provider = v_batch.rail_provider_snapshot
   and bpm.rail_env = v_batch.rail_env_snapshot
   and bpm.entity_kind = t.payee_kind
   and bpm.entity_id = t.payee_id
   and bpm.bank_details_hash = t.bank_hash;

  if v_missing_map > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_NO_PAYEE_MAP',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_missing_map
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_NO_PAYEE_MAP',
      'message', format('pay_batch_schedule: BLOCKED_NO_PAYEE_MAP for %s payee(s)', v_missing_map::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_missing_map,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  update public.pay_batches pb
  set
    schedule_kind = v_kind,
    scheduled_at_utc = v_sched_at,
    scheduled_by_user_id = p_actor_user_id,
    funding_account_ref = v_funding,
    funds_warning_hours_json = v_warn,
    authoritative_payment_date = v_authoritative_payment_date,
    authoritative_payment_date_source = 'SCHEDULED_AT_UTC',
    pay_date = v_authoritative_payment_date,
    status = 'SCHEDULED',
    execution_commit_state = v_execution_commit_state,
    execution_commit_ref = v_execution_commit_ref,
    execution_committed_at_utc = v_execution_committed_at_utc,
    execution_intent_json = coalesce(v_execution_intent_json, '{}'::jsonb) || jsonb_build_object(
      'execution_mode', v_execution_mode,
      'payment_date', v_authoritative_payment_date::text,
      'schedule_kind', v_kind,
      'scheduled_at_utc', case when v_sched_at is null then null else v_sched_at::text end,
      'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
      'freshness_result_hash', v_stored_freshness_hash,
      'freshness_scope_hash', v_stored_freshness_scope_hash
    )
  where pb.id = p_pay_batch_id;

  -- Scheduling is the second half of the same provider-unsubmitted execution
  -- overlay that linked the frozen batch items to their local transfer rows.
  -- Preserve ordinary dirtying, but give the exact reservation/event statement
  -- triggers a transaction-local, operation-owned scope they can prove.  A
  -- missing or partial context never blocks execution; it merely leaves the
  -- later cancellation proof ineligible for certified fast reversion.
  DROP TABLE IF EXISTS pg_temp._bpay_wb_unsent_execution_schedule_context_v2;
  CREATE TEMPORARY TABLE pg_temp._bpay_wb_unsent_execution_schedule_context_v2 (
    contract_version text NOT NULL,
    execution_operation_id uuid NOT NULL,
    pay_batch_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    pay_batch_candidate_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid,
    pay_batch_item_id uuid NOT NULL,
    pay_bank_transfer_id uuid NOT NULL,
    transfer_scope_id uuid NOT NULL,
    reservation_id uuid,
    finance_case_id uuid,
    finance_component_id uuid,
    source_workbench_session_id uuid,
    source_snapshot_run_id uuid,
    source_session_version bigint,
    row_context_digest text NOT NULL,
    created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  IF p_operation_id IS NOT NULL
     AND upper(btrim(coalesce(v_operation_row.operation_type,'')))='PAYMENT_EXECUTE'
     AND v_operation_row.pay_batch_id IS NOT DISTINCT FROM p_pay_batch_id
     AND upper(btrim(coalesce(v_execution_mode,'')))='STANDARD_BANK'
     AND upper(btrim(coalesce(v_execution_commit_state,'NOT_SUBMITTED')))='NOT_SUBMITTED' THEN
    INSERT INTO pg_temp._bpay_wb_unsent_execution_schedule_context_v2 (
      contract_version,execution_operation_id,pay_batch_id,actor_user_id,
      pay_batch_candidate_id,candidate_id,timesheet_id,pay_batch_item_id,
      pay_bank_transfer_id,transfer_scope_id,reservation_id,finance_case_id,
      finance_component_id,source_workbench_session_id,source_snapshot_run_id,
      source_session_version,row_context_digest,created_at_utc
    )
    SELECT
      'EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2',p_operation_id,p_pay_batch_id,
      p_actor_user_id,batch_item.pay_batch_candidate_id,batch_candidate.candidate_id,
      batch_item.timesheet_id,batch_item.id,transfer_scope.pay_bank_transfer_id,
      membership.transfer_scope_id,batch_item.reservation_id,batch_item.finance_case_id,
      batch_item.finance_component_id,v_batch.source_workbench_session_id,
      v_batch.source_snapshot_run_id,v_batch.source_session_version,
      md5(
        p_operation_id::text||'|'||p_pay_batch_id::text||'|'||p_actor_user_id::text||'|'||
        batch_candidate.candidate_id::text||'|'||batch_item.pay_batch_candidate_id::text||'|'||
        batch_item.id::text||'|'||coalesce(batch_item.timesheet_id::text,'')||'|'||
        membership.transfer_scope_id::text||'|'||transfer_scope.pay_bank_transfer_id::text||'|'||
        coalesce(batch_item.reservation_id::text,'')||'|'||
        coalesce(batch_item.finance_case_id::text,'')||'|'||
        coalesce(batch_item.finance_component_id::text,'')||'|'||
        coalesce(v_batch.source_workbench_session_id::text,'')||'|'||
        coalesce(v_batch.source_snapshot_run_id::text,'')||'|'||
        coalesce(v_batch.source_session_version::text,'')||
        '|EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2'
      ),v_commit_ts
    FROM public.banking_pay_operation_transfer_scope_items AS membership
    JOIN public.banking_pay_operation_transfer_scope AS transfer_scope
      ON transfer_scope.id=membership.transfer_scope_id
     AND transfer_scope.operation_id=membership.operation_id
     AND transfer_scope.pay_batch_id=membership.pay_batch_id
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.id=membership.pay_batch_item_id
     AND batch_item.pay_batch_candidate_id=membership.pay_batch_candidate_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=batch_item.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id=p_pay_batch_id
     AND batch_candidate.candidate_id=membership.candidate_id
    WHERE membership.operation_id=p_operation_id
      AND membership.pay_batch_id=p_pay_batch_id
      AND coalesce(batch_item.is_voided,false) IS NOT TRUE
      AND batch_item.pay_bank_transfer_id=transfer_scope.pay_bank_transfer_id
      AND transfer_scope.pay_bank_transfer_id IS NOT NULL;
  END IF;

  update public.pay_advance_reservations par
  set
    status = 'COMMITTED',
    committed_at_utc = coalesce(par.committed_at_utc, v_commit_ts),
    updated_by_user_id = p_actor_user_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'RESERVED';

  get diagnostics v_reservations_committed_count = row_count;

  select round(coalesce(sum(par.reserved_amount),0),2)
  into v_reservations_committed_amount
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED';

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    'RESERVATION_COMMITTED',
    v_commit_ts,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'RESERVED'),
    jsonb_build_object(
      'reservation_status', 'COMMITTED',
      'authoritative_payment_date', v_authoritative_payment_date::text,
      'schedule_kind', v_kind,
      'scheduled_at_utc', v_sched_at::text
    ),
    'schedule_commit',
    null
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and par.committed_at_utc = v_commit_ts;

  begin
    v_comm_result := public.pay_remittance_maybe_queue_for_trigger(
      p_pay_batch_id => p_pay_batch_id,
      p_trigger => 'ON_EXECUTION',
      p_scope => 'ALL',
      p_actor_user_id => p_actor_user_id,
      p_only_confirmed => false,
      p_root_operation_id => CASE WHEN v_operation_mode THEN p_operation_id ELSE NULL::uuid END,
      p_operation_mode => v_operation_mode
    );

    if coalesce((v_comm_result->>'ok')::boolean, true) = false then
      raise exception '%', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
        'pay_batch_schedule: remittance timing queue stage failed'
      );
    end if;

    v_comm_trigger_status := coalesce(
      nullif(btrim(coalesce(v_comm_result->>'trigger_status','')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}','')), ''),
      case
        when lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_DEFERRED_BY_TIMING'
        when lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on') then 'SUPPRESSED_BY_EXECUTION_INTENT'
        when lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_OPERATION_READY'
        when lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on') then 'QUEUE_STAGE_BUILD_READY'
        else 'ON_EXECUTION_QUEUE_GATE_PROCESSED'
      end
    );
    v_comm_message_kind := coalesce(
      nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''),
      case when v_batch_kind_fixed = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end
    );
    v_comm_error := nullif(btrim(coalesce(v_comm_result->>'error','')), '');

    v_payout_notice_result := case
      when v_batch_kind_fixed = 'LOANS' then coalesce(v_comm_result->'queue_result', v_comm_result)
      else '{}'::jsonb
    end;
    v_remittance_result := case
      when v_batch_kind_fixed <> 'LOANS' then coalesce(v_comm_result->'queue_result', v_comm_result)
      else '{}'::jsonb
    end;

    v_payout_notice_dispatch_required := (
      v_batch_kind_fixed = 'LOANS'
      and lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on')
    );
    v_remittance_dispatch_required := (
      v_batch_kind_fixed <> 'LOANS'
      and lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on')
    );

    if btrim(coalesce(coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}'), '')) ~ '^[0-9]+$' then
      if v_batch_kind_fixed = 'LOANS' then
        v_payout_notice_targeted_count := coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}')::int;
        v_remittance_targeted_count := 0;
      else
        v_remittance_targeted_count := coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}')::int;
        v_payout_notice_targeted_count := 0;
      end if;
    else
      v_payout_notice_targeted_count := 0;
      v_remittance_targeted_count := 0;
    end if;

    insert into public.audit_events(
      actor_user_id,
      object_type,
      object_id_text,
      action,
      before_json,
      after_json,
      reason
    )
    values (
      p_actor_user_id,
      'pay_batch',
      p_pay_batch_id::text,
      'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TIMING_GATE',
      null,
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'batch_kind_fixed', v_batch_kind_fixed,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'authoritative_payment_date', v_authoritative_payment_date::text,
        'trigger_status', v_comm_trigger_status,
        'message_kind', v_comm_message_kind,
        'result', coalesce(v_comm_result, '{}'::jsonb),
        'execution_mode', v_execution_mode,
        'suppress_remittances', v_suppress_remittances
      ),
      'commit_stage_communication_timing_gate'
    );
  exception when others then
    v_comm_trigger_status := 'COMMIT_STAGE_QUEUE_TIMING_GATE_ERROR';
    v_comm_error := left(coalesce(SQLERRM,'UNKNOWN_COMMS_ERROR'), 1000);
    v_comm_message_kind := coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE');
    v_comm_result := jsonb_build_object(
      'ok', false,
      'trigger', 'ON_EXECUTION',
      'configured_timing', v_timing_setting_if_known,
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'message_kind', v_comm_message_kind,
      'automatic_commit_stage', (v_provider <> 'CSV'),
      'dispatch_required', false,
      'operation_id', NULL::text,
      'deferred', false,
      'suppressed', false,
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'queue_result', jsonb_build_object(
        'ok', false,
        'trigger', 'ON_EXECUTION',
        'configured_timing', v_timing_setting_if_known,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'operation_id', NULL::text,
        'deferred', false,
        'suppressed', false
      )
    );

    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      values (
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
        null,
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'batch_kind_fixed', v_batch_kind_fixed,
          'schedule_kind', v_kind,
          'scheduled_at_utc', v_sched_at::text,
          'authoritative_payment_date', v_authoritative_payment_date::text,
          'trigger_status', v_comm_trigger_status,
          'message_kind', v_comm_message_kind,
          'error', v_comm_error,
          'queue_result', coalesce(v_comm_result, '{}'::jsonb)
        ),
        'commit_stage_communication'
      );
    exception when others then
      null;
    end;

    if v_execution_commit_state = 'NOT_SUBMITTED' then
      begin
        update public.pay_batches as pb_schedule_rollback
        set
          status = v_batch.status,
          schedule_kind = v_batch.schedule_kind,
          scheduled_at_utc = v_batch.scheduled_at_utc,
          scheduled_by_user_id = v_batch.scheduled_by_user_id,
          funding_account_ref = v_batch.funding_account_ref,
          funds_warning_hours_json = v_batch.funds_warning_hours_json,
          pay_date = v_batch.pay_date,
          authoritative_payment_date = v_batch.authoritative_payment_date,
          authoritative_payment_date_source = v_batch.authoritative_payment_date_source,
          execution_commit_state = v_execution_commit_state,
          execution_commit_ref = v_execution_commit_ref,
          execution_committed_at_utc = v_execution_committed_at_utc,
          execution_intent_json = v_batch.execution_intent_json
        where pb_schedule_rollback.id = p_pay_batch_id
          and upper(coalesce(pb_schedule_rollback.execution_commit_state, 'NOT_SUBMITTED')) = 'NOT_SUBMITTED'
          and not exists (
            select 1
            from public.pay_bank_transfer_events as rollback_transfer_event
            where rollback_transfer_event.pay_batch_id = p_pay_batch_id
          )
          and not exists (
            select 1
            from public.pay_bank_transfers as rollback_transfer
            where rollback_transfer.pay_batch_id = p_pay_batch_id
              and (
                nullif(btrim(coalesce(rollback_transfer.rail_tx_id, '')), '') is not null
                or upper(coalesce(rollback_transfer.status, '')) in ('SUBMITTED', 'PROCESSING', 'SENT', 'COMPLETED', 'PAID', 'SETTLED')
              )
          );
      exception when others then
        null;
      end;
    end if;

    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', (v_provider <> 'CSV'),
      'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'dispatch_required', false,
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'result', coalesce(v_comm_result, '{}'::jsonb),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances
    );

    return jsonb_build_object(
      'ok', false,
      'error', 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
      'code', 'COMMIT_STAGE_COMMUNICATION_ERROR',
      'message', 'pay_batch_schedule: commit-stage communication failed before provider submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', (select pb2.status from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'schedule_kind', (select pb2.schedule_kind from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'scheduled_at_utc', (select case when pb2.scheduled_at_utc is null then null else pb2.scheduled_at_utc::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'schedule_revision', (select coalesce(pb2.source_scope_change_generation, 0) from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'active_scope_hash', v_current_active_scope_hash,
      'display_message', 'Payment scheduling did not complete. No provider submission was attempted.',
      'authoritative_payment_date', (select case when pb2.authoritative_payment_date is null then null else pb2.authoritative_payment_date::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'authoritative_payment_date_source', (select pb2.authoritative_payment_date_source from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'funding_account_ref', (select pb2.funding_account_ref from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'funds_warning_hours_json', (select pb2.funds_warning_hours_json from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_commit_state', (select pb2.execution_commit_state from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_commit_ref', (select pb2.execution_commit_ref from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb2.execution_committed_at_utc is null then null else pb2.execution_committed_at_utc::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_intent_json', (select pb2.execution_intent_json from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances,
      'remittance_trigger', 'ON_EXECUTION',
      'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
      'remittance_deferred', false,
      'remittance_suppressed', false,
      'remittance_operation_queued', false,
      'remittance_child_operation_id', null,
      'remittance_trigger_status', v_comm_trigger_status,
      'remittance_message_kind', v_comm_message_kind,
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb)
    );
  end;
  v_worker_communications := jsonb_build_object(
    'automatic_commit_stage', (v_provider <> 'CSV'),
    'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
    'trigger_status', v_comm_trigger_status,
    'error', v_comm_error,
    'dispatch_required', (v_payout_notice_dispatch_required = true or v_remittance_dispatch_required = true),
    'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
    'remittance', coalesce(v_remittance_result, '{}'::jsonb),
    'result', coalesce(v_comm_result, '{}'::jsonb),
    'execution_mode', v_execution_mode,
    'suppress_remittances', v_suppress_remittances
  );

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_SCHEDULE:OK',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'authoritative_payment_date', v_authoritative_payment_date::text,
        'funding_account_ref', v_funding,
        'rail_provider_snapshot', v_batch.rail_provider_snapshot,
        'rail_env_snapshot', v_batch.rail_env_snapshot,
        'execution_mode', v_execution_mode,
        'suppress_remittances', v_suppress_remittances,
        'pending_transfers', v_pending_transfers,
        'reservations_committed_count', v_reservations_committed_count,
        'reservations_committed_amount', v_reservations_committed_amount,
        'worker_communications', v_worker_communications
      ),
      'pay_batches',
      p_pay_batch_id::text
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'status', (select pb2.status from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'schedule_kind', (select pb2.schedule_kind from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'scheduled_at_utc', (select case when pb2.scheduled_at_utc is null then null else pb2.scheduled_at_utc::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'schedule_revision', (select coalesce(pb2.source_scope_change_generation, 0) from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
    'active_scope_hash', v_current_active_scope_hash,
    'display_message', case
      when v_kind = 'SCHEDULED' then 'Payment scheduled for the current active scope.'
      else 'Payment authorised for immediate processing.'
    end,
    'authoritative_payment_date', (select case when pb2.authoritative_payment_date is null then null else pb2.authoritative_payment_date::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'authoritative_payment_date_source', (select pb2.authoritative_payment_date_source from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'funding_account_ref', (select pb2.funding_account_ref from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'funds_warning_hours_json', (select pb2.funds_warning_hours_json from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'execution_commit_state', (select pb2.execution_commit_state from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_commit_ref', (select pb2.execution_commit_ref from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_committed_at_utc', (select case when pb2.execution_committed_at_utc is null then null else pb2.execution_committed_at_utc::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_mode', v_execution_mode,
    'execution_intent_json', (select pb2.execution_intent_json from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'suppress_remittances', v_suppress_remittances,
    'finance_reservations', jsonb_build_object(
      'committed_count', v_reservations_committed_count,
      'committed_amount', v_reservations_committed_amount
    ),
    'remittance_trigger', 'ON_EXECUTION',
    'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
    'remittance_deferred', lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on'),
    'remittance_suppressed', lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on'),
    'remittance_operation_queued', lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on'),
    'remittance_child_operation_id', coalesce(
      nullif(btrim(coalesce(v_comm_result->>'operation_id', '')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,operation_id}', '')), '')
    ),
    'remittance_trigger_status', coalesce(
      nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}', '')), ''),
      v_comm_trigger_status
    ),
    'remittance_message_kind', v_comm_message_kind,
    'worker_communications', v_worker_communications,
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
    'continuation', jsonb_build_object(
      'required', v_kind = 'IMMEDIATE' AND p_operation_id IS NOT NULL,
      'operation_id', p_operation_id,
      'operation_type', 'PAYMENT_EXECUTE',
      'pay_batch_id', p_pay_batch_id,
      'root_operation_id', NULL,
      'phase', CASE WHEN v_kind = 'IMMEDIATE' THEN 'VALIDATE_BATCH' ELSE NULL END,
      'run_after_utc', CASE WHEN v_kind = 'IMMEDIATE' THEN clock_timestamp() ELSE v_sched_at END,
      'reason', CASE WHEN v_kind = 'IMMEDIATE' THEN 'PAYMENT_DUE_NOW' ELSE 'PAYMENT_SCHEDULED_FOR_DISCOVERY' END,
      'successor_relation', CASE WHEN v_kind = 'IMMEDIATE' THEN 'SELF' ELSE 'NONE' END,
      'requires_user_action', false,
      'terminal', false
    )
  );
end;
$function$;

-- pay_batch_shell_ensure_from_operation(uuid,uuid,uuid,text,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_shell_ensure_from_operation(p_operation_id uuid, p_workbench_session_id uuid, p_actor_user_id uuid, p_batch_kind text, p_pay_channel text, p_input_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(pay_batch_id uuid, created boolean, scope jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_operation public.banking_pay_operations%ROWTYPE;
    v_session public.banking_pay_workbench_sessions%ROWTYPE;
    v_input_json jsonb := '{}'::jsonb;
    v_supplied_input_json jsonb := COALESCE(p_input_json, '{}'::jsonb);
    v_batch_kind text;
    v_pay_channel text;
    v_pay_channel_raw text;
    v_batch_kind_raw text;
    v_operation_scope text := 'ALL';
    v_scope_entries jsonb := '[]'::jsonb;
    v_scope_invalid_count integer := 0;
    v_scope_values text[] := ARRAY[]::text[];
    v_existing_pay_batch_id uuid;
    v_existing_pay_batch public.pay_batches%ROWTYPE;
    v_existing_pay_batch_count integer := 0;
    v_new_pay_batch_id uuid;
    v_scope_candidate_count integer := 0;
    v_snooze_guard_scope_ids jsonb := '[]'::jsonb;
    v_snooze_guard_json jsonb := '{}'::jsonb;
    v_active_snooze_count integer := 0;
    v_settings_bank_system text;
    v_settings_external_paye_system text;
    v_settings_rail_provider text;
    v_settings_rail_env text;
    v_primary_override_json jsonb := '{}'::jsonb;
    v_secondary_override_json jsonb := '{}'::jsonb;
    v_same_week_override_json jsonb := '{}'::jsonb;
    v_same_week_override_has_values boolean := false;
    v_same_week_override_used boolean := false;
    v_same_week_override_continue boolean := false;
    v_same_week_override_verified boolean := false;
    v_same_week_override_reason text := NULL::text;
    v_same_week_override_verified_at_utc timestamptz := NULL::timestamptz;
    v_same_week_override_verified_by_user_id uuid := NULL::uuid;
    v_same_week_override_purpose text := NULL::text;
    v_same_week_override_guardrail_code text := NULL::text;
    v_same_week_override_proof_valid boolean := false;
    v_same_week_override_required boolean := false;
    v_same_week_override_persisted boolean := false;
    v_paye_guardrails jsonb := '{}'::jsonb;
    v_existing_draft_id_text text := NULL::text;
    v_top_text text;
    v_top_bool boolean;
    v_top_ts timestamptz;
    v_frozen_generation bigint := 0;
    v_prechecked_generation bigint := 0;
    v_locked_generation bigint := 0;
    v_highest_relevant_generation bigint := NULL::bigint;
    v_unresolved_broad_root_count integer := 0;
    v_failed_broad_root_count integer := 0;
    v_scope_blocker jsonb := '{}'::jsonb;
    v_post_freeze_scope_status text := 'NONE';
    v_batch_freshness_status text := 'VALID_AT_SCOPE_FREEZE';
BEGIN
    IF p_operation_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_operation_id';
    END IF;

    IF p_workbench_session_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_workbench_session_id';
    END IF;

    IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation requires p_actor_user_id';
    END IF;

    IF jsonb_typeof(v_supplied_input_json) IS DISTINCT FROM 'object' THEN
        v_supplied_input_json := '{}'::jsonb;
    END IF;

    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation tms_users row not found: %', p_actor_user_id;
    END IF;

    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation not found: %', p_operation_id;
    END IF;

    v_input_json := COALESCE(v_operation.input_json, '{}'::jsonb);

    IF jsonb_typeof(v_input_json) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_OPERATION_INPUT_INVALID',
            'message', 'DRAFT_CREATE operation input_json must be a JSON object.',
            'operation_id', p_operation_id::text
        )::text;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation cannot create shell for terminal operation % with status %', p_operation_id, v_operation.status;
    END IF;

    IF v_operation.actor_user_id IS NOT NULL AND v_operation.actor_user_id <> p_actor_user_id THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation % belongs to a different actor', p_operation_id;
    END IF;

    IF v_operation.workbench_session_id IS NOT NULL AND v_operation.workbench_session_id <> p_workbench_session_id THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation operation % belongs to a different workbench session', p_operation_id;
    END IF;

    IF v_operation.scope_freeze_status <> 'FROZEN'
       OR COALESCE(v_operation.source_scope_seed_complete, false) IS NOT TRUE
       OR v_operation.frozen_scope_change_generation IS NULL THEN
        RAISE EXCEPTION 'PAY_BATCH_SHELL_SCOPE_NOT_FROZEN'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_SHELL_SCOPE_NOT_FROZEN',
                  'operation_id', p_operation_id::text,
                  'scope_freeze_status', v_operation.scope_freeze_status
                )::text;
    END IF;

    v_frozen_generation := v_operation.frozen_scope_change_generation;

    SELECT session_row.*
    INTO v_session
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_workbench_session_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session not found: %', p_workbench_session_id;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN' THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session % is not OPEN: %', p_workbench_session_id, v_session.status;
    END IF;

    IF v_session.discarded_at_utc IS NOT NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation workbench session % has been discarded', p_workbench_session_id;
    END IF;

    IF v_operation.frozen_source_session_version IS DISTINCT FROM v_session.version
       OR v_operation.frozen_source_snapshot_run_id IS DISTINCT FROM v_session.source_snapshot_run_id THEN
        RAISE EXCEPTION 'PAY_BATCH_SHELL_FROZEN_SESSION_PROVENANCE_MISMATCH'
          USING ERRCODE = 'P0001';
    END IF;

    WITH raw_scope AS (
        SELECT 'pay_channel_scope'::text AS source_key, NULLIF(BTRIM(v_input_json->>'pay_channel_scope'), '') AS raw_value
        UNION ALL SELECT 'payChannelScope', NULLIF(BTRIM(v_input_json->>'payChannelScope'), '')
        UNION ALL SELECT 'draft_scope', NULLIF(BTRIM(v_input_json->>'draft_scope'), '')
        UNION ALL SELECT 'draftScope', NULLIF(BTRIM(v_input_json->>'draftScope'), '')
        UNION ALL SELECT 'scope', NULLIF(BTRIM(v_input_json->>'scope'), '')
    ), normalised_scope AS (
        SELECT
            raw_scope.source_key,
            raw_scope.raw_value,
            BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(raw_scope.raw_value, ''))), '[^A-Z0-9]+', '_', 'g'), '_') AS raw_normalised
        FROM raw_scope
        WHERE raw_scope.raw_value IS NOT NULL
    ), resolved_scope AS (
        SELECT
            normalised_scope.source_key,
            normalised_scope.raw_value,
            CASE
                WHEN normalised_scope.raw_normalised IN ('ALL', 'BOTH', 'MIXED', 'ALL_PAY_CHANNELS', 'BOTH_PAY_CHANNELS', 'PAYE_AND_UMBRELLA', 'PAYE_UMBRELLA', 'PAYE_PLUS_UMBRELLA', 'PAYE_WITH_UMBRELLA', 'BOTH_PAYE_UMBRELLA', 'BOTH_PAYE_AND_UMBRELLA', 'PAYE_AND_NON_PAYE', 'PAYE_NON_PAYE') THEN 'ALL'
                WHEN normalised_scope.raw_normalised IN ('PAYE', 'PAYE_ONLY', 'ONLY_PAYE', 'PAYE_PAY') THEN 'PAYE'
                WHEN normalised_scope.raw_normalised IN ('UMBRELLA', 'UMBRELLAS', 'UMBRELLA_ONLY', 'ONLY_UMBRELLA', 'UMBRELLA_PAY', 'NON_PAYE', 'NONPAYE', 'NON_PAYE_ONLY', 'NONPAYE_ONLY') THEN 'UMBRELLA'
                ELSE NULL::text
            END AS scope_value
        FROM normalised_scope
    )
    SELECT
        COALESCE(jsonb_agg(jsonb_build_object(
            'source', resolved_scope.source_key,
            'raw', resolved_scope.raw_value,
            'value', resolved_scope.scope_value,
            'invalid', (resolved_scope.scope_value IS NULL)
        ) ORDER BY resolved_scope.source_key), '[]'::jsonb),
        COUNT(*) FILTER (WHERE resolved_scope.scope_value IS NULL)::integer,
        COALESCE(ARRAY_AGG(DISTINCT resolved_scope.scope_value) FILTER (WHERE resolved_scope.scope_value IS NOT NULL), ARRAY[]::text[])
    INTO v_scope_entries, v_scope_invalid_count, v_scope_values
    FROM resolved_scope;

    IF COALESCE(v_scope_invalid_count, 0) > 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'BANKING_PAY_CREATE_DRAFT_INVALID_SCOPE',
            'message', 'Create Draft scope stored on the operation is not valid. No draft batch shell has been created.',
            'operation_id', p_operation_id::text,
            'scope_entries', COALESCE(v_scope_entries, '[]'::jsonb)
        )::text;
    END IF;

    IF COALESCE(array_length(v_scope_values, 1), 0) > 1 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'BANKING_PAY_CREATE_DRAFT_SCOPE_CONFLICT',
            'message', 'Create Draft scope stored on the operation is inconsistent. No draft batch shell has been created.',
            'operation_id', p_operation_id::text,
            'scope_entries', COALESCE(v_scope_entries, '[]'::jsonb),
            'scope_values', to_jsonb(v_scope_values)
        )::text;
    END IF;

    v_operation_scope := COALESCE(v_scope_values[1], 'ALL');

    v_pay_channel_raw := BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(p_pay_channel, ''))), '[^A-Z0-9]+', '_', 'g'), '_');

    IF v_pay_channel_raw IN ('PAYE', 'PAYE_ONLY', 'ONLY_PAYE', 'PAYE_PAY') THEN
        v_pay_channel := 'PAYE';
    ELSIF v_pay_channel_raw IN ('UMBRELLA', 'UMBRELLAS', 'UMBRELLA_ONLY', 'ONLY_UMBRELLA', 'UMBRELLA_PAY', 'NON_PAYE', 'NONPAYE', 'NON_PAYE_ONLY', 'NONPAYE_ONLY') THEN
        v_pay_channel := 'UMBRELLA';
    ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_PAY_CHANNEL_INVALID',
            'message', 'pay_batch_shell_ensure_from_operation supports PAYE or UMBRELLA shell creation only.',
            'operation_id', p_operation_id::text,
            'pay_channel', p_pay_channel
        )::text;
    END IF;

    IF v_operation_scope = 'PAYE' AND v_pay_channel <> 'PAYE' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_SCOPE_CHANNEL_MISMATCH',
            'message', 'PAYE-scoped draft operation cannot create an Umbrella shell.',
            'operation_id', p_operation_id::text,
            'operation_scope', v_operation_scope,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    IF v_operation_scope = 'UMBRELLA' AND v_pay_channel <> 'UMBRELLA' THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_SCOPE_CHANNEL_MISMATCH',
            'message', 'Umbrella-scoped draft operation cannot create a PAYE shell.',
            'operation_id', p_operation_id::text,
            'operation_scope', v_operation_scope,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    v_batch_kind_raw := BTRIM(REGEXP_REPLACE(UPPER(BTRIM(COALESCE(NULLIF(p_batch_kind, ''), 'STANDARD_PAYRUN'))), '[^A-Z0-9]+', '_', 'g'), '_');

    IF v_batch_kind_raw IN ('', 'STANDARD_PAYRUN', 'MIXED') THEN
        v_batch_kind := v_pay_channel;
    ELSIF v_batch_kind_raw IN ('PAYE', 'UMBRELLA') THEN
        v_batch_kind := v_batch_kind_raw;
    ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_BATCH_KIND_INVALID',
            'message', 'pay_batch_shell_ensure_from_operation supports PAYE or UMBRELLA batch shells for DRAFT_CREATE.',
            'operation_id', p_operation_id::text,
            'batch_kind', p_batch_kind
        )::text;
    END IF;

    IF v_batch_kind <> v_pay_channel THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PAY_BATCH_SHELL_BATCH_KIND_CHANNEL_MISMATCH',
            'message', 'Batch kind and pay channel must match for a DRAFT_CREATE shell.',
            'operation_id', p_operation_id::text,
            'batch_kind', v_batch_kind,
            'pay_channel', v_pay_channel
        )::text;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_scope_candidate_count
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel;

    IF COALESCE(v_scope_candidate_count, 0) = 0 THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation found no candidate scope rows for operation %, pay channel %', p_operation_id, v_pay_channel;
    END IF;

    SELECT COALESCE(jsonb_agg(scope_row.id::text ORDER BY scope_row.id::text), '[]'::jsonb)
    INTO v_snooze_guard_scope_ids
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel;

    v_snooze_guard_json := public.pay_workbench_operation_active_snoozes_v1(
        p_operation_id,
        p_workbench_session_id,
        v_snooze_guard_scope_ids
    );
    v_active_snooze_count := CASE
        WHEN COALESCE(v_snooze_guard_json->>'active_snooze_count', '') ~ '^[0-9]{1,9}$'
          THEN (v_snooze_guard_json->>'active_snooze_count')::integer
        ELSE 0
    END;

    IF v_active_snooze_count > 0 THEN
        RAISE EXCEPTION 'ACTIVE_SNOOZE_PREVENTS_DRAFT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_strip_nulls(
                  jsonb_build_object(
                    'code', 'ACTIVE_SNOOZE_PREVENTS_DRAFT',
                    'message', 'One or more selected payments are currently snoozed. Banking Pay has been refreshed so you can review the updated selection.',
                    'operation_id', p_operation_id::text,
                    'workbench_session_id', p_workbench_session_id::text,
                    'pay_channel', v_pay_channel,
                    'refresh_required', true,
                    'next_action', 'REFRESH_WORKBENCH'
                  )
                  || COALESCE(v_snooze_guard_json, '{}'::jsonb)
                )::text;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_existing_pay_batch_count
    FROM (
        SELECT DISTINCT scope_row.pay_batch_id
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.workbench_session_id = p_workbench_session_id
          AND scope_row.pay_batch_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
    ) AS existing_batch_ids;

    IF COALESCE(v_existing_pay_batch_count, 0) > 1 THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation found multiple pay batches for operation %, pay channel %', p_operation_id, v_pay_channel;
    END IF;

    SELECT DISTINCT scope_row.pay_batch_id
    INTO v_existing_pay_batch_id
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.workbench_session_id = p_workbench_session_id
      AND scope_row.pay_batch_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
    ORDER BY scope_row.pay_batch_id
    LIMIT 1;

    IF v_pay_channel = 'PAYE' THEN
        v_primary_override_json := CASE
            WHEN jsonb_typeof(v_input_json->'same_week_paye_override') = 'object' THEN COALESCE(v_input_json->'same_week_paye_override', '{}'::jsonb)
            ELSE '{}'::jsonb
        END;
        v_secondary_override_json := CASE
            WHEN jsonb_typeof(v_input_json->'same_week_paye_override_json') = 'object' THEN COALESCE(v_input_json->'same_week_paye_override_json', '{}'::jsonb)
            ELSE '{}'::jsonb
        END;

        IF v_primary_override_json <> '{}'::jsonb AND v_secondary_override_json <> '{}'::jsonb AND v_primary_override_json <> v_secondary_override_json THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                'message', 'PAYE same-week override proof contains conflicting nested proof objects.',
                'operation_id', p_operation_id::text,
                'field', 'same_week_paye_override_json'
            )::text;
        END IF;

        v_same_week_override_json := CASE
            WHEN v_primary_override_json <> '{}'::jsonb THEN v_primary_override_json
            ELSE v_secondary_override_json
        END;

        FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_reauth_token', 'sameWeekPayeReauthToken', 'reauth_token', 'reauthToken']) LOOP
            IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'Raw PAYE override reauthentication token must not be stored on a draft operation.',
                    'operation_id', p_operation_id::text,
                    'field', v_top_text
                )::text;
            END IF;
        END LOOP;

        v_same_week_override_has_values := (v_same_week_override_json <> '{}'::jsonb)
          AND (
            LOWER(BTRIM(COALESCE(v_same_week_override_json->>'used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(v_same_week_override_json->>'continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR LOWER(BTRIM(COALESCE(v_same_week_override_json->>'verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reason', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'verified_by_user_id', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'verified_at_utc', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reauth_purpose', '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'guardrail_code', '')), '') IS NOT NULL
          );

        IF v_same_week_override_has_values THEN
            v_same_week_override_used := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_continue := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_verified := LOWER(BTRIM(COALESCE(v_same_week_override_json->>'verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
            v_same_week_override_reason := NULLIF(BTRIM(COALESCE(v_same_week_override_json->>'reason', '')), '');
            v_same_week_override_verified_by_user_id := CASE
                WHEN COALESCE(v_same_week_override_json->>'verified_by_user_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_same_week_override_json->>'verified_by_user_id')::uuid
                ELSE NULL::uuid
            END;
            v_same_week_override_verified_at_utc := CASE
                WHEN COALESCE(v_same_week_override_json->>'verified_at_utc', '') ~ '^\d{4}-\d{2}-\d{2}' THEN (v_same_week_override_json->>'verified_at_utc')::timestamptz
                ELSE NULL::timestamptz
            END;
            v_same_week_override_purpose := UPPER(BTRIM(COALESCE(v_same_week_override_json->>'reauth_purpose', '')));
            v_same_week_override_guardrail_code := UPPER(BTRIM(COALESCE(v_same_week_override_json->>'guardrail_code', '')));

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_used THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level used flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'same_week_paye_override_used')::text;
                END IF;
            END IF;

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'override_continue', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'override_continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_continue THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level continue flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'override_continue')::text;
                END IF;
            END IF;

            IF NULLIF(BTRIM(COALESCE(v_input_json->>'override_verified', '')), '') IS NOT NULL THEN
                v_top_bool := LOWER(BTRIM(COALESCE(v_input_json->>'override_verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
                IF v_top_bool <> v_same_week_override_verified THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified flag conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', 'override_verified')::text;
                END IF;
            END IF;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_reason', 'override_reason']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL
                   AND NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS DISTINCT FROM v_same_week_override_reason THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level reason conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                END IF;
            END LOOP;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_verified_by_user_id', 'override_verified_by_user_id']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL
                   AND NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS DISTINCT FROM v_same_week_override_verified_by_user_id::text THEN
                    RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified user conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                END IF;
            END LOOP;

            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_verified_at_utc', 'override_verified_at_utc']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                    v_top_ts := CASE
                        WHEN COALESCE(v_input_json->>v_top_text, '') ~ '^\d{4}-\d{2}-\d{2}' THEN (v_input_json->>v_top_text)::timestamptz
                        ELSE NULL::timestamptz
                    END;
                    IF v_top_ts IS NULL OR v_top_ts IS DISTINCT FROM v_same_week_override_verified_at_utc THEN
                        RAISE EXCEPTION '%', jsonb_build_object('code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION', 'message', 'PAYE same-week override proof top-level verified timestamp conflicts with canonical nested proof.', 'operation_id', p_operation_id::text, 'field', v_top_text)::text;
                    END IF;
                END IF;
            END LOOP;

            v_same_week_override_proof_valid := v_same_week_override_used
                AND v_same_week_override_continue
                AND v_same_week_override_verified
                AND v_same_week_override_reason IS NOT NULL
                AND v_same_week_override_verified_by_user_id = p_actor_user_id
                AND v_same_week_override_verified_at_utc IS NOT NULL
                AND v_same_week_override_purpose = 'PAYE_SAME_WEEK_OVERRIDE'
                AND v_same_week_override_guardrail_code = 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED';

            IF v_same_week_override_proof_valid IS NOT TRUE THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'PAYE same-week override proof stored on the draft operation is incomplete or invalid.',
                    'operation_id', p_operation_id::text,
                    'pay_channel', v_pay_channel
                )::text;
            END IF;
        ELSE
            FOR v_top_text IN SELECT unnest(ARRAY['same_week_paye_override_reason', 'override_reason', 'same_week_paye_override_verified_by_user_id', 'override_verified_by_user_id', 'same_week_paye_override_verified_at_utc', 'override_verified_at_utc']) LOOP
                IF NULLIF(BTRIM(COALESCE(v_input_json->>v_top_text, '')), '') IS NOT NULL THEN
                    RAISE EXCEPTION '%', jsonb_build_object(
                        'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                        'message', 'PAYE same-week override proof aliases are present without canonical nested proof.',
                        'operation_id', p_operation_id::text,
                        'field', v_top_text
                    )::text;
                END IF;
            END LOOP;

            IF LOWER(BTRIM(COALESCE(v_input_json->>'same_week_paye_override_used', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR LOWER(BTRIM(COALESCE(v_input_json->>'override_continue', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR LOWER(BTRIM(COALESCE(v_input_json->>'override_verified', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'PAYE same-week override proof flags are present without canonical nested proof.',
                    'operation_id', p_operation_id::text
                )::text;
            END IF;
        END IF;

        PERFORM pg_advisory_xact_lock(94201, 1);

        v_paye_guardrails := public.pay_paye_guardrails(
            p_pay_date => v_session.pay_date,
            p_ignore_pay_batch_id => v_existing_pay_batch_id,
            p_actor_user_id => p_actor_user_id
        );

        IF COALESCE((v_paye_guardrails->>'ok')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_GUARDRAIL_RESPONSE_INVALID',
                'message', 'Could not confirm PAYE guardrails before creating draft shell.',
                'operation_id', p_operation_id::text,
                'guardrail', v_paye_guardrails
            )::text;
        END IF;

        IF COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false) THEN
            v_existing_draft_id_text := v_paye_guardrails #>> '{existing_paye_draft,pay_batch_id}';
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_DRAFT_ALREADY_EXISTS',
                'message', 'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.',
                'operation_id', p_operation_id::text,
                'pay_channel', v_pay_channel,
                'existing_paye_draft', v_paye_guardrails->'existing_paye_draft',
                'existing_paye_draft_id', v_existing_draft_id_text
            )::text;
        END IF;

        v_same_week_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

        IF v_same_week_override_required AND v_same_week_override_proof_valid IS NOT TRUE THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED',
                'message', 'A same-week PAYE override must be verified before creating this PAYE draft shell.',
                'operation_id', p_operation_id::text,
                'pay_channel', v_pay_channel,
                'guardrail', v_paye_guardrails,
                'no_batch_created', true,
                'no_batch_shell_created', true
            )::text;
        END IF;
    END IF;

    IF v_existing_pay_batch_id IS NOT NULL THEN
        SELECT existing_batch_row.*
        INTO v_existing_pay_batch
        FROM public.pay_batches AS existing_batch_row
        WHERE existing_batch_row.id = v_existing_pay_batch_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation candidate scope references missing pay batch %', v_existing_pay_batch_id;
        END IF;

        IF UPPER(BTRIM(COALESCE(v_existing_pay_batch.status, ''))) <> 'DRAFT' THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % is not DRAFT: %', v_existing_pay_batch_id, v_existing_pay_batch.status;
        END IF;

        IF v_existing_pay_batch.source_workbench_session_id IS DISTINCT FROM p_workbench_session_id THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different workbench session', v_existing_pay_batch_id;
        END IF;

        IF UPPER(BTRIM(COALESCE(v_existing_pay_batch.batch_kind_fixed, ''))) IS DISTINCT FROM v_batch_kind THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % has batch kind %, expected %', v_existing_pay_batch_id, v_existing_pay_batch.batch_kind_fixed, v_batch_kind;
        END IF;

        IF v_existing_pay_batch.source_snapshot_run_id IS DISTINCT FROM v_session.source_snapshot_run_id THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different snapshot run', v_existing_pay_batch_id;
        END IF;

        IF v_existing_pay_batch.source_session_version IS DISTINCT FROM v_session.version THEN
            RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation existing pay batch % belongs to a different session version', v_existing_pay_batch_id;
        END IF;

        IF v_pay_channel = 'UMBRELLA'
           AND (
             COALESCE(v_existing_pay_batch.same_week_paye_override_used, false)
             OR v_existing_pay_batch.same_week_paye_override_reason IS NOT NULL
             OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS NOT NULL
             OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS NOT NULL
           ) THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'UMBRELLA_BATCH_HAS_PAYE_OVERRIDE_PROOF',
                'message', 'Umbrella draft batch shell must not contain PAYE same-week override proof.',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_existing_pay_batch_id::text
            )::text;
        END IF;

        IF v_pay_channel = 'PAYE' AND v_same_week_override_required THEN
            IF COALESCE(v_existing_pay_batch.same_week_paye_override_used, false) IS NOT TRUE
               OR NULLIF(BTRIM(COALESCE(v_existing_pay_batch.same_week_paye_override_reason, '')), '') IS DISTINCT FROM v_same_week_override_reason
               OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS DISTINCT FROM v_same_week_override_verified_by_user_id
               OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS DISTINCT FROM v_same_week_override_verified_at_utc THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'PAYE_OVERRIDE_PROOF_INVALID_FOR_DRAFT_OPERATION',
                    'message', 'Existing PAYE draft shell does not contain the required verified same-week override proof for this operation.',
                    'operation_id', p_operation_id::text,
                    'pay_batch_id', v_existing_pay_batch_id::text
                )::text;
            END IF;
        END IF;

        UPDATE public.banking_pay_operation_candidate_scope AS scope_update
        SET pay_batch_id = v_existing_pay_batch_id,
            updated_at_utc = now()
        WHERE scope_update.operation_id = p_operation_id
          AND scope_update.workbench_session_id = p_workbench_session_id
          AND scope_update.pay_batch_id IS DISTINCT FROM v_existing_pay_batch_id
          AND UPPER(BTRIM(COALESCE(scope_update.pay_channel, ''))) = v_pay_channel;

        UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
        SET pay_batch_id = v_existing_pay_batch_id,
            updated_at_utc = now()
        WHERE allocation_update.operation_id = p_operation_id
          AND allocation_update.pay_batch_id IS DISTINCT FROM v_existing_pay_batch_id
          AND EXISTS (
              SELECT 1
              FROM public.banking_pay_operation_candidate_scope AS scope_row
              WHERE scope_row.id = allocation_update.candidate_scope_id
                AND scope_row.operation_id = p_operation_id
                AND scope_row.workbench_session_id = p_workbench_session_id
                AND scope_row.pay_batch_id = v_existing_pay_batch_id
                AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
          );

        v_same_week_override_persisted := COALESCE(v_existing_pay_batch.same_week_paye_override_used, false)
            OR v_existing_pay_batch.same_week_paye_override_reason IS NOT NULL
            OR v_existing_pay_batch.same_week_paye_override_verified_at_utc IS NOT NULL
            OR v_existing_pay_batch.same_week_paye_override_verified_by_user_id IS NOT NULL;

        RETURN QUERY
        SELECT
            v_existing_pay_batch_id,
            false,
            jsonb_build_object(
                'operation_id', p_operation_id::text,
                'workbench_session_id', p_workbench_session_id::text,
                'pay_channel', v_pay_channel,
                'batch_kind', v_batch_kind,
                'candidate_scope_count', v_scope_candidate_count,
                'source_snapshot_run_id', CASE WHEN v_existing_pay_batch.source_snapshot_run_id IS NULL THEN NULL ELSE v_existing_pay_batch.source_snapshot_run_id::text END,
                'source_session_version', v_existing_pay_batch.source_session_version,
                'operation_pay_channel_scope', v_operation_scope,
                'same_week_paye_override_required', v_same_week_override_required,
                'same_week_paye_override_persisted', CASE WHEN v_pay_channel = 'PAYE' THEN v_same_week_override_persisted ELSE false END
            );
        RETURN;
    END IF;

    -- Bounded relevance precheck over operation-owned candidates and unresolved
    -- broad roots. No source trigger scans operations or batches.
    SELECT COALESCE(change_counter.seq, 0)
    INTO v_prechecked_generation
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate_scope_generation';

    SELECT MAX(candidate_counter.scope_change_generation)
    INTO v_highest_relevant_generation
    FROM public.banking_pay_operation_candidate_scope AS frozen_scope
    JOIN public.app_change_counters AS candidate_counter
      ON candidate_counter.entity_key = 'pay_candidate:' || frozen_scope.candidate_id::text
    WHERE frozen_scope.operation_id = p_operation_id
      AND frozen_scope.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(frozen_scope.pay_channel, ''))) = v_pay_channel
      AND candidate_counter.scope_change_generation > v_frozen_generation
      AND candidate_counter.scope_change_generation <= v_prechecked_generation;

    v_scope_blocker := public.pay_workbench_scope_blocker_state_v1(
      p_workbench_session_id,
      v_prechecked_generation,
      p_operation_id
    );
    v_unresolved_broad_root_count := COALESCE((v_scope_blocker->>'upstream_active_count')::integer, 0);
    v_failed_broad_root_count := COALESCE((v_scope_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    SELECT settings_row.banking_system,
           settings_row.external_paye_system,
           settings_row.rail_provider_default,
           settings_row.rail_env_default
    INTO v_settings_bank_system,
         v_settings_external_paye_system,
         v_settings_rail_provider,
         v_settings_rail_env
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id ASC
    LIMIT 1;

    IF v_settings_bank_system IS NULL OR v_settings_external_paye_system IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation settings_defaults missing banking_system/external_paye_system';
    END IF;

    IF v_settings_rail_provider IS NULL OR v_settings_rail_env IS NULL THEN
        RAISE EXCEPTION 'pay_batch_shell_ensure_from_operation settings_defaults missing rail provider/environment';
    END IF;

    v_same_week_override_persisted := v_pay_channel = 'PAYE' AND v_same_week_override_required AND v_same_week_override_proof_valid;

    SELECT change_counter.seq
    INTO v_locked_generation
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate_scope_generation'
    FOR UPDATE;

    IF v_locked_generation = v_frozen_generation THEN
        v_post_freeze_scope_status := 'NONE';
        v_batch_freshness_status := 'VALID_AT_SCOPE_FREEZE';
    ELSIF v_highest_relevant_generation IS NOT NULL THEN
        v_post_freeze_scope_status := 'RELEVANT';
        v_batch_freshness_status := 'STALE_POST_SCOPE_FREEZE';
    ELSIF v_failed_broad_root_count > 0 THEN
        v_post_freeze_scope_status := 'PENDING_RELEVANCE';
        v_batch_freshness_status := 'PENDING_SCOPE_CHANGE_RELEVANCE_FAILED';
    ELSIF v_locked_generation > v_prechecked_generation
       OR v_unresolved_broad_root_count > 0 THEN
        v_post_freeze_scope_status := 'PENDING_RELEVANCE';
        v_batch_freshness_status := 'PENDING_SCOPE_CHANGE_RELEVANCE';
    ELSE
        v_post_freeze_scope_status := 'IRRELEVANT';
        v_batch_freshness_status := 'VALID_AT_SCOPE_FREEZE';
    END IF;

    UPDATE public.banking_pay_operations AS frozen_operation
    SET post_freeze_scope_status = v_post_freeze_scope_status,
        post_freeze_observed_generation = CASE
          WHEN v_locked_generation > v_frozen_generation THEN v_locked_generation
          ELSE NULL::bigint
        END,
        post_freeze_relevant_generation = CASE
          WHEN v_post_freeze_scope_status = 'RELEVANT' THEN v_highest_relevant_generation
          ELSE NULL::bigint
        END,
        post_freeze_scope_checked_at_utc = now(),
        updated_at_utc = now()
    WHERE frozen_operation.id = p_operation_id;

    INSERT INTO public.pay_batches (
        pay_date,
        created_at_utc,
        created_by_user_id,
        status,
        banking_system_snapshot,
        external_paye_system_snapshot,
        rail_provider_snapshot,
        rail_env_snapshot,
        batch_kind_fixed,
        source_workbench_session_id,
        source_snapshot_run_id,
        source_session_version,
        execution_commit_state,
        same_week_paye_override_used,
        same_week_paye_override_reason,
        same_week_paye_override_verified_at_utc,
        same_week_paye_override_verified_by_user_id,
        source_scope_change_generation,
        scope_generation_observed_at_shell,
        freshness_validation_status,
        freshness_checked_at_utc,
        freshness_result_json
    )
    VALUES (
        v_session.pay_date,
        now(),
        p_actor_user_id,
        'DRAFT',
        v_settings_bank_system,
        v_settings_external_paye_system,
        v_settings_rail_provider,
        v_settings_rail_env,
        v_batch_kind,
        p_workbench_session_id,
        v_session.source_snapshot_run_id,
        v_session.version,
        'NOT_SUBMITTED',
        CASE WHEN v_same_week_override_persisted THEN true ELSE false END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_reason ELSE NULL::text END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_verified_at_utc ELSE NULL::timestamptz END,
        CASE WHEN v_same_week_override_persisted THEN v_same_week_override_verified_by_user_id ELSE NULL::uuid END,
        v_frozen_generation,
        v_locked_generation,
        v_batch_freshness_status,
        now(),
        jsonb_strip_nulls(jsonb_build_object(
          'scope_freeze_status', 'FROZEN',
          'source_scope_change_generation', v_frozen_generation,
          'scope_generation_observed_at_shell', v_locked_generation,
          'post_freeze_scope_status', v_post_freeze_scope_status,
          'post_freeze_relevant_generation', v_highest_relevant_generation,
          'unresolved_broad_root_count', v_unresolved_broad_root_count,
          'failed_broad_root_count', v_failed_broad_root_count,
          'scope_blocker_failure_sample', COALESCE(v_scope_blocker->'failure_sample', '[]'::jsonb),
          'policy_x_authority', 'FROZEN_OPERATION_SCOPE'
        ))
    )
    RETURNING public.pay_batches.id INTO v_new_pay_batch_id;

    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET pay_batch_id = v_new_pay_batch_id,
        updated_at_utc = now()
    WHERE scope_update.operation_id = p_operation_id
      AND scope_update.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(scope_update.pay_channel, ''))) = v_pay_channel;

    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET pay_batch_id = v_new_pay_batch_id,
        updated_at_utc = now()
    WHERE allocation_update.operation_id = p_operation_id
      AND allocation_update.pay_batch_id IS DISTINCT FROM v_new_pay_batch_id
      AND EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS scope_row
          WHERE scope_row.id = allocation_update.candidate_scope_id
            AND scope_row.operation_id = p_operation_id
            AND scope_row.workbench_session_id = p_workbench_session_id
            AND scope_row.pay_batch_id = v_new_pay_batch_id
            AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) = v_pay_channel
      );

    RETURN QUERY
    SELECT
        v_new_pay_batch_id,
        true,
        jsonb_build_object(
            'operation_id', p_operation_id::text,
            'workbench_session_id', p_workbench_session_id::text,
            'pay_channel', v_pay_channel,
            'batch_kind', v_batch_kind,
            'candidate_scope_count', v_scope_candidate_count,
            'source_snapshot_run_id', CASE WHEN v_session.source_snapshot_run_id IS NULL THEN NULL ELSE v_session.source_snapshot_run_id::text END,
            'source_session_version', v_session.version,
            'operation_pay_channel_scope', v_operation_scope,
            'same_week_paye_override_required', v_same_week_override_required,
            'same_week_paye_override_persisted', v_same_week_override_persisted
        );
END;
$function$;

-- pay_batch_stage_operation_candidate_chunk_context(uuid,uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_batch_stage_operation_candidate_chunk_context(p_operation_id uuid, p_pay_batch_id uuid, p_candidate_scope_ids jsonb, p_actor_user_id uuid)
 RETURNS TABLE(candidate_count integer, selected_row_count integer, timesheet_snapshot_count integer, finance_component_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_operation public.banking_pay_operations%rowtype;
    v_pay_batch public.pay_batches%rowtype;
    v_scope_ids jsonb;
    v_candidate_count integer;
    v_selected_row_count integer;
    v_timesheet_snapshot_count integer;
    v_finance_component_count integer;
    v_settings_bank_system text;
    v_settings_external_paye_system text;
    v_settings_rail_provider text;
    v_settings_rail_env text;
    v_need_name_check boolean;
    v_requires_payee_map boolean;
    v_vat_rate_pct numeric;
    v_erni_pct numeric;
    v_week_start date;
    v_scope text;
begin
    v_scope_ids := coalesce(p_candidate_scope_ids, '[]'::jsonb);

    if p_actor_user_id is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires p_actor_user_id';
    end if;

    perform 1
    from public.tms_users as actor_user
    where actor_user.id = p_actor_user_id;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context tms_users row not found: %', p_actor_user_id;
    end if;

    if jsonb_typeof(v_scope_ids) <> 'array' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires p_candidate_scope_ids to be a JSON array';
    end if;

    if jsonb_array_length(v_scope_ids) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires at least one candidate scope id';
    end if;

    if exists (
        select 1
        from jsonb_array_elements(v_scope_ids) as supplied_scope(scope_value)
        where not ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    ) then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context requires candidate scope ids to be UUID strings';
    end if;

    select operation_row.*
    into v_operation
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
    for update;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context operation not found: %', p_operation_id;
    end if;

    if v_operation.operation_type <> 'DRAFT_CREATE' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
    end if;

    if v_operation.status in ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context cannot stage terminal operation % with status %', p_operation_id, v_operation.status;
    end if;

    if v_operation.actor_user_id is not null and v_operation.actor_user_id <> p_actor_user_id then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context operation % belongs to a different actor', p_operation_id;
    end if;

    select batch_row.*
    into v_pay_batch
    from public.pay_batches as batch_row
    where batch_row.id = p_pay_batch_id
    for update;

    if not found then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch not found: %', p_pay_batch_id;
    end if;

    if v_pay_batch.status <> 'DRAFT' then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch % is not DRAFT: %', p_pay_batch_id, v_pay_batch.status;
    end if;

    if v_pay_batch.source_workbench_session_id is not null
       and v_operation.workbench_session_id is not null
       and v_pay_batch.source_workbench_session_id <> v_operation.workbench_session_id then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context pay batch % belongs to a different workbench session', p_pay_batch_id;
    end if;

    drop table if exists pg_temp.tmp_pay_build_operation_candidate_scope;
    create temporary table pg_temp.tmp_pay_build_operation_candidate_scope as
    select scope_row.*
    from public.banking_pay_operation_candidate_scope as scope_row
    where scope_row.operation_id = p_operation_id
      and scope_row.pay_batch_id = p_pay_batch_id
      and scope_row.id in (
          select (supplied_scope.scope_value #>> '{}')::uuid
          from jsonb_array_elements(v_scope_ids) as supplied_scope(scope_value)
      )
    order by scope_row.chunk_sequence nulls last, scope_row.pay_channel, scope_row.candidate_id;

    select count(*)::integer
    into v_candidate_count
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope;

    if coalesce(v_candidate_count, 0) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context found no candidate scope rows for operation %, batch %', p_operation_id, p_pay_batch_id;
    end if;

    if coalesce(v_candidate_count, 0) <> jsonb_array_length(v_scope_ids) then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context one or more candidate scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    end if;

    select upper(btrim(coalesce(staged_scope.pay_channel, '')))
    into v_scope
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
    where upper(btrim(coalesce(staged_scope.pay_channel, ''))) in ('PAYE', 'UMBRELLA')
    group by upper(btrim(coalesce(staged_scope.pay_channel, '')))
    order by upper(btrim(coalesce(staged_scope.pay_channel, '')))
    limit 1;

    if v_scope is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context cannot determine pay channel scope for operation %', p_operation_id;
    end if;

    if (
        select count(*)::integer
        from (
            select distinct upper(btrim(coalesce(staged_scope.pay_channel, ''))) as pay_channel_scope
            from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
            where upper(btrim(coalesce(staged_scope.pay_channel, ''))) in ('PAYE', 'UMBRELLA')
        ) as pay_channel_scope_rows
    ) <> 1 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context candidate scope chunk must contain exactly one pay channel scope';
    end if;

    v_week_start := public._pay_week_start_monday(v_pay_batch.pay_date);

    select coalesce(nullif(v_pay_batch.banking_system_snapshot, ''), settings_row.banking_system),
           coalesce(nullif(v_pay_batch.external_paye_system_snapshot, ''), settings_row.external_paye_system),
           coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default),
           coalesce(nullif(v_pay_batch.rail_env_snapshot, ''), settings_row.rail_env_default),
           (coalesce(settings_row.rail_supports_name_check, false) = true and upper(btrim(coalesce(coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default), ''))) <> 'CSV') as need_name_check,
           (upper(btrim(coalesce(coalesce(nullif(v_pay_batch.rail_provider_snapshot, ''), settings_row.rail_provider_default), ''))) <> 'CSV') as requires_payee_map
    into v_settings_bank_system,
         v_settings_external_paye_system,
         v_settings_rail_provider,
         v_settings_rail_env,
         v_need_name_check,
         v_requires_payee_map
    from public.settings_defaults as settings_row
    order by settings_row.id asc
    limit 1;

    if v_settings_bank_system is null or v_settings_external_paye_system is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context settings_defaults missing banking_system/external_paye_system';
    end if;

    if v_settings_rail_provider is null or v_settings_rail_env is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context settings_defaults missing rail provider/environment';
    end if;

    select finance_window.vat_rate_pct,
           finance_window.erni_pct
    into v_vat_rate_pct,
         v_erni_pct
    from public.settings_finance_windows as finance_window
    where v_pay_batch.pay_date >= finance_window.date_from
      and v_pay_batch.pay_date <= coalesce(finance_window.date_to, 'infinity'::date)
    order by finance_window.date_from desc
    limit 1;

    if v_vat_rate_pct is null or v_erni_pct is null then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context no matching finance window for pay date %', v_pay_batch.pay_date;
    end if;

    create temporary table if not exists pg_temp.tmp_pay_build_settings_context (
        banking_system text,
        external_paye_system text,
        rail_provider_default text,
        rail_env_default text,
        need_name_check boolean,
        requires_payee_map boolean,
        vat_rate_pct numeric,
        erni_pct numeric,
        pay_week_start date
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_settings_context;

    insert into pg_temp.tmp_pay_build_settings_context (
        banking_system,
        external_paye_system,
        rail_provider_default,
        rail_env_default,
        need_name_check,
        requires_payee_map,
        vat_rate_pct,
        erni_pct,
        pay_week_start
    ) values (
        v_settings_bank_system,
        v_settings_external_paye_system,
        v_settings_rail_provider,
        v_settings_rail_env,
        v_need_name_check,
        v_requires_payee_map,
        v_vat_rate_pct,
        v_erni_pct,
        v_week_start
    );

    create temporary table if not exists pg_temp.tmp_pay_build_preview_candidates (
        cand jsonb not null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_preview_candidates;

    insert into pg_temp.tmp_pay_build_preview_candidates(cand)
    select candidate_json.cand
    from (
        select staged_scope.effective_paye_candidate_json as cand
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        where jsonb_typeof(staged_scope.effective_paye_candidate_json) = 'object'
          and nullif(btrim(coalesce(staged_scope.effective_paye_candidate_json->>'candidate_id', '')), '') is not null
        union all
        select staged_scope.effective_non_paye_payee_json as cand
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        where jsonb_typeof(staged_scope.effective_non_paye_payee_json) = 'object'
          and nullif(btrim(coalesce(staged_scope.effective_non_paye_payee_json->>'candidate_id', '')), '') is not null
    ) as candidate_json;

    create temporary table if not exists pg_temp.tmp_pay_build_selected_preview_rows (
        preview_row_id text primary key,
        candidate_id uuid not null,
        finance_case_id uuid null,
        timesheet_id uuid null,
        client_id uuid null,
        line_type text null,
        case_type text null,
        pay_channel text null,
        paye_treatment text null,
        routing_kind text null,
        destination_label text null,
        taxability text null,
        beneficiary_name text null,
        masked_bank_account text null,
        bank_details_hash text null,
        item_direction text null,
        item_type_label text null,
        source_ref text null,
        preview_amount_ex_vat numeric(12,2) null,
        draftable boolean not null,
        snooze_allowed boolean not null,
        is_candidate_directed_oneoff_payout boolean not null,
        appears_on_umbrella_remittance boolean not null,
        generates_candidate_payment_advice boolean not null,
        case_components_json jsonb null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_selected_preview_rows;

    insert into pg_temp.tmp_pay_build_selected_preview_rows (
        preview_row_id,
        candidate_id,
        finance_case_id,
        timesheet_id,
        client_id,
        line_type,
        case_type,
        pay_channel,
        paye_treatment,
        routing_kind,
        destination_label,
        taxability,
        beneficiary_name,
        masked_bank_account,
        bank_details_hash,
        item_direction,
        item_type_label,
        source_ref,
        preview_amount_ex_vat,
        draftable,
        snooze_allowed,
        is_candidate_directed_oneoff_payout,
        appears_on_umbrella_remittance,
        generates_candidate_payment_advice,
        case_components_json
    )
    select distinct on (line_rows.preview_row_id)
        line_rows.preview_row_id,
        line_rows.candidate_id,
        line_rows.finance_case_id,
        line_rows.timesheet_id,
        line_rows.client_id,
        line_rows.line_type,
        line_rows.case_type,
        line_rows.pay_channel,
        line_rows.paye_treatment,
        line_rows.routing_kind,
        line_rows.destination_label,
        line_rows.taxability,
        line_rows.beneficiary_name,
        line_rows.masked_bank_account,
        line_rows.bank_details_hash,
        line_rows.item_direction,
        line_rows.item_type_label,
        line_rows.source_ref,
        line_rows.preview_amount_ex_vat,
        line_rows.draftable,
        line_rows.snooze_allowed,
        line_rows.is_candidate_directed_oneoff_payout,
        line_rows.appears_on_umbrella_remittance,
        line_rows.generates_candidate_payment_advice,
        line_rows.case_components_json
    from (
        select
            coalesce(nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''), nullif(btrim(coalesce(line_element.value->>'id', '')), '')) as preview_row_id,
            case when coalesce(line_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end as candidate_id,
            case when coalesce(line_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'finance_case_id')::uuid else null::uuid end as finance_case_id,
            case when coalesce(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'timesheet_id')::uuid else null::uuid end as timesheet_id,
            case when coalesce(line_element.value->>'client_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (line_element.value->>'client_id')::uuid else null::uuid end as client_id,
            nullif(btrim(coalesce(line_element.value->>'line_type', '')), '') as line_type,
            nullif(btrim(coalesce(line_element.value->>'case_type', '')), '') as case_type,
            upper(btrim(coalesce(line_element.value->>'pay_channel', staged_scope.pay_channel, ''))) as pay_channel,
            upper(btrim(coalesce(line_element.value->>'paye_treatment', ''))) as paye_treatment,
            nullif(btrim(coalesce(line_element.value->>'routing_kind', '')), '') as routing_kind,
            nullif(btrim(coalesce(line_element.value->>'destination_label', '')), '') as destination_label,
            nullif(btrim(coalesce(line_element.value->>'taxability', '')), '') as taxability,
            nullif(btrim(coalesce(line_element.value->>'beneficiary_name', '')), '') as beneficiary_name,
            nullif(btrim(coalesce(line_element.value->>'masked_bank_account', '')), '') as masked_bank_account,
            nullif(btrim(coalesce(line_element.value->>'bank_details_hash', '')), '') as bank_details_hash,
            nullif(btrim(coalesce(line_element.value->>'item_direction', '')), '') as item_direction,
            nullif(btrim(coalesce(line_element.value->>'item_type_label', '')), '') as item_type_label,
            nullif(btrim(coalesce(line_element.value->>'source_ref', '')), '') as source_ref,
            round(coalesce(
                case when coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (line_element.value->>'amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (line_element.value->>'preview_amount_ex_vat')::numeric else null::numeric end,
                0::numeric
            ), 2)::numeric(12,2) as preview_amount_ex_vat,
            coalesce(case when lower(coalesce(line_element.value->>'draftable', '')) in ('true', 'false') then (line_element.value->>'draftable')::boolean else null::boolean end, true) as draftable,
            coalesce(case when lower(coalesce(line_element.value->>'snooze_allowed', '')) in ('true', 'false') then (line_element.value->>'snooze_allowed')::boolean else null::boolean end, false) as snooze_allowed,
            coalesce(case when lower(coalesce(line_element.value->>'is_candidate_directed_oneoff_payout', '')) in ('true', 'false') then (line_element.value->>'is_candidate_directed_oneoff_payout')::boolean else null::boolean end, false) as is_candidate_directed_oneoff_payout,
            coalesce(case when lower(coalesce(line_element.value->>'appears_on_umbrella_remittance', '')) in ('true', 'false') then (line_element.value->>'appears_on_umbrella_remittance')::boolean else null::boolean end, false) as appears_on_umbrella_remittance,
            coalesce(case when lower(coalesce(line_element.value->>'generates_candidate_payment_advice', '')) in ('true', 'false') then (line_element.value->>'generates_candidate_payment_advice')::boolean else null::boolean end, false) as generates_candidate_payment_advice,
            case
              when upper(btrim(coalesce(line_element.value->>'line_type', ''))) in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
               and jsonb_typeof(coalesce(line_element.value->'case_components', line_element.value->'components')) = 'array'
               and jsonb_array_length(coalesce(line_element.value->'case_components', line_element.value->'components')) = 1
              then (
                select jsonb_build_array(
                  component_element.value
                  || coalesce(line_element.value->'frozen_component_snapshot_json', '{}'::jsonb)
                  || jsonb_strip_nulls(jsonb_build_object(
                    'finance_component_id', line_element.value->>'finance_component_id',
                    'component_key_type', coalesce(
                      line_element.value->>'frozen_component_key_type',
                      line_element.value->>'component_key_type'
                    ),
                    'component_key_value', coalesce(
                      line_element.value->>'frozen_component_key_value',
                      line_element.value->>'component_key_value'
                    ),
                    'classification', coalesce(
                      line_element.value->>'frozen_component_classification',
                      line_element.value->>'classification'
                    ),
                    'source_pay_method', coalesce(
                      line_element.value#>>'{frozen_component_snapshot_json,source_pay_method}',
                      line_element.value->>'frozen_source_pay_method'
                    ),
                    'source_basis_json', coalesce(
                      line_element.value->'frozen_source_basis_json',
                      line_element.value->'source_basis_json'
                    ),
                    'saved_resolution_mode', coalesce(
                      line_element.value->>'frozen_resolution_mode',
                      line_element.value->>'saved_resolution_mode'
                    ),
                    'saved_resolution_payload_json', coalesce(
                      line_element.value->'frozen_resolution_payload_json',
                      line_element.value->'saved_resolution_payload_json',
                      line_element.value->'resolution_payload_json'
                    ),
                    'saved_resolution_result_json', coalesce(
                      line_element.value->'frozen_resolution_result_json',
                      line_element.value->'saved_resolution_result_json',
                      line_element.value->'resolution_result_json'
                    ),
                    'source_amount', coalesce(
                      line_element.value->>'frozen_source_amount',
                      line_element.value->>'source_amount_ex_vat',
                      line_element.value->>'source_amount'
                    ),
                    'remaining_source_amount', coalesce(
                      component_element.value->>'remaining_source_amount',
                      line_element.value->>'remaining_source_amount',
                      line_element.value->>'frozen_source_amount',
                      line_element.value->>'source_amount_ex_vat'
                    ),
                    'preview_due_amount_ex_vat', coalesce(
                      component_element.value->>'preview_due_amount_ex_vat',
                      line_element.value->>'preview_amount_ex_vat',
                      line_element.value->>'amount_ex_vat'
                    ),
                    'target_pay_ex_vat', coalesce(
                      component_element.value->>'target_pay_ex_vat',
                      line_element.value->>'target_pay_ex_vat',
                      line_element.value->>'preview_amount_ex_vat',
                      line_element.value->>'amount_ex_vat'
                    )
                  ))
                )
                from jsonb_array_elements(
                  coalesce(line_element.value->'case_components', line_element.value->'components')
                ) as component_element(value)
              )
              else coalesce(line_element.value->'case_components', line_element.value->'components', '[]'::jsonb)
            end as case_components_json,
            line_element.ord as line_ordinal
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        cross join lateral jsonb_array_elements(staged_scope.selected_canonical_preview_lines_json) with ordinality as line_element(value, ord)
        where jsonb_typeof(line_element.value) = 'object'
    ) as line_rows
    where line_rows.preview_row_id is not null
      and line_rows.candidate_id is not null
      and line_rows.draftable = true
    order by line_rows.preview_row_id, line_rows.line_ordinal;

    select count(*)::integer
    into v_selected_row_count
    from pg_temp.tmp_pay_build_selected_preview_rows as selected_row;

    if coalesce(v_selected_row_count, 0) = 0 then
        raise exception 'pay_batch_stage_operation_candidate_chunk_context staged no selected preview rows for operation %, batch %', p_operation_id, p_pay_batch_id;
    end if;

    create temporary table if not exists pg_temp.tmp_pay_build_hidden_template_input_rows (
        candidate_id uuid null,
        finance_case_id uuid null,
        recovery_family text null,
        paye_treatment text null,
        raw_pay_channel text null,
        normalized_pay_channel text null,
        umbrella_id uuid null,
        source_ref text null,
        finance_component_id uuid null,
        frozen_component_key_type text null,
        frozen_component_key_value text null,
        frozen_component_snapshot_json jsonb null,
        frozen_component_classification public.pay_finance_component_classification_enum null,
        frozen_source_basis_json jsonb null,
        frozen_source_pay_method text null,
        frozen_target_pay_method text null,
        frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        frozen_resolution_payload_json jsonb null,
        frozen_resolution_result_json jsonb null,
        frozen_source_amount numeric(12,2) null,
        frozen_outstanding_amount numeric(12,2) null,
        weekly_due numeric(12,2) null,
        minimum_earnings_threshold numeric null,
        take_home_floor_override numeric null,
        default_take_home_floor numeric null,
        payout_status text null,
        next_due_week_start date null,
        sort_order integer null,
        required_identifiers_present boolean not null,
        candidate_selected boolean not null,
        pay_channel_matches_scope boolean not null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_hidden_template_input_rows;

    insert into pg_temp.tmp_pay_build_hidden_template_input_rows (
        candidate_id,
        finance_case_id,
        recovery_family,
        paye_treatment,
        raw_pay_channel,
        normalized_pay_channel,
        umbrella_id,
        source_ref,
        finance_component_id,
        frozen_component_key_type,
        frozen_component_key_value,
        frozen_component_snapshot_json,
        frozen_component_classification,
        frozen_source_basis_json,
        frozen_source_pay_method,
        frozen_target_pay_method,
        frozen_resolution_mode,
        frozen_resolution_payload_json,
        frozen_resolution_result_json,
        frozen_source_amount,
        frozen_outstanding_amount,
        weekly_due,
        minimum_earnings_threshold,
        take_home_floor_override,
        default_take_home_floor,
        payout_status,
        next_due_week_start,
        sort_order,
        required_identifiers_present,
        candidate_selected,
        pay_channel_matches_scope
    )
    select
        case when coalesce(template_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end,
        case when coalesce(template_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'finance_case_id')::uuid else null::uuid end,
        upper(btrim(coalesce(template_element.value->>'recovery_family', ''))),
        upper(nullif(btrim(coalesce(template_element.value->>'paye_treatment', '')), '')),
        upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')),
        case
            when upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) in ('PAYE', 'UMBRELLA') then upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), ''))
            when coalesce(btrim(coalesce(template_element.value->>'pay_channel', '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
            else null::text
        end,
        case when coalesce(template_element.value->>'umbrella_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'umbrella_id')::uuid else null::uuid end,
        nullif(btrim(coalesce(template_element.value->>'source_ref', '')), ''),
        case when coalesce(template_element.value->>'finance_component_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'finance_component_id')::uuid else null::uuid end,
        nullif(btrim(coalesce(template_element.value->>'frozen_component_key_type', '')), ''),
        nullif(btrim(coalesce(template_element.value->>'frozen_component_key_value', '')), ''),
        case when jsonb_typeof(template_element.value->'frozen_component_snapshot_json') = 'object' then template_element.value->'frozen_component_snapshot_json' else null::jsonb end,
        case
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_component_classification', ''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
            else null::public.pay_finance_component_classification_enum
        end,
        case when jsonb_typeof(template_element.value->'frozen_source_basis_json') = 'object' then template_element.value->'frozen_source_basis_json' else null::jsonb end,
        upper(nullif(btrim(coalesce(template_element.value->>'frozen_source_pay_method', '')), '')),
        upper(nullif(btrim(coalesce(template_element.value->>'frozen_target_pay_method', '')), '')),
        case
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_REPLACEMENT_RATE' then 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
            when upper(btrim(coalesce(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_AMOUNT' then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
            else null::public.pay_finance_component_resolution_mode_enum
        end,
        case when jsonb_typeof(template_element.value->'frozen_resolution_payload_json') = 'object' then template_element.value->'frozen_resolution_payload_json' else null::jsonb end,
        case when jsonb_typeof(template_element.value->'frozen_resolution_result_json') = 'object' then template_element.value->'frozen_resolution_result_json' else null::jsonb end,
        case when coalesce(template_element.value->>'frozen_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'frozen_source_amount')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'frozen_outstanding_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'frozen_outstanding_amount')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'weekly_due', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((template_element.value->>'weekly_due')::numeric, 2)::numeric(12,2) else null::numeric(12,2) end,
        case when coalesce(template_element.value->>'minimum_earnings_threshold', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'minimum_earnings_threshold')::numeric else null::numeric end,
        case when coalesce(template_element.value->>'take_home_floor_override', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'take_home_floor_override')::numeric else null::numeric end,
        case when coalesce(template_element.value->>'default_take_home_floor', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (template_element.value->>'default_take_home_floor')::numeric else null::numeric end,
        nullif(btrim(coalesce(template_element.value->>'payout_status', '')), ''),
        case when coalesce(template_element.value->>'next_due_week_start', '') ~ '^\d{4}-\d{2}-\d{2}$' then (template_element.value->>'next_due_week_start')::date else null::date end,
        case when coalesce(template_element.value->>'sort_order', '') ~ '^-?[0-9]+$' then (template_element.value->>'sort_order')::integer else template_element.ord::integer end,
        (
            (case when coalesce(template_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (template_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end) is not null
            and coalesce(template_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            and upper(btrim(coalesce(template_element.value->>'recovery_family', ''))) in ('MANUAL_DEBT_RECOVERY', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY')
        ),
        true,
        case
            when upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) in ('PAYE', 'UMBRELLA') then upper(nullif(btrim(coalesce(template_element.value->>'pay_channel', '')), '')) = v_scope
            when coalesce(btrim(coalesce(template_element.value->>'pay_channel', '')), '') = '' and v_scope = 'PAYE' then true
            else false
        end
    from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
    cross join lateral jsonb_array_elements(staged_scope.hidden_recovery_template_lines_json) with ordinality as template_element(value, ord)
    where jsonb_typeof(template_element.value) = 'object';

    create temporary table if not exists pg_temp.tmp_pay_build_recovery_template_rows (
        candidate_id uuid not null,
        finance_case_id uuid not null,
        recovery_family text not null,
        paye_treatment text null,
        pay_channel text null,
        umbrella_id uuid null,
        source_ref text null,
        finance_component_id uuid null,
        frozen_component_key_type text null,
        frozen_component_key_value text null,
        frozen_component_snapshot_json jsonb null,
        frozen_component_classification public.pay_finance_component_classification_enum null,
        frozen_source_basis_json jsonb null,
        frozen_source_pay_method text null,
        frozen_target_pay_method text null,
        frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        frozen_resolution_payload_json jsonb null,
        frozen_resolution_result_json jsonb null,
        frozen_source_amount numeric(12,2) null,
        frozen_outstanding_amount numeric(12,2) null,
        weekly_due numeric(12,2) null,
        minimum_earnings_threshold numeric null,
        take_home_floor_override numeric null,
        default_take_home_floor numeric null,
        payout_status text null,
        next_due_week_start date null,
        sort_order integer null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_recovery_template_rows;

    insert into pg_temp.tmp_pay_build_recovery_template_rows (
        candidate_id,
        finance_case_id,
        recovery_family,
        paye_treatment,
        pay_channel,
        umbrella_id,
        source_ref,
        finance_component_id,
        frozen_component_key_type,
        frozen_component_key_value,
        frozen_component_snapshot_json,
        frozen_component_classification,
        frozen_source_basis_json,
        frozen_source_pay_method,
        frozen_target_pay_method,
        frozen_resolution_mode,
        frozen_resolution_payload_json,
        frozen_resolution_result_json,
        frozen_source_amount,
        frozen_outstanding_amount,
        weekly_due,
        minimum_earnings_threshold,
        take_home_floor_override,
        default_take_home_floor,
        payout_status,
        next_due_week_start,
        sort_order
    )
    select distinct on (
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        coalesce(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
        coalesce(hidden_input.source_ref, ''),
        coalesce(hidden_input.normalized_pay_channel, '')
    )
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        hidden_input.paye_treatment,
        hidden_input.normalized_pay_channel,
        hidden_input.umbrella_id,
        hidden_input.source_ref,
        hidden_input.finance_component_id,
        hidden_input.frozen_component_key_type,
        hidden_input.frozen_component_key_value,
        hidden_input.frozen_component_snapshot_json,
        hidden_input.frozen_component_classification,
        hidden_input.frozen_source_basis_json,
        hidden_input.frozen_source_pay_method,
        hidden_input.frozen_target_pay_method,
        hidden_input.frozen_resolution_mode,
        hidden_input.frozen_resolution_payload_json,
        hidden_input.frozen_resolution_result_json,
        hidden_input.frozen_source_amount,
        hidden_input.frozen_outstanding_amount,
        hidden_input.weekly_due,
        hidden_input.minimum_earnings_threshold,
        hidden_input.take_home_floor_override,
        hidden_input.default_take_home_floor,
        hidden_input.payout_status,
        hidden_input.next_due_week_start,
        hidden_input.sort_order
    from pg_temp.tmp_pay_build_hidden_template_input_rows as hidden_input
    where hidden_input.candidate_selected = true
      and hidden_input.required_identifiers_present = true
      and hidden_input.pay_channel_matches_scope = true
    order by
        hidden_input.candidate_id,
        hidden_input.finance_case_id,
        hidden_input.recovery_family,
        coalesce(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
        coalesce(hidden_input.source_ref, ''),
        coalesce(hidden_input.normalized_pay_channel, ''),
        hidden_input.sort_order;

    create temporary table if not exists pg_temp.tmp_pay_build_candidates_ctx (
        id uuid primary key,
        tms_ref text,
        display_name text,
        pay_method text,
        umbrella_id uuid,
        first_name text,
        last_name text,
        account_holder text,
        sort_code text,
        account_number text,
        bank_details_hash text,
        payee_id text,
        payee_account_id text,
        umbrella_vat_chargeable boolean
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_candidates_ctx;

    create temporary table if not exists pg_temp.tmp_pay_build_umbrellas_ctx (
        id uuid primary key,
        name text,
        vat_chargeable boolean,
        sort_code text,
        account_number text,
        bank_details_hash text,
        payee_id text,
        payee_account_id text
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_umbrellas_ctx;

    insert into pg_temp.tmp_pay_build_candidates_ctx (
        id,
        tms_ref,
        display_name,
        pay_method,
        umbrella_id,
        first_name,
        last_name,
        account_holder,
        sort_code,
        account_number,
        bank_details_hash,
        payee_id,
        payee_account_id,
        umbrella_vat_chargeable
    )
    with preview_candidate_rows as (
        select distinct on (preview_candidate_data.preview_candidate_id)
            preview_candidate_data.preview_candidate_id,
            preview_candidate_data.preview_tms_ref,
            preview_candidate_data.preview_display_name,
            preview_candidate_data.preview_pay_method,
            preview_candidate_data.preview_umbrella_id,
            preview_candidate_data.preview_umbrella_vat_chargeable,
            preview_candidate_data.preview_candidate_bank_hash
        from (
            select
                case when coalesce(preview_candidate.cand->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (preview_candidate.cand->>'candidate_id')::uuid else null::uuid end as preview_candidate_id,
                nullif(btrim(coalesce(preview_candidate.cand->>'tms_ref', '')), '') as preview_tms_ref,
                nullif(btrim(coalesce(preview_candidate.cand->>'display_name', '')), '') as preview_display_name,
                upper(nullif(btrim(coalesce(preview_candidate.cand->>'current_pay_method', '')), '')) as preview_pay_method,
                case when coalesce(preview_candidate.cand->>'umbrella_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (preview_candidate.cand->>'umbrella_id')::uuid else null::uuid end as preview_umbrella_id,
                coalesce(case when lower(coalesce(preview_candidate.cand->>'umbrella_vat_chargeable', '')) in ('true', 'false') then (preview_candidate.cand->>'umbrella_vat_chargeable')::boolean else null::boolean end, false) as preview_umbrella_vat_chargeable,
                nullif(btrim(coalesce(preview_candidate.cand->>'candidate_bank_hash', '')), '') as preview_candidate_bank_hash
            from pg_temp.tmp_pay_build_preview_candidates as preview_candidate
        ) as preview_candidate_data
        where preview_candidate_data.preview_candidate_id is not null
        order by preview_candidate_data.preview_candidate_id
    )
    select
        candidate_row.id,
        coalesce(preview_candidate_rows.preview_tms_ref, candidate_row.tms_ref),
        coalesce(preview_candidate_rows.preview_display_name, candidate_row.display_name),
        coalesce(preview_candidate_rows.preview_pay_method, upper(coalesce(candidate_row.pay_method, ''))),
        coalesce(preview_candidate_rows.preview_umbrella_id, candidate_row.umbrella_id),
        candidate_row.first_name,
        candidate_row.last_name,
        candidate_row.account_holder,
        regexp_replace(coalesce(candidate_row.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(candidate_row.account_number, ''), '[^0-9]', '', 'g'), ''),
        coalesce(preview_candidate_rows.preview_candidate_bank_hash, candidate_row.bank_details_hash),
        candidate_payee_map.payee_id,
        candidate_payee_map.payee_account_id,
        coalesce(preview_candidate_rows.preview_umbrella_vat_chargeable, umbrella_row.vat_chargeable, false)
    from (
        select distinct selected_row.candidate_id
        from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
    ) as selected_candidate
    join public.candidates as candidate_row
      on candidate_row.id = selected_candidate.candidate_id
    left join preview_candidate_rows
      on preview_candidate_rows.preview_candidate_id = candidate_row.id
    left join public.umbrellas as umbrella_row
      on umbrella_row.id = coalesce(preview_candidate_rows.preview_umbrella_id, candidate_row.umbrella_id)
    left join public.bank_payee_map as candidate_payee_map
      on upper(coalesce(candidate_payee_map.rail_provider, '')) = upper(btrim(coalesce(v_settings_rail_provider, '')))
     and upper(coalesce(candidate_payee_map.rail_env, '')) = upper(btrim(coalesce(v_settings_rail_env, '')))
     and upper(coalesce(candidate_payee_map.entity_kind, '')) = 'CANDIDATE'
     and candidate_payee_map.entity_id = candidate_row.id
     and candidate_payee_map.bank_details_hash = coalesce(preview_candidate_rows.preview_candidate_bank_hash, candidate_row.bank_details_hash);

    insert into pg_temp.tmp_pay_build_umbrellas_ctx (
        id,
        name,
        vat_chargeable,
        sort_code,
        account_number,
        bank_details_hash,
        payee_id,
        payee_account_id
    )
    select
        umbrella_row.id,
        umbrella_row.name,
        coalesce(umbrella_row.vat_chargeable, false),
        regexp_replace(coalesce(umbrella_row.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(umbrella_row.account_number, ''), '[^0-9]', '', 'g'), ''),
        umbrella_row.bank_details_hash,
        umbrella_payee_map.payee_id,
        umbrella_payee_map.payee_account_id
    from public.umbrellas as umbrella_row
    join (
        select distinct candidate_ctx.umbrella_id
        from pg_temp.tmp_pay_build_candidates_ctx as candidate_ctx
        where candidate_ctx.umbrella_id is not null
    ) as selected_umbrella
      on selected_umbrella.umbrella_id = umbrella_row.id
    left join public.bank_payee_map as umbrella_payee_map
      on upper(coalesce(umbrella_payee_map.rail_provider, '')) = upper(btrim(coalesce(v_settings_rail_provider, '')))
     and upper(coalesce(umbrella_payee_map.rail_env, '')) = upper(btrim(coalesce(v_settings_rail_env, '')))
     and upper(coalesce(umbrella_payee_map.entity_kind, '')) = 'UMBRELLA'
     and umbrella_payee_map.entity_id = umbrella_row.id
     and umbrella_payee_map.bank_details_hash = umbrella_row.bank_details_hash;

    create temporary table if not exists pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
        timesheet_id uuid primary key,
        candidate_id uuid not null,
        client_id uuid null,
        week_ending_date date null,
        source_pay_method text null,
        candidate_pay_method text null,
        baseline_signature text null,
        base_snapshot_json jsonb not null,
        target_snapshot_json jsonb not null,
        target_signature text null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_timesheet_snapshots_ctx;

    insert into pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
        timesheet_id,
        candidate_id,
        client_id,
        week_ending_date,
        source_pay_method,
        candidate_pay_method,
        baseline_signature,
        base_snapshot_json,
        target_snapshot_json,
        target_signature
    )
    select distinct on (snapshot_row.timesheet_id)
        snapshot_row.timesheet_id,
        snapshot_row.candidate_id,
        snapshot_row.client_id,
        snapshot_row.week_ending_date,
        snapshot_row.source_pay_method,
        snapshot_row.candidate_pay_method,
        snapshot_row.baseline_signature,
        snapshot_row.base_snapshot_json,
        snapshot_row.target_snapshot_json,
        snapshot_row.target_signature
    from (
        select
            case when coalesce(snapshot_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'timesheet_id')::uuid else null::uuid end as timesheet_id,
            case when coalesce(snapshot_element.value->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'candidate_id')::uuid else staged_scope.candidate_id end as candidate_id,
            case when coalesce(snapshot_element.value->>'client_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (snapshot_element.value->>'client_id')::uuid else null::uuid end as client_id,
            case when coalesce(snapshot_element.value->>'week_ending_date', '') ~ '^\d{4}-\d{2}-\d{2}$' then (snapshot_element.value->>'week_ending_date')::date else null::date end as week_ending_date,
            nullif(btrim(coalesce(snapshot_element.value->>'source_pay_method', '')), '') as source_pay_method,
            nullif(btrim(coalesce(snapshot_element.value->>'candidate_pay_method', '')), '') as candidate_pay_method,
            nullif(btrim(coalesce(snapshot_element.value->>'baseline_signature', '')), '') as baseline_signature,
            coalesce(snapshot_element.value->'base_snapshot_json', '{}'::jsonb) as base_snapshot_json,
            coalesce(snapshot_element.value->'target_snapshot_json', '{}'::jsonb) as target_snapshot_json,
            nullif(btrim(coalesce(snapshot_element.value->>'target_signature', '')), '') as target_signature
        from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
        cross join lateral jsonb_array_elements(
            case
                when jsonb_typeof(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots_json') = 'array' then coalesce(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots_json', '[]'::jsonb)
                when jsonb_typeof(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots') = 'array' then coalesce(staged_scope.effective_candidate_fragment_json->'timesheet_snapshots', '[]'::jsonb)
                else '[]'::jsonb
            end
        ) as snapshot_element(value)
        where jsonb_typeof(snapshot_element.value) = 'object'
    ) as snapshot_row
    where snapshot_row.timesheet_id is not null
      and exists (
          select 1
          from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
          where selected_row.timesheet_id = snapshot_row.timesheet_id
            and selected_row.candidate_id = snapshot_row.candidate_id
      )
    order by snapshot_row.timesheet_id, snapshot_row.week_ending_date desc nulls last;

    create temporary table if not exists pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
        finance_case_id uuid primary key,
        beneficiary_name text,
        sort_code text,
        account_number text,
        bank_details_hash text,
        created_by_user_id uuid,
        updated_by_user_id uuid,
        note text
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx;

    insert into pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
        finance_case_id,
        beneficiary_name,
        sort_code,
        account_number,
        bank_details_hash,
        created_by_user_id,
        updated_by_user_id,
        note
    )
    select
        oneoff_details.finance_case_id,
        oneoff_details.beneficiary_name,
        regexp_replace(coalesce(oneoff_details.sort_code, ''), '[^0-9]', '', 'g'),
        nullif(regexp_replace(coalesce(oneoff_details.account_number, ''), '[^0-9]', '', 'g'), ''),
        oneoff_details.bank_details_hash,
        oneoff_details.created_by_user_id,
        oneoff_details.updated_by_user_id,
        oneoff_details.note
    from public.pay_finance_case_oneoff_payout_bank_details as oneoff_details
    where oneoff_details.finance_case_id in (
        select distinct selected_row.finance_case_id
        from pg_temp.tmp_pay_build_selected_preview_rows as selected_row
        where selected_row.finance_case_id is not null
    );

    create temporary table if not exists pg_temp.tmp_pay_build_finance_case_components_ctx (
        id uuid primary key,
        finance_case_id uuid not null,
        candidate_id uuid null,
        linked_timesheet_id uuid null,
        component_key_type text null,
        component_key_value text null,
        classification public.pay_finance_component_classification_enum null,
        source_pay_method text null,
        source_basis_json jsonb null,
        saved_target_pay_method text null,
        saved_resolution_mode public.pay_finance_component_resolution_mode_enum null,
        saved_resolution_payload_json jsonb null,
        saved_resolution_result_json jsonb null,
        source_amount numeric(12,2) null,
        remaining_source_amount numeric(12,2) null,
        allocation_priority_group integer null,
        allocation_priority_order integer null,
        created_at_utc timestamptz null
    ) on commit drop;
    truncate table pg_temp.tmp_pay_build_finance_case_components_ctx;

    -- Operation-mode staging must use the frozen operation candidate/allocation scope.
    -- Do not rebuild finance component identity from live public.pay_finance_case_components here.
    -- The child batch-builder functions read this temp table, so expose allocation rows in the same shape.
    insert into pg_temp.tmp_pay_build_finance_case_components_ctx (
        id,
        finance_case_id,
        candidate_id,
        linked_timesheet_id,
        component_key_type,
        component_key_value,
        classification,
        source_pay_method,
        source_basis_json,
        saved_target_pay_method,
        saved_resolution_mode,
        saved_resolution_payload_json,
        saved_resolution_result_json,
        source_amount,
        remaining_source_amount,
        allocation_priority_group,
        allocation_priority_order,
        created_at_utc
    )
    select distinct on (coalesce(allocation_row.finance_component_id, allocation_row.id))
        coalesce(allocation_row.finance_component_id, allocation_row.id) as id,
        allocation_row.finance_case_id,
        allocation_row.candidate_id,
        case
            when coalesce(allocation_row.allocation_basis_json #>> '{line,timesheet_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then (allocation_row.allocation_basis_json #>> '{line,timesheet_id}')::uuid
            else null::uuid
        end as linked_timesheet_id,
        coalesce(
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,frozen_component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,economic_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,frozen_component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,component_key_type}'), ''),
            nullif(btrim(allocation_row.allocation_type), '')
        ) as component_key_type,
        coalesce(
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,frozen_component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{line,economic_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,frozen_component_key_value}'), ''),
            nullif(btrim(allocation_row.allocation_basis_json #>> '{component,component_key_value}'), ''),
            allocation_row.operation_source_key
        ) as component_key_value,
        case
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'TAXABLE_CHANNEL_SENSITIVE'
                then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'REIMBURSEMENT_GROSS_FIXED'
                then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_component_classification}', allocation_row.allocation_basis_json #>> '{component,classification}', '')) = 'NET_PAY_FIXED_RECOVERY'
                then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
            else null::public.pay_finance_component_classification_enum
        end as classification,
        upper(nullif(btrim(coalesce(
            allocation_row.allocation_basis_json #>> '{line,frozen_source_pay_method}',
            allocation_row.allocation_basis_json #>> '{line,source_pay_method}',
            allocation_row.allocation_basis_json #>> '{component,source_pay_method}',
            allocation_row.pay_channel
        )), '')) as source_pay_method,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_source_basis_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'source_basis_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'source_basis_json', 'null'::jsonb),
            allocation_row.allocation_basis_json
        ) as source_basis_json,
        upper(nullif(btrim(coalesce(
            allocation_row.allocation_basis_json #>> '{line,frozen_target_pay_method}',
            allocation_row.allocation_basis_json #>> '{line,target_pay_method}',
            allocation_row.allocation_basis_json #>> '{component,saved_target_pay_method}',
            allocation_row.pay_channel
        )), '')) as saved_target_pay_method,
        case
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'SUGGESTED_EQUIVALENT_BASIS'
                then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'MANUAL_REPLACEMENT_RATE'
                then 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
            when upper(coalesce(allocation_row.allocation_basis_json #>> '{line,frozen_resolution_mode}', allocation_row.allocation_basis_json #>> '{component,saved_resolution_mode}', '')) = 'MANUAL_AMOUNT'
                then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
            else null::public.pay_finance_component_resolution_mode_enum
        end as saved_resolution_mode,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_resolution_payload_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'resolution_payload_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'saved_resolution_payload_json', 'null'::jsonb),
            '{}'::jsonb
        ) as saved_resolution_payload_json,
        coalesce(
            nullif(allocation_row.allocation_basis_json->'line'->'frozen_resolution_result_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'line'->'resolution_result_json', 'null'::jsonb),
            nullif(allocation_row.allocation_basis_json->'component'->'saved_resolution_result_json', 'null'::jsonb),
            jsonb_build_object('operation_source_key', allocation_row.operation_source_key, 'allocated_amount', allocation_row.allocated_amount)
        ) as saved_resolution_result_json,
        round(abs(coalesce(allocation_row.allocated_amount, 0)), 2)::numeric(12,2) as source_amount,
        round(abs(coalesce(allocation_row.allocated_amount, 0)), 2)::numeric(12,2) as remaining_source_amount,
        0::integer as allocation_priority_group,
        coalesce(allocation_row.sort_order, 0)::integer as allocation_priority_order,
        coalesce(allocation_row.created_at_utc, now()) as created_at_utc
    from public.banking_pay_operation_candidate_allocation_rows as allocation_row
    where allocation_row.operation_id = p_operation_id
      and allocation_row.pay_batch_id = p_pay_batch_id
      and allocation_row.candidate_scope_id in (
          select staged_scope.id
          from pg_temp.tmp_pay_build_operation_candidate_scope as staged_scope
      )
      and allocation_row.finance_case_id is not null
    order by coalesce(allocation_row.finance_component_id, allocation_row.id), allocation_row.sort_order nulls last, allocation_row.id;

    select count(*)::integer
    into v_timesheet_snapshot_count
    from pg_temp.tmp_pay_build_timesheet_snapshots_ctx as snapshot_ctx;

    select count(*)::integer
    into v_finance_component_count
    from pg_temp.tmp_pay_build_finance_case_components_ctx as component_ctx;

    return query
    select
        coalesce(v_candidate_count, 0),
        coalesce(v_selected_row_count, 0),
        coalesce(v_timesheet_snapshot_count, 0),
        coalesce(v_finance_component_count, 0);
end;
$function$;

-- pay_batch_submission_evidence(uuid,boolean,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_batch_submission_evidence(p_pay_batch_id uuid, p_counts_only boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_chunk_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'OPERATION_LIGHT'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_mode text := upper(btrim(coalesce(p_mode, 'OPERATION_LIGHT')));
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_id uuid := p_operation_id;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_progress_json jsonb := '{}'::jsonb;
  v_chunk_result_json jsonb := '{}'::jsonb;
  v_chunk_error_json jsonb := '{}'::jsonb;
  v_submitted_count integer := 0;
  v_accepted_count integer := 0;
  v_failed_count integer := 0;
  v_unknown_count integer := 0;
  v_review_required_count integer := 0;
  v_remaining_ready_count integer := 0;
  v_claimed_count integer := 0;
  v_request_sent_count integer := 0;
  v_total_scope_count integer := 0;
  v_last_provider_message text := NULL::text;
  v_last_provider_state text := NULL::text;
  v_last_provider_at_utc text := NULL::text;
  v_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_completed_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_transfer_count integer := 0;
  v_terminal_no_money_count integer := 0;
  v_final_money_moved_count integer := 0;
  v_materialised_transfer_count integer := 0;
  v_materialised_final_money_moved_count integer := 0;
  v_materialised_terminal_no_money_count integer := 0;
  v_materialised_pending_non_final_count integer := 0;
  v_materialised_unknown_or_review_count integer := 0;
  v_materialised_last_provider_state text := NULL::text;
  v_materialised_last_provider_at_utc text := NULL::text;
  v_transfer_classification_summary_json jsonb := '{}'::jsonb;
  v_transfer_classification_called boolean := false;
  v_should_classify_transfers boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('DISPLAY');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_mode IS NULL OR v_mode = '' THEN
    v_mode := 'OPERATION_LIGHT';
  END IF;

  IF v_mode NOT IN ('OPERATION_LIGHT', 'LIGHT', 'COUNTS_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_MODE_NOT_SUPPORTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_MODE_NOT_SUPPORTED', 'mode', p_mode)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT chunk_row.*
    INTO v_chunk_row
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = p_chunk_id
      AND (v_operation_id IS NULL OR chunk_row.operation_id = v_operation_id)
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT');

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_CHUNK_NOT_FOUND', 'chunk_id', p_chunk_id::text, 'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END)::text;
    END IF;

    IF v_operation_id IS NULL THEN
      v_operation_id := v_chunk_row.operation_id;
    END IF;

    v_chunk_result_json := coalesce(v_chunk_row.result_json, '{}'::jsonb);
    v_chunk_error_json := coalesce(v_chunk_row.error_json, '{}'::jsonb);
  END IF;

  IF v_operation_id IS NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
             operation_row.created_at_utc DESC NULLS LAST,
             operation_row.id DESC
    LIMIT 1;

    IF FOUND THEN
      v_operation_id := v_operation_row.id;
    END IF;
  ELSE
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = v_operation_id
      AND operation_row.pay_batch_id = p_pay_batch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH', 'pay_batch_id', p_pay_batch_id::text, 'operation_id', v_operation_id::text)::text;
    END IF;
  END IF;

  v_progress_json := coalesce(v_operation_row.progress_json, '{}'::jsonb);

  SELECT
    CASE WHEN coalesce(v_progress_json->>'submitted_count', v_progress_json->>'last_rail_update_count', v_chunk_result_json->>'updated_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'submitted_count', v_progress_json->>'last_rail_update_count', v_chunk_result_json->>'updated_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'accepted_count', v_progress_json->>'last_rail_update_accepted_count', v_chunk_result_json->>'accepted_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'accepted_count', v_progress_json->>'last_rail_update_accepted_count', v_chunk_result_json->>'accepted_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'failed_count', v_progress_json->>'last_rail_update_failed_count', v_chunk_result_json->>'failed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'failed_count', v_progress_json->>'last_rail_update_failed_count', v_chunk_result_json->>'failed_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'unknown_count', v_progress_json->>'last_rail_update_unknown_count', v_chunk_result_json->>'unknown_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'unknown_count', v_progress_json->>'last_rail_update_unknown_count', v_chunk_result_json->>'unknown_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'review_required_count', v_chunk_result_json->>'review_required_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'review_required_count', v_chunk_result_json->>'review_required_count')::integer WHEN coalesce(v_operation_row.requires_user_action, false) IS TRUE OR upper(btrim(coalesce(v_operation_row.status, ''))) = 'REVIEW_REQUIRED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'remaining_ready_count', v_progress_json->>'operation_scope_provider_ready_count', v_progress_json->>'provider_ready_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'remaining_ready_count', v_progress_json->>'operation_scope_provider_ready_count', v_progress_json->>'provider_ready_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'claimed_count', v_progress_json->>'operation_scope_claimed_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'claimed_count', v_progress_json->>'operation_scope_claimed_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'RUNNING' THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'request_sent_count', v_progress_json->>'last_rail_update_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'request_sent_count', v_progress_json->>'last_rail_update_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'transfer_count', v_progress_json->>'operation_transfer_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'transfer_count', v_progress_json->>'operation_transfer_count')::integer WHEN p_chunk_id IS NOT NULL THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'scope_count', v_progress_json->>'operation_scope_count', '') ~ '^-?[0-9]+$' THEN coalesce(v_progress_json->>'scope_count', v_progress_json->>'operation_scope_count')::integer WHEN p_chunk_id IS NOT NULL THEN coalesce(v_chunk_row.unit_count, 0) ELSE 0 END,
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_message', v_chunk_result_json->>'last_provider_message', v_chunk_error_json->>'message', '')), ''), NULL::text),
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_state', v_chunk_result_json->>'provider_submission_status', v_chunk_error_json->>'provider_submission_status', '')), ''), NULL::text),
    coalesce(nullif(btrim(coalesce(v_progress_json->>'last_provider_at_utc', v_chunk_result_json->>'rail_update_applied_at_utc', v_chunk_result_json->>'provider_chunk_finalised_at_utc', '')), ''), NULL::text),
    CASE WHEN coalesce(v_progress_json->>'chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'chunk_count')::integer WHEN p_chunk_id IS NOT NULL THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'running_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'running_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'RUNNING' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'pending_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'pending_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'PENDING' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'completed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'completed_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) IN ('COMPLETE', 'COMPLETED') THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'failed_chunk_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'failed_chunk_count')::integer WHEN p_chunk_id IS NOT NULL AND upper(btrim(coalesce(v_chunk_row.status, ''))) = 'FAILED' THEN 1 ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'terminal_no_money_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'terminal_no_money_count')::integer ELSE 0 END,
    CASE WHEN coalesce(v_progress_json->>'final_money_moved_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'final_money_moved_count')::integer ELSE 0 END
  INTO v_submitted_count,
       v_accepted_count,
       v_failed_count,
       v_unknown_count,
       v_review_required_count,
       v_remaining_ready_count,
       v_claimed_count,
       v_request_sent_count,
       v_transfer_count,
       v_total_scope_count,
       v_last_provider_message,
       v_last_provider_state,
       v_last_provider_at_utc,
       v_chunk_count,
       v_running_chunk_count,
       v_pending_chunk_count,
       v_completed_chunk_count,
       v_failed_chunk_count,
       v_terminal_no_money_count,
       v_final_money_moved_count;

  v_should_classify_transfers := (
    v_operation_id IS NOT NULL
    AND upper(btrim(coalesce(v_operation_row.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (
      upper(btrim(coalesce(v_operation_row.phase, ''))) IN (
        'SUBMIT_PROVIDER_TRANSFERS',
        'SEND_PROVIDER_CHUNK',
        'APPLY_RAIL_UPDATES',
        'START_LOCAL_SETTLEMENT',
        'WAIT_LOCAL_SETTLEMENT',
        'PAYMENT_SETTLEMENT',
        'SETTLEMENT_SCOPE_SEED',
        'SEED_SETTLEMENT_SCOPE',
        'SETTLE_RAIL',
        'QUEUE_REMITTANCES',
        'REMITTANCE_SCOPE_SEED',
        'BUILD_REMITTANCE',
        'COMMIT_REMITTANCE',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_progress_json->>'phase', ''))) IN (
        'SUBMIT_PROVIDER_TRANSFERS',
        'SEND_PROVIDER_CHUNK',
        'APPLY_RAIL_UPDATES',
        'START_LOCAL_SETTLEMENT',
        'WAIT_LOCAL_SETTLEMENT',
        'PAYMENT_SETTLEMENT',
        'SETTLEMENT_SCOPE_SEED',
        'SEED_SETTLEMENT_SCOPE',
        'SETTLE_RAIL',
        'QUEUE_REMITTANCES',
        'REMITTANCE_SCOPE_SEED',
        'BUILD_REMITTANCE',
        'COMMIT_REMITTANCE',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_operation_row.status, ''))) IN (
        'WAITING_PROVIDER',
        'COMPLETE',
        'FAILED',
        'REVIEW_REQUIRED'
      )
      OR upper(btrim(coalesce(v_operation_row.runner_state, ''))) IN (
        'WAITING_PROVIDER',
        'WAITING_USER_REVIEW'
      )
      OR p_chunk_id IS NOT NULL
    )
  );

  IF v_should_classify_transfers IS TRUE THEN
    WITH classified_transfer_rows AS (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      transfer_row.pay_batch_id,
      transfer_row.status AS transfer_status,
      transfer_row.rail_state,
      transfer_row.rail_tx_id,
      transfer_row.completed_at_utc,
      transfer_row.failed_reason,
      transfer_row.amount,
      transfer_row.currency,
      transfer_row.created_at_utc,
      classifier_row.cash_state,
      classifier_row.normalised_transfer_status,
      classifier_row.is_final_money_moved,
      classifier_row.is_terminal_no_money,
      classifier_row.is_pending_non_final,
      classifier_row.reason
    FROM public.pay_bank_transfers AS transfer_row
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      p_transfer_status => transfer_row.status,
      p_rail_state => transfer_row.rail_state,
      p_event_payload_json => COALESCE(transfer_row.rail_meta_json, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'normalised_state', transfer_row.status,
        'provider_state', transfer_row.rail_state,
        'provider_transaction_id', transfer_row.rail_tx_id,
        'failed_reason', transfer_row.failed_reason,
        'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END
      )),
      p_provider_meta_json => COALESCE(transfer_row.rail_meta_json -> 'provider_submit_diagnostic', '{}'::jsonb) || COALESCE(transfer_row.rail_meta_json, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'provider_transaction_id', transfer_row.rail_tx_id,
        'rail_tx_id', transfer_row.rail_tx_id,
        'provider_external_evidence_present', NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL,
        'provider_acceptance_evidence_present', NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL,
        'completed_at_utc', CASE WHEN transfer_row.completed_at_utc IS NULL THEN NULL ELSE transfer_row.completed_at_utc::text END
      ))
    ) AS classifier_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  ), transfer_classification_totals AS (
    SELECT
      COUNT(*)::integer AS transfer_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_final_money_moved, false) IS TRUE)::integer AS final_money_moved_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_terminal_no_money, false) IS TRUE)::integer AS terminal_no_money_count,
      COUNT(*) FILTER (WHERE COALESCE(classified_transfer_rows.is_pending_non_final, false) IS TRUE)::integer AS pending_non_final_count,
      COUNT(*) FILTER (
        WHERE COALESCE(classified_transfer_rows.is_final_money_moved, false) IS NOT TRUE
          AND COALESCE(classified_transfer_rows.is_terminal_no_money, false) IS NOT TRUE
          AND COALESCE(classified_transfer_rows.is_pending_non_final, false) IS NOT TRUE
      )::integer AS unknown_or_review_count,
      (array_agg(NULLIF(BTRIM(COALESCE(classified_transfer_rows.rail_state, classified_transfer_rows.normalised_transfer_status, classified_transfer_rows.transfer_status, '')), '') ORDER BY COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc) DESC NULLS LAST, classified_transfer_rows.pay_bank_transfer_id DESC))[1] AS last_provider_state,
      (array_agg((COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc))::text ORDER BY COALESCE(classified_transfer_rows.completed_at_utc, classified_transfer_rows.created_at_utc) DESC NULLS LAST, classified_transfer_rows.pay_bank_transfer_id DESC))[1] AS last_provider_at_utc
    FROM classified_transfer_rows AS classified_transfer_rows
  )
  SELECT
    COALESCE(transfer_classification_totals.transfer_count, 0),
    COALESCE(transfer_classification_totals.final_money_moved_count, 0),
    COALESCE(transfer_classification_totals.terminal_no_money_count, 0),
    COALESCE(transfer_classification_totals.pending_non_final_count, 0),
    COALESCE(transfer_classification_totals.unknown_or_review_count, 0),
    transfer_classification_totals.last_provider_state,
    transfer_classification_totals.last_provider_at_utc,
    jsonb_strip_nulls(jsonb_build_object(
      'source', 'pay_bank_transfers',
      'bounded_scope', 'pay_batch_id',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END,
      'transfer_count', COALESCE(transfer_classification_totals.transfer_count, 0),
      'final_money_moved_count', COALESCE(transfer_classification_totals.final_money_moved_count, 0),
      'terminal_no_money_count', COALESCE(transfer_classification_totals.terminal_no_money_count, 0),
      'pending_non_final_count', COALESCE(transfer_classification_totals.pending_non_final_count, 0),
      'unknown_or_review_count', COALESCE(transfer_classification_totals.unknown_or_review_count, 0),
      'classification_called', COALESCE(transfer_classification_totals.transfer_count, 0) > 0,
      'last_provider_state', transfer_classification_totals.last_provider_state,
      'last_provider_at_utc', transfer_classification_totals.last_provider_at_utc
    ))
  INTO v_materialised_transfer_count,
       v_materialised_final_money_moved_count,
       v_materialised_terminal_no_money_count,
       v_materialised_pending_non_final_count,
       v_materialised_unknown_or_review_count,
       v_materialised_last_provider_state,
       v_materialised_last_provider_at_utc,
       v_transfer_classification_summary_json
  FROM transfer_classification_totals AS transfer_classification_totals;
  END IF;

  v_transfer_classification_called := COALESCE(v_materialised_transfer_count, 0) > 0;

  IF v_transfer_classification_called IS TRUE THEN
    v_transfer_count := v_materialised_transfer_count;
    v_submitted_count := GREATEST(COALESCE(v_submitted_count, 0), COALESCE(v_materialised_transfer_count, 0));
    v_request_sent_count := GREATEST(COALESCE(v_request_sent_count, 0), COALESCE(v_materialised_transfer_count, 0));
    v_final_money_moved_count := v_materialised_final_money_moved_count;
    v_terminal_no_money_count := v_materialised_terminal_no_money_count;
    v_unknown_count := GREATEST(COALESCE(v_unknown_count, 0), COALESCE(v_materialised_unknown_or_review_count, 0));
    v_review_required_count := GREATEST(COALESCE(v_review_required_count, 0), COALESCE(v_materialised_unknown_or_review_count, 0));
    v_last_provider_state := COALESCE(NULLIF(BTRIM(COALESCE(v_materialised_last_provider_state, '')), ''), v_last_provider_state);
    v_last_provider_at_utc := COALESCE(NULLIF(BTRIM(COALESCE(v_materialised_last_provider_at_utc, '')), ''), v_last_provider_at_utc);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'mode', v_mode,
    'operation_light', true,
    'counts_only', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_id::text END,
    'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
    'operation_status', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.status END,
    'operation_phase', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.phase END,
    'runner_state', CASE WHEN v_operation_id IS NULL THEN NULL ELSE v_operation_row.runner_state END,
    'submitted_count', coalesce(v_submitted_count, 0),
    'accepted_count', coalesce(v_accepted_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'unknown_count', coalesce(v_unknown_count, 0),
    'review_required_count', coalesce(v_review_required_count, 0),
    'remaining_ready_count', coalesce(v_remaining_ready_count, 0),
    'last_provider_message', v_last_provider_message,
    'last_provider_state', v_last_provider_state,
    'last_provider_at_utc', v_last_provider_at_utc,
    'transfer_count', coalesce(v_transfer_count, 0),
    'scope_count', coalesce(v_total_scope_count, 0),
    'claimed_count', coalesce(v_claimed_count, 0),
    'request_sent_count', coalesce(v_request_sent_count, 0),
    'terminal_no_money_count', coalesce(v_terminal_no_money_count, 0),
    'final_money_moved_count', coalesce(v_final_money_moved_count, 0),
    'pending_non_final_count', coalesce(v_materialised_pending_non_final_count, 0),
    'unknown_or_review_count', coalesce(v_materialised_unknown_or_review_count, 0),
    'materialised_transfer_count', coalesce(v_materialised_transfer_count, 0),
    'transfer_classification_scope_enabled', v_should_classify_transfers,
    'transfer_classification_summary_json', coalesce(v_transfer_classification_summary_json, '{}'::jsonb),
    'chunk_count', coalesce(v_chunk_count, 0),
    'running_chunk_count', coalesce(v_running_chunk_count, 0),
    'pending_chunk_count', coalesce(v_pending_chunk_count, 0),
    'completed_chunk_count', coalesce(v_completed_chunk_count, 0),
    'failed_chunk_count', coalesce(v_failed_chunk_count, 0),
    'provider_submit_diagnostic_called', false,
    'classification_called', v_transfer_classification_called,
    'provider_event_grouping_called', false
  );
END;
$function$;

-- pay_batch_timesheet_summary_lightweight_v1(jsonb)
CREATE OR REPLACE FUNCTION public.pay_batch_timesheet_summary_lightweight_v1(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filters jsonb := CASE WHEN jsonb_typeof(COALESCE(p_filters, '{}'::jsonb)) = 'object' THEN COALESCE(p_filters, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_inner_filters jsonb := '{}'::jsonb;
  v_filter_probe jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  v_pay_batch_id_text text := NULL;
  v_pay_batch_id uuid := NULL;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];

  v_limit_text text := NULL;
  v_offset_text text := NULL;
  v_limit integer := 50;
  v_offset integer := 0;
  v_order_by text := 'week_ending_date';
  v_order_dir text := 'desc';
  v_purpose text := '';
  v_membership_mode text := '';
  v_include_ids_text text := NULL;
  v_include_ids boolean := TRUE;
  v_has_secondary_filters boolean := FALSE;

  v_rows jsonb := '[]'::jsonb;
  v_row_ids jsonb := '[]'::jsonb;
  v_total_count bigint := 0;
  v_total_pay_ex_vat_sum numeric := 0;
  v_total_charge_ex_vat_sum numeric := 0;
  v_margin_ex_vat_sum numeric := 0;
BEGIN
  v_pay_batch_id_text := NULLIF(BTRIM(COALESCE(
    v_filters->>'pay_batch_id',
    v_filters->>'payBatchId',
    v_filters->>'batch_id',
    v_filters->>'batchId',
    ''
  )), '');

  IF v_pay_batch_id_text IS NULL OR v_pay_batch_id_text !~* v_uuid_re THEN
    RETURN jsonb_build_object(
      'rows', '[]'::jsonb,
      'row_ids', '[]'::jsonb,
      'total_count', 0,
      'total', 0,
      'count', 0,
      'totals', jsonb_build_object(
        'count_all', 0,
        'total_pay_ex_vat_sum', 0,
        'total_charge_ex_vat_sum', 0,
        'margin_ex_vat_sum', 0
      )
    );
  END IF;

  v_pay_batch_id := v_pay_batch_id_text::uuid;

  v_limit_text := NULLIF(BTRIM(COALESCE(v_filters->>'limit', v_filters->>'page_size', v_filters->>'pageSize', '')), '');
  IF v_limit_text ~ '^[0-9]+$' THEN
    v_limit := GREATEST(1, LEAST(v_limit_text::integer, 5000));
  END IF;

  v_offset_text := NULLIF(BTRIM(COALESCE(v_filters->>'offset', v_filters->>'page_offset', v_filters->>'pageOffset', '')), '');
  IF v_offset_text ~ '^[0-9]+$' THEN
    v_offset := GREATEST(v_offset_text::integer, 0);
  END IF;

  v_order_by := COALESCE(LOWER(NULLIF(BTRIM(COALESCE(v_filters->>'order_by', v_filters->>'orderBy', 'week_ending_date')), '')), 'week_ending_date');
  v_order_dir := COALESCE(LOWER(NULLIF(BTRIM(COALESCE(v_filters->>'order_dir', v_filters->>'orderDir', 'desc')), '')), 'desc');
  v_purpose := COALESCE(LOWER(NULLIF(BTRIM(COALESCE(v_filters->>'purpose', '')), '')), '');
  v_membership_mode := COALESCE(LOWER(NULLIF(BTRIM(COALESCE(v_filters->>'membership_mode', v_filters->>'membershipMode', '')), '')), '');
  v_include_ids_text := LOWER(NULLIF(BTRIM(COALESCE(v_filters->>'include_ids', v_filters->>'includeIds', v_filters->>'include_membership_ids', v_filters->>'includeMembershipIds', '')), ''));

  IF v_membership_mode IN ('deferred', 'count', 'count_only', 'counts', 'metadata') THEN
    v_include_ids := FALSE;
  ELSIF v_membership_mode IN ('ids', 'full', 'full_ids', 'membership_ids') THEN
    v_include_ids := TRUE;
  END IF;

  IF v_include_ids_text IS NOT NULL THEN
    IF v_include_ids_text IN ('0', 'false', 'no', 'n', 'off') THEN
      v_include_ids := FALSE;
    ELSIF v_include_ids_text IN ('1', 'true', 'yes', 'y', 'on') THEN
      v_include_ids := TRUE;
    END IF;
  END IF;

  IF v_order_by NOT IN (
    'candidate_name', 'candidate',
    'client_name', 'client',
    'week_ending_date', 'week_ending', 'date',
    'work_date',
    'processing_status', 'processing_status_display', 'status',
    'tools_stage', 'route_type', 'sheet_scope',
    'total_pay_ex_vat', 'pay',
    'total_charge_ex_vat', 'charge',
    'margin_ex_vat', 'margin'
  ) THEN
    v_order_by := 'week_ending_date';
  END IF;

  IF v_order_dir NOT IN ('asc', 'desc') THEN
    v_order_dir := 'desc';
  END IF;

  SELECT COALESCE(ARRAY_AGG(DISTINCT snapshot_row.timesheet_id ORDER BY snapshot_row.timesheet_id), ARRAY[]::uuid[])
    INTO v_timesheet_ids
  FROM public.pay_batch_timesheet_snapshots AS snapshot_row
  WHERE snapshot_row.pay_batch_id = v_pay_batch_id
    AND snapshot_row.timesheet_id IS NOT NULL;

  v_total_count := COALESCE(ARRAY_LENGTH(v_timesheet_ids, 1), 0);

  IF v_total_count = 0 THEN
    RETURN jsonb_build_object(
      'rows', '[]'::jsonb,
      'row_ids', '[]'::jsonb,
      'total_count', 0,
      'total', 0,
      'count', 0,
      'totals', jsonb_build_object(
        'count_all', 0,
        'total_pay_ex_vat_sum', 0,
        'total_charge_ex_vat_sum', 0,
        'margin_ex_vat_sum', 0
      ),
      'membership_deferred', CASE WHEN v_purpose IN ('membership', 'memberships', 'ids') AND v_include_ids IS NOT TRUE THEN TRUE ELSE FALSE END,
      'ids_deferred', CASE WHEN v_purpose IN ('membership', 'memberships', 'ids') AND v_include_ids IS NOT TRUE THEN TRUE ELSE FALSE END
    );
  END IF;

  v_filter_probe :=
    v_filters
    - 'pay_batch_id'
    - 'payBatchId'
    - 'batch_id'
    - 'batchId'
    - 'purpose'
    - 'profile'
    - 'context_profile'
    - 'contextProfile'
    - 'format'
    - 'page'
    - 'page_size'
    - 'pageSize'
    - 'limit'
    - 'offset'
    - 'page_offset'
    - 'pageOffset'
    - 'order_by'
    - 'orderBy'
    - 'order_dir'
    - 'orderDir'
    - 'include_totals'
    - 'includeTotals'
    - 'include_count'
    - 'includeCount'
    - 'include_ids'
    - 'includeIds'
    - 'include_membership_ids'
    - 'includeMembershipIds'
    - 'explicit_full_membership'
    - 'explicitFullMembership'
    - 'force_full_membership'
    - 'forceFullMembership'
    - 'membership_mode'
    - 'membershipMode'
    - 'disable_paging'
    - 'disablePaging'
    - 'no_paging'
    - 'noPaging'
    - 'apply_paging'
    - 'applyPaging';

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_each(v_filter_probe) AS probe_entry(probe_key, probe_value)
    WHERE CASE jsonb_typeof(probe_entry.probe_value)
      WHEN 'null' THEN FALSE
      WHEN 'array' THEN jsonb_array_length(probe_entry.probe_value) > 0
      WHEN 'object' THEN probe_entry.probe_value <> '{}'::jsonb
      WHEN 'string' THEN UPPER(BTRIM(COALESCE(probe_entry.probe_value #>> '{}', ''))) NOT IN ('', 'ALL')
      ELSE TRUE
    END
  )
    INTO v_has_secondary_filters;

  v_inner_filters :=
    (v_filters
    - 'pay_batch_id'
    - 'payBatchId'
    - 'batch_id'
    - 'batchId'
    - 'purpose'
    - 'profile'
    - 'context_profile'
    - 'contextProfile'
    - 'format'
    - 'disable_paging'
    - 'disablePaging'
    - 'no_paging'
    - 'noPaging'
    - 'apply_paging'
    - 'applyPaging'
    - 'page'
    - 'page_size'
    - 'pageSize'
    - 'limit'
    - 'offset'
    - 'page_offset'
    - 'pageOffset'
    - 'order_by'
    - 'orderBy'
    - 'order_dir'
    - 'orderDir'
    - 'include_totals'
    - 'includeTotals'
    - 'include_count'
    - 'includeCount'
    - 'include_ids'
    - 'includeIds'
    - 'include_membership_ids'
    - 'includeMembershipIds'
    - 'explicit_full_membership'
    - 'explicitFullMembership'
    - 'force_full_membership'
    - 'forceFullMembership'
    - 'membership_mode'
    - 'membershipMode')
    || jsonb_build_object(
      'timesheet_ids', to_jsonb(v_timesheet_ids),
      'disable_paging', TRUE,
      'disablePaging', TRUE,
      'no_paging', TRUE,
      'noPaging', TRUE,
      'apply_paging', FALSE,
      'applyPaging', FALSE,
      'profile', 'lightweight',
      'context_profile', 'list'
    );

  IF v_purpose IN ('membership', 'memberships', 'ids') AND v_has_secondary_filters IS NOT TRUE THEN
    IF v_include_ids IS TRUE THEN
      SELECT COALESCE(JSONB_AGG(member_id.timesheet_id::text ORDER BY member_id.timesheet_id::text), '[]'::jsonb)
        INTO v_row_ids
      FROM UNNEST(v_timesheet_ids) AS member_id(timesheet_id);
    ELSE
      v_row_ids := '[]'::jsonb;
    END IF;

    RETURN jsonb_build_object(
      'row_ids', COALESCE(v_row_ids, '[]'::jsonb),
      'ids', COALESCE(v_row_ids, '[]'::jsonb),
      'total_count', v_total_count,
      'total', v_total_count,
      'count', v_total_count,
      'membership_deferred', CASE WHEN v_include_ids IS TRUE THEN FALSE ELSE TRUE END,
      'ids_deferred', CASE WHEN v_include_ids IS TRUE THEN FALSE ELSE TRUE END
    );
  END IF;

  IF v_purpose IN ('membership', 'memberships', 'ids') THEN
    WITH summary_rows AS MATERIALIZED (
      SELECT summary_row.*
      FROM public.timesheet_summary_lightweight_rows_v1(v_inner_filters) AS summary_row
      WHERE summary_row.timesheet_id = ANY(v_timesheet_ids)
    ), filtered_member_ids AS MATERIALIZED (
      SELECT DISTINCT summary_rows.timesheet_id::text AS row_id
      FROM summary_rows
      WHERE summary_rows.timesheet_id IS NOT NULL
    )
    SELECT
      CASE
        WHEN v_include_ids IS TRUE THEN COALESCE(JSONB_AGG(filtered_member_ids.row_id ORDER BY filtered_member_ids.row_id), '[]'::jsonb)
        ELSE '[]'::jsonb
      END,
      COUNT(filtered_member_ids.row_id)::bigint
    INTO
      v_row_ids,
      v_total_count
    FROM filtered_member_ids;

    RETURN jsonb_build_object(
      'row_ids', COALESCE(v_row_ids, '[]'::jsonb),
      'ids', COALESCE(v_row_ids, '[]'::jsonb),
      'total_count', COALESCE(v_total_count, 0),
      'total', COALESCE(v_total_count, 0),
      'count', COALESCE(v_total_count, 0),
      'membership_deferred', CASE WHEN v_include_ids IS TRUE THEN FALSE ELSE TRUE END,
      'ids_deferred', CASE WHEN v_include_ids IS TRUE THEN FALSE ELSE TRUE END
    );
  END IF;

  WITH snapshot_rows AS MATERIALIZED (
    SELECT DISTINCT ON (snapshot_row.timesheet_id)
      snapshot_row.id,
      snapshot_row.pay_batch_id,
      snapshot_row.timesheet_id,
      snapshot_row.candidate_id,
      snapshot_row.pay_channel,
      snapshot_row.base_snapshot_json,
      snapshot_row.target_snapshot_json,
      snapshot_row.created_at_utc
    FROM public.pay_batch_timesheet_snapshots AS snapshot_row
    WHERE snapshot_row.pay_batch_id = v_pay_batch_id
      AND snapshot_row.timesheet_id IS NOT NULL
    ORDER BY snapshot_row.timesheet_id, snapshot_row.created_at_utc DESC NULLS LAST, snapshot_row.id
  ), summary_rows AS MATERIALIZED (
    SELECT summary_row.*
    FROM public.timesheet_summary_lightweight_rows_v1(v_inner_filters) AS summary_row
    WHERE summary_row.timesheet_id = ANY(v_timesheet_ids)
  ), live_rows AS MATERIALIZED (
    SELECT
      summary_rows.timesheet_id,
      summary_rows.contract_week_id,
      summary_rows.candidate_name,
      summary_rows.client_name,
      summary_rows.week_ending_date,
      summary_rows.work_date,
      summary_rows.processing_status_display,
      summary_rows.tools_stage,
      summary_rows.route_type,
      summary_rows.sheet_scope,
      COALESCE(summary_rows.total_pay_ex_vat, 0)::numeric AS total_pay_ex_vat,
      COALESCE(summary_rows.total_charge_ex_vat, 0)::numeric AS total_charge_ex_vat,
      COALESCE(summary_rows.margin_ex_vat, 0)::numeric AS margin_ex_vat,
      TO_JSONB(summary_rows) AS row_json
    FROM summary_rows
  ), fallback_seed AS MATERIALIZED (
    SELECT
      snapshot_rows.pay_batch_id,
      snapshot_rows.timesheet_id,
      snapshot_rows.candidate_id,
      snapshot_rows.pay_channel,
      NULLIF(BTRIM(COALESCE(
        snapshot_rows.target_snapshot_json->>'candidate_name',
        snapshot_rows.target_snapshot_json->>'candidateName',
        snapshot_rows.target_snapshot_json #>> '{candidate,name}',
        snapshot_rows.target_snapshot_json #>> '{candidate,display_name}',
        snapshot_rows.base_snapshot_json->>'candidate_name',
        snapshot_rows.base_snapshot_json->>'candidateName',
        snapshot_rows.base_snapshot_json #>> '{candidate,name}',
        snapshot_rows.base_snapshot_json #>> '{candidate,display_name}',
        ''
      )), '') AS candidate_name_text,
      NULLIF(BTRIM(COALESCE(
        snapshot_rows.target_snapshot_json->>'client_name',
        snapshot_rows.target_snapshot_json->>'clientName',
        snapshot_rows.target_snapshot_json #>> '{client,name}',
        snapshot_rows.base_snapshot_json->>'client_name',
        snapshot_rows.base_snapshot_json->>'clientName',
        snapshot_rows.base_snapshot_json #>> '{client,name}',
        ''
      )), '') AS client_name_text,
      NULLIF(BTRIM(COALESCE(
        snapshot_rows.target_snapshot_json->>'week_ending_date',
        snapshot_rows.target_snapshot_json->>'weekEndingDate',
        snapshot_rows.target_snapshot_json #>> '{timesheet,week_ending_date}',
        snapshot_rows.base_snapshot_json->>'week_ending_date',
        snapshot_rows.base_snapshot_json->>'weekEndingDate',
        snapshot_rows.base_snapshot_json #>> '{timesheet,week_ending_date}',
        ''
      )), '') AS week_ending_text,
      NULLIF(BTRIM(COALESCE(
        snapshot_rows.target_snapshot_json->>'work_date',
        snapshot_rows.target_snapshot_json->>'workDate',
        snapshot_rows.target_snapshot_json #>> '{timesheet,work_date}',
        snapshot_rows.base_snapshot_json->>'work_date',
        snapshot_rows.base_snapshot_json->>'workDate',
        snapshot_rows.base_snapshot_json #>> '{timesheet,work_date}',
        ''
      )), '') AS work_date_text,
      NULLIF(BTRIM(COALESCE(
        snapshot_rows.target_snapshot_json->>'sheet_scope',
        snapshot_rows.target_snapshot_json->>'sheetScope',
        snapshot_rows.target_snapshot_json #>> '{timesheet,sheet_scope}',
        snapshot_rows.base_snapshot_json->>'sheet_scope',
        snapshot_rows.base_snapshot_json->>'sheetScope',
        snapshot_rows.base_snapshot_json #>> '{timesheet,sheet_scope}',
        ''
      )), '') AS sheet_scope_text
    FROM snapshot_rows
    WHERE v_has_secondary_filters IS NOT TRUE
      AND NOT EXISTS (
        SELECT 1
        FROM summary_rows AS existing_summary_row
        WHERE existing_summary_row.timesheet_id = snapshot_rows.timesheet_id
      )
  ), fallback_rows AS MATERIALIZED (
    SELECT
      fallback_seed.timesheet_id,
      NULL::uuid AS contract_week_id,
      fallback_seed.candidate_name_text AS candidate_name,
      fallback_seed.client_name_text AS client_name,
      CASE WHEN fallback_seed.week_ending_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN fallback_seed.week_ending_text::date ELSE NULL::date END AS week_ending_date,
      CASE WHEN fallback_seed.work_date_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN fallback_seed.work_date_text::date ELSE NULL::date END AS work_date,
      'Linked to pay batch'::text AS processing_status_display,
      'BATCH_LINKED'::text AS tools_stage,
      NULLIF(BTRIM(COALESCE(fallback_seed.pay_channel, '')), '') AS route_type,
      NULLIF(BTRIM(COALESCE(fallback_seed.sheet_scope_text, '')), '') AS sheet_scope,
      0::numeric AS total_pay_ex_vat,
      0::numeric AS total_charge_ex_vat,
      0::numeric AS margin_ex_vat,
      (
        jsonb_build_object(
          'id', fallback_seed.timesheet_id,
          'timesheet_id', fallback_seed.timesheet_id,
          'contract_week_id', NULL,
          'contract_id', NULL,
          'candidate_id', fallback_seed.candidate_id,
          'candidate_name', fallback_seed.candidate_name_text,
          'candidate_display_name', fallback_seed.candidate_name_text,
          'client_id', NULL,
          'client_name', fallback_seed.client_name_text,
          'booking_id', NULL,
          'occupant_key_norm', NULL,
          'hospital_norm', NULL,
          'candidate_hint_text', '{}'::jsonb,
          'week_ending_date', CASE WHEN fallback_seed.week_ending_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN fallback_seed.week_ending_text::date ELSE NULL::date END,
          'work_date', CASE WHEN fallback_seed.work_date_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN fallback_seed.work_date_text::date ELSE NULL::date END,
          'sheet_scope', NULLIF(BTRIM(COALESCE(fallback_seed.sheet_scope_text, '')), ''),
          'submission_mode', NULL,
          'submission_mode_snapshot', NULL,
          'basis', NULL,
          'route_type', NULLIF(BTRIM(COALESCE(fallback_seed.pay_channel, '')), ''),
          'route_display', NULLIF(BTRIM(COALESCE(fallback_seed.pay_channel, '')), ''),
          'route_family', NULL,
          'route_subfamily', NULL
        )
        || jsonb_build_object(
          'underlying_channel_family', NULL,
          'summary_stage', 'BATCH_LINKED',
          'tools_stage', 'BATCH_LINKED',
          'processing_status', 'BATCH_LINKED',
          'processing_status_display', 'Linked to pay batch',
          'authorised_at_utc', NULL,
          'authorised_at_server', NULL,
          'processed_at_utc', NULL,
          'is_authorised', NULL,
          'total_hours', 0,
          'total_pay_ex_vat', 0,
          'total_charge_ex_vat', 0,
          'margin_ex_vat', 0,
          'net_delta_ex_vat', 0,
          'paid_at_utc', NULL,
          'pay_icon_code', 'NONE',
          'pay_status_code', 'UNPAID',
          'pay_paid_at_utc', NULL,
          'invoice_is_paid', NULL,
          'invoice_issue_stage', NULL,
          'invoice_segment_stage', NULL,
          'invoice_segments_total', 0,
          'invoice_segments_locked', 0
        )
        || jsonb_build_object(
          'invoice_segments_unlocked', 0,
          'issue_codes', ARRAY[]::text[],
          'validation_status', NULL,
          'validation_summary', NULL,
          'hr_crosscheck_status', NULL,
          'hr_crosscheck_issues', ARRAY[]::text[],
          'qr_status', NULL,
          'is_qr', NULL,
          'is_adjusted', NULL,
          'needs_attention', FALSE,
          'has_rate_issue', FALSE,
          'has_pay_channel_issue', FALSE,
          'client_no_timesheet_required', NULL,
          'client_autoprocess_hr', NULL,
          'client_is_nhsp', NULL,
          'has_any_evidence', NULL,
          'attached_evidence_count', 0,
          'primary_artifact_storage_key', NULL,
          'primary_artifact_display_name', NULL,
          'primary_artifact_preview_mode', NULL,
          'pay_batch_id', fallback_seed.pay_batch_id,
          'pay_channel', fallback_seed.pay_channel,
          'batch_linked_only', TRUE
        )
      ) AS row_json
    FROM fallback_seed
  ), combined_rows AS MATERIALIZED (
    SELECT live_rows.*
    FROM live_rows
    UNION ALL
    SELECT fallback_rows.*
    FROM fallback_rows
  ), totalled AS (
    SELECT
      COUNT(*)::bigint AS count_all,
      COALESCE(SUM(COALESCE(combined_rows.total_pay_ex_vat, 0)), 0)::numeric AS total_pay_ex_vat_sum,
      COALESCE(SUM(COALESCE(combined_rows.total_charge_ex_vat, 0)), 0)::numeric AS total_charge_ex_vat_sum,
      COALESCE(SUM(COALESCE(combined_rows.margin_ex_vat, 0)), 0)::numeric AS margin_ex_vat_sum
    FROM combined_rows
  ), ordered_rows AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY
          CASE WHEN v_order_by IN ('candidate_name', 'candidate') AND v_order_dir = 'asc' THEN combined_rows.candidate_name END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('candidate_name', 'candidate') AND v_order_dir = 'desc' THEN combined_rows.candidate_name END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('client_name', 'client') AND v_order_dir = 'asc' THEN combined_rows.client_name END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('client_name', 'client') AND v_order_dir = 'desc' THEN combined_rows.client_name END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('week_ending_date', 'week_ending', 'date') AND v_order_dir = 'asc' THEN combined_rows.week_ending_date END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('week_ending_date', 'week_ending', 'date') AND v_order_dir = 'desc' THEN combined_rows.week_ending_date END DESC NULLS LAST,

          CASE WHEN v_order_by = 'work_date' AND v_order_dir = 'asc' THEN combined_rows.work_date END ASC NULLS LAST,
          CASE WHEN v_order_by = 'work_date' AND v_order_dir = 'desc' THEN combined_rows.work_date END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('processing_status', 'processing_status_display', 'status') AND v_order_dir = 'asc' THEN combined_rows.processing_status_display END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('processing_status', 'processing_status_display', 'status') AND v_order_dir = 'desc' THEN combined_rows.processing_status_display END DESC NULLS LAST,

          CASE WHEN v_order_by = 'tools_stage' AND v_order_dir = 'asc' THEN combined_rows.tools_stage END ASC NULLS LAST,
          CASE WHEN v_order_by = 'tools_stage' AND v_order_dir = 'desc' THEN combined_rows.tools_stage END DESC NULLS LAST,

          CASE WHEN v_order_by = 'route_type' AND v_order_dir = 'asc' THEN combined_rows.route_type END ASC NULLS LAST,
          CASE WHEN v_order_by = 'route_type' AND v_order_dir = 'desc' THEN combined_rows.route_type END DESC NULLS LAST,

          CASE WHEN v_order_by = 'sheet_scope' AND v_order_dir = 'asc' THEN combined_rows.sheet_scope END ASC NULLS LAST,
          CASE WHEN v_order_by = 'sheet_scope' AND v_order_dir = 'desc' THEN combined_rows.sheet_scope END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('total_pay_ex_vat', 'pay') AND v_order_dir = 'asc' THEN combined_rows.total_pay_ex_vat END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('total_pay_ex_vat', 'pay') AND v_order_dir = 'desc' THEN combined_rows.total_pay_ex_vat END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('total_charge_ex_vat', 'charge') AND v_order_dir = 'asc' THEN combined_rows.total_charge_ex_vat END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('total_charge_ex_vat', 'charge') AND v_order_dir = 'desc' THEN combined_rows.total_charge_ex_vat END DESC NULLS LAST,

          CASE WHEN v_order_by IN ('margin_ex_vat', 'margin') AND v_order_dir = 'asc' THEN combined_rows.margin_ex_vat END ASC NULLS LAST,
          CASE WHEN v_order_by IN ('margin_ex_vat', 'margin') AND v_order_dir = 'desc' THEN combined_rows.margin_ex_vat END DESC NULLS LAST,

          combined_rows.candidate_name ASC NULLS LAST,
          combined_rows.week_ending_date DESC NULLS LAST,
          combined_rows.work_date DESC NULLS LAST,
          combined_rows.timesheet_id NULLS LAST,
          combined_rows.contract_week_id NULLS LAST
      ) AS __ctms_sort_ord,
      combined_rows.row_json
    FROM combined_rows
  ), paged_rows AS (
    SELECT ordered_row.*
    FROM ordered_rows AS ordered_row
    ORDER BY ordered_row.__ctms_sort_ord ASC
    LIMIT v_limit
    OFFSET v_offset
  )
  SELECT
    COALESCE((SELECT JSONB_AGG(paged_rows.row_json ORDER BY paged_rows.__ctms_sort_ord) FROM paged_rows), '[]'::jsonb),
    COALESCE(totalled.count_all, 0),
    COALESCE(totalled.total_pay_ex_vat_sum, 0),
    COALESCE(totalled.total_charge_ex_vat_sum, 0),
    COALESCE(totalled.margin_ex_vat_sum, 0)
  INTO
    v_rows,
    v_total_count,
    v_total_pay_ex_vat_sum,
    v_total_charge_ex_vat_sum,
    v_margin_ex_vat_sum
  FROM totalled;

  RETURN jsonb_build_object(
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'total_count', COALESCE(v_total_count, 0),
    'total', COALESCE(v_total_count, 0),
    'count', COALESCE(v_total_count, 0),
    'totals', jsonb_build_object(
      'count_all', COALESCE(v_total_count, 0),
      'total_pay_ex_vat_sum', COALESCE(v_total_pay_ex_vat_sum, 0),
      'total_charge_ex_vat_sum', COALESCE(v_total_charge_ex_vat_sum, 0),
      'margin_ex_vat_sum', COALESCE(v_margin_ex_vat_sum, 0)
    )
  );
END;
$function$;

-- pay_batch_validate_freshness_chunk(uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness_chunk(p_operation_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_invalid_scope_unit_count integer := 0;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_ordinal bigint := NULL::bigint;
  v_cursor_unit_key text := NULL::text;
  v_cursor_has_ordinal boolean := false;
  v_cursor_has_unit_key boolean := false;
  v_cursor_operation_id uuid := NULL::uuid;
  v_cursor_pay_batch_id uuid := NULL::uuid;
  v_raw_count integer := 0;
  v_validated_count integer := 0;
  v_fresh_count integer := 0;
  v_stale_count integer := 0;
  v_error_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_diff_samples jsonb := '[]'::jsonb;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_combined_stale_reasons jsonb := '[]'::jsonb;
  v_combined_diff_samples jsonb := '[]'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_prev_fresh_units integer := 0;
  v_prev_stale_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_error_units integer := 0;
  v_new_total_units integer := 0;
  v_new_seeded_units integer := 0;
  v_new_fresh_units integer := 0;
  v_new_stale_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_error_units integer := 0;
  v_new_status text := 'PENDING';
  v_persisted_batch_status text := 'PENDING';
  v_scope_hash text := NULL::text;
  v_prev_result_hash text := NULL::text;
  v_page_result_hash text := NULL::text;
  v_new_result_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
     OR UPPER(BTRIM(COALESCE(v_operation.status, ''))) <> 'RUNNING'
     OR UPPER(BTRIM(COALESCE(v_operation.phase, ''))) NOT IN ('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
     OR v_operation.pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'operation_type', v_operation.operation_type,
              'operation_status', v_operation.status,
              'operation_phase', v_operation.phase,
              'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
              'required_operation_types', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
              'required_status', 'RUNNING',
              'allowed_phases', jsonb_build_array('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation.pay_batch_id
  FOR UPDATE OF batch_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text
            )::text;
  END IF;

  IF v_batch.freshness_operation_id IS NOT NULL
     AND v_batch.freshness_operation_id IS DISTINCT FROM p_operation_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'current_freshness_operation_id', v_batch.freshness_operation_id::text
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_invalid_scope_unit_count
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id;

  IF COALESCE(v_invalid_scope_unit_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'invalid_scope_unit_count', v_invalid_scope_unit_count
            )::text;
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := CASE
    WHEN COALESCE(v_date_context->>'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN (v_date_context->>'london_current_date')::date
    ELSE NULL::date
  END;
  IF v_today_uk IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE',
              'operation_id', p_operation_id::text,
              'message', 'The current Europe/London business date could not be resolved for chunked batch freshness.'
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL THEN
    IF jsonb_typeof(p_cursor_json) <> 'object' THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_MUST_BE_OBJECT'
              )::text;
    END IF;

    v_cursor_has_ordinal := p_cursor_json ? 'last_unit_ordinal';
    v_cursor_has_unit_key := p_cursor_json ? 'last_unit_key';

    IF v_cursor_has_ordinal IS DISTINCT FROM v_cursor_has_unit_key THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_ORDINAL_AND_KEY_REQUIRED_TOGETHER'
              )::text;
    END IF;

    IF v_cursor_has_ordinal THEN
      IF COALESCE(p_cursor_json->>'last_unit_ordinal', '') !~ '^[0-9]+$'
         OR NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '') IS NULL THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_ORDINAL_OR_KEY_INVALID'
                )::text;
      END IF;

      BEGIN
        v_cursor_ordinal := (p_cursor_json->>'last_unit_ordinal')::bigint;
      EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
          RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                    'operation_id', p_operation_id::text,
                    'pay_batch_id', v_operation.pay_batch_id::text,
                    'reason', 'CURSOR_ORDINAL_OUT_OF_RANGE'
                  )::text;
      END;
      v_cursor_unit_key := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '');
    END IF;

    IF p_cursor_json ? 'operation_id' THEN
      IF COALESCE(p_cursor_json->>'operation_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_OPERATION_ID_INVALID'
                )::text;
      END IF;
      v_cursor_operation_id := (p_cursor_json->>'operation_id')::uuid;
      IF v_cursor_operation_id IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'cursor_operation_id', v_cursor_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text
                )::text;
      END IF;
    END IF;

    IF p_cursor_json ? 'pay_batch_id' THEN
      IF COALESCE(p_cursor_json->>'pay_batch_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_PAY_BATCH_ID_INVALID'
                )::text;
      END IF;
      v_cursor_pay_batch_id := (p_cursor_json->>'pay_batch_id')::uuid;
      IF v_cursor_pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'cursor_pay_batch_id', v_cursor_pay_batch_id::text
                )::text;
      END IF;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validate_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validate_page ON COMMIT DROP AS
  SELECT
    scope_unit.operation_id,
    scope_unit.pay_batch_id,
    scope_unit.phase,
    scope_unit.unit_type,
    scope_unit.unit_key,
    scope_unit.unit_payload_json,
    scope_unit.unit_ordinal,
    scope_unit.status,
    row_number() OVER (ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key)::integer AS page_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id = v_operation.pay_batch_id
    AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) IN ('PENDING', 'QUEUED', 'READY')
    AND (
      v_cursor_ordinal IS NULL
      OR scope_unit.unit_ordinal > v_cursor_ordinal
      OR (scope_unit.unit_ordinal = v_cursor_ordinal AND v_cursor_unit_key IS NOT NULL AND scope_unit.unit_key > v_cursor_unit_key)
    )
  ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row;

  v_has_more := COALESCE(v_raw_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validation_result;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validation_result ON COMMIT DROP AS
  WITH page_rows AS (
    SELECT page_row.*,
           CASE
             WHEN COALESCE(page_row.unit_payload_json->>'pay_batch_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (page_row.unit_payload_json->>'pay_batch_item_id')::uuid
             ELSE NULL::uuid
           END AS pay_batch_item_id,
           UPPER(NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_type}', '')), '')) AS stored_key_type,
           NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_value}', '')), '') AS stored_key_value,
           CASE
             WHEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id')::uuid
             ELSE NULL::uuid
           END AS stored_timesheet_id,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_ex_vat}')::numeric ELSE NULL::numeric END AS stored_amount_ex_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_vat}')::numeric ELSE NULL::numeric END AS stored_amount_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_inc_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_inc_vat}')::numeric ELSE NULL::numeric END AS stored_amount_inc_vat
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
  ), live_items AS (
    SELECT
      page_rows.*,
      batch_item.id AS live_pay_batch_item_id,
      batch_item.timesheet_id AS live_timesheet_id,
      batch_item.item_type AS live_item_type,
      batch_item.amount_ex_vat AS live_amount_ex_vat,
      batch_item.amount_vat AS live_amount_vat,
      batch_item.amount_inc_vat AS live_amount_inc_vat,
      COALESCE(batch_item.is_voided, false) AS live_is_voided,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.payout_instruction_snapshot_json,
      NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') AS live_source_ref,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
        LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
      ) AS live_exact_source_ref,
      CASE
        WHEN COALESCE(
          CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
          LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
        ) ~* '^timesheet-expense:' THEN 'TIMESHEET_EXPENSE'
        WHEN batch_item.finance_case_id IS NOT NULL
          OR LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '')) ~* '^advance:' THEN 'FINANCE_CASE'
        WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') IS NOT NULL THEN 'EXACT_SOURCE'
        ELSE 'TIMESHEET_OR_SEGMENT'
      END AS live_source_identity_kind,
      NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') AS live_segment_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
      ) AS live_segment_stable_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
      ) AS live_segment_id,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
        (
          SELECT COALESCE(
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
          )
          FROM public.pay_batch_timesheet_snapshots AS snapshot_row
          WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
            AND snapshot_row.timesheet_id = batch_item.timesheet_id
          ORDER BY snapshot_row.id
          LIMIT 1
        )
      ) AS live_booking_id,
      batch_item.finance_case_id AS live_finance_case_id,
      batch_item.finance_component_id AS live_finance_component_id,
      (
        batch_item.finance_case_id IS NOT NULL
        OR COALESCE(
          NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
          false
        )
      ) AS live_is_finance_source,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL END,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
          ELSE NULL
        END
      ) AS live_finance_source_ref,
      batch_candidate.candidate_id AS live_candidate_id,
      active_snooze.id AS active_snooze_id,
      active_snooze.snooze_kind AS active_snooze_kind,
      active_snooze.snooze_until_date AS active_snooze_until_date,
      active_snooze.source_ref AS active_snooze_source_ref,
      active_snooze.segment_stable_key AS active_snooze_segment_stable_key,
      active_snooze.segment_id AS active_snooze_segment_id,
      active_snooze.booking_id AS active_snooze_booking_id,
      active_snooze.match_scope AS active_snooze_match_scope
    FROM page_rows
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = page_rows.pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = page_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        snooze_row.id,
        snooze_row.snooze_kind,
        snooze_row.snooze_until_date,
        snooze_row.source_ref,
        snooze_row.segment_stable_key,
        snooze_row.segment_id,
        snooze_row.booking_id,
        CASE
          WHEN snooze_row.source_ref IS NOT NULL THEN 'EXACT_SOURCE_REF'
          ELSE 'LEGACY_TIMESHEET_SEGMENT'
        END AS match_scope
      FROM public.pay_item_snoozes AS snooze_row
      WHERE snooze_row.candidate_id = batch_candidate.candidate_id
        AND snooze_row.cleared_at_utc IS NULL
        AND snooze_row.cancelled_at_utc IS NULL
        AND (
          snooze_row.snooze_until_date IS NULL
          OR snooze_row.snooze_until_date >= v_today_uk
        )
        AND (
          (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NOT NULL
            AND LOWER(NULLIF(BTRIM(COALESCE(snooze_row.source_ref, '')), '')) = COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            )
          )
          OR (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NULL
            AND snooze_row.source_ref IS NULL
            AND (
              (
                batch_item.timesheet_id IS NOT NULL
                AND snooze_row.timesheet_id = batch_item.timesheet_id
              )
              OR (
                NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
                  (
                    SELECT COALESCE(
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
                    )
                    FROM public.pay_batch_timesheet_snapshots AS snapshot_row
                    WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
                      AND snapshot_row.timesheet_id = batch_item.timesheet_id
                    ORDER BY snapshot_row.id
                    LIMIT 1
                  )
                )
              )
            )
            AND (
              (
                NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') IS NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') IS NULL
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                )
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                )
              )
              OR (
                NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IN (
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), ''),
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '')
                )
              )
            )
          )
        )
      ORDER BY snooze_row.updated_at_utc DESC, snooze_row.created_at_utc DESC, snooze_row.id
      LIMIT 1
    ) AS active_snooze ON TRUE
  ), resolved AS (
    SELECT
      live_items.*,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM live_items
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => live_items.live_pay_batch_item_id,
      p_pay_batch_id => live_items.pay_batch_id,
      p_timesheet_id => live_items.live_timesheet_id,
      p_item_type => live_items.live_item_type,
      p_frozen_key_type => live_items.frozen_component_key_type,
      p_frozen_key_value => live_items.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(live_items.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(live_items.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
  ), evaluated AS (
    SELECT
      resolved.*,
      (
        CASE WHEN resolved.live_pay_batch_item_id IS NULL THEN jsonb_build_array('PAY_BATCH_ITEM_MISSING') ELSE '[]'::jsonb END
        || CASE WHEN resolved.live_is_voided THEN jsonb_build_array('PAY_BATCH_ITEM_VOIDED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.resolved_key_type IS NULL OR resolved.resolved_key_value IS NULL THEN jsonb_build_array(COALESCE(resolved.key_resolution_failure_reason, 'POST_DRAFT_KEY_RESOLUTION_FAILED')) ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_type IS NOT NULL AND resolved.resolved_key_type IS NOT NULL AND resolved.stored_key_type IS DISTINCT FROM resolved.resolved_key_type THEN jsonb_build_array('ECONOMIC_KEY_TYPE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_value IS NOT NULL AND resolved.resolved_key_value IS NOT NULL AND resolved.stored_key_value IS DISTINCT FROM resolved.resolved_key_value THEN jsonb_build_array('ECONOMIC_KEY_VALUE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_timesheet_id IS NOT NULL AND resolved.resolved_timesheet_id IS NOT NULL AND resolved.stored_timesheet_id IS DISTINCT FROM resolved.resolved_timesheet_id THEN jsonb_build_array('ECONOMIC_TIMESHEET_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_ex_vat IS NOT NULL AND resolved.live_amount_ex_vat IS NOT NULL AND ROUND(resolved.stored_amount_ex_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_ex_vat, 2) THEN jsonb_build_array('AMOUNT_EX_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_vat IS NOT NULL AND resolved.live_amount_vat IS NOT NULL AND ROUND(resolved.stored_amount_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_vat, 2) THEN jsonb_build_array('AMOUNT_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_inc_vat IS NOT NULL AND resolved.live_amount_inc_vat IS NOT NULL AND ROUND(resolved.stored_amount_inc_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_inc_vat, 2) THEN jsonb_build_array('AMOUNT_INC_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE
          WHEN resolved.active_snooze_id IS NOT NULL
            THEN jsonb_build_array('ACTIVE_SNOOZE_CHANGED')
          ELSE '[]'::jsonb
        END
      ) AS stale_reasons_json
    FROM resolved
  )
  SELECT
    evaluated.*,
    (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0) AS is_stale,
    jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'stored_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.stored_timesheet_id IS NULL THEN NULL ELSE evaluated.stored_timesheet_id::text END, 'key_type', evaluated.stored_key_type, 'key_value', evaluated.stored_key_value)),
      'resolved_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END, 'key_type', evaluated.resolved_key_type, 'key_value', evaluated.resolved_key_value)),
      'stale_reasons', evaluated.stale_reasons_json,
      'stored_amount_ex_vat', evaluated.stored_amount_ex_vat,
      'current_amount_ex_vat', evaluated.live_amount_ex_vat,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
        'snooze_id', evaluated.active_snooze_id::text,
        'snooze_kind', evaluated.active_snooze_kind,
        'snooze_until_date', CASE WHEN evaluated.active_snooze_until_date IS NULL THEN NULL ELSE evaluated.active_snooze_until_date::text END,
        'active_as_of_london_date', v_today_uk::text,
        'source_ref', evaluated.active_snooze_source_ref,
        'segment_stable_key', evaluated.active_snooze_segment_stable_key,
        'segment_id', evaluated.active_snooze_segment_id,
        'booking_id', evaluated.active_snooze_booking_id,
        'source_match_scope', evaluated.active_snooze_match_scope
      )) END
    )) AS diff_json,
    md5(jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'resolved_key_type', evaluated.resolved_key_type,
      'resolved_key_value', evaluated.resolved_key_value,
      'resolved_timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END,
      'is_stale', (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0),
      'stale_reasons', evaluated.stale_reasons_json,
      'active_snooze_id', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE evaluated.active_snooze_id::text END,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze_match_scope', evaluated.active_snooze_match_scope,
      'london_current_date', v_today_uk::text
    ))::text) AS proof_hash
  FROM evaluated;

  WITH updated_units AS (
    UPDATE public.banking_pay_operation_scope_units AS scope_unit
    SET status = CASE WHEN result_row.is_stale THEN 'STALE' ELSE 'FRESH' END,
        result_hash = result_row.proof_hash,
        error_json = NULL::jsonb,
        unit_payload_json = COALESCE(scope_unit.unit_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'validation_result', jsonb_build_object(
              'validated_at_utc', v_now::text,
              'is_stale', result_row.is_stale,
              'stale_reasons', result_row.stale_reasons_json,
              'diff', CASE WHEN result_row.is_stale THEN result_row.diff_json ELSE NULL::jsonb END,
              'proof_hash', result_row.proof_hash
            )
          ),
        updated_at_utc = v_now
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE scope_unit.operation_id = result_row.operation_id
      AND scope_unit.phase = result_row.phase
      AND scope_unit.unit_type = result_row.unit_type
      AND scope_unit.unit_key = result_row.unit_key
    RETURNING scope_unit.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'STALE')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'ERROR')::integer
  INTO v_validated_count, v_fresh_count, v_stale_count, v_error_count
  FROM updated_units;

  SELECT COALESCE(jsonb_agg(diff_source.diff_json ORDER BY diff_source.unit_ordinal, diff_source.unit_key), '[]'::jsonb)
  INTO v_diff_samples
  FROM (
    SELECT result_row.diff_json, result_row.unit_ordinal, result_row.unit_key
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE result_row.is_stale = true
    ORDER BY result_row.unit_ordinal, result_row.unit_key
    LIMIT 25
  ) AS diff_source;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_element.value ORDER BY reason_element.value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
  CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(result_row.stale_reasons_json, '[]'::jsonb)) AS reason_element(value)
  WHERE result_row.is_stale = true;

  SELECT md5(COALESCE(string_agg(COALESCE(result_row.proof_hash, 'NO_RESULT'), '|' ORDER BY result_row.unit_ordinal, result_row.unit_key), 'EMPTY_VALIDATION_CHUNK'))
  INTO v_page_result_hash
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation.pay_batch_id::text,
      'last_unit_ordinal', page_row.unit_ordinal,
      'last_unit_key', page_row.unit_key
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_fresh_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0);
  v_prev_stale_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0);
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_error_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0);
  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );
  v_prev_result_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'result_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_result_hash', '')), '')
  );

  v_new_fresh_units := COALESCE(v_prev_fresh_units, 0) + COALESCE(v_fresh_count, 0);
  v_new_stale_units := COALESCE(v_prev_stale_units, 0) + COALESCE(v_stale_count, 0);
  v_new_error_units := COALESCE(v_prev_error_units, 0) + COALESCE(v_error_count, 0);
  v_new_pending_units := GREATEST(COALESCE(v_prev_pending_units, 0) - COALESCE(v_validated_count, 0), 0);
  v_new_seeded_units := GREATEST(COALESCE(v_prev_seeded_units, 0), COALESCE(v_prev_total_units, 0), v_new_fresh_units + v_new_stale_units + v_new_error_units + v_new_pending_units);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0), v_new_seeded_units);

  v_new_status := CASE
    WHEN COALESCE(v_new_pending_units, 0) > 0 OR COALESCE(v_has_more, false) THEN 'PENDING'
    WHEN COALESCE(v_new_error_units, 0) > 0 THEN 'ERROR'
    WHEN COALESCE(v_new_stale_units, 0) > 0 THEN 'STALE'
    ELSE 'PASSED'
  END;
  v_persisted_batch_status := CASE WHEN v_new_status = 'ERROR' THEN 'FAILED' ELSE v_new_status END;

  v_new_result_hash := CASE
    WHEN v_prev_result_hash IS NULL THEN COALESCE(v_page_result_hash, 'EMPTY_RESULT')
    ELSE md5(v_prev_result_hash || '|chunk|' || COALESCE(v_page_result_hash, 'EMPTY_VALIDATION_CHUNK'))
  END;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_union.reason_text ORDER BY reason_union.reason_text), '[]'::jsonb)
  INTO v_combined_stale_reasons
  FROM (
    SELECT previous_reason.value AS reason_text
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_prev_summary->'stale_reasons') = 'array' THEN COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS previous_reason(value)
    UNION ALL
    SELECT current_reason.value AS reason_text
    FROM jsonb_array_elements_text(COALESCE(v_stale_reasons, '[]'::jsonb)) AS current_reason(value)
  ) AS reason_union
  WHERE NULLIF(BTRIM(COALESCE(reason_union.reason_text, '')), '') IS NOT NULL;

  SELECT COALESCE(jsonb_agg(capped_diff.diff_json ORDER BY capped_diff.sample_rank), '[]'::jsonb)
  INTO v_combined_diff_samples
  FROM (
    SELECT diff_union.diff_json, diff_union.sample_rank
    FROM (
      SELECT previous_diff.value AS diff_json, previous_diff.ordinality::integer AS sample_rank
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_prev_summary->'diff_samples') = 'array' THEN COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb) ELSE '[]'::jsonb END
      ) WITH ORDINALITY AS previous_diff(value, ordinality)
      UNION ALL
      SELECT current_diff.value AS diff_json, (1000 + current_diff.ordinality)::integer AS sample_rank
      FROM jsonb_array_elements(COALESCE(v_diff_samples, '[]'::jsonb)) WITH ORDINALITY AS current_diff(value, ordinality)
    ) AS diff_union
    WHERE jsonb_typeof(diff_union.diff_json) = 'object'
    ORDER BY diff_union.sample_rank
    LIMIT 25
  ) AS capped_diff;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', v_new_status,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(v_new_fresh_units, 0),
    'stale_units', COALESCE(v_new_stale_units, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(v_new_error_units, 0),
    'scope_hash', v_scope_hash,
    'result_hash', v_new_result_hash,
    'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
    'last_validated_at_utc', v_now::text,
    'london_current_date', v_today_uk::text,
    'last_validated_count', COALESCE(v_validated_count, 0),
    'last_fresh_count', COALESCE(v_fresh_count, 0),
    'last_stale_count', COALESCE(v_stale_count, 0),
    'last_error_count', COALESCE(v_error_count, 0),
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', v_new_status,
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_stale_units', COALESCE(v_new_stale_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_error_units', COALESCE(v_new_error_units, 0),
          'freshness_scope_hash', v_scope_hash,
          'freshness_result_hash', v_new_result_hash
        )
      ),
      result_json = CASE
        WHEN v_new_status <> 'PENDING' THEN jsonb_set(
          COALESCE(operation_update.result_json, '{}'::jsonb),
          '{freshness}',
          v_new_summary,
          true
        )
        ELSE operation_update.result_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  IF v_operation.pay_batch_id IS NOT NULL THEN
    UPDATE public.pay_batches AS batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_persisted_batch_status,
        freshness_checked_at_utc = CASE WHEN v_new_status <> 'PENDING' THEN v_now ELSE batch_update.freshness_checked_at_utc END,
        freshness_scope_hash = COALESCE(v_scope_hash, batch_update.freshness_scope_hash),
        freshness_result_hash = CASE WHEN v_new_status <> 'PENDING' THEN v_new_result_hash ELSE batch_update.freshness_result_hash END,
        freshness_result_json = jsonb_build_object(
          'ok', true,
          'operation_id', p_operation_id::text,
          'pay_batch_id', v_operation.pay_batch_id::text,
          'phase', 'FRESHNESS',
          'status', v_new_status,
          'is_stale', v_new_status IN ('STALE', 'ERROR'),
          'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
          'diff', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'scope_hash', v_scope_hash,
          'result_hash', v_new_result_hash,
          'summary', v_new_summary,
          'checked_at_utc', CASE WHEN v_new_status <> 'PENDING' THEN v_now::text ELSE NULL END
        )
    WHERE batch_update.id = v_operation.pay_batch_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'london_current_date', v_today_uk::text,
    'validated_count', COALESCE(v_validated_count, 0),
    'fresh_count', COALESCE(v_fresh_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$;

-- pay_batch_validate_freshness_chunk(uuid,uuid,uuid,uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness_chunk(p_operation_id uuid, p_chunk_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_diff_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
declare
  v_operation public.banking_pay_operations%rowtype;
  v_today_uk date := (clock_timestamp() AT TIME ZONE 'Europe/London')::date;
  v_chunk public.banking_pay_operation_chunks%rowtype;
  v_batch public.pay_batches%rowtype;
  v_actor_is_valid boolean := true;
  v_diff_limit integer;
  v_timesheet_ids uuid[] := array[]::uuid[];
  v_item_ids uuid[] := array[]::uuid[];
  v_candidate_ids uuid[] := array[]::uuid[];
  v_checked_units integer := 0;
  v_checked_item_count integer := 0;
  v_checked_timesheet_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_key_diff_count integer := 0;
  v_other_reservation_count integer := 0;
  v_finance_reservation_diff_count integer := 0;
  v_snooze_count integer := 0;
  v_restructure_or_writeoff_count integer := 0;
  v_timesheet_override_count integer := 0;
  v_deduction_diff_count integer := 0;
  v_candidate_scope_deduction_diff_count integer := 0;
  v_stale_count integer := 0;
  v_is_stale boolean := false;
  v_reasons text[] := array[]::text[];
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_chunk_blockers jsonb := '[]'::jsonb;
  v_chunk_result_hash text := null;
  v_result jsonb := '{}'::jsonb;
  v_carry_forward_freshness_result jsonb := '{}'::jsonb;
  v_carry_forward_blocker_count integer := 0;
begin
  if p_operation_id is null then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_ID_REQUIRED')::text;
  end if;

  if p_chunk_id is null then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_CHUNK_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_CHUNK_ID_REQUIRED')::text;
  end if;

  if p_pay_batch_id is null then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_PAY_BATCH_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_PAY_BATCH_ID_REQUIRED')::text;
  end if;

  v_diff_limit := coalesce(p_diff_limit, 50);
  if v_diff_limit < 0 then
    v_diff_limit := 0;
  elsif v_diff_limit > 250 then
    v_diff_limit := 250;
  end if;

  select operation_row.*
  into v_operation
  from public.banking_pay_operations as operation_row
  where operation_row.id = p_operation_id;

  if not found then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text
            )::text;
  end if;

  if v_operation.pay_batch_id is not null and v_operation.pay_batch_id <> p_pay_batch_id then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_BATCH_MISMATCH'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'operation_pay_batch_id', v_operation.pay_batch_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  end if;

  select pay_batch_row.*
  into v_batch
  from public.pay_batches as pay_batch_row
  where pay_batch_row.id = p_pay_batch_id;

  if not found then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_BATCH_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  end if;

  if p_actor_user_id is not null then
    select exists (
      select 1
      from public.tms_users as actor_user
      where actor_user.id = p_actor_user_id
        and coalesce(actor_user.is_active, false) = true
    )
    into v_actor_is_valid;

    if coalesce(v_actor_is_valid, false) is not true then
      raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_ACTOR_NOT_ALLOWED'
        using errcode = 'P0001',
              detail = jsonb_build_object(
                'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    end if;
  end if;

  select chunk_row.*
  into v_chunk
  from public.banking_pay_operation_chunks as chunk_row
  where chunk_row.id = p_chunk_id;

  if not found then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_NOT_FOUND',
              'chunk_id', p_chunk_id::text
            )::text;
  end if;

  if v_chunk.operation_id <> p_operation_id then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_MISMATCH'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_OPERATION_MISMATCH',
              'chunk_id', p_chunk_id::text,
              'chunk_operation_id', v_chunk.operation_id::text,
              'operation_id', p_operation_id::text
            )::text;
  end if;

  if v_chunk.phase <> 'VALIDATE_FRESHNESS' or v_chunk.chunk_type <> 'FRESHNESS_VALIDATE' then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_INVALID_CHUNK_KIND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_INVALID_CHUNK_KIND',
              'chunk_id', p_chunk_id::text,
              'phase', v_chunk.phase,
              'chunk_type', v_chunk.chunk_type
            )::text;
  end if;

  if jsonb_typeof(v_chunk.payload_json) <> 'object' or jsonb_typeof(v_chunk.payload_json->'units') <> 'array' then
    raise exception 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_INVALID_PAYLOAD'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_VALIDATE_FRESHNESS_CHUNK_INVALID_PAYLOAD',
              'chunk_id', p_chunk_id::text
            )::text;
  end if;

  select coalesce(array_agg(distinct (unit_value->>'timesheet_id')::uuid) filter (where nullif(unit_value->>'timesheet_id', '') is not null), array[]::uuid[]),
         coalesce(array_agg(distinct (item_id_text.item_id)::uuid) filter (where item_id_text.item_id is not null), array[]::uuid[]),
         coalesce(array_agg(distinct (unit_value->>'candidate_id')::uuid) filter (where nullif(unit_value->>'candidate_id', '') is not null), array[]::uuid[]),
         count(*)::integer
  into v_timesheet_ids, v_item_ids, v_candidate_ids, v_checked_units
  from jsonb_array_elements(v_chunk.payload_json->'units') as unit_items(unit_value)
  left join lateral jsonb_array_elements_text(coalesce(unit_items.unit_value->'pay_batch_item_ids', '[]'::jsonb)) as item_id_text(item_id)
    on true;

  v_checked_timesheet_count := coalesce(array_length(v_timesheet_ids, 1), 0);
  v_checked_item_count := coalesce(array_length(v_item_ids, 1), 0);

  create temporary table if not exists pg_temp.tmp_validate_freshness_chunk_diffs (
    reason text not null,
    timesheet_id uuid null,
    pay_batch_item_id uuid null,
    candidate_id uuid null,
    key_type text null,
    key_value text null,
    expected jsonb null,
    actual jsonb null,
    ord integer not null
  ) on commit drop;

  truncate table pg_temp.tmp_validate_freshness_chunk_diffs;

  if v_checked_item_count > 0 then
  insert into pg_temp.tmp_validate_freshness_chunk_diffs (
      reason,
      timesheet_id,
      pay_batch_item_id,
      candidate_id,
      key_type,
      key_value,
      expected,
      actual,
      ord
    )
    select
      'KEY_RESOLUTION_FAILED',
      batch_component.timesheet_id,
      batch_component.pay_batch_item_id,
      null::uuid,
      batch_component.key_type,
      batch_component.key_value,
      jsonb_build_object('batch_component', batch_component.pay_batch_item_id::text),
      jsonb_build_object('failure_reason', batch_component.key_resolution_failure_reason),
      10
    from public._pay_batch_item_economic_components(null::uuid, v_item_ids) as batch_component
    where nullif(btrim(coalesce(batch_component.key_resolution_failure_reason, '')), '') is not null;
  
    get diagnostics v_key_resolution_failure_count = row_count;
  
    /*
      Policy X / chunked freshness:
      Do not compare frozen batch economic components to live current entitlement
      or live reserved-component helpers in the chunk validator. The batch-side
      economic keyspace has already been resolved above through
      _pay_batch_item_economic_components(...) and unresolved frozen economic
      keys are surfaced as KEY_RESOLUTION_FAILED. Any later payment-scope,
      carry-forward, finance reservation, snooze, write-off, restructure, or
      correction drift is handled by the explicit frozen/artifact checks below.
    */
    v_key_diff_count := 0;
    v_other_reservation_count := 0;
  
  
  else
    v_key_resolution_failure_count := 0;
    v_key_diff_count := 0;
    v_other_reservation_count := 0;
  end if;

  insert into pg_temp.tmp_validate_freshness_chunk_diffs (
    reason,
    timesheet_id,
    pay_batch_item_id,
    candidate_id,
    key_type,
    key_value,
    expected,
    actual,
    ord
  )
  select
    'FINANCE_RESERVATION_CHANGED',
    batch_item.timesheet_id,
    batch_item.id,
    batch_candidate.candidate_id,
    'FINANCE_RESERVATION',
    coalesce(batch_item.finance_case_id::text, batch_item.reservation_id::text, batch_item.finance_component_id::text, batch_item.id::text),
    jsonb_build_object('expected_status', case when upper(coalesce(v_batch.status, '')) in ('AUTHORISED_FOR_PAYMENT', 'SCHEDULED', 'EXECUTING') then 'COMMITTED' else 'RESERVED' end),
    jsonb_build_object('actual_status', reservation_row.status, 'reservation_id', reservation_row.id::text),
    40
  from public.pay_batch_items as batch_item
  join public.pay_batch_candidates as batch_candidate
    on batch_candidate.id = batch_item.pay_batch_candidate_id
  left join public.pay_advance_reservations as reservation_row
    on reservation_row.pay_batch_item_id = batch_item.id
  where batch_item.id = any(v_item_ids)
    and batch_item.finance_case_id is not null
    and (
      reservation_row.id is null
      or upper(coalesce(reservation_row.status, '')) <> case when upper(coalesce(v_batch.status, '')) in ('AUTHORISED_FOR_PAYMENT', 'SCHEDULED', 'EXECUTING') then 'COMMITTED' else 'RESERVED' end
    );

  get diagnostics v_finance_reservation_diff_count = row_count;

  insert into pg_temp.tmp_validate_freshness_chunk_diffs (
    reason,
    timesheet_id,
    pay_batch_item_id,
    candidate_id,
    key_type,
    key_value,
    expected,
    actual,
    ord
  )
  with chunk_item_scope as (
    select
      batch_item.id as pay_batch_item_id,
      batch_item.timesheet_id,
      batch_candidate.candidate_id,
      nullif(btrim(coalesce(batch_item.source_ref, '')), '') as source_ref,
      nullif(btrim(coalesce(batch_item.segment_key, '')), '') as segment_key,
      coalesce(
        nullif(btrim(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
        nullif(btrim(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
        nullif(btrim(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
        nullif(btrim(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
        nullif(btrim(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
        nullif(btrim(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), '')
      ) as frozen_booking_id,
      batch_item.finance_case_id,
      batch_item.finance_component_id,
      upper(btrim(coalesce(batch_item.item_type, ''))) as item_type
    from public.pay_batch_items as batch_item
    join public.pay_batch_candidates as batch_candidate
      on batch_candidate.id = batch_item.pay_batch_candidate_id
    where batch_item.id = any(v_item_ids)
      and batch_candidate.pay_batch_id = p_pay_batch_id
  ), chunk_booking_scope as (
    select distinct
      chunk_item_scope.frozen_booking_id as booking_id
    from chunk_item_scope
    where chunk_item_scope.frozen_booking_id is not null

    union

    select distinct
      coalesce(
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
      ) as booking_id
    from public.pay_batch_timesheet_snapshots as snapshot_row
    where snapshot_row.pay_batch_id = p_pay_batch_id
      and snapshot_row.timesheet_id = any(v_timesheet_ids)
      and coalesce(
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
        nullif(btrim(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
      ) is not null
  ), scoped_snoozes as (
    select distinct
      snooze_row.id,
      snooze_row.timesheet_id,
      snooze_row.candidate_id,
      snooze_row.source_ref,
      snooze_row.segment_stable_key,
      snooze_row.segment_id,
      snooze_row.booking_id,
      snooze_row.snooze_kind,
      snooze_row.snooze_until_date
    from public.pay_item_snoozes as snooze_row
    where snooze_row.cleared_at_utc is null
      and snooze_row.cancelled_at_utc is null
      and (
        snooze_row.snooze_until_date is null
        or snooze_row.snooze_until_date >= v_today_uk
      )
      and (
        (snooze_row.timesheet_id is not null and snooze_row.timesheet_id = any(v_timesheet_ids))
        or exists (
          select 1
          from chunk_item_scope as source_ref_scope
          where source_ref_scope.source_ref is not null
            and nullif(btrim(coalesce(snooze_row.source_ref, '')), '') = source_ref_scope.source_ref
        )
        or exists (
          select 1
          from chunk_item_scope as segment_scope
          where segment_scope.segment_key is not null
            and (
              nullif(btrim(coalesce(snooze_row.segment_id, '')), '') = segment_scope.segment_key
              or nullif(btrim(coalesce(snooze_row.segment_stable_key, '')), '') = segment_scope.segment_key
            )
        )
        or exists (
          select 1
          from chunk_booking_scope as booking_scope
          where booking_scope.booking_id is not null
            and nullif(btrim(coalesce(snooze_row.booking_id, '')), '') = booking_scope.booking_id
        )
        or (
          snooze_row.candidate_id = any(v_candidate_ids)
          and snooze_row.timesheet_id is null
          and nullif(btrim(coalesce(snooze_row.source_ref, '')), '') is null
          and nullif(btrim(coalesce(snooze_row.segment_id, '')), '') is null
          and nullif(btrim(coalesce(snooze_row.segment_stable_key, '')), '') is null
          and nullif(btrim(coalesce(snooze_row.booking_id, '')), '') is null
          and upper(btrim(coalesce(snooze_row.snooze_kind, ''))) in ('FINANCE', 'FINANCE_CASE', 'LOAN', 'OVERPAYMENT', 'MANUAL_DEBT', 'PAY_ADVANCE', 'RECOVERY')
          and exists (
            select 1
            from chunk_item_scope as finance_scope
            where finance_scope.candidate_id = snooze_row.candidate_id
              and (finance_scope.finance_case_id is not null or finance_scope.finance_component_id is not null)
          )
        )
      )
  )
  select
    'ACTIVE_SNOOZE_CHANGED',
    scoped_snoozes.timesheet_id,
    null::uuid,
    scoped_snoozes.candidate_id,
    'SNOOZE',
    coalesce(scoped_snoozes.source_ref, scoped_snoozes.segment_stable_key, scoped_snoozes.segment_id, scoped_snoozes.booking_id, scoped_snoozes.id::text),
    jsonb_build_object('expected', 'no_active_snooze_affecting_batch_scope'),
    jsonb_build_object('snooze_id', scoped_snoozes.id::text, 'snooze_kind', scoped_snoozes.snooze_kind, 'snooze_until_date', scoped_snoozes.snooze_until_date),
    50
  from scoped_snoozes;

  get diagnostics v_snooze_count = row_count;

  insert into pg_temp.tmp_validate_freshness_chunk_diffs (
    reason,
    timesheet_id,
    pay_batch_item_id,
    candidate_id,
    key_type,
    key_value,
    expected,
    actual,
    ord
  )
  select
    'FINANCE_CASE_RESTRUCTURE_OR_WRITEOFF_CHANGED',
    batch_item.timesheet_id,
    batch_item.id,
    batch_candidate.candidate_id,
    'FINANCE_CASE',
    batch_item.finance_case_id::text,
    jsonb_build_object('expected', 'finance_case_open_and_not_written_off'),
    jsonb_build_object('advance_status', advance_row.status, 'written_off_at_utc', advance_row.written_off_at_utc),
    60
  from public.pay_batch_items as batch_item
  join public.pay_batch_candidates as batch_candidate
    on batch_candidate.id = batch_item.pay_batch_candidate_id
  join public.pay_advances as advance_row
    on advance_row.id = batch_item.finance_case_id
  where batch_item.id = any(v_item_ids)
    and batch_item.finance_case_id is not null
    and (
      advance_row.written_off_at_utc is not null
      or upper(coalesce(advance_row.status::text, '')) in ('CANCELLED', 'PAID_OFF')
    );

  get diagnostics v_restructure_or_writeoff_count = row_count;

  v_timesheet_override_count := 0;

  insert into pg_temp.tmp_validate_freshness_chunk_diffs (
    reason,
    timesheet_id,
    pay_batch_item_id,
    candidate_id,
    key_type,
    key_value,
    expected,
    actual,
    ord
  )
  with candidate_finance_items as (
    select
      batch_candidate.candidate_id,
      batch_item.id as pay_batch_item_id,
      batch_item.finance_case_id,
      batch_item.finance_component_id,
      round(abs(coalesce(batch_item.amount_ex_vat, 0)), 2)::numeric as item_amount_ex_vat
    from public.pay_batch_items as batch_item
    join public.pay_batch_candidates as batch_candidate
      on batch_candidate.id = batch_item.pay_batch_candidate_id
    where batch_candidate.pay_batch_id = p_pay_batch_id
      and batch_candidate.candidate_id = any(v_candidate_ids)
      and coalesce(batch_item.is_voided, false) = false
      and batch_item.item_type in ('LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY')
      and (batch_item.finance_case_id is not null or batch_item.finance_component_id is not null)
  ), finance_item_totals as (
    select
      candidate_finance_items.candidate_id,
      candidate_finance_items.finance_case_id,
      candidate_finance_items.finance_component_id,
      round(sum(candidate_finance_items.item_amount_ex_vat), 2)::numeric as item_total_ex_vat
    from candidate_finance_items
    group by candidate_finance_items.candidate_id, candidate_finance_items.finance_case_id, candidate_finance_items.finance_component_id
  ), reservation_totals as (
    select
      candidate_finance_items.candidate_id,
      reservation_row.finance_case_id,
      reservation_row.finance_component_id,
      round(sum(abs(coalesce(reservation_row.reserved_amount, reservation_row.frozen_rounded_target_amount, 0))), 2)::numeric as reservation_total_ex_vat
    from candidate_finance_items
    join public.pay_advance_reservations as reservation_row
      on reservation_row.pay_batch_item_id = candidate_finance_items.pay_batch_item_id
    group by candidate_finance_items.candidate_id, reservation_row.finance_case_id, reservation_row.finance_component_id
  ), mismatches as (
    select
      finance_item_totals.candidate_id,
      finance_item_totals.finance_case_id,
      finance_item_totals.finance_component_id,
      finance_item_totals.item_total_ex_vat,
      coalesce(reservation_totals.reservation_total_ex_vat, 0)::numeric as reservation_total_ex_vat
    from finance_item_totals
    left join reservation_totals
      on reservation_totals.candidate_id is not distinct from finance_item_totals.candidate_id
     and reservation_totals.finance_case_id is not distinct from finance_item_totals.finance_case_id
     and reservation_totals.finance_component_id is not distinct from finance_item_totals.finance_component_id
    where finance_item_totals.item_total_ex_vat <> coalesce(reservation_totals.reservation_total_ex_vat, 0)
  )
  select
    'CANDIDATE_SCOPE_DEDUCTION_MISMATCH',
    null::uuid,
    null::uuid,
    mismatches.candidate_id,
    'DEDUCTION_RECOVERY',
    coalesce(mismatches.finance_case_id::text, mismatches.finance_component_id::text),
    jsonb_build_object('candidate_batch_finance_item_total_ex_vat', mismatches.item_total_ex_vat),
    jsonb_build_object('candidate_batch_reservation_total_ex_vat', mismatches.reservation_total_ex_vat),
    80
  from mismatches;

  get diagnostics v_candidate_scope_deduction_diff_count = row_count;
  v_deduction_diff_count := v_candidate_scope_deduction_diff_count;

  v_carry_forward_freshness_result := public._pay_manual_adjustment_carry_forward_freshness_check(
    p_pay_batch_id,
    v_candidate_ids,
    v_item_ids,
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_ids', COALESCE((
        SELECT jsonb_agg(chunk_candidate_ids.candidate_id::text ORDER BY chunk_candidate_ids.candidate_id::text)
        FROM unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS chunk_candidate_ids(candidate_id)
      ), '[]'::jsonb),
      'pay_batch_item_ids', COALESCE((
        SELECT jsonb_agg(chunk_item_ids.pay_batch_item_id::text ORDER BY chunk_item_ids.pay_batch_item_id::text)
        FROM unnest(COALESCE(v_item_ids, ARRAY[]::uuid[])) AS chunk_item_ids(pay_batch_item_id)
      ), '[]'::jsonb)
    ),
    p_actor_user_id
  );

  v_carry_forward_blocker_count := jsonb_array_length(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb));

  IF COALESCE(v_carry_forward_blocker_count, 0) > 0 THEN
    INSERT INTO pg_temp.tmp_validate_freshness_chunk_diffs (
      reason,
      timesheet_id,
      pay_batch_item_id,
      candidate_id,
      key_type,
      key_value,
      expected,
      actual,
      ord
    )
    SELECT
      CASE
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
          THEN 'Manual adjustment carry-forward was consumed elsewhere'
        WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
          THEN 'Source payment scope changed'
        ELSE 'Manual adjustment carry-forward changed'
      END AS reason,
      NULL::uuid AS timesheet_id,
      NULL::uuid AS pay_batch_item_id,
      NULL::uuid AS candidate_id,
      'MANUAL_CARRY_FORWARD'::text AS key_type,
      COALESCE(carry_forward_blockers.blocker_value->>'carry_forward_id', carry_forward_blockers.blocker_value->>'code') AS key_value,
      jsonb_build_object(
        'status', 'fresh',
        'message', 'Manual adjustment carry-forward remains reserved for this batch with unchanged signed amounts.'
      ) AS expected,
      carry_forward_blockers.blocker_value AS actual,
      90 AS ord
    FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_blockers(blocker_value);

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_reason_blockers(blocker_value)
      WHERE COALESCE(carry_forward_reason_blockers.blocker_value->>'code', '') NOT IN (
        'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE',
        'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
      )
    ) THEN
      v_reasons := array_append(v_reasons, 'Manual adjustment carry-forward changed');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_reason_blockers(blocker_value)
      WHERE COALESCE(carry_forward_reason_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
    ) THEN
      v_reasons := array_append(v_reasons, 'Manual adjustment carry-forward was consumed elsewhere');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_carry_forward_freshness_result->'blockers', '[]'::jsonb)) AS carry_forward_reason_blockers(blocker_value)
      WHERE COALESCE(carry_forward_reason_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
    ) THEN
      v_reasons := array_append(v_reasons, 'Source payment scope changed');
    END IF;
  END IF;

  INSERT INTO pg_temp.tmp_validate_freshness_chunk_diffs (
    reason,
    timesheet_id,
    pay_batch_item_id,
    candidate_id,
    key_type,
    key_value,
    expected,
    actual,
    ord
  )
  SELECT
    CASE
      WHEN correction_items.correction_item_kind = 'PRE_BANK_CANCEL' THEN 'Payment was cancelled/recalculated'
      WHEN correction_items.correction_item_kind = 'NO_MONEY_UNWIND' THEN 'Financials were rewound'
      ELSE 'Payment scope changed'
    END,
    NULL::uuid,
    correction_items.pay_batch_item_id,
    correction_items.candidate_id,
    'PAYMENT_CORRECTION',
    correction_items.correction_item_kind,
    jsonb_build_object('payment_scope', 'active'),
    jsonb_build_object(
      'payment_scope', correction_items.correction_item_kind,
      'correction_request_id', correction_items.correction_request_id::text
    ),
    91
  FROM public.pay_payment_correction_items AS correction_items
  WHERE correction_items.pay_batch_id = p_pay_batch_id
    AND correction_items.status = 'APPLIED'
    AND correction_items.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND')
    AND (
      COALESCE(array_length(v_item_ids, 1), 0) = 0
      OR correction_items.pay_batch_item_id = ANY(v_item_ids)
    );

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS pre_bank_correction_reason_items
    WHERE pre_bank_correction_reason_items.pay_batch_id = p_pay_batch_id
      AND pre_bank_correction_reason_items.status = 'APPLIED'
      AND pre_bank_correction_reason_items.correction_item_kind = 'PRE_BANK_CANCEL'
      AND (
        COALESCE(array_length(v_item_ids, 1), 0) = 0
        OR pre_bank_correction_reason_items.pay_batch_item_id = ANY(v_item_ids)
      )
  ) THEN
    v_reasons := array_append(v_reasons, 'Payment was cancelled/recalculated');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_items AS no_money_correction_reason_items
    WHERE no_money_correction_reason_items.pay_batch_id = p_pay_batch_id
      AND no_money_correction_reason_items.status = 'APPLIED'
      AND no_money_correction_reason_items.correction_item_kind = 'NO_MONEY_UNWIND'
      AND (
        COALESCE(array_length(v_item_ids, 1), 0) = 0
        OR no_money_correction_reason_items.pay_batch_item_id = ANY(v_item_ids)
      )
  ) THEN
    v_reasons := array_append(v_reasons, 'Financials were rewound');
  END IF;

  select count(*)::integer
  into v_stale_count
  from pg_temp.tmp_validate_freshness_chunk_diffs as diff_count_row;

  v_is_stale := coalesce(v_stale_count, 0) > 0;

  if v_key_resolution_failure_count > 0 then
    v_reasons := array_append(v_reasons, 'KEY_RESOLUTION_FAILED');
  end if;
  if greatest(coalesce(v_key_diff_count, 0) - coalesce(v_other_reservation_count, 0), 0) > 0 then
    v_reasons := array_append(v_reasons, 'RESERVATION_CHANGED');
  end if;
  if v_other_reservation_count > 0 then
    v_reasons := array_append(v_reasons, 'OTHER_ACTIVE_RESERVATION');
  end if;
  if v_finance_reservation_diff_count > 0 then
    v_reasons := array_append(v_reasons, 'FINANCE_RESERVATION_CHANGED');
  end if;
  if v_snooze_count > 0 then
    v_reasons := array_append(v_reasons, 'ACTIVE_SNOOZE_CHANGED');
  end if;
  if v_restructure_or_writeoff_count > 0 then
    v_reasons := array_append(v_reasons, 'FINANCE_CASE_RESTRUCTURE_OR_WRITEOFF_CHANGED');
  end if;
  if v_timesheet_override_count > 0 then
    v_reasons := array_append(v_reasons, 'TIMESHEET_PAYMENT_OVERRIDE_CHANGED');
  end if;
  if v_deduction_diff_count > 0 then
    v_reasons := array_append(v_reasons, 'DEDUCTION_RECOVERY_CHANGED');
  end if;
  if v_candidate_scope_deduction_diff_count > 0 then
    v_reasons := array_append(v_reasons, 'CANDIDATE_SCOPE_DEDUCTION_MISMATCH');
  end if;

  select coalesce(jsonb_object_agg(reason_counts.reason, reason_counts.reason_count order by reason_counts.reason), '{}'::jsonb)
  into v_stale_reason_counts
  from (
    select diff_rows.reason, count(*)::integer as reason_count
    from pg_temp.tmp_validate_freshness_chunk_diffs as diff_rows
    group by diff_rows.reason
  ) as reason_counts;

  if coalesce(v_deduction_diff_count, 0) > 0 then
    v_stale_reason_counts := coalesce(v_stale_reason_counts, '{}'::jsonb)
      || jsonb_build_object('DEDUCTION_RECOVERY_CHANGED', v_deduction_diff_count);
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'reason', diff_sample_rows.reason,
      'timesheet_id', case when diff_sample_rows.timesheet_id is null then null else diff_sample_rows.timesheet_id::text end,
      'pay_batch_item_id', case when diff_sample_rows.pay_batch_item_id is null then null else diff_sample_rows.pay_batch_item_id::text end,
      'candidate_id', case when diff_sample_rows.candidate_id is null then null else diff_sample_rows.candidate_id::text end,
      'key_type', diff_sample_rows.key_type,
      'key_value', diff_sample_rows.key_value,
      'expected', diff_sample_rows.expected,
      'actual', diff_sample_rows.actual
    )
    order by diff_sample_rows.ord, diff_sample_rows.reason, diff_sample_rows.timesheet_id nulls last, diff_sample_rows.pay_batch_item_id nulls last
  ), '[]'::jsonb)
  into v_diff_sample
  from (
    select diff_rows.*
    from pg_temp.tmp_validate_freshness_chunk_diffs as diff_rows
    order by diff_rows.ord, diff_rows.reason, diff_rows.timesheet_id nulls last, diff_rows.pay_batch_item_id nulls last
    limit v_diff_limit
  ) as diff_sample_rows;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'code', case
        when blocker_rows.reason = 'Payment was cancelled/recalculated' then 'PAYMENT_WAS_CANCELLED_RECALCULATED'
        when blocker_rows.reason = 'Financials were rewound' then 'FINANCIALS_WERE_REWOUND'
        when blocker_rows.reason = 'Source payment scope changed' then 'SOURCE_PAYMENT_SCOPE_CHANGED'
        when blocker_rows.reason = 'Manual adjustment carry-forward changed' then 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CHANGED'
        when blocker_rows.reason = 'Manual adjustment carry-forward was consumed elsewhere' then 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
        else upper(regexp_replace(blocker_rows.reason, '[^A-Za-z0-9]+', '_', 'g'))
      end,
      'reason', blocker_rows.reason,
      'message', blocker_rows.reason,
      'timesheet_id', case when blocker_rows.timesheet_id is null then null else blocker_rows.timesheet_id::text end,
      'pay_batch_item_id', case when blocker_rows.pay_batch_item_id is null then null else blocker_rows.pay_batch_item_id::text end,
      'candidate_id', case when blocker_rows.candidate_id is null then null else blocker_rows.candidate_id::text end,
      'key_type', blocker_rows.key_type,
      'key_value', blocker_rows.key_value,
      'expected', blocker_rows.expected,
      'actual', blocker_rows.actual
    )
    order by blocker_rows.ord, blocker_rows.reason, blocker_rows.timesheet_id nulls last, blocker_rows.pay_batch_item_id nulls last
  ), '[]'::jsonb)
  into v_chunk_blockers
  from (
    select diff_rows.*
    from pg_temp.tmp_validate_freshness_chunk_diffs as diff_rows
    order by diff_rows.ord, diff_rows.reason, diff_rows.timesheet_id nulls last, diff_rows.pay_batch_item_id nulls last
    limit v_diff_limit
  ) as blocker_rows;

  if array_length(v_reasons, 1) is not null then
    select array_agg(distinct reason_value order by reason_value)
    into v_reasons
    from unnest(v_reasons) as reason_values(reason_value);
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'is_stale', v_is_stale,
    'checked_units', coalesce(v_checked_units, 0),
    'checked_count', coalesce(v_checked_units, 0),
    'checked_item_count', coalesce(v_checked_item_count, 0),
    'checked_timesheet_count', coalesce(v_checked_timesheet_count, 0),
    'stale_count', coalesce(v_stale_count, 0),
    'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
    'stale_reason_counts', coalesce(v_stale_reason_counts, '{}'::jsonb),
    'blockers', coalesce(v_chunk_blockers, '[]'::jsonb),
    'key_resolution_failure_count', coalesce(v_key_resolution_failure_count, 0),
    'diff_sample', coalesce(v_diff_sample, '[]'::jsonb),
    'counts', jsonb_build_object(
      'reservation_changed', greatest(coalesce(v_key_diff_count, 0) - coalesce(v_other_reservation_count, 0), 0),
      'economic_key_changed', 0,
      'other_active_reservation', coalesce(v_other_reservation_count, 0),
      'finance_reservation_changed', coalesce(v_finance_reservation_diff_count, 0),
      'active_snooze_changed', coalesce(v_snooze_count, 0),
      'finance_case_restructure_or_writeoff_changed', coalesce(v_restructure_or_writeoff_count, 0),
      'timesheet_payment_override_changed', coalesce(v_timesheet_override_count, 0),
      'deduction_recovery_changed', coalesce(v_deduction_diff_count, 0),
      'candidate_scope_deduction_mismatch', coalesce(v_candidate_scope_deduction_diff_count, 0)
    ),
    'operation_id', p_operation_id::text,
    'chunk_id', p_chunk_id::text,
    'pay_batch_id', p_pay_batch_id::text
  );

  v_chunk_result_hash := md5(v_result::text);
  v_result := v_result || jsonb_build_object('chunk_result_hash', v_chunk_result_hash);

  update public.banking_pay_operation_chunks as chunk_update
  set result_json = v_result,
      error_json = null,
      completed_count = coalesce(v_checked_units, 0),
      failed_count = case when v_is_stale then coalesce(v_stale_count, 0) else 0 end,
      updated_at_utc = now()
  where chunk_update.id = p_chunk_id;

    return jsonb_build_object(
    'ok', true,
    'is_stale', v_is_stale,
    'checked_count', coalesce(v_checked_units, 0),
    'stale_count', coalesce(v_stale_count, 0),
    'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
    'stale_reason_counts', coalesce(v_stale_reason_counts, '{}'::jsonb),
    'blockers', coalesce(v_chunk_blockers, '[]'::jsonb),
    'diff_sample', coalesce(v_diff_sample, '[]'::jsonb),
    'key_resolution_failure_count', coalesce(v_key_resolution_failure_count, 0),
    'chunk_result_hash', v_chunk_result_hash,
    'result', v_result
  );
end;
$function$;

-- pay_batch_validate_freshness(uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness(p_pay_batch_id uuid, p_actor_user_id uuid, p_allow_large_full_scan boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base_result jsonb;
  v_base_diff jsonb := '[]'::jsonb;
  v_filtered_diff jsonb := '[]'::jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_fresh_chain_components jsonb := '[]'::jsonb;
  v_original_key_diff_count integer := 0;
  v_suppressed_key_diff_count integer := 0;
  v_remaining_key_diff_count integer := 0;
BEGIN
  v_base_result := public._pay_batch_validate_freshness_base_v1(
    p_pay_batch_id,
    p_actor_user_id,
    p_allow_large_full_scan
  );

  v_base_diff := COALESCE(v_base_result->'diff', '[]'::jsonb);
  v_reasons := COALESCE(v_base_result->'stale_reasons', '[]'::jsonb);

  /*
   * A correction-chain item freezes its complete residual evidence when the
   * draft is created. The base freshness validator intentionally uses the
   * ordinary timesheet entitlement comparison for all economic rows. That
   * ordinary comparison cannot distinguish a correction-chain residual from
   * its root timesheet and therefore sees this batch's own reservation as a
   * change.
   *
   * Reconstruct the pre-current-batch correction-chain residual through the
   * bounded Policy X helper. Suppress only the exact base diff when every
   * frozen component still equals the reconstructed component. Any helper
   * error or real component change fails closed and leaves the base stale
   * result untouched.
   */
  WITH correction_items AS (
    SELECT DISTINCT ON (
      correction_item.source_family_key,
      correction_item.candidate_id,
      correction_item.target_pay_method
    )
      correction_item.pay_batch_item_id,
      correction_item.root_timesheet_id,
      correction_item.candidate_id,
      correction_item.source_family_key,
      correction_item.target_pay_method,
      correction_item.frozen_residual
    FROM (
      SELECT
        pay_batch_item.id AS pay_batch_item_id,
        COALESCE(
          NULLIF(
            COALESCE(
              pay_batch_item.frozen_source_basis_json
                #>> '{correction_chain_residual,root_timesheet_id}',
              pay_batch_item.frozen_component_snapshot_json
                #>> '{correction_chain_residual,root_timesheet_id}'
            ),
            ''
          )::uuid,
          CASE
            WHEN COALESCE(
              pay_batch_item.frozen_source_basis_json->>'source_family_key',
              pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
              ''
            ) ~ '^correction-chain:[0-9a-fA-F-]{36}$'
              THEN replace(
                COALESCE(
                  pay_batch_item.frozen_source_basis_json->>'source_family_key',
                  pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
                ),
                'correction-chain:',
                ''
              )::uuid
            ELSE pay_batch_item.timesheet_id
          END
        ) AS root_timesheet_id,
        pay_batch_candidate.candidate_id,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item.frozen_source_basis_json->>'source_family_key',
          pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
          ''
        )), '') AS source_family_key,
        UPPER(NULLIF(BTRIM(COALESCE(
          pay_batch_item.frozen_target_pay_method,
          pay_batch_item.pay_channel,
          pay_batch.batch_kind_fixed,
          ''
        )), '')) AS target_pay_method,
        COALESCE(
          pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
          pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
        ) AS frozen_residual
      FROM public.pay_batch_items AS pay_batch_item
      JOIN public.pay_batch_candidates AS pay_batch_candidate
        ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
      JOIN public.pay_batches AS pay_batch
        ON pay_batch.id = pay_batch_candidate.pay_batch_id
      WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
        AND COALESCE(pay_batch_item.is_voided, false) = false
        AND COALESCE(
          NULLIF(BTRIM(COALESCE(
            pay_batch_item.frozen_source_basis_json->>'source_family_key',
            pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
            ''
          )), ''),
          ''
        ) LIKE 'correction-chain:%'
        /*
         * Filter to the row that actually owns the frozen chain snapshot
         * before DISTINCT ON chooses one row for the family. A recovery item
         * can share the family key without carrying the snapshot; allowing it
         * into the ordering can hide the valid correction carrier entirely.
         */
        AND jsonb_typeof(
          COALESCE(
            pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
            pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
          )
        ) = 'object'
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS correction_item_exclusion
          WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
            AND correction_item_exclusion.status = 'APPLIED'
            AND correction_item_exclusion.correction_item_kind IN (
              'PRE_BANK_CANCEL',
              'NO_MONEY_UNWIND',
              'SETTLED_REVERSAL'
            )
        )
    ) AS correction_item
    WHERE correction_item.root_timesheet_id IS NOT NULL
      AND correction_item.candidate_id IS NOT NULL
      AND correction_item.target_pay_method IN ('PAYE', 'UMBRELLA')
      AND jsonb_typeof(correction_item.frozen_residual) = 'object'
    ORDER BY
      correction_item.source_family_key,
      correction_item.candidate_id,
      correction_item.target_pay_method,
      correction_item.pay_batch_item_id
  ),
  chain_results AS (
    SELECT
      correction_item.*,
      public.pay_correction_chain_residual_v1(
        correction_item.root_timesheet_id,
        correction_item.candidate_id,
        correction_item.target_pay_method,
        NULL::uuid,
        p_pay_batch_id,
        100
      ) AS live_residual
    FROM correction_items AS correction_item
  ),
  expected_components AS (
    SELECT
      chain_result.root_timesheet_id,
      chain_result.source_family_key,
      UPPER(NULLIF(BTRIM(component.component_json->>'component_key_type'), ''))
        AS key_type,
      NULLIF(BTRIM(component.component_json->>'component_key_value'), '')
        AS key_value,
      CASE
        WHEN COALESCE(
          component.component_json->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS amount_ex
    FROM chain_results AS chain_result
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(chain_result.frozen_residual->'components') = 'array'
          THEN chain_result.frozen_residual->'components'
        ELSE '[]'::jsonb
      END
    ) AS component(component_json)
  ),
  live_components AS (
    SELECT
      chain_result.root_timesheet_id,
      chain_result.source_family_key,
      UPPER(NULLIF(BTRIM(component.component_json->>'component_key_type'), ''))
        AS key_type,
      NULLIF(BTRIM(component.component_json->>'component_key_value'), '')
        AS key_value,
      CASE
        WHEN COALESCE(
          component.component_json->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS amount_ex
    FROM chain_results AS chain_result
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(chain_result.live_residual->'components') = 'array'
          THEN chain_result.live_residual->'components'
        ELSE '[]'::jsonb
      END
    ) AS component(component_json)
  ),
  chain_component_comparison AS (
    SELECT
      COALESCE(expected.root_timesheet_id, live.root_timesheet_id)
        AS root_timesheet_id,
      COALESCE(expected.source_family_key, live.source_family_key)
        AS source_family_key,
      COALESCE(expected.key_type, live.key_type) AS key_type,
      COALESCE(expected.key_value, live.key_value) AS key_value,
      expected.amount_ex AS expected_ex,
      live.amount_ex AS actual_ex,
      (
        expected.amount_ex IS NOT NULL
        AND live.amount_ex IS NOT NULL
        AND ABS(
          ROUND(expected.amount_ex, 2) - ROUND(live.amount_ex, 2)
        ) <= 0.01
      ) AS component_matches
    FROM expected_components AS expected
    FULL JOIN live_components AS live
      ON live.source_family_key = expected.source_family_key
     AND live.key_type = expected.key_type
     AND live.key_value = expected.key_value
  ),
  fresh_families AS (
    SELECT comparison.source_family_key
    FROM chain_component_comparison AS comparison
    GROUP BY comparison.source_family_key
    HAVING COUNT(*) > 0
       AND BOOL_AND(comparison.component_matches)
  ),
  fresh_components AS (
    SELECT comparison.*
    FROM chain_component_comparison AS comparison
    JOIN fresh_families AS fresh_family
      ON fresh_family.source_family_key = comparison.source_family_key
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'timesheet_id', fresh_component.root_timesheet_id::text,
        'key_type', fresh_component.key_type,
        'key_value', fresh_component.key_value,
        'expected_ex', fresh_component.expected_ex
      )
      ORDER BY
        fresh_component.root_timesheet_id,
        fresh_component.key_type,
        fresh_component.key_value
    ),
    '[]'::jsonb
  )
  INTO v_fresh_chain_components
  FROM fresh_components AS fresh_component;

  /*
   * Current canonical recovery items freeze one component per item rather
   * than embedding a second complete residual object. Accept that flat frozen
   * shape only when the chain and policy fingerprints still match and the
   * exact frozen component still equals the bounded live residual (with this
   * batch excluded). This also supplies the fresh anchor proof used by linked
   * resolved ordinary components below.
   */
  WITH flat_correction_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      (
        REPLACE(
          COALESCE(
            pay_batch_item.frozen_source_basis_json->>'source_family_key',
            pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
          ),
          'correction-chain:',
          ''
        )
      )::uuid AS root_timesheet_id,
      pay_batch_candidate.candidate_id,
      COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
      ) AS source_family_key,
      UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_target_pay_method,
        pay_batch_item.pay_channel,
        pay_batch.batch_kind_fixed,
        ''
      ))) AS target_pay_method,
      UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        pay_batch_item.frozen_component_snapshot_json->>'component_key_type',
        ''
      ))) AS key_type,
      BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        pay_batch_item.frozen_component_snapshot_json->>'component_key_value',
        ''
      )) AS key_value,
      CASE
        WHEN pay_batch_item.frozen_source_amount IS NOT NULL
          THEN ROUND(
            pay_batch_item.frozen_source_amount,
            2
          )::numeric(12,2)
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_pay_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            COALESCE(
              pay_batch_item.frozen_resolution_result_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_pay_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS expected_ex,
      CASE
        WHEN pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
          THEN ROUND(
            pay_batch_item.frozen_target_amount_ex_vat,
            2
          )::numeric(12,2)
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'target_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'target_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE ROUND(
          pay_batch_item.amount_ex_vat,
          2
        )::numeric(12,2)
      END AS expected_target_ex,
      ROUND(
        pay_batch_item.amount_ex_vat,
        2
      )::numeric(12,2) AS physical_target_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'source_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'source_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS result_source_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'target_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'target_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS result_target_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_pay_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            COALESCE(
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_pay_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS snapshot_source_ex,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_source_basis_json
          ->>'correction_chain_fingerprint',
        pay_batch_item.frozen_component_snapshot_json
          ->>'correction_chain_fingerprint',
        ''
      )), '') AS frozen_chain_fingerprint,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_source_basis_json
          ->>'correction_financials_policy_envelope_fingerprint',
        pay_batch_item.frozen_component_snapshot_json
          ->>'correction_financials_policy_envelope_fingerprint',
        ''
      )), '') AS frozen_policy_fingerprint
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.pay_batches AS pay_batch
      ON pay_batch.id = pay_batch_candidate.pay_batch_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
        ''
      ) ~ '^correction-chain:[0-9a-fA-F-]{36}$'
      AND jsonb_typeof(
        pay_batch_item.frozen_component_snapshot_json
      ) = 'object'
      AND pay_batch_item.frozen_source_amount IS NOT NULL
      AND pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_exclusion
        WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
          AND correction_item_exclusion.status = 'APPLIED'
          AND correction_item_exclusion.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ),
  flat_chain_groups AS (
    SELECT DISTINCT
      flat_item.root_timesheet_id,
      flat_item.candidate_id,
      flat_item.source_family_key,
      flat_item.target_pay_method
    FROM flat_correction_items AS flat_item
    WHERE flat_item.root_timesheet_id IS NOT NULL
      AND flat_item.candidate_id IS NOT NULL
      AND flat_item.target_pay_method IN ('PAYE', 'UMBRELLA')
  ),
  flat_chain_results AS (
    SELECT
      flat_group.*,
      public.pay_correction_chain_residual_v1(
        flat_group.root_timesheet_id,
        flat_group.candidate_id,
        flat_group.target_pay_method,
        NULL::uuid,
        p_pay_batch_id,
        100
      ) AS live_residual
    FROM flat_chain_groups AS flat_group
  ),
  flat_fresh_components AS (
    SELECT
      flat_item.root_timesheet_id,
      flat_item.key_type,
      flat_item.key_value,
      flat_item.expected_ex
    FROM flat_correction_items AS flat_item
    JOIN flat_chain_results AS flat_result
      ON flat_result.root_timesheet_id = flat_item.root_timesheet_id
     AND flat_result.candidate_id = flat_item.candidate_id
     AND flat_result.source_family_key = flat_item.source_family_key
     AND flat_result.target_pay_method = flat_item.target_pay_method
    JOIN LATERAL (
      SELECT live_component.component_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(flat_result.live_residual->'components') = 'array'
            THEN flat_result.live_residual->'components'
          ELSE '[]'::jsonb
        END
      ) AS live_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(
              live_component.component_json->>'component_key_type',
              ''
            ))) = flat_item.key_type
        AND BTRIM(COALESCE(
              live_component.component_json->>'component_key_value',
              ''
            )) = flat_item.key_value
      LIMIT 1
    ) AS matched_live_component
      ON true
    WHERE flat_item.key_type IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE',
        'EXPENSE_CODE'
      )
      AND flat_item.key_value <> ''
      AND flat_item.expected_ex IS NOT NULL
      AND flat_item.expected_target_ex IS NOT NULL
      AND flat_item.result_source_ex IS NOT NULL
      AND flat_item.result_target_ex IS NOT NULL
      AND flat_item.snapshot_source_ex IS NOT NULL
      AND flat_item.frozen_chain_fingerprint IS NOT NULL
      AND flat_item.frozen_policy_fingerprint IS NOT NULL
      AND flat_item.frozen_chain_fingerprint
            = flat_result.live_residual->>'chain_fingerprint'
      AND flat_item.frozen_policy_fingerprint
            = flat_result.live_residual
                ->>'correction_financials_policy_envelope_fingerprint'
      AND COALESCE(
        matched_live_component.component_json
          ->>'target_outstanding_ex_vat',
        matched_live_component.component_json
          ->>'effective_source_outstanding_ex_vat',
        ''
      ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND(flat_item.expected_target_ex, 2)
        - ROUND(
            COALESCE(
              matched_live_component.component_json
                ->>'target_outstanding_ex_vat',
              matched_live_component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.result_source_ex, 2)
        - ROUND(flat_item.expected_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.snapshot_source_ex, 2)
        - ROUND(flat_item.expected_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.result_target_ex, 2)
        - ROUND(flat_item.expected_target_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.physical_target_ex, 2)
        - ROUND(flat_item.expected_target_ex, 2)
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', flat_component.root_timesheet_id::text,
          'key_type', flat_component.key_type,
          'key_value', flat_component.key_value,
          'expected_ex', flat_component.expected_ex
        )
        ORDER BY
          flat_component.root_timesheet_id,
          flat_component.key_type,
          flat_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM flat_fresh_components AS flat_component;

  /*
   * A resolved ordinary timesheet component can also carry an approved target
   * rate. Its frozen source entitlement is the full original component, while
   * the item pays only the target-side remainder after the already-settled
   * baseline. The ordinary base comparison therefore reports the expected
   * source entitlement against zero even when:
   *
   *   - the live source component is unchanged;
   *   - no other active batch reserves the component;
   *   - the exact target remainder was frozen into this batch; and
   *   - its exact local-timesheet anchor remains valid, or its linked
   *     correction-chain anchor remains fresh.
   *
   * Suppress only that exact self-reservation diff. This is deliberately
   * stricter than trusting the summary flag: frozen component evidence,
   * physical/result parity, every frozen member of the economic component,
   * current source truth, settled baseline, absence of another reservation,
   * and the applicable frozen anchor must all agree. Any missing, partial or
   * contradictory evidence leaves the base stale result intact.
   */
  WITH linked_resolution_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      pay_batch_item.timesheet_id,
      UPPER(BTRIM(COALESCE(pay_batch_item.frozen_component_key_type, '')))
        AS key_type,
      BTRIM(COALESCE(pay_batch_item.frozen_component_key_value, ''))
        AS key_value,
      pay_batch_item.amount_ex_vat,
      pay_batch_item.frozen_source_amount,
      pay_batch_item.frozen_target_amount_ex_vat,
      pay_batch_item.frozen_resolution_result_json,
      pay_batch_item.frozen_resolution_payload_json
        ->'case_resolution_summary' AS resolution_summary,
      resolved_component.component_count,
      resolved_component.source_numeric_count,
      resolved_component.target_numeric_count,
      resolved_component.resolved_source_ex_vat,
      resolved_component.resolved_target_ex_vat,
      resolved_component.all_components_resolved,
      resolved_component.all_component_fingerprints_present,
      resolved_component.all_source_basis_fingerprints_present,
      resolved_component.all_components_current,
      resolved_component.all_saved_results_current,
      resolved_component.all_components_do_not_require_resolution,
      resolved_component.all_saved_anchor_modes_match,
      resolved_component.all_saved_anchor_case_keys_match,
      resolved_component.all_saved_anchor_timesheets_match,
      LOWER(BTRIM(COALESCE(
        pay_batch_item.frozen_resolution_payload_json
          #>> '{case_resolution_summary,resolved_rate_applied_via_linked_scope}',
        'false'
      ))) IN ('true','t','1','yes','y','on')
        AS applied_via_linked_scope,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_payload_json
            #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}',
          ''
        ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (
            pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}'
          )::uuid
        ELSE NULL::uuid
      END AS anchor_timesheet_id,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_resolution_payload_json
          #>> '{case_resolution_summary,resolved_rate_source_anchor_case_key}',
        ''
      )), '') AS anchor_case_key
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS component_count,
        COUNT(*) FILTER (
          WHERE COALESCE(
            frozen_component.component_json->>'source_pay_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        )::integer AS source_numeric_count,
        COUNT(*) FILTER (
          WHERE COALESCE(
            frozen_component.component_json->>'target_pay_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        )::integer AS target_numeric_count,
        ROUND(SUM(
          CASE
            WHEN COALESCE(
              frozen_component.component_json->>'source_pay_ex_vat',
              ''
            ) ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (
                frozen_component.component_json->>'source_pay_ex_vat'
              )::numeric
            ELSE 0::numeric
          END
        ), 2)::numeric(12,2) AS resolved_source_ex_vat,
        ROUND(SUM(
          CASE
            WHEN COALESCE(
              frozen_component.component_json->>'target_pay_ex_vat',
              ''
            ) ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (
                frozen_component.component_json->>'target_pay_ex_vat'
              )::numeric
            ELSE 0::numeric
          END
        ), 2)::numeric(12,2) AS resolved_target_ex_vat,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'resolved_rate_resolution_id',
          ''
        )), '') IS NOT NULL) AS all_components_resolved,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'component_fingerprint',
          ''
        )), '') IS NOT NULL) AS all_component_fingerprints_present,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'source_basis_fingerprint',
          ''
        )), '') IS NOT NULL) AS all_source_basis_fingerprints_present,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'is_resolution_stale',
          'false'
        ))) NOT IN ('true','t','1','yes','y','on'))
          AS all_components_current,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'is_stale_saved_resolution',
          'false'
        ))) NOT IN ('true','t','1','yes','y','on'))
          AS all_saved_results_current,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'requires_resolution',
          'true'
        ))) IN ('false','f','0','no','n','off'))
          AS all_components_do_not_require_resolution,
        BOOL_AND(
          (
            LOWER(BTRIM(COALESCE(
              frozen_component.component_json
                #>> '{saved_resolution_result_json,applied_via_linked_scope}',
              'false'
            ))) IN ('true','t','1','yes','y','on')
          ) = (
            LOWER(BTRIM(COALESCE(
              pay_batch_item.frozen_resolution_payload_json
                #>> '{case_resolution_summary,resolved_rate_applied_via_linked_scope}',
              'false'
            ))) IN ('true','t','1','yes','y','on')
          )
        ) AS all_saved_anchor_modes_match,
        BOOL_AND(
          frozen_component.component_json
            #>> '{saved_resolution_result_json,source_anchor_case_key}'
          = pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_case_key}'
        ) AS all_saved_anchor_case_keys_match,
        BOOL_AND(
          frozen_component.component_json
            #>> '{saved_resolution_result_json,source_anchor_timesheet_id}'
          = pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}'
        ) AS all_saved_anchor_timesheets_match
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(
            pay_batch_item.frozen_resolution_payload_json->'case_components'
          ) = 'array'
            THEN pay_batch_item.frozen_resolution_payload_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) AS frozen_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(
              frozen_component.component_json->>'component_key_type',
              ''
            ))) = UPPER(BTRIM(COALESCE(
              pay_batch_item.frozen_component_key_type,
              ''
            )))
        AND BTRIM(COALESCE(
              frozen_component.component_json->>'component_key_value',
              ''
            )) = BTRIM(COALESCE(
              pay_batch_item.frozen_component_key_value,
              ''
            ))
    ) AS resolved_component
      ON true
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(pay_batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        ''
      ))) IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE'
      )
      AND BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        ''
      )) <> ''
      AND jsonb_typeof(
        pay_batch_item.frozen_resolution_payload_json
          ->'case_resolution_summary'
      ) = 'object'
      AND COALESCE(resolved_component.component_count, 0) > 0
  ),
  linked_timesheet_ids AS (
    SELECT COALESCE(
      ARRAY_AGG(
        DISTINCT linked_resolution_item.timesheet_id
        ORDER BY linked_resolution_item.timesheet_id
      ),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM linked_resolution_items AS linked_resolution_item
  ),
  linked_outstanding AS (
    SELECT
      outstanding_component.timesheet_id,
      UPPER(BTRIM(COALESCE(outstanding_component.key_type, '')))
        AS key_type,
      BTRIM(COALESCE(outstanding_component.key_value, '')) AS key_value,
      ROUND(COALESCE(outstanding_component.truth_ex_vat, 0), 2)
        AS truth_ex_vat,
      ROUND(COALESCE(outstanding_component.baseline_ex_vat, 0), 2)
        AS baseline_ex_vat,
      ROUND(COALESCE(outstanding_component.reserved_ex_vat, 0), 2)
        AS other_reserved_ex_vat,
      ROUND(COALESCE(outstanding_component.outstanding_ex_vat, 0), 2)
        AS outstanding_ex_vat
    FROM linked_timesheet_ids AS linked_scope
    JOIN public._pay_outstanding_components(
      linked_scope.timesheet_ids,
      p_pay_batch_id
    ) AS outstanding_component
      ON true
  ),
  fresh_linked_resolution_components AS (
    SELECT
      linked_resolution_item.timesheet_id,
      linked_resolution_item.key_type,
      linked_resolution_item.key_value,
      linked_resolution_item.resolved_source_ex_vat AS expected_ex
    FROM linked_resolution_items AS linked_resolution_item
    JOIN linked_outstanding AS outstanding_component
      ON outstanding_component.timesheet_id
           = linked_resolution_item.timesheet_id
     AND outstanding_component.key_type = linked_resolution_item.key_type
     AND outstanding_component.key_value = linked_resolution_item.key_value
    WHERE linked_resolution_item.resolved_source_ex_vat IS NOT NULL
      AND linked_resolution_item.resolved_target_ex_vat IS NOT NULL
      AND linked_resolution_item.anchor_timesheet_id IS NOT NULL
      AND linked_resolution_item.anchor_case_key IS NOT NULL
      AND LOWER(BTRIM(COALESCE(
        linked_resolution_item.resolution_summary->>'has_resolved_rate',
        'false'
      ))) IN ('true','t','1','yes','y','on')
      AND LOWER(BTRIM(COALESCE(
        linked_resolution_item.resolution_summary
          ->>'case_resolution_satisfied_now',
        'false'
      ))) IN ('true','t','1','yes','y','on')
      AND linked_resolution_item.resolution_summary
            ->>'resolved_rate_timesheet_id'
          = linked_resolution_item.timesheet_id::text
      AND linked_resolution_item.component_count
            = linked_resolution_item.source_numeric_count
      AND linked_resolution_item.component_count
            = linked_resolution_item.target_numeric_count
      AND linked_resolution_item.all_components_resolved
      AND linked_resolution_item.all_component_fingerprints_present
      AND linked_resolution_item.all_source_basis_fingerprints_present
      AND linked_resolution_item.all_components_current
      AND linked_resolution_item.all_saved_results_current
      AND linked_resolution_item.all_components_do_not_require_resolution
      AND linked_resolution_item.all_saved_anchor_modes_match
      AND linked_resolution_item.all_saved_anchor_case_keys_match
      AND linked_resolution_item.all_saved_anchor_timesheets_match
      AND (
        (
          linked_resolution_item.applied_via_linked_scope
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(v_fresh_chain_components)
              AS fresh_anchor(value)
            WHERE fresh_anchor.value->>'timesheet_id'
                    = linked_resolution_item.anchor_timesheet_id::text
              AND LOWER(linked_resolution_item.anchor_case_key)
                    = LOWER(
                        'correction-chain:'
                        || linked_resolution_item.anchor_timesheet_id::text
                        || ':'
                        || COALESCE(fresh_anchor.value->>'key_type', '')
                        || ':'
                        || COALESCE(fresh_anchor.value->>'key_value', '')
                      )
          )
        )
        OR
        (
          NOT linked_resolution_item.applied_via_linked_scope
          AND linked_resolution_item.anchor_timesheet_id
                = linked_resolution_item.timesheet_id
          AND LOWER(linked_resolution_item.anchor_case_key)
                = LOWER(
                    'timesheet:'
                    || linked_resolution_item.timesheet_id::text
                  )
        )
      )
      AND ABS(
        ROUND(outstanding_component.truth_ex_vat, 2)
        - ROUND(linked_resolution_item.resolved_source_ex_vat, 2)
      ) <= 0.01
      AND ABS(
        ROUND(outstanding_component.baseline_ex_vat, 2)
        - ROUND(linked_resolution_item.resolved_source_ex_vat, 2)
      ) <= 0.01
      AND ABS(ROUND(outstanding_component.other_reserved_ex_vat, 2)) <= 0.01
      AND ABS(
        ROUND(linked_resolution_item.frozen_target_amount_ex_vat, 2)
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND COALESCE(
        linked_resolution_item.frozen_resolution_result_json
          ->>'target_amount_ex_vat',
        ''
      ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND(
          (
            linked_resolution_item.frozen_resolution_result_json
              ->>'target_amount_ex_vat'
          )::numeric,
          2
        )
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND linked_resolution_item.frozen_source_amount IS NOT NULL
      AND ABS(
        ROUND(linked_resolution_item.frozen_source_amount, 2)
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND ABS(
        ROUND(linked_resolution_item.amount_ex_vat, 2)
        - ROUND(
            GREATEST(
              linked_resolution_item.resolved_target_ex_vat
                - outstanding_component.baseline_ex_vat,
              0
            ),
            2
          )
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', linked_component.timesheet_id::text,
          'key_type', linked_component.key_type,
          'key_value', linked_component.key_value,
          'expected_ex', linked_component.expected_ex
        )
        ORDER BY
          linked_component.timesheet_id,
          linked_component.key_type,
          linked_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM fresh_linked_resolution_components AS linked_component;

  /*
   * A completed semantic-V3 source can retain a settled entitlement baseline
   * that the legacy live helper no longer exposes.  In that exact case the
   * base validator compares the frozen source amount with live truth alone
   * and mistakes this batch's own reservation for external drift.
   *
   * Recover the baseline only from the one current, parity-complete V3
   * publication that is fenced to the candidate registry's current sequence
   * and generation.  Live truth must still equal the certified build truth,
   * all other reservations are read live with this batch excluded, and the
   * complete frozen source/target evidence must reconcile exactly.  Any
   * missing, mixed or stale authority leaves the base stale result untouched.
   */
  WITH frozen_ordinary_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      pay_batch_candidate.candidate_id,
      pay_batch_item.timesheet_id,
      UPPER(BTRIM(pay_batch_item.frozen_component_key_type)) AS key_type,
      BTRIM(pay_batch_item.frozen_component_key_value) AS key_value,
      ROUND(pay_batch_item.frozen_source_amount, 2)::numeric(12,2)
        AS frozen_source_ex,
      ROUND(pay_batch_item.frozen_target_amount_ex_vat, 2)::numeric(12,2)
        AS frozen_target_ex,
      ROUND(pay_batch_item.amount_ex_vat, 2)::numeric(12,2)
        AS physical_target_ex
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(pay_batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        ''
      ))) IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE',
        'EXPENSE_CODE'
      )
      AND BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        ''
      )) <> ''
      AND pay_batch_item.frozen_source_amount IS NOT NULL
      AND pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
      AND ABS(
        ROUND(pay_batch_item.frozen_target_amount_ex_vat, 2)
        - ROUND(pay_batch_item.amount_ex_vat, 2)
      ) <= 0.01
      AND COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
        ''
      ) NOT LIKE 'correction-chain:%'
      AND jsonb_typeof(
        pay_batch_item.frozen_resolution_payload_json
          ->'case_resolution_summary'
      ) IS DISTINCT FROM 'object'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_exclusion
        WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
          AND correction_item_exclusion.status = 'APPLIED'
          AND correction_item_exclusion.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ), certified_authority_candidates AS (
    SELECT
      registry.candidate_id,
      scope_row.session_id,
      scope_row.certified_preview_publication_source_build_run_id
        AS source_build_run_id,
      scope_row.certified_preview_publication_source_publication_id
        AS source_publication_id,
      economic_build.id AS build_id,
      registry.current_source_change_seq,
      registry.dirty_generation
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.candidate_id = registry.candidate_id
     AND scope_row.status = 'MATERIALISED'
     AND COALESCE(scope_row.dirty, false) = false
     AND COALESCE(
           scope_row.certified_preview_publication_required,
           false
         )
     AND COALESCE(
           scope_row.certified_preview_publication_parity_ok,
           false
         )
     AND scope_row.certified_preview_publication_source_change_seq
           = registry.current_source_change_seq
     AND scope_row.certified_preview_publication_source_build_run_id
           IS NOT NULL
     AND scope_row.certified_preview_publication_source_publication_id
           IS NOT NULL
    JOIN private.banking_pay_workbench_economic_builds AS economic_build
      ON economic_build.id = CASE
           WHEN COALESCE(
                  scope_row.certified_preview_publication_attestation_json
                    ->>'economic_build_id',
                  ''
                ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN (
               scope_row.certified_preview_publication_attestation_json
                 ->>'economic_build_id'
             )::uuid
           ELSE NULL::uuid
         END
     AND economic_build.candidate_id = registry.candidate_id
     AND economic_build.session_id = scope_row.session_id
     AND economic_build.source_build_run_id
           = scope_row.certified_preview_publication_source_build_run_id
     AND economic_build.source_change_seq
           = registry.current_source_change_seq
     AND economic_build.captured_candidate_generation
           = registry.evaluated_generation
     AND economic_build.status = 'COMPLETE'
    WHERE registry.dirty_generation = registry.evaluated_generation
      AND scope_row.certified_preview_publication_attestation_json
            ->>'attestation_version'
          = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
      AND LOWER(BTRIM(COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'parity_complete',
            'false'
          ))) IN ('true','t','1','yes','y','on')
      AND LOWER(BTRIM(COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'semantic_ready',
            'false'
          ))) IN ('true','t','1','yes','y','on')
      AND COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'invalid_selectable_row_count',
            ''
          ) ~ '^[0-9]+$'
      AND (
            scope_row.certified_preview_publication_attestation_json
              ->>'invalid_selectable_row_count'
          )::integer = 0
      AND scope_row.certified_preview_publication_attestation_json
            ->>'source_build_run_id'
          = scope_row.certified_preview_publication_source_build_run_id::text
      AND scope_row.certified_preview_publication_attestation_json
            ->>'source_publication_id'
          = scope_row.certified_preview_publication_source_publication_id::text
      AND COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'source_row_count',
            ''
          ) ~ '^[0-9]+$'
      AND (
        SELECT COUNT(*)::integer
        FROM public.banking_pay_workbench_candidate_source_lines
          AS current_source
        WHERE current_source.session_id = scope_row.session_id
          AND current_source.candidate_id = registry.candidate_id
          AND current_source.session_version
                = scope_row.certified_preview_publication_session_version
          AND current_source.source_change_seq
                = registry.current_source_change_seq
          AND current_source.source_build_run_id
                = scope_row.certified_preview_publication_source_build_run_id
          AND current_source.source_publication_id
                = scope_row.certified_preview_publication_source_publication_id
          AND current_source.status = 'CURRENT'
      ) = (
        scope_row.certified_preview_publication_attestation_json
          ->>'source_row_count'
      )::integer
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_candidate_source_lines
          AS conflicting_source
        WHERE conflicting_source.session_id = scope_row.session_id
          AND conflicting_source.candidate_id = registry.candidate_id
          AND conflicting_source.status = 'CURRENT'
          AND (
            conflicting_source.session_version
              IS DISTINCT FROM
                scope_row.certified_preview_publication_session_version
            OR conflicting_source.source_change_seq
              IS DISTINCT FROM registry.current_source_change_seq
            OR conflicting_source.source_build_run_id
              IS DISTINCT FROM
                scope_row.certified_preview_publication_source_build_run_id
            OR conflicting_source.source_publication_id
              IS DISTINCT FROM
                scope_row.certified_preview_publication_source_publication_id
          )
      )
  ), certified_current_authorities AS (
    SELECT authority.*
    FROM certified_authority_candidates AS authority
    WHERE 1 = (
      SELECT COUNT(*)
      FROM certified_authority_candidates AS candidate_authority
      WHERE candidate_authority.candidate_id = authority.candidate_id
    )
  ), certified_fresh_components AS (
    SELECT
      frozen_item.timesheet_id,
      frozen_item.key_type,
      frozen_item.key_value,
      frozen_item.frozen_source_ex AS expected_ex
    FROM frozen_ordinary_items AS frozen_item
    JOIN certified_current_authorities AS certified_authority
      ON certified_authority.candidate_id = frozen_item.candidate_id
    JOIN private.pay_current_timesheet_entitlement_components_from_build_v1(
      certified_authority.build_id,
      NULL::text
    ) AS certified_component
      ON certified_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(certified_component.key_type))
           = frozen_item.key_type
     AND BTRIM(certified_component.key_value) = frozen_item.key_value
    JOIN public._pay_current_timesheet_entitlement_components(
      ARRAY[frozen_item.timesheet_id]::uuid[]
    ) AS live_truth_component
      ON live_truth_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(live_truth_component.key_type))
           = frozen_item.key_type
     AND BTRIM(live_truth_component.key_value) = frozen_item.key_value
    JOIN LATERAL public._pay_outstanding_components(
      ARRAY[frozen_item.timesheet_id]::uuid[],
      p_pay_batch_id
    ) AS live_component
      ON live_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(live_component.key_type)) = frozen_item.key_type
     AND BTRIM(live_component.key_value) = frozen_item.key_value
    WHERE ABS(
        ROUND(COALESCE(live_truth_component.truth_ex_vat, 0), 2)
        - ROUND(COALESCE(certified_component.truth_ex_vat, 0), 2)
      ) <= 0.01
      AND ABS(
        ROUND(COALESCE(live_truth_component.baseline_ex_vat, 0), 2)
        - ROUND(COALESCE(certified_component.baseline_ex_vat, 0), 2)
      ) > 0.01
      AND ABS(
        ROUND(COALESCE(certified_component.baseline_ex_vat, 0), 2)
      ) > 0.01
      AND ABS(
        ROUND(
          COALESCE(certified_component.truth_ex_vat, 0)
          - COALESCE(certified_component.baseline_ex_vat, 0)
          - COALESCE(live_component.reserved_ex_vat, 0),
          2
        )
        - frozen_item.frozen_source_ex
      ) <= 0.01
      AND ABS(
        frozen_item.frozen_target_ex - frozen_item.physical_target_ex
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', certified_component.timesheet_id::text,
          'key_type', certified_component.key_type,
          'key_value', certified_component.key_value,
          'expected_ex', certified_component.expected_ex
        )
        ORDER BY
          certified_component.timesheet_id,
          certified_component.key_type,
          certified_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM certified_fresh_components AS certified_component;

  SELECT COALESCE(
    MAX(
      CASE
        WHEN diff_row.value->>'key_type' = 'INFO'
         AND diff_row.value->>'key_value' = 'COUNTS'
          THEN COALESCE(
            (diff_row.value#>>'{expected,key_diffs}')::integer,
            0
          )
        ELSE NULL
      END
    ),
    0
  )
  INTO v_original_key_diff_count
  FROM jsonb_array_elements(v_base_diff) AS diff_row(value);

  SELECT COUNT(*)::integer
  INTO v_suppressed_key_diff_count
  FROM jsonb_array_elements(v_base_diff) WITH ORDINALITY AS diff_row(value, ordinality)
  WHERE EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_fresh_chain_components)
      AS fresh_component(value)
    WHERE fresh_component.value->>'timesheet_id'
            = diff_row.value->>'timesheet_id'
      AND fresh_component.value->>'key_type'
            = diff_row.value->>'key_type'
      AND fresh_component.value->>'key_value'
            = diff_row.value->>'key_value'
      AND COALESCE(diff_row.value->>'expected', '')
            ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND((diff_row.value->>'expected')::numeric, 2)
        - ROUND((fresh_component.value->>'expected_ex')::numeric, 2)
      ) <= 0.01
  );

  SELECT COALESCE(
    jsonb_agg(diff_row.value ORDER BY diff_row.ordinality),
    '[]'::jsonb
  )
  INTO v_filtered_diff
  FROM jsonb_array_elements(v_base_diff) WITH ORDINALITY AS diff_row(value, ordinality)
  WHERE NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_fresh_chain_components)
      AS fresh_component(value)
    WHERE fresh_component.value->>'timesheet_id'
            = diff_row.value->>'timesheet_id'
      AND fresh_component.value->>'key_type'
            = diff_row.value->>'key_type'
      AND fresh_component.value->>'key_value'
            = diff_row.value->>'key_value'
      AND COALESCE(diff_row.value->>'expected', '')
            ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND((diff_row.value->>'expected')::numeric, 2)
        - ROUND((fresh_component.value->>'expected_ex')::numeric, 2)
      ) <= 0.01
  );

  v_remaining_key_diff_count := GREATEST(
    v_original_key_diff_count - v_suppressed_key_diff_count,
    0
  );

  SELECT COALESCE(
    jsonb_agg(
      CASE
        WHEN diff_row.value->>'key_type' = 'INFO'
         AND diff_row.value->>'key_value' = 'COUNTS'
          THEN jsonb_set(
            diff_row.value,
            '{expected,key_diffs}',
            to_jsonb(v_remaining_key_diff_count),
            true
          )
        ELSE diff_row.value
      END
      ORDER BY diff_row.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_filtered_diff
  FROM jsonb_array_elements(v_filtered_diff)
    WITH ORDINALITY AS diff_row(value, ordinality);

  IF v_remaining_key_diff_count = 0 THEN
    SELECT COALESCE(jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
    INTO v_reasons
    FROM jsonb_array_elements(v_reasons)
      WITH ORDINALITY AS reason(value, ordinality)
    WHERE reason.value <> to_jsonb('RESERVATION_CHANGED'::text);
  END IF;

  RETURN jsonb_build_object(
    'is_stale', jsonb_array_length(v_reasons) > 0,
    'stale_reasons', v_reasons,
    'diff', v_filtered_diff
  );
END;
$function$;

-- pay_batches_claim_due_scheduled(integer,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_batches_claim_due_scheduled(p_limit integer DEFAULT 50, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
 SET statement_timeout TO '6000ms'
 SET lock_timeout TO '1000ms'
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_cutoff timestamptz;
  v_limit integer;
  v_batch_record record;
  v_actor_user_id uuid;
  v_idempotency_key text;
  v_input_json jsonb;
  v_operation_id uuid;
  v_operation_created boolean;
  v_guard jsonb;
  v_operations_json jsonb := '[]'::jsonb;
  v_claimed_count integer := 0;
  v_skipped_count integer := 0;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 50 THEN
    RAISE EXCEPTION 'PAY_BATCHES_DUE_LIMIT_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'LIMIT_INVALID',
        'limit', p_limit
      )::text;
  END IF;
  v_limit := p_limit;

  -- current_user is always the definer inside this SECURITY DEFINER function.
  -- Only a genuine direct postgres session may use deterministic test time.
  IF p_now_utc IS NOT NULL AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'PAY_BATCHES_DUE_CALLER_TIME_OVERRIDE_NOT_ALLOWED'
      USING ERRCODE = '42501', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'CALLER_TIME_OVERRIDE_NOT_ALLOWED'
      )::text;
  END IF;
  v_cutoff := COALESCE(p_now_utc, v_now);

  FOR v_batch_record IN
    SELECT
      batch_row.id,
      batch_row.pay_date,
      batch_row.authoritative_payment_date,
      batch_row.schedule_kind,
      batch_row.scheduled_at_utc,
      batch_row.scheduled_by_user_id,
      batch_row.created_by_user_id,
      batch_row.funding_account_ref,
      batch_row.rail_provider_snapshot,
      batch_row.rail_env_snapshot,
      batch_row.execution_intent_json
    FROM public.pay_batches AS batch_row
    CROSS JOIN LATERAL public.pay_batch_submission_evidence(
      batch_row.id,
      true
    ) AS submission_evidence(evidence_json)
    WHERE batch_row.status = 'SCHEDULED'
      AND COALESCE(
        batch_row.execution_commit_state,
        'NOT_SUBMITTED'
      ) = 'NOT_SUBMITTED'
      AND batch_row.scheduled_at_utc IS NOT NULL
      AND batch_row.scheduled_at_utc <= v_cutoff
      AND batch_row.cancelled_at_utc IS NULL
      AND COALESCE(
        (submission_evidence.evidence_json
          ->> 'has_external_provider_submission')::boolean,
        false
      ) IS NOT TRUE
      AND COALESCE(
        (submission_evidence.evidence_json
          ->> 'has_pending_provider_outcome')::boolean,
        false
      ) IS NOT TRUE
      AND COALESCE(
        (submission_evidence.evidence_json
          ->> 'has_unknown_provider_outcome')::boolean,
        false
      ) IS NOT TRUE
      AND COALESCE(
        (submission_evidence.evidence_json
          ->> 'has_terminal_no_money')::boolean,
        false
      ) IS NOT TRUE
      AND COALESCE(
        (submission_evidence.evidence_json
          ->> 'has_final_paid_or_settled')::boolean,
        false
      ) IS NOT TRUE
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_candidates AS candidate_row
        JOIN public.pay_batch_items AS item_row
          ON item_row.pay_batch_candidate_id = candidate_row.id
        WHERE candidate_row.pay_batch_id = batch_row.id
          AND COALESCE(item_row.is_voided, false) IS NOT TRUE
          AND item_row.item_type <> 'DEBT_CREATED'
      )
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_auth_requests AS auth_request
        WHERE auth_request.pay_batch_id = batch_row.id
          AND auth_request.state = 'AUTHORISED'
      )
    ORDER BY batch_row.scheduled_at_utc, batch_row.id
    LIMIT v_limit
  LOOP
    v_guard := private.pay_payment_mutation_guard_v1(
      v_batch_record.id,
      NULL::uuid,
      'NEW_PAYMENT_ACTION'
    );

    IF COALESCE((v_guard->>'blocked')::boolean, true) THEN
      v_skipped_count := v_skipped_count + 1;
      v_operations_json := v_operations_json || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'pay_batch_id', v_batch_record.id,
          'operation_id', NULL,
          'operation_created', false,
          'code', COALESCE(
            v_guard->>'code',
            'PAYMENT_CHANGE_IN_PROGRESS'
          )
        )
      );
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.pay_batches AS locked_batch
    WHERE locked_batch.id = v_batch_record.id
      AND locked_batch.status = 'SCHEDULED'
      AND locked_batch.scheduled_at_utc IS NOT NULL
      AND locked_batch.scheduled_at_utc <= v_cutoff
      AND COALESCE(
        locked_batch.execution_commit_state,
        'NOT_SUBMITTED'
      ) = 'NOT_SUBMITTED'
      AND locked_batch.cancelled_at_utc IS NULL
    FOR UPDATE SKIP LOCKED;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.pay_bank_transfers AS transfer_row
      WHERE transfer_row.pay_batch_id = v_batch_record.id
        AND (
          transfer_row.request_id IS NOT NULL
          OR transfer_row.rail_tx_id IS NOT NULL
          OR transfer_row.status IN (
            'SUBMITTED',
            'PROCESSING',
            'COMPLETED',
            'PAID',
            'SETTLED'
          )
        )
    ) OR EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS event_row
      WHERE event_row.pay_batch_id = v_batch_record.id
        AND event_row.normalised_state IN (
          'UNKNOWN',
          'PENDING',
          'SUBMITTED',
          'PROCESSING',
          'COMPLETED',
          'PAID',
          'SETTLED'
        )
    ) THEN
      v_skipped_count := v_skipped_count + 1;
      v_operations_json := v_operations_json || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'pay_batch_id', v_batch_record.id,
          'operation_id', NULL,
          'operation_created', false,
          'code', 'PROVIDER_EVIDENCE_PRESENT'
        )
      );
      CONTINUE;
    END IF;

    v_actor_user_id := COALESCE(
      v_batch_record.scheduled_by_user_id,
      v_batch_record.created_by_user_id
    );
    IF v_actor_user_id IS NULL THEN
      v_skipped_count := v_skipped_count + 1;
      CONTINUE;
    END IF;

    v_idempotency_key :=
      'payment-execute:scheduled:batch:' || v_batch_record.id::text
      || ':scheduled_at:' || v_batch_record.scheduled_at_utc::text;

    v_input_json := pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'source', 'pay_batches_claim_due_scheduled',
        'pay_batch_id', v_batch_record.id,
        'scheduled_at_utc', v_batch_record.scheduled_at_utc,
        'schedule_kind', v_batch_record.schedule_kind,
        'execution_mode', COALESCE(
          v_batch_record.execution_intent_json->>'execution_mode',
          v_batch_record.execution_intent_json->>'mode',
          'STANDARD_BANK'
        ),
        'payment_date', COALESCE(
          v_batch_record.authoritative_payment_date,
          v_batch_record.pay_date
        ),
        'funding_account_ref', v_batch_record.funding_account_ref,
        'rail_provider_snapshot', v_batch_record.rail_provider_snapshot,
        'rail_env_snapshot', v_batch_record.rail_env_snapshot,
        'initial_phase', 'VALIDATE_BATCH',
        'backend_runner_owned', true,
        'claimed_at_utc', v_now
      )
    );

    SELECT operation_row.operation_id,
           operation_row.is_existing IS NOT TRUE
    INTO v_operation_id,
         v_operation_created
    FROM public.banking_pay_operation_start(
      'PAYMENT_EXECUTE',
      v_actor_user_id,
      v_idempotency_key,
      NULL::uuid,
      v_batch_record.id,
      NULL::uuid,
      v_input_json,
      pg_catalog.jsonb_build_object('run_after_utc', v_now)
    ) AS operation_row
    LIMIT 1;

    UPDATE public.pay_batches AS batch_update
    SET status = 'EXECUTING',
        executing_started_at_utc = COALESCE(
          batch_update.executing_started_at_utc,
          v_now
        ),
        execution_intent_json = pg_catalog.jsonb_strip_nulls(
          COALESCE(
            batch_update.execution_intent_json,
            '{}'::jsonb
          ) || pg_catalog.jsonb_build_object(
            'active_operation_id', v_operation_id,
            'scheduled_claimed_at_utc', v_now
          )
        )
    WHERE batch_update.id = v_batch_record.id
      AND batch_update.status = 'SCHEDULED'
      AND COALESCE(
        batch_update.execution_commit_state,
        'NOT_SUBMITTED'
      ) = 'NOT_SUBMITTED';

    v_operations_json := v_operations_json || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'pay_batch_id', v_batch_record.id,
        'operation_id', v_operation_id,
        'operation_created', v_operation_created,
        'operation_type', 'PAYMENT_EXECUTE',
        'idempotency_key', v_idempotency_key,
        'scheduled_at_utc', v_batch_record.scheduled_at_utc,
        'actor_user_id', v_actor_user_id,
        'code', CASE
          WHEN v_operation_created THEN 'DUE_OPERATION_STARTED'
          ELSE 'DUE_OPERATION_EXISTING'
        END
      )
    );
    v_claimed_count := v_claimed_count + 1;
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'error_code', NULL,
    'replacement_rpc', 'banking_pay_operation_start',
    'display_message', CASE
      WHEN v_claimed_count = 0 THEN 'No scheduled payments are due.'
      ELSE 'Due scheduled payments were queued for bounded processing.'
    END,
    'server_utc', v_now,
    'cutoff_utc', v_cutoff,
    'limit', v_limit,
    'claimed_count', v_claimed_count,
    'skipped_count', v_skipped_count,
    'operations', v_operations_json,
    'claimed', v_operations_json,
    'continuations', (
      SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'required', true,
          'operation_id', operation_item.value->>'operation_id',
          'operation_type', 'PAYMENT_EXECUTE',
          'pay_batch_id', operation_item.value->>'pay_batch_id',
          'root_operation_id', NULL,
          'phase', 'VALIDATE_BATCH',
          'run_after_utc', v_now,
          'reason', 'DUE_SCHEDULE_DISCOVERED',
          'successor_relation', 'SELF',
          'requires_user_action', false,
          'terminal', false
        ) ORDER BY operation_item.ordinality
      ), '[]'::jsonb)
      FROM pg_catalog.jsonb_array_elements(v_operations_json) WITH ORDINALITY AS operation_item(value, ordinality)
      WHERE COALESCE(operation_item.value->>'operation_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    ),
    'code', CASE
      WHEN v_claimed_count = 0 THEN 'NO_DUE_BATCH'
      ELSE 'DUE_OPERATION_STARTED'
    END
  );
END;
$function$;

-- pay_batches_list(integer,integer,text,uuid,text,boolean,boolean,boolean)
CREATE OR REPLACE FUNCTION public.pay_batches_list(p_limit integer DEFAULT 5, p_offset integer DEFAULT 0, p_status text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_display_mode text DEFAULT 'LIGHT'::text, p_include_diagnostics boolean DEFAULT false, p_include_alerts boolean DEFAULT false, p_include_correction_summary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 5), 200));
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_status text := UPPER(NULLIF(BTRIM(COALESCE(p_status, '')), ''));
  v_display_mode text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_display_mode, 'LIGHT')), ''), '-', '_'));
  v_include_diagnostics boolean := false;
  v_include_alerts boolean := COALESCE(p_include_alerts, false);
  v_include_correction_summary boolean := false;
  v_rows jsonb := '[]'::jsonb;
  v_returned_count integer := 0;
  v_total_count integer := 0;
  v_has_more boolean := false;
  v_next_offset integer := NULL::integer;
  v_previous_offset integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_cached_alert_summary jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('BATCH_LIST');

  IF v_display_mode IS NULL THEN
    v_display_mode := 'LIGHT';
  END IF;

  -- This list RPC is always the safe display path.  Diagnostic/correction
  -- enrichment requests are intentionally ignored here; explicit diagnostic
  -- routes must use their own RPCs.  Cached alert signal data may still be
  -- included when requested because it is read from banking_alert_display_summary.
  v_include_diagnostics := false;
  v_include_correction_summary := false;

  IF v_display_mode NOT IN ('LIGHT', 'SUMMARY', 'BOOTSTRAP') THEN
    RAISE EXCEPTION 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED',
              'display_mode', v_display_mode,
              'message', 'pay_batches_list only supports LIGHT/SUMMARY/BOOTSTRAP display modes on this safe list path.'
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  IF v_include_alerts AND p_actor_user_id IS NOT NULL THEN
    SELECT
      COALESCE(alert_summary.alert_hash, 'banking_alert_signal:v3:' || MD5('')),
      COALESCE(alert_summary.summary_hash, 'banking_alert_summary:v3:' || MD5('')),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label,
      COALESCE(alert_summary.summary_json, '{}'::jsonb)
    INTO
      v_cached_alert_hash,
      v_cached_summary_hash,
      v_cached_unacknowledged_count,
      v_cached_highest_severity,
      v_cached_highest_label,
      v_cached_alert_summary
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = p_actor_user_id;

    IF NOT FOUND THEN
      v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_cached_unacknowledged_count := 0;
      v_cached_highest_severity := NULL::text;
      v_cached_highest_label := NULL::text;
      v_cached_alert_summary := '{}'::jsonb;
    END IF;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_total_count
  FROM public.pay_batches AS pay_batch_count
  WHERE v_status IS NULL
     OR UPPER(COALESCE(pay_batch_count.status, '')) = v_status;

  WITH page_source AS (
    SELECT
      pay_batch_row.id,
      pay_batch_row.pay_date,
      pay_batch_row.authoritative_payment_date,
      pay_batch_row.authoritative_payment_date_source,
      pay_batch_row.created_at_utc,
      pay_batch_row.created_by_user_id,
      pay_batch_row.status,
      pay_batch_row.banking_system_snapshot,
      pay_batch_row.external_paye_system_snapshot,
      pay_batch_row.batch_kind_fixed,
      pay_batch_row.source_workbench_session_id,
      pay_batch_row.source_snapshot_run_id,
      pay_batch_row.source_session_version,
      pay_batch_row.execution_commit_state,
      pay_batch_row.execution_commit_ref,
      pay_batch_row.execution_committed_at_utc,
      pay_batch_row.rail_provider_snapshot,
      pay_batch_row.rail_env_snapshot,
      pay_batch_row.schedule_kind,
      pay_batch_row.scheduled_at_utc,
      pay_batch_row.funding_account_ref,
      pay_batch_row.total_bank_out,
      pay_batch_row.total_debt_created,
      pay_batch_row.freshness_validation_status,
      pay_batch_row.freshness_checked_at_utc,
      pay_batch_row.freshness_result_hash,
      display_summary.batch_status AS display_batch_status,
      display_summary.batch_kind AS display_batch_kind,
      display_summary.candidate_count,
      display_summary.item_count,
      display_summary.transfer_count,
      display_summary.total_payable,
      display_summary.total_bank_out AS display_total_bank_out,
      display_summary.execution_commit_state AS display_execution_commit_state,
      display_summary.rail_provider_label,
      display_summary.rail_env_label,
      display_summary.issue_summary_counts,
      display_summary.latest_operation_id,
      display_summary.latest_operation_status,
      display_summary.latest_operation_phase,
      active_execution_operation.id AS active_payment_operation_id,
      active_execution_operation.operation_type AS active_payment_operation_type,
      active_execution_operation.status AS active_payment_operation_status,
      active_execution_operation.phase AS active_payment_operation_phase,
      active_execution_operation.runner_state AS active_payment_operation_runner_state,
      active_execution_operation.requires_user_action AS active_payment_operation_requires_user_action,
      active_execution_operation.resume_reason AS active_payment_operation_resume_reason,
      active_execution_operation.updated_at_utc AS active_payment_operation_updated_at_utc,
      CASE
        WHEN active_execution_operation.id IS NULL THEN NULL::jsonb
        ELSE jsonb_strip_nulls(jsonb_build_object(
          'operation_id', active_execution_operation.id::text,
          'id', active_execution_operation.id::text,
          'operation_type', active_execution_operation.operation_type,
          'status', active_execution_operation.status,
          'phase', active_execution_operation.phase,
          'runner_state', active_execution_operation.runner_state,
          'requires_user_action', active_execution_operation.requires_user_action,
          'resume_reason', active_execution_operation.resume_reason,
          'pay_batch_id', active_execution_operation.pay_batch_id::text,
          'workbench_session_id', CASE WHEN active_execution_operation.workbench_session_id IS NULL THEN NULL::text ELSE active_execution_operation.workbench_session_id::text END,
          'progress_json', active_execution_operation.progress_json,
          'updated_at_utc', active_execution_operation.updated_at_utc
        ))
      END AS active_payment_operation,
      display_summary.display_label,
      display_summary.stale_summary_json,
      display_summary.freshness_validation_status AS display_freshness_validation_status,
      display_summary.freshness_checked_at_utc AS display_freshness_checked_at_utc,
      display_summary.freshness_result_hash AS display_freshness_result_hash,
      display_summary.summary_version,
      display_summary.updated_at_utc AS summary_updated_at_utc,
      COALESCE(batch_signal.version, 0) AS live_signal_version,
      COALESCE(batch_signal.payment_status_version, 0) AS payment_status_version,
      COALESCE(batch_signal.correction_progress_version, 0) AS correction_progress_version,
      COALESCE(batch_signal.alert_version, 0) AS alert_version,
      COALESCE(batch_signal.overview_version, 0) AS overview_version,
      batch_signal.last_status_hash,
      batch_signal.last_alert_hash,
      batch_signal.last_changed_at_utc,
      batch_signal.last_payment_status_changed_at_utc,
      batch_signal.last_correction_progress_changed_at_utc,
      batch_signal.last_alert_changed_at_utc,
      batch_signal.last_change_reason,
      batch_signal.last_change_source,
      COALESCE(batch_signal.last_change_scope_json, '{}'::jsonb) AS last_change_scope_json,
      COALESCE(batch_signal.last_changed_candidate_ids, '[]'::jsonb) AS last_changed_candidate_ids,
      COALESCE(batch_signal.last_changed_pay_batch_item_ids, '[]'::jsonb) AS last_changed_pay_batch_item_ids,
      COALESCE(batch_signal.last_changed_transfer_ids, '[]'::jsonb) AS last_changed_transfer_ids,
      ROW_NUMBER() OVER (ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC) AS row_ordinal
    FROM public.pay_batches AS pay_batch_row
    LEFT JOIN public.pay_batch_display_summary AS display_summary
      ON display_summary.pay_batch_id = pay_batch_row.id
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = pay_batch_row.id
    LEFT JOIN LATERAL (
      SELECT active_operation.*
      FROM public.banking_pay_operations AS active_operation
      WHERE active_operation.pay_batch_id = pay_batch_row.id
        AND upper(BTRIM(COALESCE(active_operation.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
        AND upper(BTRIM(COALESCE(active_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'RUNNABLE', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'WAITING_FOR_PROVIDER', 'AWAITING_PROVIDER', 'WAITING_USER', 'WAITING_USER_REVIEW', 'REVIEW_REQUIRED')
      ORDER BY
        CASE upper(BTRIM(COALESCE(active_operation.status, '')))
          WHEN 'RUNNING' THEN 0
          WHEN 'WAITING' THEN 1
          WHEN 'RUNNABLE' THEN 2
          WHEN 'QUEUED' THEN 3
          WHEN 'CONTINUING' THEN 4
          WHEN 'WAITING_RETRY' THEN 5
          WHEN 'WAITING_AUTHORISATION' THEN 6
          WHEN 'WAITING_AUTHORIZATION' THEN 6
          WHEN 'AWAITING_AUTHORISATION' THEN 6
          WHEN 'AWAITING_AUTHORIZATION' THEN 6
          WHEN 'WAITING_PROVIDER' THEN 7
          WHEN 'WAITING_FOR_PROVIDER' THEN 7
          WHEN 'AWAITING_PROVIDER' THEN 7
          WHEN 'WAITING_USER' THEN 8
          WHEN 'WAITING_USER_REVIEW' THEN 8
          WHEN 'REVIEW_REQUIRED' THEN 9
          ELSE 10
        END,
        active_operation.updated_at_utc DESC NULLS LAST,
        active_operation.created_at_utc DESC NULLS LAST,
        active_operation.id DESC
      LIMIT 1
    ) AS active_execution_operation ON true
    WHERE v_status IS NULL
       OR UPPER(COALESCE(pay_batch_row.status, '')) = v_status
    ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC
    LIMIT v_limit
    OFFSET v_offset
  ),
  page_json AS (
    SELECT
      page_source.row_ordinal,
      jsonb_strip_nulls(
        jsonb_build_object(
          'id', page_source.id::text,
          'pay_date', CASE WHEN page_source.pay_date IS NULL THEN NULL::text ELSE page_source.pay_date::text END,
          'authoritative_payment_date', CASE WHEN page_source.authoritative_payment_date IS NULL THEN NULL::text ELSE page_source.authoritative_payment_date::text END,
          'authoritative_payment_date_source', page_source.authoritative_payment_date_source,
          'created_at_utc', page_source.created_at_utc,
          'created_by_user_id', CASE WHEN page_source.created_by_user_id IS NULL THEN NULL::text ELSE page_source.created_by_user_id::text END,
          'status', page_source.status,
          'db_status', page_source.status,
          'batch_kind_fixed', page_source.batch_kind_fixed,
          'batch_kind', COALESCE(page_source.display_batch_kind, page_source.batch_kind_fixed),
          'display_label', page_source.display_label,
          'banking_system_snapshot', page_source.banking_system_snapshot,
          'external_paye_system_snapshot', page_source.external_paye_system_snapshot,
          'source_workbench_session_id', CASE WHEN page_source.source_workbench_session_id IS NULL THEN NULL::text ELSE page_source.source_workbench_session_id::text END,
          'source_snapshot_run_id', CASE WHEN page_source.source_snapshot_run_id IS NULL THEN NULL::text ELSE page_source.source_snapshot_run_id::text END,
          'source_session_version', page_source.source_session_version,
          'execution_commit_state', COALESCE(page_source.display_execution_commit_state, page_source.execution_commit_state),
          'execution_commit_ref', page_source.execution_commit_ref,
          'execution_committed_at_utc', page_source.execution_committed_at_utc
        )
        || jsonb_build_object(
          'rail_provider_snapshot', COALESCE(page_source.rail_provider_label, page_source.rail_provider_snapshot),
          'rail_env_snapshot', COALESCE(page_source.rail_env_label, page_source.rail_env_snapshot),
          'schedule_kind', page_source.schedule_kind,
          'scheduled_at_utc', page_source.scheduled_at_utc,
          'funding_account_ref', page_source.funding_account_ref,
          'total_bank_out', COALESCE(page_source.display_total_bank_out, page_source.total_bank_out, 0),
          'total_debt_created', COALESCE(page_source.total_debt_created, 0),
          'candidate_count', COALESCE(page_source.candidate_count, 0),
          'item_count', COALESCE(page_source.item_count, 0),
          'transfer_count', COALESCE(page_source.transfer_count, 0),
          'total_payable', COALESCE(page_source.total_payable, 0),
          'latest_operation_id', CASE WHEN page_source.latest_operation_id IS NULL THEN NULL::text ELSE page_source.latest_operation_id::text END,
          'latest_operation_status', page_source.latest_operation_status,
          'latest_operation_phase', page_source.latest_operation_phase,
          'active_payment_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_payment_operation_type', page_source.active_payment_operation_type,
          'active_payment_operation_status', page_source.active_payment_operation_status,
          'active_payment_operation_phase', page_source.active_payment_operation_phase,
          'active_payment_operation_runner_state', page_source.active_payment_operation_runner_state,
          'active_payment_operation_requires_user_action', page_source.active_payment_operation_requires_user_action,
          'active_payment_operation_resume_reason', page_source.active_payment_operation_resume_reason,
          'active_payment_operation_updated_at_utc', page_source.active_payment_operation_updated_at_utc,
          'active_payment_operation', page_source.active_payment_operation,
          'active_payment_execute_operation', page_source.active_payment_operation,
          'payment_execute_operation', page_source.active_payment_operation,
          'active_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_operation_type', page_source.active_payment_operation_type,
          'active_operation_status', page_source.active_payment_operation_status,
          'active_operation_phase', page_source.active_payment_operation_phase,
          'active_operation', page_source.active_payment_operation,
          'issue_summary_counts', COALESCE(page_source.issue_summary_counts, '{}'::jsonb),
          'stale_summary_json', COALESCE(page_source.stale_summary_json, '{}'::jsonb),
          'freshness_validation_status', COALESCE(page_source.display_freshness_validation_status, page_source.freshness_validation_status),
          'freshness_checked_at_utc', COALESCE(page_source.display_freshness_checked_at_utc, page_source.freshness_checked_at_utc),
          'freshness_result_hash', COALESCE(page_source.display_freshness_result_hash, page_source.freshness_result_hash),
          'summary_version', COALESCE(page_source.summary_version, 0),
          'summary_updated_at_utc', page_source.summary_updated_at_utc
        )
        || jsonb_build_object(
          'live_signal_version', page_source.live_signal_version,
          'payment_status_version', page_source.payment_status_version,
          'correction_progress_version', page_source.correction_progress_version,
          'alert_version', page_source.alert_version,
          'overview_version', page_source.overview_version,
          'last_status_hash', page_source.last_status_hash,
          'last_alert_hash', page_source.last_alert_hash,
          'last_changed_at_utc', page_source.last_changed_at_utc,
          'last_payment_status_changed_at_utc', page_source.last_payment_status_changed_at_utc,
          'last_correction_progress_changed_at_utc', page_source.last_correction_progress_changed_at_utc,
          'last_alert_changed_at_utc', page_source.last_alert_changed_at_utc,
          'last_change_reason', page_source.last_change_reason,
          'last_change_source', page_source.last_change_source,
          'last_change_scope_json', COALESCE(page_source.last_change_scope_json, '{}'::jsonb),
          'last_changed_candidate_ids', COALESCE(page_source.last_changed_candidate_ids, '[]'::jsonb),
          'last_changed_pay_batch_item_ids', COALESCE(page_source.last_changed_pay_batch_item_ids, '[]'::jsonb),
          'last_changed_transfer_ids', COALESCE(page_source.last_changed_transfer_ids, '[]'::jsonb),
          'draft_stale_hint', LOWER(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_hint', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'draft_stale_reason', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_reason', '')), ''),
          'draft_stale_policy_x_authority_scope', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'policy_x_authority_scope', '')), ''),
          'diagnostics_deferred', true,
          'diagnostics_included', false,
          'alerts_included', false,
          'correction_summary_included', v_include_correction_summary,
          'display_mode', v_display_mode
        )
      ) AS row_json
    FROM page_source
  )
  SELECT
    COALESCE(jsonb_agg(page_json.row_json ORDER BY page_json.row_ordinal), '[]'::jsonb),
    (SELECT COUNT(*)::integer FROM page_source)
  INTO
    v_rows,
    v_returned_count
  FROM page_json;

  v_returned_count := COALESCE(v_returned_count, 0);
  v_total_count := COALESCE(v_total_count, 0);
  v_has_more := (v_offset + v_returned_count) < v_total_count;
  v_next_offset := CASE WHEN v_has_more THEN v_offset + v_limit ELSE NULL::integer END;
  v_previous_offset := CASE WHEN v_offset > 0 THEN GREATEST(0, v_offset - v_limit) ELSE NULL::integer END;

  RETURN jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'display_mode', v_display_mode,
      'limit', v_limit,
      'offset', v_offset,
      'next_offset', v_next_offset,
      'previous_offset', v_previous_offset,
      'has_more', v_has_more,
      'returned_count', v_returned_count,
      'count', v_total_count,
      'total_count', v_total_count,
      'known_total_count', true,
      'rows', COALESCE(v_rows, '[]'::jsonb),
      'items', COALESCE(v_rows, '[]'::jsonb),
      'diagnostics_included', false,
      'diagnostics_requested', v_include_diagnostics,
      'alerts_requested', v_include_alerts,
      'correction_summary_requested', v_include_correction_summary
    )
    || jsonb_build_object(
      'banking_alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE NULL::text END,
      'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE NULL::text END,
      'banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'grouped_banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'banking_highest_alert_severity', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_severity, '') ELSE '' END,
      'banking_highest_alert_label', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_label, '') ELSE '' END,
      'banking_alerts', '[]'::jsonb,
      'banking_alert_summary', jsonb_build_object(
        'ok', true,
        'cached', true,
        'alerts', '[]'::jsonb,
        'unacknowledged_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
        'highest_severity', CASE WHEN v_include_alerts THEN v_cached_highest_severity ELSE NULL::text END,
        'highest_label', CASE WHEN v_include_alerts THEN v_cached_highest_label ELSE NULL::text END,
        'alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE 'banking_alert_signal:v3:' || MD5('') END,
        'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE 'banking_alert_summary:v3:' || MD5('') END,
        'summary_json', CASE WHEN v_include_alerts THEN COALESCE(v_cached_alert_summary, '{}'::jsonb) ELSE '{}'::jsonb END
      )
    )
  );
END;
$function$;

-- pay_build_batch_artifacts_from_preview(date,date,uuid,jsonb,jsonb,uuid,uuid,bigint,uuid,jsonb,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_build_batch_artifacts_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_preview_payload_json jsonb, p_selected_preview_row_ids jsonb DEFAULT '[]'::jsonb, p_source_workbench_session_id uuid DEFAULT NULL::uuid, p_source_snapshot_run_id uuid DEFAULT NULL::uuid, p_source_session_version bigint DEFAULT NULL::bigint, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb, p_existing_pay_batch_id uuid DEFAULT NULL::uuid, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := NULL::text;
  v_insert_candidates_json jsonb := '{}'::jsonb;
  v_insert_items_json jsonb := '{}'::jsonb;
  v_finance_json jsonb := '{}'::jsonb;
  v_operation_scope_count integer := 0;
  v_operation_distinct_scope_count integer := 0;
  v_operation_stage_context_json jsonb := '{}'::jsonb;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_pay_batch public.pay_batches%ROWTYPE;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_PAY_DATE_REQUIRED' USING ERRCODE = '22004';
  END IF;

  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_WEEK_ENDING_CUTOFF_REQUIRED' USING ERRCODE = '22004';
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_LEGACY_UNCHUNKED_DISABLED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_LEGACY_UNCHUNKED_DISABLED',
              'message', 'Legacy all-at-once draft artifact creation is permanently disabled. Use the phased DRAFT_CREATE operation runner.'
            )::text;
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_OPERATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_OPERATION_REQUIRED',
              'message', 'Draft artifacts may only be created by an operation-scoped DRAFT_CREATE operation.'
            )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_ACTOR_REQUIRED' USING ERRCODE = 'P0001';
  END IF;

  IF p_existing_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_BATCH_REQUIRED' USING ERRCODE = 'P0001';
  END IF;

  IF p_candidate_scope_ids IS NULL
     OR jsonb_typeof(p_candidate_scope_ids) <> 'array'
     OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_REQUIRED',
              'message', 'A non-empty candidate-scope array is required.'
            )::text;
  END IF;

  IF jsonb_array_length(p_candidate_scope_ids) > 100 THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_LIMIT_EXCEEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_LIMIT_EXCEEDED',
              'scope_count', jsonb_array_length(p_candidate_scope_ids),
              'maximum_scope_count', 100
            )::text;
  END IF;

  SELECT COUNT(DISTINCT BTRIM(scope_id.value))::integer
  INTO v_operation_distinct_scope_count
  FROM jsonb_array_elements_text(p_candidate_scope_ids) AS scope_id(value)
  WHERE BTRIM(scope_id.value) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF v_operation_distinct_scope_count IS DISTINCT FROM jsonb_array_length(p_candidate_scope_ids) THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_INVALID',
              'supplied_scope_count', jsonb_array_length(p_candidate_scope_ids),
              'distinct_valid_scope_count', COALESCE(v_operation_distinct_scope_count, 0),
              'message', 'Candidate-scope identifiers must be valid and unique UUID values.'
            )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE OF operation_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_OPERATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) <> 'DRAFT_CREATE'
     OR UPPER(BTRIM(COALESCE(v_operation_row.status, ''))) <> 'RUNNING'
     OR UPPER(BTRIM(COALESCE(v_operation_row.phase, ''))) <> 'INSERT_ITEMS'
     OR v_operation_row.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_OPERATION_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_OPERATION_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'operation_type', v_operation_row.operation_type,
              'operation_status', v_operation_row.status,
              'operation_phase', v_operation_row.phase,
              'operation_actor_user_id', CASE WHEN v_operation_row.actor_user_id IS NULL THEN NULL ELSE v_operation_row.actor_user_id::text END,
              'supplied_actor_user_id', p_actor_user_id::text,
              'workbench_session_id', CASE WHEN v_operation_row.workbench_session_id IS NULL THEN NULL ELSE v_operation_row.workbench_session_id::text END,
              'message', 'The operation is not the active INSERT_ITEMS DRAFT_CREATE operation for this actor and Workbench session.'
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_operation_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_operation_row.workbench_session_id
  FOR UPDATE OF session_row;

  IF NOT FOUND
     OR UPPER(BTRIM(COALESCE(v_operation_session.status, ''))) <> 'OPEN'
     OR v_operation_session.discarded_at_utc IS NOT NULL
     OR v_operation_session.replacement_session_id IS NOT NULL
     OR v_operation_session.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation_session.pay_date IS DISTINCT FROM p_pay_date
     OR v_operation_session.week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff
     OR (p_source_workbench_session_id IS NOT NULL AND p_source_workbench_session_id IS DISTINCT FROM v_operation_session.id)
     OR (p_source_snapshot_run_id IS NOT NULL AND p_source_snapshot_run_id IS DISTINCT FROM v_operation_session.source_snapshot_run_id)
     OR (p_source_session_version IS NOT NULL AND p_source_session_version IS DISTINCT FROM v_operation_session.version) THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_WORKBENCH_SESSION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_WORKBENCH_SESSION_STALE',
              'operation_id', p_operation_id::text,
              'workbench_session_id', v_operation_row.workbench_session_id::text,
              'expected_pay_date', v_operation_session.pay_date::text,
              'supplied_pay_date', p_pay_date::text,
              'expected_week_ending_cutoff', v_operation_session.week_ending_cutoff::text,
              'supplied_week_ending_cutoff', p_week_ending_cutoff::text,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH'
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.id IN (
    SELECT BTRIM(scope_id.value)::uuid
    FROM jsonb_array_elements_text(p_candidate_scope_ids) AS scope_id(value)
  )
  ORDER BY scope_row.id
  FOR UPDATE OF scope_row;

  SELECT COUNT(*)::integer,
         MIN(UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))))
  INTO v_operation_scope_count, v_scope
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.id IN (
    SELECT BTRIM(scope_id.value)::uuid
    FROM jsonb_array_elements_text(p_candidate_scope_ids) AS scope_id(value)
  )
    AND scope_row.operation_id = p_operation_id
    AND scope_row.workbench_session_id = v_operation_row.workbench_session_id
    AND scope_row.pay_batch_id = p_existing_pay_batch_id
    AND scope_row.source_session_version IS NOT DISTINCT FROM v_operation_session.version
    AND scope_row.source_snapshot_run_id IS NOT DISTINCT FROM v_operation_session.source_snapshot_run_id
    AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('SCOPED', 'ALLOCATED', 'DRAFTED')
    AND UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) IN ('PAYE', 'UMBRELLA');

  IF v_operation_scope_count IS DISTINCT FROM jsonb_array_length(p_candidate_scope_ids)
     OR v_scope NOT IN ('PAYE', 'UMBRELLA')
     OR (
       SELECT COUNT(DISTINCT UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))))
       FROM public.banking_pay_operation_candidate_scope AS scope_row
       WHERE scope_row.id IN (
         SELECT BTRIM(scope_id.value)::uuid
         FROM jsonb_array_elements_text(p_candidate_scope_ids) AS scope_id(value)
       )
     ) IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_SCOPE_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_existing_pay_batch_id::text,
              'expected_scope_count', jsonb_array_length(p_candidate_scope_ids),
              'matched_scope_count', COALESCE(v_operation_scope_count, 0),
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH'
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_operation_pay_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_existing_pay_batch_id
  FOR UPDATE OF batch_row;

  IF NOT FOUND
     OR UPPER(BTRIM(COALESCE(v_operation_pay_batch.status, ''))) <> 'DRAFT'
     OR UPPER(BTRIM(COALESCE(v_operation_pay_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR v_operation_pay_batch.source_workbench_session_id IS DISTINCT FROM v_operation_row.workbench_session_id
     OR v_operation_pay_batch.source_snapshot_run_id IS DISTINCT FROM v_operation_session.source_snapshot_run_id
     OR v_operation_pay_batch.source_session_version IS DISTINCT FROM v_operation_session.version
     OR (p_pay_date IS NOT NULL AND v_operation_pay_batch.pay_date IS DISTINCT FROM p_pay_date) THEN
    RAISE EXCEPTION 'PAY_BUILD_BATCH_ARTIFACTS_BATCH_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BUILD_BATCH_ARTIFACTS_BATCH_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'pay_batch_id', p_existing_pay_batch_id::text,
              'refresh_required', true,
              'next_action', 'REFRESH_WORKBENCH'
            )::text;
  END IF;

  SELECT to_jsonb(stage_context_row)
  INTO v_operation_stage_context_json
  FROM public.pay_batch_stage_operation_candidate_chunk_context(
    p_operation_id,
    p_existing_pay_batch_id,
    p_candidate_scope_ids,
    p_actor_user_id
  ) AS stage_context_row;

  v_insert_candidates_json := public.pay_batch_insert_candidates_from_preview(
    p_existing_pay_batch_id,
    p_actor_user_id,
    p_operation_id,
    p_candidate_scope_ids
  );

  v_insert_items_json := public.pay_batch_insert_items_from_preview(
    p_existing_pay_batch_id,
    p_actor_user_id,
    p_operation_id,
    p_candidate_scope_ids
  );

  v_finance_json := public.pay_batch_apply_finance_adjustments(
    p_existing_pay_batch_id,
    v_scope,
    p_actor_user_id,
    NULL::numeric,
    NULL::date,
    p_operation_id,
    p_candidate_scope_ids
  );

  RETURN jsonb_build_object(
    'ok', true,
    'operation_mode', true,
    'pay_batch_id', p_existing_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'workbench_session_id', v_operation_row.workbench_session_id::text,
    'candidate_scope_count', v_operation_scope_count,
    'pay_channel_scope', v_scope,
    'stages', jsonb_build_object(
      'stage_context', COALESCE(v_operation_stage_context_json, '{}'::jsonb),
      'insert_candidates', COALESCE(v_insert_candidates_json, '{}'::jsonb),
      'insert_items', COALESCE(v_insert_items_json, '{}'::jsonb),
      'finance_adjustments', COALESCE(v_finance_json, '{}'::jsonb)
    )
  );
END;
$function$;

-- pay_candidate_advances_report(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_candidate_advances_report(p_candidate_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_week_start date := public._pay_week_start_monday(v_today_uk);
  v_week_end date := (public._pay_week_start_monday(v_today_uk) + 6);

  v_candidate record;
  v_paid_wtd numeric := 0;
  v_rows jsonb := '[]'::jsonb;
  v_payment_advances jsonb := '[]'::jsonb;
  v_overpayments jsonb := '[]'::jsonb;
  v_underpayments jsonb := '[]'::jsonb;
  v_manual_debt_adjustments jsonb := '[]'::jsonb;
  v_manual_credit_adjustments jsonb := '[]'::jsonb;
  v_snoozed_deferred_items jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CANDIDATE_ADVANCES_REPORT',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_candidate_advances_report: candidate_id is required'
    )::text;
  end if;

  select
    c.id,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.active
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CANDIDATE_ADVANCES_REPORT',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_candidate_advances_report: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  select
    round(
      coalesce(
        sum(
          case
            when pbc.net_bank_amount is not null then pbc.net_bank_amount
            when pbc.gross_preview is not null then pbc.gross_preview
            else 0
          end
        ),
        0
      ),
      2
    )
  into v_paid_wtd
  from public.pay_batch_candidates pbc
  join public.pay_batches pb
    on pb.id = pbc.pay_batch_id
  where pbc.candidate_id = p_candidate_id
    and pb.pay_date >= v_week_start
    and pb.pay_date <= v_week_end
    and upper(coalesce(pb.status::text, '')) <> 'CANCELLED';

  with finance_rows as (
    select
      case
        when vfc.active_snooze_id is not null then 'SNOOZED_DEFERRED'
        else vfc.case_type::text
      end as row_group,
      'FINANCE_CASE'::text as row_kind,
      vfc.finance_case_id,
      vfc.case_type::text as case_type,
      vfc.candidate_id,
      vfc.candidate_tms_ref,
      vfc.candidate_display_name,
      vfc.client_id,
      vfc.client_name,
      vfc.linked_timesheet_id,
      vfc.linked_shift_date,
      vfc.created_at,
      vfc.start_week_start,
      vfc.next_due_week_start,
      round(coalesce(vfc.original_amount, 0), 2)::numeric(12,2) as original_amount,
      round(
        case
          when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 0
          else greatest(coalesce(vfc.original_amount, 0) - coalesce(vfc.outstanding_amount, 0), 0)
        end,
        2
      )::numeric(12,2) as recovered_total,
      round(coalesce(vfc.outstanding_amount, 0), 2)::numeric(12,2) as remaining_outstanding,
      round(
        case
          when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
           and vfc.next_due_week_start is not null
           and vfc.next_due_week_start <= v_week_start
           and coalesce(vfc.written_off_at_utc, null) is null
           and coalesce(vfc.cleared_at_utc, null) is null
           and upper(coalesce(vfc.status::text, '')) not in ('PAID_OFF', 'CLEARED')
          then least(coalesce(vfc.weekly_due, 0), coalesce(vfc.outstanding_amount, 0))
          else 0
        end,
        2
      )::numeric(12,2) as due_this_week,
      vfc.status::text as status,
      vfc.payout_status::text as payout_status,
      vfc.reason::text as reason,
      vfc.notes,
      vfc.adjustment_comment,
      vfc.source_original_paid_amount,
      vfc.source_corrected_paid_amount,
      vfc.minimum_earnings_threshold,
      vfc.take_home_floor_override,
      vfc.active_snooze_id,
      vfc.active_snooze_kind,
      vfc.active_snooze_until_date,
      vfc.active_snooze_note,
      case
        when vfc.active_snooze_id is null then 'NONE'
        when vfc.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      case
        when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
        when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status::text, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'CLEARED'
        when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RESERVED'
        when coalesce(vfc.committed_amount, 0) > 0 then 'COMMITTED'
        when coalesce(vfc.settled_amount, 0) > 0 then 'SETTLED'
        when vfc.active_snooze_id is not null then 'SNOOZED'
        else upper(coalesce(vfc.status::text, 'ACTIVE'))
      end as lifecycle_state,
      case
        when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_CREDIT_ADJUSTMENT') then coalesce(pbp.authoritative_payment_date, pbp.pay_date)
        else coalesce(pbr.authoritative_payment_date, pbr.pay_date)
      end as authoritative_payment_date,
      case
        when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfc.payout_status::text, 'NOT_PAID')
        when vfc.case_type = 'PAYMENT_ADVANCE' then
          case
            when coalesce(vfc.payout_status::text, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) > 0 then 'RECOVERY_ACTIVE'
            when coalesce(vfc.payout_status::text, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            else coalesce(vfc.payout_status::text, 'NOT_PAID')
          end
        when vfc.case_type in ('OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT') then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status::text, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RECOVERY_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'RECOVERY_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'RECOVERY_SETTLED'
            else 'RECOVERY_ACTIVE'
          end
        when vfc.case_type = 'UNDERPAYMENT' then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status::text, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'PAYOUT_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'PAYOUT_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'PAYOUT_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'PAYOUT_SETTLED'
            else 'PAYOUT_ACTIVE'
          end
        else coalesce(vfc.status::text, 'ACTIVE')
      end as payout_or_recovery_status,
      coalesce(vfc.is_mixed_case, false) as is_mixed_case,
      coalesce(vfc.open_taxable_count, 0) as open_taxable_count,
      coalesce(vfc.open_reimbursement_count, 0) as open_reimbursement_count,
      coalesce(vfc.unresolved_taxable_count, 0) as unresolved_taxable_count,
      coalesce(vfc.stale_count, 0) as stale_count,
      coalesce(vfc.component_resolution_summary_json, '{}'::jsonb) as component_resolution_summary_json
    from public.v_finance_cases_register vfc
    left join public.pay_batches pbp
      on pbp.id = vfc.payout_pay_batch_id
    left join public.pay_batches pbr
      on pbr.id = vfc.latest_recovery_pay_batch_id
    where vfc.candidate_id = p_candidate_id
  ),
  snoozed_timesheet_rows as (
    select
      'SNOOZED_DEFERRED'::text as row_group,
      'TIMESHEET_SNOOZE'::text as row_kind,
      null::uuid as finance_case_id,
      null::text as case_type,
      c.id as candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      cli.id as client_id,
      cli.name as client_name,
      s.timesheet_id as linked_timesheet_id,
      null::date as linked_shift_date,
      s.created_at_utc as created_at,
      null::date as start_week_start,
      null::date as next_due_week_start,
      0::numeric(12,2) as original_amount,
      0::numeric(12,2) as recovered_total,
      0::numeric(12,2) as remaining_outstanding,
      0::numeric(12,2) as due_this_week,
      null::text as status,
      null::text as payout_status,
      null::text as reason,
      null::text as notes,
      null::text as adjustment_comment,
      null::numeric as source_original_paid_amount,
      null::numeric as source_corrected_paid_amount,
      null::numeric as minimum_earnings_threshold,
      null::numeric as take_home_floor_override,
      s.id as active_snooze_id,
      upper(coalesce(s.snooze_kind, '')) as active_snooze_kind,
      s.snooze_until_date as active_snooze_until_date,
      s.note as active_snooze_note,
      case
        when s.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      'SNOOZED'::text as lifecycle_state,
      null::date as authoritative_payment_date,
      'DEFERRED'::text as payout_or_recovery_status,
      false as is_mixed_case,
      0::integer as open_taxable_count,
      0::integer as open_reimbursement_count,
      0::integer as unresolved_taxable_count,
      0::integer as stale_count,
      '{}'::jsonb as component_resolution_summary_json
    from public.pay_item_snoozes s
    join public.timesheets ts
      on ts.timesheet_id = s.timesheet_id
    join public.candidates c
      on c.id = s.candidate_id
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cli
      on cli.id = ct.client_id
    where s.cleared_at_utc is null
      and s.candidate_id = p_candidate_id
      and s.timesheet_id is not null
      and s.source_ref is null
      and (
        upper(coalesce(s.snooze_kind, '')) in ('TIMESHEET_PAYMENT', 'BLOCKED_TIMESHEET', 'DO_NOT_PAY')
        or upper(coalesce(s.snooze_kind, '')) like 'TIMESHEET%'
      )
  ),
  all_rows as (
    select * from finance_rows
    union all
    select * from snoozed_timesheet_rows
  ),
  wtd_recovery_by_case_type as (
    with settled_items as (
      select
        coalesce(pbi.finance_case_id, replace(pbi.source_ref, 'advance:', '')::uuid) as finance_case_id,
        pbi.item_type,
        round(sum(abs(coalesce(pbi.amount_ex_vat, 0))), 2)::numeric(12,2) as recovered_wtd
      from public.pay_batch_candidates pbc
      join public.pay_batches pb
        on pb.id = pbc.pay_batch_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      where pbc.candidate_id = p_candidate_id
        and pb.pay_date >= v_week_start
        and pb.pay_date <= v_week_end
        and upper(coalesce(pb.status::text, '')) <> 'CANCELLED'
        and pbc.settled_at_utc is not null
        and upper(coalesce(pbc.settlement_status, '')) = 'SETTLED'
        and coalesce(pbi.is_voided, false) = false
        and (
          pbi.finance_case_id is not null
          or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
        )
      group by coalesce(pbi.finance_case_id, replace(pbi.source_ref, 'advance:', '')::uuid), pbi.item_type
    )
    select
      ar.finance_case_id,
      round(coalesce(sum(si.recovered_wtd), 0), 2)::numeric(12,2) as recovered_wtd
    from all_rows ar
    left join settled_items si
      on si.finance_case_id = ar.finance_case_id
    where ar.finance_case_id is not null
    group by ar.finance_case_id
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'row_group', ar.row_group,
          'row_kind', ar.row_kind,
          'finance_case_id', case when ar.finance_case_id is null then null else ar.finance_case_id::text end,
          'case_type', ar.case_type,
          'candidate_id', ar.candidate_id::text,
          'candidate_tms_ref', ar.candidate_tms_ref,
          'candidate_display_name', ar.candidate_display_name,
          'client_id', case when ar.client_id is null then null else ar.client_id::text end,
          'client_name', ar.client_name,
          'linked_timesheet_id', case when ar.linked_timesheet_id is null then null else ar.linked_timesheet_id::text end,
          'created_at', case when ar.created_at is null then null else ar.created_at::text end,
          'start_week_start', case when ar.start_week_start is null then null else ar.start_week_start::text end,
          'next_due_week_start', case when ar.next_due_week_start is null then null else ar.next_due_week_start::text end,
          'original_amount', ar.original_amount,
          'recovered_total', ar.recovered_total,
          'recovered_wtd', coalesce(wr.recovered_wtd, 0),
          'remaining_outstanding', ar.remaining_outstanding,
          'due_this_week', ar.due_this_week,
          'status', ar.status,
          'payout_status', ar.payout_status,
          'reason', ar.reason,
          'notes', ar.notes,
          'adjustment_comment', ar.adjustment_comment,
          'source_original_paid_amount', ar.source_original_paid_amount,
          'source_corrected_paid_amount', ar.source_corrected_paid_amount,
          'minimum_earnings_threshold', ar.minimum_earnings_threshold,
          'take_home_floor_override', ar.take_home_floor_override,
          'active_snooze_id', case when ar.active_snooze_id is null then null else ar.active_snooze_id::text end,
          'active_snooze_kind', ar.active_snooze_kind,
          'active_snooze_until_date', case when ar.active_snooze_until_date is null then null else ar.active_snooze_until_date::text end,
          'active_snooze_note', ar.active_snooze_note,
          'snooze_status', ar.snooze_status,
          'lifecycle_state', ar.lifecycle_state,
          'authoritative_payment_date', case when ar.authoritative_payment_date is null then null else ar.authoritative_payment_date::text end,
          'payout_or_recovery_status', ar.payout_or_recovery_status,
          'is_mixed_case', ar.is_mixed_case,
          'open_taxable_count', ar.open_taxable_count,
          'open_reimbursement_count', ar.open_reimbursement_count,
          'unresolved_taxable_count', ar.unresolved_taxable_count,
          'stale_count', ar.stale_count,
          'component_resolution_summary_json', coalesce(ar.component_resolution_summary_json, '{}'::jsonb)
        )
        order by ar.created_at desc nulls last, ar.finance_case_id asc nulls last, ar.linked_timesheet_id asc nulls last
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'paid_wtd', round(coalesce(v_paid_wtd, 0), 2)::numeric(12,2),
      'counts_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', count(*) filter (where ar.row_group = 'PAYMENT_ADVANCE'),
        'OVERPAYMENT', count(*) filter (where ar.row_group = 'OVERPAYMENT'),
        'UNDERPAYMENT', count(*) filter (where ar.row_group = 'UNDERPAYMENT'),
        'MANUAL_DEBT_ADJUSTMENT', count(*) filter (where ar.row_group = 'MANUAL_DEBT_ADJUSTMENT'),
        'MANUAL_CREDIT_ADJUSTMENT', count(*) filter (where ar.row_group = 'MANUAL_CREDIT_ADJUSTMENT'),
        'SNOOZED_DEFERRED', count(*) filter (where ar.row_group = 'SNOOZED_DEFERRED')
      ),
      'totals_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', round(coalesce(sum(case when ar.row_group = 'PAYMENT_ADVANCE' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'OVERPAYMENT', round(coalesce(sum(case when ar.row_group = 'OVERPAYMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'UNDERPAYMENT', round(coalesce(sum(case when ar.row_group = 'UNDERPAYMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_DEBT_ADJUSTMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_CREDIT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_CREDIT_ADJUSTMENT' then ar.original_amount else 0 end), 0), 2)::numeric(12,2),
        'SNOOZED_DEFERRED', round(coalesce(sum(case when ar.row_group = 'SNOOZED_DEFERRED' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2)
      ),
      'recovered_wtd_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', round(coalesce(sum(case when ar.row_group = 'PAYMENT_ADVANCE' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'OVERPAYMENT', round(coalesce(sum(case when ar.row_group = 'OVERPAYMENT' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'UNDERPAYMENT', 0::numeric(12,2),
        'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_CREDIT_ADJUSTMENT', 0::numeric(12,2),
        'SNOOZED_DEFERRED', 0::numeric(12,2)
      ),
      'component_totals', jsonb_build_object(
        'mixed_case_count', count(*) filter (where ar.is_mixed_case = true),
        'open_taxable_count_total', coalesce(sum(ar.open_taxable_count), 0),
        'open_reimbursement_count_total', coalesce(sum(ar.open_reimbursement_count), 0),
        'unresolved_taxable_count_total', coalesce(sum(ar.unresolved_taxable_count), 0),
        'stale_count_total', coalesce(sum(ar.stale_count), 0)
      )
    )
  into
    v_rows,
    v_summary
  from all_rows ar
  left join wtd_recovery_by_case_type wr
    on wr.finance_case_id = ar.finance_case_id;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'PAYMENT_ADVANCE'),
    '[]'::jsonb
  ) into v_payment_advances;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'OVERPAYMENT'),
    '[]'::jsonb
  ) into v_overpayments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'UNDERPAYMENT'),
    '[]'::jsonb
  ) into v_underpayments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'),
    '[]'::jsonb
  ) into v_manual_debt_adjustments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'),
    '[]'::jsonb
  ) into v_manual_credit_adjustments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'SNOOZED_DEFERRED'),
    '[]'::jsonb
  ) into v_snoozed_deferred_items;

  return jsonb_build_object(
    'ok', true,
    'candidate', jsonb_build_object(
      'id', v_candidate.id::text,
      'tms_ref', v_candidate.tms_ref,
      'display_name', v_candidate.display_name,
      'first_name', v_candidate.first_name,
      'last_name', v_candidate.last_name,
      'active', v_candidate.active
    ),
    'week_start', v_week_start::text,
    'week_end', v_week_end::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'payment_advances', coalesce(v_payment_advances, '[]'::jsonb),
    'overpayments', coalesce(v_overpayments, '[]'::jsonb),
    'underpayments', coalesce(v_underpayments, '[]'::jsonb),
    'manual_debt_adjustments', coalesce(v_manual_debt_adjustments, '[]'::jsonb),
    'manual_credit_adjustments', coalesce(v_manual_credit_adjustments, '[]'::jsonb),
    'snoozed_deferred_items', coalesce(v_snoozed_deferred_items, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$function$;

-- pay_correction_chain_residual_v1(uuid,uuid,text,uuid,uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_correction_chain_residual_v1(p_timesheet_id uuid, p_candidate_id uuid, p_target_pay_method text, p_workbench_session_id uuid DEFAULT NULL::uuid, p_exclude_pay_batch_id uuid DEFAULT NULL::uuid, p_max_components integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
DECLARE
  v_target_pay_method text :=
    UPPER(BTRIM(COALESCE(p_target_pay_method, '')));

  v_chain jsonb;
  v_root_timesheet_id uuid;
  v_correction_financials_policy_envelope jsonb;
  v_correction_financials_policy_envelope_fingerprint text;
  v_latest_positive_timesheet_id uuid;
  v_member_ids uuid[] := ARRAY[]::uuid[];
  v_member_count integer := 0;

  v_chain_candidate_id uuid;
  v_chain_client_id uuid;
  v_source_family_key text;
  v_source_pay_methods jsonb := '[]'::jsonb;
  v_distinct_candidate_count integer := 0;
  v_distinct_client_count integer := 0;
  v_source_pay_method_count integer := 0;
  v_mismatched_source_method_count integer := 0;
  v_anchor_mismatch_count integer := 0;

  v_component_count integer := 0;
  v_components jsonb := '[]'::jsonb;
  v_total_raw_ex numeric := 0;
  v_total_effective_ex numeric := 0;
  v_total_raw_inc numeric := 0;
  v_total_effective_inc numeric := 0;
  v_resolution_required_count integer := 0;
  v_unresolved_count integer := 0;
  v_reservation_overrun_count integer := 0;
  v_draftable boolean := false;
  v_residual_fingerprint text;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_TIMESHEET_ID_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_target_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_TARGET_PAY_METHOD_INVALID'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'target_pay_method', v_target_pay_method,
              'allowed', jsonb_build_array('PAYE', 'UMBRELLA')
            )::text;
  END IF;

  IF p_max_components < 1 OR p_max_components > 100 THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_MAX_COMPONENTS_OUT_OF_RANGE'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'min', 1,
              'max', 100,
              'supplied', p_max_components
            )::text;
  END IF;

  v_chain := public.timesheet_correction_chain_scope_v1(
    p_timesheet_id,
    false,
    32,
    100
  );

  IF COALESCE((v_chain ->> 'valid')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_CHAIN_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'chain', v_chain
            )::text;
  END IF;

  v_root_timesheet_id :=
    NULLIF(v_chain ->> 'root_timesheet_id', '')::uuid;


  -- A residual can span more than one correction operation. Each operation
  -- keeps its own two-leg envelope; the chain fingerprint freezes the ordered
  -- catalogue without forcing later corrections to reuse an earlier policy.
  v_correction_financials_policy_envelope := jsonb_build_object(
    'correction_units', COALESCE(v_chain -> 'correction_units', '[]'::jsonb),
    'chain_fingerprint', v_chain ->> 'chain_fingerprint'
  );
  v_correction_financials_policy_envelope_fingerprint :=
    NULLIF(v_chain ->> 'chain_fingerprint', '');

  IF jsonb_array_length(COALESCE(v_chain -> 'correction_units', '[]'::jsonb)) < 1
     OR v_correction_financials_policy_envelope_fingerprint IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_CORRECTION_FINANCIALS_POLICY_ENVELOPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'root_timesheet_id', v_root_timesheet_id::text,
              'chain_errors', COALESCE(v_chain -> 'errors', '[]'::jsonb)
            )::text;
  END IF;

  v_latest_positive_timesheet_id :=
    NULLIF(v_chain ->> 'latest_positive_timesheet_id', '')::uuid;

  SELECT COALESCE(
    array_agg(member_text::uuid ORDER BY member_text::uuid),
    ARRAY[]::uuid[]
  )
  INTO v_member_ids
  FROM jsonb_array_elements_text(
    COALESCE(v_chain -> 'member_timesheet_ids', '[]'::jsonb)
  ) AS chain_member(member_text);

  v_member_count := cardinality(v_member_ids);

  IF v_member_count < 1 OR v_member_count > 100 THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_MEMBER_COUNT_OUT_OF_RANGE'
      USING ERRCODE = '54001',
            DETAIL = jsonb_build_object(
              'member_count', v_member_count,
              'max', 100
            )::text;
  END IF;

  SELECT
    min(financial_row.candidate_id::text)::uuid,
    min(financial_row.client_id::text)::uuid,
    count(DISTINCT financial_row.candidate_id)
      FILTER (WHERE financial_row.candidate_id IS NOT NULL)::integer,
    count(DISTINCT financial_row.client_id)
      FILTER (WHERE financial_row.client_id IS NOT NULL)::integer,
    COALESCE(
      jsonb_agg(
        DISTINCT UPPER(BTRIM(financial_row.pay_method))
        ORDER BY UPPER(BTRIM(financial_row.pay_method))
      ) FILTER (
        WHERE NULLIF(BTRIM(COALESCE(financial_row.pay_method, '')), '')
          IS NOT NULL
      ),
      '[]'::jsonb
    ),
    count(DISTINCT UPPER(BTRIM(financial_row.pay_method)))
      FILTER (
        WHERE NULLIF(BTRIM(COALESCE(financial_row.pay_method, '')), '')
          IS NOT NULL
      )::integer,
    count(DISTINCT UPPER(BTRIM(financial_row.pay_method)))
      FILTER (
        WHERE NULLIF(BTRIM(COALESCE(financial_row.pay_method, '')), '')
          IS NOT NULL
          AND UPPER(BTRIM(financial_row.pay_method))
              IS DISTINCT FROM v_target_pay_method
      )::integer
  INTO
    v_chain_candidate_id,
    v_chain_client_id,
    v_distinct_candidate_count,
    v_distinct_client_count,
    v_source_pay_methods,
    v_source_pay_method_count,
    v_mismatched_source_method_count
  FROM public.timesheets_financials AS financial_row
  WHERE financial_row.timesheet_id = ANY(v_member_ids)
    AND financial_row.is_current = true;

  IF v_distinct_candidate_count <> 1
     OR v_distinct_client_count <> 1 THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_CHAIN_IDENTITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'distinct_candidate_count', v_distinct_candidate_count,
              'distinct_client_count', v_distinct_client_count
            )::text;
  END IF;

  IF v_chain_candidate_id IS DISTINCT FROM p_candidate_id THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_CANDIDATE_MISMATCH'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'expected_candidate_id', p_candidate_id::text,
              'actual_candidate_id', CASE
                WHEN v_chain_candidate_id IS NULL THEN NULL
                ELSE v_chain_candidate_id::text
              END
            )::text;
  END IF;

  IF v_source_pay_method_count < 1 THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_SOURCE_PAY_METHOD_MISSING'
      USING ERRCODE = 'P0001';
  END IF;


  SELECT count(*)::integer
  INTO v_anchor_mismatch_count
  FROM public.timesheets AS correction_member
  LEFT JOIN LATERAL (
    SELECT financial_row.*
    FROM public.timesheets_financials AS financial_row
    WHERE financial_row.timesheet_id = correction_member.timesheet_id
      AND financial_row.is_current = true
    ORDER BY financial_row.computed_at_utc DESC, financial_row.id DESC
    LIMIT 1
  ) AS current_financial
    ON true
  LEFT JOIN LATERAL (
    SELECT public._ctms_correction_policy_leg_read_v1(
      correction_member.timesheet_id
    ) AS expected_leg
  ) AS policy_leg ON true
  WHERE correction_member.timesheet_id = ANY(v_member_ids)
    AND UPPER(BTRIM(COALESCE(correction_member.correction_kind, '')))
        IN ('CHANGED_HOURS_REVERSAL', 'CHANGED_HOURS_REPLACEMENT',
            'CANCELLATION_REVERSAL', 'CANCELLATION_REPLACEMENT')
    AND (
      current_financial.id IS NULL
      OR COALESCE(
           current_financial.policy_snapshot_json ->>
             'correction_financials_policy_envelope_fingerprint',
           current_financial.policy_snapshot_json #>>
             '{correction_financials_policy_envelope,envelope_fingerprint}',
           current_financial.rate_source_refs_json ->>
             'correction_financials_policy_envelope_fingerprint',
           current_financial.rate_source_refs_json #>>
             '{correction_financials_policy_envelope,envelope_fingerprint}'
         ) IS DISTINCT FROM policy_leg.expected_leg ->> 'envelope_fingerprint'
      OR COALESCE(
           current_financial.policy_snapshot_json ->> 'correction_leg_fingerprint',
           current_financial.rate_source_refs_json ->> 'correction_leg_fingerprint'
         ) IS DISTINCT FROM policy_leg.expected_leg ->> 'leg_fingerprint'
      OR COALESCE(
           current_financial.policy_snapshot_json ->> 'correction_tsfin_policy_fingerprint',
           current_financial.rate_source_refs_json ->> 'correction_tsfin_policy_fingerprint'
         ) IS DISTINCT FROM policy_leg.expected_leg #>>
           '{tsfin_policy,tsfin_policy_fingerprint}'
      OR COALESCE(
           current_financial.policy_snapshot_json ->> 'correction_invoice_policy_fingerprint',
           current_financial.rate_source_refs_json ->> 'correction_invoice_policy_fingerprint'
         ) IS DISTINCT FROM policy_leg.expected_leg #>>
           '{invoice_policy,invoice_policy_fingerprint}'
      OR CASE
           WHEN COALESCE(
                  current_financial.policy_snapshot_json ->> 'erni_pct',
                  ''
                ) ~ '^-?[0-9]+([.][0-9]+)?$'
            AND COALESCE(
                  policy_leg.expected_leg #>> '{tsfin_policy,erni_pct}',
                  ''
                ) ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN (current_financial.policy_snapshot_json ->> 'erni_pct')::numeric
                  IS DISTINCT FROM
                   (policy_leg.expected_leg #>> '{tsfin_policy,erni_pct}')::numeric
           ELSE true
         END
      OR NULLIF(UPPER(BTRIM(COALESCE(
           current_financial.policy_snapshot_json ->> 'apply_erni_to',
           ''
         ))), '') IS DISTINCT FROM
         NULLIF(UPPER(BTRIM(COALESCE(
           policy_leg.expected_leg #>> '{tsfin_policy,apply_erni_to}',
           ''
         ))), '')
      OR COALESCE(
           current_financial.pay_vat_rate_pct_snapshot,
           CASE
             WHEN COALESCE(
                    current_financial.policy_snapshot_json ->> 'vat_rate_pct',
                    ''
                  ) ~ '^-?[0-9]+([.][0-9]+)?$'
               THEN (current_financial.policy_snapshot_json ->>
                       'vat_rate_pct')::numeric
             ELSE NULL::numeric
           END
         ) IS DISTINCT FROM
         CASE
           WHEN COALESCE(
                   policy_leg.expected_leg #>> '{tsfin_policy,applied_pay_vat_rate_pct}',
                  ''
                ) ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN (policy_leg.expected_leg #>>
                     '{tsfin_policy,applied_pay_vat_rate_pct}')::numeric
           ELSE NULL::numeric
         END
    );

  IF v_anchor_mismatch_count > 0 THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_TSFIN_ANCHOR_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'root_timesheet_id', v_root_timesheet_id::text,
              'expected_chain_policy_fingerprint',
                v_correction_financials_policy_envelope_fingerprint,
              'mismatching_correction_member_count',
                v_anchor_mismatch_count
            )::text;
  END IF;

  v_source_family_key :=
    'correction-chain:' || v_root_timesheet_id::text;

  WITH
  -- Correction-chain source truth must come from the timesheet entitlement
  -- and timesheet reservation authorities only. _pay_outstanding_components
  -- also projects open finance cases, including a correction finance case
  -- created by the synchronisation that consumes this helper. Reusing that
  -- mixed projection here would feed the new case back into its own source
  -- truth and double the residual on the post-sync recheck.
  live_entitlement_components AS (
    SELECT
      entitlement_row.timesheet_id,
      UPPER(BTRIM(entitlement_row.key_type)) AS key_type,
      BTRIM(entitlement_row.key_value) AS key_value,
      entitlement_row.truth_ex_vat,
      entitlement_row.baseline_ex_vat,
      entitlement_row.truth_inc_vat,
      entitlement_row.baseline_inc_vat
    FROM private.pay_workbench_current_entitlement_components_cached_v1(
      v_member_ids
    ) AS entitlement_row
    WHERE UPPER(BTRIM(entitlement_row.key_type)) = 'TS_DAY'
      AND NULLIF(BTRIM(entitlement_row.key_value), '') IS NOT NULL
  ),
  active_entitlement_reservations AS (
    SELECT
      reservation_row.timesheet_id,
      UPPER(BTRIM(reservation_row.key_type)) AS key_type,
      BTRIM(reservation_row.key_value) AS key_value,
      reservation_row.amount_ex_vat,
      reservation_row.amount_inc_vat
    FROM public._pay_reserved_components(
      v_member_ids,
      p_exclude_pay_batch_id
    ) AS reservation_row
    WHERE UPPER(BTRIM(reservation_row.key_type)) = 'TS_DAY'
      AND NULLIF(BTRIM(reservation_row.key_value), '') IS NOT NULL
  ),
  entitlement_keys AS (
    SELECT DISTINCT
      entitlement_row.timesheet_id,
      entitlement_row.key_type,
      entitlement_row.key_value
    FROM live_entitlement_components AS entitlement_row

    UNION

    SELECT DISTINCT
      reservation_row.timesheet_id,
      reservation_row.key_type,
      reservation_row.key_value
    FROM active_entitlement_reservations AS reservation_row
  ),
  entitlement_joined AS (
    SELECT
      component_key.timesheet_id,
      component_key.key_type,
      component_key.key_value,
      COALESCE(entitlement_row.truth_ex_vat, 0) AS truth_ex_vat,
      COALESCE(entitlement_row.baseline_ex_vat, 0) AS baseline_ex_vat,
      COALESCE(reservation_row.amount_ex_vat, 0) AS reserved_ex_vat,
      COALESCE(entitlement_row.truth_inc_vat, 0) AS truth_inc_vat,
      COALESCE(entitlement_row.baseline_inc_vat, 0)
        AS baseline_inc_vat,
      COALESCE(reservation_row.amount_inc_vat, 0) AS reserved_inc_vat
    FROM entitlement_keys AS component_key
    LEFT JOIN live_entitlement_components AS entitlement_row
      ON entitlement_row.timesheet_id = component_key.timesheet_id
     AND entitlement_row.key_type = component_key.key_type
     AND entitlement_row.key_value = component_key.key_value
    LEFT JOIN active_entitlement_reservations AS reservation_row
      ON reservation_row.timesheet_id = component_key.timesheet_id
     AND reservation_row.key_type = component_key.key_type
     AND reservation_row.key_value = component_key.key_value
  ),
  raw_component_totals AS (
    SELECT
      component_row.key_type,
      component_row.key_value,
      round(sum(component_row.truth_ex_vat), 2)::numeric(18,2)
        AS truth_ex_vat,
      round(sum(component_row.baseline_ex_vat), 2)::numeric(18,2)
        AS baseline_ex_vat,
      round(sum(component_row.reserved_ex_vat), 2)::numeric(18,2)
        AS reserved_ex_vat,
      round(sum(component_row.truth_inc_vat), 2)::numeric(18,2)
        AS truth_inc_vat,
      round(sum(component_row.baseline_inc_vat), 2)::numeric(18,2)
        AS baseline_inc_vat,
      round(sum(component_row.reserved_inc_vat), 2)::numeric(18,2)
        AS reserved_inc_vat
    FROM entitlement_joined AS component_row
    GROUP BY
      component_row.key_type,
      component_row.key_value
  ),
  raw_outstanding AS (
    SELECT
      component_total.key_type,
      component_total.key_value,
      component_total.truth_ex_vat,
      component_total.baseline_ex_vat,
      component_total.reserved_ex_vat,
      round(
        component_total.truth_ex_vat
        - component_total.baseline_ex_vat
        - component_total.reserved_ex_vat,
        2
      )::numeric(18,2) AS raw_outstanding_ex_vat,
      component_total.truth_inc_vat,
      component_total.baseline_inc_vat,
      component_total.reserved_inc_vat,
      round(
        component_total.truth_inc_vat
        - component_total.baseline_inc_vat
        - component_total.reserved_inc_vat,
        2
      )::numeric(18,2) AS raw_outstanding_inc_vat,
      round(abs(component_total.reserved_ex_vat), 2)
        > round(
            abs(GREATEST(
              component_total.truth_ex_vat
              - component_total.baseline_ex_vat,
              0
            )),
            2
          ) AS reservation_overrun_detected
    FROM raw_component_totals AS component_total
  ),
  family_components AS (
    SELECT
      finance_component.id AS finance_component_id,
      finance_component.component_key_type,
      finance_component.component_key_value
    FROM public.pay_finance_case_components AS finance_component
    WHERE finance_component.candidate_id = p_candidate_id
      AND finance_component.source_family_key = v_source_family_key
      AND UPPER(BTRIM(finance_component.component_key_type)) = 'TS_DAY'
  ),
  settled_movements AS (
    SELECT
      UPPER(BTRIM(family_component.component_key_type)) AS key_type,
      BTRIM(family_component.component_key_value) AS key_value,
      round(sum(
        CASE
          WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, '')))
               = 'OVERPAYMENT_RECOVERY'
            THEN abs(COALESCE(
              reservation_row.reserved_source_amount,
              batch_item.frozen_source_amount,
              batch_item.amount_ex_vat,
              0
            ))
          ELSE 0
        END
      ), 2)::numeric(18,2) AS settled_recovery_ex,
      round(sum(
        CASE
          WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, '')))
               = 'UNDERPAYMENT_PAYMENT'
            THEN abs(COALESCE(
              reservation_row.reserved_source_amount,
              batch_item.frozen_source_amount,
              batch_item.amount_ex_vat,
              0
            ))
          ELSE 0
        END
      ), 2)::numeric(18,2) AS settled_underpayment_ex
    FROM family_components AS family_component
    JOIN public.pay_batch_items AS batch_item
      ON batch_item.finance_component_id =
         family_component.finance_component_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations AS reservation_row
      ON reservation_row.pay_batch_item_id = batch_item.id
    WHERE COALESCE(batch_item.is_voided, false) = false
      AND (
        UPPER(BTRIM(COALESCE(
          batch_candidate.settlement_status,
          ''
        ))) = 'SETTLED'
        OR batch_candidate.settled_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(bank_transfer.status, '')))
             = 'COMPLETED'
        OR bank_transfer.completed_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(reservation_row.status, '')))
             = 'SETTLED'
        OR reservation_row.settled_at_utc IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_correction
        WHERE applied_correction.pay_batch_item_id = batch_item.id
          AND applied_correction.status = 'APPLIED'
          AND applied_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
    GROUP BY
      UPPER(BTRIM(family_component.component_key_type)),
      BTRIM(family_component.component_key_value)
  ),
  active_case_reservations AS (
    SELECT
      UPPER(BTRIM(family_component.component_key_type)) AS key_type,
      BTRIM(family_component.component_key_value) AS key_value,
      round(sum(
        CASE
          WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, '')))
               = 'OVERPAYMENT_RECOVERY'
            THEN abs(COALESCE(
              reservation_row.reserved_source_amount,
              reservation_row.reserved_amount,
              0
            ))
          ELSE 0
        END
      ), 2)::numeric(18,2) AS reserved_recovery_ex,
      round(sum(
        CASE
          WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, '')))
               = 'UNDERPAYMENT_PAYMENT'
            THEN abs(COALESCE(
              reservation_row.reserved_source_amount,
              reservation_row.reserved_amount,
              0
            ))
          ELSE 0
        END
      ), 2)::numeric(18,2) AS reserved_underpayment_ex
    FROM family_components AS family_component
    JOIN public.pay_advance_reservations AS reservation_row
      ON reservation_row.finance_component_id =
         family_component.finance_component_id
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = reservation_row.pay_batch_item_id
    WHERE UPPER(BTRIM(COALESCE(reservation_row.status, '')))
          IN ('RESERVED', 'COMMITTED')
      AND reservation_row.released_at_utc IS NULL
      AND reservation_row.settled_at_utc IS NULL
      AND (
        p_exclude_pay_batch_id IS NULL
        OR reservation_row.pay_batch_id <> p_exclude_pay_batch_id
      )
    GROUP BY
      UPPER(BTRIM(family_component.component_key_type)),
      BTRIM(family_component.component_key_value)
  ),
  -- Settled and actively reserved recovery/payment movements are part of the
  -- pre-draft source basis.  Including them in the fingerprint makes a saved
  -- PAYE/umbrella resolution stale whenever the net economic balance changes.
  source_basis AS (
    SELECT
      raw_component.*,
      COALESCE(settled_movement.settled_recovery_ex, 0)
        AS settled_recovery_ex,
      COALESCE(settled_movement.settled_underpayment_ex, 0)
        AS settled_underpayment_ex,
      COALESCE(active_reservation.reserved_recovery_ex, 0)
        AS reserved_recovery_ex,
      COALESCE(active_reservation.reserved_underpayment_ex, 0)
        AS reserved_underpayment_ex,
      encode(
        extensions.digest(
          convert_to(
            jsonb_build_object(
              'source_family_key', v_source_family_key,
              'root_timesheet_id', v_root_timesheet_id::text,
              'correction_financials_policy_envelope_fingerprint',
                v_correction_financials_policy_envelope_fingerprint,
              'candidate_id', p_candidate_id::text,
              'source_pay_methods', v_source_pay_methods,
              'target_pay_method', v_target_pay_method,
              'component_key_type', raw_component.key_type,
              'component_key_value', raw_component.key_value,
              'truth_ex_vat', raw_component.truth_ex_vat,
              'baseline_ex_vat', raw_component.baseline_ex_vat,
              'reserved_ex_vat', raw_component.reserved_ex_vat,
              'raw_outstanding_ex_vat',
                raw_component.raw_outstanding_ex_vat,
              'truth_inc_vat', raw_component.truth_inc_vat,
              'baseline_inc_vat', raw_component.baseline_inc_vat,
              'reserved_inc_vat', raw_component.reserved_inc_vat,
              'raw_outstanding_inc_vat',
                raw_component.raw_outstanding_inc_vat,
              'settled_recovery_ex',
                COALESCE(settled_movement.settled_recovery_ex, 0),
              'settled_underpayment_ex',
                COALESCE(settled_movement.settled_underpayment_ex, 0),
              'reserved_recovery_ex',
                COALESCE(active_reservation.reserved_recovery_ex, 0),
              'reserved_underpayment_ex',
                COALESCE(active_reservation.reserved_underpayment_ex, 0)
            )::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ) AS source_basis_fingerprint
    FROM raw_outstanding AS raw_component
    LEFT JOIN settled_movements AS settled_movement
      ON settled_movement.key_type = raw_component.key_type
     AND settled_movement.key_value = raw_component.key_value
    LEFT JOIN active_case_reservations AS active_reservation
      ON active_reservation.key_type = raw_component.key_type
     AND active_reservation.key_value = raw_component.key_value
  ),
  latest_session_resolution AS (
    SELECT ranked.*
    FROM (
      SELECT resolution_source.*,
        row_number() over (
          partition by
            upper(btrim(resolution_source.component_key_type)),
            btrim(resolution_source.component_key_value)
          order by resolution_source.updated_at_utc desc,
                   resolution_source.created_at_utc desc,
                   resolution_source.id desc
        ) AS resolution_rank
      FROM public.banking_pay_workbench_session_case_resolutions
        AS resolution_source
      WHERE p_workbench_session_id IS NOT NULL
        AND resolution_source.session_id = p_workbench_session_id
        AND resolution_source.candidate_id = p_candidate_id
        AND resolution_source.source_family_key = v_source_family_key
        AND upper(btrim(coalesce(resolution_source.component_key_type,''))) = 'TS_DAY'
        AND nullif(btrim(coalesce(resolution_source.component_key_value,'')),'') IS NOT NULL
        AND resolution_source.payload_json->>
              'correction_resolution_aggregate_version'
            = 'CORRECTION_CHAIN_BUCKET_SET_V1'
    ) AS ranked
    WHERE ranked.resolution_rank = 1
  ),
  session_resolution_rows AS (
    SELECT
      UPPER(BTRIM(resolution_row.component_key_type)) AS key_type,
      BTRIM(resolution_row.component_key_value) AS key_value,
      count(*)::integer AS resolution_row_count,
      min(source_component.source_basis_fingerprint)
        AS expected_source_basis_fingerprint,
      bool_and(
        resolution_row.source_basis_fingerprint
          IS NOT DISTINCT FROM source_component.source_basis_fingerprint
      ) AS source_basis_matches,
      bool_and(
        COALESCE(
          resolution_row.payload_json ->>
            'correction_financials_policy_envelope_fingerprint',
          resolution_row.payload_json #>>
            '{source_basis,correction_financials_policy_envelope_fingerprint}',
          resolution_row.payload_json #>>
            '{saved_resolution_payload_json,correction_financials_policy_envelope_fingerprint}',
          resolution_row.payload_json #>>
            '{component_state_json,correction_financials_policy_envelope_fingerprint}'
        ) IS NOT DISTINCT FROM v_correction_financials_policy_envelope_fingerprint
      ) AS historical_anchor_matches,
      bool_and(
        resolution_row.payload_json->>
          'correction_resolution_aggregate_version'
            = 'CORRECTION_CHAIN_BUCKET_SET_V1'
        AND jsonb_typeof(
              resolution_row.payload_json->'bucket_resolutions'
            ) = 'array'
        AND COALESCE(
              NULLIF(resolution_row.payload_json->>'physical_decision_count','')::integer,
              0
            ) = jsonb_array_length(
                  resolution_row.payload_json->'bucket_resolutions'
                )
        AND COALESCE(
              NULLIF(
                resolution_row.payload_json->>'distinct_projected_target_count',
                ''
              )::integer,
              0
            ) = 1
        AND COALESCE(
              resolution_row.payload_json->>'physical_decision_set_digest',
              ''
            ) = encode(
                  extensions.digest(
                    convert_to(
                      (resolution_row.payload_json->'bucket_resolutions')::text,
                      'UTF8'
                    ),
                    'sha256'
                  ),
                  'hex'
                )
      ) AS aggregate_proof_valid,
      min(COALESCE(
        NULLIF(resolution_row.payload_json->>'physical_decision_count','')::integer,
        0
      )) AS physical_decision_count,
      min(nullif(btrim(coalesce(
        resolution_row.payload_json ->> 'resolution_economic_fingerprint',
        resolution_row.payload_json #>>
          '{saved_resolution_payload_json,resolution_economic_fingerprint}',
        resolution_row.payload_json #>>
          '{bucket_resolutions,0,resolution_economic_fingerprint}',
        resolution_row.payload_json #>>
          '{bucket_resolutions,0,saved_resolution_payload_json,resolution_economic_fingerprint}',
        ''
      )), '')) AS saved_resolution_economic_fingerprint,
      count(*) FILTER (
        WHERE COALESCE(
          resolution_row.payload_json #>>
            '{resolution_result,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{saved_resolution_result_json,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{result,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,resolution_result,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,saved_resolution_result_json,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,result,target_amount_ex_vat}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,target_amount_ex_vat}',
          resolution_row.payload_json ->>
            'target_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS valid_target_amount_count,
      round(sum(
        CASE
          WHEN COALESCE(
            resolution_row.payload_json #>>
              '{resolution_result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{saved_resolution_result_json,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,resolution_result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,saved_resolution_result_json,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,target_amount_ex_vat}',
            resolution_row.payload_json ->>
              'target_amount_ex_vat',
            ''
          ) ~ '^-?[0-9]+([.][0-9]+)?$'
          THEN COALESCE(
            resolution_row.payload_json #>>
              '{resolution_result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{saved_resolution_result_json,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,resolution_result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,saved_resolution_result_json,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,result,target_amount_ex_vat}',
            resolution_row.payload_json #>>
              '{bucket_resolutions,0,target_amount_ex_vat}',
            resolution_row.payload_json ->>
              'target_amount_ex_vat'
          )::numeric
          ELSE 0
        END
      ), 2)::numeric(18,2) AS resolved_target_amount_ex_vat,
      bool_and(
        UPPER(BTRIM(COALESCE(
          resolution_row.payload_json ->> 'target_pay_method',
          resolution_row.payload_json #>>
            '{saved_resolution_payload_json,target_pay_method}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,saved_resolution_payload_json,target_pay_method}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,target_pay_method}',
          ''
        ))) = v_target_pay_method
      ) AS target_method_matches,
      bool_and(
        LOWER(BTRIM(COALESCE(
          resolution_row.payload_json ->> 'is_resolution_stale',
          resolution_row.payload_json #>>
            '{component_state_json,is_resolution_stale}',
          resolution_row.payload_json #>>
            '{bucket_resolutions,0,component_state_json,is_resolution_stale}',
          'false'
        ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      ) AS resolution_not_stale,
      jsonb_agg(
        jsonb_build_object(
          'resolution_id', resolution_row.id::text,
          'timesheet_id', CASE
            WHEN resolution_row.timesheet_id IS NULL THEN NULL
            ELSE resolution_row.timesheet_id::text
          END,
          'source_basis_fingerprint',
            resolution_row.source_basis_fingerprint,
          'resolution_identity_key',
            resolution_row.resolution_identity_key,
          'payload_json', resolution_row.payload_json
        )
        ORDER BY resolution_row.resolution_identity_key,
                 resolution_row.id
      ) AS resolution_rows
    FROM latest_session_resolution AS resolution_row
    JOIN source_basis AS source_component
      ON source_component.key_type =
           UPPER(BTRIM(resolution_row.component_key_type))
     AND source_component.key_value =
           BTRIM(resolution_row.component_key_value)
    WHERE p_workbench_session_id IS NOT NULL
      AND resolution_row.session_id = p_workbench_session_id
      AND resolution_row.candidate_id = p_candidate_id
      AND resolution_row.source_family_key = v_source_family_key
      AND UPPER(BTRIM(COALESCE(
        resolution_row.component_key_type,
        ''
      ))) = 'TS_DAY'
      AND NULLIF(BTRIM(COALESCE(
        resolution_row.component_key_value,
        ''
      )), '') IS NOT NULL
    GROUP BY
      UPPER(BTRIM(resolution_row.component_key_type)),
      BTRIM(resolution_row.component_key_value)
  ),
  component_result AS (
    SELECT
      raw_component.*,
      -- Recovery and underpayment movements form one signed ledger.  Do not
      -- clamp by the current raw sign: a later correction can legitimately
      -- cross zero, for example repaying money that was recovered in an
      -- earlier settled Banking Pay batch.
      round(
        raw_component.raw_outstanding_ex_vat
        + raw_component.settled_recovery_ex
        + raw_component.reserved_recovery_ex
        - raw_component.settled_underpayment_ex
        - raw_component.reserved_underpayment_ex,
        2
      )::numeric(18,2) AS effective_outstanding_ex_vat,

      (
        v_mismatched_source_method_count > 0
        AND round(
          raw_component.raw_outstanding_ex_vat
          + raw_component.settled_recovery_ex
          + raw_component.reserved_recovery_ex
          - raw_component.settled_underpayment_ex
          - raw_component.reserved_underpayment_ex,
          2
        ) <> 0
      ) AS resolution_required,

      COALESCE(session_resolution.resolution_row_count, 0)
        AS resolution_row_count,
      session_resolution.expected_source_basis_fingerprint,
      COALESCE(session_resolution.source_basis_matches, false)
        AS source_basis_matches,
      COALESCE(session_resolution.historical_anchor_matches, false)
        AS historical_anchor_matches,
      COALESCE(session_resolution.aggregate_proof_valid, false)
        AS aggregate_proof_valid,
      COALESCE(session_resolution.physical_decision_count, 0)
        AS physical_decision_count,
      session_resolution.saved_resolution_economic_fingerprint,
      COALESCE(session_resolution.valid_target_amount_count, 0)
        AS valid_target_amount_count,
      session_resolution.resolved_target_amount_ex_vat,
      COALESCE(session_resolution.target_method_matches, false)
        AS target_method_matches,
      COALESCE(session_resolution.resolution_not_stale, false)
        AS resolution_not_stale,
      COALESCE(session_resolution.resolution_rows, '[]'::jsonb)
        AS resolution_rows,

      CASE
        WHEN v_mismatched_source_method_count = 0 THEN true
        WHEN round(
          raw_component.raw_outstanding_ex_vat
          + raw_component.settled_recovery_ex
          + raw_component.reserved_recovery_ex
          - raw_component.settled_underpayment_ex
          - raw_component.reserved_underpayment_ex,
          2
        ) = 0 THEN true
        WHEN COALESCE(session_resolution.resolution_row_count, 0) = 1
         AND COALESCE(session_resolution.valid_target_amount_count, 0) = 1
         AND COALESCE(session_resolution.physical_decision_count, 0)
             >= GREATEST(v_mismatched_source_method_count, 1)
         AND COALESCE(session_resolution.aggregate_proof_valid, false)
         AND COALESCE(session_resolution.target_method_matches, false)
         AND COALESCE(session_resolution.resolution_not_stale, false)
         AND COALESCE(session_resolution.source_basis_matches, false)
         AND COALESCE(session_resolution.historical_anchor_matches, false)
          THEN true
        ELSE false
      END AS resolution_complete
    FROM source_basis AS raw_component
    LEFT JOIN session_resolution_rows AS session_resolution
      ON session_resolution.key_type = raw_component.key_type
     AND session_resolution.key_value = raw_component.key_value
  ),
  component_balanced AS (
    SELECT
      component_row.*,
      CASE
        WHEN component_row.raw_outstanding_ex_vat <> 0 THEN round(
          component_row.raw_outstanding_inc_vat
          * (
              component_row.effective_outstanding_ex_vat
              / component_row.raw_outstanding_ex_vat
            ),
          2
        )
        WHEN component_row.effective_outstanding_ex_vat = 0 THEN 0
        WHEN component_row.truth_ex_vat <> 0 THEN round(
          component_row.effective_outstanding_ex_vat
          * (component_row.truth_inc_vat / component_row.truth_ex_vat),
          2
        )
        WHEN component_row.baseline_ex_vat <> 0 THEN round(
          component_row.effective_outstanding_ex_vat
          * (component_row.baseline_inc_vat / component_row.baseline_ex_vat),
          2
        )
        ELSE component_row.effective_outstanding_ex_vat
      END::numeric(18,2) AS effective_outstanding_inc_vat,
      CASE
        WHEN component_row.resolution_required
         AND component_row.resolution_complete
          THEN round(
            CASE
              WHEN component_row.effective_outstanding_ex_vat = 0
                THEN 0
              ELSE
                sign(component_row.effective_outstanding_ex_vat)
                * abs(COALESCE(
                    component_row.resolved_target_amount_ex_vat,
                    0
                  ))
            END,
            2
          )
        ELSE component_row.effective_outstanding_ex_vat
      END::numeric(18,2) AS target_outstanding_ex_vat
    FROM component_result AS component_row
  ),
  component_fingerprinted AS (
    SELECT
      component_row.*,
      encode(
        extensions.digest(
          convert_to(
            jsonb_build_object(
              'canonical_correction_key',
                concat_ws(
                  '|',
                  'CORRECTION_CHAIN_V1',
                  p_candidate_id::text,
                  v_root_timesheet_id::text,
                  upper(btrim(component_row.key_type)),
                  CASE
                    WHEN upper(btrim(component_row.key_type)) = 'TS_DAY'
                      THEN (component_row.key_value::date)::text
                    ELSE btrim(component_row.key_value)
                  END
                ),
              'ordered_member_timesheet_ids', to_jsonb(v_member_ids),
              'chain_fingerprint', v_chain ->> 'chain_fingerprint',
              'source_basis_fingerprint',
                component_row.source_basis_fingerprint,
              'correction_financials_policy_envelope_fingerprint',
                v_correction_financials_policy_envelope_fingerprint,
              'classification', 'TAXABLE_CHANNEL_SENSITIVE',
              'source_pay_methods', v_source_pay_methods,
              'target_pay_method', v_target_pay_method,
              'truth_ex_vat', component_row.truth_ex_vat,
              'baseline_ex_vat', component_row.baseline_ex_vat,
              'reserved_ex_vat', component_row.reserved_ex_vat,
              'raw_outstanding_ex_vat',
                component_row.raw_outstanding_ex_vat,
              'effective_source_outstanding_ex_vat',
                component_row.effective_outstanding_ex_vat,
              'raw_outstanding_inc_vat',
                component_row.raw_outstanding_inc_vat,
              'effective_source_outstanding_inc_vat',
                component_row.effective_outstanding_inc_vat,
              'resolution_required', component_row.resolution_required
            )::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ) AS current_resolution_economic_fingerprint
    FROM component_balanced AS component_row
  ),
  component_verified AS (
    SELECT
      component_row.*,
      (
        component_row.resolution_not_stale
        AND (
          NOT component_row.resolution_required
          OR component_row.saved_resolution_economic_fingerprint
            IS NOT DISTINCT FROM
              component_row.current_resolution_economic_fingerprint
        )
      ) AS verified_resolution_not_stale,
      (
        component_row.resolution_complete
        AND (
          NOT component_row.resolution_required
          OR component_row.saved_resolution_economic_fingerprint
            IS NOT DISTINCT FROM
              component_row.current_resolution_economic_fingerprint
        )
      ) AS verified_resolution_complete,
      CASE
        WHEN component_row.resolution_required
         AND component_row.saved_resolution_economic_fingerprint
           IS DISTINCT FROM
             component_row.current_resolution_economic_fingerprint
          THEN component_row.effective_outstanding_ex_vat
        ELSE component_row.target_outstanding_ex_vat
      END::numeric(18,2) AS verified_target_outstanding_ex_vat
    FROM component_fingerprinted AS component_row
  )
  SELECT
    count(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'canonical_correction_key',
            concat_ws(
              '|',
              'CORRECTION_CHAIN_V1',
              p_candidate_id::text,
              v_root_timesheet_id::text,
              upper(btrim(component_row.key_type)),
              CASE
                WHEN upper(btrim(component_row.key_type)) = 'TS_DAY'
                  THEN (component_row.key_value::date)::text
                ELSE btrim(component_row.key_value)
              END
            ),
          'correction_identity_version', 'CORRECTION_CHAIN_V1',
          'correction_root_id', v_root_timesheet_id::text,
          'ordered_member_timesheet_ids', to_jsonb(v_member_ids),
          'component_lineage_fingerprint',
            encode(
              extensions.digest(
                convert_to(
                  jsonb_build_object(
                    'identity_version', 'CORRECTION_CHAIN_V1',
                    'candidate_id', p_candidate_id::text,
                    'correction_root_id', v_root_timesheet_id::text,
                    'component_key_type', upper(btrim(component_row.key_type)),
                    'component_key_value', CASE
                      WHEN upper(btrim(component_row.key_type)) = 'TS_DAY'
                        THEN (component_row.key_value::date)::text
                      ELSE btrim(component_row.key_value)
                    END,
                    'ordered_member_timesheet_ids', to_jsonb(v_member_ids),
                    'chain_fingerprint', v_chain ->> 'chain_fingerprint'
                  )::text,
                  'UTF8'
                ),
                'sha256'
              ),
              'hex'
            ),
          'resolution_economic_fingerprint',
            component_row.current_resolution_economic_fingerprint,
          'carrier_timesheet_id',
            v_latest_positive_timesheet_id::text,
          'source_family_key', v_source_family_key,
          'source_basis_fingerprint',
            component_row.source_basis_fingerprint,
          'correction_financials_policy_envelope_fingerprint',
            v_correction_financials_policy_envelope_fingerprint,
          'correction_financials_policy_envelope',
            v_correction_financials_policy_envelope,
          'component_key_type', component_row.key_type,
          'component_key_value', component_row.key_value,
          'classification', 'TAXABLE_CHANNEL_SENSITIVE',
          'source_pay_methods', v_source_pay_methods,
          'target_pay_method', v_target_pay_method,
          'truth_ex_vat', component_row.truth_ex_vat,
          'baseline_ex_vat', component_row.baseline_ex_vat,
          'reserved_ex_vat', component_row.reserved_ex_vat,
          'raw_outstanding_ex_vat',
            component_row.raw_outstanding_ex_vat,
          'settled_recovery_ex',
            component_row.settled_recovery_ex,
          'reserved_recovery_ex',
            component_row.reserved_recovery_ex,
          'settled_underpayment_ex',
            component_row.settled_underpayment_ex,
          'reserved_underpayment_ex',
            component_row.reserved_underpayment_ex,
          'effective_source_outstanding_ex_vat',
            component_row.effective_outstanding_ex_vat,
          'target_outstanding_ex_vat',
            component_row.verified_target_outstanding_ex_vat,
          'raw_outstanding_inc_vat',
            component_row.raw_outstanding_inc_vat,
          'effective_source_outstanding_inc_vat',
            component_row.effective_outstanding_inc_vat,
          'reservation_overrun_detected',
            component_row.reservation_overrun_detected,
          'resolution_required',
            component_row.resolution_required,
          'resolution_complete',
            component_row.verified_resolution_complete,
          'resolution_row_count',
            component_row.resolution_row_count,
          'resolution_not_stale',
            component_row.verified_resolution_not_stale,
          'saved_resolution_economic_fingerprint',
            component_row.saved_resolution_economic_fingerprint,
          'expected_source_basis_fingerprint',
            component_row.expected_source_basis_fingerprint,
          'source_basis_matches',
            component_row.source_basis_matches,
          'historical_anchor_matches',
            component_row.historical_anchor_matches,
          'aggregate_proof_valid',
            component_row.aggregate_proof_valid,
          'physical_decision_count',
            component_row.physical_decision_count,
          'resolved_target_amount_ex_vat',
            component_row.resolved_target_amount_ex_vat,
          'resolution_rows',
            component_row.resolution_rows
        )
        ORDER BY component_row.key_type, component_row.key_value
      ),
      '[]'::jsonb
    ),
    round(COALESCE(sum(component_row.raw_outstanding_ex_vat), 0), 2),
    round(COALESCE(sum(component_row.verified_target_outstanding_ex_vat), 0), 2),
    round(COALESCE(sum(component_row.raw_outstanding_inc_vat), 0), 2),
    round(COALESCE(sum(component_row.effective_outstanding_inc_vat), 0), 2),
    count(*) FILTER (
      WHERE component_row.resolution_required
    )::integer,
    count(*) FILTER (
      WHERE component_row.resolution_required
        AND NOT component_row.verified_resolution_complete
    )::integer,
    count(*) FILTER (
      WHERE component_row.reservation_overrun_detected
    )::integer
  INTO
    v_component_count,
    v_components,
    v_total_raw_ex,
    v_total_effective_ex,
    v_total_raw_inc,
    v_total_effective_inc,
    v_resolution_required_count,
    v_unresolved_count,
    v_reservation_overrun_count
  FROM component_verified AS component_row;

  IF v_component_count > p_max_components THEN
    RAISE EXCEPTION 'CORRECTION_RESIDUAL_COMPONENT_LIMIT_EXCEEDED'
      USING ERRCODE = '54001',
            DETAIL = jsonb_build_object(
              'component_count', v_component_count,
              'max_components', p_max_components
            )::text;
  END IF;

  v_draftable :=
    v_component_count > 0
    AND v_unresolved_count = 0
    AND v_reservation_overrun_count = 0;

  IF v_unresolved_count > 0 THEN
    v_total_effective_ex := NULL::numeric;
  END IF;

  v_residual_fingerprint := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'chain_fingerprint', v_chain ->> 'chain_fingerprint',
          'correction_financials_policy_envelope_fingerprint',
            v_correction_financials_policy_envelope_fingerprint,
          'candidate_id', p_candidate_id::text,
          'target_pay_method', v_target_pay_method,
          'source_family_key', v_source_family_key,
          'components', v_components,
          'exclude_pay_batch_id', CASE
            WHEN p_exclude_pay_batch_id IS NULL THEN NULL
            ELSE p_exclude_pay_batch_id::text
          END
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'draftable', v_draftable,
    'root_timesheet_id', v_root_timesheet_id::text,
    'correction_identity_version', 'CORRECTION_CHAIN_V1',
    'ordered_member_timesheet_ids', to_jsonb(v_member_ids),
    'latest_positive_timesheet_id',
      v_latest_positive_timesheet_id::text,
    'member_timesheet_ids', to_jsonb(v_member_ids),
    'member_count', v_member_count,
    'candidate_id', p_candidate_id::text,
    'client_id', CASE
      WHEN v_chain_client_id IS NULL THEN NULL
      ELSE v_chain_client_id::text
    END,
    'source_family_key', v_source_family_key,
    'correction_financials_policy_envelope', v_correction_financials_policy_envelope,
    'correction_financials_policy_envelope_fingerprint',
      v_correction_financials_policy_envelope_fingerprint,
    'source_pay_methods', v_source_pay_methods,
    'source_pay_method_count', v_source_pay_method_count,
    'target_pay_method', v_target_pay_method,
    'component_count', v_component_count,
    'components', v_components,
    'total_raw_outstanding_ex_vat', v_total_raw_ex,
    'total_target_outstanding_ex_vat', v_total_effective_ex,
    'total_raw_outstanding_inc_vat', v_total_raw_inc,
    'total_effective_source_outstanding_inc_vat',
      v_total_effective_inc,
    'resolution_required_count', v_resolution_required_count,
    'unresolved_count', v_unresolved_count,
    'reservation_overrun_count', v_reservation_overrun_count,
    'chain_fingerprint', v_chain ->> 'chain_fingerprint',
    'residual_fingerprint', v_residual_fingerprint,
    'block_code', CASE
      WHEN v_reservation_overrun_count > 0
        THEN 'CORRECTION_CHAIN_RESERVATION_OVERRUN'
      WHEN v_unresolved_count > 0
        THEN 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
      WHEN v_component_count = 0
        THEN 'CORRECTION_CHAIN_NO_TS_DAY_COMPONENTS'
      ELSE NULL
    END
  );
END;
$function$;

-- pay_create_draft_batch(date,date,text,uuid,jsonb,uuid,uuid,uuid[],text,pay_override_mode_enum,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_create_draft_batch(p_pay_date date, p_week_ending_cutoff date, p_pay_channel_scope text, p_actor_user_id uuid, p_preview_decisions_json jsonb, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_override_reason text DEFAULT NULL::text, p_override_mode pay_override_mode_enum DEFAULT 'NONE'::pay_override_mode_enum, p_operation_id uuid DEFAULT NULL::uuid, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_week_start date := public._pay_week_start_monday(p_pay_date);
  v_preview_decisions_json jsonb := CASE
    WHEN jsonb_typeof(coalesce(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN coalesce(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_preview_payload_json jsonb := '{}'::jsonb;
  v_selected_preview_row_ids_input jsonb := '[]'::jsonb;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_preview_rows_supplied boolean := false;
  v_requested_selected_preview_row_count integer := 0;
  v_selected_preview_row_count integer := 0;
  v_build_result jsonb := '{}'::jsonb;
  v_pay_batch_id uuid := NULL::uuid;
  v_consumed_timesheet_payment_override_count integer := 0;
  v_consumed_timesheet_payment_overrides jsonb := '[]'::jsonb;
  v_legacy_safe_selected_row_threshold integer := 250;
  v_operation_row public.banking_pay_operations%ROWTYPE;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION 'week_ending_cutoff is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_create_draft_batch operation % was not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type <> 'DRAFT_CREATE' THEN
      RAISE EXCEPTION 'pay_create_draft_batch expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation_row.operation_type;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_create_draft_batch operation % belongs to a different actor', p_operation_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'requires_operation_runner', true,
      'operation_id', v_operation_row.id::text,
      'operation_type', v_operation_row.operation_type,
      'status', v_operation_row.status,
      'phase', v_operation_row.phase,
      'pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
      'workbench_session_id', CASE WHEN v_operation_row.workbench_session_id IS NULL THEN NULL ELSE v_operation_row.workbench_session_id::text END,
      'total_units', v_operation_row.total_units,
      'completed_units', v_operation_row.completed_units,
      'failed_units', v_operation_row.failed_units,
      'current_chunk_index', v_operation_row.current_chunk_index,
      'chunk_count', v_operation_row.chunk_count,
      'progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
      'result_json', CASE WHEN v_operation_row.status IN ('COMPLETE', 'REVIEW_REQUIRED') THEN v_operation_row.result_json ELSE NULL END,
      'error_json', CASE WHEN v_operation_row.status IN ('FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN v_operation_row.error_json ELSE NULL END,
      'message', 'Draft creation is running through the scalable Banking Pay operation flow.'
    );
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_OPERATION_REQUIRED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'pay_create_draft_batch refused legacy all-at-once draft creation. Normal draft creation must use the scalable Banking Pay DRAFT_CREATE operation flow; set p_allow_legacy_unchunked only for explicit small diagnostic/test compatibility.',
      'pay_channel_scope', v_scope,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF (p_force_include_timesheet_ids IS NOT NULL AND coalesce(array_length(p_force_include_timesheet_ids, 1), 0) > 0)
     OR p_override_reason IS NOT NULL
     OR p_override_mode IS DISTINCT FROM 'NONE'::public.pay_override_mode_enum THEN
    BEGIN
      PERFORM public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:LEGACY_OVERRIDE_PARAMS_IGNORED',
        jsonb_build_object(
          'pay_date', p_pay_date::text,
          'week_ending_cutoff', p_week_ending_cutoff::text,
          'pay_channel_scope', v_scope,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
          'force_include_timesheet_ids_count', coalesce(array_length(p_force_include_timesheet_ids, 1), 0),
          'override_reason', p_override_reason,
          'override_mode', p_override_mode::text
        ),
        'pay_batches',
        'legacy-pay-create-draft-batch',
        NULL, NULL, NULL, NULL, NULL
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  v_selected_preview_row_ids_input := CASE
    WHEN jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'array' THEN coalesce(v_preview_decisions_json->'selected_preview_row_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_selected_preview_rows_supplied := jsonb_array_length(v_selected_preview_row_ids_input) > 0;

  SELECT count(*)::integer
  INTO v_requested_selected_preview_row_count
  FROM (
    SELECT DISTINCT btrim(sel.value) AS selected_preview_row_id
    FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
    WHERE btrim(sel.value) <> ''
  ) AS requested_rows;

  IF v_selected_preview_rows_supplied = true
     AND COALESCE(v_requested_selected_preview_row_count, 0) > v_legacy_safe_selected_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_LEGACY_SELECTED_SCOPE_TOO_LARGE',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'This draft selection is too large for the legacy all-at-once path. Even explicit legacy/test compatibility is limited to small selections; use the scalable Banking Pay draft operation flow.',
      'selected_preview_row_count', v_requested_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'pay_channel_scope', v_scope,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF v_selected_preview_rows_supplied = false
     AND p_candidate_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_UNBOUNDED_LEGACY_DISABLED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'Unbounded or client-wide legacy draft creation is disabled. Even explicit legacy/test compatibility must supply a small candidate/test scope or selected preview rows.',
      'pay_channel_scope', v_scope,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  v_preview_payload_json := public.pay_preview(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json
  );

  IF jsonb_typeof(v_preview_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_preview(...) must return a JSON object';
  END IF;

  v_selected_preview_row_ids_input := CASE
    WHEN jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'array' THEN coalesce(v_preview_decisions_json->'selected_preview_row_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_selected_preview_rows_supplied := jsonb_array_length(v_selected_preview_row_ids_input) > 0;

  SELECT count(*)::integer
  INTO v_requested_selected_preview_row_count
  FROM (
    SELECT DISTINCT btrim(sel.value) AS selected_preview_row_id
    FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
    WHERE btrim(sel.value) <> ''
  ) AS requested_rows;

  WITH preview_lines AS (
    SELECT
      line.value AS line_json
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'canonical_preview_lines', '[]'::jsonb)) AS line(value)
    WHERE jsonb_typeof(line.value) = 'object'
  ),
  preview_line_ids AS (
    SELECT
      coalesce(
        nullif(btrim(coalesce(preview_lines.line_json->>'preview_row_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'line_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'row_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'id', '')), '')
      ) AS preview_row_id,
      upper(btrim(coalesce(preview_lines.line_json->>'pay_channel', ''))) AS pay_channel_scope,
      coalesce(nullif(preview_lines.line_json->>'draftable', '')::boolean, false) AS is_draftable
    FROM preview_lines
  ),
  selected_lines AS (
    SELECT DISTINCT
      preview_line_ids.preview_row_id
    FROM preview_line_ids
    WHERE preview_line_ids.preview_row_id IS NOT NULL
      AND preview_line_ids.pay_channel_scope = v_scope
      AND preview_line_ids.is_draftable = true
      AND (
        v_selected_preview_rows_supplied = false
        OR preview_line_ids.preview_row_id IN (
          SELECT btrim(sel.value)
          FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
          WHERE btrim(sel.value) <> ''
        )
      )
  )
  SELECT
    coalesce(jsonb_agg(to_jsonb(selected_lines.preview_row_id) ORDER BY selected_lines.preview_row_id), '[]'::jsonb),
    count(*)::integer
  INTO v_selected_preview_row_ids, v_selected_preview_row_count
  FROM selected_lines;

  IF v_selected_preview_row_count = 0 THEN
    RAISE EXCEPTION 'No draftable preview rows found for requested pay channel scope %', v_scope;
  END IF;

  IF v_selected_preview_rows_supplied AND v_selected_preview_row_count <> v_requested_selected_preview_row_count THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve fully within requested pay channel scope %', v_scope;
  END IF;

  IF v_selected_preview_row_count > v_legacy_safe_selected_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_LEGACY_UNCHUNKED_TOO_LARGE',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'This draft contains too many payment rows for the legacy all-at-once path. Even explicit legacy/test compatibility is limited to small selections; use the scalable Banking Pay draft operation flow.',
      'selected_preview_row_count', v_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'pay_channel_scope', v_scope,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  v_build_result := public.pay_build_batch_artifacts_from_preview(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_preview_payload_json => v_preview_payload_json,
    p_selected_preview_row_ids => v_selected_preview_row_ids,
    p_source_workbench_session_id => NULL::uuid,
    p_source_snapshot_run_id => NULL::uuid,
    p_source_session_version => NULL::bigint,
    p_operation_id => NULL::uuid,
    p_candidate_scope_ids => NULL::jsonb,
    p_existing_pay_batch_id => NULL::uuid,
    p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
  );

  IF jsonb_typeof(v_build_result) <> 'object' THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview(...) must return a JSON object';
  END IF;

  IF coalesce(nullif(btrim(coalesce(v_build_result->>'pay_batch_id', '')), ''), '') = '' THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview(...) did not return pay_batch_id';
  END IF;

  v_pay_batch_id := (v_build_result->>'pay_batch_id')::uuid;

  SELECT
    count(*)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'override_id', tpo.id::text,
          'timesheet_id', tpo.timesheet_id::text,
          'candidate_id', CASE WHEN tpo.candidate_id IS NULL THEN NULL ELSE tpo.candidate_id::text END,
          'override_type', tpo.override_type,
          'reason', tpo.reason,
          'created_at_utc', tpo.created_at_utc,
          'created_by_user_id', CASE WHEN tpo.created_by_user_id IS NULL THEN NULL ELSE tpo.created_by_user_id::text END,
          'consumed_by_pay_batch_id', CASE WHEN tpo.consumed_by_pay_batch_id IS NULL THEN NULL ELSE tpo.consumed_by_pay_batch_id::text END,
          'consumed_at_utc', tpo.consumed_at_utc
        )
        ORDER BY tpo.timesheet_id::text, tpo.id::text
      ),
      '[]'::jsonb
    )
  INTO
    v_consumed_timesheet_payment_override_count,
    v_consumed_timesheet_payment_overrides
  FROM public.timesheet_payment_overrides tpo
  WHERE tpo.consumed_by_pay_batch_id = v_pay_batch_id
    AND upper(coalesce(tpo.override_type, '')) = 'ADVANCE_THIS_PAYMENT';

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:LEGACY_ORCHESTRATOR_RETURN',
      jsonb_build_object(
        'pay_batch_id', v_pay_batch_id::text,
        'pay_date', p_pay_date::text,
        'pay_week_start', v_week_start::text,
        'week_ending_cutoff_date', p_week_ending_cutoff::text,
        'pay_channel_scope', v_scope,
        'selected_preview_row_count', v_selected_preview_row_count,
        'consumed_timesheet_payment_override_count', v_consumed_timesheet_payment_override_count,
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
      ),
      'pay_batches',
      v_pay_batch_id::text,
      NULL, NULL, NULL, NULL, NULL
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_pay_batch_id::text,
    'pay_date', coalesce(v_build_result->>'pay_date', p_pay_date::text),
    'pay_week_start', coalesce(v_build_result->>'pay_week_start', v_week_start::text),
    'week_ending_cutoff_date', coalesce(v_build_result->>'week_ending_cutoff_date', p_week_ending_cutoff::text),
    'pay_channel_scope', coalesce(v_build_result->>'pay_channel_scope', v_scope),
    'banking_system_snapshot', v_build_result->>'banking_system_snapshot',
    'external_paye_system_snapshot', v_build_result->>'external_paye_system_snapshot',
    'rail_provider_snapshot', v_build_result->>'rail_provider_snapshot',
    'rail_env_snapshot', v_build_result->>'rail_env_snapshot',
    'consumed_timesheet_payment_override_count', coalesce(v_consumed_timesheet_payment_override_count, 0),
    'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
  );
END;
$function$;

-- pay_create_draft_batches_split(date,date,uuid,jsonb,uuid,uuid,uuid[],text,pay_override_mode_enum,boolean,boolean,uuid,timestamp with time zone,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_create_draft_batches_split(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_preview_decisions_json jsonb, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_override_reason text DEFAULT NULL::text, p_override_mode pay_override_mode_enum DEFAULT 'NONE'::pay_override_mode_enum, p_override_continue boolean DEFAULT false, p_override_verified boolean DEFAULT false, p_override_verified_by_user_id uuid DEFAULT NULL::uuid, p_override_verified_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_operation_id uuid DEFAULT NULL::uuid, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_status text := NULL::text;
  v_is_terminal boolean := false;
  v_requires_operation_runner boolean := false;
  v_expected_source_session_version bigint := NULL::bigint;
  v_expected_source_snapshot_run_id uuid := NULL::uuid;
  v_operation_input_pay_date date := NULL::date;
  v_operation_input_week_ending_cutoff date := NULL::date;
  v_scope_count integer := 0;
  v_invalid_scope_count integer := 0;
  v_candidate_count integer := 0;
  v_paye_scope_count integer := 0;
  v_umbrella_scope_count integer := 0;
  v_distinct_batch_count integer := 0;
  v_paye_batch_count integer := 0;
  v_umbrella_batch_count integer := 0;
  v_cross_channel_shared_batch_count integer := 0;
  v_paye_batch_id uuid := NULL::uuid;
  v_umbrella_batch_id uuid := NULL::uuid;
  v_scope_status_counts jsonb := '{}'::jsonb;
  v_scope_batch_ids jsonb := '[]'::jsonb;
  v_operation_batch_ids jsonb := '[]'::jsonb;
  v_invalid_batch_count integer := 0;
  v_post_shell_phase boolean := false;
BEGIN
  IF COALESCE(p_allow_legacy_unchunked, false) IS TRUE THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_LEGACY_UNCHUNKED_DISABLED', 'message', 'Legacy split all-at-once draft creation is permanently disabled. Use the Banking Pay DRAFT_CREATE operation flow.', 'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END, 'allow_legacy_unchunked', true)::text;
  END IF;
  IF p_pay_date IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'pay_date is required'; END IF;
  IF p_week_ending_cutoff IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'week_ending_cutoff is required'; END IF;
  IF p_actor_user_id IS NULL THEN RAISE EXCEPTION USING ERRCODE = '22004', MESSAGE = 'actor_user_id is required'; END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_REQUIRED',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_REQUIRED', 'message', 'Split draft creation requires an operation-scoped Banking Pay DRAFT_CREATE operation.', 'pay_date', p_pay_date::text, 'week_ending_cutoff', p_week_ending_cutoff::text)::text;
  END IF;

  SELECT operation_row.* INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE OF operation_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_NOT_FOUND', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;
  IF v_operation_row.operation_type IS DISTINCT FROM 'DRAFT_CREATE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_TYPE_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'actual_operation_type', v_operation_row.operation_type)::text;
  END IF;
  IF v_operation_row.actor_user_id IS NULL OR v_operation_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_ACTOR_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_ACTOR_INVALID', 'operation_id', p_operation_id::text)::text;
  END IF;

  v_operation_status := UPPER(BTRIM(COALESCE(v_operation_row.status, '')));
  IF v_operation_status NOT IN ('QUEUED', 'RUNNING', 'WAITING', 'COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_STATUS_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_STATUS_INVALID', 'operation_id', p_operation_id::text, 'operation_status', v_operation_row.status)::text;
  END IF;
  v_is_terminal := v_operation_status IN ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED');
  v_requires_operation_runner := v_operation_status IN ('QUEUED', 'RUNNING', 'WAITING');

  IF v_operation_row.workbench_session_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_OPERATION_SESSION_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_OPERATION_SESSION_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT session_row.* INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_operation_row.workbench_session_id
  FOR UPDATE OF session_row;
  IF NOT FOUND OR v_session_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_SESSION_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_SESSION_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_operation_row.workbench_session_id::text)::text;
  END IF;
  IF v_session_row.pay_date IS DISTINCT FROM p_pay_date OR v_session_row.week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_CONTEXT_MISMATCH',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_CONTEXT_MISMATCH', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'expected_pay_date', v_session_row.pay_date::text, 'supplied_pay_date', p_pay_date::text, 'expected_week_ending_cutoff', v_session_row.week_ending_cutoff::text, 'supplied_week_ending_cutoff', p_week_ending_cutoff::text, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF COALESCE(v_operation_row.input_json->>'source_session_version', '') !~ '^[1-9][0-9]*$'
     OR COALESCE(v_operation_row.input_json->>'source_snapshot_run_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(v_operation_row.input_json->>'pay_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR COALESCE(NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''), v_operation_row.input_json->>'week_ending_cutoff_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_REQUIRED',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_REQUIRED',
        'operation_id', p_operation_id::text,
        'workbench_session_id', v_session_row.id::text,
        'source_session_version_present', COALESCE(v_operation_row.input_json->>'source_session_version', '') ~ '^[1-9][0-9]*$',
        'source_snapshot_run_id_present', COALESCE(v_operation_row.input_json->>'source_snapshot_run_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
        'pay_date_present', COALESCE(v_operation_row.input_json->>'pay_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
        'week_ending_cutoff_present', COALESCE(NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''), v_operation_row.input_json->>'week_ending_cutoff_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
        'refresh_required', NOT v_is_terminal,
        'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
      )::text;
  END IF;

  BEGIN
    v_expected_source_session_version := (v_operation_row.input_json->>'source_session_version')::bigint;
    v_expected_source_snapshot_run_id := (v_operation_row.input_json->>'source_snapshot_run_id')::uuid;
    v_operation_input_pay_date := (v_operation_row.input_json->>'pay_date')::date;
    v_operation_input_week_ending_cutoff := COALESCE(
      NULLIF(BTRIM(COALESCE(v_operation_row.input_json->>'week_ending_cutoff', '')), ''),
      v_operation_row.input_json->>'week_ending_cutoff_date'
    )::date;
  EXCEPTION
    WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_INVALID',
        DETAIL = jsonb_build_object(
          'ok', false,
          'code', 'DRAFT_CREATE_OPERATION_SOURCE_AUTHORITY_INVALID',
          'operation_id', p_operation_id::text,
          'workbench_session_id', v_session_row.id::text,
          'refresh_required', NOT v_is_terminal,
          'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
        )::text;
  END;

  IF v_operation_input_pay_date IS DISTINCT FROM p_pay_date
     OR v_operation_input_week_ending_cutoff IS DISTINCT FROM p_week_ending_cutoff
     OR v_operation_input_pay_date IS DISTINCT FROM v_session_row.pay_date
     OR v_operation_input_week_ending_cutoff IS DISTINCT FROM v_session_row.week_ending_cutoff THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'DRAFT_CREATE_OPERATION_CONTEXT_MISMATCH',
      DETAIL = jsonb_build_object(
        'ok', false,
        'code', 'DRAFT_CREATE_OPERATION_CONTEXT_MISMATCH',
        'operation_id', p_operation_id::text,
        'workbench_session_id', v_session_row.id::text,
        'operation_pay_date', v_operation_input_pay_date::text,
        'supplied_pay_date', p_pay_date::text,
        'session_pay_date', v_session_row.pay_date::text,
        'operation_week_ending_cutoff', v_operation_input_week_ending_cutoff::text,
        'supplied_week_ending_cutoff', p_week_ending_cutoff::text,
        'session_week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'refresh_required', NOT v_is_terminal,
        'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END
      )::text;
  END IF;

  IF NOT v_is_terminal AND (
    v_session_row.status IS DISTINCT FROM 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL OR v_session_row.replacement_session_id IS NOT NULL
    OR v_session_row.version IS DISTINCT FROM v_expected_source_session_version OR v_session_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_WORKBENCH_SESSION_STALE', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_WORKBENCH_SESSION_STALE', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'refresh_required', true, 'next_action', 'REFRESH_WORKBENCH')::text;
  END IF;

  PERFORM scope_row.id
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
  ORDER BY scope_row.id
  FOR UPDATE OF scope_row;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (
      WHERE scope_row.workbench_session_id IS DISTINCT FROM v_session_row.id
         OR scope_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
         OR scope_row.source_session_version IS DISTINCT FROM v_expected_source_session_version
         OR UPPER(BTRIM(COALESCE(scope_row.pay_channel, ''))) NOT IN ('PAYE', 'UMBRELLA')
         OR scope_row.status NOT IN ('PENDING', 'SCOPED', 'ALLOCATED', 'DRAFTED', 'FAILED')
    )::integer,
    COUNT(DISTINCT scope_row.candidate_id)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(scope_row.pay_channel)) = 'PAYE')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(scope_row.pay_channel)) = 'UMBRELLA')::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL)::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL AND UPPER(BTRIM(scope_row.pay_channel)) = 'PAYE')::integer,
    COUNT(DISTINCT scope_row.pay_batch_id) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL AND UPPER(BTRIM(scope_row.pay_channel)) = 'UMBRELLA')::integer,
    COALESCE(jsonb_agg(DISTINCT scope_row.pay_batch_id::text ORDER BY scope_row.pay_batch_id::text) FILTER (WHERE scope_row.pay_batch_id IS NOT NULL), '[]'::jsonb)
  INTO v_scope_count, v_invalid_scope_count, v_candidate_count, v_paye_scope_count, v_umbrella_scope_count,
       v_distinct_batch_count, v_paye_batch_count, v_umbrella_batch_count, v_scope_batch_ids
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id;

  SELECT COUNT(*)::integer INTO v_cross_channel_shared_batch_count
  FROM (
    SELECT scope_batch.pay_batch_id
    FROM public.banking_pay_operation_candidate_scope AS scope_batch
    WHERE scope_batch.operation_id = p_operation_id AND scope_batch.pay_batch_id IS NOT NULL
    GROUP BY scope_batch.pay_batch_id
    HAVING COUNT(DISTINCT UPPER(BTRIM(scope_batch.pay_channel))) > 1
  ) AS shared_batch;

  SELECT scope_batch.pay_batch_id INTO v_paye_batch_id
  FROM public.banking_pay_operation_candidate_scope AS scope_batch
  WHERE scope_batch.operation_id = p_operation_id AND UPPER(BTRIM(scope_batch.pay_channel)) = 'PAYE' AND scope_batch.pay_batch_id IS NOT NULL
  GROUP BY scope_batch.pay_batch_id ORDER BY scope_batch.pay_batch_id LIMIT 1;
  SELECT scope_batch.pay_batch_id INTO v_umbrella_batch_id
  FROM public.banking_pay_operation_candidate_scope AS scope_batch
  WHERE scope_batch.operation_id = p_operation_id AND UPPER(BTRIM(scope_batch.pay_channel)) = 'UMBRELLA' AND scope_batch.pay_batch_id IS NOT NULL
  GROUP BY scope_batch.pay_batch_id ORDER BY scope_batch.pay_batch_id LIMIT 1;

  SELECT COALESCE(jsonb_object_agg(status_count.status, status_count.row_count), '{}'::jsonb) INTO v_scope_status_counts
  FROM (
    SELECT scope_status.status, COUNT(*)::integer AS row_count
    FROM public.banking_pay_operation_candidate_scope AS scope_status
    WHERE scope_status.operation_id = p_operation_id
    GROUP BY scope_status.status
  ) AS status_count;

  IF COALESCE(v_invalid_scope_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_CANDIDATE_SCOPE_AUTHORITY_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_CANDIDATE_SCOPE_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'invalid_scope_count', v_invalid_scope_count, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF COALESCE(v_distinct_batch_count, 0) > 2 OR COALESCE(v_paye_batch_count, 0) > 1 OR COALESCE(v_umbrella_batch_count, 0) > 1 OR COALESCE(v_cross_channel_shared_batch_count, 0) > 0
     OR (v_operation_row.pay_batch_id IS NOT NULL AND COALESCE(v_distinct_batch_count, 0) > 0 AND NOT EXISTS (SELECT 1 FROM public.banking_pay_operation_candidate_scope AS primary_scope WHERE primary_scope.operation_id = p_operation_id AND primary_scope.pay_batch_id = v_operation_row.pay_batch_id)) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_SPLIT_BATCH_AUTHORITY_INVALID',
      DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_SPLIT_BATCH_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'distinct_pay_batch_count', COALESCE(v_distinct_batch_count, 0), 'paye_batch_count', COALESCE(v_paye_batch_count, 0), 'umbrella_batch_count', COALESCE(v_umbrella_batch_count, 0), 'cross_channel_shared_batch_count', COALESCE(v_cross_channel_shared_batch_count, 0), 'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  IF v_operation_row.phase NOT IN ('INITIALISE', 'VALIDATE_SESSION', 'SYNC_SELECTED_ROWS', 'WAIT_FOR_PREVIEW_READY', 'SEED_CANDIDATE_SCOPE') AND COALESCE(v_scope_count, 0) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_CANDIDATE_SCOPE_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_CANDIDATE_SCOPE_REQUIRED', 'operation_id', p_operation_id::text, 'phase', v_operation_row.phase, 'workbench_session_id', v_session_row.id::text)::text;
  END IF;

  v_post_shell_phase := UPPER(BTRIM(COALESCE(v_operation_row.phase, ''))) IN ('SEED_DRAFT_CHUNKS', 'INSERT_CANDIDATES', 'INSERT_ITEMS', 'APPLY_FINANCE_ADJUSTMENTS', 'FINALISE_RESERVATIONS', 'POPULATE_CANDIDATE_SUMMARIES', 'CREATE_TIMESHEET_SNAPSHOTS', 'BUILD_ITEM_BREAKDOWNS', 'ASSERT_INTEGRITY', 'POST_CREATE_REFRESH', 'COMPLETE');
  IF (v_post_shell_phase OR v_operation_status = 'COMPLETE') AND (
       (COALESCE(v_paye_scope_count, 0) > 0 AND COALESCE(v_paye_batch_count, 0) <> 1)
       OR (COALESCE(v_umbrella_scope_count, 0) > 0 AND COALESCE(v_umbrella_batch_count, 0) <> 1)
     ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_SPLIT_BATCH_REQUIRED', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_SPLIT_BATCH_REQUIRED', 'operation_id', p_operation_id::text, 'paye_scope_count', v_paye_scope_count, 'paye_batch_count', v_paye_batch_count, 'umbrella_scope_count', v_umbrella_scope_count, 'umbrella_batch_count', v_umbrella_batch_count)::text;
  END IF;

  PERFORM batch_row.id
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id OR batch_row.id IN (SELECT DISTINCT candidate_scope.pay_batch_id FROM public.banking_pay_operation_candidate_scope AS candidate_scope WHERE candidate_scope.operation_id = p_operation_id AND candidate_scope.pay_batch_id IS NOT NULL)
  ORDER BY batch_row.id FOR UPDATE OF batch_row;

  SELECT COALESCE(jsonb_agg(batch_row.id::text ORDER BY batch_row.id::text), '[]'::jsonb),
         COUNT(*) FILTER (
           WHERE batch_row.source_workbench_session_id IS DISTINCT FROM v_session_row.id
              OR batch_row.source_snapshot_run_id IS DISTINCT FROM v_expected_source_snapshot_run_id
              OR batch_row.source_session_version IS DISTINCT FROM v_expected_source_session_version
              OR batch_row.pay_date IS DISTINCT FROM p_pay_date
              OR EXISTS (
                SELECT 1
                FROM public.banking_pay_operation_candidate_scope AS batch_scope
                WHERE batch_scope.operation_id = p_operation_id
                  AND batch_scope.pay_batch_id = batch_row.id
                  AND (
                    NULLIF(UPPER(BTRIM(COALESCE(batch_row.batch_kind_fixed, ''))), '') IS NULL
                    OR UPPER(BTRIM(COALESCE(batch_scope.pay_channel, ''))) IS DISTINCT FROM UPPER(BTRIM(batch_row.batch_kind_fixed))
                  )
              )
              OR (NOT v_is_terminal AND (UPPER(BTRIM(COALESCE(batch_row.status, ''))) <> 'DRAFT' OR UPPER(BTRIM(COALESCE(batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'))
         )::integer
  INTO v_operation_batch_ids, v_invalid_batch_count
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id OR batch_row.id IN (SELECT DISTINCT candidate_scope.pay_batch_id FROM public.banking_pay_operation_candidate_scope AS candidate_scope WHERE candidate_scope.operation_id = p_operation_id AND candidate_scope.pay_batch_id IS NOT NULL);

  IF COALESCE(v_invalid_batch_count, 0) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DRAFT_CREATE_BATCH_AUTHORITY_INVALID', DETAIL = jsonb_build_object('ok', false, 'code', 'DRAFT_CREATE_BATCH_AUTHORITY_INVALID', 'operation_id', p_operation_id::text, 'workbench_session_id', v_session_row.id::text, 'pay_batch_ids', v_operation_batch_ids, 'invalid_batch_count', v_invalid_batch_count, 'refresh_required', NOT v_is_terminal, 'next_action', CASE WHEN v_is_terminal THEN NULL ELSE 'REFRESH_WORKBENCH' END)::text;
  END IF;

  RETURN jsonb_build_object(
    'ok', v_operation_status NOT IN ('FAILED', 'CANCELLED'),
    'operation_mode', true, 'legacy_unchunked_permanently_disabled', true, 'no_direct_batch_creation', true,
    'split_authority', 'OPERATION_CANDIDATE_SCOPE_PAY_CHANNEL', 'requires_operation_runner', v_requires_operation_runner, 'terminal', v_is_terminal,
    'operation_id', v_operation_row.id::text, 'operation_type', v_operation_row.operation_type, 'status', v_operation_row.status, 'phase', v_operation_row.phase,
    'actor_user_id', v_operation_row.actor_user_id::text, 'workbench_session_id', v_session_row.id::text,
    'workbench_session_version', v_expected_source_session_version, 'source_snapshot_run_id', CASE WHEN v_expected_source_snapshot_run_id IS NULL THEN NULL ELSE v_expected_source_snapshot_run_id::text END,
    'pay_date', v_session_row.pay_date::text, 'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'candidate_scope_count', COALESCE(v_scope_count, 0), 'candidate_count', COALESCE(v_candidate_count, 0),
    'paye_candidate_scope_count', COALESCE(v_paye_scope_count, 0), 'umbrella_candidate_scope_count', COALESCE(v_umbrella_scope_count, 0),
    'distinct_pay_batch_count', COALESCE(v_distinct_batch_count, 0), 'paye_pay_batch_count', COALESCE(v_paye_batch_count, 0), 'umbrella_pay_batch_count', COALESCE(v_umbrella_batch_count, 0),
    'paye_pay_batch_id', CASE WHEN v_paye_batch_id IS NULL THEN NULL ELSE v_paye_batch_id::text END, 'umbrella_pay_batch_id', CASE WHEN v_umbrella_batch_id IS NULL THEN NULL ELSE v_umbrella_batch_id::text END,
    'scope_status_counts', COALESCE(v_scope_status_counts, '{}'::jsonb), 'scope_pay_batch_ids', COALESCE(v_scope_batch_ids, '[]'::jsonb), 'operation_pay_batch_ids', COALESCE(v_operation_batch_ids, '[]'::jsonb),
    'pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
    'total_units', v_operation_row.total_units, 'completed_units', v_operation_row.completed_units, 'failed_units', v_operation_row.failed_units,
    'current_chunk_index', v_operation_row.current_chunk_index, 'chunk_count', v_operation_row.chunk_count,
    'progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
    'result_json', CASE WHEN v_operation_status IN ('COMPLETE', 'REVIEW_REQUIRED') THEN v_operation_row.result_json ELSE NULL END,
    'error_json', CASE WHEN v_operation_status IN ('FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN v_operation_row.error_json ELSE NULL END,
    'message', 'PAYE and UMBRELLA draft splitting is controlled by the scalable Banking Pay DRAFT_CREATE operation runner.'
  );
END;
$function$;

-- pay_execute_bank_transfer_chunk_prepare(uuid,uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_chunk_prepare(p_operation_id uuid, p_pay_batch_id uuid, p_transfer_scope_ids jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_chunk_id uuid := NULL::uuid;
  v_limit integer := 25;
  v_requested_count integer := 0;
  v_prepared_count integer := 0;
  v_reused_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_exists boolean := false;
  v_authorisation_ready_count integer := 0;
  v_item_transfer_linked_count integer := 0;
  v_item_transfer_reused_count integer := 0;
  v_item_transfer_conflict_count integer := 0;
  v_execution_mode_raw text := NULL::text;
  v_execution_mode text := NULL::text;
  v_is_local_manual_mode boolean := false;
  v_pay_channel_scope text := 'ALL';
  v_manual_confirmation_mode text := NULL::text;
  v_csv_uploaded_confirmed boolean := false;
  v_csv_bank_confirm_ref text := NULL::text;
  v_bank_csv_generated boolean := false;
  v_bank_csv_current boolean := false;
  v_bank_csv_scope text := NULL::text;
  v_bank_csv_paye_net_state_hash text := NULL::text;
  v_bank_csv_bank_payment_projection_hash text := NULL::text;
  v_bank_csv_row_count integer := NULL::integer;
  v_bank_csv_total_amount numeric(14,2) := NULL::numeric;
  v_external_settlement_comment text := NULL::text;
  v_payment_date text := NULL::text;
  v_mode_evidence_ready boolean := true;
  v_mode_evidence_code text := NULL::text;
  v_mode_evidence_message text := NULL::text;
  v_provider_scope_evidence_count integer := 0;
  v_provider_attempt_row_count integer := 0;
  v_provider_transfer_event_count integer := 0;
  v_provider_transfer_evidence_count integer := 0;
  v_provider_submit_chunk_count integer := 0;
  v_provider_boundary_evidence_count integer := 0;
  v_next_required_phase text := NULL::text;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PAY_BATCH_ID_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_ACTOR_REQUIRED', 'operation_id', p_operation_id::text)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL::text ELSE v_operation_row.pay_batch_id::text END, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  v_execution_mode_raw := upper(btrim(coalesce(v_operation_row.input_json->>'execution_mode', '')));
  v_execution_mode := CASE
    WHEN v_execution_mode_raw IN ('STANDARD_BANK', 'BANK') THEN 'STANDARD_BANK'
    WHEN v_execution_mode_raw IN ('CSV', 'CSV_SETTLEMENT') THEN 'CSV_SETTLEMENT'
    WHEN v_execution_mode_raw IN ('EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'EXTERNAL_SETTLEMENT'
    ELSE NULL::text
  END;

  IF v_execution_mode IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_EXECUTION_MODE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_EXECUTION_MODE_INVALID',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode_raw', NULLIF(v_execution_mode_raw, ''),
        'message', 'The durable payment execution mode is missing or unsupported.'
      )::text;
  END IF;

  v_is_local_manual_mode := v_execution_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT');
  v_pay_channel_scope := upper(btrim(coalesce(NULLIF(v_operation_row.input_json->>'pay_channel_scope', ''), 'ALL')));
  IF v_pay_channel_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;
  v_manual_confirmation_mode := upper(NULLIF(btrim(coalesce(v_operation_row.input_json->>'manual_confirmation_mode', '')), ''));
  v_csv_uploaded_confirmed := lower(btrim(coalesce(v_operation_row.input_json->>'csv_uploaded_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_csv_bank_confirm_ref := NULLIF(btrim(coalesce(v_operation_row.input_json->>'csv_bank_confirm_ref', '')), '');
  v_bank_csv_generated := lower(btrim(coalesce(v_operation_row.input_json->>'bank_csv_generated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_bank_csv_current := lower(btrim(coalesce(v_operation_row.input_json->>'bank_csv_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_bank_csv_scope := upper(NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_scope', '')), ''));
  v_bank_csv_paye_net_state_hash := NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_paye_net_state_hash', '')), '');
  v_bank_csv_bank_payment_projection_hash := NULLIF(btrim(coalesce(v_operation_row.input_json->>'bank_csv_bank_payment_projection_hash', '')), '');
  IF coalesce(v_operation_row.input_json->>'bank_csv_row_count', '') ~ '^[0-9]+$' THEN
    v_bank_csv_row_count := (v_operation_row.input_json->>'bank_csv_row_count')::integer;
  END IF;
  IF coalesce(v_operation_row.input_json->>'bank_csv_total_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_bank_csv_total_amount := round((v_operation_row.input_json->>'bank_csv_total_amount')::numeric, 2)::numeric(14,2);
  END IF;
  v_external_settlement_comment := NULLIF(btrim(coalesce(v_operation_row.input_json->>'external_settlement_comment', '')), '');
  v_payment_date := NULLIF(btrim(coalesce(v_operation_row.input_json->>'payment_date', '')), '');

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF v_is_local_manual_mode THEN
    SELECT count(*)::integer
    INTO v_provider_scope_evidence_count
    FROM public.banking_pay_operation_transfer_scope AS provider_scope
    WHERE provider_scope.operation_id = p_operation_id
      AND provider_scope.pay_batch_id = p_pay_batch_id
      AND (
        coalesce(provider_scope.provider_submit_ready, false) = true
        OR upper(btrim(coalesce(provider_scope.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
        OR provider_scope.provider_submit_chunk_id IS NOT NULL
        OR provider_scope.provider_submit_claimed_at_utc IS NOT NULL
        OR coalesce(provider_scope.provider_submit_attempt_count, 0) > 0
        OR NULLIF(btrim(coalesce(provider_scope.provider_idempotency_key, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_transaction_id, '')), '') IS NOT NULL
        OR provider_scope.provider_request_prepared_at_utc IS NOT NULL
        OR provider_scope.provider_request_sending_at_utc IS NOT NULL
        OR provider_scope.provider_request_sent_at_utc IS NOT NULL
        OR provider_scope.provider_response_at_utc IS NOT NULL
        OR NULLIF(btrim(coalesce(provider_scope.provider_submission_status, '')), '') IS NOT NULL
      );

    SELECT count(*)::integer
    INTO v_provider_attempt_row_count
    FROM public.banking_pay_operation_provider_attempts AS provider_attempt
    WHERE provider_attempt.operation_id = p_operation_id
       OR provider_attempt.pay_batch_id = p_pay_batch_id;

    SELECT count(*)::integer
    INTO v_provider_transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE transfer_event.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(transfer_event.event_source, ''))) IN ('PROVIDER_WEBHOOK', 'PROVIDER_POLL', 'PROVIDER_RESPONSE')
        OR NULLIF(btrim(coalesce(transfer_event.provider_request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_event.provider_transaction_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_event.provider_event_id, '')), '') IS NOT NULL
        OR transfer_event.provider_webhook_receipt_id IS NOT NULL
      );

    SELECT count(*)::integer
    INTO v_provider_transfer_evidence_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(transfer_row.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED')
        OR NULLIF(btrim(coalesce(transfer_row.request_id, '')), '') IS NOT NULL
        OR NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        OR transfer_row.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(transfer_row.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
        OR upper(btrim(coalesce(transfer_row.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
        OR upper(btrim(coalesce(transfer_row.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
        OR NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), '') IS NOT NULL
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      );

    SELECT count(*)::integer
    INTO v_provider_submit_chunk_count
    FROM public.banking_pay_operation_chunks AS provider_chunk
    WHERE provider_chunk.operation_id = p_operation_id
      AND (
        upper(btrim(coalesce(provider_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
        OR upper(btrim(coalesce(provider_chunk.phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'SEND_PROVIDER_CHUNK', 'REQUEST_PROVIDER_SEND', 'FINALISE_PROVIDER_CHUNK', 'APPLY_RAIL_UPDATES')
      );

    v_provider_boundary_evidence_count := coalesce(v_provider_scope_evidence_count, 0)
      + coalesce(v_provider_attempt_row_count, 0)
      + coalesce(v_provider_transfer_event_count, 0)
      + coalesce(v_provider_transfer_evidence_count, 0)
      + coalesce(v_provider_submit_chunk_count, 0);

    IF v_provider_boundary_evidence_count > 0 THEN
      UPDATE public.banking_pay_operations AS operation_review
      SET status = 'REVIEW_REQUIRED',
          phase = 'REVIEW_REQUIRED',
          runner_state = 'WAITING_USER_REVIEW',
          requires_user_action = true,
          resume_reason = 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
          progress_json = jsonb_strip_nulls(coalesce(operation_review.progress_json, '{}'::jsonb) || jsonb_build_object(
            'execution_mode', v_execution_mode,
            'provider_submission_required', false,
            'provider_submission_attempted', false,
            'submitted_to_bank', false,
            'review_required', true,
            'review_reason_code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
            'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
            'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
            'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
            'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
            'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
            'provider_boundary_evidence_count', v_provider_boundary_evidence_count,
            'next_required_phase', 'REVIEW_REQUIRED',
            'review_required_at_utc', v_now::text
          )),
          error_json = jsonb_strip_nulls(coalesce(operation_review.error_json, '{}'::jsonb) || jsonb_build_object(
            'code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
            'message', 'Local/manual settlement cannot continue because provider or bank-dispatch evidence already exists.',
            'operation_id', p_operation_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'execution_mode', v_execution_mode,
            'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
            'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
            'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
            'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
            'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
            'detected_at_utc', v_now::text
          )),
          updated_at_utc = v_now
      WHERE operation_review.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'hard_blocker', true,
        'code', 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE',
        'message', 'Local/manual settlement cannot continue because provider or bank-dispatch evidence already exists.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode,
        'provider_submission_required', false,
        'provider_submission_attempted', false,
        'submitted_to_bank', false,
        'provider_scope_evidence_count', coalesce(v_provider_scope_evidence_count, 0),
        'provider_attempt_row_count', coalesce(v_provider_attempt_row_count, 0),
        'provider_transfer_event_count', coalesce(v_provider_transfer_event_count, 0),
        'provider_transfer_evidence_count', coalesce(v_provider_transfer_evidence_count, 0),
        'provider_submit_chunk_count', coalesce(v_provider_submit_chunk_count, 0),
        'provider_boundary_evidence_count', v_provider_boundary_evidence_count,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
    END IF;

    IF v_execution_mode = 'CSV_SETTLEMENT' THEN
      v_mode_evidence_ready := v_bank_csv_generated
        AND v_bank_csv_current
        AND v_csv_uploaded_confirmed
        AND v_csv_bank_confirm_ref IS NOT NULL
        AND v_manual_confirmation_mode = 'BANK_UPLOAD_CONFIRMED'
        AND v_bank_csv_scope IS NOT DISTINCT FROM v_pay_channel_scope
        AND v_bank_csv_paye_net_state_hash IS NOT NULL
        AND v_bank_csv_bank_payment_projection_hash IS NOT NULL
        AND coalesce(v_bank_csv_row_count, 0) > 0
        AND coalesce(v_bank_csv_total_amount, 0) > 0
        AND v_payment_date IS NOT NULL;
      v_mode_evidence_code := 'CSV_SETTLEMENT_PROOF_REQUIRED';
      v_mode_evidence_message := 'CSV settlement requires the current CloudTMS CSV proof, upload confirmation, bank reference, and payment date before transfer evidence can be prepared.';
    ELSIF v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN
      v_mode_evidence_ready := v_external_settlement_comment IS NOT NULL
        AND v_manual_confirmation_mode = 'EXTERNAL_SETTLEMENT_CONFIRMED'
        AND v_payment_date IS NOT NULL;
      v_mode_evidence_code := 'EXTERNAL_SETTLEMENT_CONFIRMATION_REQUIRED';
      v_mode_evidence_message := 'External settlement requires the frozen external/manual confirmation comment, confirmation mode, and payment date before transfer evidence can be prepared.';
    END IF;

  END IF;

  IF p_transfer_scope_ids IS NOT NULL AND jsonb_typeof(p_transfer_scope_ids) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_PAYLOAD_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_PAYLOAD_DISABLED',
        'operation_id', p_operation_id::text,
        'message', 'Transfer chunk prepare is row-backed and chunk-owned. Pass a JSON object with chunk_id, or omit p_transfer_scope_ids so the database claims the next bounded scope page. Array/scalar transfer-scope payloads are disabled.'
      )::text;
  END IF;

  IF p_transfer_scope_ids IS NOT NULL AND jsonb_typeof(p_transfer_scope_ids) = 'object' THEN
    IF COALESCE(nullif(btrim(coalesce(p_transfer_scope_ids->>'chunk_id', p_transfer_scope_ids->>'chunkId', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_ID_REQUIRED'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
          'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_ID_REQUIRED',
          'operation_id', p_operation_id::text,
          'message', 'When p_transfer_scope_ids is supplied, it must be a JSON object containing a valid chunk_id. Omit p_transfer_scope_ids to let the database claim the next bounded scope page.'
        )::text;
    END IF;

    v_chunk_id := coalesce(p_transfer_scope_ids->>'chunk_id', p_transfer_scope_ids->>'chunkId')::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_scope_request;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_scope_request (
    transfer_scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  IF v_chunk_id IS NOT NULL THEN
    SELECT chunk_row.*
    INTO v_chunk_row
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.id = v_chunk_id
      AND chunk_row.operation_id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_CHUNK_NOT_FOUND', 'operation_id', p_operation_id::text, 'chunk_id', v_chunk_id::text)::text;
    END IF;

    INSERT INTO pg_temp.tmp_prepare_scope_request (transfer_scope_id)
    SELECT DISTINCT scope_text.transfer_scope_id_text::uuid
    FROM (
      SELECT chunk_scope.value #>> '{}' AS transfer_scope_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfer_scope_ids') = 'array' THEN v_chunk_row.payload_json->'transfer_scope_ids' ELSE '[]'::jsonb END) AS chunk_scope(value)
      UNION ALL
      SELECT coalesce(unit_value.value->>'transfer_scope_id', unit_value.value #>> '{unit,transfer_scope_id}') AS transfer_scope_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'units') = 'array' THEN v_chunk_row.payload_json->'units' ELSE '[]'::jsonb END) AS unit_value(value)
      UNION ALL
      SELECT v_chunk_row.payload_json->>'transfer_scope_id' AS transfer_scope_id_text
    ) AS scope_text
    WHERE nullif(btrim(coalesce(scope_text.transfer_scope_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    LIMIT v_limit;
  ELSE
    INSERT INTO pg_temp.tmp_prepare_scope_request (transfer_scope_id)
    SELECT scope_row.id
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) IN ('ROLLED_UP', 'PENDING')
      AND coalesce(scope_row.provider_review_required, false) = false
      AND coalesce(scope_row.prepared_item_count, 0) > 0
      AND nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
      AND (
        (
          v_execution_mode = 'STANDARD_BANK'
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
        OR (
          v_is_local_manual_mode
          AND coalesce(scope_row.provider_submit_ready, false) = false
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
      )
    ORDER BY scope_row.updated_at_utc NULLS FIRST, scope_row.id
    LIMIT v_limit
    FOR UPDATE SKIP LOCKED;
  END IF;

  SELECT count(*)::integer
  INTO v_requested_count
  FROM pg_temp.tmp_prepare_scope_request AS requested_scope;

  IF coalesce(v_requested_count, 0) <= 0 THEN
    v_next_required_phase := CASE
      WHEN v_execution_mode = 'STANDARD_BANK' THEN 'PROVIDER_SUBMIT_CLAIM'
      ELSE 'PREPARE_BATCH_PROOF'
    END;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
      'requested_scope_count', 0,
      'prepared_count', 0,
      'reused_count', 0,
      'failed_count', 0,
      'item_transfer_linked_count', 0,
      'item_transfer_reused_count', 0,
      'item_transfer_conflict_count', 0,
      'remaining_count', 0,
      'has_more', false,
      'execution_mode', v_execution_mode,
      'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'local_settlement_evidence_only', v_is_local_manual_mode,
      'next_required_phase', v_next_required_phase
    ) || jsonb_strip_nulls(jsonb_build_object(
      'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
      'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
      'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
      'bank_csv_scope', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_scope ELSE NULL::text END,
      'bank_csv_paye_net_state_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_paye_net_state_hash ELSE NULL::text END,
      'bank_csv_bank_payment_projection_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_bank_payment_projection_hash ELSE NULL::text END,
      'bank_csv_row_count', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_row_count ELSE NULL::integer END,
      'bank_csv_total_amount', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_total_amount ELSE NULL::numeric END,
      'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
      'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
      'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END
    ));
  END IF;


  IF v_is_local_manual_mode AND v_mode_evidence_ready IS NOT TRUE THEN
    UPDATE public.banking_pay_operations AS operation_review
    SET status = 'REVIEW_REQUIRED',
        phase = 'REVIEW_REQUIRED',
        runner_state = 'WAITING_USER_REVIEW',
        requires_user_action = true,
        resume_reason = v_mode_evidence_code,
        progress_json = jsonb_strip_nulls(coalesce(operation_review.progress_json, '{}'::jsonb) || jsonb_build_object(
          'execution_mode', v_execution_mode,
          'provider_submission_required', false,
          'provider_submission_attempted', false,
          'submitted_to_bank', false,
          'review_required', true,
          'review_reason_code', v_mode_evidence_code,
          'manual_confirmation_mode', v_manual_confirmation_mode,
          'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
          'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
          'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END,
          'next_required_phase', 'REVIEW_REQUIRED',
          'review_required_at_utc', v_now::text
        )),
        error_json = jsonb_strip_nulls(coalesce(operation_review.error_json, '{}'::jsonb) || jsonb_build_object(
          'code', v_mode_evidence_code,
          'message', v_mode_evidence_message,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'execution_mode', v_execution_mode,
          'manual_confirmation_mode', v_manual_confirmation_mode,
          'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
          'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
          'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
          'csv_bank_confirm_ref_present', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref IS NOT NULL ELSE NULL::boolean END,
          'external_settlement_comment_present', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment IS NOT NULL ELSE NULL::boolean END,
          'payment_date_present', v_payment_date IS NOT NULL,
          'detected_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE operation_review.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', false,
      'hard_blocker', true,
      'code', v_mode_evidence_code,
      'message', v_mode_evidence_message,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_mode', v_execution_mode,
      'provider_submission_required', false,
      'provider_submission_attempted', false,
      'submitted_to_bank', false,
      'manual_confirmation_mode', v_manual_confirmation_mode,
      'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
      'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
      'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
      'csv_bank_confirm_ref_present', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref IS NOT NULL ELSE NULL::boolean END,
      'external_settlement_comment_present', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment IS NOT NULL ELSE NULL::boolean END,
      'payment_date_present', v_payment_date IS NOT NULL,
      'next_required_phase', 'REVIEW_REQUIRED',
      'server_utc', v_now::text
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_scope_eval;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_scope_eval ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_batch_id,
         scope_row.pay_channel,
         scope_row.transfer_group_key,
         scope_row.candidate_id,
         scope_row.umbrella_id,
         scope_row.amount,
         coalesce(nullif(btrim(scope_row.currency), ''), 'GBP') AS currency,
         scope_row.payment_reference,
         scope_row.payee_name,
         scope_row.sort_code,
         scope_row.account_number,
         scope_row.account_type,
         scope_row.bank_details_hash_snapshot,
         scope_row.payee_entity_kind,
         scope_row.payee_entity_id,
         scope_row.grouping_mode_used,
         scope_row.week_ending_bucket,
         scope_row.request_id,
         scope_row.pay_bank_transfer_id,
         scope_row.prepared_item_count,
         scope_row.prepared_amount_total,
         scope_row.prepared_scope_hash,
         scope_row.prepared_result_hash,
         scope_row.provider_review_required,
         scope_row.provider_unsafe_reason,
         upper(btrim(coalesce(scope_row.status, ''))) AS current_scope_status,
         upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) AS current_provider_submit_state,
         CASE
           WHEN v_is_local_manual_mode AND (
             coalesce(scope_row.provider_submit_ready, false) = true
             OR upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY')
             OR scope_row.provider_submit_chunk_id IS NOT NULL
             OR scope_row.provider_submit_claimed_at_utc IS NOT NULL
             OR coalesce(scope_row.provider_submit_attempt_count, 0) > 0
             OR NULLIF(btrim(coalesce(scope_row.provider_idempotency_key, '')), '') IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_request_id, '')), '') IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_transaction_id, '')), '') IS NOT NULL
             OR scope_row.provider_request_prepared_at_utc IS NOT NULL
             OR scope_row.provider_request_sending_at_utc IS NOT NULL
             OR scope_row.provider_request_sent_at_utc IS NOT NULL
             OR scope_row.provider_response_at_utc IS NOT NULL
             OR NULLIF(btrim(coalesce(scope_row.provider_submission_status, '')), '') IS NOT NULL
           ) THEN 'LOCAL_MANUAL_SETTLEMENT_PROVIDER_BOUNDARY_EVIDENCE'
           WHEN upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('CLAIMED', 'REQUEST_PREPARING', 'REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED') THEN 'TRANSFER_SCOPE_PROVIDER_SUBMISSION_ALREADY_STARTED'
           WHEN upper(btrim(coalesce(scope_row.status, ''))) IN ('SUBMITTED', 'COMPLETED', 'COMPLETE') THEN 'TRANSFER_SCOPE_ALREADY_SUBMITTED'
           WHEN existing_transfer.id IS NOT NULL
            AND (
              upper(btrim(coalesce(existing_transfer.status, ''))) NOT IN ('PENDING', 'BLOCKED', 'FAILED', 'VOIDED')
              OR (v_is_local_manual_mode AND nullif(btrim(coalesce(existing_transfer.request_id, '')), '') IS NOT NULL)
              OR nullif(btrim(coalesce(existing_transfer.rail_tx_id, '')), '') IS NOT NULL
              OR existing_transfer.completed_at_utc IS NOT NULL
              OR (
                CASE
                  WHEN v_is_local_manual_mode THEN upper(btrim(coalesce(existing_transfer.rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
                  ELSE upper(btrim(coalesce(existing_transfer.rail_state, ''))) NOT IN ('', 'PENDING')
                END
              )
              OR upper(btrim(coalesce(existing_transfer.failed_reason, ''))) IN ('PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'PROVIDER_OUTCOME_UNKNOWN', 'REQUEST_SENT_LOCAL')
              OR upper(btrim(coalesce(existing_transfer.rail_meta_json->>'provider_stage', ''))) IN ('REQUEST_SENDING', 'REQUEST_SENT_LOCAL', 'PROVIDER_ACCEPTED', 'PROVIDER_REJECTED', 'PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'CHUNK_FINALISED')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            ) THEN 'EXISTING_TRANSFER_PROVIDER_EVIDENCE_PRESENT'
           WHEN coalesce(scope_row.provider_review_required, false) THEN 'PROVIDER_REVIEW_REQUIRED'
           WHEN coalesce(scope_row.prepared_item_count, 0) <= 0 THEN 'TRANSFER_SCOPE_NO_PREPARED_ITEMS'
           WHEN v_is_local_manual_mode AND nullif(btrim(coalesce(scope_row.prepared_scope_hash, '')), '') IS NULL THEN 'TRANSFER_SCOPE_PREPARED_SCOPE_PROOF_MISSING'
           WHEN nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NULL THEN 'TRANSFER_SCOPE_PREPARED_PROOF_MISSING'
           WHEN round(coalesce(scope_row.prepared_amount_total, 0), 2) = 0 THEN 'TRANSFER_SCOPE_ZERO_AMOUNT'
           ELSE NULL::text
         END AS blocker_code
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_prepare_scope_request AS requested_scope
    ON requested_scope.transfer_scope_id = scope_row.id
  LEFT JOIN public.pay_bank_transfers AS existing_transfer
    ON existing_transfer.pay_batch_id = scope_row.pay_batch_id
   AND existing_transfer.pay_channel = scope_row.pay_channel
   AND existing_transfer.transfer_group_key = scope_row.transfer_group_key
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id;

  IF (SELECT count(*) FROM pg_temp.tmp_prepare_scope_eval AS eval_row) <> v_requested_count THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_SCOPE_MISMATCH', 'operation_id', p_operation_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_prepare_scope_eval AS eval_row
    WHERE eval_row.blocker_code IN ('TRANSFER_SCOPE_PROVIDER_SUBMISSION_ALREADY_STARTED', 'TRANSFER_SCOPE_ALREADY_SUBMITTED')
  ) THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_CHUNK_PREPARE_PROVIDER_STATE_ALREADY_STARTED',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'message', 'Transfer chunk prepare cannot run against a scope after provider submission has started or completed. Reconcile provider state instead of preparing/resending.'
      )::text;
  END IF;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET status = 'FAILED',
      provider_submit_ready = false,
      provider_submit_state = 'REVIEW_REQUIRED',
      provider_review_required = true,
      provider_unsafe_reason = coalesce(eval_row.blocker_code, 'TRANSFER_SCOPE_NOT_PREPARABLE'),
      updated_at_utc = v_now
  FROM pg_temp.tmp_prepare_scope_eval AS eval_row
  WHERE scope_update.id = eval_row.transfer_scope_id
    AND eval_row.blocker_code IS NOT NULL;

  GET DIAGNOSTICS v_failed_count = ROW_COUNT;

  WITH preparable_scope AS (
    SELECT eval_row.*
    FROM pg_temp.tmp_prepare_scope_eval AS eval_row
    WHERE eval_row.blocker_code IS NULL
  ), upserted_transfers AS (
    INSERT INTO public.pay_bank_transfers (
      pay_batch_id,
      candidate_id,
      umbrella_id,
      pay_channel,
      amount,
      currency,
      status,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      created_at_utc,
      completed_at_utc,
      failed_reason,
      rail_provider,
      rail_env,
      request_id,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket
    )
    SELECT preparable_scope.pay_batch_id,
           preparable_scope.candidate_id,
           preparable_scope.umbrella_id,
           preparable_scope.pay_channel,
           round(coalesce(preparable_scope.prepared_amount_total, preparable_scope.amount, 0), 2),
           preparable_scope.currency,
           'PENDING',
           preparable_scope.payment_reference,
           preparable_scope.payee_name,
           CASE
             WHEN regexp_replace(coalesce(preparable_scope.sort_code, ''), '[^0-9]', '', 'g') ~ '^[0-9]{6}$' THEN regexp_replace(
               regexp_replace(coalesce(preparable_scope.sort_code, ''), '[^0-9]', '', 'g'),
               '^([0-9]{2})([0-9]{2})([0-9]{2})$',
               '\1-\2-\3'
             )
             ELSE NULL::text
           END,
           regexp_replace(coalesce(preparable_scope.account_number, ''), '[^0-9]', '', 'g'),
           preparable_scope.account_type,
           v_now,
           NULL::timestamptz,
           NULL::text,
           v_batch_row.rail_provider_snapshot,
           v_batch_row.rail_env_snapshot,
           CASE
             WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(preparable_scope.request_id), ''), 'op:' || p_operation_id::text || ':scope:' || preparable_scope.transfer_scope_id::text)
             ELSE NULL::text
           END,
           NULL::text,
           NULL::text,
           jsonb_build_object(
             'operation_id', p_operation_id::text,
             'transfer_scope_id', preparable_scope.transfer_scope_id::text,
             'prepared_at_utc', v_now::text,
             'prepared_result_hash', preparable_scope.prepared_result_hash
           ) || CASE
             WHEN v_is_local_manual_mode THEN jsonb_build_object(
               'execution_mode', v_execution_mode,
               'local_settlement_evidence_only', true,
               'provider_submission_required', false,
               'provider_submission_attempted', false,
               'submitted_to_bank', false
             )
             ELSE '{}'::jsonb
           END,
           preparable_scope.bank_details_hash_snapshot,
           preparable_scope.payee_entity_kind,
           preparable_scope.payee_entity_id,
           preparable_scope.transfer_group_key,
           preparable_scope.grouping_mode_used,
           preparable_scope.week_ending_bucket
    FROM preparable_scope
    ON CONFLICT (pay_batch_id, pay_channel, transfer_group_key)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        umbrella_id = EXCLUDED.umbrella_id,
        amount = EXCLUDED.amount,
        currency = EXCLUDED.currency,
        status = CASE WHEN public.pay_bank_transfers.status IN ('PENDING', 'BLOCKED', 'FAILED') THEN 'PENDING' ELSE public.pay_bank_transfers.status END,
        payment_reference = EXCLUDED.payment_reference,
        payee_name = EXCLUDED.payee_name,
        sort_code = EXCLUDED.sort_code,
        account_number = EXCLUDED.account_number,
        account_type = EXCLUDED.account_type,
        rail_provider = EXCLUDED.rail_provider,
        rail_env = EXCLUDED.rail_env,
        request_id = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(public.pay_bank_transfers.request_id, ''), EXCLUDED.request_id)
          ELSE public.pay_bank_transfers.request_id
        END,
        rail_meta_json = jsonb_strip_nulls(coalesce(public.pay_bank_transfers.rail_meta_json, '{}'::jsonb) || coalesce(EXCLUDED.rail_meta_json, '{}'::jsonb)),
        bank_details_hash_snapshot = EXCLUDED.bank_details_hash_snapshot,
        payee_entity_kind = EXCLUDED.payee_entity_kind,
        payee_entity_id = EXCLUDED.payee_entity_id,
        grouping_mode_used = EXCLUDED.grouping_mode_used,
        week_ending_bucket = EXCLUDED.week_ending_bucket
    WHERE public.pay_bank_transfers.status IN ('PENDING', 'BLOCKED', 'FAILED')
    RETURNING public.pay_bank_transfers.id,
              public.pay_bank_transfers.pay_batch_id,
              public.pay_bank_transfers.pay_channel,
              public.pay_bank_transfers.transfer_group_key,
              (xmax = 0) AS was_inserted
  ), linked_scope AS (
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET status = 'PREPARED',
        pay_bank_transfer_id = upserted_transfers.id,
        amount = round(coalesce(eval_row.prepared_amount_total, scope_update.amount, 0), 2),
        provider_submit_ready = CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN true ELSE false END,
        provider_submit_state = CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN 'READY' ELSE 'NOT_READY' END,
        provider_review_required = false,
        provider_unsafe_reason = NULL::text,
        provider_idempotency_key = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(scope_update.provider_idempotency_key), ''), coalesce(nullif(btrim(scope_update.request_id), ''), 'scope:' || scope_update.id::text))
          ELSE NULL::text
        END,
        provider_request_id = CASE
          WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(nullif(btrim(scope_update.provider_request_id), ''), upserted_transfers.id::text)
          ELSE NULL::text
        END,
        updated_at_utc = v_now
    FROM upserted_transfers
    JOIN pg_temp.tmp_prepare_scope_eval AS eval_row
      ON eval_row.pay_batch_id = upserted_transfers.pay_batch_id
     AND eval_row.pay_channel = upserted_transfers.pay_channel
     AND eval_row.transfer_group_key = upserted_transfers.transfer_group_key
    WHERE scope_update.id = eval_row.transfer_scope_id
      AND eval_row.blocker_code IS NULL
    RETURNING scope_update.id,
              upserted_transfers.was_inserted
  )
  SELECT count(*) FILTER (WHERE linked_scope.was_inserted)::integer,
         count(*) FILTER (WHERE linked_scope.was_inserted IS NOT TRUE)::integer
  INTO v_prepared_count,
       v_reused_count
  FROM linked_scope;

  DROP TABLE IF EXISTS pg_temp.tmp_prepare_item_transfer_link;
  CREATE TEMPORARY TABLE pg_temp.tmp_prepare_item_transfer_link ON COMMIT DROP AS
  SELECT DISTINCT
         scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id AS pay_bank_transfer_id,
         scope_item_row.pay_batch_item_id AS pay_batch_item_id,
         batch_item.pay_bank_transfer_id AS existing_pay_bank_transfer_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_prepare_scope_eval AS eval_row
    ON eval_row.transfer_scope_id = scope_row.id
   AND eval_row.blocker_code IS NULL
  JOIN public.banking_pay_operation_transfer_scope_items AS scope_item_row
    ON scope_item_row.operation_id = p_operation_id
   AND scope_item_row.pay_batch_id = p_pay_batch_id
   AND scope_item_row.transfer_scope_id = scope_row.id
  JOIN public.pay_batch_items AS batch_item
    ON batch_item.id = scope_item_row.pay_batch_item_id
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id = batch_item.pay_batch_candidate_id
   AND batch_candidate.pay_batch_id = p_pay_batch_id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND scope_row.pay_bank_transfer_id IS NOT NULL
    AND COALESCE(batch_item.is_voided, false) = false;

  SELECT COUNT(*) FILTER (
           WHERE link_row.existing_pay_bank_transfer_id IS NOT NULL
             AND link_row.existing_pay_bank_transfer_id <> link_row.pay_bank_transfer_id
         )::integer,
         COUNT(*) FILTER (
           WHERE link_row.existing_pay_bank_transfer_id = link_row.pay_bank_transfer_id
         )::integer
  INTO v_item_transfer_conflict_count,
       v_item_transfer_reused_count
  FROM pg_temp.tmp_prepare_item_transfer_link AS link_row;

  -- Preserve the exact cause of the following pay_batch_items statement.  The
  -- normal financial-scope trigger must still dirty the candidate; this
  -- transaction-local envelope lets that trigger prove that the only change
  -- was the execution owner's provider-unsubmitted transfer link.
  DROP TABLE IF EXISTS pg_temp._bpay_wb_unsent_execution_overlay_context_v1;
  CREATE TEMPORARY TABLE pg_temp._bpay_wb_unsent_execution_overlay_context_v1 (
    contract_version text NOT NULL,
    execution_operation_id uuid NOT NULL,
    pay_batch_id uuid NOT NULL,
    pay_batch_candidate_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid,
    pay_batch_item_id uuid NOT NULL,
    pay_bank_transfer_id uuid NOT NULL,
    transfer_scope_id uuid NOT NULL,
    source_workbench_session_id uuid,
    source_snapshot_run_id uuid,
    source_session_version bigint,
    row_context_digest text NOT NULL,
    created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_wb_unsent_execution_overlay_context_v1 (
    contract_version,execution_operation_id,pay_batch_id,pay_batch_candidate_id,
    candidate_id,timesheet_id,pay_batch_item_id,pay_bank_transfer_id,
    transfer_scope_id,source_workbench_session_id,source_snapshot_run_id,
    source_session_version,row_context_digest,created_at_utc
  )
  SELECT
    'EXECUTION_UNSENT_OVERLAY_CONTEXT_V1',p_operation_id,p_pay_batch_id,
    batch_item.pay_batch_candidate_id,batch_candidate.candidate_id,
    batch_item.timesheet_id,link_row.pay_batch_item_id,link_row.pay_bank_transfer_id,
    link_row.transfer_scope_id,v_batch_row.source_workbench_session_id,
    v_batch_row.source_snapshot_run_id,v_batch_row.source_session_version,
    md5(
      p_operation_id::text||'|'||p_pay_batch_id::text||'|'||
      batch_candidate.candidate_id::text||'|'||batch_item.pay_batch_candidate_id::text||'|'||
      link_row.pay_batch_item_id::text||'|'||COALESCE(batch_item.timesheet_id::text,'')||'|'||
      link_row.transfer_scope_id::text||'|'||link_row.pay_bank_transfer_id::text||'|'||
      COALESCE(v_batch_row.source_workbench_session_id::text,'')||'|'||
      COALESCE(v_batch_row.source_snapshot_run_id::text,'')||'|'||
      COALESCE(v_batch_row.source_session_version::text,'')||
      '|EXECUTION_UNSENT_OVERLAY_CONTEXT_V1'
    ),v_now
  FROM pg_temp.tmp_prepare_item_transfer_link AS link_row
  JOIN public.pay_batch_items AS batch_item ON batch_item.id=link_row.pay_batch_item_id
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.id=batch_item.pay_batch_candidate_id
   AND batch_candidate.pay_batch_id=p_pay_batch_id
  WHERE batch_item.pay_bank_transfer_id IS NULL
    AND link_row.pay_bank_transfer_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM pg_temp.tmp_prepare_item_transfer_link AS conflict_row
      WHERE conflict_row.pay_batch_item_id=link_row.pay_batch_item_id
        AND conflict_row.existing_pay_bank_transfer_id IS NOT NULL
        AND conflict_row.existing_pay_bank_transfer_id<>conflict_row.pay_bank_transfer_id
    );

  WITH linked_batch_items AS (
    UPDATE public.pay_batch_items AS batch_item_update
    SET pay_bank_transfer_id = link_row.pay_bank_transfer_id,
        updated_at = v_now
    FROM pg_temp.tmp_prepare_item_transfer_link AS link_row
    WHERE batch_item_update.id = link_row.pay_batch_item_id
      AND batch_item_update.pay_bank_transfer_id IS NULL
      AND link_row.pay_bank_transfer_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_prepare_item_transfer_link AS conflict_row
        WHERE conflict_row.pay_batch_item_id = link_row.pay_batch_item_id
          AND conflict_row.existing_pay_bank_transfer_id IS NOT NULL
          AND conflict_row.existing_pay_bank_transfer_id <> conflict_row.pay_bank_transfer_id
      )
    RETURNING batch_item_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_item_transfer_linked_count
  FROM linked_batch_items;

  IF COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_conflict_update
    SET status = 'FAILED',
        provider_submit_ready = false,
        provider_submit_state = 'REVIEW_REQUIRED',
        provider_review_required = true,
        provider_unsafe_reason = 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT',
        updated_at_utc = v_now
    FROM (
      SELECT DISTINCT conflict_link.transfer_scope_id
      FROM pg_temp.tmp_prepare_item_transfer_link AS conflict_link
      WHERE conflict_link.existing_pay_bank_transfer_id IS NOT NULL
        AND conflict_link.existing_pay_bank_transfer_id <> conflict_link.pay_bank_transfer_id
    ) AS conflict_scope
    WHERE scope_conflict_update.id = conflict_scope.transfer_scope_id
      AND scope_conflict_update.operation_id = p_operation_id
      AND scope_conflict_update.pay_batch_id = p_pay_batch_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(scope_row.status, ''))) IN ('ROLLED_UP', 'PENDING')
      AND coalesce(scope_row.provider_review_required, false) = false
      AND coalesce(scope_row.prepared_item_count, 0) > 0
      AND nullif(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
      AND round(coalesce(scope_row.prepared_amount_total, 0), 2) <> 0
      AND (
        (
          v_execution_mode = 'STANDARD_BANK'
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
        OR (
          v_is_local_manual_mode
          AND coalesce(scope_row.provider_submit_ready, false) = false
          AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        )
      )
    LIMIT 1
  )
  INTO v_remaining_exists;

  SELECT count(*)::integer
  INTO v_authorisation_ready_count
  FROM pg_temp.tmp_prepare_scope_eval AS eval_row
  JOIN public.banking_pay_operation_transfer_scope AS scope_row
    ON scope_row.id = eval_row.transfer_scope_id
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = scope_row.pay_bank_transfer_id
   AND transfer_row.pay_batch_id = scope_row.pay_batch_id
  WHERE upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
    AND scope_row.pay_bank_transfer_id IS NOT NULL
    AND (
      (
        v_execution_mode = 'STANDARD_BANK'
        AND coalesce(scope_row.provider_submit_ready, false) = true
        AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY'
      )
      OR (
        v_is_local_manual_mode
        AND v_mode_evidence_ready
        AND coalesce(scope_row.provider_submit_ready, false) = false
        AND upper(btrim(coalesce(scope_row.provider_submit_state, 'NOT_READY'))) IN ('', 'NOT_READY')
        AND coalesce(scope_row.provider_review_required, false) = false
        AND NULLIF(btrim(coalesce(scope_row.provider_unsafe_reason, '')), '') IS NULL
        AND coalesce(scope_row.prepared_item_count, 0) > 0
        AND NULLIF(btrim(coalesce(scope_row.prepared_scope_hash, '')), '') IS NOT NULL
        AND NULLIF(btrim(coalesce(scope_row.prepared_result_hash, '')), '') IS NOT NULL
        AND round(coalesce(scope_row.prepared_amount_total, 0), 2) = round(coalesce(scope_row.amount, 0), 2)
        AND round(coalesce(scope_row.prepared_amount_total, 0), 2) > 0
        AND upper(btrim(coalesce(transfer_row.status, ''))) = 'PENDING'
        AND transfer_row.pay_channel = scope_row.pay_channel
        AND transfer_row.transfer_group_key = scope_row.transfer_group_key
        AND round(coalesce(transfer_row.amount, 0), 2) = round(coalesce(scope_row.amount, 0), 2)
        AND upper(btrim(coalesce(transfer_row.currency, 'GBP'))) = upper(btrim(coalesce(scope_row.currency, 'GBP')))
        AND NULLIF(btrim(coalesce(transfer_row.request_id, '')), '') IS NULL
        AND NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NULL
        AND transfer_row.completed_at_utc IS NULL
        AND NULLIF(btrim(coalesce(transfer_row.failed_reason, '')), '') IS NULL
        AND upper(btrim(coalesce(transfer_row.rail_state, ''))) IN ('', 'LOCAL', 'PENDING')
        AND (
          SELECT count(*)
          FROM public.banking_pay_operation_transfer_scope_items AS scope_item_count
          WHERE scope_item_count.operation_id = p_operation_id
            AND scope_item_count.pay_batch_id = p_pay_batch_id
            AND scope_item_count.transfer_scope_id = scope_row.id
        ) = coalesce(scope_row.prepared_item_count, 0)
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope_items AS scope_item_check
          JOIN public.pay_batch_items AS batch_item_check
            ON batch_item_check.id = scope_item_check.pay_batch_item_id
          WHERE scope_item_check.operation_id = p_operation_id
            AND scope_item_check.pay_batch_id = p_pay_batch_id
            AND scope_item_check.transfer_scope_id = scope_row.id
            AND batch_item_check.pay_bank_transfer_id IS DISTINCT FROM scope_row.pay_bank_transfer_id
        )
      )
    );

  v_next_required_phase := CASE
    WHEN coalesce(v_item_transfer_conflict_count, 0) > 0 OR coalesce(v_failed_count, 0) > 0 THEN 'REVIEW_REQUIRED'
    WHEN v_remaining_exists THEN 'TRANSFER_CHUNK_PREPARE_PAGE'
    WHEN v_execution_mode = 'STANDARD_BANK' THEN 'PROVIDER_SUBMIT_CLAIM'
    ELSE 'PREPARE_BATCH_PROOF'
  END;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'REVIEW_REQUIRED' ELSE operation_update.status END,
      phase = CASE
        WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'REVIEW_REQUIRED'
        WHEN v_remaining_exists THEN 'PREPARE_TRANSFER_CHUNKS'
        WHEN v_execution_mode = 'STANDARD_BANK' THEN 'CLAIM_PROVIDER_SUBMIT'
        ELSE 'PREPARE_BATCH_PROOF'
      END,
      runner_state = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'WAITING_USER_REVIEW' ELSE operation_update.runner_state END,
      requires_user_action = CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN true ELSE operation_update.requires_user_action END,
      progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'last_transfer_chunk_prepare_at_utc', v_now::text,
        'last_transfer_chunk_prepare_scope_count', coalesce(v_requested_count, 0),
        'last_transfer_chunk_prepare_ready_count', coalesce(v_authorisation_ready_count, 0),
        'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
        'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
        'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
        'execution_mode', v_execution_mode,
        'provider_submission_required', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'provider_submission_attempted', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'submitted_to_bank', CASE WHEN v_is_local_manual_mode THEN false ELSE NULL::boolean END,
        'local_settlement_evidence_only', CASE WHEN v_is_local_manual_mode THEN true ELSE NULL::boolean END,
        'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
        'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
        'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
        'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END,
        'review_required', CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN true ELSE NULL::boolean END,
        'review_reason_code', CASE WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT' ELSE NULL::text END,
        'next_required_phase', v_next_required_phase
      )),
      error_json = CASE
        WHEN COALESCE(v_item_transfer_conflict_count, 0) > 0 THEN jsonb_strip_nulls(coalesce(operation_update.error_json, '{}'::jsonb) || jsonb_build_object(
          'code', 'PAY_BATCH_ITEM_TRANSFER_LINK_CONFLICT',
          'message', CASE
            WHEN v_is_local_manual_mode THEN 'One or more frozen pay batch items are already linked to a different bank transfer. Local/manual settlement evidence preparation has been blocked for the affected transfer scope.'
            ELSE 'One or more frozen pay batch items are already linked to a different bank transfer. Provider submission has been blocked for the affected transfer scope.'
          END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
          'detected_at_utc', v_now::text
        ))
        ELSE operation_update.error_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', coalesce(v_failed_count, 0) = 0 AND COALESCE(v_item_transfer_conflict_count, 0) = 0,
    'hard_blocker', coalesce(v_failed_count, 0) > 0 OR COALESCE(v_item_transfer_conflict_count, 0) > 0,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
    'requested_scope_count', coalesce(v_requested_count, 0),
    'prepared_count', coalesce(v_prepared_count, 0),
    'reused_count', coalesce(v_reused_count, 0),
    'authorisation_ready_count', coalesce(v_authorisation_ready_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'item_transfer_linked_count', COALESCE(v_item_transfer_linked_count, 0),
    'item_transfer_reused_count', COALESCE(v_item_transfer_reused_count, 0),
    'item_transfer_conflict_count', COALESCE(v_item_transfer_conflict_count, 0),
    'remaining_count', CASE WHEN v_remaining_exists THEN 1 ELSE 0 END,
    'has_more', v_remaining_exists,
    'execution_mode', v_execution_mode,
    'provider_submission_required', v_execution_mode = 'STANDARD_BANK',
    'provider_submission_attempted', false,
    'submitted_to_bank', false,
    'provider_submit_ready', CASE WHEN v_execution_mode = 'STANDARD_BANK' THEN coalesce(v_authorisation_ready_count, 0) > 0 ELSE false END,
    'local_settlement_evidence_only', v_is_local_manual_mode,
    'next_required_phase', v_next_required_phase,
    'server_utc', v_now::text
  ) || jsonb_strip_nulls(jsonb_build_object(
    'manual_confirmation_mode', CASE WHEN v_is_local_manual_mode THEN v_manual_confirmation_mode ELSE NULL::text END,
    'bank_csv_generated', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_generated ELSE NULL::boolean END,
    'bank_csv_current', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_current ELSE NULL::boolean END,
    'bank_csv_scope', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_scope ELSE NULL::text END,
    'bank_csv_paye_net_state_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_paye_net_state_hash ELSE NULL::text END,
    'bank_csv_bank_payment_projection_hash', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_bank_payment_projection_hash ELSE NULL::text END,
    'bank_csv_row_count', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_row_count ELSE NULL::integer END,
    'bank_csv_total_amount', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_bank_csv_total_amount ELSE NULL::numeric END,
    'csv_uploaded_confirmed', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_uploaded_confirmed ELSE NULL::boolean END,
    'csv_bank_confirm_ref', CASE WHEN v_execution_mode = 'CSV_SETTLEMENT' THEN v_csv_bank_confirm_ref ELSE NULL::text END,
    'external_settlement_comment', CASE WHEN v_execution_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL::text END
  ));
END;
$function$;

-- pay_execute_bank_transfer_scope_items_seed_chunk(uuid,uuid,jsonb,integer,uuid)
CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_items_seed_chunk(p_operation_id uuid, p_transfer_scope_id uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_scope_row public.banking_pay_operation_transfer_scope%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_last_pay_batch_item_id uuid := NULL::uuid;
  v_last_item_ordinal bigint := 0;
  v_page_count integer := 0;
  v_seeded_count integer := 0;
  v_page_error_count integer := 0;
  v_has_more boolean := false;
  v_seed_complete boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_seed_proof_hash text := NULL::text;
  v_membership_count bigint := 0;
  v_no_source boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_transfer_scope_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_ID_REQUIRED')::text;
  END IF;

  IF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_CURSOR_MUST_BE_OBJECT')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.id = p_transfer_scope_id
    AND scope_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_SCOPE_NOT_FOUND', 'operation_id', p_operation_id::text, 'transfer_scope_id', p_transfer_scope_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_scope_row.pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'scope_pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY', 'READY', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_PROVIDER_STATE_ALREADY_STARTED', 'transfer_scope_id', p_transfer_scope_id::text, 'provider_submit_state', v_scope_row.provider_submit_state)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_scope_row.pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ITEMS_SEED_BATCH_NOT_FOUND', 'pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF nullif(btrim(coalesce(p_cursor->>'last_pay_batch_item_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_pay_batch_item_id := (p_cursor->>'last_pay_batch_item_id')::uuid;
  END IF;
  IF nullif(btrim(coalesce(p_cursor->>'last_item_ordinal', '')), '') ~ '^[0-9]+$' THEN
    v_last_item_ordinal := (p_cursor->>'last_item_ordinal')::bigint;
  END IF;

  IF v_last_pay_batch_item_id IS NULL THEN
    SELECT existing_scope_item.pay_batch_item_id,
           existing_scope_item.item_ordinal
    INTO v_last_pay_batch_item_id,
         v_last_item_ordinal
    FROM public.banking_pay_operation_transfer_scope_items AS existing_scope_item
    WHERE existing_scope_item.operation_id = p_operation_id
      AND existing_scope_item.transfer_scope_id = p_transfer_scope_id
    ORDER BY existing_scope_item.item_ordinal DESC, existing_scope_item.pay_batch_item_id DESC
    LIMIT 1;

    IF NOT FOUND THEN
      v_last_pay_batch_item_id := NULL::uuid;
      v_last_item_ordinal := 0;
    END IF;
  END IF;

  v_last_item_ordinal := COALESCE(v_last_item_ordinal, 0);

  DROP TABLE IF EXISTS pg_temp.tmp_transfer_scope_item_seed_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_transfer_scope_item_seed_page ON COMMIT DROP AS
  WITH candidate_item_page AS (
    SELECT batch_item.id AS pay_batch_item_id,
           batch_item.pay_batch_candidate_id,
           batch_candidate.candidate_id,
           batch_candidate.net_bank_amount,
           COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS source_item_amount,
           batch_item.item_type,
           batch_item.is_voided,
           batch_item.payout_instruction_snapshot_json,
           row_number() OVER (ORDER BY batch_item.id)::bigint AS page_row_no
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_scope_row.pay_batch_id
      AND batch_candidate.candidate_id = v_scope_row.candidate_id
      AND coalesce(batch_item.is_voided, false) = false
      AND batch_item.item_type <> 'DEBT_CREATED'
      AND (v_last_pay_batch_item_id IS NULL OR batch_item.id > v_last_pay_batch_item_id)
      AND (
        (v_scope_row.pay_channel = 'PAYE' AND (CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END) = 'PAYE')
        OR (v_scope_row.pay_channel = 'UMBRELLA' AND (CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END) = 'UMBRELLA')
      )
      AND (
        CASE
          WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'PAYE'
            THEN batch_candidate.candidate_id::text
               || '|PAYE|'
               || COALESCE(
                    NULLIF(BTRIM(COALESCE(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''),
                    (
                      SELECT NULLIF(
                               BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'bank_details_hash', '')),
                               ''
                             )
                      FROM public.pay_batch_items AS fallback_item
                      WHERE fallback_item.pay_batch_candidate_id = batch_candidate.id
                        AND COALESCE(fallback_item.is_voided, false) = false
                        AND fallback_item.item_type <> 'DEBT_CREATED'
                        AND fallback_item.pay_channel = 'PAYE'
                        AND NULLIF(
                              BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'bank_details_hash', '')),
                              ''
                            ) IS NOT NULL
                      ORDER BY
                        CASE
                          WHEN NULLIF(
                                 BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'sort_code', '')),
                                 ''
                               ) IS NOT NULL
                           AND NULLIF(
                                 BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'account_number', '')),
                                 ''
                               ) IS NOT NULL
                            THEN 0
                          ELSE 1
                        END,
                        fallback_item.id
                      LIMIT 1
                    ),
                    ''
                  )
          WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'UMBRELLA'
            THEN batch_candidate.candidate_id::text || '|UMBRELLA|' || coalesce(CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket') ELSE 'NO_WEEK' END, 'NO_WEEK') || '|' || coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '') || '|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
          ELSE batch_candidate.candidate_id::text || '|OTHER|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
        END
      ) = v_scope_row.transfer_group_key
    ORDER BY batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT (COALESCE(v_last_item_ordinal, 0) + candidate_item_page.page_row_no)::bigint AS item_ordinal,
         candidate_item_page.pay_batch_item_id,
         candidate_item_page.pay_batch_candidate_id,
         candidate_item_page.candidate_id,
         round(
           CASE
             WHEN v_scope_row.pay_channel = 'PAYE' THEN CASE WHEN (COALESCE(v_last_item_ordinal, 0) + candidate_item_page.page_row_no) = 1 THEN coalesce(nullif(v_scope_row.amount, 0), candidate_item_page.net_bank_amount, 0) ELSE 0 END
             ELSE coalesce(candidate_item_page.source_item_amount, 0)
           END,
           2
         )::numeric(14,2) AS item_amount,
         CASE
           WHEN COALESCE(candidate_item_page.is_voided, false) THEN 'VOIDED'
           WHEN candidate_item_page.item_type = 'DEBT_CREATED' THEN 'IGNORED_DEBT_CREATED'
           WHEN v_scope_row.pay_channel <> 'PAYE'
            AND COALESCE(candidate_item_page.source_item_amount, 0) <> 0
            AND candidate_item_page.payout_instruction_snapshot_json IS NULL THEN 'PAYOUT_INSTRUCTION_MISSING'
           ELSE 'PENDING'
         END AS seed_status
  FROM candidate_item_page
  ORDER BY candidate_item_page.page_row_no;

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  WITH page_rows AS (
    SELECT page_row.*
    FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT v_limit
  ), upserted AS (
    INSERT INTO public.banking_pay_operation_transfer_scope_items (
      operation_id,
      pay_batch_id,
      transfer_scope_id,
      pay_batch_item_id,
      pay_batch_candidate_id,
      candidate_id,
      item_amount,
      item_status,
      item_ordinal,
      rollup_status,
      created_at_utc,
      updated_at_utc
    )
    SELECT p_operation_id,
           v_scope_row.pay_batch_id,
           p_transfer_scope_id,
           page_rows.pay_batch_item_id,
           page_rows.pay_batch_candidate_id,
           page_rows.candidate_id,
           page_rows.item_amount,
           page_rows.seed_status,
           page_rows.item_ordinal,
           'PENDING',
           v_now,
           v_now
    FROM page_rows
    ON CONFLICT (operation_id, transfer_scope_id, pay_batch_item_id)
    DO UPDATE
    SET pay_batch_id = EXCLUDED.pay_batch_id,
        pay_batch_candidate_id = EXCLUDED.pay_batch_candidate_id,
        candidate_id = EXCLUDED.candidate_id,
        item_amount = EXCLUDED.item_amount,
        item_status = CASE WHEN public.banking_pay_operation_transfer_scope_items.rollup_status IN ('ROLLED_UP', 'PREPARED', 'READY', 'COMPLETE', 'COMPLETED') THEN public.banking_pay_operation_transfer_scope_items.item_status ELSE EXCLUDED.item_status END,
        item_ordinal = EXCLUDED.item_ordinal,
        rollup_status = CASE WHEN public.banking_pay_operation_transfer_scope_items.rollup_status IN ('ROLLED_UP', 'PREPARED', 'READY', 'COMPLETE', 'COMPLETED') THEN public.banking_pay_operation_transfer_scope_items.rollup_status ELSE 'PENDING' END,
        updated_at_utc = v_now
    RETURNING item_status, item_ordinal, pay_batch_item_id
  )
  SELECT count(*)::integer,
         count(*) FILTER (WHERE upper(btrim(coalesce(upserted.item_status, ''))) IN ('VOIDED', 'PAYOUT_INSTRUCTION_MISSING', 'MISSING', 'ERROR'))::integer,
         max(upserted.item_ordinal)
  INTO v_seeded_count,
       v_page_error_count,
       v_membership_count
  FROM upserted;

  v_no_source := coalesce(v_seeded_count, 0) = 0 AND coalesce(v_last_item_ordinal, 0) = 0;
  v_seed_complete := coalesce(v_has_more, false) IS NOT TRUE;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_item_ordinal', page_row.item_ordinal,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_transfer_scope_item_seed_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT 1 OFFSET GREATEST(v_limit - 1, 0);
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_seed_proof_hash := md5(jsonb_build_object(
    'operation_id', p_operation_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'seeded_count', coalesce(v_seeded_count, 0),
    'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
    'seed_complete', coalesce(v_seed_complete, false),
    'has_more', coalesce(v_has_more, false)
  )::text);

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_ready = false,
      provider_submit_state = CASE WHEN coalesce(v_page_error_count, 0) > 0 OR v_no_source THEN 'REVIEW_REQUIRED' ELSE 'NOT_READY' END,
      provider_review_required = coalesce(v_page_error_count, 0) > 0 OR v_no_source,
      provider_unsafe_reason = CASE
        WHEN v_no_source THEN 'TRANSFER_SCOPE_ITEM_SOURCE_EMPTY'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'TRANSFER_SCOPE_ITEM_SEED_ERROR'
        WHEN coalesce(v_seed_complete, false) IS NOT TRUE THEN 'TRANSFER_SCOPE_ITEM_SEED_INCOMPLETE'
        ELSE 'TRANSFER_SCOPE_ITEM_ROLLUP_PENDING'
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = p_transfer_scope_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET phase = CASE WHEN coalesce(v_has_more, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS' ELSE 'ROLLUP_TRANSFER_SCOPE_ITEMS' END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_item_seed', jsonb_build_object(
            'transfer_scope_id', p_transfer_scope_id::text,
            'seeded_at_utc', v_now::text,
            'seeded_count', coalesce(v_seeded_count, 0),
            'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
            'seed_complete', coalesce(v_seed_complete, false),
            'seed_proof_hash', v_seed_proof_hash,
            'has_more', coalesce(v_has_more, false),
            'next_cursor', v_next_cursor
          ),
          'transfer_scope_item_seed_proofs', CASE
              WHEN jsonb_typeof(operation_update.progress_json->'transfer_scope_item_seed_proofs') = 'object'
                THEN coalesce(operation_update.progress_json->'transfer_scope_item_seed_proofs', '{}'::jsonb)
              ELSE '{}'::jsonb
            END || jsonb_build_object(
              p_transfer_scope_id::text,
              jsonb_build_object(
                'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
                'seed_complete', coalesce(v_seed_complete, false),
                'seed_proof_hash', v_seed_proof_hash,
                'updated_at_utc', v_now::text
              )
            ),
          'next_required_phase', CASE WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE' ELSE 'TRANSFER_SCOPE_ROLLUP_PAGE' END
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'source_mode', 'ROW_BACKED_TRANSFER_GROUP',
    'limit', v_limit,
    'seeded_count', coalesce(v_seeded_count, 0),
    'last_item_ordinal', coalesce(v_membership_count, v_last_item_ordinal, 0),
    'seed_complete', coalesce(v_seed_complete, false),
    'seed_proof_hash', v_seed_proof_hash,
    'page_error_count', coalesce(v_page_error_count, 0),
    'has_more', coalesce(v_has_more, false),
    'next_cursor', v_next_cursor,
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_execute_bank_transfer_scope_rollup_chunk(uuid,uuid,jsonb,integer,uuid)
CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_rollup_chunk(p_operation_id uuid, p_transfer_scope_id uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_scope_row public.banking_pay_operation_transfer_scope%ROWTYPE;
  v_last_item_ordinal bigint := 0;
  v_page_count integer := 0;
  v_processed_count integer := 0;
  v_page_error_count integer := 0;
  v_page_prepared_count integer := 0;
  v_page_prepared_amount numeric(14,2) := 0;
  v_prepared_item_count integer := 0;
  v_prepared_amount_total numeric(14,2) := 0;
  v_effective_scope_amount numeric(14,2) := 0;
  v_membership_seed_complete boolean := false;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_provider_ready boolean := false;
  v_prepared_scope_hash text := NULL::text;
  v_prepared_result_hash text := NULL::text;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_transfer_scope_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_ID_REQUIRED')::text;
  END IF;

  IF p_cursor IS NOT NULL AND jsonb_typeof(p_cursor) <> 'object' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_CURSOR_MUST_BE_OBJECT')::text;
  END IF;

  IF nullif(btrim(coalesce(p_cursor->>'last_item_ordinal', '')), '') ~ '^[0-9]+$' THEN
    v_last_item_ordinal := (p_cursor->>'last_item_ordinal')::bigint;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.id = p_transfer_scope_id
    AND scope_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_SCOPE_NOT_FOUND', 'operation_id', p_operation_id::text, 'transfer_scope_id', p_transfer_scope_id::text)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> v_scope_row.pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'scope_pay_batch_id', v_scope_row.pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_scope_row.provider_submit_state, 'NOT_READY'))) NOT IN ('', 'NOT_READY', 'READY', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_PROVIDER_STATE_ALREADY_STARTED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_ROLLUP_PROVIDER_STATE_ALREADY_STARTED', 'transfer_scope_id', p_transfer_scope_id::text, 'provider_submit_state', v_scope_row.provider_submit_state)::text;
  END IF;

  v_membership_seed_complete := COALESCE((v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', p_transfer_scope_id::text, 'seed_complete'])::boolean, false);

  DROP TABLE IF EXISTS pg_temp.tmp_transfer_scope_rollup_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_transfer_scope_rollup_page ON COMMIT DROP AS
  SELECT scope_item.pay_batch_item_id,
         scope_item.item_ordinal,
         scope_item.item_amount,
         CASE
           WHEN item_rows.id IS NULL THEN 'MISSING'
           WHEN COALESCE(item_rows.is_voided, false) THEN 'VOIDED'
           WHEN upper(btrim(coalesce(scope_item.item_status, ''))) IN ('VOIDED', 'PAYOUT_INSTRUCTION_MISSING', 'MISSING', 'ERROR') THEN upper(btrim(coalesce(scope_item.item_status, 'ERROR')))
           WHEN v_scope_row.pay_channel <> 'PAYE'
            AND COALESCE(scope_item.item_amount, 0) <> 0
            AND item_rows.payout_instruction_snapshot_json IS NULL THEN 'PAYOUT_INSTRUCTION_MISSING'
           ELSE 'PREPARED'
         END AS validation_status
  FROM public.banking_pay_operation_transfer_scope_items AS scope_item
  LEFT JOIN public.pay_batch_items AS item_rows
    ON item_rows.id = scope_item.pay_batch_item_id
  WHERE scope_item.operation_id = p_operation_id
    AND scope_item.transfer_scope_id = p_transfer_scope_id
    AND scope_item.item_ordinal > v_last_item_ordinal
    AND upper(btrim(coalesce(scope_item.rollup_status, ''))) = 'PENDING'
  ORDER BY scope_item.item_ordinal, scope_item.pay_batch_item_id
  LIMIT (v_limit + 1);

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  WITH page_rows AS (
    SELECT page_row.*
    FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT v_limit
  ), updated AS (
    UPDATE public.banking_pay_operation_transfer_scope_items AS scope_item
    SET item_status = page_rows.validation_status,
        rollup_status = CASE WHEN page_rows.validation_status = 'PREPARED' THEN 'ROLLED_UP' ELSE 'ERROR' END,
        updated_at_utc = v_now
    FROM page_rows
    WHERE scope_item.operation_id = p_operation_id
      AND scope_item.transfer_scope_id = p_transfer_scope_id
      AND scope_item.pay_batch_item_id = page_rows.pay_batch_item_id
    RETURNING scope_item.item_status,
              scope_item.item_amount,
              scope_item.item_ordinal,
              scope_item.pay_batch_item_id
  )
  SELECT count(*)::integer,
         count(*) FILTER (WHERE updated.item_status = 'PREPARED')::integer,
         count(*) FILTER (WHERE updated.item_status <> 'PREPARED')::integer,
         round(coalesce(sum(CASE WHEN updated.item_status = 'PREPARED' THEN coalesce(updated.item_amount, 0) ELSE 0 END), 0), 2)::numeric(14,2),
         md5(coalesce(string_agg(updated.pay_batch_item_id::text || ':' || coalesce(updated.item_amount, 0)::text || ':' || coalesce(updated.item_status, ''), '|' ORDER BY updated.item_ordinal, updated.pay_batch_item_id), 'NO_PAGE_ITEMS'))
  INTO v_processed_count,
       v_page_prepared_count,
       v_page_error_count,
       v_page_prepared_amount,
       v_prepared_scope_hash
  FROM updated;

  v_prepared_item_count := coalesce(v_scope_row.prepared_item_count, 0) + coalesce(v_page_prepared_count, 0);
  v_prepared_amount_total := round(coalesce(v_scope_row.prepared_amount_total, 0) + coalesce(v_page_prepared_amount, 0), 2);
  v_effective_scope_amount := CASE WHEN round(coalesce(v_scope_row.amount, 0), 2) = 0 AND coalesce(v_prepared_amount_total, 0) <> 0 THEN v_prepared_amount_total ELSE round(coalesce(v_scope_row.amount, 0), 2) END;

  v_provider_ready := (
    coalesce(v_membership_seed_complete, false) = true
    AND coalesce(v_has_more, false) = false
    AND coalesce(v_page_error_count, 0) = 0
    AND coalesce(v_scope_row.provider_review_required, false) = false
    AND coalesce(v_prepared_item_count, 0) > 0
    AND round(coalesce(v_prepared_amount_total, 0), 2) = round(coalesce(v_effective_scope_amount, 0), 2)
    AND v_scope_row.pay_bank_transfer_id IS NOT NULL
  );

  v_prepared_result_hash := md5(jsonb_build_object(
    'operation_id', p_operation_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'prepared_item_count', coalesce(v_prepared_item_count, 0),
    'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
    'scope_amount', round(coalesce(v_effective_scope_amount, 0), 2),
    'page_hash', v_prepared_scope_hash,
    'provider_ready', v_provider_ready,
    'has_more', coalesce(v_has_more, false)
  )::text);

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET prepared_item_count = coalesce(v_prepared_item_count, 0),
      prepared_amount_total = round(coalesce(v_prepared_amount_total, 0), 2),
      amount = CASE WHEN round(coalesce(scope_update.amount, 0), 2) = 0 AND coalesce(v_prepared_amount_total, 0) <> 0 THEN round(coalesce(v_prepared_amount_total, 0), 2) ELSE scope_update.amount END,
      prepared_scope_hash = md5(coalesce(scope_update.prepared_scope_hash, '') || ':' || coalesce(v_prepared_scope_hash, '') || ':' || coalesce(v_processed_count, 0)::text),
      prepared_result_hash = v_prepared_result_hash,
      provider_submit_ready = v_provider_ready,
      provider_submit_state = CASE
        WHEN v_provider_ready THEN 'READY'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'REVIEW_REQUIRED'
        ELSE 'NOT_READY'
      END,
      provider_review_required = coalesce(scope_update.provider_review_required, false) OR coalesce(v_page_error_count, 0) > 0,
      provider_unsafe_reason = CASE
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'TRANSFER_SCOPE_ITEM_ROLLUP_ERROR'
        WHEN coalesce(v_membership_seed_complete, false) IS NOT TRUE THEN 'TRANSFER_SCOPE_ITEM_SEED_INCOMPLETE'
        WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ITEM_ROLLUP_PENDING'
        WHEN scope_update.pay_bank_transfer_id IS NULL THEN 'TRANSFER_PREPARE_PENDING'
        WHEN round(coalesce(v_prepared_amount_total, 0), 2) <> round(coalesce(v_effective_scope_amount, 0), 2) THEN 'TRANSFER_SCOPE_AMOUNT_MISMATCH'
        ELSE NULL::text
      END,
      status = CASE
        WHEN v_provider_ready THEN 'PREPARED'
        WHEN coalesce(v_page_error_count, 0) > 0 THEN 'FAILED'
        WHEN coalesce(v_has_more, false) IS NOT TRUE AND coalesce(v_membership_seed_complete, false) THEN 'ROLLED_UP'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = p_transfer_scope_id;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'last_item_ordinal', page_row.item_ordinal,
      'last_pay_batch_item_id', page_row.pay_batch_item_id::text
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_transfer_scope_rollup_page AS page_row
    ORDER BY page_row.item_ordinal, page_row.pay_batch_item_id
    LIMIT 1 OFFSET GREATEST(v_limit - 1, 0);
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET phase = CASE WHEN coalesce(v_has_more, false) THEN 'ROLLUP_TRANSFER_SCOPE_ITEMS' ELSE 'PREPARE_TRANSFER_CHUNKS' END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_rollup', jsonb_build_object(
            'transfer_scope_id', p_transfer_scope_id::text,
            'rolled_at_utc', v_now::text,
            'processed_count', coalesce(v_processed_count, 0),
            'membership_seed_complete', coalesce(v_membership_seed_complete, false),
            'provider_submit_ready', v_provider_ready,
            'has_more', coalesce(v_has_more, false),
            'next_cursor', v_next_cursor
          ),
          'transfer_scope_rollup_proofs', CASE
              WHEN jsonb_typeof(operation_update.progress_json->'transfer_scope_rollup_proofs') = 'object'
                THEN coalesce(operation_update.progress_json->'transfer_scope_rollup_proofs', '{}'::jsonb)
              ELSE '{}'::jsonb
            END || jsonb_build_object(
              p_transfer_scope_id::text,
              jsonb_build_object(
                'membership_seed_complete', coalesce(v_membership_seed_complete, false),
                'prepared_item_count', coalesce(v_prepared_item_count, 0),
                'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
                'prepared_result_hash', v_prepared_result_hash,
                'provider_submit_ready', v_provider_ready,
                'updated_at_utc', v_now::text
              )
            ),
          'next_required_phase', CASE WHEN coalesce(v_has_more, false) THEN 'TRANSFER_SCOPE_ROLLUP_PAGE' ELSE 'TRANSFER_CHUNK_PREPARE_PAGE' END
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_scope_row.pay_batch_id::text,
    'transfer_scope_id', p_transfer_scope_id::text,
    'limit', v_limit,
    'processed_count', coalesce(v_processed_count, 0),
    'page_error_count', coalesce(v_page_error_count, 0),
    'membership_seed_complete', coalesce(v_membership_seed_complete, false),
    'prepared_item_count', coalesce(v_prepared_item_count, 0),
    'prepared_amount_total', round(coalesce(v_prepared_amount_total, 0), 2),
    'scope_amount', round(coalesce(v_effective_scope_amount, 0), 2),
    'prepared_result_hash', v_prepared_result_hash,
    'provider_submit_ready', v_provider_ready,
    'has_more', coalesce(v_has_more, false),
    'next_cursor', v_next_cursor,
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_execute_bank_transfer_scope_seed(uuid,uuid,text,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_execute_bank_transfer_scope_seed(p_operation_id uuid, p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid, p_retry_blocked_funds boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_limit integer := 100;
  v_last_pay_batch_item_id uuid := NULL::uuid;
  v_page_count integer := 0;
  v_group_seeded_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_cached_scope_count integer := 0;
  v_existing_scope_count integer := 0;
  v_unseeded_transfer_scope_count integer := 0;
  v_next_transfer_scope_id uuid := NULL::uuid;
  v_review_scope_count integer := 0;
  v_operation_phase text := NULL::text;
  v_transfer_scope_group_seed_complete boolean := false;
  v_membership_seed_required boolean := false;
  v_next_required_phase text := 'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE';
  v_global_projection_missing_paye_count integer := 0;
  v_global_projection_explicit_zero_count integer := 0;
  v_global_projection_positive_payment_count integer := 0;
  v_global_projection_positive_payment_total numeric(14,2) := 0;
  v_global_projection_invalid_payment_row_count integer := 0;
  v_global_projection_paye_net_state_hash text := NULL::text;
  v_global_projection_bank_payment_hash text := NULL::text;
  v_scoped_projection_missing_paye_count integer := 0;
  v_scoped_projection_explicit_zero_count integer := 0;
  v_scoped_projection_positive_payment_count integer := 0;
  v_scoped_projection_positive_payment_total numeric(14,2) := 0;
  v_scoped_projection_invalid_payment_row_count integer := 0;
  v_scoped_projection_paye_net_state_hash text := NULL::text;
  v_scoped_projection_bank_payment_hash text := NULL::text;
  v_allow_explicit_zero_no_bank_scopes boolean := false;
  v_scoped_no_transfer_execution boolean := false;
  v_no_bank_payment_execution boolean := false;
  v_no_bank_proof_json jsonb := '{}'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_ID_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_ACTOR_REQUIRED')::text;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_SCOPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_SCOPE_INVALID', 'pay_channel_scope', p_pay_channel_scope)::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_NOT_FOUND', 'operation_id', p_operation_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_TYPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_TYPE_INVALID', 'operation_id', p_operation_id::text, 'operation_type', v_operation_row.operation_type)::text;
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_OPERATION_BATCH_MISMATCH', 'operation_id', p_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))) <> 'PASSED'
     OR nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NULL
     OR coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false) IS TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_FRESHNESS_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_FRESHNESS_REQUIRED',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_batch_row.freshness_validation_status,
        'freshness_result_hash_present', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
      )::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) = 'BLOCKED_FUNDS' AND coalesce(p_retry_blocked_funds, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BLOCKED_FUNDS_RETRY_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_BLOCKED_FUNDS_RETRY_REQUIRED', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  WITH global_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      'ALL'
    ) AS projection_row
  ), global_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS missing_paye_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS explicit_zero_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM global_projection_rows AS projection_row
  ), scoped_projection_rows AS MATERIALIZED (
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_scope
    ) AS projection_row
  ), scoped_projection_summary AS (
    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer AS missing_paye_count,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer AS explicit_zero_count,
      COUNT(*) FILTER (WHERE projection_row.is_positive_bank_payment)::integer AS positive_payment_count,
      ROUND(
        COALESCE(
          SUM(projection_row.amount) FILTER (WHERE projection_row.is_positive_bank_payment),
          0
        ),
        2
      )::numeric(14,2) AS positive_payment_total,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer AS invalid_payment_row_count,
      MAX(projection_row.paye_net_state_hash) AS paye_net_state_hash,
      MAX(projection_row.bank_payment_projection_hash) AS bank_payment_projection_hash
    FROM scoped_projection_rows AS projection_row
  )
  SELECT
    COALESCE(global_projection_summary.missing_paye_count, 0),
    COALESCE(global_projection_summary.explicit_zero_count, 0),
    COALESCE(global_projection_summary.positive_payment_count, 0),
    COALESCE(global_projection_summary.positive_payment_total, 0),
    COALESCE(global_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      global_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      global_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL',
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(scoped_projection_summary.missing_paye_count, 0),
    COALESCE(scoped_projection_summary.explicit_zero_count, 0),
    COALESCE(scoped_projection_summary.positive_payment_count, 0),
    COALESCE(scoped_projection_summary.positive_payment_total, 0),
    COALESCE(scoped_projection_summary.invalid_payment_row_count, 0),
    COALESCE(
      scoped_projection_summary.paye_net_state_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'rows', '[]'::jsonb
      )::text)
    ),
    COALESCE(
      scoped_projection_summary.bank_payment_projection_hash,
      MD5(JSONB_BUILD_OBJECT(
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'rows', '[]'::jsonb
      )::text)
    )
  INTO
    v_global_projection_missing_paye_count,
    v_global_projection_explicit_zero_count,
    v_global_projection_positive_payment_count,
    v_global_projection_positive_payment_total,
    v_global_projection_invalid_payment_row_count,
    v_global_projection_paye_net_state_hash,
    v_global_projection_bank_payment_hash,
    v_scoped_projection_missing_paye_count,
    v_scoped_projection_explicit_zero_count,
    v_scoped_projection_positive_payment_count,
    v_scoped_projection_positive_payment_total,
    v_scoped_projection_invalid_payment_row_count,
    v_scoped_projection_paye_net_state_hash,
    v_scoped_projection_bank_payment_hash
  FROM global_projection_summary
  CROSS JOIN scoped_projection_summary;

  IF COALESCE(v_global_projection_missing_paye_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_EXECUTE_TRANSFER_SCOPE_SEED_PAYE_NET_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = JSONB_BUILD_OBJECT(
        'code', 'PAYE_NET_REQUIRED_FOR_EXECUTION',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0)
      )::text;
  END IF;

  v_allow_explicit_zero_no_bank_scopes := (
    COALESCE(v_global_projection_missing_paye_count, 0) = 0
    AND COALESCE(v_scoped_projection_explicit_zero_count, 0) > 0
    AND COALESCE(v_scoped_projection_invalid_payment_row_count, 0) = 0
  );

  v_scoped_no_transfer_execution := (
    v_allow_explicit_zero_no_bank_scopes
    AND COALESCE(v_scoped_projection_positive_payment_count, 0) = 0
  );

  v_no_bank_payment_execution := (
    v_scoped_no_transfer_execution
    AND COALESCE(v_global_projection_positive_payment_count, 0) = 0
    AND COALESCE(v_global_projection_invalid_payment_row_count, 0) = 0
  );

  v_no_bank_proof_json := JSONB_BUILD_OBJECT(
    'proof_source', 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_SEED',
    'proof_generated_at_utc', v_now::text,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_channel_scope', v_scope,
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
    'no_bank_payment_execution', v_no_bank_payment_execution,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
    'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
    'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
    'global_positive_bank_payment_total', ROUND(COALESCE(v_global_projection_positive_payment_total, 0), 2),
    'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
    'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
    'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
    'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
    'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
    'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
    'paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
    'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
    'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
    'scoped_bank_payment_projection_hash', v_scoped_projection_bank_payment_hash
  );

  v_operation_phase := upper(btrim(coalesce(v_operation_row.phase, '')));
  v_transfer_scope_group_seed_complete :=
    v_operation_phase IN (
      'SEED_TRANSFER_SCOPE_ITEMS',
      'TRANSFER_SCOPE_ITEM_MEMBERSHIP_SEED_PAGE',
      'SEED_TRANSFER_ROLLUP_CHUNKS',
      'ROLLUP_TRANSFER_SCOPE_ITEMS',
      'TRANSFER_SCOPE_ROLLUP_PAGE',
      'PREPARE_TRANSFER_CHUNKS',
      'TRANSFER_CHUNK_PREPARE_PAGE',
      'PREPARE_BATCH_PROOF',
      'PREPARE_BATCH',
      'START_AUTHORISATION_PROOF',
      'START_AUTHORISATION',
      'SUBMIT_PROVIDER_TRANSFERS',
      'SEND_PROVIDER_CHUNK',
      'REQUEST_PROVIDER_SEND',
      'FINALISE_PROVIDER_CHUNK',
      'APPLY_RAIL_UPDATES',
      'QUEUE_REMITTANCES',
      'COMPLETE'
    )
    OR upper(btrim(coalesce(v_operation_row.progress_json->>'transfer_scope_group_seed_complete', ''))) = 'TRUE'
    OR (
      v_operation_row.progress_json ? 'has_more_transfer_groups'
      AND upper(btrim(coalesce(v_operation_row.progress_json->>'has_more_transfer_groups', 'false'))) <> 'TRUE'
      AND v_operation_row.progress_json ? 'last_transfer_scope_seed_at_utc'
    );

  IF coalesce(v_transfer_scope_group_seed_complete, false) THEN
    SELECT count(*)::integer
    INTO v_existing_scope_count
    FROM public.banking_pay_operation_transfer_scope AS existing_scope
    WHERE existing_scope.operation_id = p_operation_id
      AND existing_scope.pay_batch_id = p_pay_batch_id;

    SELECT count(*)::integer
    INTO v_unseeded_transfer_scope_count
    FROM public.banking_pay_operation_transfer_scope AS unseeded_scope
    WHERE unseeded_scope.operation_id = p_operation_id
      AND unseeded_scope.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', unseeded_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
      AND upper(btrim(coalesce(unseeded_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
        'CLAIMED',
        'REQUEST_PREPARING',
        'REQUEST_SENDING',
        'REQUEST_SENT_LOCAL',
        'PROVIDER_ACCEPTED',
        'PROVIDER_REJECTED',
        'PROVIDER_UNKNOWN',
        'CHUNK_FINALISED'
      );

    SELECT next_scope.id
    INTO v_next_transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS next_scope
    WHERE next_scope.operation_id = p_operation_id
      AND next_scope.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', next_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
      AND upper(btrim(coalesce(next_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
        'CLAIMED',
        'REQUEST_PREPARING',
        'REQUEST_SENDING',
        'REQUEST_SENT_LOCAL',
        'PROVIDER_ACCEPTED',
        'PROVIDER_REJECTED',
        'PROVIDER_UNKNOWN',
        'CHUNK_FINALISED'
      )
    ORDER BY next_scope.created_at_utc NULLS FIRST, next_scope.id
    LIMIT 1;

    SELECT count(*)::integer
    INTO v_review_scope_count
    FROM public.banking_pay_operation_transfer_scope AS review_scope
    WHERE review_scope.operation_id = p_operation_id
      AND review_scope.pay_batch_id = p_pay_batch_id
      AND (
        coalesce(review_scope.provider_review_required, false) IS TRUE
        OR upper(btrim(coalesce(review_scope.provider_submit_state, ''))) = 'REVIEW_REQUIRED'
      );

    IF coalesce(v_existing_scope_count, 0) <= 0 THEN
      IF v_scoped_no_transfer_execution THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET pay_batch_id = p_pay_batch_id,
            status = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN 'RUNNING'
              ELSE operation_update.status
            END,
            phase = 'START_AUTHORISATION_PROOF',
            runner_state = 'RUNNABLE',
            requires_user_action = false,
            resume_reason = CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_AUTHORISATION_REQUIRED' ELSE 'NO_TRANSFER_SCOPE_AUTHORISATION_REQUIRED' END,
            run_after_utc = v_now,
            progress_json = JSONB_STRIP_NULLS(
              COALESCE(operation_update.progress_json, '{}'::jsonb)
              || JSONB_BUILD_OBJECT(
                'last_transfer_scope_seed_at_utc', v_now::text,
                'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
                'transfer_scope_group_seed_complete', true,
                'transfer_scope_count', 0,
                'unseeded_transfer_scope_count', 0,
                'membership_seed_required', false,
                'no_transfer_scope', true,
                'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
                'no_bank_payment_execution', v_no_bank_payment_execution,
                'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
                'review_required', false,
                'review_reason_code', NULL::text,
                'has_more_transfer_groups', false,
                'transfer_scope_seed_cursor', NULL::jsonb,
                'next_required_phase', 'START_AUTHORISATION_PROOF'
              )
              || v_no_bank_proof_json
              || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
            ),
            error_json = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN NULL::jsonb
              ELSE operation_update.error_json
            END,
            updated_at_utc = v_now
        WHERE operation_update.id = p_operation_id;

        RETURN JSONB_BUILD_OBJECT(
          'ok', true,
          'code', CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_EXECUTION_READY' ELSE 'NO_TRANSFER_EXECUTION_SCOPE_READY' END,
          'message', CASE WHEN v_no_bank_payment_execution THEN 'All required bank-payment groups are explicit zero; no transfer scope is required and authorisation can continue.' ELSE 'The requested scope contains only explicit-zero PAYE payment groups; no transfer scope is required for this scope and authorisation can continue.' END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'bounded', true,
          'limit', v_limit,
          'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
          'source_item_page_count', 0,
          'group_seeded_count', 0,
          'membership_seeded_count', 0,
          'transfer_scope_count', 0,
          'unseeded_transfer_scope_count', 0,
          'review_scope_count', 0,
          'membership_seed_required', false,
          'no_transfer_scope', true,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
          'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
          'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
          'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
          'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
          'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
          'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
          'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
          'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
          'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
          'paye_net_state_hash', v_global_projection_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
          'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
          'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
          'has_more_transfer_groups', false,
          'has_more_membership_seed', false,
          'next_transfer_scope_id', NULL::text,
          'next_cursor', NULL::jsonb,
          'next_required_phase', 'START_AUTHORISATION_PROOF',
          'server_utc', v_now::text
        );
      END IF;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          phase = 'REVIEW_REQUIRED',
          progress_json = jsonb_strip_nulls(
            coalesce(operation_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_transfer_scope_seed_at_utc', v_now::text,
              'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
              'transfer_scope_group_seed_complete', true,
              'transfer_scope_count', 0,
              'unseeded_transfer_scope_count', 0,
              'membership_seed_required', false,
              'no_transfer_scope', true,
              'next_required_phase', 'REVIEW_REQUIRED'
            )
          ),
          updated_at_utc = v_now
      WHERE operation_update.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'code', 'NO_ELIGIBLE_TRANSFER_SCOPE',
        'message', 'No eligible payable transfer scope was available for this operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'bounded', true,
        'limit', v_limit,
        'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
        'source_item_page_count', 0,
        'group_seeded_count', 0,
        'membership_seeded_count', 0,
        'transfer_scope_count', 0,
        'unseeded_transfer_scope_count', 0,
        'review_scope_count', coalesce(v_review_scope_count, 0),
        'membership_seed_required', false,
        'no_transfer_scope', true,
        'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
        'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
        'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
        'has_more_transfer_groups', false,
        'has_more_membership_seed', false,
        'next_transfer_scope_id', NULL::text,
        'next_cursor', NULL::jsonb,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
    END IF;

    v_membership_seed_required := coalesce(v_unseeded_transfer_scope_count, 0) > 0;
    v_next_required_phase := CASE WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS' ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS' END;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        phase = v_next_required_phase,
        runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
        run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
        progress_json = jsonb_strip_nulls(
          coalesce(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_transfer_scope_seed_at_utc', v_now::text,
            'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
            'transfer_scope_group_seed_complete', true,
            'transfer_scope_count', coalesce(v_existing_scope_count, 0),
            'unseeded_transfer_scope_count', coalesce(v_unseeded_transfer_scope_count, 0),
            'membership_seed_required', coalesce(v_membership_seed_required, false),
            'next_transfer_scope_id', CASE WHEN v_next_transfer_scope_id IS NULL THEN NULL ELSE v_next_transfer_scope_id::text END,
            'next_required_phase', v_next_required_phase,
            'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
            'no_bank_payment_execution', v_no_bank_payment_execution,
            'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes
          )
          || v_no_bank_proof_json
          || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_channel_scope', v_scope,
      'bounded', true,
      'limit', v_limit,
      'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
      'source_item_page_count', 0,
      'group_seeded_count', 0,
      'membership_seeded_count', 0,
      'transfer_scope_count', coalesce(v_existing_scope_count, 0),
      'unseeded_transfer_scope_count', coalesce(v_unseeded_transfer_scope_count, 0),
      'review_scope_count', coalesce(v_review_scope_count, 0),
      'membership_seed_required', coalesce(v_membership_seed_required, false),
      'no_transfer_scope', false,
      'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
      'no_bank_payment_execution', v_no_bank_payment_execution,
      'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
      'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
      'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
      'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
      'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
      'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
      'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
      'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
      'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
      'paye_net_state_hash', v_global_projection_paye_net_state_hash,
      'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
      'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
      'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
      'has_more_transfer_groups', false,
      'has_more_membership_seed', coalesce(v_membership_seed_required, false),
      'next_transfer_scope_id', CASE WHEN v_next_transfer_scope_id IS NULL THEN NULL ELSE v_next_transfer_scope_id::text END,
      'next_cursor', NULL::jsonb,
      'next_required_phase', v_next_required_phase,
      'server_utc', v_now::text
    );
  END IF;

  IF nullif(btrim(coalesce(v_operation_row.progress_json #>> '{transfer_scope_seed_cursor,last_pay_batch_item_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_last_pay_batch_item_id := (v_operation_row.progress_json #>> '{transfer_scope_seed_cursor,last_pay_batch_item_id}')::uuid;
  END IF;

  IF nullif(btrim(coalesce(v_operation_row.progress_json->>'transfer_scope_count', '')), '') ~ '^[0-9]+$' THEN
    v_cached_scope_count := (v_operation_row.progress_json->>'transfer_scope_count')::integer;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_bank_transfer_scope_source_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_bank_transfer_scope_source_page ON COMMIT DROP AS
  WITH source_rows AS (
    SELECT
      row_number() OVER (ORDER BY batch_item.id)::integer AS page_ordinal,
      batch_item.id AS pay_batch_item_id,
      batch_candidate.id AS pay_batch_candidate_id,
      batch_candidate.candidate_id,
      CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END AS pay_channel,
      batch_item.umbrella_id,
      COALESCE(batch_item.amount_inc_vat, batch_item.amount_ex_vat, 0)::numeric AS item_amount,
      batch_candidate.net_bank_amount,
      effective_paye_input.id AS effective_paye_net_input_id,
      effective_paye_input.net_amount AS effective_paye_net_input_amount,
      (
        effective_paye_input.id IS NOT NULL
        AND effective_paye_input.net_amount IS NOT NULL
      ) AS has_effective_paye_input,
      batch_item.payout_instruction_snapshot_json,
      upper(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_kind', '')), '')) AS payee_entity_kind,
      CASE
        WHEN nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (batch_item.payout_instruction_snapshot_json->>'payee_entity_id')::uuid
        ELSE NULL::uuid
      END AS payee_entity_id,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'beneficiary_name', '')), '') AS payee_name,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'sort_code', '')), '') AS sort_code,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'account_number', '')), '') AS account_number,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'account_type', '')), '') AS account_type,
      nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), '') AS bank_details_hash_snapshot,
      CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket')::date ELSE NULL::date END AS week_ending_bucket,
      CASE
        WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'PAYE'
          THEN batch_candidate.candidate_id::text
               || '|PAYE|'
               || COALESCE(
                    NULLIF(BTRIM(COALESCE(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''),
                    (
                      SELECT NULLIF(
                               BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'bank_details_hash', '')),
                               ''
                             )
                      FROM public.pay_batch_items AS fallback_item
                      WHERE fallback_item.pay_batch_candidate_id = batch_candidate.id
                        AND COALESCE(fallback_item.is_voided, false) = false
                        AND fallback_item.item_type <> 'DEBT_CREATED'
                        AND fallback_item.pay_channel = 'PAYE'
                        AND NULLIF(
                              BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'bank_details_hash', '')),
                              ''
                            ) IS NOT NULL
                      ORDER BY
                        CASE
                          WHEN NULLIF(
                                 BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'sort_code', '')),
                                 ''
                               ) IS NOT NULL
                           AND NULLIF(
                                 BTRIM(COALESCE(fallback_item.payout_instruction_snapshot_json->>'account_number', '')),
                                 ''
                               ) IS NOT NULL
                            THEN 0
                          ELSE 1
                        END,
                        fallback_item.id
                      LIMIT 1
                    ),
                    ''
                  )
        WHEN CASE WHEN upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' THEN 'PAYE' ELSE batch_item.pay_channel END = 'UMBRELLA'
          THEN batch_candidate.candidate_id::text || '|UMBRELLA|' || coalesce(CASE WHEN coalesce(batch_item.payout_instruction_snapshot_json->>'week_ending_bucket', '') ~ '^\d{4}-\d{2}-\d{2}$' THEN (batch_item.payout_instruction_snapshot_json->>'week_ending_bucket') ELSE 'NO_WEEK' END, 'NO_WEEK') || '|' || coalesce(batch_item.payout_instruction_snapshot_json->>'payee_entity_id', '') || '|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
        ELSE batch_candidate.candidate_id::text || '|OTHER|' || coalesce(nullif(btrim(coalesce(batch_item.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''), '')
      END AS transfer_group_key
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    LEFT JOIN LATERAL (
      SELECT
        paye_input_row.id,
        paye_input_row.net_amount
      FROM public.pay_batch_paye_net_inputs AS paye_input_row
      WHERE paye_input_row.pay_batch_candidate_id = batch_candidate.id
      ORDER BY paye_input_row.imported_at_utc DESC,
               paye_input_row.id DESC
      LIMIT 1
    ) AS effective_paye_input
      ON true
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND coalesce(batch_item.is_voided, false) = false
      AND batch_item.item_type <> 'DEBT_CREATED'
      AND NOT (
        upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
        AND upper(btrim(coalesce(batch_item.pay_channel, ''))) = 'PAYE'
        AND effective_paye_input.id IS NOT NULL
        AND effective_paye_input.net_amount IS NOT NULL
        AND batch_candidate.net_bank_amount IS NOT NULL
        AND round(batch_candidate.net_bank_amount, 2) = 0
      )
      AND (v_last_pay_batch_item_id IS NULL OR batch_item.id > v_last_pay_batch_item_id)
      AND (
        (v_scope = 'ALL' AND batch_item.pay_channel IN ('PAYE', 'UMBRELLA'))
        OR (v_scope IN ('PAYE', 'UMBRELLA') AND batch_item.pay_channel = v_scope)
        OR (v_scope = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
        OR (upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) = 'LOANS' AND batch_item.item_type = 'LOAN_PAYOUT')
      )
    ORDER BY batch_item.id
    LIMIT (v_limit + 1)
  )
  SELECT source_rows.*
  FROM source_rows;

  SELECT count(*)::integer
  INTO v_page_count
  FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page;

  v_has_more := coalesce(v_page_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_bank_transfer_scope_group_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_bank_transfer_scope_group_page ON COMMIT DROP AS
  SELECT DISTINCT ON (source_page.pay_channel, source_page.transfer_group_key)
         source_page.pay_channel,
         source_page.transfer_group_key,
         source_page.candidate_id,
         source_page.has_effective_paye_input,
         CASE WHEN source_page.pay_channel = 'UMBRELLA' AND source_page.payee_entity_kind = 'UMBRELLA' THEN source_page.payee_entity_id ELSE NULL::uuid END AS umbrella_id,
         source_page.payee_entity_kind,
         source_page.payee_entity_id,
         'GBP'::text AS currency,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN round(coalesce(source_page.net_bank_amount, 0), 2) ELSE 0::numeric END AS amount,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN 'Pay' ELSE left(coalesce(source_page.payee_name, source_page.candidate_id::text), 18) END AS payment_reference,
         source_page.payee_name,
         source_page.sort_code,
         source_page.account_number,
         source_page.account_type,
         source_page.bank_details_hash_snapshot,
         CASE WHEN source_page.pay_channel = 'PAYE' THEN 'CANDIDATE_DESTINATION' ELSE 'ROW_BACKED_DESTINATION' END AS grouping_mode_used,
         source_page.week_ending_bucket,
         CASE
           WHEN source_page.payout_instruction_snapshot_json IS NULL
             OR source_page.payee_name IS NULL
             OR source_page.bank_details_hash_snapshot IS NULL
             OR length(regexp_replace(coalesce(source_page.sort_code, ''), '[^0-9]', '', 'g')) <> 6
             OR nullif(regexp_replace(coalesce(source_page.account_number, ''), '[^0-9]', '', 'g'), '') IS NULL
             OR (source_page.pay_channel = 'UMBRELLA' AND (source_page.payee_entity_kind IS NULL OR source_page.payee_entity_kind <> 'UMBRELLA' OR source_page.payee_entity_id IS NULL OR source_page.umbrella_id IS NULL OR source_page.payee_entity_id IS DISTINCT FROM source_page.umbrella_id))
             OR (source_page.pay_channel = 'PAYE' AND (source_page.payee_entity_kind IS NULL OR source_page.payee_entity_kind <> 'CANDIDATE' OR source_page.payee_entity_id IS NULL OR source_page.payee_entity_id IS DISTINCT FROM source_page.candidate_id))
             OR (
               source_page.pay_channel = 'PAYE'
               AND upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
               AND source_page.has_effective_paye_input IS NOT TRUE
             )
             OR (source_page.pay_channel = 'PAYE' AND round(coalesce(source_page.net_bank_amount, 0), 2) <= 0)
           THEN 'FAILED'
           ELSE 'PENDING'
         END AS status,
         CASE
           WHEN source_page.pay_channel = 'PAYE'
            AND upper(btrim(coalesce(v_batch_row.batch_kind_fixed, ''))) <> 'LOANS'
            AND source_page.has_effective_paye_input IS NOT TRUE
             THEN 'PAYE_NET_REQUIRED_FOR_EXECUTION'
           WHEN source_page.pay_channel = 'PAYE'
            AND round(coalesce(source_page.net_bank_amount, 0), 2) <= 0
             THEN 'TRANSFER_SCOPE_NON_POSITIVE_AMOUNT'
           ELSE 'TRANSFER_GROUP_PAYOUT_INSTRUCTION_INVALID'
         END AS failure_reason
  FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page
  WHERE source_page.page_ordinal <= v_limit
  ORDER BY
    source_page.pay_channel,
    source_page.transfer_group_key,
    CASE
      WHEN source_page.payout_instruction_snapshot_json IS NOT NULL
       AND source_page.payee_name IS NOT NULL
       AND source_page.bank_details_hash_snapshot IS NOT NULL
       AND length(regexp_replace(coalesce(source_page.sort_code, ''), '[^0-9]', '', 'g')) = 6
       AND nullif(regexp_replace(coalesce(source_page.account_number, ''), '[^0-9]', '', 'g'), '') IS NOT NULL
       AND (
         (source_page.pay_channel = 'PAYE'
          AND source_page.payee_entity_kind = 'CANDIDATE'
          AND source_page.payee_entity_id IS NOT NULL
          AND source_page.payee_entity_id IS NOT DISTINCT FROM source_page.candidate_id)
         OR
         (source_page.pay_channel = 'UMBRELLA'
          AND source_page.payee_entity_kind = 'UMBRELLA'
          AND source_page.payee_entity_id IS NOT NULL
          AND source_page.umbrella_id IS NOT NULL
          AND source_page.payee_entity_id IS NOT DISTINCT FROM source_page.umbrella_id)
       )
        THEN 0
      ELSE 1
    END,
    source_page.pay_batch_item_id;

  WITH inserted_scope AS (
    INSERT INTO public.banking_pay_operation_transfer_scope (
      operation_id,
      pay_batch_id,
      pay_channel,
      transfer_group_key,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      currency,
      amount,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      grouping_mode_used,
      week_ending_bucket,
      request_id,
      status,
      pay_bank_transfer_id,
      provider_submit_ready,
      provider_submit_state,
      provider_review_required,
      provider_unsafe_reason,
      prepared_item_count,
      prepared_amount_total,
      created_at_utc,
      updated_at_utc
    )
    SELECT p_operation_id,
           p_pay_batch_id,
           group_page.pay_channel,
           group_page.transfer_group_key,
           group_page.candidate_id,
           group_page.umbrella_id,
           group_page.payee_entity_kind,
           group_page.payee_entity_id,
           group_page.currency,
           group_page.amount,
           group_page.payment_reference,
           group_page.payee_name,
           regexp_replace(coalesce(group_page.sort_code, ''), '[^0-9]', '', 'g'),
           regexp_replace(coalesce(group_page.account_number, ''), '[^0-9]', '', 'g'),
           group_page.account_type,
           group_page.bank_details_hash_snapshot,
           group_page.grouping_mode_used,
           group_page.week_ending_bucket,
           'op:' || p_operation_id::text || ':scope:' || md5(group_page.pay_channel || ':' || group_page.transfer_group_key),
           CASE WHEN group_page.status = 'FAILED' THEN 'FAILED' ELSE 'PENDING' END,
           NULL::uuid,
           false,
           CASE WHEN group_page.status = 'FAILED' THEN 'REVIEW_REQUIRED' ELSE 'NOT_READY' END,
           group_page.status = 'FAILED',
           CASE WHEN group_page.status = 'FAILED' THEN group_page.failure_reason ELSE 'TRANSFER_SCOPE_ITEM_SEED_PENDING' END,
           0,
           0,
           v_now,
           v_now
    FROM pg_temp.tmp_bank_transfer_scope_group_page AS group_page
    ON CONFLICT (operation_id, pay_channel, transfer_group_key) DO NOTHING
    RETURNING id
  )
  SELECT count(*)::integer
  INTO v_group_seeded_count
  FROM inserted_scope;

  IF coalesce(v_page_count, 0) > 0 THEN
    SELECT jsonb_build_object('last_pay_batch_item_id', source_page.pay_batch_item_id::text)
    INTO v_next_cursor
    FROM pg_temp.tmp_bank_transfer_scope_source_page AS source_page
    WHERE source_page.page_ordinal <= LEAST(v_limit, v_page_count)
    ORDER BY source_page.page_ordinal DESC
    LIMIT 1;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  SELECT count(*)::integer
  INTO v_existing_scope_count
  FROM public.banking_pay_operation_transfer_scope AS existing_scope
  WHERE existing_scope.operation_id = p_operation_id
    AND existing_scope.pay_batch_id = p_pay_batch_id;

  SELECT count(*)::integer
  INTO v_unseeded_transfer_scope_count
  FROM public.banking_pay_operation_transfer_scope AS unseeded_scope
  WHERE unseeded_scope.operation_id = p_operation_id
    AND unseeded_scope.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', unseeded_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
    AND upper(btrim(coalesce(unseeded_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
      'CLAIMED',
      'REQUEST_PREPARING',
      'REQUEST_SENDING',
      'REQUEST_SENT_LOCAL',
      'PROVIDER_ACCEPTED',
      'PROVIDER_REJECTED',
      'PROVIDER_UNKNOWN',
      'CHUNK_FINALISED'
    );

  SELECT next_scope.id
  INTO v_next_transfer_scope_id
  FROM public.banking_pay_operation_transfer_scope AS next_scope
  WHERE next_scope.operation_id = p_operation_id
    AND next_scope.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(v_operation_row.progress_json #>> ARRAY['transfer_scope_item_seed_proofs', next_scope.id::text, 'seed_complete'], 'false'))) <> 'TRUE'
    AND upper(btrim(coalesce(next_scope.provider_submit_state, 'NOT_READY'))) NOT IN (
      'CLAIMED',
      'REQUEST_PREPARING',
      'REQUEST_SENDING',
      'REQUEST_SENT_LOCAL',
      'PROVIDER_ACCEPTED',
      'PROVIDER_REJECTED',
      'PROVIDER_UNKNOWN',
      'CHUNK_FINALISED'
    )
  ORDER BY next_scope.created_at_utc NULLS FIRST, next_scope.id
  LIMIT 1;

  SELECT count(*)::integer
  INTO v_review_scope_count
  FROM public.banking_pay_operation_transfer_scope AS review_scope
  WHERE review_scope.operation_id = p_operation_id
    AND review_scope.pay_batch_id = p_pay_batch_id
    AND (
      coalesce(review_scope.provider_review_required, false) IS TRUE
      OR upper(btrim(coalesce(review_scope.provider_submit_state, ''))) = 'REVIEW_REQUIRED'
    );

  v_cached_scope_count := coalesce(v_existing_scope_count, 0);

  IF coalesce(v_page_count, 0) = 0 AND coalesce(v_cached_scope_count, 0) <= 0 THEN
      IF v_scoped_no_transfer_execution THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET pay_batch_id = p_pay_batch_id,
            status = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN 'RUNNING'
              ELSE operation_update.status
            END,
            phase = 'START_AUTHORISATION_PROOF',
            runner_state = 'RUNNABLE',
            requires_user_action = false,
            resume_reason = CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_AUTHORISATION_REQUIRED' ELSE 'NO_TRANSFER_SCOPE_AUTHORISATION_REQUIRED' END,
            run_after_utc = v_now,
            progress_json = JSONB_STRIP_NULLS(
              COALESCE(operation_update.progress_json, '{}'::jsonb)
              || JSONB_BUILD_OBJECT(
                'last_transfer_scope_seed_at_utc', v_now::text,
                'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
                'transfer_scope_group_seed_complete', true,
                'transfer_scope_count', 0,
                'unseeded_transfer_scope_count', 0,
                'membership_seed_required', false,
                'no_transfer_scope', true,
                'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
                'no_bank_payment_execution', v_no_bank_payment_execution,
                'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
                'review_required', false,
                'review_reason_code', NULL::text,
                'has_more_transfer_groups', false,
                'transfer_scope_seed_cursor', NULL::jsonb,
                'next_required_phase', 'START_AUTHORISATION_PROOF'
              )
              || v_no_bank_proof_json
              || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
            ),
            error_json = CASE
              WHEN UPPER(BTRIM(COALESCE(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN NULL::jsonb
              ELSE operation_update.error_json
            END,
            updated_at_utc = v_now
        WHERE operation_update.id = p_operation_id;

        RETURN JSONB_BUILD_OBJECT(
          'ok', true,
          'code', CASE WHEN v_no_bank_payment_execution THEN 'NO_BANK_PAYMENT_EXECUTION_READY' ELSE 'NO_TRANSFER_EXECUTION_SCOPE_READY' END,
          'message', CASE WHEN v_no_bank_payment_execution THEN 'All required bank-payment groups are explicit zero; no transfer scope is required and authorisation can continue.' ELSE 'The requested scope contains only explicit-zero PAYE payment groups; no transfer scope is required for this scope and authorisation can continue.' END,
          'operation_id', p_operation_id::text,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'bounded', true,
          'limit', v_limit,
          'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
          'source_item_page_count', 0,
          'group_seeded_count', 0,
          'membership_seeded_count', 0,
          'transfer_scope_count', 0,
          'unseeded_transfer_scope_count', 0,
          'review_scope_count', 0,
          'membership_seed_required', false,
          'no_transfer_scope', true,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
          'missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
          'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
          'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
          'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
          'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
          'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
          'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
          'scoped_positive_bank_payment_total', ROUND(COALESCE(v_scoped_projection_positive_payment_total, 0), 2),
          'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
          'paye_net_state_hash', v_global_projection_paye_net_state_hash,
          'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
          'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
          'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
          'has_more_transfer_groups', false,
          'has_more_membership_seed', false,
          'next_transfer_scope_id', NULL::text,
          'next_cursor', NULL::jsonb,
          'next_required_phase', 'START_AUTHORISATION_PROOF',
          'server_utc', v_now::text
        );
      END IF;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          phase = 'REVIEW_REQUIRED',
          progress_json = jsonb_strip_nulls(
            coalesce(operation_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_transfer_scope_seed_at_utc', v_now::text,
              'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
              'transfer_scope_group_seed_complete', true,
              'transfer_scope_count', 0,
              'unseeded_transfer_scope_count', 0,
              'membership_seed_required', false,
              'no_transfer_scope', true,
              'next_required_phase', 'REVIEW_REQUIRED'
            )
          ),
          updated_at_utc = v_now
      WHERE operation_update.id = p_operation_id;

      RETURN jsonb_build_object(
        'ok', false,
        'code', 'NO_ELIGIBLE_TRANSFER_SCOPE',
        'message', 'No eligible payable transfer scope was available for this operation.',
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'bounded', true,
        'limit', v_limit,
        'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
        'source_item_page_count', 0,
        'group_seeded_count', 0,
        'membership_seeded_count', 0,
        'transfer_scope_count', 0,
        'unseeded_transfer_scope_count', 0,
        'review_scope_count', coalesce(v_review_scope_count, 0),
        'membership_seed_required', false,
        'no_transfer_scope', true,
        'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
        'no_bank_payment_execution', v_no_bank_payment_execution,
        'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
        'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
        'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
        'has_more_transfer_groups', false,
        'has_more_membership_seed', false,
        'next_transfer_scope_id', NULL::text,
        'next_cursor', NULL::jsonb,
        'next_required_phase', 'REVIEW_REQUIRED',
        'server_utc', v_now::text
      );
  END IF;

  v_membership_seed_required := coalesce(v_has_more, false) IS NOT TRUE AND coalesce(v_unseeded_transfer_scope_count, 0) > 0;
  v_next_required_phase := CASE
    WHEN coalesce(v_has_more, false) THEN 'TRANSFER_GROUP_SEED_PAGE'
    WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS'
    ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS'
  END;

  UPDATE public.banking_pay_operations AS operation_update
  SET pay_batch_id = p_pay_batch_id,
      phase = CASE
        WHEN coalesce(v_has_more, false) THEN 'SEED_TRANSFER_SCOPE'
        WHEN coalesce(v_membership_seed_required, false) THEN 'SEED_TRANSFER_SCOPE_ITEMS'
        ELSE 'SEED_TRANSFER_ROLLUP_CHUNKS'
      END,
      runner_state = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.runner_state ELSE 'RUNNABLE' END,
      run_after_utc = CASE WHEN upper(btrim(coalesce(operation_update.status, ''))) = 'REVIEW_REQUIRED' THEN operation_update.run_after_utc ELSE v_now END,
      progress_json = jsonb_strip_nulls(
        coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_transfer_scope_seed_at_utc', v_now::text,
          'last_transfer_scope_seed_phase', 'TRANSFER_GROUP_SEED_PAGE',
          'transfer_scope_group_seed_complete', coalesce(v_has_more, false) IS NOT TRUE,
          'transfer_scope_count', coalesce(v_cached_scope_count, 0),
          'unseeded_transfer_scope_count', CASE WHEN coalesce(v_has_more, false) THEN NULL::integer ELSE coalesce(v_unseeded_transfer_scope_count, 0) END,
          'membership_seed_required', coalesce(v_membership_seed_required, false),
          'next_transfer_scope_id', CASE WHEN coalesce(v_membership_seed_required, false) AND v_next_transfer_scope_id IS NOT NULL THEN v_next_transfer_scope_id::text ELSE NULL::text END,
          'has_more_transfer_groups', coalesce(v_has_more, false),
          'transfer_scope_seed_cursor', CASE WHEN coalesce(v_has_more, false) THEN v_next_cursor ELSE NULL::jsonb END,
          'next_required_phase', v_next_required_phase,
          'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
          'no_bank_payment_execution', v_no_bank_payment_execution,
          'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes
        )
        || v_no_bank_proof_json
        || JSONB_BUILD_OBJECT('no_bank_payment_proof', v_no_bank_proof_json)
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'pay_channel_scope', v_scope,
    'bounded', true,
    'limit', v_limit,
    'phase_completed', 'TRANSFER_GROUP_SEED_PAGE',
    'source_item_page_count', LEAST(coalesce(v_page_count, 0), v_limit),
    'group_seeded_count', coalesce(v_group_seeded_count, 0),
    'membership_seeded_count', 0,
    'transfer_scope_count', coalesce(v_cached_scope_count, 0),
    'unseeded_transfer_scope_count', CASE WHEN coalesce(v_has_more, false) THEN NULL::integer ELSE coalesce(v_unseeded_transfer_scope_count, 0) END,
    'review_scope_count', coalesce(v_review_scope_count, 0),
    'membership_seed_required', coalesce(v_membership_seed_required, false),
    'no_transfer_scope', false,
    'scoped_no_transfer_execution', v_scoped_no_transfer_execution,
    'no_bank_payment_execution', v_no_bank_payment_execution,
    'allow_explicit_zero_no_bank_scopes', v_allow_explicit_zero_no_bank_scopes,
    'global_missing_explicit_paye_input_count', COALESCE(v_global_projection_missing_paye_count, 0),
    'global_explicit_zero_count', COALESCE(v_global_projection_explicit_zero_count, 0),
    'global_positive_bank_payment_count', COALESCE(v_global_projection_positive_payment_count, 0),
    'global_invalid_payment_row_count', COALESCE(v_global_projection_invalid_payment_row_count, 0),
    'scoped_missing_explicit_paye_input_count', COALESCE(v_scoped_projection_missing_paye_count, 0),
    'scoped_explicit_zero_count', COALESCE(v_scoped_projection_explicit_zero_count, 0),
    'scoped_positive_bank_payment_count', COALESCE(v_scoped_projection_positive_payment_count, 0),
    'scoped_invalid_payment_row_count', COALESCE(v_scoped_projection_invalid_payment_row_count, 0),
    'paye_net_state_hash', v_global_projection_paye_net_state_hash,
    'global_bank_payment_projection_hash', v_global_projection_bank_payment_hash,
    'scoped_paye_net_state_hash', v_scoped_projection_paye_net_state_hash,
    'bank_payment_projection_hash', v_scoped_projection_bank_payment_hash,
    'has_more_transfer_groups', coalesce(v_has_more, false),
    'has_more_membership_seed', coalesce(v_membership_seed_required, false),
    'next_transfer_scope_id', CASE WHEN coalesce(v_membership_seed_required, false) AND v_next_transfer_scope_id IS NOT NULL THEN v_next_transfer_scope_id::text ELSE NULL::text END,
    'next_cursor', CASE WHEN coalesce(v_has_more, false) THEN v_next_cursor ELSE NULL::jsonb END,
    'next_required_phase', v_next_required_phase,
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_execute_bank(uuid,text,uuid,boolean,uuid,jsonb,boolean,boolean)
CREATE OR REPLACE FUNCTION public.pay_execute_bank(p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid, p_retry_blocked_funds boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_transfer_scope_ids jsonb DEFAULT NULL::jsonb, p_operation_mode boolean DEFAULT false, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_operation_type text := CASE WHEN coalesce(p_retry_blocked_funds, false) THEN 'PAYMENT_RETRY_BLOCKED_FUNDS' ELSE 'PAYMENT_EXECUTE' END;
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_id uuid := p_operation_id;
  v_created boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_progress_light jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_ACTOR_USER_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_ACTOR_USER_ID_REQUIRED', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_SCOPE_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_SCOPE_INVALID', 'pay_channel_scope', p_pay_channel_scope)::text;
  END IF;

  IF coalesce(p_allow_legacy_unchunked, false) IS TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_LEGACY_INLINE_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_LEGACY_INLINE_DISABLED',
        'message', 'Banking Pay execution is now backend-runner owned and cannot execute inline from the click path.'
      )::text;
  END IF;

  IF p_transfer_scope_ids IS NOT NULL
     AND jsonb_typeof(p_transfer_scope_ids) = 'array'
     AND jsonb_array_length(p_transfer_scope_ids) > 0 THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_ARRAY_DISABLED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_TRANSFER_SCOPE_ARRAY_DISABLED',
        'message', 'pay_execute_bank only starts or reuses a durable backend-owned operation. Transfer scope arrays are not accepted on the hot path.'
      )::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_ACTOR_NOT_ACTIVE'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_ACTOR_NOT_ACTIVE', 'actor_user_id', p_actor_user_id::text)::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BATCH_NOT_FOUND', 'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  IF v_execution_commit_state <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_EXECUTION_BOUNDARY_CROSSED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_strip_nulls(jsonb_build_object(
        'code', 'PAY_EXECUTE_BANK_EXECUTION_BOUNDARY_CROSSED',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref_present', nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
        'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END
      ))::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) = 'BLOCKED_FUNDS' AND coalesce(p_retry_blocked_funds, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_RETRY_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_RETRY_REQUIRED', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF coalesce(p_retry_blocked_funds, false) IS TRUE AND upper(btrim(coalesce(v_batch_row.status, ''))) <> 'BLOCKED_FUNDS' THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_STATUS_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BLOCKED_FUNDS_STATUS_MISMATCH', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF upper(btrim(coalesce(v_batch_row.status, ''))) NOT IN ('DRAFT', 'READY', 'PARTIAL', 'WAITING_BANK_CONFIRM', 'DRAFT_CREATED', 'BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'PAY_EXECUTE_BANK_BATCH_STATUS_INVALID'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_BATCH_STATUS_INVALID', 'pay_batch_id', p_pay_batch_id::text, 'status', v_batch_row.status)::text;
  END IF;

  IF v_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = v_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_NOT_FOUND'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_NOT_FOUND', 'operation_id', v_operation_id::text)::text;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_BATCH_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_BATCH_MISMATCH', 'operation_id', v_operation_id::text, 'operation_pay_batch_id', v_operation_row.pay_batch_id::text, 'pay_batch_id', p_pay_batch_id::text)::text;
    END IF;

    IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) <> v_operation_type THEN
      RAISE EXCEPTION 'PAY_EXECUTE_BANK_OPERATION_TYPE_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_EXECUTE_BANK_OPERATION_TYPE_MISMATCH', 'operation_id', v_operation_id::text, 'operation_type', v_operation_row.operation_type, 'expected_operation_type', v_operation_type)::text;
    END IF;
  ELSE
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(operation_row.operation_type, ''))) = v_operation_type
      AND upper(btrim(coalesce(operation_row.status, ''))) NOT IN ('COMPLETE', 'COMPLETED', 'FAILED', 'CANCELLED', 'CANCELED')
      AND upper(btrim(coalesce(operation_row.input_json->>'pay_channel_scope', operation_row.input_json->>'payChannelScope', 'ALL'))) = v_scope
    ORDER BY operation_row.created_at_utc DESC NULLS LAST, operation_row.id DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      v_operation_id := v_operation_row.id;
    END IF;
  END IF;

  IF v_operation_id IS NULL THEN
    INSERT INTO public.banking_pay_operations (
      operation_type,
      status,
      phase,
      actor_user_id,
      pay_batch_id,
      idempotency_key,
      input_json,
      config_json,
      progress_json,
      result_json,
      error_json,
      total_units,
      completed_units,
      failed_units,
      current_chunk_index,
      chunk_count,
      runner_state,
      run_after_utc,
      requires_user_action,
      resume_reason,
      created_at_utc,
      started_at_utc,
      updated_at_utc
    )
    VALUES (
      v_operation_type,
      'RUNNING',
      'PREPARE_TRANSFER_SCOPE',
      p_actor_user_id,
      p_pay_batch_id,
      'pay_execute_bank:' || p_pay_batch_id::text || ':' || v_operation_type || ':' || v_scope,
      jsonb_strip_nulls(jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_scope,
        'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
        'source_rpc', 'pay_execute_bank'
      )),
      jsonb_build_object('entrypoint', 'pay_execute_bank', 'durable_operation', true, 'backend_owned', true),
      jsonb_build_object(
        'started_from_entrypoint_at_utc', v_now::text,
        'next_required_phase', 'TRANSFER_SCOPE_SEED',
        'progress_is_lightweight', true
      ),
      '{}'::jsonb,
      NULL::jsonb,
      0,
      0,
      0,
      0,
      0,
      'RUNNABLE',
      v_now,
      false,
      'TRANSFER_SCOPE_SEED_REQUIRED',
      v_now,
      v_now,
      v_now
    )
    RETURNING * INTO v_operation_row;

    v_operation_id := v_operation_row.id;
    v_created := true;
  ELSE
    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        actor_user_id = coalesce(operation_update.actor_user_id, p_actor_user_id),
        status = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.status
          ELSE 'RUNNING'
        END,
        phase = coalesce(nullif(btrim(operation_update.phase), ''), 'PREPARE_TRANSFER_SCOPE'),
        runner_state = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.runner_state
          ELSE 'RUNNABLE'
        END,
        run_after_utc = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION', 'WAITING_PROVIDER') THEN operation_update.run_after_utc
          ELSE v_now
        END,
        requires_user_action = CASE
          WHEN upper(btrim(coalesce(operation_update.status, ''))) IN ('REVIEW_REQUIRED', 'WAITING_AUTHORISATION') THEN true
          ELSE coalesce(operation_update.requires_user_action, false)
        END,
        resume_reason = coalesce(nullif(btrim(operation_update.resume_reason), ''), 'TRANSFER_SCOPE_SEED_REQUIRED'),
        input_json = jsonb_strip_nulls(coalesce(operation_update.input_json, '{}'::jsonb) || jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_scope,
          'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
          'source_rpc', 'pay_execute_bank'
        )),
        progress_json = jsonb_strip_nulls(coalesce(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
          'last_entrypoint_reuse_at_utc', v_now::text,
          'next_required_phase', coalesce(operation_update.progress_json->>'next_required_phase', 'TRANSFER_SCOPE_SEED'),
          'progress_is_lightweight', true
        )),
        updated_at_utc = v_now
    WHERE operation_update.id = v_operation_id
    RETURNING * INTO v_operation_row;
  END IF;

  UPDATE public.pay_batches AS batch_update
  SET execution_intent_json = jsonb_strip_nulls(coalesce(batch_update.execution_intent_json, '{}'::jsonb) || jsonb_build_object(
        'operation_id', v_operation_id::text,
        'operation_type', v_operation_type,
        'pay_channel_scope', v_scope,
        'durable_execution', true,
        'backend_owned_execution', true
      ))
  WHERE batch_update.id = p_pay_batch_id;

  BEGIN
    PERFORM public.banking_pay_batch_signal_touch(
      p_pay_batch_id,
      'execution_operation_started',
      'pay_execute_bank',
      jsonb_build_object('actor_user_id', p_actor_user_id::text, 'operation_id', v_operation_id::text),
      true,
      false,
      false,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  v_progress_light := jsonb_strip_nulls(jsonb_build_object(
    'next_required_phase', coalesce(v_operation_row.progress_json->>'next_required_phase', 'TRANSFER_SCOPE_SEED'),
    'last_entrypoint_reuse_at_utc', v_operation_row.progress_json->>'last_entrypoint_reuse_at_utc',
    'last_advanced_at_utc', CASE WHEN v_operation_row.last_advanced_at_utc IS NULL THEN NULL ELSE v_operation_row.last_advanced_at_utc::text END,
    'heartbeat_at_utc', CASE WHEN v_operation_row.heartbeat_at_utc IS NULL THEN NULL ELSE v_operation_row.heartbeat_at_utc::text END,
    'total_units', coalesce(v_operation_row.total_units, 0),
    'completed_units', coalesce(v_operation_row.completed_units, 0),
    'failed_units', coalesce(v_operation_row.failed_units, 0),
    'current_chunk_index', coalesce(v_operation_row.current_chunk_index, 0),
    'chunk_count', coalesce(v_operation_row.chunk_count, 0),
    'progress_is_lightweight', true
  ));

  RETURN jsonb_build_object(
    'ok', true,
    'durable_operation', true,
    'operation_created', v_created,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', v_operation_id::text,
    'operation_type', v_operation_type,
    'operation_status', v_operation_row.status,
    'operation_phase', v_operation_row.phase,
    'runner_state', v_operation_row.runner_state,
    'run_after_utc', CASE WHEN v_operation_row.run_after_utc IS NULL THEN NULL ELSE v_operation_row.run_after_utc::text END,
    'requires_user_action', coalesce(v_operation_row.requires_user_action, false),
    'pay_channel_scope', v_scope,
    'retry_blocked_funds', coalesce(p_retry_blocked_funds, false),
    'progress_light', v_progress_light,
    'legacy_inline_execution_disabled', true,
    'backend_owned_execution', true,
    'provider_submission_events_insertable', false,
    'provider_submission_event_payloads', '[]'::jsonb,
    'transfers', '[]'::jsonb,
    'server_utc', v_now::text
  );
END;
$function$;

-- pay_execute_operation_cleanup_failed_local_artifacts(uuid,uuid,text,jsonb,boolean)
CREATE OR REPLACE FUNCTION public.pay_execute_operation_cleanup_failed_local_artifacts(p_operation_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_failure_phase text DEFAULT NULL::text, p_failure_error_json jsonb DEFAULT '{}'::jsonb, p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_pay_batch_id uuid := NULL::uuid;
  v_freshness_state_cleared integer := 0;
BEGIN
  v_result := COALESCE(public._pay_execute_operation_cleanup_failed_local_artifacts_base(
    p_operation_id,
    p_actor_user_id,
    p_failure_phase,
    p_failure_error_json,
    p_dry_run
  ), '{}'::jsonb);

  IF COALESCE(p_dry_run, false) IS FALSE
     AND COALESCE((v_result->>'safe_to_retry')::boolean, false) IS TRUE
     AND COALESCE((v_result->>'retry_blocked')::boolean, true) IS FALSE
     AND COALESCE((v_result->>'review_required')::boolean, true) IS FALSE THEN
    SELECT operation_row.pay_batch_id
    INTO v_pay_batch_id
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    LIMIT 1;

    UPDATE public.pay_batches AS batch_update
    SET freshness_operation_id = NULL::uuid,
        freshness_validation_status = NULL::text,
        freshness_checked_at_utc = NULL::timestamptz,
        freshness_result_hash = NULL::text,
        freshness_scope_hash = NULL::text,
        freshness_result_json = '{}'::jsonb
    WHERE batch_update.id = v_pay_batch_id
      AND batch_update.freshness_operation_id = p_operation_id
      AND upper(BTRIM(COALESCE(batch_update.status, ''))) IN ('DRAFT', 'DRAFT_CREATED')
      AND upper(BTRIM(COALESCE(batch_update.execution_commit_state, 'NOT_SUBMITTED'))) = 'NOT_SUBMITTED'
      AND NULLIF(BTRIM(COALESCE(batch_update.execution_commit_ref, '')), '') IS NULL
      AND batch_update.execution_committed_at_utc IS NULL;
    GET DIAGNOSTICS v_freshness_state_cleared = ROW_COUNT;

    IF v_freshness_state_cleared > 0 THEN
      BEGIN
        PERFORM public.pay_batch_display_summary_touch(v_pay_batch_id);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;

      BEGIN
        PERFORM public.banking_pay_batch_signal_touch(
          v_pay_batch_id,
          'PAYMENT_EXECUTION_OBSOLETE_FRESHNESS_CLEARED',
          'pay_execute_operation_cleanup_failed_local_artifacts',
          jsonb_build_object(
            'operation_id', p_operation_id::text,
            'freshness_state_cleared', true,
            'safe_to_retry', true
          ),
          true,
          false,
          false,
          true
        );
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
  END IF;

  RETURN v_result || jsonb_build_object(
    'freshness_state_cleared', COALESCE(v_freshness_state_cleared, 0)
  );
END;
$function$;

-- pay_execute_provider_submit_review_resolve(uuid,uuid,text,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_execute_provider_submit_review_resolve(p_pay_batch_id uuid, p_operation_id uuid, p_resolution_action text, p_confirmation_json jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_resolution_action text := upper(btrim(coalesce(p_resolution_action, '')));
  v_confirmation_json jsonb := '{}'::jsonb;
  v_checked_provider_or_bank boolean := false;
  v_confirmed_no_payment_made boolean := false;
  v_provider_checked text := NULL::text;
  v_checked_at_text text := NULL::text;
  v_checked_at_utc timestamptz := NULL::timestamptz;
  v_notes text := NULL::text;
  v_confirmation_redacted jsonb := '{}'::jsonb;
  v_chunk_id uuid := NULL::uuid;
  v_requested_scope_count integer := 0;
  v_scope_count integer := 0;
  v_transfer_count integer := 0;
  v_reset_scope_count integer := 0;
  v_reset_transfer_count integer := 0;
  v_chunk_rows_updated integer := 0;
  v_remaining_review_scope_count integer := 0;
  v_remaining_ready_scope_count integer := 0;
  v_attempt_rows integer := 0;
  v_resolved_transfer_scope_ids jsonb := '[]'::jsonb;
  v_resolved_transfer_ids jsonb := '[]'::jsonb;
  v_backend_work_remaining boolean := false;
  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_pay_batch_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_operation_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_actor_user_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_resolution_action <> 'CONFIRM_NO_PAYMENT_MADE_AND_RESET_FOR_RETRY' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'UNSUPPORTED_RESOLUTION_ACTION',
      'message', 'Unsupported provider-submit review resolution action',
      'resolution_action', coalesce(p_resolution_action, '')
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_confirmation_json IS NULL OR jsonb_typeof(p_confirmation_json) <> 'object' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'CONFIRMATION_JSON_REQUIRED',
      'message', 'p_confirmation_json must be a JSON object'
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_confirmation_json := p_confirmation_json;
  v_checked_provider_or_bank := lower(btrim(coalesce(v_confirmation_json->>'checked_provider_or_bank', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_confirmed_no_payment_made := lower(btrim(coalesce(v_confirmation_json->>'confirmed_no_payment_made', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_checked := upper(btrim(coalesce(v_confirmation_json->>'provider_checked', '')));
  v_checked_at_text := NULLIF(btrim(coalesce(v_confirmation_json->>'checked_at_utc', '')), '');
  v_notes := NULLIF(btrim(coalesce(v_confirmation_json->>'notes', '')), '');

  IF COALESCE(v_confirmation_json->>'chunk_id', v_confirmation_json->>'provider_chunk_id', '') ~* v_uuid_regex THEN
    v_chunk_id := COALESCE(v_confirmation_json->>'chunk_id', v_confirmation_json->>'provider_chunk_id')::uuid;
  END IF;

  IF v_checked_at_text IS NOT NULL THEN
    BEGIN
      v_checked_at_utc := v_checked_at_text::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
        'code', 'CHECKED_AT_UTC_INVALID',
        'checked_at_utc', v_checked_at_text
      )::text USING ERRCODE = 'P0001';
    END;
  ELSE
    v_checked_at_utc := v_now;
  END IF;

  IF v_checked_provider_or_bank IS NOT TRUE OR v_confirmed_no_payment_made IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PROVIDER_REVIEW_CONFIRMATION_REQUIRED',
      'message', 'Resolution requires confirmation that the provider/bank was checked and no payment was made.'
    )::text USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'ACTOR_USER_NOT_ACTIVE',
      'actor_user_id', p_actor_user_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_NOT_FOUND',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_BATCH_MISMATCH',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', v_operation_row.pay_batch_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_TYPE_NOT_SUPPORTED',
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_review_resolve_scope_request;
  CREATE TEMPORARY TABLE pg_temp.tmp_review_resolve_scope_request (
    transfer_scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  IF v_chunk_id IS NOT NULL THEN
    INSERT INTO pg_temp.tmp_review_resolve_scope_request (transfer_scope_id)
    SELECT scope_row.id
    FROM public.banking_pay_operation_transfer_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id
      AND scope_row.provider_submit_chunk_id = v_chunk_id
    ORDER BY scope_row.id
    LIMIT 100
    ON CONFLICT DO NOTHING;
  END IF;

  IF jsonb_typeof(v_confirmation_json->'transfer_scope_ids') = 'array' THEN
    INSERT INTO pg_temp.tmp_review_resolve_scope_request (transfer_scope_id)
    SELECT DISTINCT scope_id_value.scope_id_text::uuid
    FROM (
      SELECT scope_value.value #>> '{}' AS scope_id_text
      FROM jsonb_array_elements(v_confirmation_json->'transfer_scope_ids') AS scope_value(value)
    ) AS scope_id_value
    WHERE scope_id_value.scope_id_text ~* v_uuid_regex
    LIMIT 100
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_requested_scope_count
  FROM pg_temp.tmp_review_resolve_scope_request AS requested_scope;

  IF v_requested_scope_count <= 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_REQUIRED',
      'message', 'Review resolution requires a provider chunk id or capped transfer_scope_ids.',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_requested_scope_count > 100 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_TOO_LARGE',
      'scope_count', v_requested_scope_count,
      'limit', 100
    )::text USING ERRCODE = 'P0001';
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_review_resolve_scope;
  CREATE TEMPORARY TABLE pg_temp.tmp_review_resolve_scope ON COMMIT DROP AS
  SELECT scope_row.id AS transfer_scope_id,
         scope_row.pay_bank_transfer_id,
         scope_row.provider_submit_state AS previous_provider_submit_state,
         scope_row.provider_idempotency_key,
         scope_row.provider_request_id,
         scope_row.provider_transaction_id
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  JOIN pg_temp.tmp_review_resolve_scope_request AS requested_scope
    ON requested_scope.transfer_scope_id = scope_row.id
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
  FOR UPDATE OF scope_row;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE resolve_scope.pay_bank_transfer_id IS NOT NULL)::integer,
         COALESCE(jsonb_agg(to_jsonb(resolve_scope.transfer_scope_id::text) ORDER BY resolve_scope.transfer_scope_id), '[]'::jsonb),
         COALESCE(jsonb_agg(to_jsonb(resolve_scope.pay_bank_transfer_id::text) ORDER BY resolve_scope.pay_bank_transfer_id) FILTER (WHERE resolve_scope.pay_bank_transfer_id IS NOT NULL), '[]'::jsonb)
  INTO v_scope_count,
       v_transfer_count,
       v_resolved_transfer_scope_ids,
       v_resolved_transfer_ids
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope;

  IF v_scope_count <> v_requested_scope_count THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'REVIEW_SCOPE_NOT_FOUND_OR_NOT_IN_OPERATION',
      'requested_scope_count', v_requested_scope_count,
      'matched_scope_count', v_scope_count,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_confirmation_redacted := jsonb_strip_nulls(v_confirmation_json
    - 'account_number'
    - 'sort_code'
    - 'iban'
    - 'access_token'
    - 'authorization'
    || jsonb_build_object(
      'checked_provider_or_bank', v_checked_provider_or_bank,
      'confirmed_no_payment_made', v_confirmed_no_payment_made,
      'provider_checked', NULLIF(v_provider_checked, ''),
      'checked_at_utc', v_checked_at_utc::text,
      'notes_present', v_notes IS NOT NULL,
      'actor_user_id', p_actor_user_id::text
    )
  );

  UPDATE public.pay_bank_transfers AS transfer_update
  SET status = 'PENDING',
      rail_tx_id = NULL::text,
      rail_state = NULL::text,
      completed_at_utc = NULL::timestamptz,
      failed_reason = NULL::text,
      rail_meta_json = jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'manual_provider_review_resolved_at_utc', v_now::text,
        'manual_provider_review_resolution', 'CONFIRMED_NO_PAYMENT_MADE',
        'manual_provider_review_actor_user_id', p_actor_user_id::text,
        'manual_provider_review_operation_id', p_operation_id::text,
        'manual_provider_review_chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'manual_provider_review_checked_at_utc', v_checked_at_utc::text,
        'provider_submit_diagnostic', jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object(
          'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
          'review_reason_code', 'MANUAL_CONFIRMED_NO_PAYMENT_MADE',
          'manual_resolution_required', false,
          'manual_resolution_at_utc', v_now::text,
          'manual_resolution_actor_user_id', p_actor_user_id::text
        ))
      ))
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  WHERE transfer_update.id = resolve_scope.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_reset_transfer_count = ROW_COUNT;

  UPDATE public.banking_pay_operation_transfer_scope AS scope_update
  SET provider_submit_state = 'READY',
      provider_submit_ready = true,
      provider_submit_chunk_id = NULL::uuid,
      provider_submit_claimed_at_utc = NULL::timestamptz,
      provider_request_prepared_at_utc = NULL::timestamptz,
      provider_request_sending_at_utc = NULL::timestamptz,
      provider_request_sent_at_utc = NULL::timestamptz,
      provider_response_at_utc = NULL::timestamptz,
      provider_submission_status = 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
      provider_review_required = false,
      provider_unsafe_reason = NULL::text,
      status = 'PREPARED',
      updated_at_utc = v_now
  FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  WHERE scope_update.id = resolve_scope.transfer_scope_id
    AND scope_update.operation_id = p_operation_id
    AND scope_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_reset_scope_count = ROW_COUNT;

  IF v_chunk_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET status = 'COMPLETE',
        result_json = jsonb_strip_nulls(COALESCE(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
          'manual_review_resolved', true,
          'manual_review_resolved_at_utc', v_now::text,
          'resolution_action', v_resolution_action,
          'confirmation', v_confirmation_redacted,
          'resolved_transfer_scope_count', COALESCE(v_reset_scope_count, 0),
          'resolved_transfer_count', COALESCE(v_reset_transfer_count, 0)
        )),
        error_json = NULL::jsonb,
        completed_at_utc = COALESCE(chunk_update.completed_at_utc, v_now),
        updated_at_utc = v_now
    WHERE chunk_update.id = v_chunk_id
      AND chunk_update.operation_id = p_operation_id;
    GET DIAGNOSTICS v_chunk_rows_updated = ROW_COUNT;
  END IF;

  SELECT count(*)::integer
  INTO v_attempt_rows
  FROM (
    SELECT public.banking_pay_operation_provider_attempt_record(
      p_operation_id => p_operation_id,
      p_pay_batch_id => p_pay_batch_id,
      p_transfer_scope_id => resolve_scope.transfer_scope_id,
      p_provider_chunk_id => v_chunk_id,
      p_idempotency_key => resolve_scope.provider_idempotency_key,
      p_request_id => resolve_scope.provider_request_id,
      p_provider_transaction_id => resolve_scope.provider_transaction_id,
      p_previous_state => resolve_scope.previous_provider_submit_state,
      p_new_state => 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
      p_lease_owner => NULL::text,
      p_request_json => NULL::jsonb,
      p_response_json => NULL::jsonb,
      p_error_json => jsonb_build_object('manual_review_resolution', v_confirmation_redacted),
      p_actor_user_id => p_actor_user_id
    ) AS attempt_result
    FROM pg_temp.tmp_review_resolve_scope AS resolve_scope
  ) AS attempt_calls;

  SELECT count(*)::integer
  INTO v_remaining_review_scope_count
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND (
      coalesce(scope_row.provider_review_required, false) = true
      OR upper(btrim(coalesce(scope_row.provider_submit_state, ''))) IN ('PROVIDER_UNKNOWN', 'REVIEW_REQUIRED', 'PROVIDER_REJECTED')
    );

  SELECT count(*)::integer
  INTO v_remaining_ready_scope_count
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(scope_row.status, ''))) = 'PREPARED'
    AND coalesce(scope_row.provider_submit_ready, false) = true
    AND upper(btrim(coalesce(scope_row.provider_submit_state, ''))) = 'READY';

  v_backend_work_remaining := COALESCE(v_remaining_review_scope_count, 0) = 0 AND COALESCE(v_remaining_ready_scope_count, 0) > 0;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'REVIEW_REQUIRED' ELSE 'RUNNING' END,
      runner_state = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'WAITING_USER_REVIEW' ELSE 'RUNNABLE' END,
      requires_user_action = COALESCE(v_remaining_review_scope_count, 0) > 0,
      run_after_utc = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN NULL::timestamptz ELSE v_now END,
      resume_reason = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) > 0 THEN 'PROVIDER_REVIEW_REMAINS' ELSE 'PROVIDER_REVIEW_RESOLVED_CONTINUE_EXECUTION' END,
      progress_json = jsonb_strip_nulls(COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'provider_review_resolved_at_utc', v_now::text,
        'provider_review_resolution_action', v_resolution_action,
        'provider_review_resolved_scope_count', COALESCE(v_reset_scope_count, 0),
        'provider_review_remaining_scope_count', COALESCE(v_remaining_review_scope_count, 0),
        'provider_ready_scope_count_after_review', COALESCE(v_remaining_ready_scope_count, 0),
        'next_required_phase', CASE WHEN COALESCE(v_remaining_ready_scope_count, 0) > 0 THEN 'CLAIM_PROVIDER_SUBMIT_CHUNK' ELSE operation_update.progress_json->>'next_required_phase' END
      )),
      error_json = CASE WHEN COALESCE(v_remaining_review_scope_count, 0) = 0 THEN NULL::jsonb ELSE operation_update.error_json END,
      locked_by = NULL::text,
      lock_expires_at_utc = NULL::timestamptz,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  BEGIN
    PERFORM public.pay_batch_display_summary_touch(p_pay_batch_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    PERFORM public.banking_pay_batch_signal_touch(
      p_pay_batch_id,
      'PROVIDER_SUBMIT_REVIEW_RESOLVED',
      'pay_execute_provider_submit_review_resolve',
      jsonb_strip_nulls(jsonb_build_object(
        'operation_id', p_operation_id::text,
        'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
        'resolution_action', v_resolution_action,
        'resolved_scope_count', COALESCE(v_reset_scope_count, 0),
        'remaining_review_scope_count', COALESCE(v_remaining_review_scope_count, 0)
      )),
      true,
      false,
      COALESCE(v_remaining_review_scope_count, 0) > 0,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  v_result := jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'manual_review_resolved', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'chunk_id', CASE WHEN v_chunk_id IS NULL THEN NULL ELSE v_chunk_id::text END,
    'resolution_action', v_resolution_action,
    'resolution_scope', CASE WHEN v_chunk_id IS NOT NULL THEN 'PROVIDER_CHUNK' ELSE 'TRANSFER_SCOPE_IDS' END,
    'confirmed_no_payment_made', v_confirmed_no_payment_made,
    'checked_provider_or_bank', v_checked_provider_or_bank,
    'provider_checked', NULLIF(v_provider_checked, ''),
    'checked_at_utc', v_checked_at_utc::text,
    'notes_present', v_notes IS NOT NULL,
    'resolved_transfer_scope_ids', COALESCE(v_resolved_transfer_scope_ids, '[]'::jsonb),
    'resolved_transfer_ids', COALESCE(v_resolved_transfer_ids, '[]'::jsonb),
    'resolved_transfer_scope_count', COALESCE(v_reset_scope_count, 0),
    'resolved_transfer_count', COALESCE(v_reset_transfer_count, 0),
    'chunk_rows_updated', COALESCE(v_chunk_rows_updated, 0),
    'provider_attempt_rows_recorded', COALESCE(v_attempt_rows, 0),
    'remaining_review_scope_count', COALESCE(v_remaining_review_scope_count, 0),
    'provider_ready_scope_count_after_review', COALESCE(v_remaining_ready_scope_count, 0),
    'backend_work_remaining', COALESCE(v_backend_work_remaining, false),
    'operation_runnable', COALESCE(v_remaining_review_scope_count, 0) = 0,
    'server_utc', v_now::text
  ));

  RETURN v_result;
END;
$function$;

-- pay_export_bank_csv(uuid,text)
CREATE OR REPLACE FUNCTION public.pay_export_bank_csv(p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));

  v_default_cols jsonb := '["payment_reference","payee_name","sort_code","account_number","amount"]'::jsonb;
  v_cols_json jsonb;
  v_cols text[];
  v_col text;

  v_allowed_cols text[] := array[
    'transfer_id',
    'payment_reference',
    'payee_name',
    'sort_code',
    'account_number',
    'account_type',
    'amount',
    'currency',
    'pay_channel',
    'rail_provider',
    'rail_env',
    'request_id',
    'transfer_group_key',
    'grouping_mode_used',
    'week_ending_bucket',
    'candidate_id',
    'umbrella_id',
    'payee_entity_kind',
    'payee_entity_id',
    'bank_details_hash_snapshot'
  ];

  v_format_json jsonb := '{}'::jsonb;
  v_headers_json jsonb := '{}'::jsonb;
  v_include_header boolean := true;
  v_delimiter text := ',';
  v_line_ending text := E'\n';
  v_line_ending_key text := 'LF';
  v_quote_mode text := 'MINIMAL';
  v_bom boolean := false;
  v_sort_code_format text := 'AS_STORED';
  v_account_number_format text := 'AS_STORED';
  v_amount_decimals int := 2;
  v_empty_value text := '';

  v_header text := '';
  v_body text := '';
  v_csv text := '';

  v_missing_count int := 0;
  v_row_count int := 0;
  v_missing_paye_net_count int := 0;
  v_explicit_zero_count int := 0;
  v_positive_bank_payment_count int := 0;
  v_invalid_payment_row_count int := 0;

  v_hdr_part text;
  v_hdr_override text;
  v_val text;
  v_line text;
  v_digits text;

  v_batch_created_by_user_id uuid := null;
  v_batch_kind_fixed text := null;
  v_batch_status text := null;
  v_cancelled_at_utc timestamptz := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;
  v_pre_execution_export boolean := false;
  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  r record;
begin
  if v_scope not in ('ALL','PAYE','UMBRELLA','LOANS') then
    raise exception 'pay_export_bank_csv: invalid scope "%". Expected ALL|PAYE|UMBRELLA|LOANS.', v_scope;
  end if;

  select
    pb.created_by_user_id,
    upper(btrim(coalesce(pb.batch_kind_fixed, ''))),
    upper(btrim(coalesce(pb.status, ''))),
    pb.cancelled_at_utc,
    upper(btrim(coalesce(pb.execution_commit_state, 'NOT_SUBMITTED'))),
    nullif(btrim(coalesce(pb.execution_commit_ref, '')), ''),
    pb.execution_committed_at_utc,
    upper(btrim(coalesce(pb.freshness_validation_status, ''))),
    nullif(btrim(coalesce(pb.freshness_result_hash, '')), ''),
    nullif(btrim(coalesce(pb.freshness_scope_hash, '')), ''),
    coalesce(pb.freshness_result_json, '{}'::jsonb)
  into
    v_batch_created_by_user_id,
    v_batch_kind_fixed,
    v_batch_status,
    v_cancelled_at_utc,
    v_execution_commit_state,
    v_execution_commit_ref,
    v_execution_committed_at_utc,
    v_freshness_validation_status,
    v_freshness_result_hash,
    v_freshness_scope_hash,
    v_freshness_result_json
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if not found then
    raise exception 'pay_export_bank_csv: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;

  v_pre_execution_export := (
    v_cancelled_at_utc is null
    and v_batch_status not in ('CANCELLED', 'CANCELED')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id,
        coalesce(v_batch_created_by_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
        false
      );
      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_EXPORT_BANK_CSV',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_export_bank_csv: chunked freshness validation is required before payment-initiation export' else 'pay_export_bank_csv: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  -- Load configured CSV column order and formatting.
  -- Column inclusion/order remains controlled by pay_export_csv_columns_json.
  -- Formatting/header behaviour is controlled by pay_export_csv_format_json.
  select
    sd.pay_export_csv_columns_json,
    coalesce(sd.pay_export_csv_format_json, '{}'::jsonb)
  into
    v_cols_json,
    v_format_json
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cols_json is null or jsonb_typeof(v_cols_json) <> 'array' or jsonb_array_length(v_cols_json) = 0 then
    v_cols_json := v_default_cols;
  end if;

  if v_format_json is null or jsonb_typeof(v_format_json) <> 'object' then
    v_format_json := '{}'::jsonb;
  end if;

  if (v_format_json ? 'headers') and jsonb_typeof(v_format_json->'headers') = 'object' then
    v_headers_json := v_format_json->'headers';
  else
    v_headers_json := '{}'::jsonb;
  end if;

  if v_format_json ? 'include_header' then
    begin
      v_include_header := coalesce((v_format_json->>'include_header')::boolean, true);
    exception when others then
      v_include_header := true;
    end;
  end if;

  if v_format_json ? 'bom' then
    begin
      v_bom := coalesce((v_format_json->>'bom')::boolean, false);
    exception when others then
      v_bom := false;
    end;
  end if;

  v_delimiter := coalesce(nullif(v_format_json->>'delimiter', ''), ',');
  if upper(v_delimiter) = 'TAB' then
    v_delimiter := E'\t';
  elsif v_delimiter = '\\t' then
    v_delimiter := E'\t';
  elsif v_delimiter not in (',',';','|',E'\t') then
    v_delimiter := ',';
  end if;

  v_line_ending_key := upper(coalesce(nullif(v_format_json->>'line_ending', ''), 'LF'));
  if v_line_ending_key = 'CRLF' then
    v_line_ending := E'\r\n';
  else
    v_line_ending := E'\n';
  end if;

  v_quote_mode := upper(coalesce(nullif(v_format_json->>'quote_mode', ''), 'MINIMAL'));
  if v_quote_mode not in ('MINIMAL','ALL') then
    v_quote_mode := 'MINIMAL';
  end if;

  v_sort_code_format := upper(coalesce(nullif(v_format_json->>'sort_code_format', ''), 'AS_STORED'));
  if v_sort_code_format not in ('AS_STORED','DIGITS','HYPHENATED') then
    v_sort_code_format := 'AS_STORED';
  end if;

  v_account_number_format := upper(coalesce(nullif(v_format_json->>'account_number_format', ''), 'AS_STORED'));
  if v_account_number_format not in ('AS_STORED','DIGITS') then
    v_account_number_format := 'AS_STORED';
  end if;

  if v_format_json ? 'amount_decimals' then
    begin
      v_amount_decimals := greatest(0, least(4, (v_format_json->>'amount_decimals')::int));
    exception when others then
      v_amount_decimals := 2;
    end;
  end if;

  v_empty_value := coalesce(v_format_json->>'empty_value', '');

  select coalesce(array_agg(t.col order by t.ord), array[]::text[])
  into v_cols
  from jsonb_array_elements_text(v_cols_json) with ordinality as t(col, ord);

  if array_length(v_cols, 1) is null or array_length(v_cols, 1) = 0 then
    v_cols := array['payment_reference','payee_name','sort_code','account_number','amount']::text[];
  end if;

  -- Validate column keys: must be from allowed set.
  foreach v_col in array v_cols loop
    if v_col is null or btrim(v_col) = '' then
      raise exception 'pay_export_bank_csv: export columns contain an empty key';
    end if;

    if not (v_col = any(v_allowed_cols)) then
      raise exception 'pay_export_bank_csv: invalid export column "%". Allowed=%', v_col, array_to_string(v_allowed_cols, ',');
    end if;
  end loop;

  -- Reject duplicates (deterministic export).
  if (
    select count(*)::int
    from unnest(v_cols) x
  ) <> (
    select count(distinct x)::int
    from unnest(v_cols) x
  ) then
    raise exception 'pay_export_bank_csv: duplicate column keys in pay_export_csv_columns_json';
  end if;

  -- Materialise one bounded export row source. Pre-execution rows are projected
  -- directly from frozen batch artefacts; historical/cancelled rows remain the
  -- existing materialised transfer rows.
  DROP TABLE IF EXISTS pg_temp.tmp_pay_export_bank_csv_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_export_bank_csv_rows (
    row_ordinal bigint NOT NULL,
    transfer_id uuid NULL,
    payment_reference text NULL,
    payee_name text NULL,
    sort_code text NULL,
    account_number text NULL,
    account_type text NULL,
    amount numeric NULL,
    currency text NULL,
    pay_channel text NULL,
    rail_provider text NULL,
    rail_env text NULL,
    request_id text NULL,
    transfer_group_key text NULL,
    grouping_mode_used text NULL,
    week_ending_bucket date NULL,
    candidate_id uuid NULL,
    umbrella_id uuid NULL,
    payee_entity_kind text NULL,
    payee_entity_id uuid NULL,
    bank_details_hash_snapshot text NULL
  ) ON COMMIT DROP;

  IF v_pre_execution_export THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_export_bank_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_export_bank_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_scope
    ) AS projection_row;

    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer
    INTO
      v_missing_paye_net_count,
      v_explicit_zero_count,
      v_invalid_payment_row_count
    FROM pg_temp.tmp_pay_export_bank_projection_rows AS projection_row;

    v_missing_paye_net_count := COALESCE(v_missing_paye_net_count, 0);
    v_explicit_zero_count := COALESCE(v_explicit_zero_count, 0);
    v_invalid_payment_row_count := COALESCE(v_invalid_payment_row_count, 0);

    IF v_missing_paye_net_count > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXPORT_BANK_CSV',
        'code', 'PAYE_NET_REQUIRED_FOR_BANK_CSV',
        'message', 'Bank CSV cannot be generated until every required PAYE net amount has been explicitly entered or imported.',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'missing_explicit_paye_input_count', v_missing_paye_net_count
      )::text USING ERRCODE = 'P0001';
    END IF;


    IF v_invalid_payment_row_count > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXPORT_BANK_CSV',
        'code', 'BANK_PAYMENT_PROJECTION_INVALID_FOR_BANK_CSV',
        'message', 'Bank CSV cannot be generated because one or more projected payment rows have a non-positive or otherwise invalid payable amount.',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'invalid_payment_row_count', v_invalid_payment_row_count
      )::text USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO pg_temp.tmp_pay_export_bank_csv_rows (
      row_ordinal,
      transfer_id,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      amount,
      currency,
      pay_channel,
      rail_provider,
      rail_env,
      request_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      bank_details_hash_snapshot
    )
    SELECT
      projection_row.payment_group_ordinal,
      NULL::uuid,
      projection_row.payment_reference,
      projection_row.payee_name,
      projection_row.sort_code,
      projection_row.account_number,
      projection_row.account_type,
      projection_row.amount,
      projection_row.currency,
      projection_row.pay_channel,
      projection_row.rail_provider,
      projection_row.rail_env,
      NULL::text,
      projection_row.transfer_group_key,
      projection_row.grouping_mode_used,
      projection_row.week_ending_bucket,
      projection_row.candidate_id,
      projection_row.umbrella_id,
      projection_row.payee_entity_kind,
      projection_row.payee_entity_id,
      projection_row.bank_details_hash_snapshot
    FROM pg_temp.tmp_pay_export_bank_projection_rows AS projection_row
    WHERE projection_row.is_positive_bank_payment
    ORDER BY projection_row.payment_group_ordinal,
             projection_row.stable_order_key;
  ELSE
    INSERT INTO pg_temp.tmp_pay_export_bank_csv_rows (
      row_ordinal,
      transfer_id,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      amount,
      currency,
      pay_channel,
      rail_provider,
      rail_env,
      request_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      bank_details_hash_snapshot
    )
    SELECT
      ROW_NUMBER() OVER (ORDER BY transfer_row.id),
      transfer_row.id,
      transfer_row.payment_reference,
      transfer_row.payee_name,
      transfer_row.sort_code,
      transfer_row.account_number,
      transfer_row.account_type,
      transfer_row.amount,
      transfer_row.currency,
      transfer_row.pay_channel,
      transfer_row.rail_provider,
      transfer_row.rail_env,
      transfer_row.request_id,
      transfer_row.transfer_group_key,
      transfer_row.grouping_mode_used,
      transfer_row.week_ending_bucket,
      transfer_row.candidate_id,
      transfer_row.umbrella_id,
      transfer_row.payee_entity_kind,
      transfer_row.payee_entity_id,
      transfer_row.bank_details_hash_snapshot
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        v_scope = 'ALL'
        OR transfer_row.pay_channel = v_scope
        OR (v_scope = 'LOANS' AND v_batch_kind_fixed = 'LOANS' AND transfer_row.pay_channel = 'PAYE')
      )
      AND UPPER(COALESCE(transfer_row.status, '')) <> 'BLOCKED'
    ORDER BY transfer_row.id;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_positive_bank_payment_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row;

  -- Ensure required snapshot fields exist for all exportable rows, but only for
  -- fields selected by configuration. Transfer/request identifiers are allowed
  -- to be blank for the direct pre-execution projection because they do not yet
  -- exist and must never be fabricated.
  SELECT COUNT(*)::integer
  INTO v_missing_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row
  WHERE
       (array_position(v_cols, 'payment_reference') IS NOT NULL AND export_row.payment_reference IS NULL)
    OR (array_position(v_cols, 'payee_name') IS NOT NULL AND export_row.payee_name IS NULL)
    OR (array_position(v_cols, 'sort_code') IS NOT NULL AND export_row.sort_code IS NULL)
    OR (array_position(v_cols, 'account_number') IS NOT NULL AND export_row.account_number IS NULL)
    OR (array_position(v_cols, 'amount') IS NOT NULL AND export_row.amount IS NULL)
    OR (array_position(v_cols, 'currency') IS NOT NULL AND export_row.currency IS NULL)
    OR (array_position(v_cols, 'pay_channel') IS NOT NULL AND export_row.pay_channel IS NULL)
    OR (array_position(v_cols, 'rail_provider') IS NOT NULL AND export_row.rail_provider IS NULL)
    OR (array_position(v_cols, 'rail_env') IS NOT NULL AND export_row.rail_env IS NULL)
    OR (
      v_pre_execution_export IS NOT TRUE
      AND array_position(v_cols, 'request_id') IS NOT NULL
      AND export_row.request_id IS NULL
    )
    OR (array_position(v_cols, 'transfer_group_key') IS NOT NULL AND export_row.transfer_group_key IS NULL)
    OR (array_position(v_cols, 'grouping_mode_used') IS NOT NULL AND export_row.grouping_mode_used IS NULL)
    OR (array_position(v_cols, 'week_ending_bucket') IS NOT NULL AND export_row.week_ending_bucket IS NULL)
    OR (array_position(v_cols, 'candidate_id') IS NOT NULL AND export_row.candidate_id IS NULL)
    OR (array_position(v_cols, 'umbrella_id') IS NOT NULL AND export_row.umbrella_id IS NULL)
    OR (array_position(v_cols, 'payee_entity_kind') IS NOT NULL AND export_row.payee_entity_kind IS NULL)
    OR (array_position(v_cols, 'payee_entity_id') IS NOT NULL AND export_row.payee_entity_id IS NULL)
    OR (array_position(v_cols, 'bank_details_hash_snapshot') IS NOT NULL AND export_row.bank_details_hash_snapshot IS NULL);

  IF v_missing_count > 0 THEN
    RAISE EXCEPTION 'pay_export_bank_csv: % exportable payment row(s) are missing one or more required fields for the configured export.', v_missing_count;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_row_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row;

  IF v_row_count = 0
     AND NOT (
       v_pre_execution_export
       AND v_missing_paye_net_count = 0
       AND v_explicit_zero_count > 0
       AND v_positive_bank_payment_count = 0
       AND v_invalid_payment_row_count = 0
     ) THEN
    RAISE EXCEPTION 'pay_export_bank_csv: no exportable transfers found for batch % (scope=%).', p_pay_batch_id, v_scope;
  END IF;

  -- Build header from configured columns and optional user overrides.
  v_header := '';
  if v_include_header = true then
    foreach v_col in array v_cols loop
      v_hdr_part := case v_col
        when 'transfer_id' then 'Transfer id'
        when 'payment_reference' then 'Payment reference'
        when 'payee_name' then 'Payee name'
        when 'sort_code' then 'Sort code'
        when 'account_number' then 'Bank account number'
        when 'account_type' then 'Bank account type'
        when 'amount' then 'Amount'
        when 'currency' then 'Currency'
        when 'pay_channel' then 'Channel'
        when 'rail_provider' then 'Rail provider'
        when 'rail_env' then 'Rail env'
        when 'request_id' then 'Request id'
        when 'transfer_group_key' then 'Transfer group key'
        when 'grouping_mode_used' then 'Grouping mode'
        when 'week_ending_bucket' then 'Week ending'
        when 'candidate_id' then 'Candidate id'
        when 'umbrella_id' then 'Umbrella id'
        when 'payee_entity_kind' then 'Payee entity kind'
        when 'payee_entity_id' then 'Payee entity id'
        when 'bank_details_hash_snapshot' then 'Bank details hash'
        else initcap(replace(v_col, '_', ' '))
      end;

      v_hdr_override := nullif(btrim(coalesce(v_headers_json->>v_col, '')), '');
      if v_hdr_override is not null then
        v_hdr_part := v_hdr_override;
      end if;

      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_hdr_part) > 0
        or position('"' in v_hdr_part) > 0
        or position(E'\r' in v_hdr_part) > 0
        or position(E'\n' in v_hdr_part) > 0
      then
        v_hdr_part := '"' || replace(v_hdr_part, '"', '""') || '"';
      end if;

      if v_header = '' then
        v_header := v_hdr_part;
      else
        v_header := v_header || v_delimiter || v_hdr_part;
      end if;
    end loop;
  end if;

  -- Build rows.
  v_body := '';
  for r in
    SELECT
      export_row.transfer_id,
      export_row.payment_reference,
      export_row.payee_name,
      export_row.sort_code,
      export_row.account_number,
      export_row.account_type,
      export_row.amount,
      export_row.currency,
      export_row.pay_channel,
      export_row.rail_provider,
      export_row.rail_env,
      export_row.request_id,
      export_row.transfer_group_key,
      export_row.grouping_mode_used,
      export_row.week_ending_bucket,
      export_row.candidate_id,
      export_row.umbrella_id,
      export_row.payee_entity_kind,
      export_row.payee_entity_id,
      export_row.bank_details_hash_snapshot
    FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row
    ORDER BY export_row.row_ordinal
  loop
    v_line := '';

    foreach v_col in array v_cols loop
      v_val := null;

      if v_col = 'transfer_id' then
        v_val := r.transfer_id::text;
      elsif v_col = 'payment_reference' then
        v_val := r.payment_reference;
      elsif v_col = 'payee_name' then
        v_val := r.payee_name;
      elsif v_col = 'sort_code' then
        if v_sort_code_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
        elsif v_sort_code_format = 'HYPHENATED' then
          v_digits := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
          if length(v_digits) = 6 then
            v_val := substr(v_digits, 1, 2) || '-' || substr(v_digits, 3, 2) || '-' || substr(v_digits, 5, 2);
          else
            v_val := v_digits;
          end if;
        else
          v_val := r.sort_code;
        end if;
      elsif v_col = 'account_number' then
        if v_account_number_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.account_number, ''), '[^0-9]', '', 'g');
        else
          v_val := r.account_number;
        end if;
      elsif v_col = 'account_type' then
        v_val := r.account_type;
      elsif v_col = 'amount' then
        v_val := case v_amount_decimals
          when 0 then to_char(round(r.amount, 0), 'FM9999999990')
          when 1 then to_char(round(r.amount, 1), 'FM9999999990.0')
          when 2 then to_char(round(r.amount, 2), 'FM9999999990.00')
          when 3 then to_char(round(r.amount, 3), 'FM9999999990.000')
          when 4 then to_char(round(r.amount, 4), 'FM9999999990.0000')
          else to_char(round(r.amount, 2), 'FM9999999990.00')
        end;
      elsif v_col = 'currency' then
        v_val := r.currency;
      elsif v_col = 'pay_channel' then
        v_val := r.pay_channel;
      elsif v_col = 'rail_provider' then
        v_val := r.rail_provider;
      elsif v_col = 'rail_env' then
        v_val := r.rail_env;
      elsif v_col = 'request_id' then
        v_val := r.request_id;
      elsif v_col = 'transfer_group_key' then
        v_val := r.transfer_group_key;
      elsif v_col = 'grouping_mode_used' then
        v_val := r.grouping_mode_used;
      elsif v_col = 'week_ending_bucket' then
        v_val := case when r.week_ending_bucket is null then null else r.week_ending_bucket::text end;
      elsif v_col = 'candidate_id' then
        v_val := case when r.candidate_id is null then null else r.candidate_id::text end;
      elsif v_col = 'umbrella_id' then
        v_val := case when r.umbrella_id is null then null else r.umbrella_id::text end;
      elsif v_col = 'payee_entity_kind' then
        v_val := r.payee_entity_kind;
      elsif v_col = 'payee_entity_id' then
        v_val := case when r.payee_entity_id is null then null else r.payee_entity_id::text end;
      elsif v_col = 'bank_details_hash_snapshot' then
        v_val := r.bank_details_hash_snapshot;
      else
        v_val := null;
      end if;

      v_val := coalesce(v_val, v_empty_value);

      -- CSV escaping: quote according to configured quote mode or when field contains delimiter/quote/newline.
      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_val) > 0
        or position('"' in v_val) > 0
        or position(E'\r' in v_val) > 0
        or position(E'\n' in v_val) > 0
      then
        v_val := '"' || replace(v_val, '"', '""') || '"';
      end if;

      if v_line = '' then
        v_line := v_val;
      else
        v_line := v_line || v_delimiter || v_val;
      end if;
    end loop;

    if v_body = '' then
      v_body := v_line;
    else
      v_body := v_body || v_line_ending || v_line;
    end if;
  end loop;

  if v_include_header = true then
    v_csv := v_header || v_line_ending || coalesce(v_body, '');
  else
    v_csv := coalesce(v_body, '');
  end if;

  if v_bom = true then
    v_csv := chr(65279) || v_csv;
  end if;

  return v_csv;
end;
$function$;

-- pay_finance_case_apply_taxable_channel_restructure(uuid,uuid,text,text,integer,numeric,numeric,date,text)
CREATE OR REPLACE FUNCTION public.pay_finance_case_apply_taxable_channel_restructure(p_finance_case_id uuid, p_actor_user_id uuid, p_resolution_path text DEFAULT 'SUGGESTED'::text, p_schedule_input_mode text DEFAULT NULL::text, p_weeks_total integer DEFAULT NULL::integer, p_weekly_due numeric DEFAULT NULL::numeric, p_manual_total_remaining numeric DEFAULT NULL::numeric, p_effective_pay_date date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_updated_case public.pay_advances%rowtype;
  v_candidate record;

  v_suggestion jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_component_before_json jsonb := '[]'::jsonb;
  v_component_after_json jsonb := '[]'::jsonb;
  v_schedule_json jsonb := '[]'::jsonb;

  v_candidate_pay_method text := null;
  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));

  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_source_total_ex numeric(12,2) := 0;
  v_source_target_ratio numeric := 1;
  v_source_weekly_due numeric(12,2) := 0;
  v_source_final_week_amount numeric(12,2) := 0;
  v_source_schedule_json jsonb := '[]'::jsonb;
  v_weekly_due numeric(12,2) := 0;
  v_weeks_total integer := 0;
  v_final_week_amount numeric(12,2) := 0;
  v_schedule_sign integer := -1;
  v_start_week_start date := null;
  v_next_due_week_start date := null;
  v_recovered_or_paid_so_far_ex numeric(12,2) := 0;
  v_rebased_original_amount numeric(12,2) := 0;

  v_open_component_count integer := 0;
  v_new_component_remaining_total numeric(12,2) := 0;
  v_has_open_batch_item boolean := false;
  v_resolution_mode public.pay_finance_component_resolution_mode_enum := 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum;
  v_event_note text := null;
  v_case_taxability public.pay_finance_taxability_enum := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  perform pg_advisory_xact_lock(94201, 1);

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_TYPE_NOT_SUPPORTED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case type is not supported for taxable channel restructure',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_NOT_ACTIVE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case must be ACTIVE',
      'finance_case_id', p_finance_case_id::text,
      'status', v_case.status::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount, 0), 2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'NO_OUTSTANDING_BALANCE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text,
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2)
    )::text;
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method
  into v_candidate
  from public.candidates as c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  perform 1
  from public.pay_finance_case_components as pfc_lock
  where pfc_lock.finance_case_id = p_finance_case_id
    and pfc_lock.closed_at_utc is null
  for update;

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_ALREADY_IN_OPEN_BATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: cannot restructure while the case is already included in an open pay batch',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_suggestion := public.pay_finance_case_taxable_channel_restructure_suggestion(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_effective_pay_date => v_effective_pay_date,
    p_resolution_path => v_resolution_path_norm,
    p_schedule_input_mode => v_schedule_input_mode_norm,
    p_weeks_total => p_weeks_total,
    p_weekly_due => p_weekly_due,
    p_manual_total_remaining => p_manual_total_remaining,
    p_note => p_note
  );

  if coalesce((v_suggestion->>'requires_restructure')::boolean, false) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESTRUCTURE_NOT_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: taxable channel restructure is not required',
      'finance_case_id', p_finance_case_id::text,
      'suggestion', v_suggestion
    )::text;
  end if;

  if coalesce((v_suggestion->>'can_apply')::boolean, true) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', coalesce(nullif(v_suggestion->>'blocked_reason', ''), 'RESTRUCTURE_BLOCKED'),
      'message', 'pay_finance_case_apply_taxable_channel_restructure: restructure is currently blocked',
      'finance_case_id', p_finance_case_id::text,
      'blocked_reason', v_suggestion->>'blocked_reason'
    )::text;
  end if;

  if to_regclass('pg_temp._tmp_taxable_channel_restructure_components') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SUGGESTION_COMPONENT_TABLE_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: suggestion component table was not available'
    )::text;
  end if;

  select
    count(*)::integer,
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2)
  into
    v_open_component_count,
    v_source_total_ex,
    v_new_component_remaining_total
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 or v_source_total_ex <= 0 or v_new_component_remaining_total <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'COMPONENT_TARGET_TOTAL_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: target component total must be > 0',
      'open_component_count', v_open_component_count,
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_new_component_remaining_total
    )::text;
  end if;

  v_target_total_ex := round(coalesce((v_suggestion->'selected'->>'target_remaining_balance_ex_vat')::numeric, v_new_component_remaining_total), 2);
  v_weekly_due := round(coalesce((v_suggestion->'selected'->>'weekly_due')::numeric, 0), 2);
  v_weeks_total := coalesce((v_suggestion->'selected'->>'weeks_total')::integer, 0);
  v_final_week_amount := round(coalesce((v_suggestion->'selected'->>'final_week_amount')::numeric, 0), 2);
  v_schedule_sign := coalesce(
    (v_suggestion->'selected'->>'schedule_sign')::integer,
    case
      when v_case.case_type IN (
        'UNDERPAYMENT'::public.pay_finance_case_type_enum,
        'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      ) then 1
      else -1
    end
  );
  v_start_week_start := coalesce((v_suggestion->'selected'->>'start_week_start')::date, v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));

  v_source_total_ex := round(coalesce((v_suggestion->'existing'->>'source_remaining_balance_ex_vat')::numeric, v_source_total_ex), 2);
  v_source_target_ratio := case
    when round(abs(coalesce(v_source_total_ex, 0)), 2) = 0 then 1
    else coalesce(v_target_total_ex, 0) / nullif(v_source_total_ex, 0)
  end;
  v_source_weekly_due := round(
    case
      when round(abs(coalesce(v_source_target_ratio, 0)), 8) = 0 then coalesce(v_weekly_due, 0)
      else coalesce(v_weekly_due, 0) / v_source_target_ratio
    end,
    2
  );
  v_source_weekly_due := greatest(coalesce(v_source_weekly_due, 0), 0.01)::numeric(12,2);
  v_source_final_week_amount := round(
    least(
      v_source_weekly_due,
      greatest(coalesce(v_source_total_ex, 0) - (v_source_weekly_due * greatest(coalesce(v_weeks_total, 1) - 1, 0)), 0)
    ),
    2
  )::numeric(12,2);

  if v_target_total_ex <= 0 or v_source_total_ex <= 0 or v_weekly_due <= 0 or v_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SELECTED_SCHEDULE_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: selected source/target totals, weekly_due and weeks_total must be valid',
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex,
      'weekly_due', v_weekly_due,
      'weeks_total', v_weeks_total
    )::text;
  end if;

  if public._pay_week_start_monday(v_start_week_start) <> v_start_week_start then
    v_start_week_start := public._pay_week_start_monday(v_start_week_start);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_start_week_start + (gs.i * 7))::date,
        'amount', round(
          v_schedule_sign * least(
            v_weekly_due,
            greatest(v_target_total_ex - (v_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs(i);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_start_week_start + (gs.i * 7))::date,
        'amount', round(
          v_schedule_sign * least(
            v_source_weekly_due,
            greatest(v_source_total_ex - (v_source_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_source_schedule_json
  from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due_week_start
  from (
    select
      (v_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        v_schedule_sign * least(
          v_weekly_due,
          greatest(v_target_total_ex - (v_weekly_due * gs2.i), 0)
        ),
        2
      ) as amount
    from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs2(i)
  ) as x
  where abs(coalesce(x.amount, 0)) > 0;

  v_recovered_or_paid_so_far_ex := round(greatest(coalesce(v_case.original_amount, 0) - coalesce(v_case.outstanding_amount, 0), 0), 2);
  v_rebased_original_amount := round(v_recovered_or_paid_so_far_ex + v_source_total_ex, 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_before_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_before_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
      'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
      'original_amount', round(coalesce(v_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_case.weekly_due, 0), 2),
      'weeks_total', v_case.weeks_total,
      'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb),
      'components', v_component_before_json
    )
  );

  v_resolution_mode := case
    when v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
    else 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
  end;

  update public.pay_finance_case_components as pfc
  set
    saved_target_pay_method = v_candidate_pay_method,
    saved_resolution_mode = v_resolution_mode,
    saved_resolution_payload_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_path', v_resolution_path_norm,
        'schedule_input_mode', coalesce(v_schedule_input_mode_norm, 'BY_WEEKS'),
        'effective_pay_date', v_effective_pay_date::text,
        'source_pay_method', trc.source_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'target_source_ratio', case when round(coalesce(trc.remaining_source_amount, 0), 2) <> 0 then round(coalesce(trc.target_remaining_ex, 0) / trc.remaining_source_amount, 12) else null end,
        'relevant_erni_pct', v_suggestion->'suggested'->'erni_rate_pct',
        'vat_rate_pct', v_suggestion->'suggested'->'vat_rate_pct',
        'umbrella_vat_chargeable', v_suggestion->'suggested'->'umbrella_vat_chargeable',
        'weekly_due', v_weekly_due,
        'weeks_total', v_weeks_total,
        'final_week_amount', v_final_week_amount,
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    saved_resolution_result_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_mode', v_resolution_mode::text,
        'applied_at_utc', v_now_utc::text,
        'actor_user_id', p_actor_user_id::text,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'source_pay_method_before', trc.source_pay_method,
        'source_pay_method_after', v_candidate_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'case_source_remaining_amount_ex_vat', v_source_total_ex,
        'case_target_remaining_amount_ex_vat', v_target_total_ex,
        'case_source_weekly_due', v_source_weekly_due,
        'case_weekly_due', v_weekly_due,
        'case_weeks_total', v_weeks_total,
        'target_source_ratio', case when round(coalesce(trc.remaining_source_amount, 0), 2) <> 0 then round(coalesce(trc.target_remaining_ex, 0) / trc.remaining_source_amount, 12) else null end
      )
    ),
    resolution_fingerprint = public.pay_finance_component_fingerprint(
      pfc.source_family_key,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      pfc.source_pay_method,
      v_candidate_pay_method,
      coalesce(pfc.source_basis_json, '{}'::jsonb),
      round(coalesce(pfc.source_amount, 0), 2),
      nullif(v_suggestion->'suggested'->>'erni_rate_pct', '')::numeric,
      jsonb_strip_nulls(
        jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_path', v_resolution_path_norm,
        'schedule_input_mode', coalesce(v_schedule_input_mode_norm, 'BY_WEEKS'),
        'effective_pay_date', v_effective_pay_date::text,
        'source_pay_method', trc.source_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'target_source_ratio', case when round(coalesce(trc.remaining_source_amount, 0), 2) <> 0 then round(coalesce(trc.target_remaining_ex, 0) / trc.remaining_source_amount, 12) else null end,
        'relevant_erni_pct', v_suggestion->'suggested'->'erni_rate_pct',
        'vat_rate_pct', v_suggestion->'suggested'->'vat_rate_pct',
        'umbrella_vat_chargeable', v_suggestion->'suggested'->'umbrella_vat_chargeable',
        'weekly_due', v_weekly_due,
        'weeks_total', v_weeks_total,
        'final_week_amount', v_final_week_amount,
        'note', nullif(btrim(coalesce(p_note, '')), '')
        )
      )
    ),
    is_resolution_stale = false,
    stale_reason = null,
    resolved_at_utc = v_now_utc,
    updated_at_utc = v_now_utc
  from pg_temp._tmp_taxable_channel_restructure_components as trc
  where pfc.id = trc.finance_component_id
    and pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and trc.requires_component_conversion;

  select
    case
      when count(*) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) = count(*)
        then 'TAXABLE'::public.pay_finance_taxability_enum
      when count(*) filter (where trc.classification in (
        'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
        'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
      )) = count(*)
        then 'NON_TAXABLE'::public.pay_finance_taxability_enum
      else null::public.pay_finance_taxability_enum
    end
  into v_case_taxability
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  update public.pay_advances as pa
  set
    original_amount = v_rebased_original_amount,
    outstanding_amount = v_source_total_ex,
    schedule_json = coalesce(v_source_schedule_json, '[]'::jsonb),
    weekly_due = v_source_weekly_due,
    weeks_total = v_weeks_total,
    start_week_start = v_start_week_start,
    next_due_week_start = v_next_due_week_start,
    taxability = v_case_taxability,
    routing_kind = case
      when v_candidate_pay_method = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
      else 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
    end,
    notes = coalesce(nullif(btrim(coalesce(p_note, '')), ''), pa.notes),
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    count(*)::integer
  into
    v_new_component_remaining_total,
    v_open_component_count
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENTS_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: no open components remained after update',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_new_component_remaining_total <> v_source_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENT_TOTAL_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated component remaining total must match selected source total',
      'finance_case_id', p_finance_case_id::text,
      'component_remaining_total', v_new_component_remaining_total,
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select pa.*
  into v_updated_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id;

  if v_updated_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case could not be reloaded',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if round(coalesce(v_updated_case.outstanding_amount, 0), 2) <> v_source_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_OUTSTANDING_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case outstanding_amount must match selected source total',
      'finance_case_id', p_finance_case_id::text,
      'updated_outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
          'saved_resolution_result_json', pfc.saved_resolution_result_json,
          'resolution_fingerprint', pfc.resolution_fingerprint,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_after_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_after_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_updated_case.candidate_id::text,
      'client_id', case when v_updated_case.client_id is null then null else v_updated_case.client_id::text end,
      'case_type', v_updated_case.case_type::text,
      'status', v_updated_case.status::text,
      'taxability', case when v_updated_case.taxability is null then null else v_updated_case.taxability::text end,
      'routing_kind', case when v_updated_case.routing_kind is null then null else v_updated_case.routing_kind::text end,
      'original_amount', round(coalesce(v_updated_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_updated_case.weekly_due, 0), 2),
      'weeks_total', v_updated_case.weeks_total,
      'start_week_start', case when v_updated_case.start_week_start is null then null else v_updated_case.start_week_start::text end,
      'next_due_week_start', case when v_updated_case.next_due_week_start is null then null else v_updated_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_updated_case.schedule_json, '[]'::jsonb),
      'components', v_component_after_json
    )
  );

  v_event_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Taxable finance channel restructure applied'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::uuid,
    v_before_json,
    v_after_json,
    'TAXABLE_CHANNEL_RESTRUCTURE',
    v_event_note
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_updated_case.candidate_id::text,
    'case_type', v_updated_case.case_type::text,
    'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
    'resolution_path', v_resolution_path_norm,
    'resolution_mode', v_resolution_mode::text,
    'effective_pay_date', v_effective_pay_date::text,
    'target_pay_method', v_candidate_pay_method,
    'source_remaining_balance_ex_vat', v_source_total_ex,
    'target_remaining_balance_ex_vat', v_target_total_ex,
    'before', v_before_json,
    'after', v_after_json,
    'suggestion', v_suggestion
  );
end;
$function$;

-- pay_finance_case_audit_actor_index(uuid)
CREATE OR REPLACE FUNCTION public.pay_finance_case_audit_actor_index(p_finance_case_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
WITH case_ref AS (
  SELECT advance_row.linked_timesheet_id
  FROM public.pay_advances AS advance_row
  WHERE advance_row.id = p_finance_case_id
),
actor_events AS (
  SELECT
    finance_event.id,
    'FINANCE_CASE_EVENT'::text AS source,
    finance_event.event_type,
    finance_event.event_at_utc AS at_utc,
    finance_event.actor_user_id,
    COALESCE(
      NULLIF(BTRIM(COALESCE(actor_user.display_name, '')), ''),
      NULLIF(BTRIM(COALESCE(actor_user.email, '')), ''),
      CASE WHEN finance_event.actor_user_id IS NULL THEN 'System' ELSE 'Former user' END
    ) AS actor_display_name
  FROM public.pay_finance_case_events AS finance_event
  LEFT JOIN public.tms_users AS actor_user
    ON actor_user.id = finance_event.actor_user_id
  WHERE finance_event.finance_case_id = p_finance_case_id

  UNION ALL

  SELECT
    audit_event.id,
    'AUDIT'::text AS source,
    audit_event.action AS event_type,
    audit_event.ts_utc AS at_utc,
    audit_event.actor_user_id,
    COALESCE(
      NULLIF(BTRIM(COALESCE(audit_event.actor_display, '')), ''),
      NULLIF(BTRIM(COALESCE(actor_user.display_name, '')), ''),
      NULLIF(BTRIM(COALESCE(actor_user.email, '')), ''),
      CASE WHEN audit_event.actor_user_id IS NULL THEN 'System' ELSE 'Former user' END
    ) AS actor_display_name
  FROM public.audit_events AS audit_event
  LEFT JOIN public.tms_users AS actor_user
    ON actor_user.id = audit_event.actor_user_id
  CROSS JOIN case_ref
  WHERE (
    audit_event.object_type IN ('pay_advances', 'finance_cases')
    AND audit_event.object_id_text = p_finance_case_id::text
  )
  OR (
    case_ref.linked_timesheet_id IS NOT NULL
    AND audit_event.object_type = 'timesheets'
    AND audit_event.object_id_text = case_ref.linked_timesheet_id::text
  )

  UNION ALL

  SELECT
    snooze_row.id,
    'SNOOZE'::text AS source,
    'SNOOZE_APPLIED'::text AS event_type,
    snooze_row.created_at_utc AS at_utc,
    snooze_row.created_by_user_id AS actor_user_id,
    COALESCE(
      NULLIF(BTRIM(COALESCE(actor_user.display_name, '')), ''),
      NULLIF(BTRIM(COALESCE(actor_user.email, '')), ''),
      CASE WHEN snooze_row.created_by_user_id IS NULL THEN 'System' ELSE 'Former user' END
    ) AS actor_display_name
  FROM public.pay_item_snoozes AS snooze_row
  LEFT JOIN public.tms_users AS actor_user
    ON actor_user.id = snooze_row.created_by_user_id
  WHERE snooze_row.source_ref = ('advance:' || p_finance_case_id::text)
    AND snooze_row.created_at_utc IS NOT NULL

  UNION ALL

  SELECT
    snooze_row.id,
    'SNOOZE'::text AS source,
    'SNOOZE_CLEARED'::text AS event_type,
    snooze_row.cleared_at_utc AS at_utc,
    snooze_row.cleared_by_user_id AS actor_user_id,
    COALESCE(
      NULLIF(BTRIM(COALESCE(actor_user.display_name, '')), ''),
      NULLIF(BTRIM(COALESCE(actor_user.email, '')), ''),
      CASE WHEN snooze_row.cleared_by_user_id IS NULL THEN 'System' ELSE 'Former user' END
    ) AS actor_display_name
  FROM public.pay_item_snoozes AS snooze_row
  LEFT JOIN public.tms_users AS actor_user
    ON actor_user.id = snooze_row.cleared_by_user_id
  WHERE snooze_row.source_ref = ('advance:' || p_finance_case_id::text)
    AND snooze_row.cleared_at_utc IS NOT NULL
)
SELECT jsonb_build_object(
  'events',
  COALESCE(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'event_id', actor_event.id::text,
          'source', actor_event.source,
          'event_type', actor_event.event_type,
          'at_utc', actor_event.at_utc,
          'actor_user_id', CASE
            WHEN actor_event.actor_user_id IS NULL THEN NULL
            ELSE actor_event.actor_user_id::text
          END,
          'actor_display_name', actor_event.actor_display_name
        )
      )
      ORDER BY actor_event.at_utc, actor_event.source, actor_event.event_type, actor_event.id
    ),
    '[]'::jsonb
  )
)
FROM actor_events AS actor_event;
$function$;

-- pay_finance_case_audit_feed(uuid)
CREATE OR REPLACE FUNCTION public.pay_finance_case_audit_feed(p_finance_case_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_finance_case_id uuid := p_finance_case_id;
  v_case record;
  v_timeline jsonb := '[]'::jsonb;
  v_current_component_state jsonb := '[]'::jsonb;
begin
  if v_finance_case_id is null then
    raise exception 'pay_finance_case_audit_feed: finance_case_id is required';
  end if;

  select
    vfcr.finance_case_id,
    vfcr.case_type,
    vfcr.candidate_id,
    vfcr.candidate_tms_ref,
    vfcr.candidate_display_name,
    vfcr.client_id,
    vfcr.client_name,
    vfcr.linked_timesheet_id,
    vfcr.linked_shift_date,
    vfcr.status,
    vfcr.payout_status,
    vfcr.original_amount,
    vfcr.outstanding_amount,
    vfcr.weekly_due,
    vfcr.weeks_total,
    vfcr.start_week_start,
    vfcr.next_due_week_start,
    vfcr.adjustment_comment,
    vfcr.source_original_paid_amount,
    vfcr.source_corrected_paid_amount,
    vfcr.minimum_earnings_threshold,
    vfcr.take_home_floor_override,
    vfcr.active_snooze_id,
    vfcr.active_snooze_kind,
    vfcr.active_snooze_until_date,
    vfcr.active_snooze_note,
    vfcr.latest_remittance_sent_at_utc,
    vfcr.latest_remittance_trigger_status,
    vfcr.last_remittance_error,
    vfcr.latest_recovery_pay_batch_id,
    vfcr.latest_recovery_pay_date,
    vfcr.payout_pay_batch_id,
    vfcr.payout_transfer_id,
    vfcr.written_off_at_utc,
    vfcr.write_off_reason,
    vfcr.cleared_at_utc,
    vfcr.baseline_signature,
    vfcr.schedule_json,
    vfcr.notes,
    vfcr.created_at,
    vfcr.updated_at,
    vfcr.is_mixed_case,
    vfcr.open_taxable_count,
    vfcr.open_reimbursement_count,
    vfcr.unresolved_taxable_count,
    vfcr.stale_count,
    vfcr.component_resolution_summary_json
  into v_case
  from public.v_finance_cases_register vfcr
  where vfcr.finance_case_id = v_finance_case_id;

  if v_case.finance_case_id is null then
    raise exception 'pay_finance_case_audit_feed: finance case % not found.', v_finance_case_id;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'candidate_id', pfc.candidate_id::text,
          'client_id', case when pfc.client_id is null then null else pfc.client_id::text end,
          'linked_timesheet_id', case when pfc.linked_timesheet_id is null then null else pfc.linked_timesheet_id::text end,
          'source_family_key', pfc.source_family_key,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_basis_json', pfc.source_basis_json,
          'source_amount', pfc.source_amount,
          'remaining_source_amount', pfc.remaining_source_amount,
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
          'saved_resolution_result_json', pfc.saved_resolution_result_json,
          'resolution_fingerprint', pfc.resolution_fingerprint,
          'is_resolution_stale', pfc.is_resolution_stale,
          'stale_reason', pfc.stale_reason,
          'allocation_priority_group', pfc.allocation_priority_group,
          'allocation_priority_order', pfc.allocation_priority_order,
          'created_at_utc', pfc.created_at_utc,
          'updated_at_utc', pfc.updated_at_utc,
          'resolved_at_utc', pfc.resolved_at_utc,
          'closed_at_utc', pfc.closed_at_utc
        )
        order by
          pfc.source_family_key,
          pfc.allocation_priority_group,
          pfc.allocation_priority_order,
          pfc.component_key_type,
          pfc.component_key_value
      ),
      '[]'::jsonb
    )
  into v_current_component_state
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = v_finance_case_id
    and pfc.closed_at_utc is null;

  with booking_ctx as (
    select ts.booking_id
    from public.timesheets ts
    where ts.timesheet_id = v_case.linked_timesheet_id
    limit 1
  ),
  finance_events as (
    select
      pfce.event_at_utc as at_utc,
      'FINANCE_CASE_EVENT'::text as source,
      pfce.event_type as event_type,
      initcap(replace(lower(coalesce(pfce.event_type, 'EVENT')), '_', ' ')) as title,
      pfce.before_json,
      pfce.after_json,
      pfce.reason,
      pfce.note,
      case when pfce.pay_batch_id is null then null else pfce.pay_batch_id::text end as pay_batch_id_text,
      case when pfce.reservation_id is null then null else pfce.reservation_id::text end as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', case when pfce.finance_component_id is null then null else pfce.finance_component_id::text end,
          'classification', case when pfc.classification is null then null else pfc.classification::text end,
          'source_pay_method', pfc.source_pay_method,
          'target_pay_method', pfc.saved_target_pay_method,
          'resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'resolution_payload_json', pfc.saved_resolution_payload_json,
          'resolution_result_json', pfc.saved_resolution_result_json,
          'stale_reason', pfc.stale_reason,
          'remaining_source_amount', pfc.remaining_source_amount,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'frozen_source_basis_json', par.frozen_source_basis_json,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'frozen_resolution_payload_json', par.frozen_resolution_payload_json,
          'frozen_resolution_result_json', par.frozen_resolution_result_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        )
      ) as meta_json
    from public.pay_finance_case_events pfce
    left join public.pay_finance_case_components pfc
      on pfc.id = pfce.finance_component_id
    left join public.pay_advance_reservations par
      on par.id = pfce.reservation_id
    where pfce.finance_case_id = v_finance_case_id
  ),
  reservation_events as (
    select
      x.at_utc,
      'RESERVATION'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      x.pay_batch_id_text,
      x.reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        par.created_at_utc as at_utc,
        'RESERVED'::text as event_type,
        'Finance reservation created'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'repayment_week_start', case when par.repayment_week_start is null then null else par.repayment_week_start::text end,
          'status', par.status,
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_classification', case when par.frozen_component_classification is null then null else par.frozen_component_classification::text end,
          'frozen_source_basis_json', par.frozen_source_basis_json,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'frozen_resolution_payload_json', par.frozen_resolution_payload_json,
          'frozen_resolution_result_json', par.frozen_resolution_result_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', par.status,
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_classification', case when par.frozen_component_classification is null then null else par.frozen_component_classification::text end,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'reserved_source_amount', par.reserved_source_amount
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.created_at_utc is not null

      union all

      select
        par.committed_at_utc as at_utc,
        'COMMITTED'::text as event_type,
        'Finance reservation committed'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'COMMITTED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'COMMITTED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.committed_at_utc is not null

      union all

      select
        par.settled_at_utc as at_utc,
        'SETTLED'::text as event_type,
        'Finance reservation settled'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'SETTLED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'SETTLED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.settled_at_utc is not null

      union all

      select
        par.released_at_utc as at_utc,
        'RELEASED'::text as event_type,
        'Finance reservation released'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'RELEASED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'released_reason', par.released_reason,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        par.released_reason as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'RELEASED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.released_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  batch_item_events as (
    select
      pbi.created_at as at_utc,
      'BATCH_ITEM'::text as source,
      coalesce(pbi.item_type, 'BATCH_ITEM_CREATED')::text as event_type,
      'Finance batch item created'::text as title,
      null::jsonb as before_json,
      jsonb_build_object(
        'item_type', pbi.item_type,
        'finance_case_id', case when pbi.finance_case_id is null then null else pbi.finance_case_id::text end,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'frozen_component_classification', case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end,
        'frozen_source_basis_json', pbi.frozen_source_basis_json,
        'frozen_source_pay_method', pbi.frozen_source_pay_method,
        'frozen_target_pay_method', pbi.frozen_target_pay_method,
        'frozen_resolution_mode', case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end,
        'frozen_resolution_payload_json', pbi.frozen_resolution_payload_json,
        'frozen_resolution_result_json', pbi.frozen_resolution_result_json,
        'frozen_source_amount', pbi.frozen_source_amount,
        'frozen_target_amount_ex_vat', pbi.frozen_target_amount_ex_vat,
        'frozen_target_amount_vat', pbi.frozen_target_amount_vat,
        'frozen_target_amount_inc_vat', pbi.frozen_target_amount_inc_vat,
        'frozen_component_snapshot_json', pbi.frozen_component_snapshot_json,
        'is_voided', pbi.is_voided
      ) as after_json,
      null::text as reason,
      null::text as note,
      pbc.pay_batch_id::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'pay_batch_candidate_id', pbi.pay_batch_candidate_id::text,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'is_voided', pbi.is_voided
      ) as meta_json
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbi.created_at is not null
      and (
        pbi.finance_case_id = v_finance_case_id
        or (
          pbi.source_ref is not null
          and pbi.source_ref = ('advance:' || v_finance_case_id::text)
        )
      )
  ),
  patch_events as (
    select
      pap.patched_at_utc as at_utc,
      'PATCH'::text as source,
      'PATCHED'::text as event_type,
      'Finance case patched'::text as title,
      jsonb_build_object(
        'outstanding_amount', pap.old_outstanding_amount,
        'schedule_json', pap.old_schedule_json,
        'next_due_week_start', case when pap.old_next_due_week_start is null then null else pap.old_next_due_week_start::text end
      ) as before_json,
      jsonb_build_object(
        'outstanding_amount', pap.new_outstanding_amount,
        'schedule_json', pap.new_schedule_json,
        'next_due_week_start', case when pap.new_next_due_week_start is null then null else pap.new_next_due_week_start::text end
      ) as after_json,
      null::text as reason,
      null::text as note,
      case when pap.pay_batch_id is null then null else pap.pay_batch_id::text end as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      null::jsonb as meta_json
    from public.pay_advance_patches pap
    where pap.advance_id = v_finance_case_id
  ),
  snooze_events as (
    select
      x.at_utc,
      'SNOOZE'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      case when x.timesheet_id is null then null else x.timesheet_id::text end as timesheet_id_text,
      x.meta_json
    from (
      select
        pis.created_at_utc as at_utc,
        'SNOOZE_APPLIED'::text as event_type,
        'Snooze applied'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'snooze_kind', pis.snooze_kind,
          'snooze_until_date', case when pis.snooze_until_date is null then null else pis.snooze_until_date::text end,
          'note', pis.note,
          'source_ref', pis.source_ref
        ) as after_json,
        null::text as reason,
        pis.note as note,
        pis.timesheet_id,
        jsonb_build_object('snooze_id', pis.id::text) as meta_json
      from public.pay_item_snoozes pis
      where pis.source_ref = ('advance:' || v_finance_case_id::text)
        and pis.created_at_utc is not null

      union all

      select
        pis.cleared_at_utc as at_utc,
        'SNOOZE_CLEARED'::text as event_type,
        'Snooze cleared'::text as title,
        jsonb_build_object(
          'snooze_kind', pis.snooze_kind,
          'snooze_until_date', case when pis.snooze_until_date is null then null else pis.snooze_until_date::text end,
          'note', pis.note,
          'source_ref', pis.source_ref
        ) as before_json,
        null::jsonb as after_json,
        null::text as reason,
        pis.note as note,
        pis.timesheet_id,
        jsonb_build_object('snooze_id', pis.id::text) as meta_json
      from public.pay_item_snoozes pis
      where pis.source_ref = ('advance:' || v_finance_case_id::text)
        and pis.cleared_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  generic_audit_events as (
    select
      ae.ts_utc as at_utc,
      'AUDIT'::text as source,
      ae.action as event_type,
      initcap(replace(lower(coalesce(ae.action, 'EVENT')), '_', ' ')) as title,
      ae.before_json,
      ae.after_json,
      ae.reason,
      null::text as note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'object_type', ae.object_type,
        'object_id_text', ae.object_id_text,
        'actor_user_id', case when ae.actor_user_id is null then null else ae.actor_user_id::text end,
        'actor_display', ae.actor_display,
        'actor_role_at_time', ae.actor_role_at_time,
        'correlation_id', ae.correlation_id
      ) as meta_json
    from public.audit_events ae
    where (
      ae.object_type in ('pay_advances','finance_cases')
      and ae.object_id_text = v_finance_case_id::text
    )
    or (
      v_case.linked_timesheet_id is not null
      and ae.object_type = 'timesheets'
      and ae.object_id_text = v_case.linked_timesheet_id::text
    )
  ),
  batch_refs as (
    select distinct par.pay_batch_id
    from public.pay_advance_reservations par
    where par.finance_case_id = v_finance_case_id
      and par.pay_batch_id is not null
    union
    select distinct pap.pay_batch_id
    from public.pay_advance_patches pap
    where pap.advance_id = v_finance_case_id
      and pap.pay_batch_id is not null
    union
    select v_case.payout_pay_batch_id
    where v_case.payout_pay_batch_id is not null
    union
    select v_case.latest_recovery_pay_batch_id
    where v_case.latest_recovery_pay_batch_id is not null
  ),
  batch_override_events as (
    select
      x.at_utc,
      'PAYE_OVERRIDE'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      x.pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        pb.created_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_REQUESTED'::text as event_type,
        'Same-week PAYE override requested'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_req.display_name, '')), ''), nullif(btrim(coalesce(tu_req.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        'Derived from pay batch creation because no separate requested-at field is stored on pay_batches.'::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_req.display_name, '')), ''), nullif(btrim(coalesce(tu_req.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_req
        on tu_req.id = pb.same_week_paye_override_verified_by_user_id
      where coalesce(pb.same_week_paye_override_used, false) = true

      union all

      select
        pb.same_week_paye_override_verified_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_VERIFIED'::text as event_type,
        'Same-week PAYE override verified'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_ver.display_name, '')), ''), nullif(btrim(coalesce(tu_ver.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        null::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_ver.display_name, '')), ''), nullif(btrim(coalesce(tu_ver.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_ver
        on tu_ver.id = pb.same_week_paye_override_verified_by_user_id
      where pb.same_week_paye_override_verified_at_utc is not null

      union all

      select
        pb.created_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_USED'::text as event_type,
        'Same-week PAYE override used'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_used.display_name, '')), ''), nullif(btrim(coalesce(tu_used.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'status', pb.status
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        null::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_used.display_name, '')), ''), nullif(btrim(coalesce(tu_used.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_used
        on tu_used.id = pb.same_week_paye_override_verified_by_user_id
      where coalesce(pb.same_week_paye_override_used, false) = true
    ) x
    where x.at_utc is not null
  ),
  batch_candidate_communication_events as (
    select
      pbc.remittance_sent_at_utc as at_utc,
      'COMMUNICATION'::text as source,
      case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'PAYOUT_NOTICE_SENT' else 'REMITTANCE_SENT' end as event_type,
      case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'Worker payout notice sent' else 'Worker remittance sent' end as title,
      null::jsonb as before_json,
      jsonb_build_object(
        'message_kind', case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
        'candidate_id', case when pbc.candidate_id is null then null else pbc.candidate_id::text end,
        'candidate_display_name', pbc.candidate_display_name,
        'remittance_sent_at_utc', case when pbc.remittance_sent_at_utc is null then null else pbc.remittance_sent_at_utc::text end,
        'trigger_status', pbc.remittance_trigger_status,
        'last_remittance_error', pbc.last_remittance_error,
        'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
        'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
      ) as after_json,
      null::text as reason,
      pbc.last_remittance_error as note,
      pbc.pay_batch_id::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'pay_batch_candidate_id', pbc.id::text,
        'candidate_id', case when pbc.candidate_id is null then null else pbc.candidate_id::text end,
        'trigger_status', pbc.remittance_trigger_status
      ) as meta_json
    from batch_refs br
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = br.pay_batch_id
     and pbc.candidate_id = v_case.candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbc.remittance_sent_at_utc is not null
  ),
  batch_audit_events as (
    select
      ae.ts_utc as at_utc,
      case
        when ae.action in (
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR',
          'PAY_REMITTANCE_SENT'
        ) then 'COMMUNICATION'::text
        when upper(coalesce(ae.action, '')) like '%SAME_WEEK%'
         and upper(coalesce(ae.action, '')) like '%OVERRIDE%' then 'PAYE_OVERRIDE'::text
        else 'BATCH_AUDIT'::text
      end as source,
      ae.action as event_type,
      case
        when ae.action = 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' then 'Commit-stage worker payout notice triggered' else 'Commit-stage worker remittance triggered' end
        when ae.action = 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Commit-stage worker payout notice error' else 'Commit-stage worker remittance error' end
        when ae.action = 'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Settlement catch-up payout notice triggered' else 'Settlement catch-up remittance triggered' end
        when ae.action = 'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Settlement catch-up payout notice error' else 'Settlement catch-up remittance error' end
        when ae.action = 'PAY_REMITTANCE_SENT' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' then 'Worker payout notice send results recorded' else 'Worker remittance send results recorded' end
        else initcap(replace(lower(coalesce(ae.action, 'EVENT')), '_', ' '))
      end as title,
      ae.before_json,
      ae.after_json,
      ae.reason,
      null::text as note,
      ae.object_id_text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'object_type', ae.object_type,
        'object_id_text', ae.object_id_text,
        'actor_user_id', case when ae.actor_user_id is null then null else ae.actor_user_id::text end,
        'actor_display', ae.actor_display,
        'actor_role_at_time', ae.actor_role_at_time,
        'correlation_id', ae.correlation_id
      ) as meta_json
    from public.audit_events ae
    join batch_refs br
      on ae.object_id_text = br.pay_batch_id::text
    where ae.object_type in ('pay_batch', 'pay_batches')
      and (
        ae.action in (
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR',
          'PAY_REMITTANCE_SENT'
        )
        or (
          upper(coalesce(ae.action, '')) like '%SAME_WEEK%'
          and upper(coalesce(ae.action, '')) like '%OVERRIDE%'
        )
      )
  ),
  batch_events as (
    select
      x.at_utc,
      'BATCH'::text as source,
      x.event_type,
      x.title,
      null::jsonb as before_json,
      x.after_json,
      x.reason,
      null::text as note,
      x.pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        pb.created_at_utc as at_utc,
        'BATCH_CREATED'::text as event_type,
        'Pay batch created'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'batch_kind_fixed', pb.batch_kind_fixed,
          'bulk_reference', pb.bulk_reference
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.created_at_utc is not null

      union all

      select
        pb.scheduled_at_utc as at_utc,
        'BATCH_SCHEDULED'::text as event_type,
        'Pay batch scheduled'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'schedule_kind', pb.schedule_kind
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.scheduled_at_utc is not null

      union all

      select
        pb.completed_at_utc as at_utc,
        'BATCH_SETTLED'::text as event_type,
        'Pay batch settled'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'completed_at_utc', pb.completed_at_utc,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.completed_at_utc is not null

      union all

      select
        pbar.created_at_utc as at_utc,
        'AUTH_REQUEST_CREATED'::text as event_type,
        'Authorisation requested'::text as title,
        jsonb_build_object(
          'state', pbar.state,
          'required_quantity', pbar.required_quantity,
          'schedule_kind', pbar.schedule_kind,
          'scheduled_at_utc', pbar.scheduled_at_utc
        ) as after_json,
        null::text as reason,
        pbar.pay_batch_id::text as pay_batch_id_text,
        jsonb_build_object('auth_request_id', pbar.id::text) as meta_json
      from batch_refs br
      join public.pay_batch_auth_requests pbar
        on pbar.pay_batch_id = br.pay_batch_id
      where pbar.created_at_utc is not null

      union all

      select
        pbaa.action_at_utc as at_utc,
        'AUTH_ACTION'::text as event_type,
        'Authorisation action'::text as title,
        jsonb_build_object('action', pbaa.action, 'note', pbaa.note) as after_json,
        null::text as reason,
        pbaa.pay_batch_id::text as pay_batch_id_text,
        jsonb_build_object('auth_request_id', pbaa.auth_request_id::text, 'auth_action_id', pbaa.id::text) as meta_json
      from batch_refs br
      join public.pay_batch_auth_actions pbaa
        on pbaa.pay_batch_id = br.pay_batch_id
      where pbaa.action_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  timesheet_events as (
    select
      x.at_utc,
      'TIMESHEET'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      x.timesheet_id_text,
      x.meta_json
    from (
      select
        ts.created_at as at_utc,
        'TIMESHEET_VERSION'::text as event_type,
        'Timesheet version captured'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'timesheet_id', ts.timesheet_id::text,
          'version', ts.version,
          'is_current', ts.is_current,
          'status', ts.status,
          'reference_number', ts.reference_number,
          'actual_schedule_json', ts.actual_schedule_json
        ) as after_json,
        null::text as reason,
        null::text as note,
        ts.timesheet_id::text as timesheet_id_text,
        jsonb_build_object('booking_id', ts.booking_id, 'version', ts.version) as meta_json
      from booking_ctx bc
      join public.timesheets ts
        on ts.booking_id = bc.booking_id
      where ts.created_at is not null

      union all

      select
        pbts.created_at_utc as at_utc,
        'FROZEN_SNAPSHOT'::text as event_type,
        'Pay batch timesheet snapshot captured'::text as title,
        jsonb_build_object('base_snapshot_json', pbts.base_snapshot_json) as before_json,
        jsonb_build_object('target_snapshot_json', pbts.target_snapshot_json, 'signature', pbts.signature) as after_json,
        null::text as reason,
        null::text as note,
        pbts.timesheet_id::text as timesheet_id_text,
        jsonb_build_object('pay_batch_id', pbts.pay_batch_id::text, 'pay_channel', pbts.pay_channel) as meta_json
      from public.pay_batch_timesheet_snapshots pbts
      where pbts.timesheet_id = v_case.linked_timesheet_id
        and pbts.created_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  all_events as (
    select * from finance_events
    union all select * from reservation_events
    union all select * from batch_item_events
    union all select * from patch_events
    union all select * from snooze_events
    union all select * from generic_audit_events
    union all select * from batch_override_events
    union all select * from batch_candidate_communication_events
    union all select * from batch_audit_events
    union all select * from batch_events
    union all select * from timesheet_events
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'at_utc', ae.at_utc,
        'source', ae.source,
        'event_type', ae.event_type,
        'title', ae.title,
        'before_json', ae.before_json,
        'after_json', ae.after_json,
        'reason', ae.reason,
        'note', ae.note,
        'pay_batch_id', ae.pay_batch_id_text,
        'reservation_id', ae.reservation_id_text,
        'timesheet_id', ae.timesheet_id_text,
        'meta', ae.meta_json
      )
      order by ae.at_utc asc, ae.source asc, ae.event_type asc
    ),
    '[]'::jsonb
  )
  into v_timeline
  from all_events ae;

  return jsonb_build_object(
    'ok', true,
    'finance_case', jsonb_build_object(
      'finance_case_id', v_case.finance_case_id::text,
      'case_type', v_case.case_type,
      'candidate_id', case when v_case.candidate_id is null then null else v_case.candidate_id::text end,
      'candidate_tms_ref', v_case.candidate_tms_ref,
      'candidate_display_name', v_case.candidate_display_name,
      'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
      'client_name', v_case.client_name,
      'linked_timesheet_id', case when v_case.linked_timesheet_id is null then null else v_case.linked_timesheet_id::text end,
      'linked_shift_date', case when v_case.linked_shift_date is null then null else v_case.linked_shift_date::text end,
      'status', v_case.status,
      'payout_status', v_case.payout_status,
      'original_amount', v_case.original_amount,
      'outstanding_amount', v_case.outstanding_amount,
      'weekly_due', v_case.weekly_due,
      'weeks_total', v_case.weeks_total,
      'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'adjustment_comment', v_case.adjustment_comment,
      'source_original_paid_amount', v_case.source_original_paid_amount,
      'source_corrected_paid_amount', v_case.source_corrected_paid_amount,
      'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
      'take_home_floor_override', v_case.take_home_floor_override,
      'latest_remittance_sent_at_utc', v_case.latest_remittance_sent_at_utc,
      'latest_remittance_trigger_status', v_case.latest_remittance_trigger_status,
      'last_remittance_error', v_case.last_remittance_error,
      'latest_recovery_pay_batch_id', case when v_case.latest_recovery_pay_batch_id is null then null else v_case.latest_recovery_pay_batch_id::text end,
      'latest_recovery_pay_date', case when v_case.latest_recovery_pay_date is null then null else v_case.latest_recovery_pay_date::text end,
      'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end,
      'payout_transfer_id', case when v_case.payout_transfer_id is null then null else v_case.payout_transfer_id::text end,
      'active_snooze_id', case when v_case.active_snooze_id is null then null else v_case.active_snooze_id::text end,
      'active_snooze_kind', v_case.active_snooze_kind,
      'active_snooze_until_date', case when v_case.active_snooze_until_date is null then null else v_case.active_snooze_until_date::text end,
      'active_snooze_note', v_case.active_snooze_note,
      'written_off_at_utc', v_case.written_off_at_utc,
      'write_off_reason', v_case.write_off_reason,
      'cleared_at_utc', v_case.cleared_at_utc,
      'baseline_signature', v_case.baseline_signature,
      'schedule_json', v_case.schedule_json,
      'notes', v_case.notes,
      'created_at', v_case.created_at,
      'updated_at', v_case.updated_at,
      'is_mixed_case', v_case.is_mixed_case,
      'open_taxable_count', v_case.open_taxable_count,
      'open_reimbursement_count', v_case.open_reimbursement_count,
      'unresolved_taxable_count', v_case.unresolved_taxable_count,
      'stale_count', v_case.stale_count,
      'component_resolution_summary_json', v_case.component_resolution_summary_json
    ),
    'current_component_state', coalesce(v_current_component_state, '[]'::jsonb),
    'timeline', coalesce(v_timeline, '[]'::jsonb)
  );
end;
$function$;

-- pay_finance_case_pause_resume(uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.pay_finance_case_pause_resume(p_finance_case_id uuid, p_actor_user_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_target_status public.pay_advance_status_enum;
  v_event_type text;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_action text := upper(btrim(coalesce(p_action,'')));
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_pause_resume: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_pause_resume: actor_user_id is required'
    )::text;
  end if;

  if v_action not in ('PAUSE','RESUME') then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','ACTION_INVALID',
      'message','pay_finance_case_pause_resume: action must be PAUSE or RESUME'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_pause_resume: repayable finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if coalesce(v_case.write_off_reason,'') <> '' or v_case.written_off_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_WRITTEN_OFF',
      'message','pay_finance_case_pause_resume: written-off finance cases cannot be paused or resumed',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount,0),2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','NO_OUTSTANDING_BALANCE',
      'message','pay_finance_case_pause_resume: finance case has no outstanding balance',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_action = 'PAUSE' then
    if v_case.status = 'PAUSED'::public.pay_advance_status_enum then
      return jsonb_build_object(
        'ok', true,
        'finance_case_id', p_finance_case_id::text,
        'case_type', v_case.case_type::text,
        'status', v_case.status::text,
        'action', 'PAUSE'
      );
    end if;
    v_target_status := 'PAUSED'::public.pay_advance_status_enum;
    v_event_type := 'PAUSED';
  else
    if v_case.status = 'ACTIVE'::public.pay_advance_status_enum then
      return jsonb_build_object(
        'ok', true,
        'finance_case_id', p_finance_case_id::text,
        'case_type', v_case.case_type::text,
        'status', v_case.status::text,
        'action', 'RESUME'
      );
    end if;
    if v_case.status <> 'PAUSED'::public.pay_advance_status_enum then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_PAUSE_RESUME',
        'code','RESUME_NOT_ALLOWED',
        'message','pay_finance_case_pause_resume: only paused finance cases can be resumed',
        'finance_case_id', p_finance_case_id::text,
        'current_status', v_case.status::text
      )::text;
    end if;
    v_target_status := 'ACTIVE'::public.pay_advance_status_enum;
    v_event_type := 'RESUMED';
  end if;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end
  );

  update public.pay_advances pa
  set status = v_target_status,
      updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_event_type,
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    nullif(btrim(coalesce(p_reason,'')), ''),
    case when v_action = 'PAUSE' then 'Finance case paused' else 'Finance case resumed' end
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'action', v_action
  );
end;
$function$;

-- pay_finance_case_restructure(uuid,uuid,numeric,integer,date,numeric,numeric,text)
CREATE OR REPLACE FUNCTION public.pay_finance_case_restructure(p_finance_case_id uuid, p_actor_user_id uuid, p_weekly_due numeric, p_weeks_total integer, p_start_week_start date, p_minimum_earnings_threshold numeric DEFAULT NULL::numeric, p_take_home_floor_override numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due_week_start date := null;
  v_required_weeks int := 0;
  v_remaining_amount numeric(12,2);
  v_component_remaining_amount numeric(12,2) := 0;
  v_open_component_count integer := 0;
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_note text;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;
  v_candidate_pay_method text := null;
  v_taxable_channel_restructure_required boolean := false;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_restructure: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_restructure: actor_user_id is required'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','START_WEEK_START_REQUIRED',
      'message','pay_finance_case_restructure: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','START_WEEK_START_NOT_MONDAY',
      'message','pay_finance_case_restructure: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message','pay_finance_case_restructure: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','TAKE_HOME_FLOOR_INVALID',
      'message','pay_finance_case_restructure: take_home_floor_override must be >= 0'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_restructure: repayable finance case not found or not eligible for restructure',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if coalesce(v_case.write_off_reason,'') <> '' or v_case.written_off_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_WRITTEN_OFF',
      'message','pay_finance_case_restructure: written-off finance cases cannot be restructured',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_NOT_REPAYABLE',
      'message','pay_finance_case_restructure: manual credit adjustments are not repayable and cannot be restructured',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method, ''))
  into v_candidate_pay_method
  from public.candidates as c
  where c.id = v_case.candidate_id
  limit 1;

  select exists (
    select 1
    from public.pay_finance_case_components as pfc_block
    where pfc_block.finance_case_id = p_finance_case_id
      and pfc_block.closed_at_utc is null
      and pfc_block.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and round(coalesce(pfc_block.remaining_source_amount, 0), 2) > 0
      and upper(coalesce(pfc_block.source_pay_method, '')) in ('PAYE', 'UMBRELLA')
      and v_candidate_pay_method in ('PAYE', 'UMBRELLA')
      and upper(coalesce(pfc_block.source_pay_method, '')) <> v_candidate_pay_method
      and (
        coalesce(pfc_block.is_resolution_stale, false) = true
        or nullif(btrim(coalesce(pfc_block.saved_target_pay_method, '')), '') is null
        or upper(coalesce(pfc_block.saved_target_pay_method, '')) <> v_candidate_pay_method
      )
  )
  into v_taxable_channel_restructure_required;

  if coalesce(v_taxable_channel_restructure_required, false) = true then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','TAXABLE_CHANNEL_RESTRUCTURE_REQUIRED',
      'message','pay_finance_case_restructure: taxable PAYE/Umbrella channel restructure is required before schedule-only restructure can be applied',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'candidate_pay_method', v_candidate_pay_method
    )::text;
  end if;

  select
    round(coalesce(sum(pfc.remaining_source_amount), 0), 2)::numeric(12,2),
    count(*)::integer
  into
    v_component_remaining_amount,
    v_open_component_count
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_remaining_amount := case
    when v_open_component_count > 0 then v_component_remaining_amount
    else round(coalesce(v_case.outstanding_amount,0),2)
  end;

  if v_remaining_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','NO_OUTSTANDING_BALANCE',
      'message','pay_finance_case_restructure: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_RESTRUCTURE',
        'code','WEEKLY_DUE_INVALID',
        'message','pay_finance_case_restructure: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_RESTRUCTURE',
        'code','WEEKS_TOTAL_INVALID',
        'message','pay_finance_case_restructure: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','REPAYMENT_INPUT_REQUIRED',
      'message','pay_finance_case_restructure: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_remaining_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_remaining_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKLY_DUE_INVALID',
      'message','pay_finance_case_restructure: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKS_TOTAL_INVALID',
      'message','pay_finance_case_restructure: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_new_start_week_start := p_start_week_start;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;
  v_new_note := case when p_note is null then v_case.notes else nullif(btrim(coalesce(p_note,'')), '') end;

  v_required_weeks := greatest(ceil(v_remaining_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKS_TOTAL_TOO_SHORT',
      'message','pay_finance_case_restructure: repayment schedule does not cover the remaining outstanding balance',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total,
      'outstanding_amount', v_remaining_amount
    )::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_new_start_week_start + (gs.i * 7))::date,
        'amount', round(
          -least(
            v_new_weekly_due,
            greatest(v_remaining_amount - (v_new_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_new_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due_week_start
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_remaining_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'notes', v_case.notes
  );

  update public.pay_advances pa
  set
    outstanding_amount = v_remaining_amount,
    schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
    weekly_due = v_new_weekly_due,
    weeks_total = v_new_weeks_total,
    start_week_start = v_new_start_week_start,
    next_due_week_start = v_new_next_due_week_start,
    minimum_earnings_threshold = v_new_minimum_earnings_threshold,
    take_home_floor_override = v_new_take_home_floor_override,
    notes = v_new_note,
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'notes', v_case.notes,
    'schedule_input_mode', v_schedule_input_mode
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'RESTRUCTURED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    null::text,
    'Finance case repayment terms restructured'
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'schedule_input_mode', v_schedule_input_mode,
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb)
  );
end;
$function$;

-- pay_finance_case_taxable_channel_restructure_suggestion(uuid,uuid,date,text,text,integer,numeric,numeric,text)
CREATE OR REPLACE FUNCTION public.pay_finance_case_taxable_channel_restructure_suggestion(p_finance_case_id uuid, p_actor_user_id uuid, p_effective_pay_date date DEFAULT NULL::date, p_resolution_path text DEFAULT 'SUGGESTED'::text, p_schedule_input_mode text DEFAULT NULL::text, p_weeks_total integer DEFAULT NULL::integer, p_weekly_due numeric DEFAULT NULL::numeric, p_manual_total_remaining numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_candidate record;
  v_finance_settings record;
  v_target_umbrella_vat_chargeable boolean := false;

  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));
  v_candidate_pay_method text := null;

  v_open_component_count integer := 0;
  v_source_total_ex numeric(12,2) := 0;
  v_taxable_source_total_ex numeric(12,2) := 0;
  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_taxable_target_total_ex numeric(12,2) := 0;
  v_fixed_target_total_ex numeric(12,2) := 0;
  v_fixed_target_total_vat numeric(12,2) := 0;
  v_fixed_target_total_inc numeric(12,2) := 0;
  v_taxable_manual_target_ex numeric(12,2) := 0;
  v_convertible_target_total_ex numeric(12,2) := 0;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_requires_restructure boolean := false;
  v_has_open_batch_item boolean := false;
  v_blocked_reason text := null;

  v_restructure_start_week_start date := null;
  v_existing_weeks_remaining integer := null;
  v_selected_weeks_total integer := null;
  v_existing_weekly_due numeric(12,2) := null;
  v_selected_weekly_due numeric(12,2) := null;
  v_existing_final_week_amount numeric(12,2) := null;
  v_suggested_weekly_due numeric(12,2) := null;
  v_suggested_final_week_amount numeric(12,2) := null;
  v_selected_final_week_amount numeric(12,2) := null;
  v_schedule_sign integer := -1;

  v_manual_total_remaining_ex numeric(12,2) := null;
  v_ratio numeric := 1;
  v_delta numeric(12,2) := 0;
  v_adjust_component_id uuid := null;

  v_component_breakdown jsonb := '[]'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  if v_schedule_input_mode_norm is null then
    v_schedule_input_mode_norm := 'BY_WEEKS';
  end if;

  if v_schedule_input_mode_norm not in ('BY_WEEKS', 'BY_WEEKLY_DUE') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'SCHEDULE_INPUT_MODE_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE',
      'schedule_input_mode', p_schedule_input_mode
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKS' and p_weekly_due is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKLY_DUE_NOT_ALLOWED_WITH_BY_WEEKS',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must not be supplied when schedule_input_mode is BY_WEEKS'
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKLY_DUE' and p_weeks_total is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKS_TOTAL_NOT_ALLOWED_WITH_BY_WEEKLY_DUE',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must not be supplied when schedule_input_mode is BY_WEEKLY_DUE'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  limit 1;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'UNDERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'CASE_TYPE_NOT_SUPPORTED'
    );
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'reason_code', 'CASE_NOT_ACTIVE'
    );
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method,
    c.umbrella_id as umbrella_id,
    u.id as target_umbrella_id,
    coalesce(u.vat_chargeable, false) as target_umbrella_vat_chargeable
  into v_candidate
  from public.candidates as c
  left join public.umbrellas as u
    on u.id = c.umbrella_id
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_candidate_pay_method = 'UMBRELLA' and v_candidate.target_umbrella_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'TARGET_UMBRELLA_CONTEXT_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate is currently UMBRELLA but no target umbrella company is configured for VAT/routing context',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_target_umbrella_vat_chargeable := case
    when v_candidate_pay_method = 'UMBRELLA' then coalesce(v_candidate.target_umbrella_vat_chargeable, false)
    else false
  end;

  select
    sfp.vat_rate_pct,
    sfp.erni_pct
  into v_finance_settings
  from public.settings_finance_pick(v_effective_pay_date) as sfp
  limit 1;

  if v_finance_settings.vat_rate_pct is null or v_finance_settings.erni_pct is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance settings missing vat_rate_pct and/or erni_pct',
      'effective_pay_date', v_effective_pay_date::text
    )::text;
  end if;

  v_relevant_erni_pct := round(v_finance_settings.erni_pct, 6);
  v_vat_rate_pct := round(v_finance_settings.vat_rate_pct, 6);

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where pbc.pay_batch_id = pb.id
      and coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    v_blocked_reason := 'CASE_ALREADY_IN_OPEN_BATCH';
  end if;

  drop table if exists pg_temp._tmp_taxable_channel_restructure_components;

  create temp table _tmp_taxable_channel_restructure_components on commit drop as
  select
    pfc.id as finance_component_id,
    pfc.finance_case_id as finance_case_id,
    pfc.candidate_id as candidate_id,
    pfc.client_id as client_id,
    pfc.linked_timesheet_id as linked_timesheet_id,
    pfc.source_family_key as source_family_key,
    pfc.component_key_type as component_key_type,
    pfc.component_key_value as component_key_value,
    pfc.classification as classification,
    upper(nullif(btrim(coalesce(pfc.source_pay_method, '')), '')) as source_pay_method,
    coalesce(pfc.source_basis_json, '{}'::jsonb) as source_basis_json,
    round(coalesce(pfc.source_amount, 0), 2)::numeric(12,2) as source_amount,
    round(coalesce(pfc.remaining_source_amount, 0), 2)::numeric(12,2) as remaining_source_amount,
    pfc.saved_target_pay_method as saved_target_pay_method,
    pfc.saved_resolution_mode as saved_resolution_mode,
    pfc.saved_resolution_payload_json as saved_resolution_payload_json,
    pfc.saved_resolution_result_json as saved_resolution_result_json,
    coalesce(pfc.is_resolution_stale, false) as is_resolution_stale,
    pfc.stale_reason as stale_reason,
    (
      pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    )::boolean as is_taxable_channel_component,
    false::boolean as requires_component_conversion,
    0::numeric(12,2) as target_remaining_ex,
    0::numeric(12,2) as target_remaining_vat,
    0::numeric(12,2) as target_remaining_inc
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

  select count(*)::integer
  into v_open_component_count
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'NO_OPEN_REMAINING_COMPONENTS'
    );
  end if;

  select coalesce(
    bool_or(
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    false
  )
  into v_requires_restructure
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_requires_restructure is distinct from true then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'candidate_pay_method', v_candidate_pay_method,
      'reason_code', 'NO_TAXABLE_CHANNEL_MISMATCH'
    );
  end if;

  v_umbrella_vat_chargeable := v_target_umbrella_vat_chargeable;

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set
    requires_component_conversion = (
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    target_remaining_ex = round(
      case
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'UMBRELLA'
         and v_candidate_pay_method = 'PAYE'
          then public._pay_convert_umbrella_to_paye_ex(trc.remaining_source_amount, v_relevant_erni_pct)
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'PAYE'
         and v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0)
        else trc.remaining_source_amount
      end,
      2
    ),
    target_remaining_vat = round(
      case
        when v_candidate_pay_method = 'UMBRELLA'
         and trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'PAYE'
         and v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_umbrella_vat_calc(
            coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0),
            v_vat_rate_pct,
            v_umbrella_vat_chargeable
          )->>'vat')::numeric, 0)
        else 0
      end,
      2
    )
  where trc.finance_component_id is not null;

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2)
  where trc.finance_component_id is not null;

  select
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.remaining_source_amount) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_vat) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_inc) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
  into
    v_source_total_ex,
    v_taxable_source_total_ex,
    v_target_total_ex,
    v_target_total_vat,
    v_target_total_inc,
    v_taxable_target_total_ex,
    v_fixed_target_total_ex,
    v_fixed_target_total_vat,
    v_fixed_target_total_inc,
    v_convertible_target_total_ex
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then
    v_manual_total_remaining_ex := round(p_manual_total_remaining, 2);
    if v_manual_total_remaining_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'MANUAL_TOTAL_REMAINING_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: manual_total_remaining must be > 0 when supplied',
        'manual_total_remaining', p_manual_total_remaining
      )::text;
    end if;

    select
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
    into
      v_fixed_target_total_ex,
      v_convertible_target_total_ex
    from pg_temp._tmp_taxable_channel_restructure_components as trc;

    if v_manual_total_remaining_ex < v_fixed_target_total_ex then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'MANUAL_TOTAL_BELOW_FIXED_COMPONENTS',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: manual_total_remaining cannot be below the unchanged fixed component total',
        'manual_total_remaining', v_manual_total_remaining_ex,
        'fixed_component_total_ex_vat', v_fixed_target_total_ex
      )::text;
    end if;

    if v_convertible_target_total_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'TAXABLE_TARGET_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: taxable target total must be > 0 before manual allocation'
      )::text;
    end if;

    v_taxable_manual_target_ex := greatest(round(v_manual_total_remaining_ex - v_fixed_target_total_ex, 2), 0);

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set
      target_remaining_ex = round((trc.target_remaining_ex / v_convertible_target_total_ex) * v_taxable_manual_target_ex, 2),
      target_remaining_vat = case
        when v_candidate_pay_method = 'UMBRELLA'
          then round(coalesce((public._pay_umbrella_vat_calc(round((trc.target_remaining_ex / v_convertible_target_total_ex) * v_taxable_manual_target_ex, 2), v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
        else 0
      end
    where trc.requires_component_conversion;

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2)
    where trc.finance_component_id is not null;

    select trc.finance_component_id
    into v_adjust_component_id
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    where trc.requires_component_conversion
    order by trc.target_remaining_ex desc, trc.finance_component_id desc
    limit 1;

    select round(v_taxable_manual_target_ex - coalesce(sum(trc.target_remaining_ex), 0), 2)
    into v_delta
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    where trc.requires_component_conversion;

    if v_adjust_component_id is not null and v_delta <> 0 then
      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set target_remaining_ex = round(trc.target_remaining_ex + v_delta, 2)
      where trc.finance_component_id = v_adjust_component_id
        and trc.requires_component_conversion;

      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set
        target_remaining_vat = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else 0
        end,
        target_remaining_inc = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(trc.target_remaining_ex + coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else trc.target_remaining_ex
        end
      where trc.finance_component_id = v_adjust_component_id
        and trc.requires_component_conversion;
    end if;

    select
      round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_vat) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_inc) filter (where trc.requires_component_conversion is distinct from true), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.requires_component_conversion), 0), 2)::numeric(12,2)
    into
      v_target_total_ex,
      v_target_total_vat,
      v_target_total_inc,
      v_taxable_target_total_ex,
      v_fixed_target_total_ex,
      v_fixed_target_total_vat,
      v_fixed_target_total_inc,
      v_convertible_target_total_ex
    from pg_temp._tmp_taxable_channel_restructure_components as trc;
  end if;

  if v_source_total_ex <= 0 or v_target_total_ex <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'REMAINING_TOTAL_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: source and target totals must be > 0',
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  v_restructure_start_week_start := coalesce(v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));
  if public._pay_week_start_monday(v_restructure_start_week_start) <> v_restructure_start_week_start then
    v_restructure_start_week_start := public._pay_week_start_monday(v_restructure_start_week_start);
  end if;

  v_schedule_sign := case
    when v_case.case_type IN (
      'UNDERPAYMENT'::public.pay_finance_case_type_enum,
      'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
    ) then 1
    else -1
  end;

  select count(*)::integer
  into v_existing_weeks_remaining
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and abs(coalesce(
      case
        when coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
          then round((sched.schedule_row->>'amount')::numeric, 2)
        else null::numeric
      end,
      0::numeric
    )) > 0;

  if v_existing_weeks_remaining is null or v_existing_weeks_remaining < 1 then
    if round(coalesce(v_case.weekly_due, 0), 2) > 0 then
      v_existing_weeks_remaining := greatest(ceil(v_source_total_ex / round(coalesce(v_case.weekly_due, 0), 2))::integer, 1);
    elsif coalesce(v_case.weeks_total, 0) > 0 then
      v_existing_weeks_remaining := v_case.weeks_total;
    else
      v_existing_weeks_remaining := 1;
    end if;
  end if;

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_weekly_due
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date asc
  limit 1;

  v_existing_weekly_due := coalesce(nullif(round(coalesce(v_case.weekly_due, 0), 2), 0), v_existing_weekly_due, round((ceil((v_source_total_ex / greatest(v_existing_weeks_remaining, 1)) * 100) / 100), 2));

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_final_week_amount
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date desc
  limit 1;

  if v_existing_final_week_amount is null then
    v_existing_final_week_amount := round(least(v_existing_weekly_due, greatest(v_source_total_ex - (v_existing_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);
  end if;

  v_ratio := case when v_source_total_ex > 0 then v_target_total_ex / v_source_total_ex else 1 end;
  v_suggested_weekly_due := greatest(round(v_existing_weekly_due * v_ratio, 2), 0.01);
  v_suggested_final_week_amount := round(least(v_suggested_weekly_due, greatest(v_target_total_ex - (v_suggested_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);

  if v_schedule_input_mode_norm = 'BY_WEEKS' then
    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must be >= 1',
        'weeks_total', p_weeks_total
      )::text;
    end if;

    v_selected_weeks_total := coalesce(p_weeks_total, v_existing_weeks_remaining);
    v_selected_weekly_due := case
      when p_weeks_total is null then v_suggested_weekly_due
      else round((ceil((v_target_total_ex / p_weeks_total) * 100) / 100), 2)
    end;
  else
    if p_weekly_due is null or round(p_weekly_due, 2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKLY_DUE_REQUIRED',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must be > 0 when schedule_input_mode is BY_WEEKLY_DUE',
        'weekly_due', p_weekly_due
      )::text;
    end if;

    v_selected_weekly_due := round(p_weekly_due, 2);
    v_selected_weeks_total := greatest(ceil(v_target_total_ex / v_selected_weekly_due)::integer, 1);
  end if;

  v_selected_final_week_amount := round(least(v_selected_weekly_due, greatest(v_target_total_ex - (v_selected_weekly_due * greatest(v_selected_weeks_total - 1, 0)), 0)), 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', trc.finance_component_id::text,
          'linked_timesheet_id', case when trc.linked_timesheet_id is null then null else trc.linked_timesheet_id::text end,
          'source_family_key', trc.source_family_key,
          'component_key_type', trc.component_key_type,
          'component_key_value', trc.component_key_value,
          'classification', trc.classification::text,
          'source_pay_method', trc.source_pay_method,
          'target_pay_method', v_candidate_pay_method,
          'source_remaining_amount_ex_vat', trc.remaining_source_amount,
          'target_remaining_amount_ex_vat', trc.target_remaining_ex,
          'target_remaining_amount_vat', trc.target_remaining_vat,
          'target_remaining_amount_inc_vat', trc.target_remaining_inc,
          'requires_component_conversion', trc.requires_component_conversion,
          'is_taxable_channel_component', trc.is_taxable_channel_component,
          'is_fixed_component', (trc.requires_component_conversion is distinct from true),
          'fixed_component_unchanged', (trc.requires_component_conversion is distinct from true),
          'saved_target_pay_method', trc.saved_target_pay_method,
          'saved_resolution_mode', case when trc.saved_resolution_mode is null then null else trc.saved_resolution_mode::text end,
          'is_resolution_stale', trc.is_resolution_stale,
          'stale_reason', trc.stale_reason
        )
      )
      order by trc.allocation_priority_group nulls last, trc.allocation_priority_order nulls last, trc.finance_component_id
    ),
    '[]'::jsonb
  )
  into v_component_breakdown
  from (
    select
      trc.*,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    join public.pay_finance_case_components as pfc
      on pfc.id = trc.finance_component_id
  ) as trc;

  return jsonb_build_object(
    'ok', true,
    'requires_restructure', true,
    'can_apply', (v_has_open_batch_item is distinct from true),
    'blocked_reason', v_blocked_reason,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'source_pay_methods', (
      select coalesce(jsonb_agg(distinct trc.source_pay_method), '[]'::jsonb)
      from pg_temp._tmp_taxable_channel_restructure_components as trc
      where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    ),
    'target_pay_method', v_candidate_pay_method,
    'effective_pay_date', v_effective_pay_date::text,
    'resolution_path', v_resolution_path_norm,
    'schedule_input_mode', v_schedule_input_mode_norm,
    'existing', jsonb_build_object(
      'source_remaining_balance_ex_vat', v_source_total_ex,
      'taxable_source_remaining_balance_ex_vat', v_taxable_source_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'fixed_component_total_vat', v_fixed_target_total_vat,
      'fixed_component_total_inc_vat', v_fixed_target_total_inc,
      'weekly_due', v_existing_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_existing_final_week_amount,
      'start_week_start', v_restructure_start_week_start::text,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb)
    ),
    'suggested', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'target_remaining_balance_vat', v_target_total_vat,
      'target_remaining_balance_inc_vat', v_target_total_inc,
      'taxable_target_remaining_balance_ex_vat', v_taxable_target_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'fixed_component_total_vat', v_fixed_target_total_vat,
      'fixed_component_total_inc_vat', v_fixed_target_total_inc,
      'fixed_components_preserved', true,
      'weekly_due', v_suggested_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_suggested_final_week_amount,
      'erni_rate_pct', v_relevant_erni_pct,
      'erni_component_ex_vat', round(abs(v_taxable_source_total_ex - v_taxable_target_total_ex), 2),
      'vat_rate_pct', v_vat_rate_pct,
      'vat_amount', v_target_total_vat,
      'umbrella_vat_chargeable', v_umbrella_vat_chargeable
    ),
    'selected', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'fixed_component_total_ex_vat', v_fixed_target_total_ex,
      'taxable_target_remaining_balance_ex_vat', v_taxable_target_total_ex,
      'weekly_due', v_selected_weekly_due,
      'weeks_total', v_selected_weeks_total,
      'final_week_amount', v_selected_final_week_amount,
      'schedule_sign', v_schedule_sign,
      'start_week_start', v_restructure_start_week_start::text
    ),
    'component_breakdown', v_component_breakdown,
    'generated_at_utc', v_now_utc::text,
    'note', p_note
  );
end;
$function$;

-- pay_finance_case_write_off(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_finance_case_write_off(p_finance_case_id uuid, p_actor_user_id uuid, p_write_off_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_released_count int := 0;
  v_write_off_reason text := nullif(btrim(coalesce(p_write_off_reason,'')), '');
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_write_off: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_write_off: actor_user_id is required'
    )::text;
  end if;

  if v_write_off_reason is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','WRITE_OFF_REASON_REQUIRED',
      'message','pay_finance_case_write_off: write_off_reason is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_write_off: repayable finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.written_off_at_utc is not null or coalesce(v_case.write_off_reason,'') <> '' then
    return jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'written_off_at_utc', v_case.written_off_at_utc,
      'write_off_reason', v_case.write_off_reason
    );
  end if;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'write_off_reason', v_case.write_off_reason
  );

  update public.pay_advance_reservations par
  set status = 'RELEASED',
      released_at_utc = coalesce(par.released_at_utc, v_now_utc),
      released_reason = 'WRITE_OFF',
      updated_by_user_id = p_actor_user_id
  where par.finance_case_id = p_finance_case_id
    and par.status in ('RESERVED','COMMITTED');

  get diagnostics v_released_count = row_count;

  update public.pay_advances pa
  set
    status = 'PAID_OFF'::public.pay_advance_status_enum,
    outstanding_amount = 0,
    next_due_week_start = null::date,
    updated_at = v_now_utc,
    written_off_at_utc = v_now_utc,
    written_off_by_user_id = p_actor_user_id,
    write_off_reason = v_write_off_reason,
    cleared_at_utc = coalesce(pa.cleared_at_utc, v_now_utc),
    cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id)
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'write_off_reason', v_case.write_off_reason,
    'released_reservation_count', v_released_count
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    'WRITTEN_OFF',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    v_write_off_reason,
    'Finance case written off'
  );

  perform public._audit_insert(
    'pay_advances',
    p_finance_case_id::text,
    'FINANCE_CASE_WRITTEN_OFF',
    v_before_json,
    v_after_json,
    v_write_off_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'write_off_reason', v_case.write_off_reason,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'released_reservation_count', v_released_count
  );
end;
$function$;

-- pay_finance_component_fingerprint(text,text,text,pay_finance_component_classification_enum,text,text,jsonb,numeric,numeric,jsonb)
CREATE OR REPLACE FUNCTION public.pay_finance_component_fingerprint(p_source_family_key text, p_component_key_type text, p_component_key_value text, p_classification pay_finance_component_classification_enum, p_source_pay_method text, p_current_target_pay_method text, p_source_basis_json jsonb, p_source_amount numeric, p_relevant_erni_pct numeric DEFAULT NULL::numeric, p_target_basis_json jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT md5(
    jsonb_build_object(
      'source_family_key', coalesce(btrim(p_source_family_key), ''),
      'component_key_type', coalesce(btrim(p_component_key_type), ''),
      'component_key_value', coalesce(btrim(p_component_key_value), ''),
      'classification', coalesce(p_classification::text, ''),
      'source_pay_method', upper(coalesce(btrim(p_source_pay_method), '')),
      'current_target_pay_method', upper(coalesce(btrim(p_current_target_pay_method), '')),
      'source_basis_json', coalesce(jsonb_strip_nulls(p_source_basis_json), '{}'::jsonb),
      'source_amount', round(coalesce(abs(p_source_amount), 0), 2),
      'relevant_erni_pct', CASE WHEN p_relevant_erni_pct IS NULL THEN NULL ELSE round(p_relevant_erni_pct, 6) END,
      'target_basis_json', coalesce(jsonb_strip_nulls(p_target_basis_json), '{}'::jsonb)
    )::text
  );
$function$;

-- pay_finance_component_resolutions_apply(uuid,jsonb,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.pay_finance_component_resolutions_apply(p_candidate_id uuid, p_component_resolutions jsonb, p_actor_user_id uuid, p_finance_case_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_today_uk date := (now() at time zone 'Europe/London')::date;

  v_candidate record;
  v_finance_settings record;

  v_input_json jsonb := coalesce(p_component_resolutions, '[]'::jsonb);
  v_resolution_json jsonb;
  v_row_seq integer := 0;

  v_component_id_text text;
  v_component_id uuid;
  v_resolution_mode_text text;
  v_target_pay_method text;
  v_resolution_mode public.pay_finance_component_resolution_mode_enum;

  v_component record;

  v_before_json jsonb := null;
  v_after_json jsonb := null;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_target_units numeric := null;
  v_manual_replacement_rate numeric := null;
  v_manual_amount_ex_vat numeric := null;
  v_requested_target_units numeric := null;

  v_source_units numeric := null;
  v_source_rate numeric := null;
  v_source_charge_rate numeric := null;
  v_bucket_code text := null;
  v_component_semantics text := null;
  v_is_rate_bearing_row boolean := false;
  v_is_amount_led_row boolean := false;

  v_basis_amount_ex_vat numeric(12,2) := 0;
  v_target_amount_ex_vat numeric(12,2) := 0;
  v_target_amount_vat numeric(12,2) := 0;
  v_target_amount_inc_vat numeric(12,2) := 0;
  v_rate_precision numeric := null;

  v_target_amount_ex_vat_per_source numeric(18,10) := 0;
  v_target_amount_vat_per_source numeric(18,10) := 0;
  v_target_amount_inc_vat_per_source numeric(18,10) := 0;
  v_target_units_per_source numeric(18,10) := null;

  v_target_amounts_json jsonb := '{}'::jsonb;
  v_target_basis_json jsonb := '{}'::jsonb;
  v_resolution_payload_json jsonb := '{}'::jsonb;
  v_resolution_result_json jsonb := '{}'::jsonb;
  v_resolution_fingerprint text := null;

  v_applied_components jsonb := '[]'::jsonb;
  v_event_reason text := null;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: candidate_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: actor_user_id is required'
    )::text;
  END IF;

  IF jsonb_typeof(v_input_json) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'COMPONENT_RESOLUTIONS_ARRAY_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: component_resolutions must be a JSON array'
    )::text;
  END IF;

  SELECT
    c.id,
    upper(coalesce(c.pay_method, '')) AS pay_method
  INTO v_candidate
  FROM public.candidates c
  WHERE c.id = p_candidate_id
  LIMIT 1;

  IF v_candidate.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_component_resolutions_apply: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  END IF;

  IF v_candidate.pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_PAY_METHOD_INVALID',
      'message', 'pay_finance_component_resolutions_apply: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'candidate_pay_method', v_candidate.pay_method
    )::text;
  END IF;

  SELECT
    sfp.vat_rate_pct,
    sfp.erni_pct
  INTO v_finance_settings
  FROM public.settings_finance_pick(v_today_uk) sfp
  LIMIT 1;

  IF v_finance_settings.vat_rate_pct IS NULL OR v_finance_settings.erni_pct IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_finance_component_resolutions_apply: finance settings missing vat_rate_pct and/or erni_pct'
    )::text;
  END IF;

  IF jsonb_array_length(v_input_json) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'candidate_id', p_candidate_id::text,
      'finance_case_id', CASE WHEN p_finance_case_id IS NULL THEN NULL ELSE p_finance_case_id::text END,
      'applied_count', 0,
      'components', '[]'::jsonb
    );
  END IF;

  FOR v_resolution_json IN
    SELECT t_resolution.value
    FROM jsonb_array_elements(v_input_json) AS t_resolution(value)
  LOOP
    v_row_seq := v_row_seq + 1;

    IF v_resolution_json IS NULL OR jsonb_typeof(v_resolution_json) <> 'object' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'INVALID_RESOLUTION_ROW',
        'message', 'pay_finance_component_resolutions_apply: each resolution row must be a JSON object',
        'row_index', v_row_seq
      )::text;
    END IF;

    v_component_id_text := nullif(btrim(coalesce(v_resolution_json->>'finance_component_id', '')), '');
    IF v_component_id_text IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_ID_REQUIRED',
        'message', 'pay_finance_component_resolutions_apply: finance_component_id is required for every resolution row',
        'row_index', v_row_seq
      )::text;
    END IF;

    BEGIN
      v_component_id := v_component_id_text::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_ID_INVALID',
        'message', 'pay_finance_component_resolutions_apply: finance_component_id must be a valid UUID',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id_text
      )::text;
    END;

    v_resolution_mode_text := upper(coalesce(nullif(btrim(coalesce(v_resolution_json->>'resolution_mode', '')), ''), ''));
    IF v_resolution_mode_text NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE', 'MANUAL_AMOUNT') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'RESOLUTION_MODE_INVALID',
        'message', 'pay_finance_component_resolutions_apply: resolution_mode must be SUGGESTED_EQUIVALENT_BASIS, MANUAL_REPLACEMENT_RATE, or MANUAL_AMOUNT',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'resolution_mode', v_resolution_mode_text
      )::text;
    END IF;
    v_resolution_mode := v_resolution_mode_text::public.pay_finance_component_resolution_mode_enum;

    v_target_pay_method := upper(
      coalesce(
        nullif(btrim(coalesce(v_resolution_json->>'target_pay_method', '')), ''),
        v_candidate.pay_method
      )
    );

    IF v_target_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'TARGET_PAY_METHOD_INVALID',
        'message', 'pay_finance_component_resolutions_apply: target_pay_method must be PAYE or UMBRELLA',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'target_pay_method', v_target_pay_method
      )::text;
    END IF;

    IF v_target_pay_method IS DISTINCT FROM v_candidate.pay_method THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'TARGET_PAY_METHOD_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: target_pay_method must match the candidate current pay_method',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'target_pay_method', v_target_pay_method,
        'candidate_pay_method', v_candidate.pay_method
      )::text;
    END IF;

    SELECT
      pfc.id,
      pfc.finance_case_id,
      pfc.candidate_id,
      pfc.client_id,
      pfc.linked_timesheet_id,
      pfc.source_family_key,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      upper(coalesce(pfc.source_pay_method, '')) AS source_pay_method,
      pfc.source_basis_json,
      round(coalesce(pfc.source_amount, 0), 2) AS source_amount,
      round(coalesce(pfc.remaining_source_amount, 0), 2) AS remaining_source_amount,
      pfc.saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      pfc.resolution_fingerprint,
      pfc.is_resolution_stale,
      pfc.stale_reason,
      pfc.resolved_at_utc,
      pfc.closed_at_utc,
      pa.case_type,
      pa.status AS finance_case_status
    INTO v_component
    FROM public.pay_finance_case_components pfc
    JOIN public.pay_advances pa
      ON pa.id = pfc.finance_case_id
    WHERE pfc.id = v_component_id
    FOR UPDATE;

    IF v_component.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_NOT_FOUND',
        'message', 'pay_finance_component_resolutions_apply: finance component not found',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text
      )::text;
    END IF;

    IF v_component.candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_CANDIDATE_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: finance component does not belong to the specified candidate',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'candidate_id', p_candidate_id::text,
        'component_candidate_id', v_component.candidate_id::text
      )::text;
    END IF;

    IF p_finance_case_id IS NOT NULL AND v_component.finance_case_id IS DISTINCT FROM p_finance_case_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_CASE_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: finance component does not belong to the specified finance case',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'finance_case_id', p_finance_case_id::text,
        'component_finance_case_id', v_component.finance_case_id::text
      )::text;
    END IF;

    IF v_component.closed_at_utc IS NOT NULL OR round(coalesce(v_component.remaining_source_amount, 0), 2) <= 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_NOT_OPEN',
        'message', 'pay_finance_component_resolutions_apply: finance component must be open with remaining_source_amount > 0',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'closed_at_utc', v_component.closed_at_utc,
        'remaining_source_amount', round(coalesce(v_component.remaining_source_amount, 0), 2)
      )::text;
    END IF;

    IF v_component.classification IS DISTINCT FROM 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'REIMBURSEMENT_RESOLUTION_NOT_ALLOWED',
        'message', 'pay_finance_component_resolutions_apply: reimbursement components cannot be resolved through this path',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'classification', v_component.classification::text
      )::text;
    END IF;

    IF v_component.source_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'SOURCE_PAY_METHOD_INVALID',
        'message', 'pay_finance_component_resolutions_apply: source_pay_method must be PAYE or UMBRELLA on the component',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'source_pay_method', v_component.source_pay_method
      )::text;
    END IF;

    v_source_units := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_units', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_units')::numeric, 6)
      ELSE NULL
    END;
    v_source_rate := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_rate')::numeric, 6)
      ELSE NULL
    END;
    v_source_charge_rate := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_charge_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_charge_rate')::numeric, 6)
      ELSE NULL
    END;
    v_bucket_code := nullif(upper(btrim(coalesce(v_component.source_basis_json->>'bucket_code', ''))), '');
    v_is_rate_bearing_row := (
      v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and v_component.component_key_type in ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE')
      and v_component.component_key_type <> 'ADJUSTMENT_CODE'
      and v_source_units is not null
      and v_source_units > 0
      and v_source_rate is not null
      and v_source_charge_rate is not null
    );
    v_is_amount_led_row := not v_is_rate_bearing_row;
    v_component_semantics := case when v_is_rate_bearing_row then 'RATE_BEARING' else 'AMOUNT_LED' end;

    v_basis_amount_ex_vat := round(coalesce(v_component.remaining_source_amount, 0), 2)::numeric(12,2);

    v_relevant_erni_pct := CASE
      WHEN coalesce(v_resolution_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'relevant_erni_pct')::numeric, 6)
      WHEN coalesce(v_component.saved_resolution_payload_json->>'relevant_erni_pct', v_component.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round(coalesce(v_component.saved_resolution_payload_json->>'relevant_erni_pct', v_component.saved_resolution_result_json->>'relevant_erni_pct')::numeric, 6)
      ELSE round(v_finance_settings.erni_pct, 6)
    END;

    v_vat_rate_pct := CASE
      WHEN coalesce(v_resolution_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'vat_rate_pct')::numeric, 6)
      WHEN coalesce(v_component.saved_resolution_payload_json->>'vat_rate_pct', v_component.saved_resolution_result_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round(coalesce(v_component.saved_resolution_payload_json->>'vat_rate_pct', v_component.saved_resolution_result_json->>'vat_rate_pct')::numeric, 6)
      ELSE round(v_finance_settings.vat_rate_pct, 6)
    END;

    v_umbrella_vat_chargeable := coalesce(
      CASE
        WHEN lower(coalesce(v_resolution_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_resolution_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.saved_resolution_result_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.saved_resolution_result_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.source_basis_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.source_basis_json->>'vat_chargeable')::boolean
        ELSE NULL
      END,
      false
    );

    v_target_units := CASE
      WHEN coalesce(v_resolution_json->>'target_units', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_units')::numeric, 6)
      ELSE NULL
    END;
    v_requested_target_units := v_target_units;

    v_manual_replacement_rate := CASE
      WHEN coalesce(v_resolution_json->>'replacement_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'replacement_rate')::numeric, 6)
      WHEN coalesce(v_resolution_json->>'manual_replacement_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'manual_replacement_rate')::numeric, 6)
      ELSE NULL
    END;

    v_manual_amount_ex_vat := CASE
      WHEN coalesce(v_resolution_json->>'target_amount_ex_vat', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_amount_ex_vat')::numeric, 2)
      WHEN coalesce(v_resolution_json->>'target_amount', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_amount')::numeric, 2)
      WHEN coalesce(v_resolution_json->>'manual_amount_ex_vat', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'manual_amount_ex_vat')::numeric, 2)
      ELSE NULL
    END;

    IF v_is_rate_bearing_row AND v_resolution_mode = 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'MANUAL_AMOUNT_NOT_ALLOWED_FOR_RATE_BEARING_COMPONENT',
        'message', 'pay_finance_component_resolutions_apply: MANUAL_AMOUNT is not allowed for genuine rate-bearing taxable rows',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'component_semantics', v_component_semantics
      )::text;
    END IF;

    IF v_is_amount_led_row AND v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'MANUAL_REPLACEMENT_RATE_NOT_ALLOWED_FOR_AMOUNT_LED_COMPONENT',
        'message', 'pay_finance_component_resolutions_apply: MANUAL_REPLACEMENT_RATE is only allowed for genuine rate-bearing taxable rows',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'component_semantics', v_component_semantics
      )::text;
    END IF;

    IF v_is_rate_bearing_row THEN
      IF v_target_units IS NULL THEN
        v_target_units := round(v_source_units, 6);
      END IF;

      IF round(coalesce(v_target_units, 0), 6) <> round(coalesce(v_source_units, 0), 6) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'RATE_BEARING_TARGET_UNITS_MISMATCH',
          'message', 'pay_finance_component_resolutions_apply: rate-bearing rows must preserve exact source units',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'source_units', v_source_units,
          'target_units', v_target_units
        )::text;
      END IF;
    ELSE
      v_target_units := NULL;
    END IF;

    v_target_amount_ex_vat := null;
    v_target_amount_vat := null;
    v_target_amount_inc_vat := null;
    v_target_amounts_json := '{}'::jsonb;
    v_target_basis_json := '{}'::jsonb;
    v_resolution_payload_json := '{}'::jsonb;
    v_resolution_result_json := '{}'::jsonb;
    v_resolution_fingerprint := null;
    v_target_amount_ex_vat_per_source := 0;
    v_target_amount_vat_per_source := 0;
    v_target_amount_inc_vat_per_source := 0;
    v_target_units_per_source := null;

    v_before_json := jsonb_build_object(
      'finance_component_id', v_component.id::text,
      'finance_case_id', v_component.finance_case_id::text,
      'classification', v_component.classification::text,
      'source_pay_method', v_component.source_pay_method,
      'source_basis_json', v_component.source_basis_json,
      'source_amount', round(coalesce(v_component.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_component.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_component.saved_resolution_mode IS NULL THEN NULL ELSE v_component.saved_resolution_mode::text END,
      'saved_resolution_payload_json', v_component.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component.saved_resolution_result_json,
      'source_units', v_source_units,
      'source_rate', v_source_rate,
      'source_charge_rate', v_source_charge_rate,
      'bucket_code', v_bucket_code,
      'component_semantics', v_component_semantics,
      'is_rate_bearing_row', v_is_rate_bearing_row,
      'is_amount_led_row', v_is_amount_led_row,
      'resolution_fingerprint', v_component.resolution_fingerprint,
      'is_resolution_stale', v_component.is_resolution_stale,
      'stale_reason', v_component.stale_reason,
      'resolved_at_utc', v_component.resolved_at_utc
    );

    IF v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN
      IF v_component.source_pay_method = 'PAYE' AND v_target_pay_method = 'UMBRELLA' THEN
        v_target_amounts_json := public._pay_convert_paye_to_umbrella(
          v_basis_amount_ex_vat,
          v_relevant_erni_pct,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      ELSIF v_component.source_pay_method = 'UMBRELLA' AND v_target_pay_method = 'PAYE' THEN
        v_target_amount_ex_vat := public._pay_convert_umbrella_to_paye_ex(v_basis_amount_ex_vat, v_relevant_erni_pct);
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSIF v_component.source_pay_method = v_target_pay_method AND v_target_pay_method = 'PAYE' THEN
        v_target_amount_ex_vat := v_basis_amount_ex_vat;
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSIF v_component.source_pay_method = v_target_pay_method AND v_target_pay_method = 'UMBRELLA' THEN
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_basis_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'UNSUPPORTED_SUGGESTED_CONVERSION',
          'message', 'pay_finance_component_resolutions_apply: unsupported suggested-equivalent conversion pair',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'source_pay_method', v_component.source_pay_method,
          'target_pay_method', v_target_pay_method
        )::text;
      END IF;

      IF v_target_units IS NOT NULL THEN
        IF v_target_units <= 0 THEN
          RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
            'code', 'TARGET_UNITS_INVALID',
            'message', 'pay_finance_component_resolutions_apply: target_units must be > 0 when provided for suggested equivalent basis',
            'row_index', v_row_seq,
            'finance_component_id', v_component.id::text,
            'target_units', v_target_units
          )::text;
        END IF;
        v_rate_precision := round(v_target_amount_ex_vat / v_target_units, 6);
      ELSE
        v_rate_precision := null;
      END IF;
    ELSIF v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN
      IF v_target_units IS NULL OR v_target_units <= 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'TARGET_UNITS_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: target_units must be > 0 for MANUAL_REPLACEMENT_RATE',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'target_units', v_target_units
        )::text;
      END IF;

      IF v_manual_replacement_rate IS NULL OR v_manual_replacement_rate < 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'REPLACEMENT_RATE_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: replacement_rate must be >= 0 for MANUAL_REPLACEMENT_RATE',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'replacement_rate', v_manual_replacement_rate
        )::text;
      END IF;

      v_target_amount_ex_vat := round(v_target_units * v_manual_replacement_rate, 2);

      IF v_target_pay_method = 'PAYE' THEN
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSE
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_target_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      END IF;

      v_rate_precision := round(v_manual_replacement_rate, 6);
    ELSE
      IF v_manual_amount_ex_vat IS NULL OR v_manual_amount_ex_vat < 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'TARGET_AMOUNT_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: target_amount_ex_vat must be >= 0 for MANUAL_AMOUNT',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'target_amount_ex_vat', v_manual_amount_ex_vat
        )::text;
      END IF;

      v_target_amount_ex_vat := round(v_manual_amount_ex_vat, 2);

      IF v_target_pay_method = 'PAYE' THEN
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSE
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_target_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      END IF;

      v_rate_precision := null;
    END IF;

    IF v_basis_amount_ex_vat <= 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'BASIS_AMOUNT_INVALID',
        'message', 'pay_finance_component_resolutions_apply: basis_source_amount_ex_vat must be > 0',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'basis_source_amount_ex_vat', v_basis_amount_ex_vat
      )::text;
    END IF;

    v_target_amount_ex_vat_per_source := round(v_target_amount_ex_vat / v_basis_amount_ex_vat, 10);
    v_target_amount_vat_per_source := round(v_target_amount_vat / v_basis_amount_ex_vat, 10);
    v_target_amount_inc_vat_per_source := round(v_target_amount_inc_vat / v_basis_amount_ex_vat, 10);
    v_target_units_per_source := CASE
      WHEN v_target_units IS NOT NULL THEN round(v_target_units / v_basis_amount_ex_vat, 10)
      ELSE NULL
    END;

    v_target_basis_json := jsonb_strip_nulls(
      jsonb_build_object(
        'target_pay_method', v_target_pay_method,
        'calculation_kind', v_resolution_mode::text,
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'replacement_rate', CASE WHEN v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN round(v_manual_replacement_rate, 6) ELSE NULL END,
        'target_amount_ex_vat_per_source_ex_vat', v_target_amount_ex_vat_per_source,
        'target_amount_vat_per_source_ex_vat', v_target_amount_vat_per_source,
        'target_amount_inc_vat_per_source_ex_vat', v_target_amount_inc_vat_per_source,
        'target_units_per_source_ex_vat', v_target_units_per_source,
        'suggested_target_rate', CASE WHEN v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN v_rate_precision ELSE NULL END
      )
    );

    v_resolution_payload_json := jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_mode', v_resolution_mode::text,
        'target_pay_method', v_target_pay_method,
        'applied_basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'requested_target_units', CASE WHEN v_requested_target_units IS NULL THEN NULL ELSE round(v_requested_target_units, 6) END,
        'target_units', CASE WHEN v_target_units IS NULL THEN NULL ELSE round(v_target_units, 6) END,
        'replacement_rate', CASE WHEN v_manual_replacement_rate IS NULL THEN NULL ELSE round(v_manual_replacement_rate, 6) END,
        'manual_amount_ex_vat', CASE WHEN v_manual_amount_ex_vat IS NULL THEN NULL ELSE round(v_manual_amount_ex_vat, 2) END,
        'suggested_target_rate', CASE WHEN v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN v_rate_precision ELSE NULL END,
        'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
      )
    );

    v_resolution_result_json := jsonb_strip_nulls(
      jsonb_build_object(
        'target_pay_method', v_target_pay_method,
        'target_amount_ex_vat', round(v_target_amount_ex_vat, 2),
        'target_amount_vat', round(v_target_amount_vat, 2),
        'target_amount_inc_vat', round(v_target_amount_inc_vat, 2),
        'basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'applied_basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'requested_target_units', CASE WHEN v_requested_target_units IS NULL THEN NULL ELSE round(v_requested_target_units, 6) END,
        'target_units', CASE WHEN v_target_units IS NULL THEN NULL ELSE round(v_target_units, 6) END,
        'replacement_rate', CASE WHEN v_manual_replacement_rate IS NULL THEN NULL ELSE round(v_manual_replacement_rate, 6) END,
        'target_amount_ex_vat_per_source_ex_vat', v_target_amount_ex_vat_per_source,
        'target_amount_vat_per_source_ex_vat', v_target_amount_vat_per_source,
        'target_amount_inc_vat_per_source_ex_vat', v_target_amount_inc_vat_per_source,
        'target_units_per_source_ex_vat', v_target_units_per_source,
        'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
      )
    );

    v_resolution_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => v_component.source_family_key,
      p_component_key_type        => v_component.component_key_type,
      p_component_key_value       => v_component.component_key_value,
      p_classification            => v_component.classification,
      p_source_pay_method         => v_component.source_pay_method,
      p_current_target_pay_method => v_target_pay_method,
      p_source_basis_json         => coalesce(v_component.source_basis_json, '{}'::jsonb),
      p_source_amount             => round(coalesce(v_component.source_amount, 0), 2),
      p_relevant_erni_pct         => round(v_relevant_erni_pct, 6),
      p_target_basis_json         => v_target_basis_json
    );

    UPDATE public.pay_finance_case_components pfc
    SET
      saved_target_pay_method = v_target_pay_method,
      saved_resolution_mode = v_resolution_mode,
      saved_resolution_payload_json = v_resolution_payload_json,
      saved_resolution_result_json = v_resolution_result_json,
      resolution_fingerprint = v_resolution_fingerprint,
      resolved_at_utc = v_now_utc,
      is_resolution_stale = false,
      stale_reason = NULL,
      updated_at_utc = v_now_utc
    WHERE pfc.id = v_component.id;

    SELECT jsonb_build_object(
      'finance_component_id', pfc.id::text,
      'finance_case_id', pfc.finance_case_id::text,
      'classification', pfc.classification::text,
      'source_pay_method', pfc.source_pay_method,
      'source_basis_json', pfc.source_basis_json,
      'source_amount', round(coalesce(pfc.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
      'saved_target_pay_method', pfc.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
      'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
      'saved_resolution_result_json', pfc.saved_resolution_result_json,
      'source_units', v_source_units,
      'source_rate', v_source_rate,
      'source_charge_rate', v_source_charge_rate,
      'bucket_code', v_bucket_code,
      'component_semantics', v_component_semantics,
      'is_rate_bearing_row', v_is_rate_bearing_row,
      'is_amount_led_row', v_is_amount_led_row,
      'resolution_fingerprint', pfc.resolution_fingerprint,
      'is_resolution_stale', pfc.is_resolution_stale,
      'stale_reason', pfc.stale_reason,
      'resolved_at_utc', pfc.resolved_at_utc
    )
    INTO v_after_json
    FROM public.pay_finance_case_components pfc
    WHERE pfc.id = v_component.id;

    v_event_reason := coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'COMPONENT_RESOLUTION_APPLIED');

    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_component.finance_case_id,
      v_component.id,
      'COMPONENT_RESOLUTION_APPLIED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      v_before_json,
      v_after_json,
      v_event_reason,
      ('Applied ' || v_resolution_mode::text || ' to taxable finance component')
    );

    v_applied_components := v_applied_components || jsonb_build_array(
      jsonb_build_object(
        'finance_component_id', v_component.id::text,
        'finance_case_id', v_component.finance_case_id::text,
        'saved_target_pay_method', v_target_pay_method,
        'saved_resolution_mode', v_resolution_mode::text,
        'saved_resolution_payload_json', v_resolution_payload_json,
        'saved_resolution_result_json', v_resolution_result_json,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'bucket_code', v_bucket_code,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'resolution_fingerprint', v_resolution_fingerprint,
        'resolved_at_utc', v_now_utc
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'candidate_id', p_candidate_id::text,
    'finance_case_id', CASE WHEN p_finance_case_id IS NULL THEN NULL ELSE p_finance_case_id::text END,
    'applied_count', jsonb_array_length(v_applied_components),
    'components', v_applied_components
  );
END;
$function$;

-- pay_finance_components_sync_from_preview(uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.pay_finance_components_sync_from_preview(p_finance_case_id uuid, p_preview_lines_json jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_case_candidate_id uuid;
  v_case_client_id uuid;
  v_case_linked_timesheet_id uuid;
  v_case_current_pay_method text;
  v_case_type public.pay_finance_case_type_enum;
  v_case_outstanding_amount numeric(12,2) := 0;

  v_input_json jsonb := coalesce(p_preview_lines_json, '[]'::jsonb);
  v_line_json jsonb;
  v_row_seq integer := 0;

  v_source_family_key text;
  v_component_key_type text;
  v_component_key_value text;
  v_raw_key_type text;
  v_raw_key_value text;
  v_raw_classification text;
  v_raw_item_type text;
  v_raw_source_ref text;
  v_raw_expense_kind text;
  v_source_pay_method text;
  v_current_target_pay_method text;

  v_source_amount_text text;
  v_remaining_amount_text text;
  v_relevant_erni_text text;
  v_allocation_group_text text;
  v_allocation_order_text text;

  v_source_amount numeric(12,2);
  v_incoming_remaining_source_amount numeric(12,2);
  v_incoming_remaining_is_explicit boolean;
  v_relevant_erni_pct numeric;
  v_allocation_priority_group integer;
  v_allocation_priority_order integer;

  v_source_basis_json jsonb;
  v_target_basis_json jsonb;
  v_current_basis_fingerprint text;
  v_classification public.pay_finance_component_classification_enum;

  v_line_candidate_id uuid;
  v_line_client_id uuid;
  v_line_linked_timesheet_id uuid;
  v_line_classification public.pay_finance_component_classification_enum;
  v_line_source_amount numeric(12,2);
  v_line_incoming_remaining_source_amount numeric(12,2);
  v_line_allocation_priority_group integer;
  v_line_allocation_priority_order integer;
  v_line_source_basis_json jsonb;
  v_line_current_target_pay_method text;
  v_line_source_pay_method text;

  v_existing_component public.pay_finance_case_components%ROWTYPE;
  v_reopen_component public.pay_finance_case_components%ROWTYPE;
  v_component_after public.pay_finance_case_components%ROWTYPE;

  v_before_json jsonb;
  v_after_json jsonb;

  v_has_saved_resolution boolean;
  v_should_be_stale boolean;
  v_stale_reason text;
  v_consumed_amount numeric(12,2);
  v_new_remaining_source_amount numeric(12,2);
  v_created_component_id uuid;

  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_reopened_count integer := 0;
  v_closed_count integer := 0;
  v_stale_marked_count integer := 0;

  v_open_components_json jsonb := '[]'::jsonb;

  v_case_status text;
  v_case_written_off_at_utc timestamptz;
  v_case_cleared_at_utc timestamptz;
  v_case_has_protected_event boolean := false;
  v_case_is_preview_auto_clear boolean := false;
  v_case_is_protected boolean := false;
  v_protected_skip_count integer := 0;

  v_component_has_protected_event boolean := false;
  v_component_is_protected boolean := false;
  v_active_consumed_amount numeric(12,2);
  v_active_reserved_source_amount numeric(12,2) := 0;
  v_identity_consumed_amount numeric(12,2);
  v_identity_reserved_source_amount numeric(12,2);
  v_case_active_consumed_amount numeric(12,2) := 0;
  v_case_active_reserved_source_amount numeric(12,2) := 0;
  v_raw_input_component_count integer := 0;
  v_input_component_count integer := 0;
  v_aggregated_duplicate_identity_count integer := 0;
  v_open_component_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_effective_source_amount numeric(12,2) := 0;
  v_active_reservation_deferred_count integer := 0;

  v_accepted_resolution_json jsonb;
  v_line_accepted_resolution_json jsonb;
  v_accepted_resolution_fingerprint text;
  v_resolution_target_ratio numeric := NULL;
  v_resolution_vat_ratio numeric := NULL;
  v_resolution_inc_ratio numeric := NULL;
  v_upstream_correction_resolution_applied boolean := false;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION 'p_finance_case_id is required';
  END IF;

  IF jsonb_typeof(v_input_json) <> 'array' THEN
    RAISE EXCEPTION 'p_preview_lines_json must be a jsonb array';
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_START',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'preview_line_count', jsonb_array_length(v_input_json),
      'actor_user_id', p_actor_user_id
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  SELECT
    pa.candidate_id,
    pa.client_id,
    pa.linked_timesheet_id,
    upper(coalesce(c.pay_method, '')),
    pa.case_type,
    round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
    upper(coalesce(pa.status::text, '')),
    pa.written_off_at_utc,
    pa.cleared_at_utc
  INTO
    v_case_candidate_id,
    v_case_client_id,
    v_case_linked_timesheet_id,
    v_case_current_pay_method,
    v_case_type,
    v_case_outstanding_amount,
    v_case_status,
    v_case_written_off_at_utc,
    v_case_cleared_at_utc
  FROM public.pay_advances pa
  JOIN public.candidates c
    ON c.id = pa.candidate_id
  WHERE pa.id = p_finance_case_id
  FOR UPDATE OF pa;

  IF v_case_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Finance case % not found in public.pay_advances', p_finance_case_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_finance_case_events AS protected_case_events
    WHERE protected_case_events.finance_case_id = p_finance_case_id
      AND (
        upper(btrim(coalesce(protected_case_events.event_type, ''))) LIKE '%WRITE%OFF%'
        OR upper(btrim(coalesce(protected_case_events.event_type, ''))) IN (
          'MANUAL_ECONOMIC_OVERRIDE',
          'MANUAL_WRITE_OFF',
          'CASE_MANUAL_ECONOMIC_OVERRIDE',
          'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
        )
        OR upper(btrim(coalesce(protected_case_events.reason, ''))) IN (
          'MANUAL_ECONOMIC_OVERRIDE',
          'WRITE_OFF',
          'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
        )
      )
  )
  INTO v_case_has_protected_event;

  SELECT COALESCE((
    SELECT
      upper(btrim(coalesce(latest_case_event.event_type, ''))) = 'CLEARED'
      AND upper(btrim(coalesce(latest_case_event.reason, ''))) = 'PREVIEW_FINANCE_SYNC'
    FROM public.pay_finance_case_events AS latest_case_event
    WHERE latest_case_event.finance_case_id = p_finance_case_id
    ORDER BY latest_case_event.event_at_utc DESC, latest_case_event.id DESC
    LIMIT 1
  ), false)
  INTO v_case_is_preview_auto_clear;

  v_case_is_protected := (
    v_case_written_off_at_utc IS NOT NULL
    OR (
      v_case_cleared_at_utc IS NOT NULL
      AND NOT (
        coalesce(v_case_is_preview_auto_clear, false)
        AND jsonb_array_length(v_input_json) = 0
        AND coalesce(v_case_status, '') = 'PAID_OFF'
        AND round(coalesce(v_case_outstanding_amount, 0), 2) = 0
      )
    )
    OR coalesce(v_case_status, '') NOT IN ('ACTIVE', 'PAUSED', 'PAID_OFF')
    OR coalesce(v_case_has_protected_event, false)
  );

  IF v_case_is_protected THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      NULL,
      'SYNC_SKIPPED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      jsonb_build_object(
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event,
        'is_preview_auto_clear', v_case_is_preview_auto_clear
      ),
      jsonb_build_object(
        'sync_skipped', true,
        'reason', 'PROTECTED_FINANCE_CASE'
      ),
      'COMPONENT_SYNC_SKIPPED_PROTECTED_CASE',
      'Skipped component sync because the finance case is written-off, cleared, closed, manually resolved, or already restructured.'
    );

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_SKIPPED_PROTECTED_CASE',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event,
        'is_preview_auto_clear', v_case_is_preview_auto_clear
      ),
      'pay_finance_components',
      p_finance_case_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'skipped', true,
      'skip_reason', 'PROTECTED_FINANCE_CASE',
      'inserted_count', 0,
      'updated_count', 0,
      'reopened_count', 0,
      'closed_count', 0,
      'stale_marked_count', 0,
      'open_components', (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', pfc.id::text,
              'finance_case_id', pfc.finance_case_id::text,
              'candidate_id', pfc.candidate_id::text,
              'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
              'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
              'source_family_key', pfc.source_family_key,
              'component_key_type', pfc.component_key_type,
              'component_key_value', pfc.component_key_value,
              'classification', pfc.classification::text,
              'source_pay_method', pfc.source_pay_method,
              'source_amount', round(coalesce(pfc.source_amount, 0), 2),
              'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
              'saved_target_pay_method', pfc.saved_target_pay_method,
              'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
              'is_resolution_stale', pfc.is_resolution_stale,
              'stale_reason', pfc.stale_reason,
              'allocation_priority_group', pfc.allocation_priority_group,
              'allocation_priority_order', pfc.allocation_priority_order,
              'created_at_utc', pfc.created_at_utc,
              'updated_at_utc', pfc.updated_at_utc
            )
            ORDER BY
              pfc.source_family_key,
              pfc.allocation_priority_group,
              pfc.allocation_priority_order,
              pfc.component_key_type,
              pfc.component_key_value
          ),
          '[]'::jsonb
        )
        FROM public.pay_finance_case_components AS pfc
        WHERE pfc.finance_case_id = p_finance_case_id
          AND pfc.closed_at_utc IS NULL
      )
    );
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_sync_input (
    row_seq integer NOT NULL,
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    classification public.pay_finance_component_classification_enum NOT NULL,
    candidate_id uuid NOT NULL,
    client_id uuid NULL,
    linked_timesheet_id uuid NULL,
    source_pay_method text NOT NULL,
    current_target_pay_method text NULL,
    source_basis_json jsonb NOT NULL,
    target_basis_json jsonb NULL,
    accepted_resolution_json jsonb NULL,
    source_amount numeric(12,2) NOT NULL,
    incoming_remaining_source_amount numeric(12,2) NULL,
    incoming_remaining_is_explicit boolean NOT NULL,
    relevant_erni_pct numeric NULL,
    allocation_priority_group integer NOT NULL,
    allocation_priority_order integer NOT NULL,
    current_basis_fingerprint text NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_input;

  FOR v_line_json IN
    SELECT x.value
    FROM jsonb_array_elements(v_input_json) AS x(value)
  LOOP
    v_row_seq := v_row_seq + 1;

    IF v_line_json IS NULL OR jsonb_typeof(v_line_json) <> 'object' THEN
      RAISE EXCEPTION 'Each preview line must be a jsonb object (row %)', v_row_seq;
    END IF;

    v_raw_key_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'component_key_type'), ''),
        nullif(btrim(v_line_json->>'frozen_component_key_type'), ''),
        nullif(btrim(v_line_json->>'key_type'), ''),
        ''
      )
    );

    v_raw_key_value := coalesce(
      nullif(btrim(v_line_json->>'component_key_value'), ''),
      nullif(btrim(v_line_json->>'frozen_component_key_value'), ''),
      nullif(btrim(v_line_json->>'key_value'), ''),
      ''
    );

    v_raw_classification := upper(
      coalesce(
        nullif(btrim(v_line_json->>'classification'), ''),
        nullif(btrim(v_line_json->>'component_classification'), ''),
        ''
      )
    );

    v_raw_item_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'item_type'), ''),
        nullif(btrim(v_line_json->>'line_type'), ''),
        ''
      )
    );

    v_raw_source_ref := upper(coalesce(nullif(btrim(v_line_json->>'source_ref'), ''), ''));
    v_raw_expense_kind := upper(
      coalesce(
        nullif(btrim(v_line_json->>'expense_kind'), ''),
        nullif(btrim(v_line_json->>'expense_code'), ''),
        nullif(btrim(v_line_json->>'expense_type'), ''),
        ''
      )
    );

    v_component_key_type := NULL;
    v_component_key_value := NULL;

    IF v_raw_key_type <> '' THEN
      v_component_key_type := v_raw_key_type;
    ELSIF v_raw_item_type = 'SEGMENT_DELTA' THEN
      IF coalesce(nullif(btrim(v_line_json->>'work_date'), ''), nullif(btrim(v_line_json->>'date'), '')) ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_component_key_type := 'TS_DAY';
      ELSE
        v_component_key_type := 'TS_TOTAL';
      END IF;
    ELSIF v_raw_item_type = 'ADDITIONAL_DELTA'
       OR nullif(btrim(v_line_json->>'additional_code'), '') IS NOT NULL THEN
      v_component_key_type := 'ADDITIONAL_CODE';
    ELSIF v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA', 'EXPENSE_DELTA')
       OR v_raw_expense_kind <> '' THEN
      v_component_key_type := 'EXPENSE_CODE';
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
      IF v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
        v_component_key_type := 'TS_TOTAL';
      ELSE
        v_component_key_type := 'EXPENSE_CODE';
      END IF;
    ELSE
      v_component_key_type := 'CASE_TOTAL';
    END IF;

    IF v_raw_key_value <> '' THEN
      v_component_key_value := v_raw_key_value;
    ELSIF v_component_key_type = 'TS_DAY' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'work_date'), ''),
        nullif(btrim(v_line_json->>'date'), ''),
        'UNKNOWN_DAY'
      );
    ELSIF v_component_key_type = 'TS_TOTAL' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'segment_id'), ''),
        CASE
          WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NULL THEN 'TOTAL'
          ELSE coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        END
      );
    ELSIF v_component_key_type = 'ADDITIONAL_CODE' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'additional_code'), ''),
        nullif(btrim(v_line_json->>'source_ref'), ''),
        nullif(btrim(v_line_json->>'code'), ''),
        'TOTAL'
      );
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'adjustment_code'), ''),
          nullif(btrim(v_line_json->>'adjustment_id'), ''),
          nullif(btrim(v_line_json->>'source_ref'), ''),
          'ADJUSTMENT'
        );
      ELSE
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'expense_code'), ''),
          nullif(btrim(v_line_json->>'expense_kind'), ''),
          nullif(btrim(v_line_json->>'expense_type'), ''),
          nullif(btrim(v_line_json->>'item_type'), ''),
          'EXPENSE'
        );
      END IF;
    ELSE
      v_component_key_value := 'TOTAL';
    END IF;

    IF v_raw_classification IN ('TAXABLE_CHANNEL_SENSITIVE', 'REIMBURSEMENT_GROSS_FIXED', 'NET_PAY_FIXED_RECOVERY') THEN
      v_classification := v_raw_classification::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type IN ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'CASE_TOTAL') THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA'
       OR v_raw_source_ref LIKE 'ADJ:%'
       OR v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF upper(v_component_key_value) IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_expense_kind IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA')
         OR v_raw_source_ref LIKE 'MILEAGE:%'
         OR v_raw_source_ref LIKE 'TRAVEL:%'
         OR v_raw_source_ref LIKE 'ACCOMMODATION:%'
         OR v_raw_source_ref LIKE 'OTHER:%'
         OR v_raw_source_ref LIKE 'EXPENSE:%'
      THEN
        v_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
      ELSE
        v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
      END IF;
    ELSE
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    END IF;

    v_source_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'source_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_current_target_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'current_target_pay_method'), ''),
        nullif(btrim(v_line_json->>'target_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_source_amount_text := nullif(btrim(v_line_json->>'source_amount'), '');
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount_ex_vat'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      RAISE EXCEPTION 'Preview line % is missing source_amount/amount/amount_ex_vat', v_row_seq;
    END IF;
    IF v_source_amount_text !~ '^-?\d+(\.\d+)?$' THEN
      RAISE EXCEPTION 'Preview line % has invalid source amount: %', v_row_seq, v_source_amount_text;
    END IF;
    v_source_amount := round(abs(v_source_amount_text::numeric), 2)::numeric(12,2);

    v_remaining_amount_text := nullif(btrim(v_line_json->>'remaining_source_amount'), '');
    v_incoming_remaining_is_explicit := v_remaining_amount_text IS NOT NULL;
    IF v_incoming_remaining_is_explicit THEN
      IF v_remaining_amount_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid remaining_source_amount: %', v_row_seq, v_remaining_amount_text;
      END IF;
      v_incoming_remaining_source_amount := round(abs(v_remaining_amount_text::numeric), 2)::numeric(12,2);
    ELSE
      v_incoming_remaining_source_amount := NULL;
    END IF;

    v_relevant_erni_text := nullif(
      btrim(
        coalesce(
          v_line_json->>'relevant_erni_pct',
          v_line_json->>'erni_pct'
        )
      ),
      ''
    );
    IF v_relevant_erni_text IS NOT NULL THEN
      IF v_relevant_erni_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid relevant_erni_pct: %', v_row_seq, v_relevant_erni_text;
      END IF;
      v_relevant_erni_pct := round(v_relevant_erni_text::numeric, 6);
    ELSE
      v_relevant_erni_pct := NULL;
    END IF;

    v_allocation_group_text := nullif(btrim(v_line_json->>'allocation_priority_group'), '');
    IF v_allocation_group_text IS NOT NULL THEN
      IF v_allocation_group_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_group: %', v_row_seq, v_allocation_group_text;
      END IF;
      v_allocation_priority_group := v_allocation_group_text::integer;
    ELSE
      v_allocation_priority_group := CASE
        WHEN v_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN 0
        ELSE 1
      END;
    END IF;

    v_allocation_order_text := nullif(btrim(v_line_json->>'allocation_priority_order'), '');
    IF v_allocation_order_text IS NOT NULL THEN
      IF v_allocation_order_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_order: %', v_row_seq, v_allocation_order_text;
      END IF;
      v_allocation_priority_order := v_allocation_order_text::integer;
    ELSE
      v_allocation_priority_order := v_row_seq;
    END IF;

    IF v_line_json ? 'source_basis_json'
       AND jsonb_typeof(v_line_json->'source_basis_json') IN ('object', 'array') THEN
      v_source_basis_json := v_line_json->'source_basis_json';
    ELSE
      v_source_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'linked_timesheet_id', coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text),
          'work_date', nullif(btrim(v_line_json->>'work_date'), ''),
          'date', nullif(btrim(v_line_json->>'date'), ''),
          'segment_id', nullif(btrim(v_line_json->>'segment_id'), ''),
          'item_type', nullif(btrim(v_line_json->>'item_type'), ''),
          'line_type', nullif(btrim(v_line_json->>'line_type'), ''),
          'source_ref', nullif(btrim(v_line_json->>'source_ref'), ''),
          'additional_code', nullif(btrim(v_line_json->>'additional_code'), ''),
          'expense_code', nullif(btrim(v_line_json->>'expense_code'), ''),
          'expense_kind', nullif(btrim(v_line_json->>'expense_kind'), ''),
          'adjustment_code', nullif(btrim(v_line_json->>'adjustment_code'), ''),
          'rate_code', nullif(btrim(v_line_json->>'rate_code'), ''),
          'units', nullif(btrim(v_line_json->>'units'), ''),
          'hours', nullif(btrim(v_line_json->>'hours'), ''),
          'rate', nullif(btrim(v_line_json->>'rate'), '')
        )
      );
    END IF;

    IF v_line_json ? 'target_basis_json'
       AND jsonb_typeof(v_line_json->'target_basis_json') IN ('object', 'array') THEN
      v_target_basis_json := v_line_json->'target_basis_json';
    ELSE
      v_target_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'current_target_pay_method', v_current_target_pay_method,
          'relevant_erni_pct', v_relevant_erni_pct
        )
      );
    END IF;

    v_line_accepted_resolution_json := NULL;
    IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_resolution_json';
    ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
    ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
    END IF;

    v_source_family_key := coalesce(
      nullif(btrim(v_line_json->>'source_family_key'), ''),
      CASE
        WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NOT NULL
          THEN 'timesheet:' || coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        ELSE 'case:' || p_finance_case_id::text
      END
    );

    v_current_basis_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => v_source_family_key,
      p_component_key_type        => v_component_key_type,
      p_component_key_value       => v_component_key_value,
      p_classification            => v_classification,
      p_source_pay_method         => v_source_pay_method,
      p_current_target_pay_method => v_current_target_pay_method,
      p_source_basis_json         => v_source_basis_json,
      p_source_amount             => v_source_amount,
      p_relevant_erni_pct         => v_relevant_erni_pct,
      p_target_basis_json         => v_target_basis_json
    );

    v_line_candidate_id := coalesce(
      CASE
        WHEN nullif(btrim(v_line_json->>'candidate_id'), '') IS NULL THEN NULL
        ELSE (nullif(btrim(v_line_json->>'candidate_id'), ''))::uuid
      END,
      v_case_candidate_id
    );

    v_line_client_id := CASE
      WHEN nullif(btrim(v_line_json->>'client_id'), '') IS NULL THEN v_case_client_id
      ELSE (nullif(btrim(v_line_json->>'client_id'), ''))::uuid
    END;

    v_line_linked_timesheet_id := CASE
      WHEN nullif(btrim(v_line_json->>'linked_timesheet_id'), '') IS NULL THEN v_case_linked_timesheet_id
      ELSE (nullif(btrim(v_line_json->>'linked_timesheet_id'), ''))::uuid
    END;

    IF v_line_linked_timesheet_id IS NOT NULL OR v_source_family_key LIKE 'timesheet:%' THEN
      IF COALESCE(v_raw_key_type, '') = '' OR COALESCE(v_raw_key_value, '') = '' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_ECONOMIC_KEY_REQUIRED'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_ECONOMIC_KEY_REQUIRED',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'source_family_key', v_source_family_key,
                  'raw_component_key_type', v_raw_key_type,
                  'raw_component_key_value', v_raw_key_value,
                  'message', 'Linked timesheet finance components must carry an explicit canonical component_key_type/component_key_value.'
                )::text;
      END IF;

      IF v_component_key_type IS NULL
         OR v_component_key_value IS NULL
         OR v_component_key_type = 'CASE_TOTAL'
         OR v_component_key_value IN ('UNKNOWN_DAY', '') THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_INVALID_ECONOMIC_KEY'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_INVALID_ECONOMIC_KEY',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'source_family_key', v_source_family_key,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'Linked timesheet finance components must not fall back to CASE_TOTAL/TOTAL or an unknown bucket.'
                )::text;
      END IF;

      IF v_component_key_type = 'TS_DAY' AND v_component_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_TS_DAY_KEY_NOT_DATE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_TS_DAY_KEY_NOT_DATE',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'TS_DAY finance components must be keyed by YYYY-MM-DD work date, not by segment id or stable id.'
                )::text;
      END IF;

      IF v_component_key_type = 'TS_TOTAL' AND v_component_key_value IS DISTINCT FROM 'TOTAL' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_TS_TOTAL_KEY_NOT_TOTAL'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_TS_TOTAL_KEY_NOT_TOTAL',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'TS_TOTAL finance components must use TOTAL as the economic key value.'
                )::text;
      END IF;
    END IF;

    INSERT INTO pg_temp.tmp_pay_finance_component_sync_input (
      row_seq,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_pay_method,
      current_target_pay_method,
      source_basis_json,
      target_basis_json,
      accepted_resolution_json,
      source_amount,
      incoming_remaining_source_amount,
      incoming_remaining_is_explicit,
      relevant_erni_pct,
      allocation_priority_group,
      allocation_priority_order,
      current_basis_fingerprint
    )
    VALUES (
      v_row_seq,
      v_source_family_key,
      v_component_key_type,
      v_component_key_value,
      v_classification,
      v_line_candidate_id,
      v_line_client_id,
      v_line_linked_timesheet_id,
      v_source_pay_method,
      v_current_target_pay_method,
      v_source_basis_json,
      v_target_basis_json,
      v_line_accepted_resolution_json,
      v_source_amount,
      v_incoming_remaining_source_amount,
      v_incoming_remaining_is_explicit,
      v_relevant_erni_pct,
      v_allocation_priority_group,
      v_allocation_priority_order,
      v_current_basis_fingerprint
    );
  END LOOP;

  /* Policy X economic identity is source_family_key + component_key_type +
     component_key_value.  Preview production may legitimately emit several
     physical rows for one economic identity (for example DAY and NIGHT work
     buckets on the same TS_DAY date).  Normalise those physical rows into one
     component before settlement/reservation reconciliation.  Keeping only the
     last row would understate the component and make the case/component parity
     guard reject an otherwise valid case. */
  SELECT COUNT(*)::integer
  INTO v_raw_input_component_count
  FROM pg_temp.tmp_pay_finance_component_sync_input AS raw_input_count_rows;

  SELECT COUNT(*)::integer
  INTO v_aggregated_duplicate_identity_count
  FROM (
    SELECT
      duplicate_identity.source_family_key,
      duplicate_identity.component_key_type,
      duplicate_identity.component_key_value
    FROM pg_temp.tmp_pay_finance_component_sync_input AS duplicate_identity
    GROUP BY
      duplicate_identity.source_family_key,
      duplicate_identity.component_key_type,
      duplicate_identity.component_key_value
    HAVING COUNT(*) > 1
  ) AS duplicate_identity_count_rows;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_finance_component_sync_input AS conflicting_identity
    GROUP BY
      conflicting_identity.source_family_key,
      conflicting_identity.component_key_type,
      conflicting_identity.component_key_value
    HAVING COUNT(*) > 1
       AND (
         COUNT(DISTINCT conflicting_identity.candidate_id) > 1
         OR COUNT(DISTINCT (conflicting_identity.client_id IS NULL, conflicting_identity.client_id)) > 1
         OR COUNT(DISTINCT (conflicting_identity.linked_timesheet_id IS NULL, conflicting_identity.linked_timesheet_id)) > 1
         OR COUNT(DISTINCT conflicting_identity.classification::text) > 1
         OR COUNT(DISTINCT upper(btrim(conflicting_identity.source_pay_method))) > 1
         OR COUNT(DISTINCT (conflicting_identity.current_target_pay_method IS NULL, upper(btrim(conflicting_identity.current_target_pay_method)))) > 1
         OR COUNT(DISTINCT (conflicting_identity.relevant_erni_pct IS NULL, conflicting_identity.relevant_erni_pct)) > 1
         OR BOOL_OR(conflicting_identity.incoming_remaining_is_explicit)
              IS DISTINCT FROM BOOL_AND(conflicting_identity.incoming_remaining_is_explicit)
         OR (
           COUNT(*) FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) > 0
           AND COUNT(*) FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) < COUNT(*)
         )
         OR COUNT(DISTINCT conflicting_identity.accepted_resolution_json)
              FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) > 1
       )
  ) THEN
    RAISE EXCEPTION 'PAY_FINANCE_COMPONENTS_DUPLICATE_IDENTITY_CONFLICT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_FINANCE_COMPONENTS_DUPLICATE_IDENTITY_CONFLICT',
              'finance_case_id', p_finance_case_id::text,
              'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
              'duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0),
              'message', 'Rows sharing one Policy X economic identity must agree on candidate, client, linked Timesheet, classification, route, ERNI basis, remaining-amount mode, and accepted resolution.'
            )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_sync_normalized
    (LIKE pg_temp.tmp_pay_finance_component_sync_input INCLUDING ALL)
    ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_normalized;

  INSERT INTO pg_temp.tmp_pay_finance_component_sync_normalized (
    row_seq,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_pay_method,
    current_target_pay_method,
    source_basis_json,
    target_basis_json,
    accepted_resolution_json,
    source_amount,
    incoming_remaining_source_amount,
    incoming_remaining_is_explicit,
    relevant_erni_pct,
    allocation_priority_group,
    allocation_priority_order,
    current_basis_fingerprint
  )
  WITH grouped_input AS (
    SELECT
      MIN(input_row.row_seq)::integer AS row_seq,
      input_row.source_family_key,
      input_row.component_key_type,
      input_row.component_key_value,
      (ARRAY_AGG(input_row.classification ORDER BY input_row.row_seq))[1] AS classification,
      (ARRAY_AGG(input_row.candidate_id ORDER BY input_row.row_seq))[1] AS candidate_id,
      (ARRAY_AGG(input_row.client_id ORDER BY input_row.row_seq))[1] AS client_id,
      (ARRAY_AGG(input_row.linked_timesheet_id ORDER BY input_row.row_seq))[1] AS linked_timesheet_id,
      (ARRAY_AGG(input_row.source_pay_method ORDER BY input_row.row_seq))[1] AS source_pay_method,
      (ARRAY_AGG(input_row.current_target_pay_method ORDER BY input_row.row_seq))[1] AS current_target_pay_method,
      (ARRAY_AGG(input_row.source_basis_json ORDER BY input_row.row_seq))[1] AS first_source_basis_json,
      (ARRAY_AGG(input_row.target_basis_json ORDER BY input_row.row_seq))[1] AS first_target_basis_json,
      (ARRAY_AGG(input_row.accepted_resolution_json ORDER BY input_row.row_seq))[1] AS accepted_resolution_json,
      ROUND(SUM(input_row.source_amount), 2)::numeric(12,2) AS source_amount,
      CASE
        WHEN BOOL_AND(input_row.incoming_remaining_is_explicit)
          THEN ROUND(SUM(COALESCE(input_row.incoming_remaining_source_amount, 0)), 2)::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS incoming_remaining_source_amount,
      BOOL_AND(input_row.incoming_remaining_is_explicit) AS incoming_remaining_is_explicit,
      (ARRAY_AGG(input_row.relevant_erni_pct ORDER BY input_row.row_seq))[1] AS relevant_erni_pct,
      MIN(input_row.allocation_priority_group)::integer AS allocation_priority_group,
      MIN(input_row.allocation_priority_order)::integer AS allocation_priority_order,
      COUNT(*)::integer AS physical_row_count,
      COUNT(DISTINCT COALESCE(input_row.target_basis_json, 'null'::jsonb))::integer AS target_basis_distinct_count,
      JSONB_AGG(
        jsonb_build_object(
          'source_amount', input_row.source_amount,
          'source_basis_json', input_row.source_basis_json,
          'target_basis_json', input_row.target_basis_json
        )
        ORDER BY input_row.source_basis_json::text, input_row.target_basis_json::text, input_row.source_amount, input_row.row_seq
      ) AS physical_basis_rows,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_units', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_units_count,
      ROUND(SUM(
        CASE
          WHEN jsonb_typeof(input_row.source_basis_json) = 'object'
           AND COALESCE(input_row.source_basis_json->>'source_units', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (input_row.source_basis_json->>'source_units')::numeric
          ELSE 0::numeric
        END
      ), 6) AS source_units_sum,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_rate_count,
      COUNT(DISTINCT ROUND((input_row.source_basis_json->>'source_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_rate_distinct_count,
      MAX(ROUND((input_row.source_basis_json->>'source_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      ) AS common_source_rate,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_charge_rate_count,
      COUNT(DISTINCT ROUND((input_row.source_basis_json->>'source_charge_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_charge_rate_distinct_count,
      MAX(ROUND((input_row.source_basis_json->>'source_charge_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      ) AS common_source_charge_rate,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      )::integer AS bucket_code_count,
      COUNT(DISTINCT NULLIF(upper(btrim(input_row.source_basis_json->>'bucket_code')), '')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      )::integer AS bucket_code_distinct_count,
      MAX(NULLIF(upper(btrim(input_row.source_basis_json->>'bucket_code')), '')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      ) AS common_bucket_code,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      )::integer AS umbrella_vat_count,
      COUNT(DISTINCT lower(input_row.source_basis_json->>'umbrella_vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      )::integer AS umbrella_vat_distinct_count,
      MAX(lower(input_row.source_basis_json->>'umbrella_vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      ) AS common_umbrella_vat_chargeable,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      )::integer AS vat_chargeable_count,
      COUNT(DISTINCT lower(input_row.source_basis_json->>'vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      )::integer AS vat_chargeable_distinct_count,
      MAX(lower(input_row.source_basis_json->>'vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      ) AS common_vat_chargeable
    FROM pg_temp.tmp_pay_finance_component_sync_input AS input_row
    GROUP BY
      input_row.source_family_key,
      input_row.component_key_type,
      input_row.component_key_value
  ), normalized_basis AS (
    SELECT
      grouped_input.*,
      CASE
        WHEN grouped_input.physical_row_count = 1
          THEN grouped_input.first_source_basis_json
        ELSE jsonb_strip_nulls(
          jsonb_build_object(
            'aggregation_mode', 'POLICY_X_ECONOMIC_IDENTITY',
            'source_family_key', grouped_input.source_family_key,
            'component_key_type', grouped_input.component_key_type,
            'component_key_value', grouped_input.component_key_value,
            'candidate_id', grouped_input.candidate_id::text,
            'client_id', CASE WHEN grouped_input.client_id IS NULL THEN NULL ELSE grouped_input.client_id::text END,
            'linked_timesheet_id', CASE WHEN grouped_input.linked_timesheet_id IS NULL THEN NULL ELSE grouped_input.linked_timesheet_id::text END
          )
          || jsonb_build_object(
            'source_pay_method', grouped_input.source_pay_method,
            'current_target_pay_method', grouped_input.current_target_pay_method,
            'source_amount', grouped_input.source_amount,
            'work_date', CASE WHEN grouped_input.component_key_type = 'TS_DAY' THEN grouped_input.component_key_value ELSE NULL END,
            'physical_row_count', grouped_input.physical_row_count,
            'source_basis_rows', grouped_input.physical_basis_rows
          )
          || jsonb_build_object(
            'source_units', CASE
              WHEN grouped_input.source_units_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_distinct_count = 1
                THEN grouped_input.source_units_sum
              ELSE NULL
            END,
            'source_rate', CASE
              WHEN grouped_input.source_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_distinct_count = 1 THEN grouped_input.common_source_rate
              ELSE NULL
            END,
            'source_charge_rate', CASE
              WHEN grouped_input.source_charge_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_charge_rate_distinct_count = 1 THEN grouped_input.common_source_charge_rate
              ELSE NULL
            END,
            'bucket_code', CASE
              WHEN grouped_input.bucket_code_count = grouped_input.physical_row_count
               AND grouped_input.bucket_code_distinct_count = 1 THEN grouped_input.common_bucket_code
              ELSE NULL
            END,
            'umbrella_vat_chargeable', CASE
              WHEN grouped_input.umbrella_vat_count = grouped_input.physical_row_count
               AND grouped_input.umbrella_vat_distinct_count = 1 THEN grouped_input.common_umbrella_vat_chargeable::boolean
              ELSE NULL
            END,
            'vat_chargeable', CASE
              WHEN grouped_input.vat_chargeable_count = grouped_input.physical_row_count
               AND grouped_input.vat_chargeable_distinct_count = 1 THEN grouped_input.common_vat_chargeable::boolean
              ELSE NULL
            END
          )
        )
      END AS normalized_source_basis_json,
      CASE
        WHEN grouped_input.physical_row_count = 1
          THEN grouped_input.first_target_basis_json
        WHEN grouped_input.target_basis_distinct_count = 1
          THEN grouped_input.first_target_basis_json
        ELSE jsonb_strip_nulls(
          jsonb_build_object(
            'aggregation_mode', 'POLICY_X_ECONOMIC_IDENTITY',
            'current_target_pay_method', grouped_input.current_target_pay_method,
            'relevant_erni_pct', grouped_input.relevant_erni_pct,
            'physical_row_count', grouped_input.physical_row_count,
            'target_basis_rows', grouped_input.physical_basis_rows
          )
        )
      END AS normalized_target_basis_json
    FROM grouped_input
  )
  SELECT
    normalized_basis.row_seq,
    normalized_basis.source_family_key,
    normalized_basis.component_key_type,
    normalized_basis.component_key_value,
    normalized_basis.classification,
    normalized_basis.candidate_id,
    normalized_basis.client_id,
    normalized_basis.linked_timesheet_id,
    normalized_basis.source_pay_method,
    normalized_basis.current_target_pay_method,
    normalized_basis.normalized_source_basis_json,
    normalized_basis.normalized_target_basis_json,
    normalized_basis.accepted_resolution_json,
    normalized_basis.source_amount,
    normalized_basis.incoming_remaining_source_amount,
    normalized_basis.incoming_remaining_is_explicit,
    normalized_basis.relevant_erni_pct,
    normalized_basis.allocation_priority_group,
    normalized_basis.allocation_priority_order,
    public.pay_finance_component_fingerprint(
      p_source_family_key => normalized_basis.source_family_key,
      p_component_key_type => normalized_basis.component_key_type,
      p_component_key_value => normalized_basis.component_key_value,
      p_classification => normalized_basis.classification,
      p_source_pay_method => normalized_basis.source_pay_method,
      p_current_target_pay_method => normalized_basis.current_target_pay_method,
      p_source_basis_json => normalized_basis.normalized_source_basis_json,
      p_source_amount => normalized_basis.source_amount,
      p_relevant_erni_pct => normalized_basis.relevant_erni_pct,
      p_target_basis_json => normalized_basis.normalized_target_basis_json
    ) AS current_basis_fingerprint
  FROM normalized_basis;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_input;

  INSERT INTO pg_temp.tmp_pay_finance_component_sync_input
  SELECT normalized_input.*
  FROM pg_temp.tmp_pay_finance_component_sync_normalized AS normalized_input
  ORDER BY normalized_input.row_seq;

  SELECT COUNT(*)::integer
  INTO v_input_component_count
  FROM pg_temp.tmp_pay_finance_component_sync_input AS normalized_input_count_rows;

  /* Build the case-scoped frozen item/reservation set once using the existing
     finance_case_id, source_ref and pay_batch_item_id indexes.  All settlement
     and reservation reconciliation below joins this bounded set rather than
     repeatedly scanning unrelated historical batch items. */
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_case_item_scope (
    pay_batch_item_id uuid NOT NULL PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_case_item_scope;

  INSERT INTO pg_temp.tmp_pay_finance_case_item_scope (pay_batch_item_id)
  SELECT scoped_item.id
  FROM public.pay_batch_items AS scoped_item
  WHERE scoped_item.finance_case_id = p_finance_case_id
     OR scoped_item.source_ref IN (
       'advance:' || p_finance_case_id::text,
       'ADVANCE:' || p_finance_case_id::text
     )
  ON CONFLICT (pay_batch_item_id) DO NOTHING;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_case_reservation_scope (
    reservation_id uuid NOT NULL PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_case_reservation_scope;

  INSERT INTO pg_temp.tmp_pay_finance_case_reservation_scope (reservation_id)
  SELECT scoped_reservation.id
  FROM public.pay_advance_reservations AS scoped_reservation
  WHERE scoped_reservation.finance_case_id = p_finance_case_id
  ON CONFLICT (reservation_id) DO NOTHING;

  INSERT INTO pg_temp.tmp_pay_finance_case_item_scope (pay_batch_item_id)
  SELECT scoped_reservation.pay_batch_item_id
  FROM public.pay_advance_reservations AS scoped_reservation
  JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS scoped_reservation_id
    ON scoped_reservation_id.reservation_id = scoped_reservation.id
  WHERE scoped_reservation.pay_batch_item_id IS NOT NULL
  ON CONFLICT (pay_batch_item_id) DO NOTHING;

  INSERT INTO pg_temp.tmp_pay_finance_case_reservation_scope (reservation_id)
  SELECT scoped_reservation.id
  FROM public.pay_advance_reservations AS scoped_reservation
  JOIN pg_temp.tmp_pay_finance_case_item_scope AS scoped_item_id
    ON scoped_item_id.pay_batch_item_id = scoped_reservation.pay_batch_item_id
  ON CONFLICT (reservation_id) DO NOTHING;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id uuid NOT NULL PRIMARY KEY,
    active_consumed_source_amount numeric(12,2) NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_active_recovered;

  INSERT INTO pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id,
    active_consumed_source_amount
  )
  SELECT
    settled_component_amounts.finance_component_id,
    round(sum(settled_component_amounts.component_source_amount), 2)::numeric(12,2) AS active_consumed_source_amount
  FROM (
    SELECT
      coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) AS finance_component_id,
      abs(coalesce(
        public.pay_advance_reservations.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id),
        public.pay_batch_items.frozen_source_amount,
        public.pay_batch_items.amount_ex_vat,
        public.pay_batch_items.amount_inc_vat,
        public.pay_advance_reservations.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_batch_items
    JOIN pg_temp.tmp_pay_finance_case_item_scope AS settled_component_scope
      ON settled_component_scope.pay_batch_item_id = public.pay_batch_items.id
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    JOIN public.pay_batches
      ON public.pay_batches.id = public.pay_batch_candidates.pay_batch_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations
      ON public.pay_advance_reservations.pay_batch_item_id = public.pay_batch_items.id
    WHERE coalesce(public.pay_batch_items.is_voided, false) = false
      AND coalesce(public.pay_advance_reservations.finance_case_id, public.pay_batch_items.finance_case_id) = p_finance_case_id
      AND coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) IS NOT NULL
      AND (
        v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(public.pay_batch_items.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
      AND (
        upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
        OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
        OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_advance_reservations.status, ''))) = 'SETTLED'
        OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
      )
  ) AS settled_component_amounts
  WHERE settled_component_amounts.finance_component_id IS NOT NULL
    AND round(coalesce(settled_component_amounts.component_source_amount, 0), 2) > 0
  GROUP BY settled_component_amounts.finance_component_id;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_active_reserved (
    finance_component_id uuid NOT NULL PRIMARY KEY,
    active_reserved_source_amount numeric(12,2) NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_active_reserved;

  INSERT INTO pg_temp.tmp_pay_finance_component_active_reserved (
    finance_component_id,
    active_reserved_source_amount
  )
  SELECT
    active_component_amounts.finance_component_id,
    round(sum(active_component_amounts.component_source_amount), 2)::numeric(12,2) AS active_reserved_source_amount
  FROM (
    SELECT
      coalesce(active_reservation.finance_component_id, active_item.finance_component_id) AS finance_component_id,
      abs(coalesce(
        active_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(active_item.id),
        active_item.frozen_source_amount,
        active_item.amount_ex_vat,
        active_item.amount_inc_vat,
        active_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_advance_reservations AS active_reservation
    JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS active_reservation_scope
      ON active_reservation_scope.reservation_id = active_reservation.id
    LEFT JOIN public.pay_batch_items AS active_item
      ON active_item.id = active_reservation.pay_batch_item_id
    WHERE coalesce(active_reservation.finance_case_id, active_item.finance_case_id) = p_finance_case_id
      AND coalesce(active_reservation.finance_component_id, active_item.finance_component_id) IS NOT NULL
      AND (
        active_item.id IS NULL
        OR v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(active_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND (active_item.id IS NULL OR coalesce(active_item.is_voided, false) = false)
      AND active_reservation.settled_at_utc IS NULL
      AND active_reservation.released_at_utc IS NULL
      AND upper(btrim(coalesce(active_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS active_corrections
        WHERE active_corrections.pay_batch_item_id = active_item.id
          AND active_corrections.status = 'APPLIED'
          AND active_corrections.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ) AS active_component_amounts
  WHERE active_component_amounts.finance_component_id IS NOT NULL
    AND round(coalesce(active_component_amounts.component_source_amount, 0), 2) > 0
  GROUP BY active_component_amounts.finance_component_id;

  /* v_input_component_count was established after Policy X identity normalisation. */

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_identity_recovered (
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    active_consumed_source_amount numeric(12,2) NOT NULL,
    PRIMARY KEY (source_family_key, component_key_type, component_key_value)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_identity_recovered;

  INSERT INTO pg_temp.tmp_pay_finance_component_identity_recovered (
    source_family_key,
    component_key_type,
    component_key_value,
    active_consumed_source_amount
  )
  SELECT
    normalized_settled_identity.source_family_key,
    normalized_settled_identity.component_key_type,
    normalized_settled_identity.component_key_value,
    round(sum(normalized_settled_identity.component_source_amount), 2)::numeric(12,2)
  FROM (
    SELECT
      coalesce(
        settled_identity_component.source_family_key,
        nullif(btrim(settled_identity_item.frozen_source_basis_json->>'source_family_key'), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'source_family_key'), ''),
        CASE
          WHEN coalesce(
            settled_identity_component.linked_timesheet_id,
            settled_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          ) IS NOT NULL
          THEN 'timesheet:' || coalesce(
            settled_identity_component.linked_timesheet_id,
            settled_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          )::text
          ELSE NULL::text
        END
      ) AS source_family_key,
      upper(coalesce(
        nullif(btrim(settled_identity_component.component_key_type), ''),
        nullif(btrim(settled_identity_item.frozen_component_key_type), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'component_key_type'), '')
      )) AS component_key_type,
      coalesce(
        nullif(btrim(settled_identity_component.component_key_value), ''),
        nullif(btrim(settled_identity_item.frozen_component_key_value), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'component_key_value'), '')
      ) AS component_key_value,
      abs(coalesce(
        settled_identity_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(settled_identity_item.id),
        settled_identity_item.frozen_source_amount,
        settled_identity_item.amount_ex_vat,
        settled_identity_item.amount_inc_vat,
        settled_identity_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_batch_items AS settled_identity_item
    JOIN pg_temp.tmp_pay_finance_case_item_scope AS settled_identity_scope
      ON settled_identity_scope.pay_batch_item_id = settled_identity_item.id
    JOIN public.pay_batch_candidates AS settled_identity_candidate
      ON settled_identity_candidate.id = settled_identity_item.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS settled_identity_transfer
      ON settled_identity_transfer.id = settled_identity_item.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations AS settled_identity_reservation
      ON settled_identity_reservation.pay_batch_item_id = settled_identity_item.id
    LEFT JOIN public.pay_finance_case_components AS settled_identity_component
      ON settled_identity_component.id = coalesce(
        settled_identity_reservation.finance_component_id,
        settled_identity_item.finance_component_id
      )
    WHERE coalesce(settled_identity_item.is_voided, false) = false
      AND coalesce(
        settled_identity_reservation.finance_case_id,
        settled_identity_item.finance_case_id,
        CASE
          WHEN upper(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 1))) = 'ADVANCE'
           AND nullif(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 2)), '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN nullif(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 2)), '')::uuid
          ELSE NULL::uuid
        END
      ) = p_finance_case_id
      AND (
        v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(settled_identity_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS settled_identity_correction
        WHERE settled_identity_correction.pay_batch_item_id = settled_identity_item.id
          AND settled_identity_correction.status = 'APPLIED'
          AND settled_identity_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
      AND (
        upper(btrim(coalesce(settled_identity_candidate.settlement_status, ''))) = 'SETTLED'
        OR settled_identity_candidate.settled_at_utc IS NOT NULL
        OR upper(btrim(coalesce(settled_identity_transfer.status, ''))) = 'COMPLETED'
        OR settled_identity_transfer.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(settled_identity_reservation.status, ''))) = 'SETTLED'
        OR settled_identity_reservation.settled_at_utc IS NOT NULL
      )
  ) AS normalized_settled_identity
  WHERE normalized_settled_identity.source_family_key IS NOT NULL
    AND normalized_settled_identity.component_key_type IS NOT NULL
    AND normalized_settled_identity.component_key_value IS NOT NULL
    AND round(coalesce(normalized_settled_identity.component_source_amount, 0), 2) > 0
  GROUP BY
    normalized_settled_identity.source_family_key,
    normalized_settled_identity.component_key_type,
    normalized_settled_identity.component_key_value;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_identity_reserved (
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    active_reserved_source_amount numeric(12,2) NOT NULL,
    PRIMARY KEY (source_family_key, component_key_type, component_key_value)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_identity_reserved;

  INSERT INTO pg_temp.tmp_pay_finance_component_identity_reserved (
    source_family_key,
    component_key_type,
    component_key_value,
    active_reserved_source_amount
  )
  SELECT
    normalized_reserved_identity.source_family_key,
    normalized_reserved_identity.component_key_type,
    normalized_reserved_identity.component_key_value,
    round(sum(normalized_reserved_identity.component_source_amount), 2)::numeric(12,2)
  FROM (
    SELECT
      coalesce(
        reserved_identity_component.source_family_key,
        nullif(btrim(reserved_identity_item.frozen_source_basis_json->>'source_family_key'), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'source_family_key'), ''),
        CASE
          WHEN coalesce(
            reserved_identity_component.linked_timesheet_id,
            reserved_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          ) IS NOT NULL
          THEN 'timesheet:' || coalesce(
            reserved_identity_component.linked_timesheet_id,
            reserved_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          )::text
          ELSE NULL::text
        END
      ) AS source_family_key,
      upper(coalesce(
        nullif(btrim(reserved_identity_component.component_key_type), ''),
        nullif(btrim(reserved_identity_item.frozen_component_key_type), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'component_key_type'), '')
      )) AS component_key_type,
      coalesce(
        nullif(btrim(reserved_identity_component.component_key_value), ''),
        nullif(btrim(reserved_identity_item.frozen_component_key_value), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'component_key_value'), '')
      ) AS component_key_value,
      abs(coalesce(
        reserved_identity_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(reserved_identity_item.id),
        reserved_identity_item.frozen_source_amount,
        reserved_identity_item.amount_ex_vat,
        reserved_identity_item.amount_inc_vat,
        reserved_identity_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_advance_reservations AS reserved_identity_reservation
    JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS reserved_identity_scope
      ON reserved_identity_scope.reservation_id = reserved_identity_reservation.id
    LEFT JOIN public.pay_batch_items AS reserved_identity_item
      ON reserved_identity_item.id = reserved_identity_reservation.pay_batch_item_id
    LEFT JOIN public.pay_finance_case_components AS reserved_identity_component
      ON reserved_identity_component.id = coalesce(
        reserved_identity_reservation.finance_component_id,
        reserved_identity_item.finance_component_id
      )
    WHERE coalesce(
        reserved_identity_reservation.finance_case_id,
        reserved_identity_item.finance_case_id
      ) = p_finance_case_id
      AND (
        reserved_identity_item.id IS NULL
        OR v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(reserved_identity_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND (reserved_identity_item.id IS NULL OR coalesce(reserved_identity_item.is_voided, false) = false)
      AND reserved_identity_reservation.settled_at_utc IS NULL
      AND reserved_identity_reservation.released_at_utc IS NULL
      AND upper(btrim(coalesce(reserved_identity_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reserved_identity_correction
        WHERE reserved_identity_correction.pay_batch_item_id = reserved_identity_item.id
          AND reserved_identity_correction.status = 'APPLIED'
          AND reserved_identity_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ) AS normalized_reserved_identity
  WHERE normalized_reserved_identity.source_family_key IS NOT NULL
    AND normalized_reserved_identity.component_key_type IS NOT NULL
    AND normalized_reserved_identity.component_key_value IS NOT NULL
    AND round(coalesce(normalized_reserved_identity.component_source_amount, 0), 2) > 0
  GROUP BY
    normalized_reserved_identity.source_family_key,
    normalized_reserved_identity.component_key_type,
    normalized_reserved_identity.component_key_value;

  SELECT round(coalesce(sum(abs(coalesce(
    case_settled_reservation.reserved_source_amount,
    public._pay_batch_item_source_reservation_amount_ex_vat(case_settled_item.id),
    case_settled_item.frozen_source_amount,
    case_settled_item.amount_ex_vat,
    case_settled_item.amount_inc_vat,
    case_settled_reservation.reserved_amount,
    0
  ))), 0), 2)::numeric(12,2)
  INTO v_case_active_consumed_amount
  FROM public.pay_batch_items AS case_settled_item
  JOIN pg_temp.tmp_pay_finance_case_item_scope AS case_settled_scope
    ON case_settled_scope.pay_batch_item_id = case_settled_item.id
  JOIN public.pay_batch_candidates AS case_settled_candidate
    ON case_settled_candidate.id = case_settled_item.pay_batch_candidate_id
  LEFT JOIN public.pay_bank_transfers AS case_settled_transfer
    ON case_settled_transfer.id = case_settled_item.pay_bank_transfer_id
  LEFT JOIN public.pay_advance_reservations AS case_settled_reservation
    ON case_settled_reservation.pay_batch_item_id = case_settled_item.id
  WHERE coalesce(case_settled_item.is_voided, false) = false
    AND coalesce(
      case_settled_reservation.finance_case_id,
      case_settled_item.finance_case_id,
      CASE
        WHEN upper(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 1))) = 'ADVANCE'
         AND nullif(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 2)), '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN nullif(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 2)), '')::uuid
        ELSE NULL::uuid
      END
    ) = p_finance_case_id
    AND (
      v_case_type NOT IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      )
      OR upper(btrim(coalesce(case_settled_item.item_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'UNDERPAYMENT_PAYMENT'
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS case_settled_correction
      WHERE case_settled_correction.pay_batch_item_id = case_settled_item.id
        AND case_settled_correction.status = 'APPLIED'
        AND case_settled_correction.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    )
    AND (
      upper(btrim(coalesce(case_settled_candidate.settlement_status, ''))) = 'SETTLED'
      OR case_settled_candidate.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(case_settled_transfer.status, ''))) = 'COMPLETED'
      OR case_settled_transfer.completed_at_utc IS NOT NULL
      OR upper(btrim(coalesce(case_settled_reservation.status, ''))) = 'SETTLED'
      OR case_settled_reservation.settled_at_utc IS NOT NULL
    );

  SELECT round(coalesce(sum(abs(coalesce(
    case_reserved_reservation.reserved_source_amount,
    public._pay_batch_item_source_reservation_amount_ex_vat(case_reserved_item.id),
    case_reserved_item.frozen_source_amount,
    case_reserved_item.amount_ex_vat,
    case_reserved_item.amount_inc_vat,
    case_reserved_reservation.reserved_amount,
    0
  ))), 0), 2)::numeric(12,2)
  INTO v_case_active_reserved_source_amount
  FROM public.pay_advance_reservations AS case_reserved_reservation
  JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS case_reserved_scope
    ON case_reserved_scope.reservation_id = case_reserved_reservation.id
  LEFT JOIN public.pay_batch_items AS case_reserved_item
    ON case_reserved_item.id = case_reserved_reservation.pay_batch_item_id
  WHERE coalesce(
      case_reserved_reservation.finance_case_id,
      case_reserved_item.finance_case_id
    ) = p_finance_case_id
    AND (
      case_reserved_item.id IS NULL
      OR v_case_type NOT IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      )
      OR upper(btrim(coalesce(case_reserved_item.item_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'UNDERPAYMENT_PAYMENT'
      )
    )
    AND (case_reserved_item.id IS NULL OR coalesce(case_reserved_item.is_voided, false) = false)
    AND case_reserved_reservation.settled_at_utc IS NULL
    AND case_reserved_reservation.released_at_utc IS NULL
    AND upper(btrim(coalesce(case_reserved_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS case_reserved_correction
      WHERE case_reserved_correction.pay_batch_item_id = case_reserved_item.id
        AND case_reserved_correction.status = 'APPLIED'
        AND case_reserved_correction.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    );

  FOR v_existing_component IN
    SELECT
      pfc.*
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.closed_at_utc IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM (
          SELECT DISTINCT ON (
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          )
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          FROM pg_temp.tmp_pay_finance_component_sync_input src
          ORDER BY
            src.source_family_key,
            src.component_key_type,
            src.component_key_value,
            src.row_seq DESC
        ) keep_rows
        WHERE keep_rows.source_family_key = pfc.source_family_key
          AND keep_rows.component_key_type = pfc.component_key_type
          AND keep_rows.component_key_value = pfc.component_key_value
      )
  LOOP
    v_before_json := jsonb_build_object(
      'candidate_id', v_existing_component.candidate_id::text,
      'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
      'source_family_key', v_existing_component.source_family_key,
      'component_key_type', v_existing_component.component_key_type,
      'component_key_value', v_existing_component.component_key_value,
      'classification', v_existing_component.classification::text,
      'source_pay_method', v_existing_component.source_pay_method,
      'source_basis_json', v_existing_component.source_basis_json,
      'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_existing_component.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
      'resolution_fingerprint', v_existing_component.resolution_fingerprint,
      'is_resolution_stale', v_existing_component.is_resolution_stale,
      'stale_reason', v_existing_component.stale_reason,
      'closed_at_utc', v_existing_component.closed_at_utc
    );

    SELECT EXISTS (
      SELECT 1
      FROM public.pay_finance_case_events AS protected_component_events
      WHERE protected_component_events.finance_case_id = p_finance_case_id
        AND protected_component_events.finance_component_id = v_existing_component.id
        AND (
          upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
          OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE',
            'MANUAL_WRITE_OFF',
            'CASE_MANUAL_ECONOMIC_OVERRIDE',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE',
            'WRITE_OFF',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
        )
    )
    INTO v_component_has_protected_event;

    v_component_is_protected := coalesce(v_component_has_protected_event, false);

    IF v_component_is_protected THEN
      INSERT INTO public.pay_finance_case_events (
        finance_case_id,
        finance_component_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      VALUES (
        p_finance_case_id,
        v_existing_component.id,
        'SYNC_SKIPPED',
        v_now_utc,
        p_actor_user_id,
        NULL,
        NULL,
        v_before_json,
        jsonb_build_object(
          'sync_skipped', true,
          'reason', 'PROTECTED_COMPONENT_NOT_CLOSED',
          'has_protected_event', v_component_has_protected_event,
          'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
          'is_resolution_stale', v_existing_component.is_resolution_stale
        ),
        'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
        'Skipped closing finance component because an explicit manual, write-off, or restructure event protects it.'
      );
      v_protected_skip_count := v_protected_skip_count + 1;
      CONTINUE;
    END IF;

    SELECT reserved_amounts.active_reserved_source_amount
    INTO v_active_reserved_source_amount
    FROM pg_temp.tmp_pay_finance_component_active_reserved AS reserved_amounts
    WHERE reserved_amounts.finance_component_id = v_existing_component.id;

    v_active_reserved_source_amount := round(coalesce(v_active_reserved_source_amount, 0), 2)::numeric(12,2);

    IF v_active_reserved_source_amount > 0 THEN
      UPDATE public.pay_finance_case_components AS preserved_component
      SET remaining_source_amount = greatest(round(coalesce(preserved_component.remaining_source_amount, 0), 2), v_active_reserved_source_amount)::numeric(12,2),
          updated_at_utc = v_now_utc
      WHERE preserved_component.id = v_existing_component.id
      RETURNING preserved_component.* INTO v_component_after;

      v_after_json := jsonb_build_object(
        'candidate_id', v_component_after.candidate_id::text,
        'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
        'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
        'source_family_key', v_component_after.source_family_key,
        'component_key_type', v_component_after.component_key_type,
        'component_key_value', v_component_after.component_key_value,
        'classification', v_component_after.classification::text,
        'source_pay_method', v_component_after.source_pay_method,
        'source_basis_json', v_component_after.source_basis_json,
        'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
        'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
        'active_reserved_source_amount', v_active_reserved_source_amount,
        'closed_at_utc', v_component_after.closed_at_utc
      );

      INSERT INTO public.pay_finance_case_events (
        finance_case_id,
        finance_component_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      VALUES (
        p_finance_case_id,
        v_existing_component.id,
        'SYNC_SKIPPED',
        v_now_utc,
        p_actor_user_id,
        NULL,
        NULL,
        v_before_json,
        v_after_json,
        'COMPONENT_SYNC_CLOSE_DEFERRED_ACTIVE_RESERVATION',
        'Deferred closing finance component because active RESERVED/COMMITTED recovery reservations still protect it.'
      );

      v_active_reservation_deferred_count := v_active_reservation_deferred_count + 1;
      CONTINUE;
    END IF;

    UPDATE public.pay_finance_case_components pfc
    SET
      remaining_source_amount = 0,
      is_resolution_stale = false,
      stale_reason = NULL,
      closed_at_utc = v_now_utc,
      updated_at_utc = v_now_utc
    WHERE pfc.id = v_existing_component.id
    RETURNING pfc.* INTO v_component_after;

    v_after_json := jsonb_build_object(
      'candidate_id', v_component_after.candidate_id::text,
      'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
      'source_family_key', v_component_after.source_family_key,
      'component_key_type', v_component_after.component_key_type,
      'component_key_value', v_component_after.component_key_value,
      'classification', v_component_after.classification::text,
      'source_pay_method', v_component_after.source_pay_method,
      'source_basis_json', v_component_after.source_basis_json,
      'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
      'resolution_fingerprint', v_component_after.resolution_fingerprint,
      'is_resolution_stale', v_component_after.is_resolution_stale,
      'stale_reason', v_component_after.stale_reason,
      'closed_at_utc', v_component_after.closed_at_utc
    );

    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      v_existing_component.id,
      'COMPONENT_CLOSED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      v_before_json,
      v_after_json,
      'COMPONENT_SYNC',
      'Closed finance component because it no longer exists in the current preview/truth line set'
    );

    v_closed_count := v_closed_count + 1;
  END LOOP;

  FOR v_line_json IN
    SELECT to_jsonb(src.*)
    FROM (
      SELECT DISTINCT ON (
        src.source_family_key,
        src.component_key_type,
        src.component_key_value
      )
        src.row_seq,
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.classification,
        src.candidate_id,
        src.client_id,
        src.linked_timesheet_id,
        src.source_pay_method,
        src.current_target_pay_method,
        src.source_basis_json,
        src.target_basis_json,
        src.accepted_resolution_json,
        src.source_amount,
        src.incoming_remaining_source_amount,
        src.incoming_remaining_is_explicit,
        src.relevant_erni_pct,
        src.allocation_priority_group,
        src.allocation_priority_order,
        src.current_basis_fingerprint
      FROM pg_temp.tmp_pay_finance_component_sync_input src
      ORDER BY
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.row_seq DESC
    ) src
    ORDER BY
      (src.source_basis_json->>'work_date') NULLS LAST,
      src.allocation_priority_group,
      src.allocation_priority_order,
      src.row_seq
  LOOP
    v_line_candidate_id := (v_line_json->>'candidate_id')::uuid;
    v_line_client_id := CASE
      WHEN nullif(v_line_json->>'client_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'client_id')::uuid
    END;
    v_line_linked_timesheet_id := CASE
      WHEN nullif(v_line_json->>'linked_timesheet_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'linked_timesheet_id')::uuid
    END;
    v_line_classification := (v_line_json->>'classification')::public.pay_finance_component_classification_enum;
    v_line_source_pay_method := v_line_json->>'source_pay_method';
    v_line_current_target_pay_method := coalesce(v_line_json->>'current_target_pay_method', '');
    v_line_source_basis_json := v_line_json->'source_basis_json';
    v_line_source_amount := round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2)::numeric(12,2);
    v_line_incoming_remaining_source_amount := CASE
      WHEN (v_line_json->>'incoming_remaining_is_explicit')::boolean
        THEN round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2)::numeric(12,2)
      ELSE NULL
    END;
    v_line_allocation_priority_group := (v_line_json->>'allocation_priority_group')::integer;
    v_line_allocation_priority_order := (v_line_json->>'allocation_priority_order')::integer;

    SELECT
      pfc.*
    INTO
      v_existing_component
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.source_family_key = v_line_json->>'source_family_key'
      AND pfc.component_key_type = v_line_json->>'component_key_type'
      AND pfc.component_key_value = v_line_json->>'component_key_value'
      AND pfc.closed_at_utc IS NULL
    ORDER BY
      pfc.updated_at_utc DESC,
      pfc.created_at_utc DESC,
      pfc.id DESC
    LIMIT 1;

    IF FOUND THEN
      v_active_consumed_amount := NULL::numeric;
      v_active_reserved_source_amount := 0::numeric(12,2);
      v_identity_consumed_amount := NULL::numeric;
      v_identity_reserved_source_amount := NULL::numeric;

      SELECT recovered_amounts.active_consumed_source_amount
      INTO v_active_consumed_amount
      FROM pg_temp.tmp_pay_finance_component_active_recovered AS recovered_amounts
      WHERE recovered_amounts.finance_component_id = v_existing_component.id;

      SELECT reserved_amounts.active_reserved_source_amount
      INTO v_active_reserved_source_amount
      FROM pg_temp.tmp_pay_finance_component_active_reserved AS reserved_amounts
      WHERE reserved_amounts.finance_component_id = v_existing_component.id;

      SELECT identity_recovered.active_consumed_source_amount
      INTO v_identity_consumed_amount
      FROM pg_temp.tmp_pay_finance_component_identity_recovered AS identity_recovered
      WHERE identity_recovered.source_family_key = v_existing_component.source_family_key
        AND identity_recovered.component_key_type = v_existing_component.component_key_type
        AND identity_recovered.component_key_value = v_existing_component.component_key_value;

      SELECT identity_reserved.active_reserved_source_amount
      INTO v_identity_reserved_source_amount
      FROM pg_temp.tmp_pay_finance_component_identity_reserved AS identity_reserved
      WHERE identity_reserved.source_family_key = v_existing_component.source_family_key
        AND identity_reserved.component_key_type = v_existing_component.component_key_type
        AND identity_reserved.component_key_value = v_existing_component.component_key_value;

      IF v_case_type IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      ) THEN
        v_consumed_amount := round(coalesce(
          v_identity_consumed_amount,
          CASE WHEN v_input_component_count = 1 THEN v_case_active_consumed_amount ELSE NULL::numeric END,
          0
        ), 2)::numeric(12,2);
        v_active_reserved_source_amount := round(greatest(
          coalesce(v_identity_reserved_source_amount, 0),
          coalesce(v_active_reserved_source_amount, 0),
          CASE WHEN v_input_component_count = 1 THEN coalesce(v_case_active_reserved_source_amount, 0) ELSE 0::numeric END
        ), 2)::numeric(12,2);
      ELSE
        v_active_reserved_source_amount := round(coalesce(v_active_reserved_source_amount, 0), 2)::numeric(12,2);
        v_consumed_amount := coalesce(
          v_active_consumed_amount,
          greatest(
            round(coalesce(v_existing_component.source_amount, 0), 2) - round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
            0
          )::numeric(12,2)
        );
      END IF;

      IF (v_line_json->>'incoming_remaining_is_explicit')::boolean THEN
        /* Explicit remaining is the upstream net-open authority.  Correction
           residual inputs already include settled recovery/underpayment
           movements, so subtracting v_consumed_amount again would double
           consume the frozen movement.  v_effective_source_amount below keeps
           the cumulative source basis at consumed + still open, while the
           active-reservation floor prevents a live draft from being stranded. */
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2),
          0
        )::numeric(12,2);
      ELSE
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2) - v_consumed_amount,
          0
        )::numeric(12,2);
      END IF;

      IF v_active_reserved_source_amount > 0
         AND round(coalesce(v_new_remaining_source_amount, 0), 2) < v_active_reserved_source_amount THEN
        v_new_remaining_source_amount := v_active_reserved_source_amount;
        v_active_reservation_deferred_count := v_active_reservation_deferred_count + 1;
      END IF;

      v_effective_source_amount := greatest(
        round(coalesce(v_line_source_amount, 0), 2),
        round(coalesce(v_consumed_amount, 0), 2) + round(coalesce(v_new_remaining_source_amount, 0), 2)
      )::numeric(12,2);

      v_upstream_correction_resolution_applied := (
        lower(coalesce(
          v_line_source_basis_json->>'upstream_correction_pay_method_resolution_applied',
          'false'
        )) in ('true','t','1','yes','y','on')
        and upper(coalesce(v_line_source_pay_method,'')) =
            upper(coalesce(v_line_current_target_pay_method,''))
      );

      v_has_saved_resolution := not v_upstream_correction_resolution_applied and (
        v_existing_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND (
          v_existing_component.saved_target_pay_method IS NOT NULL
          OR v_existing_component.saved_resolution_mode IS NOT NULL
          OR v_existing_component.saved_resolution_payload_json IS NOT NULL
          OR v_existing_component.saved_resolution_result_json IS NOT NULL
          OR v_existing_component.resolution_fingerprint IS NOT NULL
          OR v_existing_component.is_resolution_stale = true
        )
      );

      IF v_has_saved_resolution THEN
        IF v_existing_component.classification IS DISTINCT FROM v_line_classification THEN
          v_should_be_stale := true;
          v_stale_reason := 'COMPONENT_CLASSIFICATION_CHANGED';
        ELSIF v_existing_component.saved_target_pay_method IS NOT NULL
           AND upper(v_existing_component.saved_target_pay_method) IS DISTINCT FROM upper(v_line_current_target_pay_method) THEN
          v_should_be_stale := true;
          v_stale_reason := 'TARGET_PAY_METHOD_CHANGED';
        ELSIF upper(coalesce(v_existing_component.source_pay_method, '')) IS DISTINCT FROM upper(coalesce(v_line_source_pay_method, '')) THEN
          v_should_be_stale := true;
          v_stale_reason := 'SOURCE_PAY_METHOD_CHANGED';
        ELSIF (
          coalesce(v_existing_component.source_basis_json, '{}'::jsonb)
            - 'amount'
            - 'amount_ex_vat'
            - 'amount_inc_vat'
            - 'component_amount_ex_vat'
            - 'remaining_source_amount'
            - 'source_amount'
            - 'source_units'
            - 'units'
            - 'hours'
            - 'quantity'
            - 'line_total'
            - 'total'
            - 'current_amount'
            - 'current_units'
        ) IS DISTINCT FROM (
          coalesce(v_line_source_basis_json, '{}'::jsonb)
            - 'amount'
            - 'amount_ex_vat'
            - 'amount_inc_vat'
            - 'component_amount_ex_vat'
            - 'remaining_source_amount'
            - 'source_amount'
            - 'source_units'
            - 'units'
            - 'hours'
            - 'quantity'
            - 'line_total'
            - 'total'
            - 'current_amount'
            - 'current_units'
        ) THEN
          v_should_be_stale := true;
          v_stale_reason := 'COMPONENT_BASIS_CHANGED';
        ELSE
          v_should_be_stale := false;
          v_stale_reason := NULL;
        END IF;
      ELSE
        v_should_be_stale := false;
        v_stale_reason := NULL;
      END IF;

      v_resolution_target_ratio := NULL;
      v_resolution_vat_ratio := NULL;
      v_resolution_inc_ratio := NULL;

      IF v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
        v_resolution_target_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_source_ratio', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (v_existing_component.saved_resolution_result_json->>'target_source_ratio')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          1::numeric
        );

        v_resolution_vat_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          0::numeric
        );

        v_resolution_inc_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          v_resolution_target_ratio
        );
      END IF;

      v_before_json := jsonb_build_object(
        'candidate_id', v_existing_component.candidate_id::text,
        'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
        'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
        'source_family_key', v_existing_component.source_family_key,
        'component_key_type', v_existing_component.component_key_type,
        'component_key_value', v_existing_component.component_key_value,
        'classification', v_existing_component.classification::text,
        'source_pay_method', v_existing_component.source_pay_method,
        'source_basis_json', v_existing_component.source_basis_json,
        'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
        'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
        'saved_target_pay_method', v_existing_component.saved_target_pay_method,
        'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
        'resolution_fingerprint', v_existing_component.resolution_fingerprint,
        'is_resolution_stale', v_existing_component.is_resolution_stale,
        'stale_reason', v_existing_component.stale_reason,
        'closed_at_utc', v_existing_component.closed_at_utc
      );

      SELECT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protected_component_events
        WHERE protected_component_events.finance_case_id = p_finance_case_id
          AND protected_component_events.finance_component_id = v_existing_component.id
          AND (
            upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'MANUAL_WRITE_OFF',
                'CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
              OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'WRITE_OFF',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
          )
      )
      INTO v_component_has_protected_event;

      v_component_is_protected := coalesce(v_component_has_protected_event, false);

      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        v_accepted_resolution_fingerprint := coalesce(
          nullif(btrim(v_accepted_resolution_json->>'component_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'resolution_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['component_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['resolution_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['validation', 'component_fingerprints', v_existing_component.id::text]), '')
        );

        IF v_component_is_protected
           OR v_existing_component.closed_at_utc IS NOT NULL
           OR v_accepted_resolution_fingerprint IS NULL
           OR v_should_be_stale THEN
          RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'ACCEPTED_RESOLUTION_STALE',
            'code', 'ACCEPTED_RESOLUTION_STALE',
            'message', 'Accepted suggested correction resolution is stale or no longer matches the open finance component state.',
            'finance_case_id', p_finance_case_id::text,
            'finance_component_id', v_existing_component.id::text,
            'component_still_open', v_existing_component.closed_at_utc IS NULL,
            'has_protected_event', v_component_has_protected_event,
            'accepted_fingerprint', v_accepted_resolution_fingerprint,
            'current_fingerprint', v_line_json->>'current_basis_fingerprint'
          )::text;
        END IF;
      END IF;

      IF v_component_is_protected THEN
        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
            'has_protected_event', v_component_has_protected_event,
            'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
            'is_resolution_stale', v_existing_component.is_resolution_stale
          ),
          'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
          'Skipped updating finance component because an explicit write-off or manual economic override protects it.'
        );
        v_protected_skip_count := v_protected_skip_count + 1;
        CONTINUE;
      END IF;

      IF round(coalesce(v_existing_component.source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_effective_source_amount, v_line_source_amount, 0), 2)
         OR round(coalesce(v_existing_component.remaining_source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_new_remaining_source_amount, 0), 2)
         OR v_existing_component.candidate_id IS DISTINCT FROM v_line_candidate_id
         OR v_existing_component.client_id IS DISTINCT FROM v_line_client_id
         OR v_existing_component.linked_timesheet_id IS DISTINCT FROM v_line_linked_timesheet_id
         OR v_existing_component.source_pay_method IS DISTINCT FROM v_line_source_pay_method
         OR v_existing_component.source_basis_json IS DISTINCT FROM v_line_source_basis_json
         OR v_existing_component.classification IS DISTINCT FROM v_line_classification
         OR v_existing_component.allocation_priority_group IS DISTINCT FROM v_line_allocation_priority_group
         OR v_existing_component.allocation_priority_order IS DISTINCT FROM v_line_allocation_priority_order
         OR v_existing_component.is_resolution_stale IS DISTINCT FROM v_should_be_stale
          OR v_existing_component.stale_reason IS DISTINCT FROM v_stale_reason
          OR (
            v_upstream_correction_resolution_applied
            AND (
              v_existing_component.saved_target_pay_method IS NOT NULL
              OR v_existing_component.saved_resolution_mode IS NOT NULL
              OR v_existing_component.saved_resolution_payload_json IS NOT NULL
              OR v_existing_component.saved_resolution_result_json IS NOT NULL
              OR v_existing_component.resolution_fingerprint IS NOT NULL
            )
          )
      THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.pay_finance_case_events AS protected_component_events
          WHERE protected_component_events.finance_case_id = p_finance_case_id
            AND protected_component_events.finance_component_id = v_existing_component.id
            AND (
              upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'MANUAL_WRITE_OFF',
                'CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
              OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'WRITE_OFF',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
            )
        )
        INTO v_component_has_protected_event;

        v_component_is_protected := coalesce(v_component_has_protected_event, false);

        IF v_component_is_protected THEN
          INSERT INTO public.pay_finance_case_events (
            finance_case_id,
            finance_component_id,
            event_type,
            event_at_utc,
            actor_user_id,
            pay_batch_id,
            reservation_id,
            before_json,
            after_json,
            reason,
            note
          )
          VALUES (
            p_finance_case_id,
            v_existing_component.id,
            'SYNC_SKIPPED',
            v_now_utc,
            p_actor_user_id,
            NULL,
            NULL,
            v_before_json,
            jsonb_build_object(
              'sync_skipped', true,
              'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
              'has_protected_event', v_component_has_protected_event
            ),
            'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
            'Skipped updating finance component because it has an explicit write-off or manual economic override protection.'
          );
          v_protected_skip_count := v_protected_skip_count + 1;
          CONTINUE;
        END IF;

        UPDATE public.pay_finance_case_components pfc
        SET
          candidate_id = v_line_candidate_id,
          client_id = v_line_client_id,
          linked_timesheet_id = v_line_linked_timesheet_id,
          classification = v_line_classification,
          source_pay_method = v_line_source_pay_method,
          source_basis_json = v_line_source_basis_json,
          source_amount = round(coalesce(v_effective_source_amount, v_line_source_amount, 0), 2)::numeric(12,2),
          remaining_source_amount = round(coalesce(v_new_remaining_source_amount, 0), 2)::numeric(12,2),
          saved_target_pay_method = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_target_pay_method
          END,
          saved_resolution_mode = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_resolution_mode
          END,
          saved_resolution_payload_json = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_resolution_payload_json
          END,
          saved_resolution_result_json = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            WHEN v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
              jsonb_strip_nulls(
                coalesce(pfc.saved_resolution_result_json, '{}'::jsonb)
                || jsonb_build_object(
                  'source_remaining_amount_ex_vat', round(coalesce(v_new_remaining_source_amount, 0), 2),
                  'target_remaining_amount_ex_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_target_ratio, 1), 2),
                  'target_remaining_amount_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_vat_ratio, 0), 2),
                  'target_remaining_amount_inc_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_inc_ratio, coalesce(v_resolution_target_ratio, 1)), 2),
                  'target_source_ratio', round(coalesce(v_resolution_target_ratio, 1), 12),
                  'amount_only_resolution_reused', true,
                  'amount_only_resolution_reused_at_utc', v_now_utc::text
                )
              )
            ELSE pfc.saved_resolution_result_json
          END,
          resolution_fingerprint = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            WHEN v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
              coalesce(nullif(btrim(coalesce(v_line_json->>'current_basis_fingerprint', '')), ''), pfc.resolution_fingerprint)
            ELSE pfc.resolution_fingerprint
          END,
          is_resolution_stale = v_should_be_stale,
          stale_reason = v_stale_reason,
          allocation_priority_group = v_line_allocation_priority_group,
          allocation_priority_order = v_line_allocation_priority_order,
          updated_at_utc = v_now_utc
        WHERE pfc.id = v_existing_component.id
        RETURNING pfc.* INTO v_component_after;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN 'COMPONENT_STALE'
            ELSE 'COMPONENT_UPDATED'
          END,
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          v_after_json,
          'COMPONENT_SYNC',
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true
              THEN 'Updated finance component and marked saved taxable resolution stale because the basis or target pay method changed materially'
            ELSE 'Updated finance component from current preview/truth line set'
          END
        );

        IF v_active_reserved_source_amount > 0
           AND round(coalesce(v_line_source_amount, 0), 2) < round(coalesce(v_effective_source_amount, 0), 2) THEN
          INSERT INTO public.pay_finance_case_events (
            finance_case_id,
            finance_component_id,
            event_type,
            event_at_utc,
            actor_user_id,
            pay_batch_id,
            reservation_id,
            before_json,
            after_json,
            reason,
            note
          )
          VALUES (
            p_finance_case_id,
            v_existing_component.id,
            'COMPONENT_UPDATED',
            v_now_utc,
            p_actor_user_id,
            NULL,
            NULL,
            v_before_json,
            v_after_json || jsonb_build_object(
              'active_reserved_source_amount', v_active_reserved_source_amount,
              'incoming_source_amount', round(coalesce(v_line_source_amount, 0), 2),
              'effective_source_amount', round(coalesce(v_effective_source_amount, 0), 2),
              'effective_remaining_source_amount', round(coalesce(v_new_remaining_source_amount, 0), 2)
            ),
            'COMPONENT_SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
            'Deferred component shrink below active RESERVED/COMMITTED recovery reservations.'
          );
        END IF;

        IF v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN
          v_stale_marked_count := v_stale_marked_count + 1;
        END IF;

        v_updated_count := v_updated_count + 1;
      END IF;
    ELSE
      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'ACCEPTED_RESOLUTION_STALE',
          'code', 'ACCEPTED_RESOLUTION_STALE',
          'message', 'Accepted suggested correction resolution cannot be applied because the finance component is no longer open.',
          'finance_case_id', p_finance_case_id::text,
          'source_family_key', v_line_json->>'source_family_key',
          'component_key_type', v_line_json->>'component_key_type',
          'component_key_value', v_line_json->>'component_key_value',
          'component_still_open', false
        )::text;
      END IF;

      SELECT
        pfc.*
      INTO
        v_reopen_component
      FROM public.pay_finance_case_components pfc
      WHERE pfc.finance_case_id = p_finance_case_id
        AND pfc.source_family_key = v_line_json->>'source_family_key'
        AND pfc.component_key_type = v_line_json->>'component_key_type'
        AND pfc.component_key_value = v_line_json->>'component_key_value'
        AND pfc.closed_at_utc IS NOT NULL
      ORDER BY
        pfc.closed_at_utc DESC,
        pfc.updated_at_utc DESC,
        pfc.created_at_utc DESC,
        pfc.id DESC
      LIMIT 1;

      IF FOUND THEN
        v_before_json := jsonb_build_object(
          'candidate_id', v_reopen_component.candidate_id::text,
          'client_id', CASE WHEN v_reopen_component.client_id IS NULL THEN NULL ELSE v_reopen_component.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_reopen_component.linked_timesheet_id IS NULL THEN NULL ELSE v_reopen_component.linked_timesheet_id::text END,
          'source_family_key', v_reopen_component.source_family_key,
          'component_key_type', v_reopen_component.component_key_type,
          'component_key_value', v_reopen_component.component_key_value,
          'classification', v_reopen_component.classification::text,
          'source_pay_method', v_reopen_component.source_pay_method,
          'source_basis_json', v_reopen_component.source_basis_json,
          'source_amount', round(coalesce(v_reopen_component.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_reopen_component.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_reopen_component.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_reopen_component.saved_resolution_mode IS NULL THEN NULL ELSE v_reopen_component.saved_resolution_mode::text END,
          'resolution_fingerprint', v_reopen_component.resolution_fingerprint,
          'is_resolution_stale', v_reopen_component.is_resolution_stale,
          'stale_reason', v_reopen_component.stale_reason,
          'closed_at_utc', v_reopen_component.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_reopen_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'CLOSED_COMPONENT_PRESERVED',
            'new_component_will_be_created', true,
            'source_family_key', v_line_json->>'source_family_key',
            'component_key_type', v_line_json->>'component_key_type',
            'component_key_value', v_line_json->>'component_key_value'
          ),
          'COMPONENT_SYNC_CLOSED_COMPONENT_PRESERVED',
          'Preserved closed finance component and created a new open component for the current preview/truth line set instead of silently reopening or overwriting the closed component.'
        );

        v_protected_skip_count := v_protected_skip_count + 1;
      END IF;

        v_identity_consumed_amount := NULL::numeric;
        v_identity_reserved_source_amount := NULL::numeric;
        v_consumed_amount := 0::numeric(12,2);
        v_active_reserved_source_amount := 0::numeric(12,2);

        SELECT identity_recovered.active_consumed_source_amount
        INTO v_identity_consumed_amount
        FROM pg_temp.tmp_pay_finance_component_identity_recovered AS identity_recovered
        WHERE identity_recovered.source_family_key = v_line_json->>'source_family_key'
          AND identity_recovered.component_key_type = v_line_json->>'component_key_type'
          AND identity_recovered.component_key_value = v_line_json->>'component_key_value';

        SELECT identity_reserved.active_reserved_source_amount
        INTO v_identity_reserved_source_amount
        FROM pg_temp.tmp_pay_finance_component_identity_reserved AS identity_reserved
        WHERE identity_reserved.source_family_key = v_line_json->>'source_family_key'
          AND identity_reserved.component_key_type = v_line_json->>'component_key_type'
          AND identity_reserved.component_key_value = v_line_json->>'component_key_value';

        IF v_case_type IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        ) THEN
          v_consumed_amount := round(coalesce(
            v_identity_consumed_amount,
            CASE WHEN v_input_component_count = 1 THEN v_case_active_consumed_amount ELSE NULL::numeric END,
            0
          ), 2)::numeric(12,2);
          v_active_reserved_source_amount := round(greatest(
            coalesce(v_identity_reserved_source_amount, 0),
            CASE WHEN v_input_component_count = 1 THEN coalesce(v_case_active_reserved_source_amount, 0) ELSE 0::numeric END
          ), 2)::numeric(12,2);
        END IF;

        IF (v_line_json->>'incoming_remaining_is_explicit')::boolean THEN
          v_new_remaining_source_amount := greatest(
            round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2),
            v_active_reserved_source_amount,
            0
          )::numeric(12,2);
        ELSE
          v_new_remaining_source_amount := greatest(
            round(coalesce(v_line_source_amount, 0), 2) - round(coalesce(v_consumed_amount, 0), 2),
            v_active_reserved_source_amount,
            0
          )::numeric(12,2);
        END IF;

        v_effective_source_amount := greatest(
          round(coalesce(v_line_source_amount, 0), 2),
          round(coalesce(v_consumed_amount, 0), 2) + round(coalesce(v_new_remaining_source_amount, 0), 2)
        )::numeric(12,2);

        v_created_component_id := gen_random_uuid();

        INSERT INTO public.pay_finance_case_components (
          id,
          finance_case_id,
          candidate_id,
          client_id,
          linked_timesheet_id,
          source_family_key,
          component_key_type,
          component_key_value,
          classification,
          source_pay_method,
          source_basis_json,
          source_amount,
          remaining_source_amount,
          saved_target_pay_method,
          saved_resolution_mode,
          saved_resolution_payload_json,
          saved_resolution_result_json,
          resolution_fingerprint,
          is_resolution_stale,
          stale_reason,
          allocation_priority_group,
          allocation_priority_order,
          created_at_utc,
          updated_at_utc,
          resolved_at_utc,
          closed_at_utc
        )
        VALUES (
          v_created_component_id,
          p_finance_case_id,
          v_line_candidate_id,
          v_line_client_id,
          v_line_linked_timesheet_id,
          v_line_json->>'source_family_key',
          v_line_json->>'component_key_type',
          v_line_json->>'component_key_value',
          v_line_classification,
          v_line_source_pay_method,
          v_line_source_basis_json,
          round(coalesce(v_effective_source_amount, 0), 2)::numeric(12,2),
          round(coalesce(v_new_remaining_source_amount, 0), 2)::numeric(12,2),
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          false,
          NULL,
          v_line_allocation_priority_group,
          v_line_allocation_priority_order,
          v_now_utc,
          v_now_utc,
          NULL,
          NULL
        );

        SELECT
          pfc.*
        INTO
          v_component_after
        FROM public.pay_finance_case_components pfc
        WHERE pfc.id = v_created_component_id;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_created_component_id,
          'COMPONENT_CREATED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          NULL,
          v_after_json,
          'COMPONENT_SYNC',
          'Created finance component from current preview/truth line set'
        );

        v_inserted_count := v_inserted_count + 1;
    END IF;
  END LOOP;

  SELECT
    round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
    round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
  INTO
    v_case_outstanding_amount,
    v_open_component_remaining_total
  FROM public.pay_advances AS pa
  LEFT JOIN public.pay_finance_case_components AS pfc
    ON pfc.finance_case_id = pa.id
  WHERE pa.id = p_finance_case_id
  GROUP BY pa.outstanding_amount;

  v_component_case_mismatch_amount := round(
    coalesce(v_case_outstanding_amount, 0) - coalesce(v_open_component_remaining_total, 0),
    2
  )::numeric(12,2);

  IF v_case_type IN (
       'OVERPAYMENT'::public.pay_finance_case_type_enum,
       'UNDERPAYMENT'::public.pay_finance_case_type_enum
     )
     AND abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
    RAISE EXCEPTION 'PAY_FINANCE_COMPONENTS_CASE_OUTSTANDING_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_FINANCE_COMPONENTS_CASE_OUTSTANDING_MISMATCH',
              'finance_case_id', p_finance_case_id::text,
              'case_type', CASE WHEN v_case_type IS NULL THEN NULL ELSE v_case_type::text END,
              'case_outstanding_amount', coalesce(v_case_outstanding_amount, 0),
              'open_component_remaining_total', coalesce(v_open_component_remaining_total, 0),
              'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
              'raw_input_component_count', coalesce(v_raw_input_component_count, 0),
              'input_component_count', coalesce(v_input_component_count, 0),
              'aggregated_duplicate_identity_count', coalesce(v_aggregated_duplicate_identity_count, 0),
              'case_active_consumed_amount', coalesce(v_case_active_consumed_amount, 0),
              'case_active_reserved_source_amount', coalesce(v_case_active_reserved_source_amount, 0),
              'message', 'Finance-case outstanding does not reconcile to the open component remaining-source total after component synchronisation.'
            )::text;
  END IF;

  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', pfc.id::text,
          'finance_case_id', pfc.finance_case_id::text,
          'candidate_id', pfc.candidate_id::text,
          'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
          'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
          'source_family_key', pfc.source_family_key,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
          'is_resolution_stale', pfc.is_resolution_stale,
          'stale_reason', pfc.stale_reason,
          'allocation_priority_group', pfc.allocation_priority_group,
          'allocation_priority_order', pfc.allocation_priority_order,
          'created_at_utc', pfc.created_at_utc,
          'updated_at_utc', pfc.updated_at_utc
        )
        ORDER BY
          pfc.source_family_key,
          pfc.allocation_priority_group,
          pfc.allocation_priority_order,
          pfc.component_key_type,
          pfc.component_key_value
      ),
      '[]'::jsonb
    )
  INTO
    v_open_components_json
  FROM public.pay_finance_case_components pfc
  WHERE pfc.finance_case_id = p_finance_case_id
    AND pfc.closed_at_utc IS NULL;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'inserted_count', v_inserted_count,
      'updated_count', v_updated_count,
      'reopened_count', v_reopened_count,
      'closed_count', v_closed_count,
      'stale_marked_count', v_stale_marked_count,
      'protected_skip_count', v_protected_skip_count,
      'active_reservation_deferred_count', v_active_reservation_deferred_count,
      'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
      'normalized_input_component_count', COALESCE(v_input_component_count, 0),
      'aggregated_duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0)
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'inserted_count', v_inserted_count,
    'updated_count', v_updated_count,
    'reopened_count', v_reopened_count,
    'closed_count', v_closed_count,
    'stale_marked_count', v_stale_marked_count,
    'protected_skip_count', v_protected_skip_count,
    'active_reservation_deferred_count', v_active_reservation_deferred_count,
    'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
    'normalized_input_component_count', COALESCE(v_input_component_count, 0),
    'aggregated_duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0),
    'case_outstanding_amount', coalesce(v_case_outstanding_amount, 0),
    'open_component_remaining_total', coalesce(v_open_component_remaining_total, 0),
    'component_case_mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
    'component_case_reconciled', abs(coalesce(v_component_case_mismatch_amount, 0)) <= 0.01,
    'open_components', v_open_components_json
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_finance_components',
      COALESCE(p_finance_case_id::text, 'NO_FINANCE_CASE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
END;
$function$;

-- pay_finance_ledger_export_rows(uuid,date,date,text,uuid,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_finance_ledger_export_rows(p_actor_user_id uuid DEFAULT NULL::uuid, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_status text DEFAULT 'ALL'::text, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_case_type text DEFAULT NULL::text, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := upper(btrim(coalesce(p_status, 'ALL')));
  v_case_type text := upper(nullif(btrim(coalesce(p_case_type, '')), ''));
  v_sort_key text := lower(coalesce(nullif(btrim(p_sort_key), ''), 'created_at'));
  v_sort_dir text := lower(coalesce(nullif(btrim(p_sort_dir), ''), 'desc'));
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_meta jsonb := '{}'::jsonb;
BEGIN
  IF v_status NOT IN ('ALL', 'OUTSTANDING', 'FULLY_PAID') THEN
    v_status := 'ALL';
  END IF;

  IF v_sort_key NOT IN (
    'created_at',
    'candidate',
    'client',
    'case_type',
    'outstanding_amount',
    'next_due_week_start'
  ) THEN
    v_sort_key := 'created_at';
  END IF;

  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  WITH base_rows AS (
    SELECT
      vfcr.finance_case_id,
      vfcr.case_type,
      CASE vfcr.case_type
        WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance'
        WHEN 'OVERPAYMENT' THEN 'Overpayment'
        WHEN 'UNDERPAYMENT' THEN 'Underpayment'
        WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment'
        WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
        ELSE coalesce(vfcr.case_type::text, 'Finance Case')
      END AS row_label,
      CASE vfcr.case_type
        WHEN 'PAYMENT_ADVANCE' THEN 'PAYMENT_ADVANCE'
        WHEN 'OVERPAYMENT' THEN 'OVERPAYMENT'
        WHEN 'UNDERPAYMENT' THEN 'UNDERPAYMENT'
        WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'MANUAL_DEBT_ADJUSTMENT'
        WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'MANUAL_CREDIT_ADJUSTMENT'
        ELSE 'OTHER'
      END AS row_group,
      cs.tms_ref AS candidate_tms_ref,
      cs.tms_ref_num AS candidate_tms_ref_num,
      cs.first_name AS candidate_first_name,
      cs.last_name AS candidate_last_name,
      coalesce(cs.display_name, vfcr.candidate_display_name) AS candidate_display_name,
      vfcr.pay_method,
      vfcr.client_name,
      ts.booking_id AS linked_timesheet_booking_id,
      ts.week_ending_date AS linked_timesheet_week_ending_date,
      ts.shift_label_norm AS linked_timesheet_shift_label_norm,
      ts.reference_number AS linked_timesheet_reference_number,
      vfcr.linked_shift_date,
      vfcr.created_at,
      vfcr.updated_at,
      coalesce(nullif(btrim(coalesce(u_created.display_name, u_created.email, '')), ''), 'CloudTMS server') AS created_by_display,
      coalesce(vfcr.status::text, '') AS finance_status,
      coalesce(vfcr.payout_status::text, '') AS payout_status,
      CASE
        WHEN vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' THEN
          CASE
            WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'PAID' THEN 'FULLY_PAID'
            WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'CANCELLED' THEN 'CANCELLED'
            ELSE 'OUTSTANDING'
          END
        ELSE
          CASE
            WHEN vfcr.written_off_at_utc IS NOT NULL THEN 'WRITTEN_OFF'
            WHEN round(norm.outstanding_amount_norm, 2) > 0 THEN 'OUTSTANDING'
            ELSE 'FULLY_PAID'
          END
      END AS ledger_status,
      round(norm.original_amount_norm, 2) AS original_amount,
      round(norm.outstanding_amount_norm, 2) AS outstanding_amount,
      round(norm.weekly_due_norm, 2) AS weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      norm.schedule_json_norm AS schedule_json,
      vfcr.adjustment_comment,
      round(norm.source_original_paid_amount_norm, 2) AS source_original_paid_amount,
      round(norm.source_corrected_paid_amount_norm, 2) AS source_corrected_paid_amount,
      round(norm.minimum_earnings_threshold_norm, 2) AS minimum_earnings_threshold,
      round(norm.take_home_floor_override_norm, 2) AS take_home_floor_override,
      vfcr.baseline_signature,
      round(norm.best_guess_hours_norm, 2) AS best_guess_hours,
      vfcr.notes,
      vfcr.written_off_at_utc,
      coalesce(nullif(btrim(coalesce(u_written_off.display_name, u_written_off.email, '')), ''), NULL) AS written_off_by_display,
      vfcr.write_off_reason,
      vfcr.cleared_at_utc,
      coalesce(nullif(btrim(coalesce(u_cleared.display_name, u_cleared.email, '')), ''), NULL) AS cleared_by_display,
      round(norm.active_reserved_amount_norm, 2) AS active_reserved_amount,
      round(norm.reserved_amount_norm, 2) AS reserved_amount,
      round(norm.committed_amount_norm, 2) AS committed_amount,
      round(norm.settled_amount_norm, 2) AS settled_amount,
      round(norm.released_amount_norm, 2) AS released_amount,
      norm.active_reservation_count_norm AS active_reservation_count,
      vfcr.latest_reservation_created_at_utc,
      vfcr.latest_committed_at_utc,
      vfcr.latest_settled_at_utc,
      vfcr.latest_released_at_utc,
      vfcr.latest_recovery_pay_date,
      vfcr.latest_remittance_sent_at_utc,
      vfcr.latest_remittance_trigger_status,
      vfcr.last_remittance_error,
      vfcr.active_snooze_kind,
      CASE
        WHEN vfcr.active_snooze_kind IS NULL THEN NULL
        WHEN vfcr.active_snooze_until_date IS NULL THEN 'INDEFINITE'
        ELSE 'DATED'
      END AS active_snooze_mode,
      vfcr.active_snooze_until_date,
      vfcr.active_snooze_note,
      vfcr.active_snooze_created_at_utc,
      vfcr.active_snooze_updated_at_utc,
      CASE
        WHEN vfcr.active_snooze_kind IS NULL THEN NULL
        WHEN vfcr.active_snooze_until_date IS NULL THEN 'INDEFINITE_DEFERRED'
        ELSE 'ACTIVE'
      END AS active_snooze_visibility_status,
      norm.is_mixed_case_norm AS is_mixed_case,
      norm.open_taxable_count_norm AS open_taxable_count,
      norm.open_reimbursement_count_norm AS open_reimbursement_count,
      norm.unresolved_taxable_count_norm AS unresolved_taxable_count,
      norm.stale_count_norm AS stale_count,
      norm.component_resolution_summary_json_norm AS component_resolution_summary_json
    FROM public.v_finance_cases_register AS vfcr
    LEFT JOIN public.candidates_summary AS cs
      ON cs.id = vfcr.candidate_id
    LEFT JOIN public.timesheets AS ts
      ON ts.timesheet_id = vfcr.linked_timesheet_id
     AND ts.is_current IS TRUE
    LEFT JOIN public.tms_users AS u_created
      ON u_created.id = vfcr.created_by
    LEFT JOIN public.tms_users AS u_written_off
      ON u_written_off.id = vfcr.written_off_by_user_id
    LEFT JOIN public.tms_users AS u_cleared
      ON u_cleared.id = vfcr.cleared_by_user_id
    LEFT JOIN LATERAL (
      WITH normalized AS (
        SELECT
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN false
            WHEN lower(nullif(btrim(vfcr.is_mixed_case::text, '"'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
            ELSE false
          END AS is_mixed_case_norm,
          CASE
            WHEN nullif(btrim(vfcr.original_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.original_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS original_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.outstanding_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.outstanding_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS outstanding_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.weekly_due::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.weekly_due::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS weekly_due_norm,
          CASE
            WHEN nullif(btrim(vfcr.source_original_paid_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.source_original_paid_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS source_original_paid_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.source_corrected_paid_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.source_corrected_paid_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS source_corrected_paid_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.minimum_earnings_threshold::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.minimum_earnings_threshold::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS minimum_earnings_threshold_norm,
          CASE
            WHEN nullif(btrim(vfcr.take_home_floor_override::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.take_home_floor_override::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS take_home_floor_override_norm,
          CASE
            WHEN nullif(btrim(vfcr.best_guess_hours::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.best_guess_hours::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS best_guess_hours_norm,
          CASE
            WHEN nullif(btrim(vfcr.active_reserved_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.active_reserved_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS active_reserved_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.reserved_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.reserved_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS reserved_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.committed_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.committed_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS committed_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.settled_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.settled_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS settled_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.released_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.released_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS released_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.active_reservation_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.active_reservation_count::text, '"'), '')::integer
            ELSE 0
          END AS active_reservation_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.open_taxable_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.open_taxable_count::text, '"'), '')::integer
            ELSE 0
          END AS open_taxable_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.open_reimbursement_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.open_reimbursement_count::text, '"'), '')::integer
            ELSE 0
          END AS open_reimbursement_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.unresolved_taxable_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.unresolved_taxable_count::text, '"'), '')::integer
            ELSE 0
          END AS unresolved_taxable_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.stale_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.stale_count::text, '"'), '')::integer
            ELSE 0
          END AS stale_count_norm,
          CASE
            WHEN vfcr.schedule_json IS NULL THEN '[]'::jsonb
            WHEN jsonb_typeof(to_jsonb(vfcr.schedule_json)) IN ('object', 'array') THEN to_jsonb(vfcr.schedule_json)
            ELSE '[]'::jsonb
          END AS schedule_json_norm
      )
      SELECT
        normalized.is_mixed_case_norm,
        normalized.original_amount_norm,
        normalized.outstanding_amount_norm,
        normalized.weekly_due_norm,
        normalized.source_original_paid_amount_norm,
        normalized.source_corrected_paid_amount_norm,
        normalized.minimum_earnings_threshold_norm,
        normalized.take_home_floor_override_norm,
        normalized.best_guess_hours_norm,
        normalized.active_reserved_amount_norm,
        normalized.reserved_amount_norm,
        normalized.committed_amount_norm,
        normalized.settled_amount_norm,
        normalized.released_amount_norm,
        normalized.active_reservation_count_norm,
        normalized.open_taxable_count_norm,
        normalized.open_reimbursement_count_norm,
        normalized.unresolved_taxable_count_norm,
        normalized.stale_count_norm,
        normalized.schedule_json_norm,
        CASE
          WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN jsonb_build_object(
            'open_taxable_count', 0,
            'open_reimbursement_count', 0,
            'unresolved_taxable_count', 0,
            'stale_count', 0,
            'is_mixed_case', false
          )
          WHEN vfcr.component_resolution_summary_json IS NULL THEN jsonb_build_object(
            'open_taxable_count', normalized.open_taxable_count_norm,
            'open_reimbursement_count', normalized.open_reimbursement_count_norm,
            'unresolved_taxable_count', normalized.unresolved_taxable_count_norm,
            'stale_count', normalized.stale_count_norm,
            'is_mixed_case', normalized.is_mixed_case_norm
          )
          WHEN jsonb_typeof(to_jsonb(vfcr.component_resolution_summary_json)) IN ('object', 'array') THEN to_jsonb(vfcr.component_resolution_summary_json)
          ELSE jsonb_build_object(
            'open_taxable_count', normalized.open_taxable_count_norm,
            'open_reimbursement_count', normalized.open_reimbursement_count_norm,
            'unresolved_taxable_count', normalized.unresolved_taxable_count_norm,
            'stale_count', normalized.stale_count_norm,
            'is_mixed_case', normalized.is_mixed_case_norm
          )
        END AS component_resolution_summary_json_norm
      FROM normalized
    ) AS norm ON TRUE
    WHERE
      (p_created_from IS NULL OR vfcr.created_at::date >= p_created_from)
      AND (p_created_to IS NULL OR vfcr.created_at::date <= p_created_to)
      AND (p_candidate_id IS NULL OR vfcr.candidate_id = p_candidate_id)
      AND (p_client_id IS NULL OR vfcr.client_id = p_client_id)
      AND (v_case_type IS NULL OR upper(coalesce(vfcr.case_type::text, '')) = v_case_type)
  ),
  filtered_rows AS (
    SELECT
      br.*
    FROM base_rows AS br
    WHERE
      v_status = 'ALL'
      OR (v_status = 'OUTSTANDING' AND br.ledger_status = 'OUTSTANDING')
      OR (v_status = 'FULLY_PAID' AND br.ledger_status = 'FULLY_PAID')
  ),
  ordered_rows AS (
    SELECT
      fr.*
    FROM filtered_rows AS fr
    ORDER BY
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'asc' THEN fr.created_at END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'desc' THEN fr.created_at END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.candidate_display_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.candidate_display_name, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.client_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.client_name, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'case_type' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.case_type::text, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'case_type' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.case_type::text, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'outstanding_amount' AND v_sort_dir = 'asc' THEN fr.outstanding_amount END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'outstanding_amount' AND v_sort_dir = 'desc' THEN fr.outstanding_amount END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'next_due_week_start' AND v_sort_dir = 'asc' THEN fr.next_due_week_start END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'next_due_week_start' AND v_sort_dir = 'desc' THEN fr.next_due_week_start END DESC NULLS LAST,
      fr.created_at DESC,
      lower(coalesce(fr.candidate_display_name, '')) ASC
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'row_group', orw.row_group,
          'case_type', orw.case_type,
          'row_label', orw.row_label,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_tms_ref_num', orw.candidate_tms_ref_num,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'candidate_display_name', orw.candidate_display_name,
          'pay_method', orw.pay_method,
          'client_name', orw.client_name,
          'linked_timesheet_booking_id', orw.linked_timesheet_booking_id,
          'linked_timesheet_week_ending_date', CASE WHEN orw.linked_timesheet_week_ending_date IS NULL THEN NULL ELSE orw.linked_timesheet_week_ending_date::text END,
          'linked_timesheet_shift_label_norm', orw.linked_timesheet_shift_label_norm,
          'linked_timesheet_reference_number', orw.linked_timesheet_reference_number,
          'linked_shift_date', CASE WHEN orw.linked_shift_date IS NULL THEN NULL ELSE orw.linked_shift_date::text END,
          'created_at', CASE WHEN orw.created_at IS NULL THEN NULL ELSE orw.created_at::text END,
          'updated_at', CASE WHEN orw.updated_at IS NULL THEN NULL ELSE orw.updated_at::text END
        )
        || jsonb_build_object(
          'created_by_display', orw.created_by_display,
          'finance_status', orw.finance_status,
          'payout_status', orw.payout_status,
          'ledger_status', orw.ledger_status,
          'original_amount', orw.original_amount,
          'outstanding_amount', orw.outstanding_amount,
          'weekly_due', orw.weekly_due,
          'weeks_total', orw.weeks_total,
          'start_week_start', CASE WHEN orw.start_week_start IS NULL THEN NULL ELSE orw.start_week_start::text END,
          'next_due_week_start', CASE WHEN orw.next_due_week_start IS NULL THEN NULL ELSE orw.next_due_week_start::text END,
          'schedule_json', orw.schedule_json,
          'adjustment_comment', orw.adjustment_comment,
          'source_original_paid_amount', orw.source_original_paid_amount,
          'source_corrected_paid_amount', orw.source_corrected_paid_amount,
          'minimum_earnings_threshold', orw.minimum_earnings_threshold,
          'take_home_floor_override', orw.take_home_floor_override,
          'baseline_signature', orw.baseline_signature,
          'best_guess_hours', orw.best_guess_hours
        )
        || jsonb_build_object(
          'notes', orw.notes,
          'written_off_at_utc', CASE WHEN orw.written_off_at_utc IS NULL THEN NULL ELSE orw.written_off_at_utc::text END,
          'written_off_by_display', orw.written_off_by_display,
          'write_off_reason', orw.write_off_reason,
          'cleared_at_utc', CASE WHEN orw.cleared_at_utc IS NULL THEN NULL ELSE orw.cleared_at_utc::text END,
          'cleared_by_display', orw.cleared_by_display,
          'active_reserved_amount', orw.active_reserved_amount,
          'reserved_amount', orw.reserved_amount,
          'committed_amount', orw.committed_amount,
          'settled_amount', orw.settled_amount,
          'released_amount', orw.released_amount,
          'active_reservation_count', orw.active_reservation_count,
          'latest_reservation_created_at_utc', CASE WHEN orw.latest_reservation_created_at_utc IS NULL THEN NULL ELSE orw.latest_reservation_created_at_utc::text END,
          'latest_committed_at_utc', CASE WHEN orw.latest_committed_at_utc IS NULL THEN NULL ELSE orw.latest_committed_at_utc::text END,
          'latest_settled_at_utc', CASE WHEN orw.latest_settled_at_utc IS NULL THEN NULL ELSE orw.latest_settled_at_utc::text END,
          'latest_released_at_utc', CASE WHEN orw.latest_released_at_utc IS NULL THEN NULL ELSE orw.latest_released_at_utc::text END
        )
        || jsonb_build_object(
          'latest_recovery_pay_date', CASE WHEN orw.latest_recovery_pay_date IS NULL THEN NULL ELSE orw.latest_recovery_pay_date::text END,
          'latest_remittance_sent_at_utc', CASE WHEN orw.latest_remittance_sent_at_utc IS NULL THEN NULL ELSE orw.latest_remittance_sent_at_utc::text END,
          'latest_remittance_trigger_status', orw.latest_remittance_trigger_status,
          'last_remittance_error', orw.last_remittance_error,
          'active_snooze_kind', orw.active_snooze_kind,
          'active_snooze_mode', orw.active_snooze_mode,
          'active_snooze_until_date', CASE WHEN orw.active_snooze_until_date IS NULL THEN NULL ELSE orw.active_snooze_until_date::text END,
          'active_snooze_note', orw.active_snooze_note,
          'active_snooze_created_at_utc', CASE WHEN orw.active_snooze_created_at_utc IS NULL THEN NULL ELSE orw.active_snooze_created_at_utc::text END,
          'active_snooze_updated_at_utc', CASE WHEN orw.active_snooze_updated_at_utc IS NULL THEN NULL ELSE orw.active_snooze_updated_at_utc::text END,
          'active_snooze_visibility_status', orw.active_snooze_visibility_status,
          'is_mixed_case', orw.is_mixed_case,
          'open_taxable_count', orw.open_taxable_count,
          'open_reimbursement_count', orw.open_reimbursement_count,
          'unresolved_taxable_count', orw.unresolved_taxable_count,
          'stale_count', orw.stale_count,
          'component_resolution_summary_json', orw.component_resolution_summary_json
        )
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'total_count', count(*)::int,
      'outstanding_count', count(*) FILTER (WHERE orw.ledger_status = 'OUTSTANDING')::int,
      'fully_paid_count', count(*) FILTER (WHERE orw.ledger_status = 'FULLY_PAID')::int,
      'payment_advance_count', count(*) FILTER (WHERE orw.case_type = 'PAYMENT_ADVANCE')::int,
      'overpayment_count', count(*) FILTER (WHERE orw.case_type = 'OVERPAYMENT')::int,
      'underpayment_count', count(*) FILTER (WHERE orw.case_type = 'UNDERPAYMENT')::int,
      'manual_debt_adjustment_count', count(*) FILTER (WHERE orw.case_type = 'MANUAL_DEBT_ADJUSTMENT')::int,
      'manual_credit_adjustment_count', count(*) FILTER (WHERE orw.case_type = 'MANUAL_CREDIT_ADJUSTMENT')::int,
      'original_amount_total', round(coalesce(sum(orw.original_amount), 0), 2),
      'outstanding_amount_total', round(coalesce(sum(orw.outstanding_amount), 0), 2),
      'active_reserved_amount_total', round(coalesce(sum(orw.active_reserved_amount), 0), 2),
      'mixed_case_count', count(*) FILTER (WHERE orw.is_mixed_case = true)::int,
      'open_taxable_count_total', coalesce(sum(orw.open_taxable_count), 0)::int,
      'open_reimbursement_count_total', coalesce(sum(orw.open_reimbursement_count), 0)::int,
      'unresolved_taxable_count_total', coalesce(sum(orw.unresolved_taxable_count), 0)::int,
      'stale_count_total', coalesce(sum(orw.stale_count), 0)::int
    )
  INTO v_rows, v_summary
  FROM ordered_rows AS orw;

  v_meta := jsonb_build_object(
    'title', 'Finance Ledger',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'applied_filters', jsonb_build_object(
      'created_from', CASE WHEN p_created_from IS NULL THEN NULL ELSE p_created_from::text END,
      'created_to', CASE WHEN p_created_to IS NULL THEN NULL ELSE p_created_to::text END,
      'status', v_status,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'case_type', v_case_type,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Finance Ledger',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'meta', v_meta,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

-- pay_finance_ledger_pdf_payload(uuid,date,date,text,uuid,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_finance_ledger_pdf_payload(p_actor_user_id uuid DEFAULT NULL::uuid, p_created_from date DEFAULT NULL::date, p_created_to date DEFAULT NULL::date, p_status text DEFAULT 'ALL'::text, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_case_type text DEFAULT NULL::text, p_sort_key text DEFAULT 'created_at'::text, p_sort_dir text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
BEGIN
  v_base := public.pay_finance_ledger_export_rows(
    p_actor_user_id => p_actor_user_id,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_status => p_status,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_case_type => p_case_type,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  SELECT jsonb_build_array(
    jsonb_build_object(
      'row_group', 'PAYMENT_ADVANCE',
      'title', 'Payment Advances',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'PAYMENT_ADVANCE'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'OVERPAYMENT',
      'title', 'Overpayments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'OVERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'MANUAL_DEBT_ADJUSTMENT',
      'title', 'Manual Debt Adjustments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'UNDERPAYMENT',
      'title', 'Underpayments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'UNDERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'MANUAL_CREDIT_ADJUSTMENT',
      'title', 'Manual Credit Adjustments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'), '[]'::jsonb)
    )
  )
  INTO v_groups;

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Finance Ledger',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'groups', coalesce(v_groups, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

-- pay_finance_payout_notice_build(uuid)
CREATE OR REPLACE FUNCTION public.pay_finance_payout_notice_build(p_pay_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch_id uuid := p_pay_batch_id;
  v_batch record;
  v_jobs jsonb := '[]'::jsonb;
begin
  if v_batch_id is null then
    raise exception 'pay_finance_payout_notice_build: pay_batch_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.authoritative_payment_date,
    pb.pay_date,
    pb.bulk_reference,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot
  into v_batch
  from public.pay_batches pb
  where pb.id = v_batch_id;

  if v_batch.id is null then
    raise exception 'pay_finance_payout_notice_build: pay batch % not found.', v_batch_id;
  end if;

  with payout_items as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      c.display_name,
      c.first_name,
      c.last_name,
      c.email,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      pbi.description,
      pbi.amount_ex_vat,
      pbi.amount_vat,
      pbi.amount_inc_vat,
      pbi.finance_case_id,
      pa.case_type,
      pa.adjustment_comment,
      pa.schedule_json,
      pa.weekly_due,
      pa.weeks_total,
      pa.start_week_start,
      pa.next_due_week_start,
      pa.outstanding_amount,
      pa.notes
    from public.pay_batch_candidates pbc
    join public.candidates c
      on c.id = pbc.candidate_id
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.pay_advances pa
      on pa.id = pbi.finance_case_id
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT')
  ),
  items_grouped as (
    select
      pi.candidate_id,
      max(pi.display_name) as display_name,
      max(pi.first_name) as first_name,
      max(pi.last_name) as last_name,
      max(pi.email) as email,
      jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', pi.pay_batch_item_id::text,
          'finance_case_id', case when pi.finance_case_id is null then null else pi.finance_case_id::text end,
          'case_type', case
            when pi.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum then 'PAYMENT_ADVANCE'
            when pi.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then 'MANUAL_CREDIT_ADJUSTMENT'
            when pi.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then 'UNDERPAYMENT'
            else null
          end,
          'label', case
            when pi.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
            when pi.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
            when pi.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment Payment'
            else coalesce(nullif(btrim(pi.description), ''), 'Payment')
          end,
          'amount', round(coalesce(pi.amount_inc_vat, pi.amount_ex_vat, 0), 2),
          'amount_ex_vat', round(coalesce(pi.amount_ex_vat, 0), 2),
          'scheduled_payment_date', coalesce(v_batch.authoritative_payment_date, v_batch.pay_date),
          'repayment_arrangement', case
            when pi.item_type = 'LOAN_PAYOUT' then jsonb_build_object(
              'weekly_due', pi.weekly_due,
              'weeks_total', pi.weeks_total,
              'start_week_start', case when pi.start_week_start is null then null else pi.start_week_start::text end,
              'next_due_week_start', case when pi.next_due_week_start is null then null else pi.next_due_week_start::text end,
              'schedule_json', coalesce(pi.schedule_json, '[]'::jsonb),
              'remaining_outstanding_amount', pi.outstanding_amount
            )
            else null
          end,
          'adjustment_comment', case
            when pi.item_type in ('MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT') then nullif(btrim(coalesce(pi.adjustment_comment, '')), '')
            else null
          end,
          'notes', nullif(btrim(coalesce(pi.notes, '')), '')
        )
        order by pi.pay_batch_item_id
      ) as items_json,
      round(sum(round(coalesce(pi.amount_inc_vat, pi.amount_ex_vat, 0), 2)), 2) as total_amount
    from payout_items pi
    group by pi.candidate_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', ig.candidate_id::text,
        'recipient_name', coalesce(nullif(btrim(ig.display_name), ''), nullif(btrim(trim(coalesce(ig.first_name, '') || ' ' || coalesce(ig.last_name, ''))), ''), 'Worker'),
        'recipient_email', ig.email,
        'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
        'subject', case
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Payment Advance' then 'Payment Advance scheduled'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Manual Credit Adjustment' then 'Manual Credit Adjustment scheduled'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Underpayment Payment' then 'Underpayment Payment scheduled'
          else 'Payment scheduled'
        end,
        'worker_message', case
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Payment Advance' then 'A Payment Advance has been scheduled.'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Manual Credit Adjustment' then 'A Manual Credit Adjustment has been scheduled.'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Underpayment Payment' then 'An Underpayment Payment has been scheduled.'
          else 'A payment has been scheduled.'
        end,
        'total_amount', ig.total_amount,
        'items', ig.items_json,
        'batch', jsonb_build_object(
          'pay_batch_id', v_batch.id::text,
          'status', v_batch.status,
          'batch_kind_fixed', v_batch.batch_kind_fixed,
          'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'bulk_reference', v_batch.bulk_reference,
          'rail_provider_snapshot', v_batch.rail_provider_snapshot,
          'rail_env_snapshot', v_batch.rail_env_snapshot
        )
      )
      order by ig.candidate_id
    ),
    '[]'::jsonb
  )
  into v_jobs
  from items_grouped ig
  where nullif(btrim(coalesce(ig.email, '')), '') is not null;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch.id::text,
    'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'jobs', coalesce(v_jobs, '[]'::jsonb)
  );
end;
$function$;

-- pay_finance_payout_notice_queue_commit_stage(uuid,uuid,boolean,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_finance_payout_notice_queue_commit_stage(p_pay_batch_id uuid, p_actor_user_id uuid, p_only_confirmed boolean DEFAULT false, p_operation_id uuid DEFAULT NULL::uuid, p_remittance_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch record;
  v_build_result jsonb := '{}'::jsonb;
  v_build_jobs jsonb := '[]'::jsonb;
  v_filtered_jobs jsonb := '[]'::jsonb;
  v_candidate_results jsonb := '[]'::jsonb;
  v_job_results jsonb := '[]'::jsonb;

  v_job jsonb;
  v_work_job jsonb;
  v_job_kind text;
  v_recipient_email text;
  v_candidate_id_text text;
  v_candidate_id uuid;

  v_pruned_job_items jsonb := '[]'::jsonb;
  v_pruned_job_total numeric := 0;
  v_pruned_job_item_count integer := 0;
  v_first_label text := null;
  v_subject text := null;
  v_worker_message text := null;
  v_queue_context jsonb := '{}'::jsonb;
  v_queue_reference text := null;

  v_target_candidate_count integer := 0;
  v_ready_candidate_count integer := 0;
  v_job_count integer := 0;
  v_trigger_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_already_queued_count integer := 0;
  v_inserted_outbox_count integer := 0;
  v_reused_outbox_count integer := 0;
  v_skipped_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_count integer := 0;
  v_has_more boolean := false;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_operation_job_results jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: actor_user_id is required';
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'only_confirmed', COALESCE(p_only_confirmed, false)
    ),
    'pay_finance_payout_notice',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.bulk_reference,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  if v_batch.settlement_confirmation_json is not null and jsonb_typeof(v_batch.settlement_confirmation_json) = 'object' then
    v_settlement_confirmation_json := v_batch.settlement_confirmation_json;
  else
    v_settlement_confirmation_json := '{}'::jsonb;
  end if;

  v_suppress_remittances := lower(btrim(coalesce(
    v_settlement_confirmation_json->>'suppress_remittances',
    v_execution_intent_json->>'suppress_remittances',
    'false'
  ))) in ('true','1','yes','y','on');

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode requires p_operation_id';
    END IF;
    IF p_remittance_scope_ids IS NULL OR jsonb_typeof(p_remittance_scope_ids) <> 'array' OR jsonb_array_length(p_remittance_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode requires non-empty p_remittance_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % is not payout-notice-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % belongs to a different actor', p_operation_id;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode received invalid or duplicate remittance scope ids';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'QUEUED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'FAILED')::integer,
           COALESCE(jsonb_agg(to_jsonb(selected_scope.id::text) ORDER BY selected_scope.id::text), '[]'::jsonb)
    INTO v_matched_scope_count,
         v_already_queued_count,
         v_skipped_count,
         v_failed_count,
         v_operation_scope_ids
    FROM selected_scope;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    IF v_suppress_remittances = true THEN
      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), skipped_scope AS (
        UPDATE public.banking_pay_operation_remittance_scope AS scope_update
        SET status = 'SKIPPED',
            payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
              'skip_reason', 'SUPPRESSED_BY_EXECUTION_INTENT',
              'skipped_at_utc', now()::text
            )),
            updated_at_utc = now()
        FROM requested_scope
        WHERE scope_update.id = requested_scope.remittance_scope_id
          AND scope_update.operation_id = p_operation_id
          AND scope_update.pay_batch_id = p_pay_batch_id
          AND scope_update.status IN ('PENDING', 'FAILED')
        RETURNING scope_update.id
      ), selected_scope_after AS (
        SELECT scope_row.status
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      )
      SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'QUEUED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
      INTO v_already_queued_count,
           v_skipped_count,
           v_failed_count
      FROM selected_scope_after;

      SELECT COUNT(*)::integer
      INTO v_remaining_count
      FROM public.banking_pay_operation_remittance_scope AS remaining_scope
      WHERE remaining_scope.operation_id = p_operation_id
        AND remaining_scope.pay_batch_id = p_pay_batch_id
        AND remaining_scope.status = 'PENDING';

      v_has_more := COALESCE(v_remaining_count, 0) > 0;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;

      RETURN jsonb_build_object(
        'ok', true,
        'operation_mode', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
        'message_kind', 'PAYOUT_NOTICE',
        'queued_count', 0,
        'reused_count', COALESCE(v_already_queued_count, 0),
        'skipped_count', COALESCE(v_skipped_count, 0),
        'failed_count', COALESCE(v_failed_count, 0),
        'remaining', COALESCE(v_remaining_count, 0),
        'has_more', v_has_more,
        'dispatch_required', false,
        'remittance_scope_ids', COALESCE(v_operation_scope_ids, '[]'::jsonb),
        'job_results', '[]'::jsonb
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_payout_notice_targets;
    CREATE TEMPORARY TABLE pg_temp.tmp_operation_payout_notice_targets AS
    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), payload_item_ids AS (
      SELECT selected_scope.id AS remittance_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM selected_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(selected_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), eligible_item_rows AS (
      SELECT
        selected_scope.id AS remittance_scope_id,
        selected_scope.status AS scope_status,
        pbc.id AS pay_batch_candidate_id,
        pbc.candidate_id,
        pbi.id AS pay_batch_item_id,
        pbi.finance_case_id,
        pbi.item_type,
        pbi.description,
        pbi.amount_inc_vat,
        pbi.amount_ex_vat,
        pbi.payout_instruction_snapshot_json,
        pbi.pay_bank_transfer_id,
        pbi.source_ref,
        pbi.operation_source_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), ''),
          NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), ''),
          CASE
            WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), '^carry_forward:', '', 'i')
            WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), '^carry_forward:', '', 'i')
            ELSE NULL
          END
        ) AS manual_adjustment_carry_forward_id,
        CASE
          WHEN pbi.item_type = 'LOAN_PAYOUT' THEN 'Payment Advance'
          WHEN pbi.item_type = 'MANUAL_CREDIT_PAYOUT' THEN 'Manual Credit Adjustment'
          ELSE COALESCE(NULLIF(BTRIM(COALESCE(pbi.description, '')), ''), 'Payment')
        END AS item_label,
        pa_payout.case_type,
        pa_payout.payout_status,
        pa_payout.payout_pay_batch_id,
        pa_payout.payout_transfer_id,
        pa_payout.adjustment_comment,
        pa_payout.schedule_json,
        pa_payout.weekly_due,
        pa_payout.weeks_total,
        pa_payout.start_week_start,
        pa_payout.next_due_week_start,
        pa_payout.outstanding_amount
      FROM selected_scope
      JOIN payload_item_ids
        ON payload_item_ids.remittance_scope_id = selected_scope.id
      JOIN public.pay_batch_items AS pbi
        ON pbi.id = payload_item_ids.pay_batch_item_id
      JOIN public.pay_batch_candidates AS pbc
        ON pbc.id = pbi.pay_batch_candidate_id
       AND pbc.pay_batch_id = p_pay_batch_id
      LEFT JOIN public.pay_bank_transfers AS pbt_confirm
        ON pbt_confirm.id = pbi.pay_bank_transfer_id
       AND pbt_confirm.pay_batch_id = p_pay_batch_id
      LEFT JOIN public.pay_advances AS pa_payout
        ON pa_payout.id = pbi.finance_case_id
      WHERE COALESCE(pbi.is_voided, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS payout_notice_correction
          WHERE payout_notice_correction.pay_batch_item_id = pbi.id
            AND payout_notice_correction.status = 'APPLIED'
            AND payout_notice_correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
        )
        AND (
          pbi.finance_case_id IS NOT NULL
          OR (
            pbi.item_type IN ('MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
            AND (
              NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            )
          )
        )
        AND pbi.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY')
        AND (
          (
            jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            AND upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            AND lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
            AND lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
          )
          OR (
            pbi.item_type IN ('MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
            AND (
              NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            )
          )
        )
        AND (
          COALESCE(p_only_confirmed, false) = false
          OR (
            (
              pbi.pay_bank_transfer_id IS NOT NULL
              AND EXISTS (
                SELECT 1
                FROM public._pay_rail_state_money_movement_classify(
                  pbt_confirm.status,
                  pbt_confirm.rail_state,
                  COALESCE(pbt_confirm.rail_meta_json, '{}'::jsonb),
                  COALESCE(pbt_confirm.rail_meta_json, '{}'::jsonb)
                ) AS final_paid_evidence_check
                WHERE final_paid_evidence_check.is_final_money_moved IS TRUE
              )
            )
            OR (
              pbi.pay_bank_transfer_id IS NULL
              AND (
                upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
                OR pbc.settled_at_utc IS NOT NULL
              )
            )
          )
        )
    ), grouped_targets AS (
      SELECT
        selected_scope.id AS remittance_scope_id,
        selected_scope.status,
        selected_scope.candidate_id,
        candidate_row.email AS recipient_email,
        candidate_row.display_name AS recipient_name,
        'payout_notice:pay_batch:' || p_pay_batch_id::text || ':scope:' || selected_scope.id::text || ':candidate:' || COALESCE(selected_scope.candidate_id::text, 'UNKNOWN') AS deterministic_outbox_key,
        COUNT(eligible_item_rows.pay_batch_item_id)::integer AS eligible_item_count,
        ROUND(COALESCE(SUM(COALESCE(eligible_item_rows.amount_inc_vat, eligible_item_rows.amount_ex_vat, 0)), 0), 2) AS total_amount,
        COALESCE(jsonb_agg(
          jsonb_strip_nulls(jsonb_build_object(
            'pay_batch_item_id', eligible_item_rows.pay_batch_item_id::text,
            'manual_adjustment_carry_forward_id', eligible_item_rows.manual_adjustment_carry_forward_id,
            'finance_case_id', CASE WHEN eligible_item_rows.finance_case_id IS NULL THEN NULL ELSE eligible_item_rows.finance_case_id::text END,
            'source_ref', eligible_item_rows.source_ref,
            'operation_source_key', eligible_item_rows.operation_source_key,
            'item_type', eligible_item_rows.item_type,
            'label', eligible_item_rows.item_label,
            'amount', ROUND(COALESCE(eligible_item_rows.amount_inc_vat, eligible_item_rows.amount_ex_vat, 0), 2),
            'amount_ex_vat', ROUND(COALESCE(eligible_item_rows.amount_ex_vat, 0), 2),
            'pay_bank_transfer_id', CASE WHEN eligible_item_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE eligible_item_rows.pay_bank_transfer_id::text END,
            'case_type', CASE WHEN eligible_item_rows.case_type IS NULL THEN NULL ELSE eligible_item_rows.case_type::text END,
            'adjustment_comment', eligible_item_rows.adjustment_comment,
            'repayment_arrangement', CASE
              WHEN eligible_item_rows.item_type = 'LOAN_PAYOUT' THEN jsonb_build_object(
                'weekly_due', eligible_item_rows.weekly_due,
                'weeks_total', eligible_item_rows.weeks_total,
                'start_week_start', CASE WHEN eligible_item_rows.start_week_start IS NULL THEN NULL ELSE eligible_item_rows.start_week_start::text END,
                'next_due_week_start', CASE WHEN eligible_item_rows.next_due_week_start IS NULL THEN NULL ELSE eligible_item_rows.next_due_week_start::text END,
                'schedule_json', COALESCE(eligible_item_rows.schedule_json, '[]'::jsonb),
                'remaining_outstanding_amount', eligible_item_rows.outstanding_amount
              )
              ELSE NULL
            END
          )) ORDER BY eligible_item_rows.pay_batch_item_id::text
        ) FILTER (WHERE eligible_item_rows.pay_batch_item_id IS NOT NULL), '[]'::jsonb) AS items_json,
        selected_scope.payload_json
      FROM selected_scope
      LEFT JOIN public.candidates AS candidate_row
        ON candidate_row.id = selected_scope.candidate_id
      LEFT JOIN eligible_item_rows
        ON eligible_item_rows.remittance_scope_id = selected_scope.id
      GROUP BY selected_scope.id,
               selected_scope.status,
               selected_scope.candidate_id,
               candidate_row.email,
               candidate_row.display_name,
               selected_scope.payload_json
    )
    SELECT *
    FROM grouped_targets;

    WITH skipped_not_queueable AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'SKIPPED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'skip_reason', CASE
              WHEN NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL THEN 'MISSING_PAYOUT_NOTICE_RECIPIENT_EMAIL'
              ELSE 'NO_ELIGIBLE_PAYOUT_NOTICE_ITEMS'
            END,
            'skipped_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM pg_temp.tmp_operation_payout_notice_targets AS target_row
      WHERE scope_update.id = target_row.remittance_scope_id
        AND scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.status IN ('PENDING', 'FAILED')
        AND (
          NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL
          OR COALESCE(target_row.eligible_item_count, 0) = 0
        )
      RETURNING scope_update.id
    )
    SELECT COUNT(*)::integer
    INTO v_skipped_count
    FROM skipped_not_queueable;

    WITH valid_targets AS (
      SELECT target_row.*,
             CASE
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Payment Advance' THEN 'Payment Advance scheduled'
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Manual Credit Adjustment' THEN 'Manual Credit Adjustment scheduled'
               ELSE 'Payment scheduled'
             END AS subject_text,
             CASE
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Payment Advance' THEN 'A Payment Advance has been scheduled.'
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Manual Credit Adjustment' THEN 'A Manual Credit Adjustment has been scheduled.'
               ELSE 'A payment has been scheduled.'
             END AS body_intro
      FROM pg_temp.tmp_operation_payout_notice_targets AS target_row
      WHERE target_row.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NOT NULL
        AND COALESCE(target_row.eligible_item_count, 0) > 0
    ), upserted_outbox AS (
      INSERT INTO public.mail_outbox AS mail_insert (
        type,
        "to",
        cc,
        subject,
        body_html,
        body_text,
        attachments,
        status,
        created_at_utc,
        created_by,
        reference,
        recipient_kind,
        recipient_id,
        context_kind,
        context_id,
        email_type,
        importance,
        scheduled_for_utc,
        next_attempt_at_utc,
        payment_scope_json,
        deterministic_outbox_key
      )
      SELECT
        'REMITTANCE',
        valid_targets.recipient_email,
        NULL::text,
        valid_targets.subject_text,
        '<pre>' || valid_targets.body_intro || E'

Total amount: £' || COALESCE(valid_targets.total_amount::text, '0.00') || E'

This payout notice was generated from frozen CloudTMS payment batch artefacts.</pre>',
        valid_targets.body_intro || E'

Total amount: £' || COALESCE(valid_targets.total_amount::text, '0.00') || E'

This payout notice was generated from frozen CloudTMS payment batch artefacts.',
        '[]'::jsonb,
        'QUEUED'::public.mail_status_enum,
        now(),
        p_actor_user_id,
        valid_targets.deterministic_outbox_key,
        'candidate',
        valid_targets.candidate_id,
        'pay_batches',
        p_pay_batch_id,
        'html',
        'Normal',
        now(),
        now(),
        jsonb_strip_nulls(COALESCE(valid_targets.payload_json, '{}'::jsonb) || jsonb_build_object(
          'notice_scope', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'remittance_scope_id', valid_targets.remittance_scope_id::text,
          'candidate_id', CASE WHEN valid_targets.candidate_id IS NULL THEN NULL ELSE valid_targets.candidate_id::text END,
          'deterministic_outbox_key', valid_targets.deterministic_outbox_key,
          'items', valid_targets.items_json,
          'total_amount', valid_targets.total_amount,
          'message_kind', 'PAYOUT_NOTICE'
        )),
        valid_targets.deterministic_outbox_key
      FROM valid_targets
      ON CONFLICT (deterministic_outbox_key)
      DO UPDATE
      SET status = CASE WHEN mail_insert.status::text = 'FAILED' THEN 'QUEUED'::public.mail_status_enum ELSE mail_insert.status END,
          last_error = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.last_error END,
          failed_at = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.failed_at END,
          next_attempt_at_utc = CASE WHEN mail_insert.status::text = 'FAILED' THEN now() ELSE mail_insert.next_attempt_at_utc END,
          payment_scope_json = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.payment_scope_json ELSE EXCLUDED.payment_scope_json END
      RETURNING mail_insert.id,
                mail_insert.deterministic_outbox_key,
                (xmax = 0) AS was_inserted
    ), updated_scope AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'QUEUED',
          outbox_id = upserted_outbox.id,
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'payout_notice_outbox_key', upserted_outbox.deterministic_outbox_key,
            'payout_notice_queued_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM upserted_outbox
      JOIN pg_temp.tmp_operation_payout_notice_targets AS target_row
        ON target_row.deterministic_outbox_key = upserted_outbox.deterministic_outbox_key
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.id = target_row.remittance_scope_id
        AND scope_update.status IN ('PENDING', 'FAILED')
      RETURNING scope_update.id,
                upserted_outbox.id AS outbox_id,
                upserted_outbox.deterministic_outbox_key,
                upserted_outbox.was_inserted
    )
    SELECT COUNT(*) FILTER (WHERE updated_scope.was_inserted)::integer,
           COUNT(*) FILTER (WHERE updated_scope.was_inserted IS NOT TRUE)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'remittance_scope_id', updated_scope.id::text,
             'deterministic_outbox_key', updated_scope.deterministic_outbox_key,
             'outbox_id', updated_scope.outbox_id::text,
             'queued', true,
             'reused', (updated_scope.was_inserted IS NOT TRUE)
           ) ORDER BY updated_scope.id::text), '[]'::jsonb)
    INTO v_inserted_outbox_count,
         v_reused_outbox_count,
         v_operation_job_results
    FROM updated_scope;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope_after AS (
      SELECT scope_row.status
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    )
    SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
    INTO v_skipped_count,
         v_failed_count
    FROM selected_scope_after;

    SELECT COUNT(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_remittance_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    v_has_more := COALESCE(v_remaining_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = now()
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'trigger_status', CASE WHEN COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0 THEN 'PAYOUT_NOTICE_QUEUE_CHUNK_PROCESSED' ELSE 'NO_QUEUEABLE_PAYOUT_NOTICE_SCOPE' END,
      'message_kind', 'PAYOUT_NOTICE',
      'queued_count', COALESCE(v_inserted_outbox_count, 0),
      'reused_count', COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0),
      'skipped_count', COALESCE(v_skipped_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'remaining', COALESCE(v_remaining_count, 0),
      'has_more', v_has_more,
      'dispatch_required', (COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) > 0),
      'remittance_scope_ids', COALESCE(v_operation_scope_ids, '[]'::jsonb),
      'job_results', COALESCE(v_operation_job_results, '[]'::jsonb)
    );
  END IF;

  if v_suppress_remittances = true then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
      'error', null,
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'pay_batch_id', p_pay_batch_id::text,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  SELECT COUNT(DISTINCT legacy_candidate_count.candidate_id)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  JOIN public.pay_batch_items AS legacy_payout_item
    ON legacy_payout_item.pay_batch_candidate_id = legacy_candidate_count.id
  LEFT JOIN public.pay_bank_transfers AS legacy_transfer_confirm
    ON legacy_transfer_confirm.id = legacy_payout_item.pay_bank_transfer_id
   AND legacy_transfer_confirm.pay_batch_id = p_pay_batch_id
  LEFT JOIN public.pay_advances AS legacy_payout_case
    ON legacy_payout_case.id = legacy_payout_item.finance_case_id
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND COALESCE(legacy_payout_item.is_voided, false) = false
    AND legacy_payout_item.finance_case_id IS NOT NULL
    AND legacy_payout_item.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    AND jsonb_typeof(legacy_payout_item.payout_instruction_snapshot_json) = 'object'
    AND upper(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    AND lower(btrim(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
    AND lower(btrim(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS legacy_payout_notice_correction
      WHERE legacy_payout_notice_correction.pay_batch_item_id = legacy_payout_item.id
        AND legacy_payout_notice_correction.status = 'APPLIED'
        AND legacy_payout_notice_correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND (
      COALESCE(p_only_confirmed, false) = false
      OR (
        (
          legacy_payout_item.pay_bank_transfer_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public._pay_rail_state_money_movement_classify(
              legacy_transfer_confirm.status,
              legacy_transfer_confirm.rail_state,
              COALESCE(legacy_transfer_confirm.rail_meta_json, '{}'::jsonb),
              COALESCE(legacy_transfer_confirm.rail_meta_json, '{}'::jsonb)
            ) AS legacy_final_paid_evidence_check
            WHERE legacy_final_paid_evidence_check.is_final_money_moved IS TRUE
          )
        )
        OR (
          legacy_payout_item.pay_bank_transfer_id IS NULL
          AND (
            upper(btrim(coalesce(legacy_candidate_count.settlement_status, ''))) = 'SETTLED'
            OR legacy_candidate_count.settled_at_utc IS NOT NULL
          )
        )
      )
    );

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_OPERATION_REQUIRED',
      'code', 'PAYOUT_NOTICE_OPERATION_REQUIRED',
      'message', 'pay_finance_payout_notice_queue_commit_stage legacy mode is limited to small batches; use the scalable remittance/payout notice operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  drop table if exists pg_temp.tmp_payout_notice_target_candidates;
  create temporary table pg_temp.tmp_payout_notice_target_candidates(
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    candidate_display_name text null,
    candidate_tms_ref text null
  ) on commit drop;

  drop table if exists pg_temp.tmp_payout_notice_target_items;
  create temporary table pg_temp.tmp_payout_notice_target_items(
    candidate_id uuid not null,
    finance_case_id uuid not null,
    primary key (candidate_id, finance_case_id)
  ) on commit drop;

  drop table if exists pg_temp.tmp_payout_notice_carry_forward_items;
  create temporary table pg_temp.tmp_payout_notice_carry_forward_items(
    candidate_id uuid not null,
    pay_batch_item_id uuid not null,
    item_json jsonb not null,
    amount_inc_vat numeric not null default 0,
    primary key (candidate_id, pay_batch_item_id)
  ) on commit drop;

  insert into pg_temp.tmp_payout_notice_target_items(
    candidate_id,
    finance_case_id
  )
  select distinct
    pbc.candidate_id,
    pbi.finance_case_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers pbt_confirm
    on pbt_confirm.id = pbi.pay_bank_transfer_id
   and pbt_confirm.pay_batch_id = p_pay_batch_id
  left join public.pay_advances pa_payout
    on pa_payout.id = pbi.finance_case_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_payout_notice_correction
      where ppc_payout_notice_correction.pay_batch_item_id = pbi.id
        and ppc_payout_notice_correction.status = 'APPLIED'
        and ppc_payout_notice_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.finance_case_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
    and (
      coalesce(p_only_confirmed, false) = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirm.status,
              pbt_confirm.rail_state,
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb),
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb)
            ) as final_paid_evidence_check
            where final_paid_evidence_check.is_final_money_moved is true
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_payout_notice_carry_forward_items(
    candidate_id,
    pay_batch_item_id,
    item_json,
    amount_inc_vat
  )
  select distinct
    pbc.candidate_id,
    pbi.id,
    jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_item_id', pbi.id::text,
      'manual_adjustment_carry_forward_id', COALESCE(
        NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), ''),
        NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), ''),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), '^carry_forward:', '', 'i')
          WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), '^carry_forward:', '', 'i')
          ELSE NULL
        END
      ),
      'finance_case_id', CASE WHEN pbi.finance_case_id IS NULL THEN NULL ELSE pbi.finance_case_id::text END,
      'item_type', pbi.item_type,
      'label', COALESCE(NULLIF(BTRIM(COALESCE(pbi.description, '')), ''), 'Manual adjustment carry-forward'),
      'amount', ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2),
      'amount_ex_vat', ROUND(COALESCE(pbi.amount_ex_vat, 0), 2),
      'amount_vat', ROUND(COALESCE(pbi.amount_vat, 0), 2),
      'amount_inc_vat', ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2),
      'pay_bank_transfer_id', CASE WHEN pbi.pay_bank_transfer_id IS NULL THEN NULL ELSE pbi.pay_bank_transfer_id::text END,
      'source_ref', pbi.source_ref,
      'operation_source_key', pbi.operation_source_key,
      'case_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
      'adjustment_comment', pbi.description,
      'signed_amount_convention', 'SIGNED_AMOUNTS'
    )),
    ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2)
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers pbt_confirm
    on pbt_confirm.id = pbi.pay_bank_transfer_id
   and pbt_confirm.pay_batch_id = p_pay_batch_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
    and pbi.item_type in ('MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY')
    and (
      NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_payout_notice_carry_forward_correction
      where ppc_payout_notice_carry_forward_correction.pay_batch_item_id = pbi.id
        and ppc_payout_notice_carry_forward_correction.status = 'APPLIED'
        and ppc_payout_notice_carry_forward_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      coalesce(p_only_confirmed, false) = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirm.status,
              pbt_confirm.rail_state,
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb),
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb)
            ) as final_paid_carry_forward_check
            where final_paid_carry_forward_check.is_final_money_moved is true
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_payout_notice_target_candidates(
    pay_batch_candidate_id,
    candidate_id,
    candidate_display_name,
    candidate_tms_ref
  )
  select
    pbc.id,
    pbc.candidate_id,
    pbc.candidate_display_name,
    pbc.candidate_tms_ref
  from public.pay_batch_candidates pbc
  where pbc.pay_batch_id = p_pay_batch_id
    and (
      exists (
        select 1
        from pg_temp.tmp_payout_notice_target_items ti
        where ti.candidate_id = pbc.candidate_id
      )
      or exists (
        select 1
        from pg_temp.tmp_payout_notice_carry_forward_items cfi
        where cfi.candidate_id = pbc.candidate_id
      )
    )
    and not exists (
      select 1
      from public.mail_outbox mo
      where mo.reference = (
        'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || pbc.candidate_id::text
      )
        and upper(coalesce(mo.recipient_kind, '')) = 'CANDIDATE'
        and mo.recipient_id = pbc.candidate_id
        and lower(coalesce(mo.context_kind, '')) = 'pay_batches'
        and mo.context_id = p_pay_batch_id
    );

  select count(*)::int
  into v_target_candidate_count
  from pg_temp.tmp_payout_notice_target_candidates tc;

  if v_target_candidate_count = 0 then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'NO_ELIGIBLE_UNSENT_CANDIDATES',
      'error', null,
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
      'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  begin
    v_build_result := public.pay_finance_payout_notice_build(p_pay_batch_id);
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'PAYOUT_NOTICE_BUILD_ERROR',
      'error', left(coalesce(SQLERRM, 'pay_finance_payout_notice_build failed'), 1000),
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end;

  if coalesce((v_build_result->>'ok')::boolean, false) = false then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'PAYOUT_NOTICE_BUILD_ERROR',
      'error', left(coalesce(nullif(btrim(coalesce(v_build_result->>'error', '')), ''), 'pay_finance_payout_notice_build returned not ok'), 1000),
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  v_build_jobs := case
    when jsonb_typeof(v_build_result->'jobs') = 'array' then coalesce(v_build_result->'jobs', '[]'::jsonb)
    else '[]'::jsonb
  end;

  drop table if exists pg_temp.tmp_payout_notice_job_map;
  create temporary table pg_temp.tmp_payout_notice_job_map(
    candidate_id uuid not null,
    job_kind text not null,
    recipient_email text null
  ) on commit drop;

  for v_job in
    select j.value
    from jsonb_array_elements(v_build_jobs) as j(value)
  loop
    v_job_kind := upper(btrim(coalesce(v_job->>'job_kind', 'PAYOUT_NOTICE')));
    v_candidate_id_text := nullif(btrim(coalesce(v_job->>'candidate_id', '')), '');
    v_candidate_id := null;
    v_recipient_email := nullif(btrim(coalesce(v_job->>'recipient_email', '')), '');

    if v_candidate_id_text is not null then
      begin
        v_candidate_id := v_candidate_id_text::uuid;
      exception when invalid_text_representation then
        v_candidate_id := null;
      end;
    end if;

    if v_candidate_id is not null
       and exists (
         select 1
         from pg_temp.tmp_payout_notice_target_candidates tc
         where tc.candidate_id = v_candidate_id
       ) then
      select
        coalesce(jsonb_agg(it.value order by it.ord), '[]'::jsonb),
        round(
          coalesce(
            sum(
              case
                when btrim(coalesce(it.value->>'amount', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
                  then (it.value->>'amount')::numeric
                else 0
              end
            ),
            0
          ),
          2
        )
      into
        v_pruned_job_items,
        v_pruned_job_total
      from jsonb_array_elements(coalesce(v_job->'items', '[]'::jsonb)) with ordinality as it(value, ord)
      where nullif(btrim(coalesce(it.value->>'finance_case_id', '')), '') is not null
        and exists (
          select 1
          from pg_temp.tmp_payout_notice_target_items ti
          where ti.candidate_id = v_candidate_id
            and ti.finance_case_id::text = btrim(it.value->>'finance_case_id')
        );

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      select
        coalesce(v_pruned_job_items, '[]'::jsonb)
          || coalesce(jsonb_agg(cfi.item_json order by cfi.pay_batch_item_id::text), '[]'::jsonb),
        round(coalesce(v_pruned_job_total, 0) + coalesce(sum(cfi.amount_inc_vat), 0), 2)
      into
        v_pruned_job_items,
        v_pruned_job_total
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where cfi.candidate_id = v_candidate_id;

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      if v_pruned_job_item_count > 0 then
        v_first_label := nullif(btrim(coalesce(v_pruned_job_items->0->>'label', '')), '');

        v_subject := case
          when v_pruned_job_item_count = 1 and v_first_label = 'Payment Advance' then 'Payment Advance scheduled'
          when v_pruned_job_item_count = 1 and v_first_label = 'Manual Credit Adjustment' then 'Manual Credit Adjustment scheduled'
          else 'Payment scheduled'
        end;

        v_worker_message := case
          when v_pruned_job_item_count = 1 and v_first_label = 'Payment Advance' then 'A Payment Advance has been scheduled.'
          when v_pruned_job_item_count = 1 and v_first_label = 'Manual Credit Adjustment' then 'A Manual Credit Adjustment has been scheduled.'
          else 'A payment has been scheduled.'
        end;

        v_queue_reference := 'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || v_candidate_id::text;

        SELECT jsonb_build_object(
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'scope_kind', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'candidate_id', v_candidate_id::text,
          'pay_batch_candidate_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_candidates.pay_batch_candidate_id::text)
              FROM pg_temp.tmp_payout_notice_target_candidates AS public_tmp_payout_notice_candidates
              WHERE public_tmp_payout_notice_candidates.candidate_id = v_candidate_id
            ),
            '[]'::jsonb
          ),
          'candidate_ids', jsonb_build_array(v_candidate_id::text),
          'finance_case_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_target_items.finance_case_id::text)
              FROM pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_target_items
              WHERE public_tmp_payout_notice_target_items.candidate_id = v_candidate_id
            ),
            '[]'::jsonb
          ),
          'finance_component_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_component_scope.finance_component_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_component_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_component_scope
                ON public_pay_batch_candidates_component_scope.id = public_pay_batch_items_component_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_component_scope
                ON public_tmp_payout_notice_component_scope.candidate_id = public_pay_batch_candidates_component_scope.candidate_id
               AND public_tmp_payout_notice_component_scope.finance_case_id = public_pay_batch_items_component_scope.finance_case_id
              WHERE public_pay_batch_candidates_component_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_component_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_component_scope.finance_component_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_component_scope.is_voided, false) = false
                AND public_pay_batch_items_component_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            ),
            '[]'::jsonb
          ),
          'reservation_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_reservation_scope.reservation_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_reservation_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_reservation_scope
                ON public_pay_batch_candidates_reservation_scope.id = public_pay_batch_items_reservation_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_reservation_scope
                ON public_tmp_payout_notice_reservation_scope.candidate_id = public_pay_batch_candidates_reservation_scope.candidate_id
               AND public_tmp_payout_notice_reservation_scope.finance_case_id = public_pay_batch_items_reservation_scope.finance_case_id
              WHERE public_pay_batch_candidates_reservation_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_reservation_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_reservation_scope.reservation_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_reservation_scope.is_voided, false) = false
                AND public_pay_batch_items_reservation_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            ),
            '[]'::jsonb
          ),
          'payout_transfer_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_advances_payout_scope.payout_transfer_id::text)
              FROM public.pay_advances AS public_pay_advances_payout_scope
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_payout_scope
                ON public_tmp_payout_notice_payout_scope.finance_case_id = public_pay_advances_payout_scope.id
               AND public_tmp_payout_notice_payout_scope.candidate_id = v_candidate_id
              WHERE public_pay_advances_payout_scope.payout_transfer_id IS NOT NULL
                AND public_pay_advances_payout_scope.payout_pay_batch_id = p_pay_batch_id
            ),
            '[]'::jsonb
          ),
          'pay_batch_item_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_scope.id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_scope
                ON public_pay_batch_candidates_scope.id = public_pay_batch_items_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_items_scope
                ON public_tmp_payout_notice_items_scope.candidate_id = public_pay_batch_candidates_scope.candidate_id
               AND public_tmp_payout_notice_items_scope.finance_case_id = public_pay_batch_items_scope.finance_case_id
              WHERE public_pay_batch_candidates_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_scope.candidate_id = v_candidate_id
                AND COALESCE(public_pay_batch_items_scope.is_voided, false) = false
                AND public_pay_batch_items_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items AS public_pay_payment_correction_items_scope
                  WHERE public_pay_payment_correction_items_scope.pay_batch_item_id = public_pay_batch_items_scope.id
                    AND public_pay_payment_correction_items_scope.status = 'APPLIED'
                    AND public_pay_payment_correction_items_scope.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                )
            ),
            '[]'::jsonb
          ),
          'pay_bank_transfer_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_transfer_scope.pay_bank_transfer_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_transfer_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_transfer_scope
                ON public_pay_batch_candidates_transfer_scope.id = public_pay_batch_items_transfer_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_transfer_scope
                ON public_tmp_payout_notice_transfer_scope.candidate_id = public_pay_batch_candidates_transfer_scope.candidate_id
               AND public_tmp_payout_notice_transfer_scope.finance_case_id = public_pay_batch_items_transfer_scope.finance_case_id
              WHERE public_pay_batch_candidates_transfer_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_transfer_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_transfer_scope.pay_bank_transfer_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_transfer_scope.is_voided, false) = false
                AND public_pay_batch_items_transfer_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items AS public_pay_payment_correction_transfer_scope
                  WHERE public_pay_payment_correction_transfer_scope.pay_batch_item_id = public_pay_batch_items_transfer_scope.id
                    AND public_pay_payment_correction_transfer_scope.status = 'APPLIED'
                    AND public_pay_payment_correction_transfer_scope.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                )
            ),
            '[]'::jsonb
          ),
          'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
            'notice_scope', 'FINANCE_PAYOUT',
            'pay_batch_id', p_pay_batch_id::text,
            'pay_batch_candidate_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_candidates.pay_batch_candidate_id::text)
                FROM pg_temp.tmp_payout_notice_target_candidates AS public_tmp_payout_notice_candidates
                WHERE public_tmp_payout_notice_candidates.candidate_id = v_candidate_id
              ),
              '[]'::jsonb
            ),
            'candidate_ids', jsonb_build_array(v_candidate_id::text),
            'finance_case_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_target_items.finance_case_id::text)
                FROM pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_target_items
                WHERE public_tmp_payout_notice_target_items.candidate_id = v_candidate_id
              ),
              '[]'::jsonb
            ),
            'finance_component_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_component_scope.finance_component_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_component_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_component_scope
                  ON public_pay_batch_candidates_component_scope.id = public_pay_batch_items_component_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_component_scope
                  ON public_tmp_payout_notice_component_scope.candidate_id = public_pay_batch_candidates_component_scope.candidate_id
                 AND public_tmp_payout_notice_component_scope.finance_case_id = public_pay_batch_items_component_scope.finance_case_id
                WHERE public_pay_batch_candidates_component_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_component_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_component_scope.finance_component_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_component_scope.is_voided, false) = false
                  AND public_pay_batch_items_component_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'reservation_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_reservation_scope.reservation_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_reservation_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_reservation_scope
                  ON public_pay_batch_candidates_reservation_scope.id = public_pay_batch_items_reservation_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_reservation_scope
                  ON public_tmp_payout_notice_reservation_scope.candidate_id = public_pay_batch_candidates_reservation_scope.candidate_id
                 AND public_tmp_payout_notice_reservation_scope.finance_case_id = public_pay_batch_items_reservation_scope.finance_case_id
                WHERE public_pay_batch_candidates_reservation_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_reservation_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_reservation_scope.reservation_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_reservation_scope.is_voided, false) = false
                  AND public_pay_batch_items_reservation_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'pay_bank_transfer_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_transfer_scope.pay_bank_transfer_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_transfer_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_transfer_scope
                  ON public_pay_batch_candidates_transfer_scope.id = public_pay_batch_items_transfer_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_transfer_scope
                  ON public_tmp_payout_notice_transfer_scope.candidate_id = public_pay_batch_candidates_transfer_scope.candidate_id
                 AND public_tmp_payout_notice_transfer_scope.finance_case_id = public_pay_batch_items_transfer_scope.finance_case_id
                WHERE public_pay_batch_candidates_transfer_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_transfer_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_transfer_scope.pay_bank_transfer_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_transfer_scope.is_voided, false) = false
                  AND public_pay_batch_items_transfer_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'payout_transfer_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_advances_payout_scope.payout_transfer_id::text)
                FROM public.pay_advances AS public_pay_advances_payout_scope
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_payout_scope
                  ON public_tmp_payout_notice_payout_scope.finance_case_id = public_pay_advances_payout_scope.id
                 AND public_tmp_payout_notice_payout_scope.candidate_id = v_candidate_id
                WHERE public_pay_advances_payout_scope.payout_transfer_id IS NOT NULL
                  AND public_pay_advances_payout_scope.payout_pay_batch_id = p_pay_batch_id
              ),
              '[]'::jsonb
            ),
            'pay_batch_item_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_scope.id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_scope
                  ON public_pay_batch_candidates_scope.id = public_pay_batch_items_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_items_scope
                  ON public_tmp_payout_notice_items_scope.candidate_id = public_pay_batch_candidates_scope.candidate_id
                 AND public_tmp_payout_notice_items_scope.finance_case_id = public_pay_batch_items_scope.finance_case_id
                WHERE public_pay_batch_candidates_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_scope.candidate_id = v_candidate_id
                  AND COALESCE(public_pay_batch_items_scope.is_voided, false) = false
                  AND public_pay_batch_items_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            )
          ))
        )
        INTO v_queue_context;

        v_work_job := coalesce(v_job, '{}'::jsonb) || jsonb_build_object(
          'job_kind', 'PAYOUT_NOTICE',
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'queue_context', COALESCE(v_queue_context, '{}'::jsonb)
        );
        v_work_job := jsonb_set(v_work_job, '{items}', coalesce(v_pruned_job_items, '[]'::jsonb), true);
        v_work_job := jsonb_set(v_work_job, '{total_amount}', to_jsonb(coalesce(v_pruned_job_total, 0)), true);
        v_work_job := jsonb_set(v_work_job, '{subject}', to_jsonb(v_subject), true);
        v_work_job := jsonb_set(v_work_job, '{worker_message}', to_jsonb(v_worker_message), true);
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          COALESCE(v_queue_context->'payment_scope_json', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_payout_notice_job_map(
          candidate_id,
          job_kind,
          recipient_email
        )
        values (
          v_candidate_id,
          v_job_kind,
          v_recipient_email
        );
      end if;
    end if;
  end loop;


  for v_candidate_id, v_recipient_email in
    select
      cfi_candidates.candidate_id,
      nullif(btrim(coalesce(candidate_row.email, '')), '') as recipient_email
    from (
      select distinct cfi.candidate_id
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where not exists (
        select 1
        from pg_temp.tmp_payout_notice_job_map jm
        where jm.candidate_id = cfi.candidate_id
      )
    ) cfi_candidates
    left join public.candidates as candidate_row
      on candidate_row.id = cfi_candidates.candidate_id
  loop
    if v_recipient_email is not null then
      select
        coalesce(jsonb_agg(cfi.item_json order by cfi.pay_batch_item_id::text), '[]'::jsonb),
        round(coalesce(sum(cfi.amount_inc_vat), 0), 2)
      into
        v_pruned_job_items,
        v_pruned_job_total
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where cfi.candidate_id = v_candidate_id;

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      if v_pruned_job_item_count > 0 then
        v_subject := case
          when v_pruned_job_item_count = 1 then 'Manual adjustment carried forward'
          else 'Manual adjustments carried forward'
        end;

        v_worker_message := case
          when v_pruned_job_item_count = 1 then 'A manual adjustment has been carried forward into this payment.'
          else 'Manual adjustments have been carried forward into this payment.'
        end;

        v_queue_reference := 'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || v_candidate_id::text;

        select jsonb_build_object(
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'scope_kind', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'candidate_id', v_candidate_id::text,
          'pay_batch_candidate_ids', COALESCE((
            select jsonb_agg(distinct pbc_scope.id::text)
            from public.pay_batch_candidates pbc_scope
            where pbc_scope.pay_batch_id = p_pay_batch_id
              and pbc_scope.candidate_id = v_candidate_id
          ), '[]'::jsonb),
          'candidate_ids', jsonb_build_array(v_candidate_id::text),
          'finance_case_ids', '[]'::jsonb,
          'finance_component_ids', '[]'::jsonb,
          'reservation_ids', '[]'::jsonb,
          'payout_transfer_ids', '[]'::jsonb,
          'pay_batch_item_ids', COALESCE((
            select jsonb_agg(distinct cfi_scope.pay_batch_item_id::text order by cfi_scope.pay_batch_item_id::text)
            from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
            where cfi_scope.candidate_id = v_candidate_id
          ), '[]'::jsonb),
          'pay_bank_transfer_ids', COALESCE((
            select jsonb_agg(distinct cfi_scope.item_json->>'pay_bank_transfer_id' order by cfi_scope.item_json->>'pay_bank_transfer_id')
            from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
            where cfi_scope.candidate_id = v_candidate_id
              and nullif(btrim(coalesce(cfi_scope.item_json->>'pay_bank_transfer_id', '')), '') is not null
          ), '[]'::jsonb),
          'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
            'notice_scope', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
            'pay_batch_id', p_pay_batch_id::text,
            'candidate_ids', jsonb_build_array(v_candidate_id::text),
            'pay_batch_item_ids', COALESCE((
              select jsonb_agg(distinct cfi_scope.pay_batch_item_id::text order by cfi_scope.pay_batch_item_id::text)
              from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
              where cfi_scope.candidate_id = v_candidate_id
            ), '[]'::jsonb)
          ))
        )
        into v_queue_context;

        v_work_job := jsonb_build_object(
          'job_kind', 'PAYOUT_NOTICE',
          'candidate_id', v_candidate_id::text,
          'recipient_email', v_recipient_email,
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'queue_context', COALESCE(v_queue_context, '{}'::jsonb),
          'items', coalesce(v_pruned_job_items, '[]'::jsonb),
          'total_amount', coalesce(v_pruned_job_total, 0),
          'subject', v_subject,
          'worker_message', v_worker_message,
          'payment_scope_json', COALESCE(v_queue_context->'payment_scope_json', '{}'::jsonb)
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_payout_notice_job_map(
          candidate_id,
          job_kind,
          recipient_email
        )
        values (
          v_candidate_id,
          'PAYOUT_NOTICE',
          v_recipient_email
        );
      end if;
    end if;
  end loop;

  select count(distinct jm.candidate_id)::int
  into v_ready_candidate_count
  from pg_temp.tmp_payout_notice_job_map jm;

  select jsonb_array_length(v_filtered_jobs)
  into v_job_count;

  if v_job_count > 0 then
    v_trigger_status := 'PAYOUT_NOTICE_BUILD_READY';
  else
    v_trigger_status := 'NO_QUEUEABLE_PAYOUT_NOTICE_JOB';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'pay_batch_candidate_id', tc.pay_batch_candidate_id::text,
               'candidate_id', tc.candidate_id::text,
               'candidate_display_name', tc.candidate_display_name,
               'candidate_tms_ref', tc.candidate_tms_ref,
               'has_job', exists (
                 select 1
                 from pg_temp.tmp_payout_notice_job_map jm
                 where jm.candidate_id = tc.candidate_id
               ),
               'job_kinds', coalesce(
                 (
                   select jsonb_agg(to_jsonb(jk.job_kind) order by jk.job_kind)
                   from (
                     select distinct jm2.job_kind
                     from pg_temp.tmp_payout_notice_job_map jm2
                     where jm2.candidate_id = tc.candidate_id
                   ) jk
                 ),
                 '[]'::jsonb
               ),
               'trigger_status',
                 case
                   when exists (
                     select 1
                     from pg_temp.tmp_payout_notice_job_map jm3
                     where jm3.candidate_id = tc.candidate_id
                   )
                   then 'PAYOUT_NOTICE_BUILD_READY'
                   else 'NO_QUEUEABLE_PAYOUT_NOTICE_JOB'
                 end
             )
             order by tc.candidate_display_name nulls last, tc.candidate_tms_ref nulls last, tc.candidate_id
           ),
           '[]'::jsonb
         )
  into v_candidate_results
  from pg_temp.tmp_payout_notice_target_candidates tc;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'job_kind', upper(btrim(coalesce(j.job->>'job_kind', 'PAYOUT_NOTICE'))),
               'candidate_id', nullif(btrim(coalesce(j.job->>'candidate_id', '')), ''),
               'recipient_email', nullif(btrim(coalesce(j.job->>'recipient_email', '')), ''),
               'scheduled_payment_date', nullif(btrim(coalesce(j.job->>'scheduled_payment_date', '')), ''),
               'subject', nullif(btrim(coalesce(j.job->>'subject', '')), ''),
               'label_set', coalesce(
                 (
                   select jsonb_agg(to_jsonb(li.label_text) order by li.label_text)
                   from (
                     select distinct nullif(btrim(coalesce(it.value->>'label', '')), '') as label_text
                     from jsonb_array_elements(coalesce(j.job->'items', '[]'::jsonb)) as it(value)
                     where nullif(btrim(coalesce(it.value->>'label', '')), '') is not null
                   ) li
                 ),
                 '[]'::jsonb
               )
             )
             order by j.ord
           ),
           '[]'::jsonb
         )
  into v_job_results
  from jsonb_array_elements(v_filtered_jobs) with ordinality as j(job, ord);

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'trigger_status', v_trigger_status,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', v_ready_candidate_count,
      'job_count', v_job_count
    ),
    'pay_finance_payout_notice',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'trigger_status', v_trigger_status,
    'error', null,
    'message_kind', 'PAYOUT_NOTICE',
    'automatic_commit_stage', true,
    'dispatch_required', (v_job_count > 0),
    'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
    'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'candidate_count_targeted', v_target_candidate_count,
    'candidate_count_ready', v_ready_candidate_count,
    'candidate_count_without_jobs', greatest(v_target_candidate_count - v_ready_candidate_count, 0),
    'job_count', v_job_count,
    'candidate_results', coalesce(v_candidate_results, '[]'::jsonb),
    'job_results', coalesce(v_job_results, '[]'::jsonb),
    'jobs', coalesce(v_filtered_jobs, '[]'::jsonb)
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_finance_payout_notice',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

-- pay_item_snoozes_sync_identity_fields()
CREATE OR REPLACE FUNCTION public.pay_item_snoozes_sync_identity_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_booking_id text;
BEGIN
  NEW.source_ref := NULLIF(BTRIM(COALESCE(NEW.source_ref, '')), '');
  NEW.segment_id := NULLIF(BTRIM(COALESCE(NEW.segment_id, '')), '');
  NEW.booking_id := NULLIF(BTRIM(COALESCE(NEW.booking_id, '')), '');
  NEW.segment_stable_key := NULLIF(BTRIM(COALESCE(NEW.segment_stable_key, '')), '');
  NEW.note := NULLIF(BTRIM(COALESCE(NEW.note, '')), '');

  NEW.snooze_kind := UPPER(BTRIM(COALESCE(NEW.snooze_kind, 'DO_NOT_PAY')));
  IF NEW.snooze_kind = 'BLOCKED' THEN
    NEW.snooze_kind := 'BLOCKED_TIMESHEET';
  ELSIF NEW.snooze_kind = 'LOAN_REPAYMENT' THEN
    NEW.snooze_kind := 'PAYMENT_ADVANCE_REPAYMENT';
  END IF;

  IF NEW.timesheet_id IS NOT NULL AND NEW.booking_id IS NULL THEN
    SELECT NULLIF(BTRIM(COALESCE(timesheet_row.booking_id, '')), '')
    INTO v_booking_id
    FROM public.timesheets AS timesheet_row
    WHERE timesheet_row.timesheet_id = NEW.timesheet_id
    LIMIT 1;

    IF v_booking_id IS NOT NULL THEN
      NEW.booking_id := v_booking_id;
    END IF;
  END IF;

  IF NEW.segment_stable_key IS NULL AND NEW.segment_id IS NOT NULL THEN
    NEW.segment_stable_key := NEW.segment_id;
  END IF;

  NEW.natural_expiry_source_fingerprint := ENCODE(
    extensions.digest(
      convert_to(
        jsonb_build_array(
          COALESCE(NEW.id::text, ''),
          COALESCE(NEW.candidate_id::text, ''),
          COALESCE(NEW.timesheet_id::text, ''),
          COALESCE(NEW.booking_id, ''),
          COALESCE(NEW.segment_id, ''),
          COALESCE(NEW.segment_stable_key, ''),
          COALESCE(NEW.source_ref, ''),
          COALESCE(NEW.snooze_kind, ''),
          COALESCE(NEW.snooze_until_date::text, '')
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  RETURN NEW;
END;
$function$;

-- pay_loans_snoozes_list(uuid,uuid,boolean,boolean)
CREATE OR REPLACE FUNCTION public.pay_loans_snoozes_list(p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_include_paid_off boolean DEFAULT true, p_include_cleared_snoozes boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_finance_cases jsonb := '[]'::jsonb;
  v_timesheet_snoozes jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  with finance_rows as (
    select
      vfcr.finance_case_id,
      vfcr.case_type,
      vfcr.candidate_id,
      vfcr.candidate_tms_ref,
      vfcr.candidate_display_name,
      vfcr.pay_method,
      vfcr.client_id,
      vfcr.client_name,
      vfcr.status,
      vfcr.payout_status,
      vfcr.payout_pay_batch_id,
      vfcr.payout_transfer_id,
      round(coalesce(vfcr.original_amount, 0), 2) as original_amount,
      round(coalesce(vfcr.outstanding_amount, 0), 2) as outstanding_amount,
      round(coalesce(vfcr.weekly_due, 0), 2) as weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      vfcr.schedule_json,
      vfcr.adjustment_comment,
      vfcr.notes,
      vfcr.linked_timesheet_id,
      vfcr.linked_shift_date,
      vfcr.source_original_paid_amount,
      vfcr.source_corrected_paid_amount,
      vfcr.minimum_earnings_threshold,
      vfcr.take_home_floor_override,
      vfcr.written_off_at_utc,
      vfcr.write_off_reason,
      vfcr.cleared_at_utc,
      vfcr.active_reserved_amount,
      vfcr.reserved_amount,
      vfcr.committed_amount,
      vfcr.settled_amount,
      vfcr.released_amount,
      vfcr.active_reservation_count,
      vfcr.latest_recovery_pay_batch_id,
      vfcr.latest_recovery_pay_date,
      vfcr.latest_remittance_sent_at_utc,
      vfcr.latest_remittance_trigger_status,
      vfcr.last_remittance_error,
      vfcr.active_snooze_id,
      vfcr.active_snooze_kind,
      vfcr.active_snooze_until_date,
      vfcr.active_snooze_note,
      vfcr.active_snooze_created_at_utc,
      vfcr.active_snooze_updated_at_utc,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then false
        else coalesce(vfcr.is_mixed_case, false)
      end as is_mixed_case,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_taxable_count, 0)
      end as open_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_reimbursement_count, 0)
      end as open_reimbursement_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.unresolved_taxable_count, 0)
      end as unresolved_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.stale_count, 0)
      end as stale_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then jsonb_build_object(
          'open_taxable_count', 0,
          'open_reimbursement_count', 0,
          'unresolved_taxable_count', 0,
          'stale_count', 0,
          'is_mixed_case', false
        )
        else coalesce(vfcr.component_resolution_summary_json, '{}'::jsonb)
      end as component_resolution_summary_json,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'Payment Advance'
        when vfcr.case_type = 'OVERPAYMENT' then 'Overpayment'
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual Debt Adjustment'
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual Credit Adjustment'
        when vfcr.case_type = 'UNDERPAYMENT' then 'Underpayment'
        else vfcr.case_type::text
      end as admin_label,
      case
        when vfcr.active_snooze_id is null then 'NOT_SNOOZED'
        when vfcr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'READY'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'BLOCKED_STALE_TAXABLE_COMPONENTS'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'BLOCKED_UNRESOLVED_TAXABLE_COMPONENTS'
        else 'READY'
      end as blocked_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then null
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'One or more taxable components are stale and must be re-resolved before the case can proceed.'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'One or more taxable components are unresolved and must be resolved before the case can proceed.'
        else null
      end as blocked_reason,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_restructure,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'ACTIVE'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_pause,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'PAUSED'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_resume,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_write_off,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then true
        else false
      end as can_edit,
      case when vfcr.active_snooze_id is not null then true else false end as can_unsnooze
    from public.v_finance_cases_register vfcr
    where (p_candidate_id is null or vfcr.candidate_id = p_candidate_id)
      and (p_client_id is null or vfcr.client_id = p_client_id)
      and (
        p_include_paid_off = true
        or vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
        or (vfcr.status <> 'PAID_OFF' and coalesce(vfcr.outstanding_amount, 0) > 0)
      )
  ),
  finance_payload_rows as (
    select
      fr.candidate_display_name,
      fr.admin_label,
      fr.finance_case_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', fr.finance_case_id::text,
          'case_type', fr.case_type::text,
          'admin_label', fr.admin_label,
          'candidate_id', fr.candidate_id::text,
          'candidate_tms_ref', fr.candidate_tms_ref,
          'candidate_display_name', fr.candidate_display_name,
          'pay_method', fr.pay_method,
          'client_id', case when fr.client_id is null then null else fr.client_id::text end,
          'client_name', fr.client_name,
          'status', fr.status::text,
          'payout_status', case when fr.payout_status is null then null else fr.payout_status::text end,
          'blocked_state', fr.blocked_state,
          'blocked_reason', fr.blocked_reason
        )
        ||
        jsonb_build_object(
          'payout_pay_batch_id', case when fr.payout_pay_batch_id is null then null else fr.payout_pay_batch_id::text end,
          'payout_transfer_id', case when fr.payout_transfer_id is null then null else fr.payout_transfer_id::text end,
          'original_amount', fr.original_amount,
          'outstanding_amount', fr.outstanding_amount,
          'weekly_due', fr.weekly_due,
          'weeks_total', fr.weeks_total,
          'start_week_start', case when fr.start_week_start is null then null else fr.start_week_start::text end,
          'next_due_week_start', case when fr.next_due_week_start is null then null else fr.next_due_week_start::text end,
          'schedule_json', coalesce(fr.schedule_json, '[]'::jsonb),
          'adjustment_comment', fr.adjustment_comment,
          'notes', fr.notes,
          'linked_timesheet_id', case when fr.linked_timesheet_id is null then null else fr.linked_timesheet_id::text end,
          'linked_shift_date', case when fr.linked_shift_date is null then null else fr.linked_shift_date::text end
        )
        ||
        jsonb_build_object(
          'source_original_paid_amount', fr.source_original_paid_amount,
          'source_corrected_paid_amount', fr.source_corrected_paid_amount,
          'minimum_earnings_threshold', fr.minimum_earnings_threshold,
          'take_home_floor_override', fr.take_home_floor_override,
          'written_off_at_utc', case when fr.written_off_at_utc is null then null else fr.written_off_at_utc::text end,
          'write_off_reason', fr.write_off_reason,
          'cleared_at_utc', case when fr.cleared_at_utc is null then null else fr.cleared_at_utc::text end,
          'active_reserved_amount', coalesce(fr.active_reserved_amount, 0),
          'reserved_amount', coalesce(fr.reserved_amount, 0),
          'committed_amount', coalesce(fr.committed_amount, 0),
          'settled_amount', coalesce(fr.settled_amount, 0),
          'released_amount', coalesce(fr.released_amount, 0),
          'active_reservation_count', coalesce(fr.active_reservation_count, 0)
        )
        ||
        jsonb_build_object(
          'latest_recovery_pay_batch_id', case when fr.latest_recovery_pay_batch_id is null then null else fr.latest_recovery_pay_batch_id::text end,
          'latest_recovery_pay_date', case when fr.latest_recovery_pay_date is null then null else fr.latest_recovery_pay_date::text end,
          'latest_remittance_sent_at_utc', case when fr.latest_remittance_sent_at_utc is null then null else fr.latest_remittance_sent_at_utc::text end,
          'latest_remittance_trigger_status', fr.latest_remittance_trigger_status,
          'last_remittance_error', fr.last_remittance_error,
          'is_mixed_case', fr.is_mixed_case,
          'open_taxable_count', fr.open_taxable_count,
          'open_reimbursement_count', fr.open_reimbursement_count,
          'unresolved_taxable_count', fr.unresolved_taxable_count,
          'stale_count', fr.stale_count,
          'component_resolution_summary_json', fr.component_resolution_summary_json,
          'snooze', case
            when fr.active_snooze_id is null then null
            else jsonb_build_object(
              'snooze_id', fr.active_snooze_id::text,
              'snooze_kind', fr.active_snooze_kind,
              'snooze_until_date', case when fr.active_snooze_until_date is null then null else fr.active_snooze_until_date::text end,
              'snooze_note', fr.active_snooze_note,
              'snooze_created_at_utc', case when fr.active_snooze_created_at_utc is null then null else fr.active_snooze_created_at_utc::text end,
              'snooze_updated_at_utc', case when fr.active_snooze_updated_at_utc is null then null else fr.active_snooze_updated_at_utc::text end,
              'snooze_state', fr.snooze_state
            )
          end,
          'action_flags', jsonb_build_object(
            'can_restructure', fr.can_restructure,
            'can_pause', fr.can_pause,
            'can_resume', fr.can_resume,
            'can_write_off', fr.can_write_off,
            'can_edit', fr.can_edit,
            'can_unsnooze', fr.can_unsnooze
          )
        )
      ) as row_json
    from finance_rows fr
  ),
  finance_json as (
    select
      coalesce(
        jsonb_agg(
          fpr.row_json
          order by fpr.candidate_display_name asc, fpr.admin_label asc, fpr.finance_case_id asc
        ),
        '[]'::jsonb
      ) as payload
    from finance_payload_rows fpr
  ),
  pay_item_snooze_source as (
    select
      pis.id as snooze_id,
      pis.candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      pis.timesheet_id as stored_timesheet_id,
      coalesce(pis.booking_id, ts_stored.booking_id) as booking_id,
      pis.segment_id as stored_segment_id,
      coalesce(nullif(btrim(coalesce(pis.segment_stable_key, '')), ''), nullif(btrim(coalesce(pis.segment_id, '')), '')) as segment_stable_key,
      upper(coalesce(pis.snooze_kind, '')) as snooze_kind,
      pis.snooze_until_date,
      pis.note,
      pis.created_at_utc,
      pis.updated_at_utc,
      pis.cleared_at_utc,
      pis.created_by_user_id,
      pis.updated_by_user_id
    from public.pay_item_snoozes pis
    join public.candidates c
      on c.id = pis.candidate_id
    left join public.timesheets ts_stored
      on ts_stored.timesheet_id = pis.timesheet_id
    where pis.source_ref is null
      and (p_candidate_id is null or pis.candidate_id = p_candidate_id)
      and (
        coalesce(pis.booking_id, ts_stored.booking_id) is not null
        or pis.timesheet_id is not null
      )
  ),
  current_timesheet_context as (
    select distinct
      pss.booking_id,
      ts_current.timesheet_id as current_timesheet_id,
      tf_current.client_id as client_id,
      cl_current.name as client_name,
      tf_current.role as role,
      tf_current.band as band,
      ts_current.week_ending_date as week_ending_date,
      ts_current.reference_number as reference_number,
      tf_current.invoice_breakdown_json as invoice_breakdown_json,
      round(coalesce(tf_current.total_pay_ex_vat, 0), 2) as total_pay_ex_vat
    from pay_item_snooze_source pss
    join public.timesheets ts_current
      on ts_current.booking_id = pss.booking_id
     and ts_current.is_current = true
    left join public.timesheets_financials tf_current
      on tf_current.timesheet_id = ts_current.timesheet_id
     and tf_current.is_current = true
    left join public.clients cl_current
      on cl_current.id = tf_current.client_id
  ),
  current_timesheet_segments_actual as (
    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), '') as segment_id,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'segment_stable_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'date', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '')
      ) as segment_stable_key,
      nullif(btrim(coalesce(seg_item.value->>'date', '')), '') as work_date,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'client_name', '')), ''), ctc.client_name) as client_name,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'role', '')), ''), ctc.role) as role,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'band', '')), ''), ctc.band) as band,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'start', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'start_hhmm', '')), '')
      ) as start_time,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'end', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'end_hhmm', '')), '')
      ) as finish_time,
      nullif(btrim(coalesce(seg_item.value->>'break_start', '')), '') as break_start,
      nullif(btrim(coalesce(seg_item.value->>'break_end', '')), '') as break_end,
      coalesce(
        nullif(seg_item.value->>'break_mins', '')::numeric,
        nullif(seg_item.value->>'break_minutes', '')::numeric
      ) as break_mins,
      round(coalesce(nullif(seg_item.value->>'pay_amount', '')::numeric, 0), 2) as pay_amount_ex_vat,
      nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '') as ref_num
    from current_timesheet_context ctc
    join lateral jsonb_array_elements(
      case
        when ctc.invoice_breakdown_json is not null
         and jsonb_typeof(ctc.invoice_breakdown_json) = 'object'
         and jsonb_typeof(ctc.invoice_breakdown_json->'segments') = 'array'
        then ctc.invoice_breakdown_json->'segments'
        else '[]'::jsonb
      end
    ) as seg_item(value)
      on true
    where seg_item.value is not null
      and jsonb_typeof(seg_item.value) = 'object'
  ),
  current_timesheet_segments as (
    select
      ctsa.current_timesheet_id,
      ctsa.booking_id,
      ctsa.segment_id,
      ctsa.segment_stable_key,
      ctsa.work_date,
      ctsa.client_name,
      ctsa.role,
      ctsa.band,
      ctsa.start_time,
      ctsa.finish_time,
      ctsa.break_start,
      ctsa.break_end,
      ctsa.break_mins,
      ctsa.pay_amount_ex_vat,
      ctsa.ref_num
    from current_timesheet_segments_actual ctsa

    union all

    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      null::text as segment_id,
      ('timesheet:' || coalesce(ctc.booking_id, ctc.current_timesheet_id::text)) as segment_stable_key,
      null::text as work_date,
      ctc.client_name,
      ctc.role,
      ctc.band,
      null::text as start_time,
      null::text as finish_time,
      null::text as break_start,
      null::text as break_end,
      null::numeric as break_mins,
      round(coalesce(ctc.total_pay_ex_vat, 0), 2) as pay_amount_ex_vat,
      ctc.reference_number as ref_num
    from current_timesheet_context ctc
    where not exists (
      select 1
      from current_timesheet_segments_actual ctsa
      where ctsa.current_timesheet_id = ctc.current_timesheet_id
    )
  ),
  current_timesheet_segment_groups as (
    select
      cts.current_timesheet_id,
      count(*)::int as segment_count,
      round(coalesce(sum(cts.pay_amount_ex_vat), 0), 2) as total_segment_pay_ex_vat,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'segment_id', cts.segment_id,
            'segment_stable_key', cts.segment_stable_key,
            'date', cts.work_date,
            'client_name', cts.client_name,
            'role', cts.role,
            'band', cts.band,
            'start', cts.start_time,
            'finish', cts.finish_time,
            'break_start', cts.break_start,
            'break_end', cts.break_end,
            'break_mins', cts.break_mins,
            'pay_amount_ex_vat', cts.pay_amount_ex_vat,
            'ref_num', cts.ref_num
          )
          order by cts.work_date asc nulls last, cts.start_time asc nulls last, cts.segment_stable_key asc
        ),
        '[]'::jsonb
      ) as segment_rows_json
    from current_timesheet_segments cts
    group by cts.current_timesheet_id
  ),
  timesheet_snooze_rows_raw as (
    select
      pss.snooze_id,
      pss.candidate_id,
      pss.candidate_tms_ref,
      pss.candidate_display_name,
      pss.stored_timesheet_id,
      pss.booking_id,
      pss.stored_segment_id,
      pss.segment_stable_key,
      pss.snooze_kind,
      pss.snooze_until_date,
      pss.note,
      pss.created_at_utc,
      pss.updated_at_utc,
      pss.cleared_at_utc,
      pss.created_by_user_id,
      pss.updated_by_user_id,
      case when pss.segment_stable_key is null then 'WHOLE_TIMESHEET' else 'SEGMENT' end as row_kind,
      ctc.current_timesheet_id,
      ctc.client_id as current_client_id,
      ctc.client_name as current_client_name,
      ctc.role as current_role,
      ctc.band as current_band,
      ctc.week_ending_date as current_week_ending_date,
      ctc.reference_number as current_reference_number,
      cts.segment_id as current_segment_id,
      cts.segment_stable_key as current_segment_stable_key,
      cts.work_date as current_segment_date,
      cts.client_name as current_segment_client_name,
      cts.role as current_segment_role,
      cts.band as current_segment_band,
      cts.start_time as current_segment_start,
      cts.finish_time as current_segment_finish,
      cts.break_start as current_segment_break_start,
      cts.break_end as current_segment_break_end,
      cts.break_mins as current_segment_break_mins,
      cts.pay_amount_ex_vat as current_segment_pay_amount_ex_vat,
      cts.ref_num as current_segment_ref_num,
      ctsg.segment_count,
      ctsg.total_segment_pay_ex_vat,
      ctsg.segment_rows_json
    from pay_item_snooze_source pss
    left join current_timesheet_context ctc
      on ctc.booking_id = pss.booking_id
    left join current_timesheet_segments cts
      on cts.current_timesheet_id = ctc.current_timesheet_id
     and pss.segment_stable_key is not null
     and (
       cts.segment_stable_key = pss.segment_stable_key
       or (
         pss.stored_segment_id is not null
         and cts.segment_id = pss.stored_segment_id
       )
     )
    left join current_timesheet_segment_groups ctsg
      on ctsg.current_timesheet_id = ctc.current_timesheet_id
  ),
  timesheet_snooze_rows_lifecycle as (
    select
      tsrr.*,
      case
        when tsrr.cleared_at_utc is not null then 'CLEARED'
        when tsrr.current_timesheet_id is null then 'CLEARED_DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'CLEARED_DELETED_SEGMENT'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        else 'ACTIVE'
      end as lifecycle_state,
      case
        when tsrr.cleared_at_utc is not null then tsrr.cleared_at_utc
        when tsrr.current_timesheet_id is null then tsrr.updated_at_utc
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then tsrr.updated_at_utc
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then tsrr.updated_at_utc
        else null::timestamptz
      end as effective_cleared_at_utc,
      case
        when tsrr.cleared_at_utc is not null then 'USER_CLEARED'
        when tsrr.current_timesheet_id is null then 'DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'DELETED_SEGMENT'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        else null::text
      end as clear_reason
    from timesheet_snooze_rows_raw tsrr
  ),
  timesheet_snooze_rows_filtered as (
    select
      tsrl.snooze_id,
      tsrl.candidate_id,
      tsrl.candidate_tms_ref,
      tsrl.candidate_display_name,
      case when tsrl.current_client_id is null then null else tsrl.current_client_id::text end as client_id_text,
      tsrl.current_client_name as client_name,
      coalesce(tsrl.current_timesheet_id, tsrl.stored_timesheet_id) as display_timesheet_id,
      tsrl.current_timesheet_id,
      tsrl.stored_timesheet_id,
      tsrl.booking_id,
      case when tsrl.row_kind = 'SEGMENT' then coalesce(tsrl.current_segment_id, tsrl.stored_segment_id) else null end as display_segment_id,
      tsrl.stored_segment_id,
      tsrl.segment_stable_key,
      tsrl.row_kind,
      tsrl.snooze_kind,
      tsrl.snooze_until_date,
      tsrl.note,
      tsrl.created_at_utc,
      tsrl.updated_at_utc,
      tsrl.effective_cleared_at_utc,
      tsrl.lifecycle_state,
      tsrl.clear_reason,
      case
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is not null then 'DATED_SNOOZE'
        when tsrl.lifecycle_state = 'EXPIRED' then 'EXPIRED'
        else 'CLEARED'
      end as snooze_state,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then tsrl.current_week_ending_date
        else null::date
      end as week_ending_date,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then tsrl.current_reference_number
        else tsrl.current_segment_ref_num
      end as reference_number,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then round(coalesce(tsrl.total_segment_pay_ex_vat, 0), 2)
        else round(coalesce(tsrl.current_segment_pay_amount_ex_vat, 0), 2)
      end as pay_amount_ex_vat,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_count, 0)
        when tsrl.current_segment_stable_key is not null then 1
        else 0
      end as segment_count,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_rows_json, '[]'::jsonb)
        when tsrl.current_segment_stable_key is not null then jsonb_build_array(
          jsonb_build_object(
            'segment_id', tsrl.current_segment_id,
            'segment_stable_key', tsrl.current_segment_stable_key,
            'date', tsrl.current_segment_date,
            'client_name', tsrl.current_segment_client_name,
            'role', tsrl.current_segment_role,
            'band', tsrl.current_segment_band,
            'start', tsrl.current_segment_start,
            'finish', tsrl.current_segment_finish,
            'break_start', tsrl.current_segment_break_start,
            'break_end', tsrl.current_segment_break_end,
            'break_mins', tsrl.current_segment_break_mins,
            'pay_amount_ex_vat', tsrl.current_segment_pay_amount_ex_vat,
            'ref_num', tsrl.current_segment_ref_num
          )
        )
        else '[]'::jsonb
      end as segment_rows_json
    from timesheet_snooze_rows_lifecycle tsrl
    where (p_client_id is null or tsrl.current_client_id = p_client_id)
      and (
        tsrl.lifecycle_state = 'ACTIVE'
        or (p_include_cleared_snoozes = true and tsrl.lifecycle_state <> 'ACTIVE')
      )
  ),
  timesheet_snoozes_json as (
    select
      coalesce(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'snooze_id', tsf.snooze_id::text,
              'row_kind', tsf.row_kind,
              'lifecycle_state', tsf.lifecycle_state,
              'clear_reason', tsf.clear_reason,
              'candidate_id', tsf.candidate_id::text,
              'candidate_tms_ref', tsf.candidate_tms_ref,
              'candidate_display_name', tsf.candidate_display_name,
              'client_id', tsf.client_id_text,
              'client_name', tsf.client_name,
              'timesheet_id', case when tsf.display_timesheet_id is null then null else tsf.display_timesheet_id::text end,
              'current_timesheet_id', case when tsf.current_timesheet_id is null then null else tsf.current_timesheet_id::text end,
              'original_timesheet_id', case when tsf.stored_timesheet_id is null then null else tsf.stored_timesheet_id::text end,
              'booking_id', tsf.booking_id,
              'segment_id', tsf.display_segment_id,
              'original_segment_id', tsf.stored_segment_id,
              'segment_stable_key', tsf.segment_stable_key,
              'week_ending_date', case when tsf.week_ending_date is null then null else tsf.week_ending_date::text end,
              'reference_number', tsf.reference_number,
              'snooze_kind', tsf.snooze_kind,
              'snooze_until_date', case when tsf.snooze_until_date is null then null else tsf.snooze_until_date::text end,
              'note', tsf.note,
              'created_at_utc', case when tsf.created_at_utc is null then null else tsf.created_at_utc::text end,
              'updated_at_utc', case when tsf.updated_at_utc is null then null else tsf.updated_at_utc::text end,
              'cleared_at_utc', case when tsf.effective_cleared_at_utc is null then null else tsf.effective_cleared_at_utc::text end,
              'snooze_state', tsf.snooze_state,
              'pay_amount_ex_vat', tsf.pay_amount_ex_vat,
              'segment_count', tsf.segment_count,
              'segment_rows', tsf.segment_rows_json,
              'action_flags', jsonb_build_object(
                'can_unsnooze', (tsf.lifecycle_state = 'ACTIVE'),
                'can_change_to_indefinite', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null),
                'can_change_to_dated', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is null),
                'can_amend_date', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null)
              )
            )
          )
          order by tsf.candidate_display_name asc, tsf.row_kind asc, tsf.week_ending_date asc nulls last, tsf.display_timesheet_id asc nulls last, tsf.segment_stable_key asc nulls last, tsf.snooze_id asc
        ),
        '[]'::jsonb
      ) as payload
    from timesheet_snooze_rows_filtered tsf
  ),
  summary_data as (
    select
      jsonb_build_object(
        'payment_advances_active_count', count(*) filter (where fr.case_type = 'PAYMENT_ADVANCE' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'overpayments_active_count', count(*) filter (where fr.case_type = 'OVERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'underpayments_active_count', count(*) filter (where fr.case_type = 'UNDERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_debt_adjustments_active_count', count(*) filter (where fr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_credit_adjustments_count', count(*) filter (where fr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'),
        'mixed_finance_cases_count', count(*) filter (where fr.is_mixed_case),
        'unresolved_finance_cases_count', count(*) filter (where fr.unresolved_taxable_count > 0),
        'stale_finance_cases_count', count(*) filter (where fr.stale_count > 0),
        'finance_cases_with_active_snooze_count', count(*) filter (where fr.active_snooze_id is not null),
        'timesheet_snoozes_count', (select count(*) from timesheet_snooze_rows_filtered)
      ) as payload
    from finance_rows fr
  )
  select
    coalesce((select fj.payload from finance_json fj), '[]'::jsonb),
    coalesce((select tsj.payload from timesheet_snoozes_json tsj), '[]'::jsonb),
    coalesce((select sd.payload from summary_data sd), '{}'::jsonb)
  into v_finance_cases, v_timesheet_snoozes, v_summary;

  return jsonb_build_object(
    'ok', true,
    'filters', jsonb_build_object(
      'candidate_id', case when p_candidate_id is null then null else p_candidate_id::text end,
      'client_id', case when p_client_id is null then null else p_client_id::text end,
      'include_paid_off', p_include_paid_off,
      'include_cleared_snoozes', p_include_cleared_snoozes
    ),
    'summary', v_summary,
    'finance_cases', v_finance_cases,
    'timesheet_snoozes', v_timesheet_snoozes
  );
end;
$function$;

-- pay_loans_snoozes_list(uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.pay_loans_snoozes_list(p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_hide_completed_non_current_items boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_finance_cases jsonb := '[]'::jsonb;
  v_timesheet_snoozes jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_hide_completed_non_current_items boolean := coalesce(p_hide_completed_non_current_items, true);
begin
  with finance_rows as (
    select
      vfcr.finance_case_id,
      vfcr.case_type,
      vfcr.candidate_id,
      vfcr.candidate_tms_ref,
      vfcr.candidate_display_name,
      vfcr.pay_method,
      vfcr.client_id,
      vfcr.client_name,
      vfcr.status,
      vfcr.payout_status,
      vfcr.payout_pay_batch_id,
      vfcr.payout_transfer_id,
      round(coalesce(vfcr.original_amount, 0), 2) as original_amount,
      round(coalesce(vfcr.outstanding_amount, 0), 2) as outstanding_amount,
      round(coalesce(vfcr.weekly_due, 0), 2) as weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      vfcr.schedule_json,
      vfcr.adjustment_comment,
      vfcr.notes,
      vfcr.linked_timesheet_id,
      vfcr.linked_shift_date,
      vfcr.source_original_paid_amount,
      vfcr.source_corrected_paid_amount,
      vfcr.minimum_earnings_threshold,
      vfcr.take_home_floor_override,
      vfcr.written_off_at_utc,
      vfcr.write_off_reason,
      vfcr.cleared_at_utc,
      vfcr.active_reserved_amount,
      vfcr.reserved_amount,
      vfcr.committed_amount,
      vfcr.settled_amount,
      vfcr.released_amount,
      vfcr.active_reservation_count,
      vfcr.latest_recovery_pay_batch_id,
      vfcr.latest_recovery_pay_date,
      vfcr.latest_remittance_sent_at_utc,
      vfcr.latest_remittance_trigger_status,
      vfcr.last_remittance_error,
      vfcr.active_snooze_id,
      vfcr.active_snooze_kind,
      vfcr.active_snooze_until_date,
      vfcr.active_snooze_note,
      vfcr.active_snooze_created_at_utc,
      vfcr.active_snooze_updated_at_utc,
      case when vfcr.management_group is null then null else vfcr.management_group::text end as management_group,
      vfcr.lifecycle_status_display,
      case when vfcr.taxability is null then null else vfcr.taxability::text end as taxability,
      case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end as routing_kind,
      coalesce(vfcr.oneoff_bank_details_required, false) as oneoff_bank_details_required,
      coalesce(vfcr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(vfcr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(vfcr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      coalesce(vfcr.oneoff_bank_details_present, false) as oneoff_bank_details_present,
      coalesce(vfcr.oneoff_bank_details_editable, false) as oneoff_bank_details_editable,
      coalesce(vfcr.snooze_allowed, false) as snooze_allowed,
      coalesce(vfcr.edit_bank_details_allowed, false) as edit_bank_details_allowed,
      vfcr.oneoff_bank_beneficiary_name,
      vfcr.oneoff_bank_sort_code,
      vfcr.oneoff_bank_account_number,
      vfcr.oneoff_bank_note,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then false
        else coalesce(vfcr.is_mixed_case, false)
      end as is_mixed_case,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_taxable_count, 0)
      end as open_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_reimbursement_count, 0)
      end as open_reimbursement_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.unresolved_taxable_count, 0)
      end as unresolved_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.stale_count, 0)
      end as stale_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then jsonb_build_object(
          'open_taxable_count', 0,
          'open_reimbursement_count', 0,
          'unresolved_taxable_count', 0,
          'stale_count', 0,
          'is_mixed_case', false
        )
        else coalesce(vfcr.component_resolution_summary_json, '{}'::jsonb)
      end as component_resolution_summary_json,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'Payment Advance'
        when vfcr.case_type = 'OVERPAYMENT' then 'Overpayment'
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual Debt Adjustment'
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual Credit Adjustment'
        when vfcr.case_type = 'UNDERPAYMENT' then 'Underpayment'
        else vfcr.case_type::text
      end as admin_label,
      case
        when vfcr.active_snooze_id is null then 'NOT_SNOOZED'
        when vfcr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'READY'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'BLOCKED_STALE_TAXABLE_COMPONENTS'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'BLOCKED_UNRESOLVED_TAXABLE_COMPONENTS'
        else 'READY'
      end as blocked_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then null
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'One or more taxable components are stale and must be re-resolved before the case can proceed.'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'One or more taxable components are unresolved and must be resolved before the case can proceed.'
        else null
      end as blocked_reason,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_restructure,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'ACTIVE'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_pause,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'PAUSED'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_resume,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_write_off,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then true
        else false
      end as can_edit,
      case when vfcr.active_snooze_id is not null then true else false end as can_unsnooze
    from public.v_finance_cases_register vfcr
    where (p_candidate_id is null or vfcr.candidate_id = p_candidate_id)
      and (p_client_id is null or vfcr.client_id = p_client_id)
      and (
        v_hide_completed_non_current_items = false
        or (
          vfcr.written_off_at_utc is null
          and vfcr.cleared_at_utc is null
          and upper(coalesce(vfcr.status::text, '')) not in ('PAID_OFF', 'PAID', 'CLEARED', 'WRITTEN_OFF', 'CANCELLED', 'SETTLED')
          and (
            upper(coalesce(vfcr.status::text, '')) in ('NOT_PROCESSED_YET', 'DRAFTED_AWAITING_AUTHORISATION', 'ACTIVE', 'PAUSED')
            or round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
            or vfcr.active_snooze_id is not null
          )
        )
      )
  ),
  finance_payload_rows as (
    select
      fr.candidate_display_name,
      fr.admin_label,
      fr.finance_case_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', fr.finance_case_id::text,
          'case_type', fr.case_type::text,
          'admin_label', fr.admin_label,
          'candidate_id', fr.candidate_id::text,
          'candidate_tms_ref', fr.candidate_tms_ref,
          'candidate_display_name', fr.candidate_display_name,
          'pay_method', fr.pay_method,
          'client_id', case when fr.client_id is null then null else fr.client_id::text end,
          'client_name', fr.client_name,
          'status', fr.status::text,
          'finance_status', fr.status::text,
          'payout_status', case when fr.payout_status is null then null else fr.payout_status::text end,
          'finance_payout_status', case when fr.payout_status is null then null else fr.payout_status::text end,
          'management_group', fr.management_group,
          'lifecycle_status_display', fr.lifecycle_status_display,
          'finance_lifecycle_status_display', fr.lifecycle_status_display,
          'taxability', fr.taxability,
          'routing_kind', fr.routing_kind,
          'oneoff_bank_details_required', fr.oneoff_bank_details_required,
          'oneoff_bank_details_present', fr.oneoff_bank_details_present,
          'oneoff_bank_details_editable', fr.oneoff_bank_details_editable,
          'edit_bank_details_allowed', fr.edit_bank_details_allowed,
          'snooze_allowed', fr.snooze_allowed,
          'is_candidate_directed_oneoff_payout', fr.is_candidate_directed_oneoff_payout,
          'appears_on_umbrella_remittance', fr.appears_on_umbrella_remittance,
          'generates_candidate_payment_advice', fr.generates_candidate_payment_advice,
          'blocked_state', fr.blocked_state,
          'blocked_reason', fr.blocked_reason
        )
        ||
        jsonb_build_object(
          'payout_pay_batch_id', case when fr.payout_pay_batch_id is null then null else fr.payout_pay_batch_id::text end,
          'payout_transfer_id', case when fr.payout_transfer_id is null then null else fr.payout_transfer_id::text end,
          'original_amount', fr.original_amount,
          'outstanding_amount', fr.outstanding_amount,
          'weekly_due', fr.weekly_due,
          'weeks_total', fr.weeks_total,
          'start_week_start', case when fr.start_week_start is null then null else fr.start_week_start::text end,
          'next_due_week_start', case when fr.next_due_week_start is null then null else fr.next_due_week_start::text end,
          'schedule_json', coalesce(fr.schedule_json, '[]'::jsonb),
          'adjustment_comment', fr.adjustment_comment,
          'notes', fr.notes,
          'linked_timesheet_id', case when fr.linked_timesheet_id is null then null else fr.linked_timesheet_id::text end,
          'linked_shift_date', case when fr.linked_shift_date is null then null else fr.linked_shift_date::text end,
          'active_snooze_id', case when fr.active_snooze_id is null then null else fr.active_snooze_id::text end,
          'active_snooze_kind', fr.active_snooze_kind,
          'active_snooze_mode', case
            when fr.active_snooze_id is null then 'NOT_SNOOZED'
            when fr.active_snooze_until_date is null then 'INDEFINITE'
            else 'DATED'
          end,
          'active_snooze_until_date', case when fr.active_snooze_until_date is null then null else fr.active_snooze_until_date::text end,
          'active_snooze_note', fr.active_snooze_note,
          'active_snooze_created_at_utc', case when fr.active_snooze_created_at_utc is null then null else fr.active_snooze_created_at_utc::text end,
          'active_snooze_updated_at_utc', case when fr.active_snooze_updated_at_utc is null then null else fr.active_snooze_updated_at_utc::text end,
          'active_snooze_visibility_status', case
            when fr.active_snooze_id is null then 'NOT_SNOOZED'
            when fr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
            else 'DATED_SNOOZE'
          end
        )
        ||
        jsonb_build_object(
          'source_original_paid_amount', fr.source_original_paid_amount,
          'source_corrected_paid_amount', fr.source_corrected_paid_amount,
          'minimum_earnings_threshold', fr.minimum_earnings_threshold,
          'take_home_floor_override', fr.take_home_floor_override,
          'written_off_at_utc', case when fr.written_off_at_utc is null then null else fr.written_off_at_utc::text end,
          'write_off_reason', fr.write_off_reason,
          'cleared_at_utc', case when fr.cleared_at_utc is null then null else fr.cleared_at_utc::text end,
          'active_reserved_amount', coalesce(fr.active_reserved_amount, 0),
          'reserved_amount', coalesce(fr.reserved_amount, 0),
          'committed_amount', coalesce(fr.committed_amount, 0),
          'settled_amount', coalesce(fr.settled_amount, 0),
          'released_amount', coalesce(fr.released_amount, 0),
          'active_reservation_count', coalesce(fr.active_reservation_count, 0)
        )
        ||
        jsonb_build_object(
          'latest_recovery_pay_batch_id', case when fr.latest_recovery_pay_batch_id is null then null else fr.latest_recovery_pay_batch_id::text end,
          'latest_recovery_pay_date', case when fr.latest_recovery_pay_date is null then null else fr.latest_recovery_pay_date::text end,
          'latest_remittance_sent_at_utc', case when fr.latest_remittance_sent_at_utc is null then null else fr.latest_remittance_sent_at_utc::text end,
          'latest_remittance_trigger_status', fr.latest_remittance_trigger_status,
          'last_remittance_error', fr.last_remittance_error,
          'is_mixed_case', fr.is_mixed_case,
          'open_taxable_count', fr.open_taxable_count,
          'open_reimbursement_count', fr.open_reimbursement_count,
          'unresolved_taxable_count', fr.unresolved_taxable_count,
          'stale_count', fr.stale_count,
          'component_resolution_summary_json', fr.component_resolution_summary_json,
          'oneoff_bank_beneficiary_name', fr.oneoff_bank_beneficiary_name,
          'oneoff_bank_sort_code', fr.oneoff_bank_sort_code,
          'oneoff_bank_account_number', fr.oneoff_bank_account_number,
          'oneoff_bank_note', fr.oneoff_bank_note,
          'snooze', case
            when fr.active_snooze_id is null then null
            else jsonb_build_object(
              'snooze_id', fr.active_snooze_id::text,
              'snooze_kind', fr.active_snooze_kind,
              'snooze_until_date', case when fr.active_snooze_until_date is null then null else fr.active_snooze_until_date::text end,
              'snooze_note', fr.active_snooze_note,
              'snooze_created_at_utc', case when fr.active_snooze_created_at_utc is null then null else fr.active_snooze_created_at_utc::text end,
              'snooze_updated_at_utc', case when fr.active_snooze_updated_at_utc is null then null else fr.active_snooze_updated_at_utc::text end,
              'snooze_state', fr.snooze_state
            )
          end,
          'action_flags', jsonb_build_object(
            'can_restructure', fr.can_restructure,
            'can_pause', fr.can_pause,
            'can_resume', fr.can_resume,
            'can_write_off', fr.can_write_off,
            'can_edit', fr.can_edit,
            'can_snooze', (fr.snooze_allowed and fr.active_snooze_id is null),
            'can_unsnooze', fr.can_unsnooze,
            'can_clear_snooze', fr.can_unsnooze,
            'can_edit_snooze', fr.can_unsnooze,
            'can_edit_bank_details', fr.edit_bank_details_allowed
          )
        )
      ) as row_json
    from finance_rows fr
  ),
  finance_json as (
    select
      coalesce(
        jsonb_agg(
          fpr.row_json
          order by fpr.candidate_display_name asc, fpr.admin_label asc, fpr.finance_case_id asc
        ),
        '[]'::jsonb
      ) as payload
    from finance_payload_rows fpr
  ),
  pay_item_snooze_source as (
    select
      pis.id as snooze_id,
      pis.candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      pis.timesheet_id as stored_timesheet_id,
      coalesce(pis.booking_id, ts_stored.booking_id) as booking_id,
      pis.segment_id as stored_segment_id,
      lower(nullif(btrim(coalesce(pis.source_ref, '')), '')) as source_ref,
      (
        lower(nullif(btrim(coalesce(pis.source_ref, '')), '')) ~
        '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
      ) as is_timesheet_expense,
      case
        when lower(nullif(btrim(coalesce(pis.source_ref, '')), '')) ~ '^timesheet-expense:'
          then upper(split_part(lower(pis.source_ref), ':', 3))
        else null::text
      end as expense_code,
      case
        when lower(nullif(btrim(coalesce(pis.source_ref, '')), '')) ~ '^timesheet-expense:'
          then lower(split_part(lower(pis.source_ref), ':', 4))
        else null::text
      end as expense_source_basis_fingerprint,
      coalesce(nullif(btrim(coalesce(pis.segment_stable_key, '')), ''), nullif(btrim(coalesce(pis.segment_id, '')), '')) as segment_stable_key,
      upper(coalesce(pis.snooze_kind, '')) as snooze_kind,
      pis.snooze_until_date,
      pis.note,
      pis.created_at_utc,
      pis.updated_at_utc,
      pis.cleared_at_utc,
      pis.cancelled_at_utc,
      pis.cancel_reason,
      pis.created_by_user_id,
      pis.updated_by_user_id
    from public.pay_item_snoozes pis
    join public.candidates c
      on c.id = pis.candidate_id
    left join public.timesheets ts_stored
      on ts_stored.timesheet_id = pis.timesheet_id
    where (
        pis.source_ref is null
        or lower(nullif(btrim(coalesce(pis.source_ref, '')), '')) ~
           '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
      )
      and (p_candidate_id is null or pis.candidate_id = p_candidate_id)
      and (
        coalesce(pis.booking_id, ts_stored.booking_id) is not null
        or pis.timesheet_id is not null
      )
  ),
  current_timesheet_context as (
    select distinct
      pss.booking_id,
      ts_current.timesheet_id as current_timesheet_id,
      tf_current.client_id as client_id,
      cl_current.name as client_name,
      tf_current.role as role,
      tf_current.band as band,
      ts_current.week_ending_date as week_ending_date,
      ts_current.reference_number as reference_number,
      tf_current.invoice_breakdown_json as invoice_breakdown_json,
      round(coalesce(tf_current.total_pay_ex_vat, 0), 2) as total_pay_ex_vat
    from pay_item_snooze_source pss
    join public.timesheets ts_current
      on ts_current.booking_id = pss.booking_id
     and ts_current.is_current = true
    left join public.timesheets_financials tf_current
      on tf_current.timesheet_id = ts_current.timesheet_id
     and tf_current.is_current = true
    left join public.clients cl_current
      on cl_current.id = tf_current.client_id
  ),
  current_expense_timesheet_scope as (
    select distinct
      pss.candidate_id,
      ctc.current_timesheet_id
    from pay_item_snooze_source pss
    join current_timesheet_context ctc
      on ctc.booking_id = pss.booking_id
    join public.timesheets_financials tf_owner
      on tf_owner.timesheet_id = ctc.current_timesheet_id
     and tf_owner.is_current = true
     and tf_owner.candidate_id = pss.candidate_id
    where pss.is_timesheet_expense
      and ctc.current_timesheet_id is not null
  ),
  current_expense_timesheet_ids as (
    select coalesce(
      array_agg(distinct cets.current_timesheet_id order by cets.current_timesheet_id),
      array[]::uuid[]
    ) as timesheet_ids
    from current_expense_timesheet_scope cets
  ),
  current_expense_entitlement_rows as (
    select
      cets.candidate_id,
      entitlement_row.timesheet_id,
      upper(btrim(entitlement_row.key_value)) as expense_code,
      round(coalesce(outstanding_row.outstanding_ex_vat, entitlement_row.truth_ex_vat, 0), 2) as source_pay_ex_vat
    from current_expense_timesheet_ids expense_ids
    cross join lateral public._pay_current_timesheet_entitlement_components(expense_ids.timesheet_ids) entitlement_row
    join current_expense_timesheet_scope cets
      on cets.current_timesheet_id = entitlement_row.timesheet_id
    left join lateral public._pay_outstanding_components(expense_ids.timesheet_ids) outstanding_row
      on outstanding_row.timesheet_id = entitlement_row.timesheet_id
     and outstanding_row.key_type = entitlement_row.key_type
     and outstanding_row.key_value = entitlement_row.key_value
    where upper(btrim(coalesce(entitlement_row.key_type, ''))) = 'EXPENSE_CODE'
      and upper(btrim(coalesce(entitlement_row.key_value, ''))) in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
      and round(coalesce(outstanding_row.outstanding_ex_vat, entitlement_row.truth_ex_vat, 0), 2) > 0
  ),
  current_expense_active_settled_counts as (
    select
      settled_row.timesheet_id,
      count(*)::integer as active_settled_component_count
    from current_expense_timesheet_ids expense_ids
    cross join lateral public._pay_active_settled_components(expense_ids.timesheet_ids) settled_row
    group by settled_row.timesheet_id
  ),
  current_expense_financial_context as (
    select
      cets.candidate_id,
      cets.current_timesheet_id,
      round(coalesce(tf_current.expenses_charge_ex_vat, 0), 2) as expenses_charge_ex_vat,
      round(coalesce(tf_current.travel_charge_ex_vat, 0), 2) as travel_charge_ex_vat,
      round(coalesce(tf_current.accommodation_charge_ex_vat, 0), 2) as accommodation_charge_ex_vat,
      round(coalesce(tf_current.other_charge_ex_vat, 0), 2) as other_charge_ex_vat,
      round(coalesce(tf_current.mileage_charge_ex_vat, 0), 2) as mileage_charge_ex_vat,
      case
        when coalesce(settled_counts.active_settled_component_count, 0) > 0 then '{}'::jsonb
        else coalesce(timesheet_pay_state.last_settled_snapshot_json, '{}'::jsonb)
      end as expense_baseline_json
    from current_expense_timesheet_scope cets
    join public.timesheets ts_current
      on ts_current.timesheet_id = cets.current_timesheet_id
     and ts_current.is_current = true
    join public.timesheets_financials tf_current
      on tf_current.timesheet_id = ts_current.timesheet_id
     and tf_current.is_current = true
     and tf_current.candidate_id = cets.candidate_id
    left join public.timesheet_pay_state timesheet_pay_state
      on timesheet_pay_state.timesheet_id = ts_current.timesheet_id
    left join current_expense_active_settled_counts settled_counts
      on settled_counts.timesheet_id = ts_current.timesheet_id
    where ts_current.authorised_at_server is not null
      and ts_current.revoked_at is null
      and tf_current.authorised_at_utc is not null
      and upper(btrim(coalesce(tf_current.processing_status::text, ''))) = 'READY_FOR_INVOICE'
      and coalesce(tf_current.pay_on_hold, false) is not true
      and coalesce(tf_current.has_rate_issue, false) is not true
      and coalesce(tf_current.has_pay_channel_issue, false) is not true
  ),
  current_expense_live_basis_values as (
    select
      entitlement_row.candidate_id,
      entitlement_row.timesheet_id,
      entitlement_row.expense_code,
      entitlement_row.source_pay_ex_vat,
      case entitlement_row.expense_code
        when 'EXPENSES' then round(
          coalesce(financial_context.expenses_charge_ex_vat, 0)
          - coalesce(nullif(financial_context.expense_baseline_json #>> '{expenses,expenses_charge_ex_vat}', '')::numeric, 0),
          2
        )
        when 'TRAVEL' then round(
          coalesce(financial_context.travel_charge_ex_vat, 0)
          - coalesce(nullif(financial_context.expense_baseline_json #>> '{expenses,travel_charge_ex_vat}', '')::numeric, 0),
          2
        )
        when 'ACCOMMODATION' then round(
          coalesce(financial_context.accommodation_charge_ex_vat, 0)
          - coalesce(nullif(financial_context.expense_baseline_json #>> '{expenses,accommodation_charge_ex_vat}', '')::numeric, 0),
          2
        )
        when 'OTHER' then round(
          coalesce(financial_context.other_charge_ex_vat, 0)
          - coalesce(nullif(financial_context.expense_baseline_json #>> '{expenses,other_charge_ex_vat}', '')::numeric, 0),
          2
        )
        when 'MILEAGE' then round(
          coalesce(financial_context.mileage_charge_ex_vat, 0)
          - coalesce(nullif(financial_context.expense_baseline_json #>> '{expenses,mileage_charge_ex_vat}', '')::numeric, 0),
          2
        )
        else null::numeric
      end as source_charge_ex_vat
    from current_expense_entitlement_rows entitlement_row
    join current_expense_financial_context financial_context
      on financial_context.candidate_id = entitlement_row.candidate_id
     and financial_context.current_timesheet_id = entitlement_row.timesheet_id
  ),
  current_expense_live_basis as (
    select
      live_values.candidate_id,
      live_values.timesheet_id,
      live_values.expense_code,
      live_values.source_pay_ex_vat,
      live_values.source_charge_ex_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'timesheet_id', live_values.timesheet_id::text,
          'expense_code', live_values.expense_code,
          'source_charge_ex_vat', live_values.source_charge_ex_vat,
          'source_pay_ex_vat', round(coalesce(live_values.source_pay_ex_vat, 0), 2)
        )
      ) as source_basis_json
    from current_expense_live_basis_values live_values
  ),
  current_expense_live_rows as (
    select
      live_basis.candidate_id,
      live_basis.timesheet_id,
      live_basis.expense_code,
      live_basis.source_pay_ex_vat,
      live_basis.source_charge_ex_vat,
      live_basis.source_basis_json,
      md5(live_basis.source_basis_json::text) as source_basis_fingerprint,
      lower(
        'timesheet-expense:' || live_basis.timesheet_id::text || ':' ||
        live_basis.expense_code || ':' || md5(live_basis.source_basis_json::text)
      ) as source_ref,
      jsonb_strip_nulls(
        jsonb_build_object(
          'source_ref', lower(
            'timesheet-expense:' || live_basis.timesheet_id::text || ':' ||
            live_basis.expense_code || ':' || md5(live_basis.source_basis_json::text)
          ),
          'amount_ex_vat', round(coalesce(live_basis.source_pay_ex_vat, 0), 2),
          'expense_code', live_basis.expense_code,
          'expense_label', case live_basis.expense_code
            when 'EXPENSES' then 'Expenses'
            when 'TRAVEL' then 'Travel'
            when 'ACCOMMODATION' then 'Accommodation'
            when 'OTHER' then 'Other'
            when 'MILEAGE' then 'Mileage'
            else null::text
          end,
          'source_basis_json', live_basis.source_basis_json,
          'snooze_identity', jsonb_build_object(
            'identity_type', 'TIMESHEET_EXPENSE',
            'candidate_id', live_basis.candidate_id::text,
            'timesheet_id', live_basis.timesheet_id::text,
            'expense_code', live_basis.expense_code,
            'source_basis_fingerprint', md5(live_basis.source_basis_json::text)
          )
        )
      ) as source_row_json
    from current_expense_live_basis live_basis
  ),
  current_expense_source_rows as (
    select
      pss.snooze_id,
      exact_source.source_row_json as exact_source_row_json,
      changed_source.source_row_json as changed_source_row_json,
      exact_source.source_ref as exact_current_source_ref,
      changed_source.source_ref as changed_current_source_ref,
      exact_source.source_pay_ex_vat as exact_current_amount_ex_vat,
      changed_source.source_pay_ex_vat as changed_current_amount_ex_vat,
      coalesce(
        nullif(btrim(coalesce(exact_source.source_row_json->>'expense_label', '')), ''),
        nullif(btrim(coalesce(changed_source.source_row_json->>'expense_label', '')), ''),
        case pss.expense_code
          when 'EXPENSES' then 'Expenses'
          when 'TRAVEL' then 'Travel'
          when 'ACCOMMODATION' then 'Accommodation'
          when 'OTHER' then 'Other'
          when 'MILEAGE' then 'Mileage'
          else null::text
        end
      ) as expense_label
    from pay_item_snooze_source pss
    left join current_timesheet_context ctc
      on ctc.booking_id = pss.booking_id
    left join lateral (
      select
        live_source.source_row_json,
        live_source.source_ref,
        live_source.source_pay_ex_vat
      from current_expense_live_rows live_source
      where pss.is_timesheet_expense
        and live_source.candidate_id = pss.candidate_id
        and live_source.source_ref = pss.source_ref
      order by live_source.timesheet_id, live_source.expense_code, live_source.source_ref
      limit 1
    ) exact_source on true
    left join lateral (
      select
        live_source.source_row_json,
        live_source.source_ref,
        live_source.source_pay_ex_vat
      from current_expense_live_rows live_source
      where pss.is_timesheet_expense
        and live_source.candidate_id = pss.candidate_id
        and live_source.timesheet_id = ctc.current_timesheet_id
        and live_source.expense_code = pss.expense_code
        and live_source.source_ref is distinct from pss.source_ref
      order by live_source.timesheet_id, live_source.expense_code, live_source.source_ref
      limit 1
    ) changed_source on true
    where pss.is_timesheet_expense
  ),
  current_timesheet_segments_actual as (
    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), '') as segment_id,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'segment_stable_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'date', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '')
      ) as segment_stable_key,
      nullif(btrim(coalesce(seg_item.value->>'date', '')), '') as work_date,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'client_name', '')), ''), ctc.client_name) as client_name,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'role', '')), ''), ctc.role) as role,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'band', '')), ''), ctc.band) as band,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'start', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'start_hhmm', '')), '')
      ) as start_time,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'end', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'end_hhmm', '')), '')
      ) as finish_time,
      nullif(btrim(coalesce(seg_item.value->>'break_start', '')), '') as break_start,
      nullif(btrim(coalesce(seg_item.value->>'break_end', '')), '') as break_end,
      coalesce(
        nullif(seg_item.value->>'break_mins', '')::numeric,
        nullif(seg_item.value->>'break_minutes', '')::numeric
      ) as break_mins,
      round(coalesce(nullif(seg_item.value->>'pay_amount', '')::numeric, 0), 2) as pay_amount_ex_vat,
      nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '') as ref_num
    from current_timesheet_context ctc
    join lateral jsonb_array_elements(
      case
        when ctc.invoice_breakdown_json is not null
         and jsonb_typeof(ctc.invoice_breakdown_json) = 'object'
         and jsonb_typeof(ctc.invoice_breakdown_json->'segments') = 'array'
        then ctc.invoice_breakdown_json->'segments'
        else '[]'::jsonb
      end
    ) as seg_item(value)
      on true
    where seg_item.value is not null
      and jsonb_typeof(seg_item.value) = 'object'
  ),
  current_timesheet_segments as (
    select
      ctsa.current_timesheet_id,
      ctsa.booking_id,
      ctsa.segment_id,
      ctsa.segment_stable_key,
      ctsa.work_date,
      ctsa.client_name,
      ctsa.role,
      ctsa.band,
      ctsa.start_time,
      ctsa.finish_time,
      ctsa.break_start,
      ctsa.break_end,
      ctsa.break_mins,
      ctsa.pay_amount_ex_vat,
      ctsa.ref_num
    from current_timesheet_segments_actual ctsa

    union all

    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      null::text as segment_id,
      ('timesheet:' || coalesce(ctc.booking_id, ctc.current_timesheet_id::text)) as segment_stable_key,
      null::text as work_date,
      ctc.client_name,
      ctc.role,
      ctc.band,
      null::text as start_time,
      null::text as finish_time,
      null::text as break_start,
      null::text as break_end,
      null::numeric as break_mins,
      round(coalesce(ctc.total_pay_ex_vat, 0), 2) as pay_amount_ex_vat,
      ctc.reference_number as ref_num
    from current_timesheet_context ctc
    where not exists (
      select 1
      from current_timesheet_segments_actual ctsa
      where ctsa.current_timesheet_id = ctc.current_timesheet_id
    )
  ),
  current_timesheet_segment_groups as (
    select
      cts.current_timesheet_id,
      count(*)::int as segment_count,
      round(coalesce(sum(cts.pay_amount_ex_vat), 0), 2) as total_segment_pay_ex_vat,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'segment_id', cts.segment_id,
            'segment_stable_key', cts.segment_stable_key,
            'date', cts.work_date,
            'client_name', cts.client_name,
            'role', cts.role,
            'band', cts.band,
            'start', cts.start_time,
            'finish', cts.finish_time,
            'break_start', cts.break_start,
            'break_end', cts.break_end,
            'break_mins', cts.break_mins,
            'pay_amount_ex_vat', cts.pay_amount_ex_vat,
            'ref_num', cts.ref_num
          )
          order by cts.work_date asc nulls last, cts.start_time asc nulls last, cts.segment_stable_key asc
        ),
        '[]'::jsonb
      ) as segment_rows_json
    from current_timesheet_segments cts
    group by cts.current_timesheet_id
  ),
  timesheet_snooze_rows_raw as (
    select
      pss.snooze_id,
      pss.candidate_id,
      pss.candidate_tms_ref,
      pss.candidate_display_name,
      pss.stored_timesheet_id,
      pss.booking_id,
      pss.stored_segment_id,
      pss.segment_stable_key,
      pss.source_ref,
      pss.is_timesheet_expense,
      pss.expense_code,
      pss.expense_source_basis_fingerprint,
      pss.snooze_kind,
      pss.snooze_until_date,
      pss.note,
      pss.created_at_utc,
      pss.updated_at_utc,
      pss.cleared_at_utc,
      pss.cancelled_at_utc,
      pss.cancel_reason,
      pss.created_by_user_id,
      pss.updated_by_user_id,
      case
        when pss.is_timesheet_expense then 'TIMESHEET_EXPENSE'
        when pss.segment_stable_key is null then 'WHOLE_TIMESHEET'
        else 'SEGMENT'
      end as row_kind,
      ctc.current_timesheet_id,
      ctc.client_id as current_client_id,
      ctc.client_name as current_client_name,
      ctc.role as current_role,
      ctc.band as current_band,
      ctc.week_ending_date as current_week_ending_date,
      ctc.reference_number as current_reference_number,
      cts.segment_id as current_segment_id,
      cts.segment_stable_key as current_segment_stable_key,
      cts.work_date as current_segment_date,
      cts.client_name as current_segment_client_name,
      cts.role as current_segment_role,
      cts.band as current_segment_band,
      cts.start_time as current_segment_start,
      cts.finish_time as current_segment_finish,
      cts.break_start as current_segment_break_start,
      cts.break_end as current_segment_break_end,
      cts.break_mins as current_segment_break_mins,
      cts.pay_amount_ex_vat as current_segment_pay_amount_ex_vat,
      cts.ref_num as current_segment_ref_num,
      ctsg.segment_count,
      ctsg.total_segment_pay_ex_vat,
      ctsg.segment_rows_json,
      cesr.exact_source_row_json,
      cesr.changed_source_row_json,
      cesr.exact_current_source_ref,
      cesr.changed_current_source_ref,
      cesr.exact_current_amount_ex_vat,
      cesr.changed_current_amount_ex_vat,
      cesr.expense_label
    from pay_item_snooze_source pss
    left join current_timesheet_context ctc
      on ctc.booking_id = pss.booking_id
    left join current_timesheet_segments cts
      on cts.current_timesheet_id = ctc.current_timesheet_id
     and pss.segment_stable_key is not null
     and (
       cts.segment_stable_key = pss.segment_stable_key
       or (
         pss.stored_segment_id is not null
         and cts.segment_id = pss.stored_segment_id
       )
     )
    left join current_timesheet_segment_groups ctsg
      on ctsg.current_timesheet_id = ctc.current_timesheet_id
    left join current_expense_source_rows cesr
      on cesr.snooze_id = pss.snooze_id
  ),
  timesheet_snooze_rows_lifecycle as (
    select
      tsrr.*,
      case
        when tsrr.cancelled_at_utc is not null then 'CANCELLED'
        when tsrr.cleared_at_utc is not null then 'CLEARED'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is null then 'SOURCE_UNAVAILABLE'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is distinct from tsrr.stored_timesheet_id
         and tsrr.changed_source_row_json is not null then 'SOURCE_REPLACED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is distinct from tsrr.stored_timesheet_id then 'SOURCE_UNAVAILABLE'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.exact_source_row_json is null
         and tsrr.changed_source_row_json is not null then 'SOURCE_CHANGED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.exact_source_row_json is null then 'SOURCE_UNAVAILABLE'
        when tsrr.current_timesheet_id is null then 'CLEARED_DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'CLEARED_DELETED_SEGMENT'
        else 'ACTIVE'
      end as lifecycle_state,
      case
        when tsrr.cancelled_at_utc is not null then tsrr.cancelled_at_utc
        when tsrr.cleared_at_utc is not null then tsrr.cleared_at_utc
        when tsrr.current_timesheet_id is null and tsrr.row_kind <> 'TIMESHEET_EXPENSE' then tsrr.updated_at_utc
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then tsrr.updated_at_utc
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then tsrr.updated_at_utc
        else null::timestamptz
      end as effective_cleared_at_utc,
      case
        when tsrr.cancelled_at_utc is not null then coalesce(tsrr.cancel_reason, 'CANCELLED')
        when tsrr.cleared_at_utc is not null then 'USER_CLEARED'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is null then 'EXPENSE_SOURCE_UNAVAILABLE'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is distinct from tsrr.stored_timesheet_id
         and tsrr.changed_source_row_json is not null then 'TIMESHEET_REPLACED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.current_timesheet_id is distinct from tsrr.stored_timesheet_id then 'EXPENSE_SOURCE_UNAVAILABLE'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.exact_source_row_json is null
         and tsrr.changed_source_row_json is not null then 'EXPENSE_SOURCE_CHANGED'
        when tsrr.row_kind = 'TIMESHEET_EXPENSE'
         and tsrr.exact_source_row_json is null then 'EXPENSE_SOURCE_UNAVAILABLE'
        when tsrr.current_timesheet_id is null then 'DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'DELETED_SEGMENT'
        else null::text
      end as clear_reason
    from timesheet_snooze_rows_raw tsrr
  ),
  timesheet_snooze_rows_filtered as (
    select
      tsrl.snooze_id,
      tsrl.candidate_id,
      tsrl.candidate_tms_ref,
      tsrl.candidate_display_name,
      case when tsrl.current_client_id is null then null else tsrl.current_client_id::text end as client_id_text,
      tsrl.current_client_name as client_name,
      coalesce(tsrl.current_timesheet_id, tsrl.stored_timesheet_id) as display_timesheet_id,
      tsrl.current_timesheet_id,
      tsrl.stored_timesheet_id,
      tsrl.booking_id,
      case when tsrl.row_kind = 'SEGMENT' then coalesce(tsrl.current_segment_id, tsrl.stored_segment_id) else null end as display_segment_id,
      tsrl.stored_segment_id,
      tsrl.segment_stable_key,
      tsrl.source_ref,
      tsrl.expense_code,
      tsrl.expense_source_basis_fingerprint,
      tsrl.expense_label,
      tsrl.exact_current_source_ref,
      tsrl.changed_current_source_ref,
      tsrl.changed_current_amount_ex_vat,
      tsrl.row_kind,
      tsrl.snooze_kind,
      tsrl.snooze_until_date,
      tsrl.note,
      tsrl.created_at_utc,
      tsrl.updated_at_utc,
      tsrl.effective_cleared_at_utc,
      tsrl.lifecycle_state,
      tsrl.clear_reason,
      case
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is not null then 'DATED_SNOOZE'
        when tsrl.lifecycle_state in ('SOURCE_REPLACED', 'SOURCE_CHANGED', 'SOURCE_UNAVAILABLE') then tsrl.lifecycle_state
        when tsrl.lifecycle_state = 'EXPIRED' then 'EXPIRED'
        when tsrl.lifecycle_state = 'CANCELLED' then 'CANCELLED'
        else 'CLEARED'
      end as snooze_state,
      case
        when tsrl.row_kind in ('WHOLE_TIMESHEET', 'TIMESHEET_EXPENSE') then tsrl.current_week_ending_date
        else null::date
      end as week_ending_date,
      case
        when tsrl.row_kind in ('WHOLE_TIMESHEET', 'TIMESHEET_EXPENSE') then tsrl.current_reference_number
        else tsrl.current_segment_ref_num
      end as reference_number,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then round(coalesce(tsrl.total_segment_pay_ex_vat, 0), 2)
        when tsrl.row_kind = 'TIMESHEET_EXPENSE' then round(coalesce(tsrl.exact_current_amount_ex_vat, tsrl.changed_current_amount_ex_vat, 0), 2)
        else round(coalesce(tsrl.current_segment_pay_amount_ex_vat, 0), 2)
      end as pay_amount_ex_vat,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_count, 0)
        when tsrl.row_kind = 'TIMESHEET_EXPENSE' then 0
        when tsrl.current_segment_stable_key is not null then 1
        else 0
      end as segment_count,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_rows_json, '[]'::jsonb)
        when tsrl.current_segment_stable_key is not null then jsonb_build_array(
          jsonb_build_object(
            'segment_id', tsrl.current_segment_id,
            'segment_stable_key', tsrl.current_segment_stable_key,
            'date', tsrl.current_segment_date,
            'client_name', tsrl.current_segment_client_name,
            'role', tsrl.current_segment_role,
            'band', tsrl.current_segment_band,
            'start', tsrl.current_segment_start,
            'finish', tsrl.current_segment_finish,
            'break_start', tsrl.current_segment_break_start,
            'break_end', tsrl.current_segment_break_end,
            'break_mins', tsrl.current_segment_break_mins,
            'pay_amount_ex_vat', tsrl.current_segment_pay_amount_ex_vat,
            'ref_num', tsrl.current_segment_ref_num
          )
        )
        else '[]'::jsonb
      end as segment_rows_json
    from timesheet_snooze_rows_lifecycle tsrl
    where (p_client_id is null or tsrl.current_client_id = p_client_id)
      and (
        tsrl.lifecycle_state in ('ACTIVE', 'SOURCE_REPLACED', 'SOURCE_CHANGED', 'SOURCE_UNAVAILABLE')
        or (
          v_hide_completed_non_current_items = false
          and tsrl.lifecycle_state not in ('ACTIVE', 'SOURCE_REPLACED', 'SOURCE_CHANGED', 'SOURCE_UNAVAILABLE')
        )
      )
  ),
  timesheet_snoozes_json as (
    select
      coalesce(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'snooze_id', tsf.snooze_id::text,
              'row_kind', tsf.row_kind,
              'lifecycle_state', tsf.lifecycle_state,
              'clear_reason', tsf.clear_reason,
              'candidate_id', tsf.candidate_id::text,
              'candidate_tms_ref', tsf.candidate_tms_ref,
              'candidate_display_name', tsf.candidate_display_name,
              'client_id', tsf.client_id_text,
              'client_name', tsf.client_name,
              'timesheet_id', case when tsf.display_timesheet_id is null then null else tsf.display_timesheet_id::text end,
              'current_timesheet_id', case when tsf.current_timesheet_id is null then null else tsf.current_timesheet_id::text end,
              'original_timesheet_id', case when tsf.stored_timesheet_id is null then null else tsf.stored_timesheet_id::text end,
              'booking_id', tsf.booking_id,
              'segment_id', tsf.display_segment_id,
              'original_segment_id', tsf.stored_segment_id,
              'segment_stable_key', tsf.segment_stable_key,
              'source_ref', tsf.source_ref,
              'expense_code', tsf.expense_code,
              'expense_label', tsf.expense_label,
              'expense_source_basis_fingerprint', tsf.expense_source_basis_fingerprint,
              'current_expense_source_ref', tsf.exact_current_source_ref,
              'replacement_expense_source_ref', tsf.changed_current_source_ref,
              'replacement_expense_amount_ex_vat', tsf.changed_current_amount_ex_vat,
              'week_ending_date', case when tsf.week_ending_date is null then null else tsf.week_ending_date::text end,
              'reference_number', tsf.reference_number,
              'snooze_kind', tsf.snooze_kind,
              'snooze_until_date', case when tsf.snooze_until_date is null then null else tsf.snooze_until_date::text end,
              'note', tsf.note,
              'created_at_utc', case when tsf.created_at_utc is null then null else tsf.created_at_utc::text end,
              'updated_at_utc', case when tsf.updated_at_utc is null then null else tsf.updated_at_utc::text end,
              'cleared_at_utc', case when tsf.effective_cleared_at_utc is null then null else tsf.effective_cleared_at_utc::text end,
              'snooze_state', tsf.snooze_state,
              'pay_amount_ex_vat', tsf.pay_amount_ex_vat,
              'segment_count', tsf.segment_count,
              'segment_rows', tsf.segment_rows_json,
              'action_flags', jsonb_build_object(
                'can_unsnooze', (tsf.lifecycle_state in ('ACTIVE', 'SOURCE_REPLACED', 'SOURCE_CHANGED', 'SOURCE_UNAVAILABLE')),
                'can_clear_snooze', (tsf.lifecycle_state in ('ACTIVE', 'SOURCE_REPLACED', 'SOURCE_CHANGED', 'SOURCE_UNAVAILABLE')),
                'can_change_to_indefinite', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null),
                'can_change_to_dated', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is null),
                'can_amend_date', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null)
              )
            )
          )
          order by tsf.candidate_display_name asc, tsf.row_kind asc, tsf.week_ending_date asc nulls last, tsf.display_timesheet_id asc nulls last, tsf.segment_stable_key asc nulls last, tsf.snooze_id asc
        ),
        '[]'::jsonb
      ) as payload
    from timesheet_snooze_rows_filtered tsf
  ),
  summary_data as (
    select
      jsonb_build_object(
        'payment_advances_active_count', count(*) filter (where fr.case_type = 'PAYMENT_ADVANCE' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'overpayments_active_count', count(*) filter (where fr.case_type = 'OVERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'underpayments_active_count', count(*) filter (where fr.case_type = 'UNDERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_debt_adjustments_active_count', count(*) filter (where fr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_credit_adjustments_count', count(*) filter (where fr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'),
        'mixed_finance_cases_count', count(*) filter (where fr.is_mixed_case),
        'unresolved_finance_cases_count', count(*) filter (where fr.unresolved_taxable_count > 0),
        'stale_finance_cases_count', count(*) filter (where fr.stale_count > 0),
        'finance_cases_with_active_snooze_count', count(*) filter (where fr.active_snooze_id is not null),
        'timesheet_snoozes_count', (select count(*) from timesheet_snooze_rows_filtered),
        'timesheet_expense_snoozes_count', (
          select count(*) from timesheet_snooze_rows_filtered where row_kind = 'TIMESHEET_EXPENSE'
        )
      ) as payload
    from finance_rows fr
  )
  select
    coalesce((select fj.payload from finance_json fj), '[]'::jsonb),
    coalesce((select tsj.payload from timesheet_snoozes_json tsj), '[]'::jsonb),
    coalesce((select sd.payload from summary_data sd), '{}'::jsonb)
  into v_finance_cases, v_timesheet_snoozes, v_summary;

  return jsonb_build_object(
    'ok', true,
    'filters', jsonb_build_object(
      'candidate_id', case when p_candidate_id is null then null else p_candidate_id::text end,
      'client_id', case when p_client_id is null then null else p_client_id::text end,
      'hide_completed_non_current_items', v_hide_completed_non_current_items
    ),
    'summary', v_summary,
    'finance_cases', v_finance_cases,
    'timesheet_snoozes', v_timesheet_snoozes
  );
end;
$function$;

